class Solution {
    public static int[] concertTickets(int[] prices, int[] payments) {
        TreeMap<Integer, Integer> available = new TreeMap<>();
        for (int p : prices) available.merge(p, 1, Integer::sum);
        int[] result = new int[payments.length];
        for (int i = 0; i < payments.length; i++) {
            Integer key = available.floorKey(payments[i]);
            if (key == null) {
                result[i] = -1;
            } else {
                result[i] = key;
                int cnt = available.get(key);
                if (cnt == 1) available.remove(key);
                else available.put(key, cnt - 1);
            }
        }
        return result;
    }
}

