class Solution {
    public static int removingDigits(int n) {
        int[] dp = new int[n + 1];
        java.util.Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int temp = i;
            while (temp > 0) {
                int d = temp % 10;
                if (d > 0) dp[i] = Math.min(dp[i], dp[i - d] + 1);
                temp /= 10;
            }
        }
        return dp[n];
    }
}

