class Solution {
    public static double[] shortestRoutes(double[][] graph, int start) {
        int n = graph.length;
        double[] distances = new double[n];
        for (int i = 0; i < n; i++) {
            distances[i] = Double.POSITIVE_INFINITY;
        }
        distances[start] = 0;
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(start);
        while (!queue.isEmpty()) {
            int currentNode = queue.poll();
            for (int i = 0; i < n; i++) {
                if (graph[currentNode][i] != 0 && distances[currentNode] + graph[currentNode][i] < distances[i]) {
                    distances[i] = distances[currentNode] + graph[currentNode][i];
                    queue.add(i);
                }
            }
        }
        return distances;
    }
}

