class Solution {
    public static long shortestRoutes(int n, int[][] edges, int src, int dest) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int w = e[2];
            graph[u].add(new int[]{v, w});
            graph[v].add(new int[]{u, w});
        }
        long[] distance = new long[n];
        Arrays.fill(distance, Long.MAX_VALUE);
        distance[src] = 0;
        List<long[]> pq = new ArrayList<>();
        pq.add(new long[]{src, 0});
        while (!pq.isEmpty()) {
            long[] cur = pq.remove(0);
            int currentNode = (int) cur[0];
            long currentDistance = cur[1];
            if (currentDistance > distance[currentNode]) continue;
            for (int[] edge : graph[currentNode]) {
                int neighbor = edge[0];
                int weight = edge[1];
                long newDistance = currentDistance + weight;
                if (newDistance < distance[neighbor]) {
                    distance[neighbor] = newDistance;
                    pq.add(new long[]{neighbor, newDistance});
                    pq.sort(Comparator.comparingLong(a -> a[1]));
                }
            }
        }
        return distance[dest] == Long.MAX_VALUE ? -1 : distance[dest];
    }
}

