class Solution {
    public static int[] treeDistances(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] d0 = bfs(0, n, adj);
        int a = 0;
        for (int i = 0; i < n; i++) if (d0[i] > d0[a]) a = i;
        int[] dA = bfs(a, n, adj);
        int b = 0;
        for (int i = 0; i < n; i++) if (dA[i] > dA[b]) b = i;
        int[] dB = bfs(b, n, adj);
        int[] result = new int[n];
        for (int i = 0; i < n; i++) result[i] = Math.max(dA[i], dB[i]);
        return result;
    }
    private static int[] bfs(int src, int n, List<Integer>[] adj) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[src] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(src);
        while (!q.isEmpty()) {
            int node = q.poll();
            for (int nb : adj[node]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[node] + 1;
                    q.add(nb);
                }
            }
        }
        return dist;
    }
}

