class Solution {
    public static long wordCombinations(String s, List<String> words) {
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (String w : words) {
                int L = w.length();
                if (L <= i && s.substring(i - L, i).equals(w)) {
                    dp[i] = (dp[i] + dp[i - L]) % 1000000007;
                }
            }
        }
        return dp[n];
    }
}

