class Solution {
    public static int[] findBorders(String s) {
        int[] borders = new int[s.length()];
        int maxLength = 0;
        for (int i = 1; i < s.length(); i++) {
            int j = maxLength;
            while (j > 0 && s.charAt(i) != s.charAt(j)) {
                j = borders[j - 1];
            }
            if (s.charAt(i) == s.charAt(j)) {
                maxLength = j + 1;
            }
            borders[i] = maxLength;
        }
        return borders;
    }
}

