public class Solution {
    public static double findMedianSortedArrays(int[] nums1, int[] nums2) {
        if (nums1.length > nums2.length) {
            return findMedianSortedArrays(nums2, nums1);
        }
        int x = nums1.length;
        int y = nums2.length;
        int start = 0;
        int end = x;
        while (start <= end) {
            int partitionX = (start + end) / 2;
            int partitionY = (x + y + 1) / 2 - partitionX;
            double maxLeftX = partitionX == 0 ? Double.NEGATIVE_INFINITY : nums1[partitionX - 1];
            double minRightX = partitionX == x ? Double.POSITIVE_INFINITY : nums1[partitionX];
            double maxLeftY = partitionY == 0 ? Double.NEGATIVE_INFINITY : nums2[partitionY - 1];
            double minRightY = partitionY == y ? Double.POSITIVE_INFINITY : nums2[partitionY];
            if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
                if ((x + y) % 2 == 0) {
                    return (Math.max(maxLeftX, maxLeftY) + Math.min(minRightX, minRightY)) / 2.0;
                } else {
                    return Math.max(maxLeftX, maxLeftY);
                }
            } else if (maxLeftX > minRightY) {
                end = partitionX - 1;
            } else {
                start = partitionX + 1;
            }
        }
        return 0;
    }
}

