class Solution {
    public static boolean isMatch(String s, String p) {
        int m = s.length();
        int n = p.length();
        boolean[][] dp = new boolean[m + 1][n + 1];
        dp[m][n] = true;
        for (int i = m; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (p.charAt(j) == '*') {
                    dp[i][j] = dp[i][j + 1] || (i < m && (p.charAt(j - 1) == s.charAt(i) || p.charAt(j - 1) == '.') && dp[i + 1][j]);
                } else {
                    dp[i][j] = i < m && (p.charAt(j) == s.charAt(i) || p.charAt(j) == '.') && dp[i + 1][j + 1];
                }
            }
        }
        return dp[0][0];
    }
}

