    public static ListNode mergeKLists(ListNode[] lists) {
        List<NodeInfo> minHeap = new ArrayList<>();
        for (int i = 0; i < lists.length; i++) {
            if (lists[i] != null) {
                minHeap.add(new NodeInfo(lists[i].val, i, lists[i]));
            }
        }
        ListNode dummy = new ListNode(0);
        ListNode current = dummy;
        while (!minHeap.isEmpty()) {
            Collections.sort(minHeap, Comparator.comparingInt(a -> a.val));
            NodeInfo info = minHeap.remove(0);
            ListNode node = info.node;
            current.next = node;
            current = current.next;
            if (node.next != null) {
                minHeap.add(new NodeInfo(node.next.val, info.listIndex, node.next));
            }
        }
        return dummy.next;
    }
}

