class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode current = head;
        int length = 0;
        ListNode temp = head;
        while (temp != null) {
            length++;
            temp = temp.next;
        }
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;
        for (int i = 0; i < length; i += k) {
            int count = 0;
            ListNode tail = prev;
            ListNode temp2 = current;
            while (temp2 != null && count < k) {
                count++;
                temp2 = temp2.next;
            }
            if (count == k) {
                ListNode groupHead = current;
                ListNode prevNode = null;
                ListNode nextNode = null;
                for (int j = 0; j < k; j++) {
                    nextNode = current.next;
                    current.next = prevNode;
                    prevNode = current;
                    current = nextNode;
                }
                tail.next = prevNode;
                groupHead.next = current;
                prev = groupHead;
            }
        }
        return dummy.next;
    }
}

