class Solution {
    public static int divide(int dividend, int divisor) {
        int sign = ((dividend < 0) ^ (divisor < 0)) ? -1 : 1;
        int a = Math.abs(dividend);
        int b = Math.abs(divisor);
        int quotient = 0;
        while (a >= b) {
            int shift = 0;
            while ((b << shift) <= a) {
                shift++;
            }
            a -= (b << (shift - 1));
            quotient += (1 << (shift - 1));
        }
        quotient *= sign;
        return Math.max(Integer.MIN_VALUE, Math.min(quotient, Integer.MAX_VALUE));
    }
}

