class Solution {
    public static List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(target, new ArrayList<>(), 0, candidates, result);
        return result;
    }

    private static void backtrack(int remain, List<Integer> comb, int start, int[] candidates, List<List<Integer>> result) {
        if (remain == 0) {
            result.add(new ArrayList<>(comb));
        }
        for (int i = start; i < candidates.length; i++) {
            if (candidates[i] > remain) break;
            comb.add(candidates[i]);
            backtrack(remain - candidates[i], comb, i, candidates, result);
            comb.remove(comb.size() - 1);
        }
    }
}

