class Solution {
    public static boolean isMatch(String s, String p) {
        int sIndex = 0, pIndex = 0, starIndex = -1, matchIndex = 0;
        while (sIndex < s.length()) {
            if (pIndex < p.length() && p.charAt(pIndex) == '*') {
                starIndex = pIndex;
                matchIndex = sIndex;
                pIndex++;
            } else if (pIndex < p.length() && (p.charAt(pIndex) == '?' || p.charAt(pIndex) == s.charAt(sIndex))) {
                pIndex++;
                sIndex++;
            } else if (starIndex != -1) {
                pIndex = starIndex + 1;
                matchIndex++;
                sIndex = matchIndex;
            } else {
                return false;
            }
        }
        while (pIndex < p.length() && p.charAt(pIndex) == '*') {
            pIndex++;
        }
        return pIndex == p.length();
    }
}

class Solution {
    public static int jump(int[] nums) {
        int jumps = 0;
        int currentEnd = 0;
        int farthest = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == currentEnd) {
                jumps++;
                currentEnd = farthest;
            }
        }
        return jumps;
    }
}

class Solution {
    public static int[][] rotate(int[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int temp = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = temp;
            }
        }
        for (int i = 0; i < n; i++) {
            int left = 0;
            int right = n - 1;
            while (left < right) {
                int temp = matrix[i][left];
                matrix[i][left] = matrix[i][right];
                matrix[i][right] = temp;
                left++;
                right--;
            }
        }
        return matrix;
    }
}

import java.util.*;

class Solution {
    public static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> initial = new ArrayList<>();
        for (int num : nums) {
            initial.add(num);
        }
        backtrack(new ArrayList<>(), initial, result);
        return result;
    }

    private static void backtrack(List<Integer> current, List<Integer> remaining, List<List<Integer>> result) {
        if (remaining.isEmpty()) {
            result.add(new ArrayList<>(current));
        } else {
            for (int i = 0; i < remaining.size(); i++) {
                current.add(remaining.get(i));
                List<Integer> newRemaining = new ArrayList<>();
                newRemaining.addAll(remaining.subList(0, i));
                newRemaining.addAll(remaining.subList(i + 1, remaining.size()));
                backtrack(current, newRemaining, result);
                current.remove(current.size() - 1);
            }
        }
    }
}

import java.util.*;

class Solution {
    public static List<List<Integer>> permuteUnique(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> result = new ArrayList<>();
        boolean[] visited = new boolean[nums.length];
        backtrack(new ArrayList<>(), nums, visited, result);
        return result;
    }

    private static void backtrack(List<Integer> current, int[] nums, boolean[] visited, List<List<Integer>> result) {
        if (current.size() == nums.length) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (visited[i] || (i > 0 && nums[i] == nums[i - 1] && !visited[i - 1])) {
                continue;
            }
            visited[i] = true;
            current.add(nums[i]);
            backtrack(current, nums, visited, result);
            current.remove(current.size() - 1);
            visited[i] = false;
        }
    }
}

