class Solution {
    public static String addBinary(String a, String b) {
        String result = "";
        int carry = 0;
        int i = a.length() - 1;
        int j = b.length() - 1;
        while (i >= 0 || j >= 0 || carry != 0) {
            int sum = carry;
            if (i >= 0) sum += a.charAt(i--) - '0';
            if (j >= 0) sum += b.charAt(j--) - '0';
            result = (char)('0' + (sum % 2)) + result;
            carry = sum / 2;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static List<String> fullJustify(String[] words, int maxWidth) {
        List<String> result = new ArrayList<>();
        List<String> currentLine = new ArrayList<>();
        int currentWidth = 0;
        for (int i = 0; i < words.length; i++) {
            if (currentWidth + currentLine.size() + words[i].length() > maxWidth) {
                int spaces = maxWidth - currentWidth;
                int gaps = currentLine.size() - 1;
                int extraSpaces = gaps > 0 ? spaces / gaps : 0;
                int remainingSpaces = gaps > 0 ? spaces % gaps : spaces;
                StringBuilder line = new StringBuilder();
                for (int j = 0; j < currentLine.size(); j++) {
                    line.append(currentLine.get(j));
                    if (j < currentLine.size() - 1) {
                        line.append(" ".repeat(extraSpaces + (j < remainingSpaces ? 1 : 0)));
                    }
                }
                if (line.length() < maxWidth) {
                    line.append(" ".repeat(maxWidth - line.length()));
                }
                result.add(line.toString());
                currentLine = new ArrayList<>();
                currentLine.add(words[i]);
                currentWidth = words[i].length();
            } else {
                currentLine.add(words[i]);
                currentWidth += words[i].length();
            }
        }
        String lastLine = String.join(" ", currentLine);
        lastLine += " ".repeat(maxWidth - lastLine.length());
        result.add(lastLine);
        return result;
    }
}

