class Solution {
    public static int mySqrt(int x) {
        if (x < 2) return x;
        int left = 2;
        int right = x / 2;
        while (left <= right) {
            int mid = (left + right) / 2;
            int square = mid * mid;
            if (square == x) return mid;
            if (square < x) left = mid + 1;
            else right = mid - 1;
        }
        return right;
    }
}

class Solution {
    public static int climbStairs(int n) {
        int[] ways = new int[n + 1];
        ways[0] = 1;
        if (n >= 1) {
            ways[1] = 1;
        }
        for (int i = 2; i <= n; i++) {
            ways[i] = ways[i - 1] + ways[i - 2];
        }
        return ways[n];
    }
}

