class Solution {
    public static String minWindow(String s, String t) {
        if (s.length() < t.length()) return "";
        Map<Character, Integer> tCount = new HashMap<>();
        for (char ch : t.toCharArray()) {
            tCount.put(ch, tCount.getOrDefault(ch, 0) + 1);
        }
        int requiredChars = tCount.size();
        int left = 0, right = 0;
        int formedChars = 0;
        Map<Character, Integer> windowCounts = new HashMap<>();
        int[] minWindow = new int[]{0, Integer.MAX_VALUE};
        while (right < s.length()) {
            char c = s.charAt(right);
            if (tCount.containsKey(c)) {
                windowCounts.put(c, windowCounts.getOrDefault(c, 0) + 1);
                if (windowCounts.get(c).intValue() == tCount.get(c).intValue()) {
                    formedChars++;
                }
            }
            while (left <= right && formedChars == requiredChars) {
                if (right - left + 1 < minWindow[1] - minWindow[0]) {
                    minWindow[0] = left;
                    minWindow[1] = right + 1;
                }
                char leftChar = s.charAt(left);
                if (tCount.containsKey(leftChar)) {
                    windowCounts.put(leftChar, windowCounts.get(leftChar) - 1);
                    if (windowCounts.get(leftChar).intValue() < tCount.get(leftChar).intValue()) {
                        formedChars--;
                    }
                }
                left++;
            }
            right++;
        }
        return minWindow[1] == Integer.MAX_VALUE ? "" : s.substring(minWindow[0], minWindow[1]);
    }
}

