class Solution {
    public static boolean exist(char[][] board, String word) {
        int rows = board.length;
        int cols = board[0].length;
        boolean[][] visited = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (dfs(board, visited, rows, cols, word, i, j, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean dfs(char[][] board, boolean[][] visited, int rows, int cols, String word, int row, int col, int index) {
        if (index == word.length()) {
            return true;
        }
        if (row < 0 || row >= rows || col < 0 || col >= cols || visited[row][col] || board[row][col] != word.charAt(index)) {
            return false;
        }
        visited[row][col] = true;
        boolean found = dfs(board, visited, rows, cols, word, row + 1, col, index + 1)
                || dfs(board, visited, rows, cols, word, row - 1, col, index + 1)
                || dfs(board, visited, rows, cols, word, row, col + 1, index + 1)
                || dfs(board, visited, rows, cols, word, row, col - 1, index + 1);
        visited[row][col] = false;
        return found;
    }
}

