import java.util.HashMap;
import java.util.Map;
import java.util.Arrays;

class Solution {
    public static boolean isScramble(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        return helper(s1, s2, new HashMap<>());
    }

    private static boolean helper(String s1, String s2, Map<String, Boolean> memo) {
        String key = s1 + "#" + s2;
        if (memo.containsKey(key)) return memo.get(key);
        if (s1.equals(s2)) {
            memo.put(key, true);
            return true;
        }
        if (!sameCharMultiset(s1, s2)) {
            memo.put(key, false);
            return false;
        }
        int n = s1.length();
        for (int i = 1; i < n; i++) {
            if (helper(s1.substring(0, i), s2.substring(0, i), memo) &&
                helper(s1.substring(i), s2.substring(i), memo)) {
                memo.put(key, true);
                return true;
            }
            if (helper(s1.substring(0, i), s2.substring(n - i), memo) &&
                helper(s1.substring(i), s2.substring(0, n - i), memo)) {
                memo.put(key, true);
                return true;
            }
        }
        memo.put(key, false);
        return false;
    }

    private static boolean sameCharMultiset(String a, String b) {
        char[] ca = a.toCharArray();
        char[] cb = b.toCharArray();
        Arrays.sort(ca);
        Arrays.sort(cb);
        return Arrays.equals(ca, cb);
    }
}

class Solution {
    public static int[] merge(int[] nums1, int m, int[] nums2, int n) {
        int i = m - 1;
        int j = n - 1;
        int k = m + n - 1;
        while (i >= 0 && j >= 0) {
            if (nums1[i] > nums2[j]) {
                nums1[k--] = nums1[i--];
            } else {
                nums1[k--] = nums2[j--];
            }
        }
        while (j >= 0) {
            nums1[k--] = nums2[j--];
        }
        return nums1;
    }
}

