public class Solution {
    public static List<Integer> grayCode(int n) {
        List<Integer> result = new ArrayList<>();
        int limit = 1 << n;
        for (int i = 0; i < limit; i++) {
            int j = i >> 1;
            if ((i ^ j) == (i ^ (i >> 1))) {
                result.add(i);
            }
        }
        List<Integer> grayCodeSequence = new ArrayList<>();
        if (n == 0) {
            grayCodeSequence.add(0);
        } else {
            List<Integer> subSequence = grayCode(n - 1);
            for (int i = 0; i < subSequence.size(); i++) {
                grayCodeSequence.add(subSequence.get(i));
            }
            for (int i = subSequence.size() - 1; i >= 0; i--) {
                grayCodeSequence.add(subSequence.get(i) + (1 << (n - 1)));
            }
        }
        return grayCodeSequence;
    }
}

