class Solution {
    public static void flatten(TreeNode root) {
        if (root == null) return;
        flatten(root.left);
        flatten(root.right);
        if (root.left != null) {
            TreeNode rightmost = root.left;
            while (rightmost.right != null) {
                rightmost = rightmost.right;
            }
            rightmost.right = root.right;
            root.right = root.left;
            root.left = null;
        }
    }
}

