class Solution {
    public static List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> result = new ArrayList<>();
        dfs(root, new ArrayList<>(), 0, targetSum, result);
        return result;
    }
    private static void dfs(TreeNode node, List<Integer> currentPath, int currentSum, int targetSum, List<List<Integer>> result) {
        if (node == null) return;
        currentPath.add(node.val);
        currentSum += node.val;
        if (node.left == null && node.right == null && currentSum == targetSum) {
            result.add(new ArrayList<>(currentPath));
        }
        dfs(node.left, currentPath, currentSum, targetSum, result);
        dfs(node.right, currentPath, currentSum, targetSum, result);
        currentPath.remove(currentPath.size() - 1);
    }
}

class Solution {
    public static long numDistinct(String s, String t) {
        int sLength = s.length();
        int tLength = t.length();
        long[][] dp = new long[tLength + 1][sLength + 1];
        for (int j = 0; j <= sLength; j++) {
            dp[0][j] = 1;
        }
        for (int i = 1; i <= tLength; i++) {
            for (int j = 1; j <= sLength; j++) {
                if (t.charAt(i - 1) == s.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1];
                } else {
                    dp[i][j] = dp[i][j - 1];
                }
            }
        }
        return dp[tLength][sLength];
    }
}

