class Solution {
    public static List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return new ArrayList<>();
        }
        LinkedList<List<String>> queue = new LinkedList<>();
        queue.add(new ArrayList<>(Collections.singletonList(beginWord)));
        Set<String> visited = new HashSet<>();
        visited.add(beginWord);
        int shortestPathLength = Integer.MAX_VALUE;
        List<List<String>> result = new ArrayList<>();
        while (!queue.isEmpty()) {
            List<String> path = queue.poll();
            String currentWord = path.get(path.size() - 1);
            for (int i = 0; i < currentWord.length(); i++) {
                for (int j = 0; j < 26; j++) {
                    char c = (char) ('a' + j);
                    String nextWord = currentWord.substring(0, i) + c + currentWord.substring(i + 1);
                    if (wordSet.contains(nextWord) && !visited.contains(nextWord)) {
                        if (nextWord.equals(endWord)) {
                            List<String> newPath = new ArrayList<>(path);
                            newPath.add(nextWord);
                            if (path.size() + 1 < shortestPathLength) {
                                shortestPathLength = path.size() + 1;
                                result = new ArrayList<>();
                                result.add(newPath);
                            } else if (path.size() + 1 == shortestPathLength) {
                                result.add(newPath);
                            }
                        } else {
                            List<String> newPath = new ArrayList<>(path);
                            newPath.add(nextWord);
                            queue.add(newPath);
                            visited.add(nextWord);
                        }
                    }
                }
            }
        }
        return result;
    }
}

