class Solution {
    public static int maxPoints(int[][] points) {
        if (points == null || points.length == 0) return 0;
        int maxPoints = 0;
        for (int i = 0; i < points.length; i++) {
            Map<String, Integer> slopeMap = new HashMap<>();
            int samePoint = 1;
            for (int j = i + 1; j < points.length; j++) {
                String slope = calculateSlope(points[i], points[j]);
                if (slope.equals("inf") && points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    samePoint++;
                } else {
                    slopeMap.put(slope, slopeMap.getOrDefault(slope, 0) + 1);
                }
            }
            int localMax = 0;
            for (int count : slopeMap.values()) {
                if (count > localMax) localMax = count;
            }
            maxPoints = Math.max(maxPoints, localMax + samePoint);
        }
        return maxPoints;
    }

    private static String calculateSlope(int[] p1, int[] p2) {
        int dx = p2[0] - p1[0];
        int dy = p2[1] - p1[1];
        if (dx == 0) {
            return "inf";
        }
        int g = gcd(dy, dx);
        dy /= g;
        dx /= g;
        if (dx < 0) {
            dx = -dx;
            dy = -dy;
        }
        return dy + "/" + dx;
    }

    private static int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a == 0 ? 1 : a;
    }
}

