class Solution {
    public static int maximumGap(int[] nums) {
        if (nums.length < 2) return 0;
        int minVal = nums[0];
        int maxVal = nums[0];
        for (int num : nums) {
            if (num < minVal) minVal = num;
            if (num > maxVal) maxVal = num;
        }
        if (minVal == maxVal) return 0;
        int bucketSize = Math.max(1, (maxVal - minVal) / (nums.length - 1));
        int bucketCount = (int) Math.ceil((double) (maxVal - minVal) / bucketSize);
        Bucket[] buckets = new Bucket[bucketCount];
        for (int i = 0; i < bucketCount; i++) {
            buckets[i] = new Bucket();
        }
        for (int num : nums) {
            int index = Math.min((num - minVal) / bucketSize, bucketCount - 1);
            if (num < buckets[index].min) buckets[index].min = num;
            if (num > buckets[index].max) buckets[index].max = num;
        }
        int maxGap = 0;
        int prevMax = -1;
        for (Bucket bucket : buckets) {
            if (bucket.min == Integer.MAX_VALUE) continue;
            if (prevMax != -1) {
                maxGap = Math.max(maxGap, bucket.min - prevMax);
            }
            prevMax = bucket.max;
        }
        return maxGap;
    }

    private static class Bucket {
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
    }
}

