class Solution {
    public static int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (k == 0 || n == 0) {
            return 0;
        }
        if (k >= n / 2) {
            int profit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    profit += prices[i] - prices[i - 1];
                }
            }
            return profit;
        }
        int[] dpPrev = new int[n];
        int[] dpCurr = new int[n];
        for (int t = 1; t <= k; t++) {
            int maxDiff = -prices[0];
            dpCurr[0] = 0;
            for (int i = 1; i < n; i++) {
                dpCurr[i] = Math.max(dpCurr[i - 1], prices[i] + maxDiff);
                maxDiff = Math.max(maxDiff, dpPrev[i] - prices[i]);
            }
            int[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
            Arrays.fill(dpCurr, 0);
        }
        return dpPrev[n - 1];
    }
}

