class Solution {
    public static int rob(int[] nums) {
        if (nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];
        int[] maxAmounts = new int[nums.length];
        maxAmounts[0] = nums[0];
        maxAmounts[1] = Math.max(nums[0], nums[1]);
        for (int i = 2; i < nums.length; i++) {
            maxAmounts[i] = Math.max(maxAmounts[i - 1], maxAmounts[i - 2] + nums[i]);
        }
        return maxAmounts[maxAmounts.length - 1];
    }
}

