class Solution {
    public static boolean isIsomorphic(String s, String t) {
        if (s.length() != t.length()) return false;
        Map<Character, Character> sToTMap = new HashMap<>();
        Map<Character, Character> tToSMap = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char cs = s.charAt(i);
            char ct = t.charAt(i);
            if (sToTMap.containsKey(cs) && sToTMap.get(cs) != ct) return false;
            if (tToSMap.containsKey(ct) && tToSMap.get(ct) != cs) return false;
            sToTMap.put(cs, ct);
            tToSMap.put(ct, cs);
        }
        return true;
    }
}

class Trie {
