    public boolean search(String word) { Trie node = this; for (char c : word.toCharArray()) { if (!node.children.containsKey(c)) return false; node = node.children.get(c); } return node.isEnd; }
    public boolean startsWith(String prefix) { Trie node = this; for (char c : prefix.toCharArray()) { if (!node.children.containsKey(c)) return false; node = node.children.get(c); } return true; }
}

