class Solution {
    public static String shortestPalindrome(String s) {
        String reversedS = new StringBuilder(s).reverse().toString();
        for (int i = 0; i <= s.length(); i++) {
            if (s.startsWith(reversedS.substring(i))) {
                return reversedS.substring(0, i) + s;
            }
        }
        return s;
