class Solution {
    public static int[] findOrder(int numCourses, int[][] prerequisites) {
        List<Integer>[] graph = new ArrayList[numCourses];
        for (int i = 0; i < numCourses; i++) {
            graph[i] = new ArrayList<>();
        }
        int[] visited = new int[numCourses];
        List<Integer> result = new ArrayList<>();

        for (int[] pair : prerequisites) {
            int course = pair[0];
            int prerequisite = pair[1];
            graph[prerequisite].add(course);
        }

        for (int i = 0; i < numCourses; i++) {
            if (visited[i] == 0) {
                if (!dfs(graph, visited, result, i)) {
                    return new int[0];
                }
            }
        }

        Collections.reverse(result);
        int[] order = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            order[i] = result.get(i);
        }
        return order;
    }

    private static boolean dfs(List<Integer>[] graph, int[] visited, List<Integer> result, int node) {
        if (visited[node] == 1) {
            return false;
        }
        if (visited[node] == 2) {
            return true;
        }
        visited[node] = 1;
        for (int neighbor : graph[node]) {
            if (!dfs(graph, visited, result, neighbor)) {
                return false;
            }
        }
        visited[node] = 2;
        result.add(node);
        return true;
    }
}

import java.util.Arrays;

class Solution {
    public static int rob(int[] nums) {
        if (nums.length == 1) return nums[0];
        if (nums.length == 2) return Math.max(nums[0], nums[1]);
        int case1 = helper(Arrays.copyOfRange(nums, 0, nums.length - 1));
        int case2 = helper(Arrays.copyOfRange(nums, 1, nums.length));
        return Math.max(case1, case2);
    }

    private static int helper(int[] nums) {
        int[] dp = new int[nums.length];
        dp[0] = nums[0];
        dp[1] = Math.max(nums[0], nums[1]);
        for (int i = 2; i < nums.length; i++) {
            dp[i] = Math.max(dp[i - 1], dp[i - 2] + nums[i]);
        }
        return dp[nums.length - 1];
    }
}

import java.util.*;

class Solution {
    public static int findKthLargest(int[] nums, int k) {
        return quickSelect(nums, 0, nums.length - 1, nums.length - k);
    }

    private static int quickSelect(int[] nums, int left, int right, int k) {
        int pivotIndex = partition(nums, left, right);
        if (k == pivotIndex) {
            return nums[k];
        } else if (k < pivotIndex) {
            return quickSelect(nums, left, pivotIndex - 1, k);
        } else {
            return quickSelect(nums, pivotIndex + 1, right, k);
        }
    }

    private static int partition(int[] nums, int left, int right) {
        int pivot = nums[(left + right) / 2];
        int i = left, j = right;
        while (i <= j) {
            while (nums[i] < pivot) i++;
            while (nums[j] > pivot) j--;
            if (i <= j) {
                int temp = nums[i];
                nums[i] = nums[j];
                nums[j] = temp;
                i++;
                j--;
            }
        }
        return i - 1;
    }
}

class TrieNodeW { Map<Character, TrieNodeW> children = new HashMap<>(); boolean isEnd = false; }
class WordDictionary {
    TrieNodeW root = new TrieNodeW();
    public void addWord(String word) {
        TrieNodeW node = root;
        for (char c : word.toCharArray()) { node.children.putIfAbsent(c, new TrieNodeW()); node = node.children.get(c); }
        node.isEnd = true;
    }
    public boolean search(String word) { return dfs(root, word, 0); }
    private boolean dfs(TrieNodeW node, String word, int i) {
        if (i == word.length()) return node.isEnd;
        char c = word.charAt(i);
        if (c == '.') {
            for (TrieNodeW child : node.children.values()) if (dfs(child, word, i+1)) return true;
            return false;
        }
        if (!node.children.containsKey(c)) return false;
        return dfs(node.children.get(c), word, i+1);
    }
}

import java.util.*;

class Solution {
    static class Node {
        Map<Character, Node> children = new HashMap<>();
        String end = null;
    }

    public static List<String> findWords(char[][] board, String[] words) {
        List<String> result = new ArrayList<>();
        Node trie = new Node();
        for (String word : words) {
            Node node = trie;
            for (char ch : word.toCharArray()) {
                node = node.children.computeIfAbsent(ch, k -> new Node());
            }
            node.end = word;
        }
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                backtrack(i, j, trie, board, directions, result);
            }
        }
        Collections.sort(result);
        return result;
    }

    private static void backtrack(int i, int j, Node node, char[][] board, int[][] directions, List<String> result) {
        char c = board[i][j];
        if (!node.children.containsKey(c)) {
            return;
        }
        node = node.children.get(c);
        if (node.end != null) {
            result.add(node.end);
            node.end = null;
        }
        char temp = board[i][j];
        board[i][j] = '#';
        for (int[] dir : directions) {
            int x = i + dir[0];
            int y = j + dir[1];
            if (x >= 0 && x < board.length && y >= 0 && y < board[0].length) {
                backtrack(x, y, node, board, directions, result);
            }
        }
        board[i][j] = temp;
    }
}

