import java.util.HashMap;
import java.util.Map;

class Solution {
    public static boolean containsNearbyAlmostDuplicate(int[] nums, int indexDiff, int valueDiff) {
        Map<Long, Integer> buckets = new HashMap<>();
        long bucketSize = (long) valueDiff + 1L;
        for (int i = 0; i < nums.length; i++) {
            long bucketId = (long) Math.floor((double) nums[i] / bucketSize);
            if (buckets.containsKey(bucketId) ||
                (buckets.containsKey(bucketId - 1) && Math.abs((long) nums[i] - buckets.get(bucketId - 1)) <= valueDiff) ||
                (buckets.containsKey(bucketId + 1) && Math.abs((long) nums[i] - buckets.get(bucketId + 1)) <= valueDiff)) {
                return true;
            }
            buckets.put(bucketId, nums[i]);
            if (i >= indexDiff) {
                long oldBucketId = (long) Math.floor((double) nums[i - indexDiff] / bucketSize);
                buckets.remove(oldBucketId);
            }
        }
        return false;
    }
}

