class Solution {
    public static List<List<Integer>> combinationSum3(int k, int n) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(1, n, k, new ArrayList<>(), result);
        return result;
    }

    private static void backtrack(int start, int target, int k, List<Integer> path, List<List<Integer>> result) {
        if (k == 0 && target == 0) {
            result.add(new ArrayList<>(path));
            return;
        }
        if (k == 0 || target < 0) {
            return;
        }
        for (int i = start; i <= 9; i++) {
            path.add(i);
            backtrack(i + 1, target - i, k - 1, path, result);
            path.remove(path.size() - 1);
        }
    }
}

