class Solution {
    public static int maximalSquare(char[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0] == null || matrix[0].length == 0) {
            return 0;
        }
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] dp = new int[rows][cols];
        int maxSide = 0;
        for (int i = 0; i < rows; i++) {
            dp[i][0] = matrix[i][0] == '1' ? 1 : 0;
            if (dp[i][0] > maxSide) {
                maxSide = dp[i][0];
            }
        }
        for (int j = 0; j < cols; j++) {
            dp[0][j] = matrix[0][j] == '1' ? 1 : 0;
            if (dp[0][j] > maxSide) {
                maxSide = dp[0][j];
            }
        }
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (matrix[i][j] == '1') {
                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;
                    if (dp[i][j] > maxSide) {
                        maxSide = dp[i][j];
                    }
                }
            }
        }
        return maxSide * maxSide;
    }
}

import java.util.*;

class Solution {
    public static List<int[]> getSkyline(int[][] buildings) {
        List<int[]> points = new ArrayList<>();
        for (int[] b : buildings) {
            points.add(new int[]{b[0], -b[2]});
            points.add(new int[]{b[1], b[2]});
        }
        points.sort((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);
        TreeMap<Integer, Integer> heights = new TreeMap<>(Collections.reverseOrder());
        heights.put(0, 1);
        int prev = 0;
        List<int[]> result = new ArrayList<>();
        for (int[] p : points) {
            if (p[1] < 0) {
                int h = -p[1];
                heights.put(h, heights.getOrDefault(h, 0) + 1);
            } else {
                int h = p[1];
                int cnt = heights.get(h);
                if (cnt == 1) {
                    heights.remove(h);
                } else {
                    heights.put(h, cnt - 1);
                }
            }
            int curr = heights.firstKey();
            if (curr != prev) {
                result.add(new int[]{p[0], curr});
                prev = curr;
            }
        }
        return result;
    }
}

