        Integer[] result = new Integer[1];
        int[] count = new int[1];
        inorder(root, k, count, result);
        return result[0];
    }
    private static void inorder(TreeNode node, int k, int[] count, Integer[] result) {
        if (node == null) return;
        if (node.left != null) inorder(node.left, k, count, result);
        count[0]++;
        if (count[0] == k) {
            result[0] = node.val;
            return;
        }
        if (node.right != null) inorder(node.right, k, count, result);
    }
}

