class Solution {
    public static int[] singleNumber(int[] nums) {
        int xorResult = 0;
        for (int num : nums) {
            xorResult ^= num;
        }
        int rightmostSetBit = xorResult & -xorResult;
        int singleNumber1 = 0;
        int singleNumber2 = 0;
        for (int num : nums) {
            if ((num & rightmostSetBit) != 0) {
                singleNumber1 ^= num;
            } else {
                singleNumber2 ^= num;
            }
        }
        return new int[]{singleNumber1, singleNumber2};
    }
}

