class Solution {
    public static List<String> addOperators(String num, int target) {
        List<String> result = new ArrayList<>();
        backtrack(num, target, 0, "", 0, 0, result);
        return result;
    }

    private static void backtrack(String num, int target, int index, String path, long value, long prev, List<String> result) {
        if (index == num.length()) {
            if (value == target) {
                result.add(path);
            }
            return;
        }
        for (int i = index; i < num.length(); i++) {
            if (i != index && num.charAt(index) == '0') {
                break;
            }
            long cur = Long.parseLong(num.substring(index, i + 1));
            if (path.isEmpty()) {
                backtrack(num, target, i + 1, Long.toString(cur), cur, cur, result);
            } else {
                backtrack(num, target, i + 1, path + "*" + cur, value - prev + prev * cur, prev * cur, result);
                backtrack(num, target, i + 1, path + "+" + cur, value + cur, cur, result);
                backtrack(num, target, i + 1, path + "-" + cur, value - cur, -cur, result);
            }
        }
    }
}

