    public int sumRegion(int row1,int col1,int row2,int col2) {
        return (int)(prefix[row2+1][col2+1]-prefix[row1][col2+1]-prefix[row2+1][col1]+prefix[row1][col1]);
    }
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

class Solution {
    public static boolean isAdditiveNumber(String num) {
        return backtrack(num, 0, new ArrayList<>());
    }

    private static boolean isValid(String s) {
        return !(s.length() > 1 && s.charAt(0) == '0');
    }

    private static boolean backtrack(String num, int start, List<String> path) {
        if (start == num.length() && path.size() >= 3) {
            return true;
        }
        for (int i = start; i < num.length(); i++) {
            String currNum = num.substring(start, i + 1);
            if (!isValid(currNum)) {
                continue;
            }
            if (path.size() < 2) {
                List<String> newPath = new ArrayList<>(path);
                newPath.add(currNum);
                if (backtrack(num, i + 1, newPath)) {
                    return true;
                }
            } else {
                BigInteger sum = new BigInteger(path.get(path.size() - 1))
                        .add(new BigInteger(path.get(path.size() - 2)));
                if (sum.equals(new BigInteger(currNum))) {
                    List<String> newPath = new ArrayList<>(path);
                    newPath.add(currNum);
                    if (backtrack(num, i + 1, newPath)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

class NumArray {
    int n; int[] tree, nums;
    public NumArray(int[] in) { n = in.length; tree = new int[n+1]; nums = new int[n]; for (int i=0;i<n;i++) update(i, in[i]); }
    public void update(int index, int val) { int delta = val - nums[index]; nums[index]=val; for (int i=index+1;i<=n;i+=i&(-i)) tree[i]+=delta; }
    private int prefixSum(int i) { int s=0; for (int idx=i+1; idx>0; idx-=idx&(-idx)) s+=tree[idx]; return s; }
    public int sumRange(int left, int right) { return prefixSum(right) - (left>0?prefixSum(left-1):0); }
}

class Solution {
    public static int maxProfit(int[] prices) {
        int buy = Integer.MIN_VALUE;
        int sell = 0;
        int cooldown = 0;
        for (int price : prices) {
            int newBuy = Math.max(buy, cooldown - price);
            int newCooldown = Math.max(cooldown, sell);
            int newSell = Math.max(sell, buy + price);
            buy = newBuy;
            sell = newSell;
            cooldown = newCooldown;
        }
        return Math.max(sell, cooldown);
    }
}

import java.util.*;

class Solution {
    public static List<Integer> findMinHeightTrees(int n, int[][] edges) {
        if (n == 1) {
            return Collections.singletonList(0);
        }
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        int[] degree = new int[n];
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph[u].add(v);
            graph[v].add(u);
            degree[u]++;
            degree[v]++;
        }
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (degree[i] == 1) {
                queue.add(i);
            }
        }
        while (n > 2) {
            int size = queue.size();
            n -= size;
            for (int i = 0; i < size; i++) {
                int node = queue.poll();
                for (int neighbor : graph[node]) {
                    degree[neighbor]--;
                    if (degree[neighbor] == 1) {
                        queue.add(neighbor);
                    }
                }
            }
        }
        return new ArrayList<>(queue);
    }
}

