class Solution {
    public static int[] countSmallerNumbersAfterSelf(int[] nums) {
        int n = nums.length;
        int[] count = new int[n];
        int[] indices = new int[n];
        int[] temp = new int[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }
        mergeSort(nums, indices, temp, count, 0, n - 1);
        return count;
    }

    private static void mergeSort(int[] nums, int[] indices, int[] temp, int[] count, int left, int right) {
        if (left >= right) {
            return;
        }
        int mid = left + (right - left) / 2;
        mergeSort(nums, indices, temp, count, left, mid);
        mergeSort(nums, indices, temp, count, mid + 1, right);
        merge(nums, indices, temp, count, left, mid, right);
    }

    private static void merge(int[] nums, int[] indices, int[] temp, int[] count, int left, int mid, int right) {
        int i = left;
        int j = mid + 1;
        int k = left;
        int rightCount = 0;
        while (i <= mid && j <= right) {
            if (nums[indices[j]] < nums[indices[i]]) {
                temp[k++] = indices[j++];
                rightCount++;
            } else {
                count[indices[i]] += rightCount;
                temp[k++] = indices[i++];
            }
        }
        while (i <= mid) {
            count[indices[i]] += rightCount;
            temp[k++] = indices[i++];
        }
        while (j <= right) {
            temp[k++] = indices[j++];
        }
        for (int p = left; p <= right; p++) {
            indices[p] = temp[p];
        }
    }
}

