class Solution {
    public static int countRangeSum(int[] nums, int lower, int upper) {
        int n = nums.length;
        long[] prefixSums = new long[n + 1];
        prefixSums[0] = 0;
        for (int i = 0; i < n; i++) {
            prefixSums[i + 1] = prefixSums[i] + nums[i];
        }
        long count = sortAndCount(prefixSums, lower, upper, 0, prefixSums.length - 1);
        return (int) count;
    }

    private static long sortAndCount(long[] sums, int lower, int upper, int left, int right) {
        if (right - left <= 0) {
            return 0;
        }
        int mid = (left + right) >>> 1;
        long count = sortAndCount(sums, lower, upper, left, mid) + sortAndCount(sums, lower, upper, mid + 1, right);
        int j = mid + 1, k = mid + 1, t = mid + 1;
        long[] cache = new long[right - left + 1];
        int r = 0;
        for (int i = left; i <= mid; i++) {
            while (k <= right && sums[k] - sums[i] < lower) {
                k++;
            }
            while (j <= right && sums[j] - sums[i] <= upper) {
                j++;
            }
            count += j - k;
            while (t <= right && sums[t] < sums[i]) {
                cache[r++] = sums[t++];
            }
            cache[r++] = sums[i];
        }
        while (t <= right) {
            cache[r++] = sums[t++];
        }
        System.arraycopy(cache, 0, sums, left, r);
        return count;
    }
}

