public class Solution {
    public static int longestIncreasingPath(int[][] matrix) {
        if (matrix == null || matrix.length == 0) return 0;
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int[][] memo = new int[rows][cols];
        int maxLength = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                maxLength = Math.max(maxLength, dfs(i, j, matrix, memo, rows, cols, directions));
            }
        }
        return maxLength;
    }

    private static int dfs(int row, int col, int[][] matrix, int[][] memo, int rows, int cols, int[][] directions) {
        if (memo[row][col] != 0) return memo[row][col];
        int longestPath = 1;
        for (int[] dir : directions) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && matrix[nr][nc] > matrix[row][col]) {
                longestPath = Math.max(longestPath, 1 + dfs(nr, nc, matrix, memo, rows, cols, directions));
            }
        }
        memo[row][col] = longestPath;
        return longestPath;
    }
}

