class Solution {
    public static List<String> findItinerary(List<List<String>> tickets) {
        Map<String, LinkedList<String>> graph = new HashMap<>();
        for (int i = 0; i < tickets.size(); i++) {
            List<String> ticket = tickets.get(i);
            String from = ticket.get(0);
            String to = ticket.get(1);
            graph.computeIfAbsent(from, k -> new LinkedList<>()).add(to);
        }
        for (Map.Entry<String, LinkedList<String>> entry : graph.entrySet()) {
            Collections.sort(entry.getValue());
        }
        List<String> path = new ArrayList<>();
        path.add("JFK");
        dfs(graph, tickets.size(), path);
        return path;
    }

    private static boolean dfs(Map<String, LinkedList<String>> graph, int ticketCount, List<String> path) {
        if (path.size() - 1 == ticketCount) {
            return true;
        }
        String currentAirport = path.get(path.size() - 1);
        LinkedList<String> destinations = graph.get(currentAirport);
        if (destinations == null || destinations.isEmpty()) {
            return false;
        }
        int size = destinations.size();
        for (int i = 0; i < size; i++) {
            String nextDestination = destinations.removeFirst();
            path.add(nextDestination);
            if (dfs(graph, ticketCount, path)) {
                return true;
            }
            path.remove(path.size() - 1);
            destinations.addFirst(nextDestination);
        }
        return false;
    }
}

