class Solution {
    public static int maxCoins(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] extended = new int[n + 2];
        extended[0] = 1;
        System.arraycopy(nums, 0, extended, 1, n);
        extended[n + 1] = 1;
        int[][] dp = new int[n + 2][n + 2];
        int totalLength = n + 2;
        for (int gap = 2; gap < totalLength; gap++) {
            for (int left = 0; left + gap < totalLength; left++) {
                int right = left + gap;
                int best = 0;
                for (int i = left + 1; i < right; i++) {
                    int coins = extended[left] * extended[i] * extended[right] + dp[left][i] + dp[i][right];
                    if (coins > best) {
                        best = coins;
                    }
                }
                dp[left][right] = best;
            }
        }
        return dp[0][totalLength - 1];
    }
}

