class SummaryRanges {
    TreeMap<Integer,Integer> intervals = new TreeMap<>();
    public void addNum(int value) {
        Map.Entry<Integer,Integer> floor = intervals.floorEntry(value);
        if (floor != null && floor.getValue() >= value) return;
        boolean mergeLeft = floor != null && floor.getValue() == value - 1;
        Map.Entry<Integer,Integer> ceil = intervals.ceilingEntry(value + 1);
        boolean mergeRight = ceil != null && ceil.getKey() == value + 1;
        if (mergeLeft && mergeRight) {
            intervals.put(floor.getKey(), ceil.getValue());
            intervals.remove(ceil.getKey());
        } else if (mergeLeft) {
            intervals.put(floor.getKey(), value);
        } else if (mergeRight) {
            intervals.put(value, ceil.getValue());
            intervals.remove(ceil.getKey());
        } else {
            intervals.put(value, value);
        }
    }
    public int[][] getIntervals() {
        int[][] res = new int[intervals.size()][2]; int i = 0;
        for (Map.Entry<Integer,Integer> ent : intervals.entrySet()) res[i++] = new int[]{ent.getKey(), ent.getValue()};
        return res;
    }
}

