class Solution {
    public static int countNumbersWithUniqueDigits(int n) {
        if (n == 0) {
            return 1;
        }
        n = Math.min(n, 10);
        int count = 10;
        int uniqueDigits = 9;
        int availableNumberPool = 9;
        for (int x = 2; x <= n && availableNumberPool > 0; x++) {
            uniqueDigits *= availableNumberPool;
            count += uniqueDigits;
            availableNumberPool--;
        }
        return count;
    }
}

import java.util.TreeSet;

class Solution {
    public static int maxSumSubmatrix(int[][] matrix, int k) {
        int maxSum = Integer.MIN_VALUE;
        int rows = matrix.length;
        int cols = matrix[0].length;
        for (int left = 0; left < cols; left++) {
            int[] temp = new int[rows];
            for (int right = left; right < cols; right++) {
                for (int i = 0; i < rows; i++) {
                    temp[i] += matrix[i][right];
                }
                maxSum = Math.max(maxSum, maxSumSubarray(temp, k));
            }
        }
        return maxSum;
    }

    private static int maxSumSubarray(int[] nums, int k) {
        TreeSet<Integer> set = new TreeSet<>();
        set.add(0);
        int curSum = 0;
        int best = Integer.MIN_VALUE;
        for (int num : nums) {
            curSum += num;
            Integer target = set.ceiling(curSum - k);
            if (target != null) {
                best = Math.max(best, curSum - target);
            }
            set.add(curSum);
        }
        return best;
    }
}

