class Solution {
    public static boolean canMeasureWater(int x, int y, int target) {
        Queue<int[]> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.add(new int[]{0, 0});
        visited.add("0,0");
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int currX = curr[0];
            int currY = curr[1];
            if (currX + currY == target) {
                return true;
            }
            int[][] nextStates = {
                {x, currY},
                {currX, y},
                {0, currY},
                {currX, 0},
                {Math.max(0, currX - (y - currY)), Math.min(y, currY + currX)},
                {Math.min(x, currX + currY), Math.max(0, currY - (x - currX))}
            };
            for (int[] state : nextStates) {
                String key = state[0] + "," + state[1];
                if (!visited.contains(key)) {
                    queue.add(state);
                    visited.add(key);
                }
            }
        }
        return false;
    }
}

