class Solution {
    public static int superPow(int a, int[] b) {
        int result = 1;
        int mod = 1337;
        for (int i = 0; i < b.length; i++) {
            result = (int) ((long) powMod(result, 10, mod) * powMod(a, b[i], mod) % mod);
        }
        return result;
    }

    private static int powMod(int base, int exp, int mod) {
        long result = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * b % mod;
            }
            b = b * b % mod;
            exp >>= 1;
        }
        return (int) result;
    }
}

