class Solution {
    public static List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums1 == null || nums2 == null || nums1.length == 0 || nums2.length == 0 || k <= 0) {
            return result;
        }
        PriorityQueue<Node> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a.sum));
        for (int i = 0; i < nums1.length; i++) {
            minHeap.offer(new Node(i, 0, nums1[i], nums2[0]));
        }
        while (!minHeap.isEmpty() && result.size() < k) {
            Node cur = minHeap.poll();
            result.add(Arrays.asList(cur.u, cur.v));
            if (cur.j + 1 < nums2.length) {
                minHeap.offer(new Node(cur.i, cur.j + 1, nums1[cur.i], nums2[cur.j + 1]));
            }
        }
        return result;
    }

    private static class Node {
        int i;
        int j;
        int u;
        int v;
