public class Solution {
    public static int kthSmallest(int[][] matrix, int k) {
        int n = matrix.length;
        int low = matrix[0][0];
        int high = matrix[n - 1][n - 1];
        while (low < high) {
            int mid = (low + high) / 2;
            int count = 0;
            int j = n - 1;
            for (int i = 0; i < n; i++) {
                while (j >= 0 && matrix[i][j] > mid) {
                    j--;
                }
                count += (j + 1);
            }
            if (count < k) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

class RandomizedSet {
    List<Integer> values = new ArrayList<>();
    Map<Integer,Integer> indexMap = new HashMap<>();
    public boolean insert(int val) {
        if (indexMap.containsKey(val)) return false;
        indexMap.put(val, values.size()); values.add(val); return true;
    }
    public boolean remove(int val) {
        if (!indexMap.containsKey(val)) return false;
        int idx = indexMap.get(val); int last = values.get(values.size()-1);
        values.set(idx, last); indexMap.put(last, idx);
        values.remove(values.size()-1); indexMap.remove(val); return true;
    }
    public int getRandom() { return values.get(new Random().nextInt(values.size())); }
}

