class RandomizedCollection {
    List<Integer> values = new ArrayList<>();
    Map<Integer, Set<Integer>> idxMap = new HashMap<>();
    public boolean insert(int val) {
        boolean present = idxMap.containsKey(val) && !idxMap.get(val).isEmpty();
        idxMap.computeIfAbsent(val, k -> new LinkedHashSet<>()).add(values.size());
        values.add(val);
        return !present;
    }
    public boolean remove(int val) {
        if (!idxMap.containsKey(val) || idxMap.get(val).isEmpty()) return false;
        int idx = idxMap.get(val).iterator().next();
        idxMap.get(val).remove(idx);
        int last = values.get(values.size()-1), lastIdx = values.size()-1;
        values.set(idx, last);
        if (idx != lastIdx) { idxMap.get(last).remove(lastIdx); idxMap.get(last).add(idx); }
        values.remove(values.size()-1);
        return true;
    }
    public int getRandom() { return values.get(new Random().nextInt(values.size())); }
}

