import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static Object deserialize(String s) {
        if (s.charAt(0) != '[') {
            return Integer.parseInt(s);
        }
        Stack<List<Object>> stack = new Stack<>();
        StringBuilder currNum = new StringBuilder();
        boolean hasNum = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                stack.push(new ArrayList<Object>());
            } else if (c == '-' || (c >= '0' && c <= '9')) {
                currNum.append(c);
                hasNum = true;
            } else if (c == ',' || c == ']') {
                if (hasNum) {
                    stack.peek().add(Integer.parseInt(currNum.toString()));
                    currNum.setLength(0);
                    hasNum = false;
                }
                if (c == ']') {
                    List<Object> top = stack.pop();
                    if (stack.isEmpty()) {
                        return top;
                    }
                    stack.peek().add(top);
                }
            }
        }
        return stack.isEmpty() ? new ArrayList<Object>() : stack.peek();
    }
}

