class Solution {
    public static boolean isRectangleCover(int[][] rectangles) {
        long area = 0;
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        Map<String, Integer> corners = new HashMap<>();
        for (int[] rectangle : rectangles) {
            int x = rectangle[0];
            int y = rectangle[1];
            int a = rectangle[2];
            int b = rectangle[3];
            area += (long) (a - x) * (b - y);
            if (x < minX) minX = x;
            if (y < minY) minY = y;
            if (a > maxX) maxX = a;
            if (b > maxY) maxY = b;
            int[][] points = {{x, y}, {x, b}, {a, y}, {a, b}};
            for (int[] point : points) {
                String key = point[0] + "," + point[1];
                if (corners.containsKey(key)) {
                    corners.remove(key);
                } else {
                    corners.put(key, 1);
                }
            }
        }
        if (area != (long) (maxX - minX) * (maxY - minY)) {
            return false;
        }
        if (corners.size() != 4) {
            return false;
        }
        String[] required = {
            minX + "," + minY,
            minX + "," + maxY,
            maxX + "," + minY,
            maxX + "," + maxY
        };
        for (String key : required) {
            if (!corners.containsKey(key)) {
                return false;
            }
        }
        return true;
    }
}

