class Solution {
    public static int longestSubstring(String s, int k) {
        if (s.length() < k) return 0;
        Set<Character> unique = new HashSet<>();
        for (char c : s.toCharArray()) unique.add(c);
        for (char uniqueChar : unique) {
            int count = 0;
            for (int i = 0; i < s.length(); i++) if (s.charAt(i) == uniqueChar) count++;
            if (count < k) {
                String[] parts = s.split(Pattern.quote(String.valueOf(uniqueChar)));
                int max = 0;
                for (String part : parts) {
                    int val = longestSubstring(part, k);
                    if (val > max) max = val;
                }
                return max;
            }
        }
        return s.length();
    }
}

