class Solution {
    public static int integerReplacement(int n) {
        long cur = n;
        int operations = 0;
        while (cur != 1) {
            if ((cur & 1) == 0) {
                cur >>= 1;
            } else if ((cur & 3) == 1 || cur == 3) {
                cur--;
            } else {
                cur++;
            }
            operations++;
        }
        return operations;
    }
}

class Solution {
    public static int rotateFunction(int[] nums) {
        int n = nums.length;
        long totalSum = 0;
        long initialSum = 0;
        for (int i = 0; i < n; i++) {
            totalSum += nums[i];
            initialSum += (long) i * nums[i];
        }
        long maxVal = initialSum;
        for (int k = 1; k < n; k++) {
            initialSum = initialSum + totalSum - (long) n * nums[n - k];
            if (initialSum > maxVal) {
                maxVal = initialSum;
            }
        }
        return (int) maxVal;
    }
}

