class Solution {
    static class Edge {
        String node;
        double weight;
        Edge(String node, double weight) {
            this.node = node;
            this.weight = weight;
        }
    }

    public static double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {
        Map<String, List<Edge>> graph = new HashMap<>();
        for (int i = 0; i < equations.size(); i++) {
            List<String> eq = equations.get(i);
            String a = eq.get(0);
            String b = eq.get(1);
            double val = values[i];
            graph.computeIfAbsent(a, k -> new ArrayList<>()).add(new Edge(b, val));
            graph.computeIfAbsent(b, k -> new ArrayList<>()).add(new Edge(a, 1.0 / val));
        }

        double[] result = new double[queries.size()];
        for (int i = 0; i < queries.size(); i++) {
            List<String> q = queries.get(i);
            String a = q.get(0);
            String b = q.get(1);
            if (!graph.containsKey(a) || !graph.containsKey(b)) {
                result[i] = -1.0;
            } else {
                result[i] = dfs(a, b, new HashSet<>(), graph);
            }
        }
        return result;
    }

    private static double dfs(String a, String b, Set<String> visited, Map<String, List<Edge>> graph) {
        if (a.equals(b)) return 1.0;
        visited.add(a);
        for (Edge edge : graph.get(a)) {
            if (edge.node.equals(b) && !visited.contains(edge.node)) {
                return edge.weight;
            }
            if (!visited.contains(edge.node)) {
                double subResult = dfs(edge.node, b, visited, graph);
                if (subResult != -1.0) {
                    return edge.weight * subResult;
                }
            }
        }
        return -1.0;
    }
}

