class Solution {
    public static boolean canCross(int[] stones) {
        int n = stones.length;
        Set<Integer> stoneSet = new HashSet<>();
        for (int stone : stones) {
            stoneSet.add(stone);
        }
        Map<String, Boolean> memo = new HashMap<>();
        return dfs(stones[0], 1, stones, stoneSet, memo);
    }

    private static boolean dfs(int stone, int k, int[] stones, Set<Integer> stoneSet, Map<String, Boolean> memo) {
        String key = stone + "," + k;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        if (stone == stones[stones.length - 1]) {
            return true;
        }
        for (int jump = k - 1; jump <= k + 1; jump++) {
            if (jump <= 0) {
                continue;
            }
            int nextStone = stone + jump;
            if (stoneSet.contains(nextStone)) {
                if (dfs(nextStone, jump, stones, stoneSet, memo)) {
                    memo.put(key, true);
                    return true;
                }
            }
        }
        memo.put(key, false);
        return false;
    }
}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class Solution {
    public static int sumOfLeftLeaves(TreeNode root) {
        return dfs(root, false);
    }
    private static int dfs(TreeNode node, boolean isLeft) {
        if (node == null) return 0;
        if (node.left == null && node.right == null && isLeft) return node.val;
        return dfs(node.left, true) + dfs(node.right, false);
    }
}

class Solution {
    public static String toHex(long num) {
        if (num == 0) return "0";
        String result = "";
        boolean isNegative = num < 0;
        if (isNegative) num = num + (1L << 32);
        while (num > 0) {
            long remainder = num % 16;
            if (remainder < 10) result = (char) (48 + remainder) + result;
            else result = (char) (87 + remainder) + result;
            num = num / 16;
        }
        return result;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static String removeKDigits(String num, int k) {
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < num.length(); i++) {
            char current = num.charAt(i);
            while (!stack.isEmpty() && stack.peekLast() > current && k > 0) {
                stack.pollLast();
                k--;
            }
            stack.addLast(current);
        }
        while (k > 0 && !stack.isEmpty()) {
            stack.pollLast();
            k--;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : stack) {
            sb.append(c);
        }
        String result = sb.toString().replaceFirst("^0+", "");
        if (result.isEmpty()) {
            result = "0";
        }
        return result;
    }
}

import java.util.ArrayList;
