class Solution {
    public static int trapRainWater(int[][] heightMap) {
        int m = heightMap.length;
        int n = heightMap[0].length;
        boolean[][] visited = new boolean[m][n];
        List<int[]> pq = new ArrayList<>();
        int volume = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 || j == 0 || i == m - 1 || j == n - 1) {
                    visited[i][j] = true;
                    pq.add(new int[]{heightMap[i][j], i, j});
                }
            }
        }
        pq.sort((a, b) -> Integer.compare(a[0], b[0]));
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!pq.isEmpty()) {
            int[] cur = pq.remove(0);
            int height = cur[0];
            int x = cur[1];
            int y = cur[2];
            for (int[] d : directions) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && !visited[nx][ny]) {
                    volume += Math.max(0, height - heightMap[nx][ny]);
                    heightMap[nx][ny] = Math.max(heightMap[nx][ny], height);
                    visited[nx][ny] = true;
                    pq.add(new int[]{heightMap[nx][ny], nx, ny});
                    pq.sort((a, b) -> Integer.compare(a[0], b[0]));
                }
            }
        }
        return volume;
    }
}

