class Solution {
    public static int thirdMax(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int n : nums) {
            set.add(n);
        }
        List<Integer> unique = new ArrayList<>(set);
        unique.sort(Collections.reverseOrder());
        if (unique.size() >= 3) {
            return unique.get(2);
        }
        return unique.get(0);
    }
}

