class Solution {
    public static int splitArray(int[] nums, int k) {
        long left = Long.MIN_VALUE;
        for (int num : nums) {
            if (num > left) left = num;
        }
        long right = 0;
        for (int num : nums) {
            right += num;
        }
        while (left < right) {
            long mid = (left + right) / 2;
            int count = 1;
            long sum = 0;
            for (int num : nums) {
                sum += num;
                if (sum > mid) {
                    count++;
                    sum = num;
                }
            }
            if (count > k) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return (int) left;
    }
}

