public class Solution {
    public static boolean canPartition(int[] nums) {
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }
        if (totalSum % 2 != 0) {
            return false;
        }
        int targetSum = totalSum / 2;
        boolean[] dp = new boolean[targetSum + 1];
        dp[0] = true;
        for (int num : nums) {
            for (int i = targetSum; i >= num; i--) {
                dp[i] = dp[i] || dp[i - num];
            }
        }
        return dp[targetSum];
    }
}

public class Solution {
    public static int strongPasswordChecker(String password) {
        int missingTypes = 3;
        boolean one = false, upper = false, digit = false;
        int totalLength = password.length();
        int changes = 0;
        for (int i = 0; i < totalLength; i++) {
            char c = password.charAt(i);
            if (c >= 'a' && c <= 'z') one = true;
            else if (c >= 'A' && c <= 'Z') upper = true;
            else if (c >= '0' && c <= '9') digit = true;
        }
        if (one) missingTypes--;
        if (upper) missingTypes--;
        if (digit) missingTypes--;
        if (totalLength < 6) {
            changes += 6 - totalLength;
        } else if (totalLength > 20) {
            changes += totalLength - 20;
        }
        int i = 2;
        while (i < totalLength) {
            if (password.charAt(i) == password.charAt(i - 1) && password.charAt(i) == password.charAt(i - 2)) {
                int length = 2;
                while (i + 1 < totalLength && password.charAt(i) == password.charAt(i + 1)) {
                    i++;
                    length++;
                }
                changes += length / 3;
            }
            i++;
        }
        return Math.max(missingTypes, changes);
    }
}

