public class Solution {
    public static List<List<Integer>> pacificAtlantic(int[][] heights) {
        List<List<Integer>> result = new ArrayList<>();
        if (heights == null || heights.length == 0 || heights[0].length == 0) {
            return result;
        }
        int m = heights.length;
        int n = heights[0].length;
        boolean[][] pacific = new boolean[m][n];
        boolean[][] atlantic = new boolean[m][n];
        for (int i = 0; i < m; i++) {
            dfs(i, 0, pacific, heights, m, n);
        }
        for (int j = 0; j < n; j++) {
            dfs(0, j, pacific, heights, m, n);
        }
        for (int i = 0; i < m; i++) {
            dfs(i, n - 1, atlantic, heights, m, n);
        }
        for (int j = 0; j < n; j++) {
            dfs(m - 1, j, atlantic, heights, m, n);
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (pacific[i][j] && atlantic[i][j]) {
                    List<Integer> pair = new ArrayList<>(2);
                    pair.add(i);
                    pair.add(j);
                    result.add(pair);
                }
            }
        }
        return result;
    }

    private static void dfs(int row, int col, boolean[][] visited, int[][] heights, int m, int n) {
        visited[row][col] = true;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : directions) {
            int nr = row + d[0];
            int nc = col + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && heights[nr][nc] >= heights[row][col]) {
                dfs(nr, nc, visited, heights, m, n);
            }
        }
    }
}

import java.util.*;

class Solution {
    private static class Node {
        Node[] child = new Node[2];
    }

    public static int findMaximumXOR(int[] nums) {
        int maximumXOR = 0;
        Node root = new Node();
        for (int num : nums) {
            Node node = root;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.child[bit] == null) {
                    node.child[bit] = new Node();
                }
                node = node.child[bit];
            }
        }
        for (int num : nums) {
            Node node = root;
            int currentXOR = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.child[1 - bit] != null) {
                    currentXOR |= (1 << i);
                    node = node.child[1 - bit];
                } else {
                    node = node.child[bit];
                }
            }
            maximumXOR = Math.max(maximumXOR, currentXOR);
        }
        return maximumXOR;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int characterReplacement(String s, int k) {
        int maxLength = 0;
        int windowStart = 0;
        Map<Character, Integer> frequencyMap = new HashMap<>();
        int maxFrequency = 0;
        for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {
            char rightChar = s.charAt(windowEnd);
            frequencyMap.put(rightChar, frequencyMap.getOrDefault(rightChar, 0) + 1);
            maxFrequency = Math.max(maxFrequency, frequencyMap.get(rightChar));
            if ((windowEnd - windowStart + 1) - maxFrequency > k) {
                char leftChar = s.charAt(windowStart);
                frequencyMap.put(leftChar, frequencyMap.get(leftChar) - 1);
                windowStart++;
            }
            maxLength = Math.max(maxLength, windowEnd - windowStart + 1);
        }
        return maxLength;
    }
}

