import java.util.*;

class Solution {
    public static List<Object> construct(int[][] grid) {
        return constructQuadTree(grid, 0, 0, grid.length);
    }

    private static List<Object> constructQuadTree(int[][] grid, int x, int y, int n) {
        boolean isLeaf = true;
        int val = grid[x][y];
        for (int i = x; i < x + n; i++) {
            for (int j = y; j < y + n; j++) {
                if (grid[i][j] != val) {
                    isLeaf = false;
                    break;
                }
            }
            if (!isLeaf) break;
        }
        if (isLeaf) {
            List<Object> leaf = new ArrayList<>();
            leaf.add(1);
            leaf.add(val);
            return leaf;
        }
        List<Object> node = new ArrayList<>();
        node.add(0);
        node.add(0);
        int half = n / 2;
        node.add(constructQuadTree(grid, x, y, half));
        node.add(constructQuadTree(grid, x, y + half, half));
        node.add(constructQuadTree(grid, x + half, y, half));
        node.add(constructQuadTree(grid, x + half, y + half, half));
        return node;
    }
}

