class Solution {
    private Node prev;
    public Node flatten(Node head) {
        if (head == null) return null;
        Node dummy = new Node(0, null, null, null);
        prev = dummy;
        dfs(head);
        dummy.next.prev = null;
        return dummy.next;
    }
    private void dfs(Node node) {
        if (node == null) return;
        prev.next = node;
        node.prev = prev;
        Node temp = node.next;
        prev = node;
        dfs(node.child);
        node.child = null;
        dfs(temp);
    }
}

import java.util.*;

class Solution {
    private static class Pair {
        String gene;
        int steps;
        Pair(String gene, int steps) {
            this.gene = gene;
            this.steps = steps;
        }
    }

    public static int minMutation(String startGene, String endGene, String[] bank) {
        Set<String> bankSet = new HashSet<>(Arrays.asList(bank));
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(startGene, 0));
        Set<String> visited = new HashSet<>();
        visited.add(startGene);
        char[] chars = {'A', 'C', 'G', 'T'};
        while (!queue.isEmpty()) {
            Pair current = queue.poll();
            String currentGene = current.gene;
            int steps = current.steps;
            if (currentGene.equals(endGene)) {
                return steps;
            }
            for (int i = 0; i < 8; i++) {
                for (char c : chars) {
                    String nextGene = currentGene.substring(0, i) + c + currentGene.substring(i + 1);
                    if (bankSet.contains(nextGene) && !visited.contains(nextGene)) {
                        queue.offer(new Pair(nextGene, steps + 1));
                        visited.add(nextGene);
                    }
                }
            }
        }
        return -1;
    }
}

public class Solution {
