        int segmentCount = 0;
        boolean inSegment = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != ' ' && !inSegment) {
                segmentCount++;
                inSegment = true;
            } else if (c == ' ' && inSegment) {
                inSegment = false;
            }
        }
        return segmentCount;
    }
}

class AllOne {
    class Node { int count; Set<String> keys = new LinkedHashSet<>(); Node prev, next; Node(int c) { count = c; } }
    Node head = new Node(0), tail = new Node(0);
    Map<String, Node> keyNode = new HashMap<>();
    public AllOne() { head.next = tail; tail.prev = head; }
    private Node insertAfter(Node node, int count) {
        Node n = new Node(count);
        n.prev = node; n.next = node.next; node.next.prev = n; node.next = n;
        return n;
    }
    private void remove(Node node) { node.prev.next = node.next; node.next.prev = node.prev; }
    public void inc(String key) {
        if (!keyNode.containsKey(key)) {
            Node n = (head.next.count == 1) ? head.next : insertAfter(head, 1);
            n.keys.add(key); keyNode.put(key, n);
        } else {
            Node node = keyNode.get(key); node.keys.remove(key);
            Node n = (node.next.count == node.count+1) ? node.next : insertAfter(node, node.count+1);
            n.keys.add(key); keyNode.put(key, n);
            if (node.keys.isEmpty()) remove(node);
        }
    }
    public void dec(String key) {
        Node node = keyNode.get(key); node.keys.remove(key);
        if (node.count == 1) keyNode.remove(key);
        else {
            Node n;
            if (node.prev.count == node.count-1) n = node.prev;
            else { n = new Node(node.count-1); n.prev = node.prev; n.next = node; node.prev.next = n; node.prev = n; }
            n.keys.add(key); keyNode.put(key, n);
        }
        if (node.keys.isEmpty()) remove(node);
    }
    public String getMaxKey() { return tail.prev == head ? "" : tail.prev.keys.iterator().next(); }
    public String getMinKey() { return head.next == tail ? "" : head.next.keys.iterator().next(); }
}

import java.util.Arrays;
import java.util.Comparator;

class Solution {
    public static int[] findRightInterval(int[][] intervals) {
        int n = intervals.length;
        int[] result = new int[n];
        int[][] intervalIndices = new int[n][2];
        for (int i = 0; i < n; i++) {
            intervalIndices[i][0] = intervals[i][0];
            intervalIndices[i][1] = i;
        }
        Arrays.sort(intervalIndices, new Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                return Integer.compare(a[0], b[0]);
            }
        });
        for (int i = 0; i < n; i++) {
            int target = intervals[i][1];
            int left = 0, right = n - 1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (intervalIndices[mid][0] >= target) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            result[i] = left < n ? intervalIndices[left][1] : -1;
        }
        return result;
    }
}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}
class Solution {
    public int pathSum(TreeNode root, int targetSum) {
        int[] count = new int[1];
        traverse(root, targetSum, count);
        return count[0];
    }
    private static void dfs(TreeNode node, int currentSum, int targetSum, int[] count) {
        if (node == null) return;
        currentSum += node.val;
        if (currentSum == targetSum) count[0]++;
        dfs(node.left, currentSum, targetSum, count);
        dfs(node.right, currentSum, targetSum, count);
    }
    private static void traverse(TreeNode node, int targetSum, int[] count) {
        if (node == null) return;
        dfs(node, 0, targetSum, count);
        traverse(node.left, targetSum, count);
        traverse(node.right, targetSum, count);
    }
}

