class Solution {
    public static List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        Map<Character, Integer> pCount = new HashMap<>();
        Map<Character, Integer> sCount = new HashMap<>();

        for (char ch : p.toCharArray()) {
            pCount.put(ch, pCount.getOrDefault(ch, 0) + 1);
        }

        int left = 0;
        int right = 0;

        while (right < s.length()) {
            char c = s.charAt(right);
            sCount.put(c, sCount.getOrDefault(c, 0) + 1);

            if (right - left + 1 == p.length()) {
                boolean isAnagram = true;
                for (char ch : pCount.keySet()) {
                    if (!pCount.get(ch).equals(sCount.getOrDefault(ch, 0))) {
                        isAnagram = false;
                        break;
                    }
                }
                if (isAnagram) {
                    result.add(left);
                }

                char leftChar = s.charAt(left);
                int cnt = sCount.get(leftChar) - 1;
                if (cnt == 0) {
                    sCount.remove(leftChar);
                } else {
                    sCount.put(leftChar, cnt);
                }
                left++;
            }
            right++;
        }

        return result;
    }
}

public class Solution {
    public static int findKthNumber(int n, int k) {
        int cur = 1;
        k--;
        while (k > 0) {
            long step = 0;
            long first = cur;
            long last = cur + 1;
            while (first <= n) {
                step += Math.min((long) n + 1, last) - first;
                first *= 10;
                last *= 10;
            }
            if (k >= step) {
                k -= step;
                cur++;
            } else {
                k--;
                cur *= 10;
            }
        }
        return cur;
    }
}

