class Solution {
    public static int arrangeCoins(int n) {
        long left = 1, right = n;
        while (left <= right) {
            long mid = (left + right) / 2;
            long sum = mid * (mid + 1) / 2;
            if (sum <= n) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return (int) right;
    }
}

class Solution {
    public static int compress(char[] chars) {
        int write = 0;
        int n = chars.length;
        int i = 0;
        while (i < n) {
            char c = chars[i];
            int count = 0;
            while (i < n && chars[i] == c) {
                i++;
                count++;
            }
            chars[write++] = c;
            if (count > 1) {
                String cnt = Integer.toString(count);
                for (int k = 0; k < cnt.length(); k++) {
                    chars[write++] = cnt.charAt(k);
                }
            }
        }
        return write;
    }
}

