class Solution {
    public static long numberOfArithmeticSlices(int[] nums) {
        long count = 0;
        int n = nums.length;
        Map<Long, Long>[] dp = new HashMap[n];
        for (int i = 0; i < n; i++) {
            dp[i] = new HashMap<>();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                long diff = (long) nums[i] - (long) nums[j];
                long prev = dp[j].getOrDefault(diff, 0L);
                count += prev;
                long cur = dp[i].getOrDefault(diff, 0L);
                dp[i].put(diff, cur + prev + 1);
            }
        }
        return count;
    }
}

