class Solution {
    public static boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int slow = i, fast = i;
            boolean direction = nums[i] > 0;
            while (true) {
                slow = findNextIndex(nums, slow, direction);
                if (slow == -1) break;
                fast = findNextIndex(nums, fast, direction);
                if (fast == -1) break;
                fast = findNextIndex(nums, fast, direction);
                if (fast == -1) break;
                if (slow == fast) {
                    if (slow == findNextIndex(nums, slow, direction)) {
                        continue;
                    } else {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static int findNextIndex(int[] nums, int currentIndex, boolean direction) {
        int n = nums.length;
        int move = nums[currentIndex];
        if ((move > 0) != direction) return -1;
        int next = ((currentIndex + move) % n + n) % n;
        if (next == currentIndex) return -1;
        return next;
    }
}

