class LFUCache {
    int capacity, minFreq;
    Map<Integer,Integer> keyVal = new HashMap<>(), keyFreq = new HashMap<>();
    Map<Integer, LinkedHashSet<Integer>> freqKeys = new HashMap<>();
    public LFUCache(int capacity) { this.capacity = capacity; }
    private void touch(int key) {
        int freq = keyFreq.get(key); freqKeys.get(freq).remove(key);
        if (freqKeys.get(freq).isEmpty()) { freqKeys.remove(freq); if (minFreq == freq) minFreq++; }
        keyFreq.put(key, freq+1); freqKeys.computeIfAbsent(freq+1, k -> new LinkedHashSet<>()).add(key);
    }
    public int get(int key) { if (!keyVal.containsKey(key)) return -1; touch(key); return keyVal.get(key); }
    public void put(int key, int value) {
        if (capacity <= 0) return;
        if (keyVal.containsKey(key)) { keyVal.put(key, value); touch(key); return; }
        if (keyVal.size() >= capacity) {
            int oldest = freqKeys.get(minFreq).iterator().next(); freqKeys.get(minFreq).remove(oldest);
            if (freqKeys.get(minFreq).isEmpty()) freqKeys.remove(minFreq);
            keyVal.remove(oldest); keyFreq.remove(oldest);
        }
        keyVal.put(key, value); keyFreq.put(key, 1);
        freqKeys.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key); minFreq = 1;
    }
}

