class Solution {
    public static String validIPAddress(String queryIP) {
        if (queryIP.indexOf('.') >= 0) {
            String[] parts = queryIP.split("\\.");
            if (parts.length != 4) return "Neither";
            for (String part : parts) {
                if (part.isEmpty()) return "Neither";
                if (part.length() > 1 && part.charAt(0) == '0') return "Neither";
                try {
                    int val = Integer.parseInt(part);
                    if (val < 0 || val > 255) return "Neither";
                } catch (NumberFormatException e) {
                    return "Neither";
                }
            }
            return "IPv4";
        } else if (queryIP.indexOf(':') >= 0) {
            String[] parts = queryIP.split(":");
            if (parts.length != 8) return "Neither";
            for (String part : parts) {
                if (part.length() == 0 || part.length() > 4) return "Neither";
                if (!part.matches("[0-9a-fA-F]+")) return "Neither";
            }
            return "IPv6";
        } else {
            return "Neither";
        }
    }
}

