class Solution {
    public static List<String> findAllConcatenatedWordsInADict(String[] words) {
        Set<String> wordSet = new HashSet<>(Arrays.asList(words));
        List<String> result = new ArrayList<>();
        for (String word : words) {
            wordSet.remove(word);
            if (canBeConcatenated(word, wordSet, 0)) {
                result.add(word);
            }
            wordSet.add(word);
        }
        return result;
    }

    private static boolean canBeConcatenated(String word, Set<String> wordSet, int start) {
        if (start == word.length()) {
            return true;
        }
        for (int end = start + 1; end <= word.length(); end++) {
            String sub = word.substring(start, end);
            if (wordSet.contains(sub) && canBeConcatenated(word, wordSet, end)) {
                return true;
            }
        }
        return false;
    }
}

