public class Solution {
    public static boolean makesquare(int[] matchsticks) {
        int totalLength = 0;
        for (int i = 0; i < matchsticks.length; i++) {
            totalLength += matchsticks[i];
        }
        if (totalLength % 4 != 0) return false;
        int sideLength = totalLength / 4;
        int[] sides = new int[4];
        Integer[] sorted = new Integer[matchsticks.length];
        for (int i = 0; i < matchsticks.length; i++) {
            sorted[i] = matchsticks[i];
        }
        Arrays.sort(sorted, Collections.reverseOrder());
        for (int i = 0; i < matchsticks.length; i++) {
            matchsticks[i] = sorted[i];
        }
        return backtrack(0, matchsticks, sides, sideLength);
    }

    private static boolean backtrack(int index, int[] matchsticks, int[] sides, int sideLength) {
        if (index == matchsticks.length) {
            return sides[0] == sideLength && sides[1] == sideLength && sides[2] == sideLength && sides[3] == sideLength;
        }
        for (int i = 0; i < 4; i++) {
            if (sides[i] + matchsticks[index] > sideLength) continue;
            sides[i] += matchsticks[index];
            if (backtrack(index + 1, matchsticks, sides, sideLength)) return true;
            sides[i] -= matchsticks[index];
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public static boolean canIWin(int maxChoosableInteger, int desiredTotal) {
        int maxSum = maxChoosableInteger * (maxChoosableInteger + 1) / 2;
        if (maxSum < desiredTotal) return false;
        if (desiredTotal <= 0) return true;
        Map<Integer, Boolean> memo = new HashMap<>();
        return canWin(0, desiredTotal, maxChoosableInteger, memo);
    }

    private static boolean canWin(int used, int remaining, int maxChoosableInteger, Map<Integer, Boolean> memo) {
        if (memo.containsKey(used)) return memo.get(used);
        for (int i = 1; i <= maxChoosableInteger; i++) {
            int bit = 1 << (i - 1);
            if ((used & bit) == 0) {
                if (i >= remaining) {
                    memo.put(used, true);
                    return true;
                }
                if (!canWin(used | bit, remaining - i, maxChoosableInteger, memo)) {
                    memo.put(used, true);
                    return true;
                }
            }
        }
        memo.put(used, false);
        return false;
    }
}

