public class Solution {
    public static int magicalString(int n) {
        if (n <= 0) {
            return 0;
        }
        if (n <= 3) {
            return n == 1 ? 1 : (n == 2 ? 1 : 1);
        }
        int size = n * 2;
        int[] s = new int[size];
        s[0] = 1;
        s[1] = 2;
        s[2] = 2;
        int head = 2;
        int tail = 3;
        int cur = 1;
        while (tail < n) {
            int count = s[head];
            for (int i = 0; i < count && tail < n; i++) {
                s[tail++] = cur;
            }
            cur = 3 - cur;
            head++;
        }
        int ones = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == 1) {
                ones++;
            }
        }
        return ones;
    }
}

class Solution {
    public static String licenseKeyFormatting(String s, int k) {
        String sNoDashes = s.replace("-", "").toUpperCase();
        int firstGroupLength = sNoDashes.length() % k;
        StringBuilder result = new StringBuilder();
        if (firstGroupLength > 0) {
            result.append(sNoDashes.substring(0, firstGroupLength));
        }
        for (int i = firstGroupLength; i < sNoDashes.length(); i += k) {
            if (i > 0) result.append('-');
            result.append(sNoDashes.substring(i, i + k));
        }
        return result.toString();
    }
}

import java.math.BigInteger;

public class Solution {
    public static String smallestGoodBase(String n) {
        long num = Long.parseLong(n);
        int maxLen = (int) (Math.floor(Math.log(num) / Math.log(2)) + 1);
        BigInteger bigNum = new BigInteger(n);
        for (int len = maxLen; len >= 2; len--) {
            long left = 2;
            long right = num - 1;
            while (left <= right) {
                long mid = left + (right - left) / 2;
                BigInteger sum = BigInteger.ZERO;
                for (int i = 0; i < len; i++) {
                    sum = sum.multiply(BigInteger.valueOf(mid)).add(BigInteger.ONE);
                    if (sum.compareTo(bigNum) > 0) {
                        break;
                    }
                }
                int cmp = sum.compareTo(bigNum);
                if (cmp == 0) {
                    return Long.toString(mid);
                } else if (cmp < 0) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }
        return Long.toString(num - 1);
    }
}

