public class Solution {
    public static int findMinStep(String board, String hand) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(board, hand, memo);
    }

    private static int dfs(String board, String hand, Map<String, Integer> memo) {
        String key = board + "," + hand;
        if (memo.containsKey(key)) return memo.get(key);
        if (board.isEmpty()) return 0;
        int res = Integer.MAX_VALUE;
        for (int i = 0; i < hand.length(); i++) {
            String newHand = hand.substring(0, i) + hand.substring(i + 1);
            char c = hand.charAt(i);
            for (int j = 0; j <= board.length(); j++) {
                String newBoard = board.substring(0, j) + c + board.substring(j);
                newBoard = reduce(newBoard);
                if (newBoard.isEmpty()) {
                    memo.put(key, 1);
                    return 1;
                }
                if (!newHand.isEmpty()) {
                    int temp = dfs(newBoard, newHand, memo);
                    if (temp != -1) {
                        res = Math.min(res, 1 + temp);
                    }
                }
            }
        }
        if (res == Integer.MAX_VALUE) res = -1;
        memo.put(key, res);
        return res;
    }

    private static String reduce(String s) {
        boolean changed = true;
        while (changed) {
            changed = false;
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < s.length()) {
                int j = i;
                while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
                int cnt = j - i;
                if (cnt >= 3) {
                    changed = true;
                } else {
                    for (int k = 0; k < cnt; k++) sb.append(s.charAt(i));
                }
                i = j;
            }
            s = sb.toString();
        }
        return s;
    }
}

