class Solution {
    public static List<List<Integer>> findSubsequences(int[] nums) {
        Set<String> result = new LinkedHashSet<>();
        backtrack(nums, 0, new ArrayList<>(), result);
        List<List<Integer>> output = new ArrayList<>();
        for (String s : result) {
            List<Integer> list = new ArrayList<>();
            String trimmed = s.substring(1, s.length() - 1).trim();
            if (!trimmed.isEmpty()) {
                for (String part : trimmed.split(",")) {
                    list.add(Integer.parseInt(part.trim()));
                }
            }
            output.add(list);
        }
        return output;
    }

    private static void backtrack(int[] nums, int start, List<Integer> current, Set<String> result) {
        if (current.size() >= 2) {
            result.add(current.toString());
        }
        for (int i = start; i < nums.length; i++) {
            if (current.isEmpty() || nums[i] >= current.get(current.size() - 1)) {
                current.add(nums[i]);
                backtrack(nums, i + 1, current, result);
                current.remove(current.size() - 1);
            }
        }
    }
}

public class Solution {
    public static int findTargetSumWays(int[] nums, int target) {
        int[] count = new int[1];
        backtrack(nums, target, 0, 0, count);
        return count[0];
    }
    private static void backtrack(int[] nums, int target, int index, int sum, int[] count) {
        if (index == nums.length) {
            if (sum == target) count[0]++;
            return;
        }
        backtrack(nums, target, index + 1, sum + nums[index], count);
        backtrack(nums, target, index + 1, sum - nums[index], count);
    }
}

