public class Solution {
    public int[][] rects;
    public long[] weights;
    public long totalWeight;

    public Solution(int[][] rects) {
        this.rects = rects;
        this.weights = new long[rects.length];
        this.totalWeight = 0;
        for (int i = 0; i < rects.length; i++) {
            int[] rect = rects[i];
            long weight = (long) (rect[2] - rect[0] + 1) * (long) (rect[3] - rect[1] + 1);
            this.weights[i] = weight;
            this.totalWeight += weight;
        }
    }

    public int[] pick() {
        long rand = (long) (Math.random() * totalWeight);
        long cumulativeWeight = 0;
        for (int i = 0; i < rects.length; i++) {
            cumulativeWeight += weights[i];
            if (rand < cumulativeWeight) {
                int[] rect = rects[i];
                long pointsInRect = rand - (cumulativeWeight - weights[i]);
                long width = rect[2] - rect[0] + 1;
                int x = (int) (rect[0] + pointsInRect % width);
                int y = (int) (rect[1] + pointsInRect / width);
                return new int[]{x, y};
            }
        }
        return null;
    }
}

