class Solution {
    public static int[] findDiagonalOrder(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int[] result = new int[rows * cols];
        int index = 0;
        for (int k = 0; k < rows + cols - 1; k++) {
            if (k % 2 == 0) {
                int i = Math.min(k, rows - 1);
                int j = k - i;
                while (i >= 0 && j < cols) {
                    result[index++] = mat[i][j];
                    i--;
                    j++;
                }
            } else {
                int i = Math.max(0, k - cols + 1);
                int j = k - i;
                while (i < rows && j >= 0) {
                    result[index++] = mat[i][j];
                    i++;
                    j--;
                }
            }
        }
        return result;
    }
}

