class Solution {
    public List<Integer> findFrequentTreeSum(TreeNode root) {
        Map<Integer, Integer> sumFrequency = new HashMap<>();
        int[] maxFrequency = new int[1];
        List<Integer> result = new ArrayList<>();
        dfs(root, sumFrequency, maxFrequency, result);
        return result;
    }

    private int dfs(TreeNode node, Map<Integer, Integer> sumFrequency, int[] maxFrequency, List<Integer> result) {
        if (node == null) return 0;
        int sum = node.val + dfs(node.left, sumFrequency, maxFrequency, result) + dfs(node.right, sumFrequency, maxFrequency, result);
        int freq = sumFrequency.getOrDefault(sum, 0) + 1;
        sumFrequency.put(sum, freq);
        if (freq > maxFrequency[0]) {
            maxFrequency[0] = freq;
            result.clear();
            result.add(sum);
        } else if (freq == maxFrequency[0]) {
            result.add(sum);
        }
        return sum;
    }
}

