class Solution {
    public static int findPoisonedDuration(int[] timeSeries, int duration) {
        int totalDuration = 0;
        for (int i = 0; i < timeSeries.length; i++) {
            int nextTime = (i < timeSeries.length - 1) ? timeSeries[i + 1] : timeSeries[i] + duration;
            totalDuration += Math.min(duration, nextTime - timeSeries[i]);
        }
        return totalDuration;
    }
}

