class Solution {
    public static int findRotateSteps(String ring, String key) {
        int n = ring.length();
        int m = key.length();
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[m][n];
        for (int[] row : dp) {
            Arrays.fill(row, INF);
        }
        for (int j = 0; j < n; j++) {
            if (ring.charAt(j) == key.charAt(0)) {
                dp[0][j] = Math.min(j, n - j) + 1;
            }
        }
        for (int i = 1; i < m; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (ring.charAt(k) == key.charAt(i - 1)) {
                        int diff = Math.abs(j - k);
                        int step = Math.min(diff, n - diff);
                        dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + step + 1);
                    }
                }
            }
        }
        int minSteps = INF;
        for (int j = 0; j < n; j++) {
            if (ring.charAt(j) == key.charAt(m - 1)) {
                minSteps = Math.min(minSteps, dp[m - 1][j]);
            }
        }
        return minSteps;
    }
}

class Solution {
    public static int findMinMoves(int[] machines) {
        int totalDresses = 0;
        for (int v : machines) {
            totalDresses += v;
        }
        int n = machines.length;
        if (totalDresses % n != 0) return -1;
        int average = totalDresses / n;
        int maxMoves = 0;
        int currentImbalance = 0;
        for (int i = 0; i < n; i++) {
            currentImbalance += machines[i] - average;
            maxMoves = Math.max(maxMoves, Math.abs(currentImbalance));
            maxMoves = Math.max(maxMoves, machines[i] - average);
        }
        return maxMoves;
    }
}

