class Solution {
    public static int findLUSlength(String[] strs) {
        Map<String, Integer> count = new HashMap<>();
        for (String str : strs) {
            count.put(str, count.getOrDefault(str, 0) + 1);
        }
        List<String> uniqueStrs = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : count.entrySet()) {
            if (entry.getValue() == 1) {
                uniqueStrs.add(entry.getKey());
            }
        }
        if (uniqueStrs.isEmpty()) {
            return -1;
        }
        Collections.sort(uniqueStrs, (a, b) -> b.length() - a.length());
        for (String candidate : uniqueStrs) {
            boolean isSubsequence = false;
            for (String s : strs) {
                if (candidate.equals(s)) {
                    continue;
                }
                if (isSubsequenceOf(candidate, s)) {
                    isSubsequence = true;
                    break;
                }
            }
            if (!isSubsequence) {
                return candidate.length();
            }
        }
        return -1;
    }

    private static boolean isSubsequenceOf(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            if (a.charAt(i) == b.charAt(j)) {
                i++;
            }
            j++;
        }
        return i == a.length();
    }
}

