class Solution {
    public static String findLongestWord(String s, List<String> dictionary) {
        String longestWord = "";
        for (String word : dictionary) {
            if (isSubsequence(s, word)) {
                if (word.length() > longestWord.length() || (word.length() == longestWord.length() && word.compareTo(longestWord) < 0)) {
                    longestWord = word;
                }
            }
        }
        return longestWord;
    }

    private static boolean isSubsequence(String s, String word) {
        int sIndex = 0, wordIndex = 0;
        while (sIndex < s.length() && wordIndex < word.length()) {
            if (s.charAt(sIndex) == word.charAt(wordIndex)) {
                wordIndex++;
            }
            sIndex++;
        }
        return wordIndex == word.length();
    }
}

