class Solution {
    public static int getMinimumDifference(TreeNode root) {
        int[] minDiff = new int[]{Integer.MAX_VALUE};
        Integer[] prevVal = new Integer[]{null};
        inorder(root, minDiff, prevVal);
        return minDiff[0];
    }
    private static void inorder(TreeNode node, int[] minDiff, Integer[] prevVal) {
        if (node == null) {
            return;
        }
        inorder(node.left, minDiff, prevVal);
        if (prevVal[0] != null) {
            int diff = Math.abs(node.val - prevVal[0]);
            if (diff < minDiff[0]) {
                minDiff[0] = diff;
            }
        }
        prevVal[0] = node.val;
        inorder(node.right, minDiff, prevVal);
    }
}

class Solution {
    public static char[][] updateBoard(char[][] board, int[] click) {
        int rows = board.length;
        int cols = board[0].length;
        int row = click[0];
        int col = click[1];
        if (board[row][col] == 'M') {
            board[row][col] = 'X';
        } else {
            int count = 0;
            for (int i = -1; i <= 1; i++) {
                for (int j = -1; j <= 1; j++) {
                    int newRow = row + i;
                    int newCol = col + j;
                    if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && board[newRow][newCol] == 'M') {
                        count++;
                    }
                }
            }
            if (count == 0) {
                board[row][col] = 'B';
                dfs(board, row, col);
            } else {
                board[row][col] = (char) ('0' + count);
            }
        }
        return board;
    }

    private static void dfs(char[][] board, int row, int col) {
        int rows = board.length;
        int cols = board[0].length;
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                int newRow = row + i;
                int newCol = col + j;
                if (newRow < 0 || newRow >= rows || newCol < 0 || newCol >= cols) continue;
                if (board[newRow][newCol] != 'E') continue;
                int count = 0;
                for (int a = -1; a <= 1; a++) {
                    for (int b = -1; b <= 1; b++) {
                        int r = newRow + a;
                        int c = newCol + b;
                        if (r >= 0 && r < rows && c >= 0 && c < cols && board[r][c] == 'M') {
                            count++;
                        }
                    }
                }
                if (count == 0) {
                    board[newRow][newCol] = 'B';
                    dfs(board, newRow, newCol);
                } else {
                    board[newRow][newCol] = (char) ('0' + count);
                }
            }
        }
    }
}

