        StringBuilder result = new StringBuilder();
        for (int i = 0; i < s.length(); i += 2 * k) {
            int endFirst = Math.min(i + k, s.length());
            String reversed = new StringBuilder(s.substring(i, endFirst)).reverse().toString();
            int startSecond = endFirst;
            int endSecond = Math.min(i + 2 * k, s.length());
            result.append(reversed);
            result.append(s.substring(startSecond, endSecond));
        }
        return result.toString();
    }
}

