class Solution {
    public static int diameterOfBinaryTree(TreeNode root) {
        int[] maxDiameter = new int[1];
        depthFirstSearch(root, maxDiameter);
        return maxDiameter[0];
    }
    private static int depthFirstSearch(TreeNode node, int[] maxDiameter) {
        if (node == null) return 0;
        int leftDepth = depthFirstSearch(node.left, maxDiameter);
        int rightDepth = depthFirstSearch(node.right, maxDiameter);
        maxDiameter[0] = Math.max(maxDiameter[0], leftDepth + rightDepth);
        return Math.max(leftDepth, rightDepth) + 1;
    }
}

