class Solution {
    public static int[][] matrixReshape(int[][] mat, int r, int c) {
        int originalRows = mat.length;
        int originalColumns = mat[0].length;
        if (originalRows * originalColumns != r * c) {
            return mat;
        }
        int[][] reshapedMatrix = new int[r][];
        int index = 0;
        for (int i = 0; i < r; i++) {
            reshapedMatrix[i] = new int[c];
            for (int j = 0; j < c; j++) {
                int originalRow = index / originalColumns;
                int originalColumn = index % originalColumns;
                reshapedMatrix[i][j] = mat[originalRow][originalColumn];
                index++;
            }
        }
        return reshapedMatrix;
    }
}

