        for (int right = s1.length(); right < s2.length(); right++) {
            char leftChar = s2.charAt(left);
            int leftCount = s2Count.get(leftChar) - 1;
            s2Count.put(leftChar, leftCount);
            if (s1Count.containsKey(leftChar)) {
                int target = s1Count.get(leftChar);
                if (leftCount == target) matches++;
                else if (leftCount == target - 1) matches--;
            }
            char rightChar = s2.charAt(right);
            int rightCount = s2Count.getOrDefault(rightChar, 0) + 1;
            s2Count.put(rightChar, rightCount);
            if (s1Count.containsKey(rightChar)) {
                int target = s1Count.get(rightChar);
                if (rightCount == target) matches++;
                else if (rightCount == target + 1) matches--;
            }
            if (matches == s1Count.size()) return true;
            left++;
        }
        return matches == s1Count.size();
    }
}

