class Solution {
    public static int[][] outerTrees(int[][] points) {
        int n = points.length;
        if (n <= 1) {
            return points.clone();
        }
        Arrays.sort(points, (a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            return a[1] - b[1];
        });
        List<int[]> hull = new ArrayList<>();
        for (int[] p : points) {
            while (hull.size() >= 2 && cross(hull.get(hull.size() - 2), hull.get(hull.size() - 1), p) < 0) {
                hull.remove(hull.size() - 1);
            }
            hull.add(p);
        }
        int lowerSize = hull.size();
        for (int i = n - 2; i >= 0; i--) {
            int[] p = points[i];
            while (hull.size() > lowerSize && cross(hull.get(hull.size() - 2), hull.get(hull.size() - 1), p) < 0) {
                hull.remove(hull.size() - 1);
            }
            hull.add(p);
        }
        hull.remove(hull.size() - 1);
        Set<String> seen = new HashSet<>();
        List<int[]> uniq = new ArrayList<>();
        for (int[] p : hull) {
            String key = p[0] + "," + p[1];
            if (seen.add(key)) {
                uniq.add(p);
            }
        }
        if (uniq.size() == n) {
            Collections.reverse(uniq);
        }
        int[][] res = new int[uniq.size()][2];
        for (int i = 0; i < uniq.size(); i++) {
            res[i] = uniq.get(i);
        }
        return res;
    }

    private static long cross(int[] a, int[] b, int[] c) {
        return (long) (b[0] - a[0]) * (c[1] - a[1]) - (long) (b[1] - a[1]) * (c[0] - a[0]);
    }
}

