import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static boolean isValid(String code) {
        Deque<String> stack = new ArrayDeque<>();
        int i = 0;
        int n = code.length();
        while (i < n) {
            if (i + 9 <= n && code.startsWith("<![CDATA[", i)) {
                if (stack.isEmpty()) return false;
                int j = code.indexOf("]]>", i + 9);
                if (j == -1) return false;
                i = j + 3;
            } else if (i + 2 <= n && code.startsWith("</", i)) {
                int j = i + 2;
                while (j < n && code.charAt(j) != '>') j++;
                if (j == n) return false;
                String tag = code.substring(i + 2, j);
                if (tag.length() < 1 || tag.length() > 9) return false;
                for (char c : tag.toCharArray()) {
                    if (c < 'A' || c > 'Z') return false;
                }
                if (stack.isEmpty() || !stack.peekLast().equals(tag)) return false;
                stack.pollLast();
                i = j + 1;
                if (stack.isEmpty() && i != n) return false;
            } else if (i + 1 < n && code.charAt(i) == '<') {
                int j = i + 1;
                while (j < n && code.charAt(j) != '>') j++;
                if (j == n) return false;
                String tag = code.substring(i + 1, j);
                if (tag.length() < 1 || tag.length() > 9) return false;
                for (char c : tag.toCharArray()) {
                    if (c < 'A' || c > 'Z') return false;
                }
                stack.addLast(tag);
                i = j + 1;
            } else {
                if (stack.isEmpty()) return false;
                i++;
            }
        }
        return stack.isEmpty();
    }
}

import java.lang.Math;

class Solution {
    public static String fractionAddition(String expression) {
        long numerator = 0, denominator = 1;
        int i = 0;
        int len = expression.length();
        while (i < len) {
            int sign = 1;
            if (expression.charAt(i) == '-') {
                sign = -1;
                i++;
            } else if (expression.charAt(i) == '+') {
                i++;
            }
            long num = 0;
            while (i < len && expression.charAt(i) != '/') {
                num = num * 10 + (expression.charAt(i) - '0');
                i++;
            }
            i++; // skip '/'
            long den = 0;
            while (i < len && expression.charAt(i) != '+' && expression.charAt(i) != '-') {
                den = den * 10 + (expression.charAt(i) - '0');
                i++;
            }
            numerator = numerator * den + sign * num * denominator;
            denominator *= den;
            long g = gcd(Math.abs(numerator), denominator);
            numerator /= g;
            denominator /= g;
        }
        return numerator + "/" + denominator;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

