class Solution {
    public static int findIntegers(int n) {
        int[] dp = new int[31];
        dp[0] = 1;
        dp[1] = 2;
        for (int i = 2; i <= 30; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        int result = 0;
        int bitLength = 0;
        while (n > 0) {
            if ((n & 1) == 1) {
                result += dp[bitLength];
                if (n >= 2 && ((n >> 1) & 1) == 1) {
                    break;
                }
            }
            n >>= 1;
            bitLength++;
        }
        return result + 1;
    }
}

