class Solution {
    public static int leastInterval(char[] tasks, int n) {
        Map<Character, Integer> frequencyMap = new HashMap<>();
        for (char task : tasks) {
            frequencyMap.put(task, frequencyMap.getOrDefault(task, 0) + 1);
        }
        int maxFrequency = 0;
        int maxFrequencyCount = 0;
        for (int freq : frequencyMap.values()) {
            if (freq > maxFrequency) {
                maxFrequency = freq;
                maxFrequencyCount = 1;
            } else if (freq == maxFrequency) {
                maxFrequencyCount++;
            }
        }
        int intervals = (maxFrequency - 1) * (n + 1) + maxFrequencyCount;
        return Math.max(tasks.length, intervals);
    }
}

public class Solution {
    public static class MyCircularQueue {
        int capacity;
        int[] queue;
        int head, tail, size;

        public MyCircularQueue(int k) {
            capacity = k;
            queue = new int[k];
            head = 0;
            tail = -1;
            size = 0;
        }

        public boolean enQueue(int value) {
            if (size == capacity) return false;
            tail = (tail + 1) % capacity;
            queue[tail] = value;
            size++;
            return true;
        }

        public boolean deQueue() {
            if (size == 0) return false;
            head = (head + 1) % capacity;
            size--;
            return true;
        }

        public int Front() { return size == 0 ? -1 : queue[head]; }
        public int Rear() { return size == 0 ? -1 : queue[tail]; }
        public boolean isEmpty() { return size == 0; }
        public boolean isFull() { return size == capacity; }
    }
}

