    private static void traverse(TreeNode node, int currentDepth, int depth, int val) {
        if (node == null) return;
        if (currentDepth == depth - 1) {
            node.left = new TreeNode(val, node.left, null);
            node.right = new TreeNode(val, null, node.right);
        } else {
            traverse(node.left, currentDepth + 1, depth, val);
            traverse(node.right, currentDepth + 1, depth, val);
        }
    }
}

