class Solution {
    public static int kInversePairs(int n, int k) {
        final int MOD = 1_000_000_007;
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                long sum = 0;
                int maxP = Math.min(i - 1, j);
                for (int p = 0; p <= maxP; p++) {
                    sum = (sum + dp[i - 1][j - p]) % MOD;
                }
                dp[i][j] = (int) sum;
            }
        }
        return dp[n][k];
    }
}

