class Solution {
    public static int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        int n = price.size();
        int[] priceArr = new int[n];
        for (int i = 0; i < n; i++) {
            priceArr[i] = price.get(i);
        }
        int[] needsArr = new int[n];
        for (int i = 0; i < n; i++) {
            needsArr[i] = needs.get(i);
        }
        Map<String, Integer> memo = new HashMap<>();
        return dfs(needsArr, priceArr, special, memo);
    }

    private static int dfs(int[] needs, int[] price, List<List<Integer>> special, Map<String, Integer> memo) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < needs.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(needs[i]);
        }
        String key = sb.toString();
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int res = 0;
        for (int i = 0; i < needs.length; i++) {
            res += needs[i] * price[i];
        }

        for (List<Integer> spec : special) {
            int[] clone = needs.clone();
            boolean valid = true;
            for (int i = 0; i < needs.length; i++) {
                clone[i] -= spec.get(i);
                if (clone[i] < 0) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                int cost = spec.get(spec.size() - 1) + dfs(clone, price, special, memo);
                if (cost < res) {
                    res = cost;
                }
            }
        }

        memo.put(key, res);
        return res;
    }
}

