class Solution {
    public static int numDecodings(String s) {
        final long MOD = 1000000007L;
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            char cur = s.charAt(i - 1);
            if (cur != '*') {
                if (cur != '0') {
                    dp[i] += dp[i - 1];
                }
                if (i >= 2) {
                    char prev = s.charAt(i - 2);
                    if (prev == '1' || (prev == '2' && cur <= '6')) {
                        dp[i] += dp[i - 2];
                    }
                }
            } else {
                dp[i] += dp[i - 1] * 9;
                if (i >= 2) {
                    char prev = s.charAt(i - 2);
                    if (prev == '1') {
                        dp[i] += dp[i - 2] * 9;
                    } else if (prev == '2') {
                        dp[i] += dp[i - 2] * 6;
                    }
                }
            }
            dp[i] %= MOD;
        }
        return (int) dp[n];
    }
}

