class Solution {
    public static String solveEquation(String equation) {
        int leftX = 0, leftVal = 0, rightX = 0, rightVal = 0;
        boolean left = true;
        int num = 0, sign = 1;
        for (int i = 0; i < equation.length(); i++) {
            char c = equation.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == 'x') {
                if (num == 0) num = 1;
                if (left) leftX += sign * num; else rightX += sign * num;
                num = 0;
            } else if (c == '+' || c == '-') {
                if (num != 0) {
                    if (left) leftVal += sign * num; else rightVal += sign * num;
                    num = 0;
                }
                sign = c == '+' ? 1 : -1;
            } else if (c == '=') {
                left = false;
                sign = 1;
            }
        }
        if (num != 0) {
            if (left) leftVal += sign * num; else rightVal += sign * num;
        }
        int newX = leftX - rightX;
        int newVal = rightVal - leftVal;
        if (newX == 0 && newVal == 0) return "Infinite solutions";
        if (newX == 0) return "No solution";
        double result = (double) newVal / newX;
        if (result == (int) result) {
            return "x=" + (int) result;
        }
        return "x=" + result;
    }
}

