class Solution {
    public static String predictPartyVictory(String senate) {
        Deque<Integer> radiantQueue = new ArrayDeque<>();
        Deque<Integer> direQueue = new ArrayDeque<>();
        int n = senate.length();
        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') {
                radiantQueue.addLast(i);
            } else {
                direQueue.addLast(i);
            }
        }
        while (!radiantQueue.isEmpty() && !direQueue.isEmpty()) {
            int r = radiantQueue.peekFirst();
            int d = direQueue.peekFirst();
            if (r < d) {
                radiantQueue.addLast(r + n);
                radiantQueue.pollFirst();
                direQueue.pollFirst();
            } else {
                direQueue.addLast(d + n);
                direQueue.pollFirst();
                radiantQueue.pollFirst();
            }
        }
        return radiantQueue.isEmpty() ? "Dire" : "Radiant";
    }
}

public class Solution {
    public static int minSteps(int n) {
        int currentSteps = 0;
        int currentChars = 1;
        int buffer = 0;
        while (currentChars < n) {
            if (n % currentChars == 0) {
                buffer = currentChars;
                currentChars *= 2;
                currentSteps += 2;
            } else {
                currentChars += buffer;
                currentSteps += 1;
            }
        }
        return currentSteps;
    }
}

