class Solution {
    public static List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int width = (1 << height) - 1;
        List<List<String>> res = new ArrayList<>();
        for (int i = 0; i < height; i++) {
            res.add(new ArrayList<>(Collections.nCopies(width, "")));
        }
        printNode(root, 0, 0, width, res);
        return res;
    }

    private static int getHeight(TreeNode node) {
        if (node == null) return 0;
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private static void printNode(TreeNode node, int row, int left, int right, List<List<String>> res) {
        if (node == null) return;
        int mid = left + (right - left) / 2;
        res.get(row).set(mid, Integer.toString(node.val));
        printNode(node.left, row + 1, left, mid, res);
        printNode(node.right, row + 1, mid + 1, right, res);
    }
}

