class Solution {
    private static class Pair {
        TreeNode node;
        long index;
        Pair(TreeNode node, long index) {
            this.node = node;
            this.index = index;
        }
    }

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        int maxWidth = 0;
        Deque<Pair> queue = new ArrayDeque<>();
        queue.addLast(new Pair(root, 0));
        while (!queue.isEmpty()) {
            int size = queue.size();
            long leftmost = queue.peekFirst().index;
            long rightmost = queue.peekLast().index;
            maxWidth = Math.max(maxWidth, (int)(rightmost - leftmost + 1));
            for (int i = 0; i < size; i++) {
                Pair current = queue.pollFirst();
                TreeNode node = current.node;
                long index = current.index;
                if (node.left != null) queue.addLast(new Pair(node.left, 2 * index + 1));
                if (node.right != null) queue.addLast(new Pair(node.right, 2 * index + 2));
            }
        }
        return maxWidth;
    }
}

