class Solution {
    public static int strangePrinter(String s) {
        int n = s.length();
        if (n == 0) return 0;
        int[][] dp = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; j++) {
                dp[i][j] = dp[i][j - 1] + 1;
                for (int k = i; k < j; k++) {
                    if (s.charAt(k) == s.charAt(j)) {
                        int val = dp[i][k] + (k + 1 <= j - 1 ? dp[k + 1][j - 1] : 0);
                        if (val < dp[i][j]) dp[i][j] = val;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

