        for (int i = 0; i < words.length; i++) {
            int bitmask = 0;
            for (char c : words[i].toCharArray()) {
                bitmask |= 1 << (c - 'a');
            }
            bitmasks[i] = bitmask;
        }
        for (int i = 0; i < words.length; i++) {
            for (int j = i + 1; j < words.length; j++) {
                if ((bitmasks[i] & bitmasks[j]) == 0) {
                    int product = words[i].length() * words[j].length();
                    if (product > maxProduct) {
                        maxProduct = product;
                    }
                }
            }
        }
        return maxProduct;
    }
}

import java.util.*;

public class Solution {
    public static class MapSum {
        Map<String, Integer> map;
        Map<Character, Object> trie;

        public MapSum() {
            map = new HashMap<>();
            trie = new HashMap<>();
        }

        @SuppressWarnings("unchecked")
        public void insert(String key, int val) {
            int delta = val - map.getOrDefault(key, 0);
            map.put(key, val);
            Map<Character, Object> node = trie;
            for (char c : key.toCharArray()) {
                Map<Character, Object> child = (Map<Character, Object>) node.get(c);
                if (child == null) {
                    child = new HashMap<>();
                    node.put(c, child);
                }
                int prevSum = child.containsKey('#') ? (Integer) child.get('#') : 0;
                child.put('#', prevSum + delta);
                node = child;
            }
        }

        @SuppressWarnings("unchecked")
        public int sum(String prefix) {
            Map<Character, Object> node = trie;
            for (char c : prefix.toCharArray()) {
                Object next = node.get(c);
                if (next == null) return 0;
                node = (Map<Character, Object>) next;
            }
            return node.containsKey('#') ? (Integer) node.get('#') : 0;
        }
    }

    public static MapSum MapSum() {
        return new MapSum();
    }
}

import java.util.*;

class Solution {
    public static int cutOffTree(int[][] forest) {
        int m = forest.length, n = forest[0].length;
        List<int[]> trees = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (forest[i][j] > 1) {
                    trees.add(new int[]{forest[i][j], i, j});
                }
            }
        }
        trees.sort(Comparator.comparingInt(a -> a[0]));
        int[] start = new int[]{0, 0};
        int totalSteps = 0;
        for (int[] tree : trees) {
            int steps = bfs(forest, start, tree);
            if (steps == -1) return -1;
            totalSteps += steps;
            start = new int[]{tree[1], tree[2]};
        }
        return totalSteps;
    }

    private static int bfs(int[][] forest, int[] start, int[] target) {
        int m = forest.length, n = forest[0].length;
        boolean[][] visited = new boolean[m][n];
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{start[0], start[1], 0});
        visited[start[0]][start[1]] = true;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1], d = cur[2];
            if (r == target[1] && c == target[2]) return d;
            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && forest[nr][nc] != 0) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc, d + 1});
                }
            }
        }
        return -1;
    }
}

import java.util.Arrays;

class Solution {
    public static int findNumberOfLIS(int[] nums) {
        int n = nums.length;
        int[] lengths = new int[n];
        int[] counts = new int[n];
        Arrays.fill(lengths, 1);
        Arrays.fill(counts, 1);
        int maxLength = 1;
        int maxCount = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) {
                    if (lengths[j] + 1 > lengths[i]) {
                        lengths[i] = lengths[j] + 1;
                        counts[i] = counts[j];
                    } else if (lengths[j] + 1 == lengths[i]) {
                        counts[i] += counts[j];
                    }
                }
            }
            if (lengths[i] > maxLength) {
                maxLength = lengths[i];
                maxCount = counts[i];
            } else if (lengths[i] == maxLength) {
                maxCount += counts[i];
            }
        }
        return maxCount;
    }
}

