public class Solution {
    public static boolean validUtf8(int[] data) {
        int bytesLeft = 0;
        for (int i = 0; i < data.length; i++) {
            String binary = String.format("%8s", Integer.toBinaryString(data[i] & 0xFF)).replace(' ', '0');
            if (bytesLeft == 0) {
                if (binary.charAt(0) == '0') {
                    continue;
                } else if (binary.startsWith("110")) {
                    bytesLeft = 1;
                } else if (binary.startsWith("1110")) {
                    bytesLeft = 2;
                } else if (binary.startsWith("11110")) {
                    bytesLeft = 3;
                } else {
                    return false;
                }
            } else {
                if (!binary.startsWith("10")) {
                    return false;
                }
                bytesLeft--;
            }
        }
        return bytesLeft == 0;
    }
}

import java.util.*;

class Solution {
    public static int[] maxNumber(int[] nums1, int[] nums2, int k) {
        int[] result = new int[0];
        int start = Math.max(0, k - nums2.length);
        int end = Math.min(k, nums1.length);
        for (int i = start; i <= end; i++) {
            int[] subsequence1 = maxSubsequence(nums1, i);
            int[] subsequence2 = maxSubsequence(nums2, k - i);
            int[] merged = merge(subsequence1, subsequence2);
            if (greater(merged, 0, result, 0)) {
                result = merged;
            }
        }
        return result;
    }

    private static int[] maxSubsequence(int[] nums, int k) {
        int n = nums.length;
        int[] stack = new int[k];
        int top = -1;
        int drop = n - k;
        for (int num : nums) {
            while (top >= 0 && drop > 0 && stack[top] < num) {
                top--;
                drop--;
            }
            if (top + 1 < k) {
                stack[++top] = num;
            } else {
                drop--;
            }
        }
        return stack;
    }

    private static int[] merge(int[] nums1, int[] nums2) {
        int m = nums1.length, n = nums2.length;
        int[] merged = new int[m + n];
        int i = 0, j = 0, r = 0;
        while (i < m || j < n) {
            if (greater(nums1, i, nums2, j)) {
                merged[r++] = nums1[i++];
            } else {
                merged[r++] = nums2[j++];
            }
        }
        return merged;
    }

    private static boolean greater(int[] nums1, int i, int[] nums2, int j) {
        int m = nums1.length, n = nums2.length;
        while (i < m && j < n) {
            if (nums1[i] != nums2[j]) {
                return nums1[i] > nums2[j];
            }
            i++;
            j++;
        }
        return (m - i) > (n - j);
    }
}

import java.util.*;

public class Solution {
    public static int shortestPathLength(int[][] graph) {
        int n = graph.length;
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        int[][] visited = new int[n][1 << n];
        int INF = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            Arrays.fill(visited[i], INF);
        }
        for (int i = 0; i < n; i++) {
            queue.offer(new int[]{i, 1 << i, 0});
            visited[i][1 << i] = 0;
        }
        int allVisited = (1 << n) - 1;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int node = cur[0];
            int state = cur[1];
            int pathLength = cur[2];
            if (state == allVisited) {
                return pathLength;
            }
            for (int neighbor : graph[node]) {
                int newState = state | (1 << neighbor);
                if (visited[neighbor][newState] > pathLength + 1) {
                    visited[neighbor][newState] = pathLength + 1;
                    queue.offer(new int[]{neighbor, newState, pathLength + 1});
                }
            }
        }
        return -1;
    }
}

