class Solution {
    public static boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : hand) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }
        List<Integer> keys = new ArrayList<>(countMap.keySet());
        Collections.sort(keys);
        for (int key : keys) {
            int currentCount = countMap.get(key);
            if (currentCount > 0) {
                for (int i = 0; i < groupSize; i++) {
                    int nextNum = key + i;
                    Integer nextCount = countMap.get(nextNum);
                    if (nextCount == null || nextCount < currentCount) return false;
                    countMap.put(nextNum, nextCount - currentCount);
                }
            }
        }
        return true;
    }
}

import java.util.Stack;

class Solution {
    public static int scoreOfParentheses(String s) {
        Stack<Integer> stack = new Stack<>();
        int currentScore = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                stack.push(currentScore);
                currentScore = 0;
            } else {
                currentScore = stack.pop() + Math.max(2 * currentScore, 1);
            }
        }
        return currentScore;
    }
}

