class Solution {
    public static int kSimilarity(String s1, String s2) {
        List<String> queue = new ArrayList<>();
        queue.add(s1);
        Set<String> visited = new HashSet<>();
        visited.add(s1);
        int step = 0;
        while (true) {
            List<String> nextQueue = new ArrayList<>();
            for (String s : queue) {
                if (s.equals(s2)) return step;
                int len = s.length();
                for (int i = 0; i < len; i++) {
                    if (s.charAt(i) != s2.charAt(i)) {
                        for (int j = i + 1; j < len; j++) {
                            if (s.charAt(j) == s2.charAt(i)) {
                                StringBuilder sb = new StringBuilder(s);
                                char ci = sb.charAt(i);
                                sb.setCharAt(i, sb.charAt(j));
                                sb.setCharAt(j, ci);
                                String nextS = sb.toString();
                                if (!visited.contains(nextS)) {
                                    nextQueue.add(nextS);
                                    visited.add(nextS);
                                }
                            }
                        }
                        break;
                    }
                }
            }
            queue = nextQueue;
            step++;
        }
    }
}

import java.util.*;

class Solution {
    public static int shortestPathAllKeys(String[] grid) {
        int m = grid.length;
        int n = grid[0].length();
        Set<Character> allKeys = new HashSet<>();
        int startX = -1, startY = -1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i].charAt(j);
                if (c == '@') {
                    startX = i;
                    startY = j;
                }
                if (c >= 'a' && c <= 'f') {
                    allKeys.add(c);
                }
            }
        }
        int allKeysSize = allKeys.size();
        class State {
            int x, y;
            Set<Character> keys;
            State(int x, int y, Set<Character> keys) {
                this.x = x;
                this.y = y;
                this.keys = keys;
            }
        }
        Queue<State> queue = new LinkedList<>();
        queue.offer(new State(startX, startY, new HashSet<>()));
        Set<String> visited = new HashSet<>();
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                State cur = queue.poll();
                if (cur.keys.size() == allKeysSize) {
                    return steps;
                }
                for (int[] d : directions) {
                    int nx = cur.x + d[0];
                    int ny = cur.y + d[1];
                    if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                    char cell = grid[nx].charAt(ny);
                    if (cell == '#') continue;
                    Set<Character> newKeys = new HashSet<>(cur.keys);
                    if (cell >= 'a' && cell <= 'f') {
                        newKeys.add(cell);
                    }
                    if (cell >= 'A' && cell <= 'F' && !newKeys.contains(Character.toLowerCase(cell))) {
                        continue;
                    }
                    List<Character> keyList = new ArrayList<>(newKeys);
                    Collections.sort(keyList);
                    StringBuilder sb = new StringBuilder();
                    for (char k : keyList) sb.append(k);
                    String stateStr = nx + "," + ny + "," + sb.toString();
                    if (!visited.contains(stateStr)) {
                        visited.add(stateStr);
                        queue.offer(new State(nx, ny, newKeys));
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

