class Solution {
    public static class ExamRoom {
        int n;
        List<Integer> seats;

        public ExamRoom(int n) {
            this.n = n;
            this.seats = new ArrayList<>();
        }

        public int seat() {
            if (seats.isEmpty()) { seats.add(0); return 0; }
            int maxDist = seats.get(0), seatPos = 0;
            for (int i = 0; i < seats.size() - 1; i++) {
                int d = (seats.get(i + 1) - seats.get(i)) / 2;
                if (d > maxDist) { maxDist = d; seatPos = seats.get(i) + d; }
            }
            if (n - 1 - seats.get(seats.size() - 1) > maxDist) seatPos = n - 1;
            int idx = Collections.binarySearch(seats, seatPos);
            if (idx < 0) idx = -idx - 1;
            seats.add(idx, seatPos);
            return seatPos;
        }

        public void leave(int p) {
            seats.remove(Integer.valueOf(p));
        }
    }
}

import java.util.*;

class Solution {
    public static double mincostToHireWorkers(int[] quality, int[] wage, int k) {
        int n = quality.length;
        double[][] workers = new double[n][2];
        for (int i = 0; i < n; i++) {
            workers[i][0] = quality[i];
            workers[i][1] = (double) wage[i] / quality[i];
        }
        Arrays.sort(workers, (a, b) -> Double.compare(a[1], b[1]));
        double minCost = Double.POSITIVE_INFINITY;
        long totalQuality = 0;
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i < n; i++) {
            int q = (int) workers[i][0];
            double ratio = workers[i][1];
            totalQuality += q;
            maxHeap.add(q);
            if (maxHeap.size() > k) {
                int removed = maxHeap.poll();
                totalQuality -= removed;
            }
            if (maxHeap.size() == k) {
                double cost = totalQuality * ratio;
                if (cost < minCost) {
                    minCost = cost;
                }
            }
        }
        return minCost;
    }
}

