    public TreeNode increasingBST(TreeNode root) {
        TreeNode head = new TreeNode();
        curr = head;
        inOrder(root);
        return head.right;
    }
    private void inOrder(TreeNode node) {
        if (node == null) return;
        inOrder(node.left);
        curr.right = new TreeNode(node.val);
        curr = curr.right;
        inOrder(node.right);
    }
