class Solution {
    public static class RLEIterator {
        int[] encoding;
        int index;
        public RLEIterator(int[] encoding) {
            this.encoding = encoding;
            this.index = 0;
        }
        public int next(int num) {
            while (index < encoding.length) {
                int remaining = encoding[index];
                if (num <= remaining) {
                    encoding[index] -= num;
                    return encoding[index + 1];
                }
                num -= remaining;
                index += 2;
            }
            return -1;
        }
    }
}

