class Solution {
    public static int dieSimulator(int n, int[] rollMax) {
        final int MOD = 1_000_000_007;
        Map<String, Integer> memo = new HashMap<>();
        return dp(0, 0, 0, n, rollMax, MOD, memo);
    }

    private static int dp(int roll, int last, int count, int n, int[] rollMax, int MOD, Map<String, Integer> memo) {
        if (roll == n) return 1;
        String key = roll + "," + last + "," + count;
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        long res = 0;
        for (int i = 1; i <= 6; i++) {
            if (i == last && count == rollMax[i - 1]) continue;
            int nextCount = (i == last) ? count + 1 : 1;
            res = (res + dp(roll + 1, i, nextCount, n, rollMax, MOD, memo)) % MOD;
        }
        int result = (int) res;
        memo.put(key, result);
        return result;
    }
}

import java.util.*;

class Solution {
    public static int[] threeEqualParts(int[] arr) {
        int totalOnes = 0;
        for (int bit : arr) {
            totalOnes += bit;
        }
        if (totalOnes % 3 != 0) {
            return new int[]{-1, -1};
        }
        if (totalOnes == 0) {
            return new int[]{0, arr.length - 1};
        }
        int onesPerPart = totalOnes / 3;
        int first = -1, second = -1, third = -1;
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == 1) {
                count++;
                if (count == 1) {
                    first = i;
                } else if (count == onesPerPart + 1) {
                    second = i;
                } else if (count == 2 * onesPerPart + 1) {
                    third = i;
                }
            }
        }
        int len = arr.length - third;
        for (int i = 0; i < len; i++) {
            if (arr[first + i] != arr[second + i] || arr[first + i] != arr[third + i]) {
                return new int[]{-1, -1};
            }
        }
        int iIdx = first + len - 1;
        int jIdx = second + len;
        return new int[]{iIdx, jIdx};
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxEqualFreq(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();
        Map<Integer, Integer> freqMap = new HashMap<>();
        int maxFreq = 0;
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int prev = countMap.getOrDefault(num, 0);
            if (prev > 0) {
                int prevCnt = freqMap.get(prev);
                if (prevCnt == 1) {
                    freqMap.remove(prev);
                } else {
                    freqMap.put(prev, prevCnt - 1);
                }
            }
            int cur = prev + 1;
            countMap.put(num, cur);
            freqMap.put(cur, freqMap.getOrDefault(cur, 0) + 1);
            if (cur > maxFreq) {
                maxFreq = cur;
            }
            int total = i + 1;
            int distinct = countMap.size();
            boolean valid = false;
            if (maxFreq == 1) {
                valid = true;
            } else {
                int cntMax = freqMap.getOrDefault(maxFreq, 0);
                if (cntMax == 1) {
                    int rest = total - maxFreq;
                    if (rest == (maxFreq - 1) * (distinct - 1)) {
                        valid = true;
                    }
                }
                int cntOne = freqMap.getOrDefault(1, 0);
                if (cntOne == 1) {
                    int rest = total - 1;
                    if (rest == maxFreq * (distinct - 1)) {
                        valid = true;
                    }
                }
            }
            if (valid) {
                maxLen = total;
            }
        }
        return maxLen;
    }
}

