class Solution {
    public static int minNumberOfSemesters(int n, int[][] relations, int k) {
        int[] prereq = new int[n];
        for (int[] rel : relations) {
            int prev = rel[0] - 1;
            int next = rel[1] - 1;
            prereq[next] |= 1 << prev;
        }
        int totalMask = (1 << n) - 1;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int mask = 0; mask <= totalMask; mask++) {
            if (dp[mask] == Integer.MAX_VALUE) continue;
            int available = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0 && (prereq[i] & mask) == prereq[i]) {
                    available |= 1 << i;
                }
            }
            if (available == 0) continue;
            int sub = available;
            while (sub > 0) {
                if (Integer.bitCount(sub) <= k) {
                    int nextMask = mask | sub;
                    dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
                }
                sub = (sub - 1) & available;
            }
            if (Integer.bitCount(available) <= k) {
                int nextMask = mask | available;
                dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
            }
        }
        return dp[totalMask];
    }
}

