class Solution {
    public static long numSubmat(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int[] height = new int[n];
        long total = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                height[j] = mat[i][j] == 1 ? height[j] + 1 : 0;
            }
            Deque<int[]> stack = new ArrayDeque<>();
            long rowSum = 0;
            for (int j = 0; j < n; j++) {
                int cnt = 1;
                while (!stack.isEmpty() && stack.peekLast()[0] >= height[j]) {
                    int[] top = stack.removeLast();
                    cnt += top[1];
                    rowSum -= (long) top[0] * top[1];
                }
                stack.addLast(new int[]{height[j], cnt});
                rowSum += (long) height[j] * cnt;
                total += rowSum;
            }
        }
        return total;
    }
}

