class Solution {
    public static int closestToTarget(int[] arr, int target) {
        long best = Long.MAX_VALUE;
        List<int[]> cur = new ArrayList<>();
        for (int i = 0; i < arr.length; i++) {
            List<int[]> nxt = new ArrayList<>();
            nxt.add(new int[]{arr[i], i});
            for (int[] p : cur) {
                int newVal = p[0] & arr[i];
                if (newVal == nxt.get(nxt.size() - 1)[0]) {
                    continue;
                }
                nxt.add(new int[]{newVal, p[1]});
            }
            for (int[] p : nxt) {
                long diff = Math.abs((long) p[0] - target);
                if (diff < best) {
                    best = diff;
                    if (best == 0) {
                        return 0;
                    }
                }
            }
            cur = nxt;
        }
        return (int) best;
    }
}

