class Solution {
    private static class Pair {
        int node;
        double prob;
        Pair(int node, double prob) {
            this.node = node;
            this.prob = prob;
        }
    }

    public static double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<Pair>> graph = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < edges.length; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            double p = succProb[i];
            graph.get(a).add(new Pair(b, p));
            graph.get(b).add(new Pair(a, p));
        }

        double[] prob = new double[n];
        prob[start] = 1.0;

        PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Double.compare(b.prob, a.prob));
        pq.offer(new Pair(start, 1.0));

        while (!pq.isEmpty()) {
            Pair cur = pq.poll();
            int node = cur.node;
            double currProb = cur.prob;
            if (node == end) return currProb;
            if (currProb < prob[node]) continue;
            for (Pair edge : graph.get(node)) {
                int neighbor = edge.node;
                double newProb = currProb * edge.prob;
                if (newProb > prob[neighbor]) {
                    prob[neighbor] = newProb;
                    pq.offer(new Pair(neighbor, newProb));
                }
            }
        }
        return 0.0;
    }
}

