class Solution {
    public static int maximumScore(int a, int b, int c) {
        int score = 0;
        while ((a > 0 && b > 0) || (a > 0 && c > 0) || (b > 0 && c > 0)) {
            int max = Math.max(a, Math.max(b, c));
            int min = Math.min(a, Math.min(b, c));
            int mid = a + b + c - max - min;
            if (max == a) {
                if (mid == b) {
                    a--;
                    b--;
                } else {
                    a--;
                    c--;
                }
            } else if (max == b) {
                if (mid == a) {
                    a--;
                    b--;
                } else {
                    b--;
                    c--;
                }
            } else {
                if (mid == a) {
                    a--;
                    c--;
                } else {
                    b--;
                    c--;
                }
            }
            score++;
        }
        return score;
    }
}

