class Solution {
    public static int maxValue(int[][] events, int k) {
        int n = events.length;
        Arrays.sort(events, (a, b) -> Integer.compare(a[1], b[1]));
        int[] starts = new int[n];
        int[] ends = new int[n];
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = events[i][0];
            ends[i] = events[i][1];
            values[i] = events[i][2];
        }
        int[] prev = new int[n];
        for (int i = 0; i < n; i++) {
            int lo = 0, hi = i - 1, ans = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] < starts[i]) {
                    ans = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            prev[i] = ans;
        }
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                int notTake = dp[i - 1][j];
                int take = values[i - 1];
                int p = prev[i - 1];
                if (p != -1) {
                    take += dp[p + 1][j - 1];
                }
                dp[i][j] = Math.max(notTake, take);
            }
        }
        return dp[n][k];
    }
}

