class Solution {
    public static long maximumScore(int[] nums, int[] multipliers) {
        int n = nums.length;
        int m = multipliers.length;
        long[][] dp = new long[m + 1][m + 1];
        for (int i = m - 1; i >= 0; i--) {
            for (int left = 0; left <= i; left++) {
                int right = n - 1 - (i - left);
                long takeLeft = (long) nums[left] * multipliers[i] + dp[i + 1][left + 1];
                long takeRight = (long) nums[right] * multipliers[i] + dp[i + 1][left];
                dp[i][left] = Math.max(takeLeft, takeRight);
            }
        }
        return dp[0][0];
    }
}

