class Solution {
    public static int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] first = null, second = null;
        for (int i = 0; i < n; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            if (parent[v] != 0) {
                first = new int[]{parent[v], v};
                second = new int[]{u, v};
                edges[i] = null;
                break;
            }
            parent[v] = u;
        }
        if (first == null) {
            UnionFind uf = new UnionFind(n + 1);
            for (int i = 0; i < n; i++) {
                if (edges[i] != null) {
                    int[] e = edges[i];
                    if (!uf.union(e[0], e[1])) {
                        return e;
                    }
                }
            }
        } else {
            UnionFind uf = new UnionFind(n + 1);
            for (int i = 0; i < n; i++) {
                if (edges[i] != null) {
                    int[] e = edges[i];
                    if (!uf.union(e[0], e[1])) {
                        return first;
                    }
                }
            }
            return second;
        }
        return null;
    }

    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        boolean union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return false;
            }
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
            return true;
        }
    }
}

