class Solution {
    public static double knightProbability(int n, int k, int row, int column) {
        int[][] directions = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};
        Map<String, Double> memo = new HashMap<>();
        return dfs(row, column, k, n, directions, memo);
    }

    private static double dfs(int r, int c, int k, int n, int[][] directions, Map<String, Double> memo) {
        if (k == 0) {
            return (r >= 0 && r < n && c >= 0 && c < n) ? 1.0 : 0.0;
        }
        String key = r + "," + c + "," + k;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        double prob = 0.0;
        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                prob += dfs(nr, nc, k - 1, n, directions, memo);
            }
        }
        prob /= 8.0;
        memo.put(key, prob);
        return prob;
    }
}

