class Solution {
    public static int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        int m = n - k + 1;
        long[] sums = new long[m];
        for (int i = 0; i <= n - k; i++) {
            sums[i] = prefix[i + k] - prefix[i];
        }
        long maxSum = Long.MIN_VALUE;
        int[] result = new int[3];
        for (int i = 0; i <= n - k; i++) {
            for (int j = i + k; j <= n - k; j++) {
                for (int l = j + k; l <= n - k; l++) {
                    long total = sums[i] + sums[j] + sums[l];
                    if (total > maxSum) {
                        maxSum = total;
                        result[0] = i;
                        result[1] = j;
                        result[2] = l;
                    } else if (total == maxSum) {
                        if (i < result[0] || (i == result[0] && j < result[1]) || (i == result[0] && j == result[1] && l < result[2])) {
                            result[0] = i;
                            result[1] = j;
                            result[2] = l;
                        }
                    }
                }
            }
        }
        return result;
    }
}

