class Solution {
    public static int minStickers(String[] stickers, String target) {
        int n = target.length();
        int fullMask = (1 << n) - 1;
        int INF = Integer.MAX_VALUE / 2;
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int i = 1; i <= (1 << n); i++) {
            dp.put(i, INF);
        }
        for (int mask = 0; mask < (1 << n); mask++) {
            int cur = dp.get(mask);
            if (cur == INF) continue;
            for (String sticker : stickers) {
                int newMask = mask;
                for (char ch : sticker.toCharArray()) {
                    for (int i = 0; i < n; i++) {
                        if (target.charAt(i) == ch && ((newMask >> i) & 1) == 0) {
                            newMask |= (1 << i);
                            break;
                        }
                    }
                }
                int prev = dp.getOrDefault(newMask, INF);
                if (prev > cur + 1) {
                    dp.put(newMask, cur + 1);
                }
            }
        }
        int result = dp.get(fullMask);
        return result == INF ? -1 : result;
    }
}

public class Solution {
    public static boolean hasAlternatingBits(int n) {
        int previousBit = n & 1;
        n >>= 1;
        while (n > 0) {
            int currentBit = n & 1;
            if (currentBit == previousBit) {
                return false;
            }
            previousBit = currentBit;
            n >>= 1;
        }
        return true;
    }
}

