class Solution {
    public static int findShortestSubArray(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        Map<Integer, Integer> first = new HashMap<>();
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            count.put(num, count.getOrDefault(num, 0) + 1);
            if (!first.containsKey(num)) {
                first.put(num, i);
            }
            last.put(num, i);
        }
        int degree = 0;
        for (int val : count.values()) {
            if (val > degree) {
                degree = val;
            }
        }
        int minLen = Integer.MAX_VALUE;
        for (int num : count.keySet()) {
            if (count.get(num) == degree) {
                int len = last.get(num) - first.get(num) + 1;
                if (len < minLen) {
                    minLen = len;
                }
            }
        }
        return minLen;
    }
}

import java.util.*;

class Solution {
    public static boolean canPartitionKSubsets(int[] nums, int k) {
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }
        if (totalSum % k != 0) return false;
        int targetSum = totalSum / k;
        boolean[] visited = new boolean[nums.length];
        return backtrack(0, 0, 0, nums, k, targetSum, visited);
    }

    private static boolean backtrack(int index, int count, int currentSum, int[] nums, int k, int targetSum, boolean[] visited) {
        if (count == k) return true;
        if (currentSum > targetSum) return false;
        if (currentSum == targetSum) return backtrack(0, count + 1, 0, nums, k, targetSum, visited);
        for (int i = index; i < nums.length; i++) {
            if (visited[i]) continue;
            visited[i] = true;
            if (backtrack(i + 1, count, currentSum + nums[i], nums, k, targetSum, visited)) return true;
            visited[i] = false;
        }
        return false;
    }
}

