class Solution {
    public static List<Integer> fallingSquares(int[][] positions) {
        int[] heights = new int[positions.length];
        int maxHeight = 0;
        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < positions.length; i++) {
            int left = positions[i][0];
            int sideLength = positions[i][1];
            int right = left + sideLength;
            int currHeight = 0;
            for (int j = 0; j < i; j++) {
                if (positions[j][0] < right && left < positions[j][0] + positions[j][1]) {
                    currHeight = Math.max(currHeight, heights[j]);
                }
            }
            heights[i] = currHeight + sideLength;
            maxHeight = Math.max(maxHeight, heights[i]);
            ans.add(maxHeight);
        }
        return ans;
    }
}

