public class Solution {
    public static int pickRandom(int n, int[] blacklist) {
        int availableNumbers = n - blacklist.length;
        HashMap<Integer, Integer> mapping = new HashMap<>();
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (contains(blacklist, i)) {
                continue;
            }
            if (j < blacklist.length && i > blacklist[j]) {
                mapping.put(blacklist[j], i);
                j++;
            }
        }
        int randomIndex = (int) (Math.random() * availableNumbers);
        for (int i = 0; i < n; i++) {
            if (!contains(blacklist, i)) {
                if (randomIndex == 0) {
                    return i;
                }
                randomIndex--;
            }
        }
        return -1;
    }

    private static boolean contains(int[] arr, int val) {
        for (int v : arr) {
            if (v == val) {
                return true;
            }
        }
        return false;
    }
}

