class RangeModule {
    private List<int[]> ranges = new ArrayList<>();

    public void addRange(int left, int right) {
        int i = 0;
        while (i < ranges.size() && ranges.get(i)[1] < left) i++;
        int start = i;
        int j = i;
        while (j < ranges.size() && ranges.get(j)[0] <= right) j++;
        int[] merged = new int[]{left, right};
        while (i < j) {
            merged[0] = Math.min(merged[0], ranges.get(i)[0]);
            merged[1] = Math.max(merged[1], ranges.get(i)[1]);
            i++;
        }
        List<int[]> newRanges = new ArrayList<>();
        newRanges.addAll(ranges.subList(0, start));
        newRanges.add(merged);
        newRanges.addAll(ranges.subList(j, ranges.size()));
        ranges = newRanges;
    }

    public boolean queryRange(int left, int right) {
        int i = 0;
        while (i < ranges.size() && ranges.get(i)[1] < left) i++;
        return i < ranges.size() && ranges.get(i)[0] <= left && right <= ranges.get(i)[1];
    }

    public void removeRange(int left, int right) {
        int i = 0;
        while (i < ranges.size() && ranges.get(i)[1] < left) i++;
        int start = i;
        int j = i;
        while (j < ranges.size() && ranges.get(j)[0] < right) j++;
        List<int[]> newRanges = new ArrayList<>();
        newRanges.addAll(ranges.subList(0, start));
        if (i < j) {
            if (ranges.get(i)[0] < left) newRanges.add(new int[]{ranges.get(i)[0], left});
            if (ranges.get(i)[1] > right) newRanges.add(new int[]{right, ranges.get(i)[1]});
            i++;
        }
        while (i < j) {
            if (ranges.get(i)[1] > right) newRanges.add(new int[]{right, ranges.get(i)[1]});
            i++;
        }
        newRanges.addAll(ranges.subList(j, ranges.size()));
        ranges = newRanges;
    }
}

