class Solution {
    public static int kthSmallestPairDistance(int[] nums, int k) {
        int n = nums.length;
        int total = n * (n - 1) / 2;
        int[] distances = new int[total];
        int idx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                distances[idx++] = Math.abs(nums[i] - nums[j]);
            }
        }
        Arrays.sort(distances);
        return distances[k - 1];
    }
}

