class Solution {
    public static List<String> removeComments(List<String> source) {
        List<String> result = new ArrayList<>();
        boolean blockComment = false;
        StringBuilder currentLine = new StringBuilder();
        for (String line : source) {
            int i = 0;
            while (i < line.length()) {
                if (blockComment) {
                    if (i + 1 < line.length() && line.substring(i, i + 2).equals("*/")) {
                        i += 2;
                        blockComment = false;
                    } else {
                        i++;
                    }
                } else {
                    if (i + 1 < line.length() && line.substring(i, i + 2).equals("//")) {
                        break;
                    } else if (i + 1 < line.length() && line.substring(i, i + 2).equals("/*")) {
                        i += 2;
                        blockComment = true;
                    } else {
                        currentLine.append(line.charAt(i));
                        i++;
                    }
                }
            }
            if (currentLine.length() > 0 && !blockComment) {
                result.add(currentLine.toString());
                currentLine.setLength(0);
            }
        }
        return result;
    }
}

