class Solution {
    public static List<List<String>> accountsMerge(List<List<String>> accounts) {
        Map<String, String> parent = new HashMap<>();
        Map<String, String> emailMap = new HashMap<>();
        for (int i = 0; i < accounts.size(); i++) {
            List<String> account = accounts.get(i);
            for (int j = 1; j < account.size(); j++) {
                String email = account.get(j);
                parent.put(email, email);
                emailMap.put(email, account.get(0));
            }
        }
        for (int i = 0; i < accounts.size(); i++) {
            List<String> account = accounts.get(i);
            for (int j = 2; j < account.size(); j++) {
                union(account.get(j), account.get(j - 1), parent);
            }
        }
        Map<String, List<String>> result = new HashMap<>();
        for (String email : parent.keySet()) {
            String root = find(email, parent);
            result.computeIfAbsent(root, k -> new ArrayList<>()).add(email);
        }
        List<List<String>> finalResult = new ArrayList<>();
        for (Map.Entry<String, List<String>> entry : result.entrySet()) {
            List<String> emails = entry.getValue();
            Collections.sort(emails);
            List<String> merged = new ArrayList<>();
            merged.add(emailMap.get(entry.getKey()));
            merged.addAll(emails);
            finalResult.add(merged);
        }
        return finalResult;
    }

    private static String find(String email, Map<String, String> parent) {
        if (!parent.get(email).equals(email)) {
            parent.put(email, find(parent.get(email), parent));
        }
        return parent.get(email);
    }

    private static void union(String email1, String email2, Map<String, String> parent) {
        String root1 = find(email1, parent);
        String root2 = find(email2, parent);
        if (!root1.equals(root2)) {
            parent.put(root1, root2);
        }
    }
}

class Solution {
    public static int pivotIndex(int[] nums) {
        int totalSum = 0;
        for (int i = 0; i < nums.length; i++) {
            totalSum += nums[i];
        }
        int leftSum = 0;
        for (int i = 0; i < nums.length; i++) {
            if (leftSum == totalSum - leftSum - nums[i]) {
                return i;
            }
            leftSum += nums[i];
        }
        return -1;
    }
}

import java.util.*;

class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; }
}

class Solution {
    public ListNode[] splitListToParts(ListNode head, int k) {
        int length = 0;
        ListNode temp = head;
        while (temp != null) {
            length++;
            temp = temp.next;
        }
        ListNode[] result = new ListNode[k];
        int size = length / k;
        int remainder = length % k;
        ListNode start = head;
        for (int i = 0; i < k; i++) {
            result[i] = start;
            int partSize = size + (i < remainder ? 1 : 0);
            for (int j = 0; j < partSize - 1; j++) {
                if (start != null) {
                    start = start.next;
                }
            }
            if (start != null) {
                ListNode next = start.next;
                start.next = null;
                start = next;
            }
        }
        return result;
    }
}

