class Solution {
    public static String countOfAtoms(String formula) {
        List<Map<String, Integer>> stack = new ArrayList<>();
        stack.add(new HashMap<>());
        int i = 0;
        int n = formula.length();
        while (i < n) {
            char ch = formula.charAt(i);
            if (ch == '(') {
                stack.add(new HashMap<>());
                i++;
            } else if (ch == ')') {
                Map<String, Integer> current = stack.remove(stack.size() - 1);
                i++;
                int multiplier = 0;
                while (i < n && Character.isDigit(formula.charAt(i))) {
                    multiplier = multiplier * 10 + (formula.charAt(i) - '0');
                    i++;
                }
                if (multiplier == 0) multiplier = 1;
                Map<String, Integer> prev = stack.get(stack.size() - 1);
                for (Map.Entry<String, Integer> entry : current.entrySet()) {
                    String name = entry.getKey();
                    int count = entry.getValue() * multiplier;
                    prev.put(name, prev.getOrDefault(name, 0) + count);
                }
            } else {
                StringBuilder nameBuilder = new StringBuilder();
                nameBuilder.append(ch);
                i++;
                while (i < n) {
                    char c = formula.charAt(i);
                    if (c >= 'a' && c <= 'z') {
                        nameBuilder.append(c);
                        i++;
                    } else {
                        break;
                    }
                }
                String name = nameBuilder.toString();
                int multiplier = 0;
                while (i < n && Character.isDigit(formula.charAt(i))) {
                    multiplier = multiplier * 10 + (formula.charAt(i) - '0');
                    i++;
                }
                if (multiplier == 0) multiplier = 1;
                Map<String, Integer> cur = stack.get(stack.size() - 1);
                cur.put(name, cur.getOrDefault(name, 0) + multiplier);
            }
        }
        Map<String, Integer> finalMap = stack.get(0);
        List<String> parts = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : finalMap.entrySet()) {
            int cnt = entry.getValue();
            parts.add(entry.getKey() + (cnt > 1 ? cnt : ""));
        }
        Collections.sort(parts);
        return String.join("", parts);
    }
}

