import java.util.*;

class Solution {
    public static int countPalindromicSubsequences(String s) {
        final int MOD = 1_000_000_007;
        int n = s.length();
        if (n == 0) return 0;
        int[][] dp = new int[n][n];
        int[][] next = new int[n][26];
        int[][] prev = new int[n][26];

        int[] nextPos = new int[26];
        Arrays.fill(nextPos, -1);
        for (int i = n - 1; i >= 0; i--) {
            nextPos[s.charAt(i) - 'a'] = i;
            for (int c = 0; c < 26; c++) {
                next[i][c] = nextPos[c];
            }
        }

        int[] prevPos = new int[26];
        Arrays.fill(prevPos, -1);
        for (int i = 0; i < n; i++) {
            prevPos[s.charAt(i) - 'a'] = i;
            for (int c = 0; c < 26; c++) {
                prev[i][c] = prevPos[c];
            }
        }

        for (int i = 0; i < n; i++) dp[i][i] = 1;

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) != s.charAt(j)) {
                    dp[i][j] = ((dp[i + 1][j] + dp[i][j - 1]) % MOD - dp[i + 1][j - 1] + MOD) % MOD;
                } else {
                    int c = s.charAt(i) - 'a';
                    int ni = (i + 1 < n) ? next[i + 1][c] : -1;
                    int pj = (j - 1 >= 0) ? prev[j - 1][c] : -1;
                    if (ni == -1 || ni > j - 1) {
                        dp[i][j] = (int) ((2L * dp[i + 1][j - 1] + 2) % MOD);
                    } else if (ni == pj) {
                        dp[i][j] = (int) ((2L * dp[i + 1][j - 1] + 1) % MOD);
                    } else {
                        int inner = (ni + 1 <= pj - 1) ? dp[ni + 1][pj - 1] : 0;
                        dp[i][j] = (int) ((2L * dp[i + 1][j - 1] - inner) % MOD);
                        if (dp[i][j] < 0) dp[i][j] += MOD;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

