class Solution {
    // Persist events across calls (bug: original static method re-initialized
    // `events` on every call, so it never accumulated bookings and always returned 1)
    private List<int[]> events = new ArrayList<>();

    public int book(int startTime, int endTime) {
        events.add(new int[]{startTime, endTime});
        List<int[]> sorted = new ArrayList<>(events);
        Collections.sort(sorted, new Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                return Integer.compare(a[0], b[0]);
            }
        });
        int maxKBooking = 0;
        List<Integer> endTimes = new ArrayList<>();
        for (int i = 0; i < sorted.size(); i++) {
            List<Integer> filtered = new ArrayList<>();
            for (Integer et : endTimes) {
                if (et > sorted.get(i)[0]) filtered.add(et);
            }
            endTimes = filtered;
            endTimes.add(sorted.get(i)[1]);
            maxKBooking = Math.max(maxKBooking, endTimes.size());
        }
        return maxKBooking;
    }
}

