class Solution {
    public static int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int targetColor = image[sr][sc];
        if (targetColor == color) return image;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        dfs(image, sr, sc, targetColor, color, directions);
        return image;
    }

    private static void dfs(int[][] image, int row, int col, int targetColor, int newColor, int[][] directions) {
        if (row < 0 || row >= image.length || col < 0 || col >= image[0].length || image[row][col] != targetColor) return;
        image[row][col] = newColor;
        for (int i = 0; i < directions.length; i++) {
            int newRow = row + directions[i][0];
            int newCol = col + directions[i][1];
            dfs(image, newRow, newCol, targetColor, newColor, directions);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int[] asteroidCollision(int[] asteroids) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int a : asteroids) {
            boolean alive = true;
            while (alive && a < 0 && !stack.isEmpty() && stack.peekLast() > 0) {
                int top = stack.peekLast();
                if (top < -a) {
                    stack.removeLast();
                } else if (top == -a) {
                    stack.removeLast();
                    alive = false;
                } else {
                    alive = false;
                }
            }
            if (alive) {
                stack.addLast(a);
            }
        }
        int[] result = new int[stack.size()];
        int i = 0;
        for (int v : stack) {
            result[i++] = v;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static int evaluate(String expression) {
        int[] idx = new int[]{0};
        Deque<Map<String, Integer>> env = new ArrayDeque<>();
        env.push(new HashMap<>());
        return eval(expression, idx, env);
    }

    private static int eval(String s, int[] idx, Deque<Map<String, Integer>> env) {
        skipSpaces(s, idx);
        if (s.charAt(idx[0]) != '(') {
            String token = readWord(s, idx);
            return getValue(token, env);
        }
        idx[0]++; // skip '('
        String op = readWord(s, idx);
        int result;
        if (op.equals("add")) {
            int a = eval(s, idx, env);
            int b = eval(s, idx, env);
            result = a + b;
        } else if (op.equals("mult")) {
            int a = eval(s, idx, env);
            int b = eval(s, idx, env);
            result = a * b;
        } else { // let
            env.push(new HashMap<>());
            while (true) {
                skipSpaces(s, idx);
                if (s.charAt(idx[0]) == ')') {
                    // no final expression (should not happen)
                    result = 0;
                    break;
                }
                if (s.charAt(idx[0]) == '(') {
                    result = eval(s, idx, env);
                    break;
                }
                String token = readWord(s, idx);
                skipSpaces(s, idx);
                if (s.charAt(idx[0]) == ')') {
                    result = getValue(token, env);
                    break;
                }
                int val = eval(s, idx, env);
                env.peek().put(token, val);
            }
            skipSpaces(s, idx);
            if (idx[0] < s.length() && s.charAt(idx[0]) == ')') {
                idx[0]++; // consume ')'
            }
            env.pop();
            return result;
        }
        skipSpaces(s, idx);
        if (idx[0] < s.length() && s.charAt(idx[0]) == ')') {
            idx[0]++; // consume ')'
        }
        return result;
    }

    private static int getValue(String token, Deque<Map<String, Integer>> env) {
        if (Character.isDigit(token.charAt(0)) || token.charAt(0) == '-') {
            return Integer.parseInt(token);
        }
        for (Map<String, Integer> scope : env) {
            if (scope.containsKey(token)) {
                return scope.get(token);
            }
        }
        return 0;
    }

    private static String readWord(String s, int[] idx) {
        int start = idx[0];
        while (idx[0] < s.length() && s.charAt(idx[0]) != ' ' && s.charAt(idx[0]) != ')') {
            idx[0]++;
        }
        return s.substring(start, idx[0]);
    }

    private static void skipSpaces(String s, int[] idx) {
        while (idx[0] < s.length() && s.charAt(idx[0]) == ' ') {
            idx[0]++;
        }
    }
}

class Solution {
    public static int monotoneIncreasingDigits(int n) {
        String numStr = Integer.toString(n);
        int result = -1;
        for (int i = numStr.length() - 1; i >= 0; i--) {
            if (i < numStr.length() - 1 && numStr.charAt(i) > numStr.charAt(i + 1)) {
                int digit = numStr.charAt(i) - '0';
                numStr = numStr.substring(0, i) + (digit - 1) + "9".repeat(numStr.length() - i - 1);
                break;
            }
        }
        if (!numStr.equals(Integer.toString(n))) {
            result = monotoneIncreasingDigits(Integer.parseInt(numStr));
        } else {
            result = n;
        }
        return result;
    }
}

