public class Solution {
    public static int deleteAndEarn(int[] nums) {
        int maxVal = 0;
        for (int num : nums) {
            if (num > maxVal) {
                maxVal = num;
            }
        }
        int[] count = new int[maxVal + 1];
        for (int num : nums) {
            count[num]++;
        }
        int[] dp = new int[maxVal + 1];
        if (maxVal >= 1) {
            dp[1] = count[1];
        }
        for (int i = 2; i <= maxVal; i++) {
            dp[i] = Math.max(dp[i - 1], dp[i - 2] + count[i] * i);
        }
        return dp[maxVal];
    }
}

import java.util.Arrays;

class Solution {
    public static int cherryPickup(int[][] grid) {
        int n = grid.length;
        int[][][][] memo = new int[n][n][n][n];
        for (int[][][] a : memo) {
            for (int[][] b : a) {
                for (int[] c : b) {
                    Arrays.fill(c, Integer.MIN_VALUE);
                }
            }
        }
        int result = dfs(grid, 0, 0, 0, 0, memo);
        return Math.max(0, result);
    }

    private static int dfs(int[][] grid, int r1, int c1, int r2, int c2, int[][][][] memo) {
        int n = grid.length;
        if (r1 >= n || c1 >= n || r2 >= n || c2 >= n) return Integer.MIN_VALUE / 2;
        if (grid[r1][c1] == -1 || grid[r2][c2] == -1) return Integer.MIN_VALUE / 2;
        if (r1 == n - 1 && c1 == n - 1 && r2 == n - 1 && c2 == n - 1) {
            return grid[r1][c1];
        }
        if (memo[r1][c1][r2][c2] != Integer.MIN_VALUE) return memo[r1][c1][r2][c2];
        int cherries = grid[r1][c1];
        if (r1 != r2 || c1 != c2) cherries += grid[r2][c2];
        int maxNext = Math.max(
                Math.max(dfs(grid, r1 + 1, c1, r2 + 1, c2, memo), dfs(grid, r1 + 1, c1, r2, c2 + 1, memo)),
                Math.max(dfs(grid, r1, c1 + 1, r2 + 1, c2, memo), dfs(grid, r1, c1 + 1, r2, c2 + 1, memo))
        );
        int total = cherries + maxNext;
        memo[r1][c1][r2][c2] = total;
        return total;
    }
}

public class Solution {
    public static char nextGreatestLetter(char[] letters, char target) {
        int left = 0, right = letters.length - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (letters[mid] > target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return letters[left % letters.length];
    }
}

import java.util.*;

class Solution {
    public static int networkDelayTime(int[][] times, int n, int k) {
        List<int[]>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : times) {
            int u = edge[0];
            int v = edge[1];
            int w = edge[2];
            graph[u].add(new int[]{v, w});
        }
        int[] distance = new int[n + 1];
        Arrays.fill(distance, Integer.MAX_VALUE);
        distance[k] = 0;
        List<int[]> pq = new ArrayList<>();
        pq.add(new int[]{k, 0});
        while (!pq.isEmpty()) {
            int[] cur = pq.remove(0);
            int node = cur[0];
            int dist = cur[1];
            if (dist > distance[node]) continue;
            for (int[] neighborInfo : graph[node]) {
                int neighbor = neighborInfo[0];
                int weight = neighborInfo[1];
                int newDist = dist + weight;
                if (newDist < distance[neighbor]) {
                    distance[neighbor] = newDist;
                    pq.add(new int[]{neighbor, newDist});
                    pq.sort(Comparator.comparingInt(a -> a[1]));
                }
            }
        }
        int maxDist = 0;
        for (int i = 1; i <= n; i++) {
            if (distance[i] == Integer.MAX_VALUE) return -1;
            maxDist = Math.max(maxDist, distance[i]);
        }
        return maxDist;
    }
}

