import java.util.*;

class Solution {
    public static int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;
        Queue<Node> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.add(new Node("0000", 0));
        visited.add("0000");
        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            String lock = cur.lock;
            int turns = cur.turns;
            for (int i = 0; i < 4; i++) {
                for (int j = -1; j <= 1; j += 2) {
                    int digit = lock.charAt(i) - '0';
                    int newDigit = (digit + j + 10) % 10;
                    String nextLock = lock.substring(0, i) + newDigit + lock.substring(i + 1);
                    if (nextLock.equals(target)) return turns + 1;
                    if (!dead.contains(nextLock) && !visited.contains(nextLock)) {
                        queue.add(new Node(nextLock, turns + 1));
                        visited.add(nextLock);
                    }
                }
            }
        }
        return -1;
    }

    private static class Node {
        String lock;
        int turns;
        Node(String lock, int turns) {
            this.lock = lock;
            this.turns = turns;
        }
    }
}

