class Solution {
    public static String crackSafe(int n, int k) {
        StringBuilder startBuilder = new StringBuilder();
        for (int i = 0; i < n - 1; i++) {
            startBuilder.append('0');
        }
        String start = startBuilder.toString();
        Set<String> visited = new HashSet<>();
        StringBuilder result = new StringBuilder();
        dfs(start, visited, result, n, k);
        result.append(start);
        return result.toString();
    }

    private static void dfs(String node, Set<String> visited, StringBuilder result, int n, int k) {
        for (int i = 0; i < k; i++) {
            String edge = node + i;
            if (!visited.contains(edge)) {
                visited.add(edge);
                dfs(edge.substring(1), visited, result, n, k);
                result.append(i);
            }
        }
    }
}

