class Solution {
    private static class Region {
        List<int[]> cells;
        Set<Integer> frontier;
        int walls;
        Region(List<int[]> cells, Set<Integer> frontier, int walls) {
            this.cells = cells;
            this.frontier = frontier;
            this.walls = walls;
        }
    }

    private static void dfs(int x, int y, int[][] grid, boolean[][] visited,
                            List<int[]> cells, Set<Integer> frontier, int[] wallCnt,
                            int m, int n) {
        visited[x][y] = true;
        cells.add(new int[]{x, y});
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                if (grid[nx][ny] == 1 && !visited[nx][ny]) {
                    dfs(nx, ny, grid, visited, cells, frontier, wallCnt, m, n);
                } else if (grid[nx][ny] == 0) {
                    wallCnt[0]++;
                    frontier.add(nx * n + ny);
                }
            }
        }
    }

    public static int containVirus(int[][] isInfected) {
        int m = isInfected.length;
        int n = isInfected[0].length;
        int wallsUsed = 0;
        while (true) {
            List<Region> regions = new ArrayList<>();
            boolean[][] visited = new boolean[m][n];
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (isInfected[i][j] == 1 && !visited[i][j]) {
                        List<int[]> cells = new ArrayList<>();
                        Set<Integer> frontier = new HashSet<>();
                        int[] wallCnt = new int[1];
                        dfs(i, j, isInfected, visited, cells, frontier, wallCnt, m, n);
                        regions.add(new Region(cells, frontier, wallCnt[0]));
                    }
                }
            }
            if (regions.isEmpty()) break;
            int maxIdx = -1;
            int maxFrontier = 0;
            for (int i = 0; i < regions.size(); i++) {
                int size = regions.get(i).frontier.size();
                if (size > maxFrontier) {
                    maxFrontier = size;
                    maxIdx = i;
                }
            }
            if (maxFrontier == 0) break;
            Region quarantine = regions.get(maxIdx);
            wallsUsed += quarantine.walls;
            for (int[] cell : quarantine.cells) {
                isInfected[cell[0]][cell[1]] = -1;
            }
            for (int i = 0; i < regions.size(); i++) {
                if (i == maxIdx) continue;
                for (int pos : regions.get(i).frontier) {
                    int x = pos / n;
                    int y = pos % n;
                    if (isInfected[x][y] == 0) {
                        isInfected[x][y] = 1;
                    }
                }
            }
        }
        return wallsUsed;
    }
}

