class Solution {
    public static int findSecondMinimumValue(TreeNode root) {
        int min = root.val;
        long[] secondMin = new long[]{Long.MAX_VALUE};
        dfs(root, min, secondMin);
        return secondMin[0] == Long.MAX_VALUE ? -1 : (int) secondMin[0];
    }

    private static void dfs(TreeNode node, int min, long[] secondMin) {
        if (node.val > min && node.val < secondMin[0]) {
            secondMin[0] = node.val;
        }
        if (node.left != null) {
            dfs(node.left, min, secondMin);
        }
        if (node.right != null) {
            dfs(node.right, min, secondMin);
        }
    }
}

