class Solution {
    public static boolean judgePoint24(double[] cards) {
        List<Double> initial = new ArrayList<>();
        for (double v : cards) {
            initial.add(v);
        }
        return dfs(initial);
    }

    private static double calculate(double a, double b, char op) {
        if (op == '+') return a + b;
        if (op == '-') return a - b;
        if (op == '*') return a * b;
        if (op == '/') return a / b;
        return 0;
    }

    private static boolean dfs(List<Double> nums) {
        if (nums.size() == 1) {
            return Math.abs(nums.get(0) - 24) < 0.001;
        }
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (char op : new char[]{'+', '-', '*', '/'}) {
                    double a = nums.get(i);
                    double b = nums.get(j);
                    double result = calculate(a, b, op);
                    List<Double> next = new ArrayList<>();
                    next.add(result);
                    for (int k = 0; k < n; k++) {
                        if (k != i && k != j) {
                            next.add(nums.get(k));
                        }
                    }
                    if (dfs(next)) return true;
                }
            }
        }
        return false;
    }
}

