import java.math.BigInteger;

class Solution {
    public static String findClosestPalindrome(String n) {
        int len = n.length();
        List<String> candidates = new ArrayList<>();
        String edgeHigh = "1" + "0".repeat(len - 1) + "1";
        candidates.add(edgeHigh);
        String edgeLow = "9".repeat(len - 1);
        if (edgeLow.isEmpty()) edgeLow = "0";
        candidates.add(edgeLow);
        int prefixLen = (len + 1) / 2;
        String prefixStr = n.substring(0, prefixLen);
        BigInteger prefix = new BigInteger(prefixStr);
        for (int delta = -1; delta <= 1; delta++) {
            BigInteger newPrefix = prefix.add(BigInteger.valueOf(delta));
            if (newPrefix.compareTo(BigInteger.ZERO) < 0) continue;
            String newPrefixStr = newPrefix.toString();
            StringBuilder sb = new StringBuilder(newPrefixStr);
            String revPart = new StringBuilder(newPrefixStr.substring(0, len / 2)).reverse().toString();
            sb.append(revPart);
            candidates.add(sb.toString());
        }
        BigInteger original = new BigInteger(n);
        String best = "";
        BigInteger bestDiff = null;
        for (String cand : candidates) {
            if (cand.equals(n) || cand.isEmpty()) continue;
            BigInteger candVal = new BigInteger(cand);
            BigInteger diff = candVal.subtract(original).abs();
            if (bestDiff == null || diff.compareTo(bestDiff) < 0 ||
                (diff.compareTo(bestDiff) == 0 && candVal.compareTo(new BigInteger(best)) < 0)) {
                bestDiff = diff;
                best = cand;
            }
        }
        return best;
    }
}

