        Arrays.sort(intervals, (a, b) -> {
            if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
            return Integer.compare(b[0], a[0]);
        });
        int a = -1, b = -1, count = 0;
        for (int[] interval : intervals) {
            if (interval[0] > b) {
                a = interval[1] - 1;
                b = interval[1];
                count += 2;
            } else if (interval[0] > a) {
                a = b;
                b = interval[1];
                count += 1;
            }
        }
