class Solution {
    public static int orderOfLargestPlusSign(int n, int[][] mines) {
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(grid[i], 1);
        }
        for (int[] mine : mines) {
            grid[mine[0]][mine[1]] = 0;
        }
        int maxOrder = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int order = 1;
                    while (i - order >= 0 && i + order < n && j - order >= 0 && j + order < n &&
                           grid[i - order][j] == 1 && grid[i + order][j] == 1 &&
                           grid[i][j - order] == 1 && grid[i][j + order] == 1) {
                        order++;
                    }
                    maxOrder = Math.max(maxOrder, order);
                }
            }
        }
        return maxOrder;
    }
}

