class Solution {
    private static class Pair {
        char c;
        int freq;
        Pair(char c, int freq) {
            this.c = c;
            this.freq = freq;
        }
    }

    public static String reorganizeString(String s) {
        Map<Character, Integer> frequencyMap = new HashMap<>();
        for (char ch : s.toCharArray()) {
            frequencyMap.put(ch, frequencyMap.getOrDefault(ch, 0) + 1);
        }

        List<Pair> maxHeap = new ArrayList<>();
        for (Map.Entry<Character, Integer> entry : frequencyMap.entrySet()) {
            maxHeap.add(new Pair(entry.getKey(), entry.getValue()));
        }
        maxHeap.sort((a, b) -> b.freq - a.freq);

        StringBuilder result = new StringBuilder();

        while (!maxHeap.isEmpty()) {
            if (result.length() > 0 && result.charAt(result.length() - 1) == maxHeap.get(0).c) {
                if (maxHeap.size() == 1) {
                    return "";
                }
                Pair secondChar = maxHeap.get(1);
                result.append(secondChar.c);
                secondChar.freq--;
                if (secondChar.freq == 0) {
                    maxHeap.remove(1);
                }
                Pair firstChar = maxHeap.remove(0);
                maxHeap.add(firstChar);
            } else {
                Pair topChar = maxHeap.remove(0);
                result.append(topChar.c);
                topChar.freq--;
                if (topChar.freq > 0) {
                    maxHeap.add(topChar);
                }
            }
            maxHeap.sort((a, b) -> b.freq - a.freq);
        }

        return result.toString();
    }
}

