class Solution {
    public static boolean pyramidTransition(String bottom, String[] allowed) {
        Map<String, List<Character>> allowedMap = new HashMap<>();
        for (String pattern : allowed) {
            String key = pattern.substring(0, 2);
            allowedMap.computeIfAbsent(key, k -> new ArrayList<>()).add(pattern.charAt(2));
        }
        Map<String, Boolean> memo = new HashMap<>();
        return dfs(bottom, allowedMap, memo);
    }

    private static boolean dfs(String bottom, Map<String, List<Character>> allowedMap, Map<String, Boolean> memo) {
        if (bottom.length() == 1) return true;
        if (memo.containsKey(bottom)) return memo.get(bottom);
        List<String> next = new ArrayList<>();
        for (int i = 0; i < bottom.length() - 1; i++) {
            String pair = bottom.substring(i, i + 2);
            List<Character> chars = allowedMap.get(pair);
            if (chars == null) {
                memo.put(bottom, false);
                return false;
            }
            if (next.isEmpty()) {
                for (char c : chars) {
                    next.add(String.valueOf(c));
                }
            } else {
                List<String> temp = new ArrayList<>();
                for (String n : next) {
                    for (char c : chars) {
                        temp.add(n + c);
                    }
                }
                next = temp;
            }
        }
        for (String n : next) {
            if (dfs(n, allowedMap, memo)) {
                memo.put(bottom, true);
                return true;
            }
        }
        memo.put(bottom, false);
        return false;
    }
}

