import java.util.*;

class Solution {
    public static List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        Map<String, Integer> evalMap = new HashMap<>();
        for (int i = 0; i < evalvars.length; i++) {
            evalMap.put(evalvars[i], evalints[i]);
        }
        Parser parser = new Parser(expression, evalMap);
        Map<String, Integer> poly = parser.parseExpression();
        List<String> result = new ArrayList<>();
        List<Term> terms = new ArrayList<>();
        for (Map.Entry<String, Integer> e : poly.entrySet()) {
            int coeff = e.getValue();
            if (coeff == 0) continue;
            String key = e.getKey();
            List<String> vars = key.isEmpty() ? new ArrayList<>() : Arrays.asList(key.split("\\*"));
            terms.add(new Term(coeff, vars));
        }
        terms.sort((a, b) -> {
            if (a.vars.size() != b.vars.size()) return b.vars.size() - a.vars.size();
            for (int i = 0; i < a.vars.size(); i++) {
                int cmp = a.vars.get(i).compareTo(b.vars.get(i));
                if (cmp != 0) return cmp;
            }
            return 0;
        });
        for (Term t : terms) {
            if (t.vars.isEmpty()) {
                result.add(String.valueOf(t.coeff));
            } else {
                result.add(t.coeff + "*" + String.join("*", t.vars));
            }
        }
        return result;
    }

    private static class Term {
        int coeff;
        List<String> vars;
        Term(int c, List<String> v) {
            coeff = c;
            vars = v;
        }
    }

    private static class Parser {
        private final List<String> tokens;
        private int pos = 0;
        private final Map<String, Integer> evalMap;

        Parser(String expr, Map<String, Integer> evalMap) {
            this.tokens = tokenize(expr);
            this.evalMap = evalMap;
        }

        private List<String> tokenize(String s) {
            List<String> list = new ArrayList<>();
            int n = s.length();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                if (c == ' ') continue;
                if (c == '+' || c == '-' || c == '*' || c == '(' || c == ')') {
                    if (sb.length() > 0) {
                        list.add(sb.toString());
                        sb.setLength(0);
                    }
                    list.add(String.valueOf(c));
                } else {
                    sb.append(c);
                }
            }
            if (sb.length() > 0) list.add(sb.toString());
            return list;
        }

        Map<String, Integer> parseExpression() {
            Map<String, Integer> left = parseTerm();
            while (pos < tokens.size() && (tokens.get(pos).equals("+") || tokens.get(pos).equals("-"))) {
                String op = tokens.get(pos++);
                Map<String, Integer> right = parseTerm();
                if (op.equals("+")) {
                    left = add(left, right);
                } else {
                    left = subtract(left, right);
                }
            }
            return left;
        }

        Map<String, Integer> parseTerm() {
            Map<String, Integer> left = parseFactor();
            while (pos < tokens.size() && tokens.get(pos).equals("*")) {
                pos++;
                Map<String, Integer> right = parseFactor();
                left = multiply(left, right);
            }
            return left;
        }

        Map<String, Integer> parseFactor() {
            String token = tokens.get(pos++);
            if (token.equals("(")) {
                Map<String, Integer> inside = parseExpression();
                pos++; // skip ')'
                return inside;
            } else if (Character.isDigit(token.charAt(0))) {
                int val = Integer.parseInt(token);
                Map<String, Integer> map = new HashMap<>();
                map.put("", val);
                return map;
            } else { // variable
                if (evalMap.containsKey(token)) {
                    int val = evalMap.get(token);
                    Map<String, Integer> map = new HashMap<>();
                    map.put("", val);
                    return map;
                } else {
                    Map<String, Integer> map = new HashMap<>();
                    map.put(token, 1);
                    return map;
                }
            }
        }

        private Map<String, Integer> add(Map<String, Integer> a, Map<String, Integer> b) {
            Map<String, Integer> res = new HashMap<>(a);
            for (Map.Entry<String, Integer> e : b.entrySet()) {
                res.merge(e.getKey(), e.getValue(), Integer::sum);
            }
            return res;
        }

        private Map<String, Integer> subtract(Map<String, Integer> a, Map<String, Integer> b) {
            Map<String, Integer> res = new HashMap<>(a);
            for (Map.Entry<String, Integer> e : b.entrySet()) {
                res.merge(e.getKey(), -e.getValue(), Integer::sum);
            }
            return res;
        }

        private Map<String, Integer> multiply(Map<String, Integer> a, Map<String, Integer> b) {
            Map<String, Integer> res = new HashMap<>();
            for (Map.Entry<String, Integer> e1 : a.entrySet()) {
                for (Map.Entry<String, Integer> e2 : b.entrySet()) {
                    int coeff = e1.getValue() * e2.getValue();
                    String key = combineKeys(e1.getKey(), e2.getKey());
                    res.merge(key, coeff, Integer::sum);
                }
            }
            return res;
        }

        private String combineKeys(String k1, String k2) {
            if (k1.isEmpty()) return k2;
            if (k2.isEmpty()) return k1;
            String[] arr1 = k1.split("\\*");
            String[] arr2 = k2.split("\\*");
            List<String> list = new ArrayList<>(Arrays.asList(arr1));
            list.addAll(Arrays.asList(arr2));
            Collections.sort(list);
            return String.join("*", list);
        }
    }
}

