class Solution {
    public static boolean canTransform(String start, String result) {
        int startPointer = 0, resultPointer = 0;
        while (startPointer < start.length() && resultPointer < result.length()) {
            while (startPointer < start.length() && start.charAt(startPointer) == 'X') startPointer++;
            while (resultPointer < result.length() && result.charAt(resultPointer) == 'X') resultPointer++;
            if (startPointer == start.length() && resultPointer == result.length()) return true;
            if (startPointer == start.length() || resultPointer == result.length()) return false;
            if (start.charAt(startPointer) != result.charAt(resultPointer)) return false;
            if ((start.charAt(startPointer) == 'L' && startPointer < resultPointer) ||
                (start.charAt(startPointer) == 'R' && startPointer > resultPointer)) return false;
            startPointer++;
            resultPointer++;
        }
        return true;
    }
}

