class Solution {
    public static boolean isIdealPermutation(int[] nums) {
        int n = nums.length;
        int globalInversions = 0;
        int localInversions = 0;
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] > nums[i + 1]) {
                localInversions++;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums[i] > nums[j]) {
                    globalInversions++;
                }
            }
        }
        return globalInversions == localInversions;
    }
}

