public class Solution {
    public static int slidingPuzzle(int[][] board) {
        int[][] target = {{1, 2, 3}, {4, 5, 0}};
        int[][] directions = {{1, 3}, {0, 2, 4}, {1, 5}, {0, 4}, {1, 3, 5}, {2, 4}};
        Queue<Node> queue = new LinkedList<>();
        queue.offer(new Node(board, 0));
        Set<String> visited = new HashSet<>();
        visited.add(boardToString(board));
        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            int[][] state = cur.board;
            int moves = cur.moves;
            if (Arrays.deepEquals(state, target)) {
                return moves;
            }
            int zeroIndex = -1;
            outer:
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 3; j++) {
                    if (state[i][j] == 0) {
                        zeroIndex = i * 3 + j;
                        break outer;
                    }
                }
            }
            for (int dir : directions[zeroIndex]) {
                int[][] nextState = copyBoard(state);
                int zr = zeroIndex / 3;
                int zc = zeroIndex % 3;
                int nr = dir / 3;
                int nc = dir % 3;
                int temp = nextState[zr][zc];
                nextState[zr][zc] = nextState[nr][nc];
                nextState[nr][nc] = temp;
                String nextStr = boardToString(nextState);
                if (!visited.contains(nextStr)) {
                    queue.offer(new Node(nextState, moves + 1));
                    visited.add(nextStr);
                }
            }
        }
        return -1;
    }

    private static int[][] copyBoard(int[][] board) {
        int[][] copy = new int[2][3];
        for (int i = 0; i < 2; i++) {
            System.arraycopy(board[i], 0, copy[i], 0, 3);
        }
        return copy;
    }

    private static String boardToString(int[][] board) {
        return Arrays.deepToString(board);
    }

    private static class Node {
        int[][] board;
        int moves;
        Node(int[][] b, int m) {
            this.board = b;
            this.moves = m;
        }
    }
}

