class Solution {
    private int minDiff;
    private Integer prevVal;
    public int minDiffInBST(TreeNode root) {
        minDiff = Integer.MAX_VALUE;
        prevVal = null;
        inorder(root);
        return minDiff;
    }
    private void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        if (prevVal != null) {
            int diff = Math.abs(node.val - prevVal);
            if (diff < minDiff) minDiff = diff;
        }
        prevVal = node.val;
        inorder(node.right);
    }
}

