class Solution {
    public static int movesToMakeBoard(int[][] board) {
        int n = board.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if ((board[i][j] ^ board[0][j] ^ board[i][0] ^ board[0][0]) != 0) {
                    return -1;
                }
            }
        }
        int rowOnes = 0, colOnes = 0;
        for (int i = 0; i < n; i++) {
            rowOnes += board[i][0];
            colOnes += board[0][i];
        }
        if (n % 2 == 0) {
            if (rowOnes != n / 2 || colOnes != n / 2) return -1;
        } else {
            if (rowOnes != n / 2 && rowOnes != n / 2 + 1) return -1;
            if (colOnes != n / 2 && colOnes != n / 2 + 1) return -1;
        }
        int rowMis = 0, colMis = 0;
        for (int i = 0; i < n; i++) {
            if (board[i][0] != i % 2) rowMis++;
            if (board[0][i] != i % 2) colMis++;
        }
        int rowSwaps, colSwaps;
        if (n % 2 == 0) {
            rowSwaps = Math.min(rowMis, n - rowMis) / 2;
            colSwaps = Math.min(colMis, n - colMis) / 2;
        } else {
            rowSwaps = (rowOnes == n / 2 ? rowMis : n - rowMis) / 2;
            colSwaps = (colOnes == n / 2 ? colMis : n - colMis) / 2;
        }
        return rowSwaps + colSwaps;
    }
}

