class Solution {
    public static List<String> letterCasePermutation(String s) {
        List<String> result = new ArrayList<>();
        backtrack(s, "", 0, result);
        return result;
    }

    private static void backtrack(String s, String current, int index, List<String> result) {
        if (index == s.length()) {
            result.add(current);
        } else {
            char c = s.charAt(index);
            if (Character.isLetter(c)) {
                backtrack(s, current + Character.toLowerCase(c), index + 1, result);
                backtrack(s, current + Character.toUpperCase(c), index + 1, result);
            } else {
                backtrack(s, current + c, index + 1, result);
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class Solution {
    public static boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);
        for (int i = 0; i < n; i++) {
            if (color[i] == -1) {
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(i);
                color[i] = 0;
                while (!stack.isEmpty()) {
                    int node = stack.pop();
                    for (int neighbor : graph[node]) {
                        if (color[neighbor] == color[node]) return false;
                        if (color[neighbor] == -1) {
                            color[neighbor] = 1 - color[node];
                            stack.push(neighbor);
                        }
                    }
                }
            }
        }
        return true;
    }
}

