class Solution {
    private static final int MOD = 1000000007;
    public static int numTilings(int n) {
        if (n == 0) return 0;
        if (n == 1) return 1;
        if (n == 2) return 2;
        if (n == 3) return 5;
        long[] dp = new long[n + 1];
        dp[0] = 0;
        dp[1] = 1;
        dp[2] = 2;
        dp[3] = 5;
        for (int i = 4; i <= n; i++) {
            dp[i] = (2 * dp[i - 1] + dp[i - 3]) % MOD;
        }
        return (int) dp[n];
    }
}

public class Solution {
    public static int preimageSizeFZF(long k) {
        long left = 0, right = 5 * k;
        while (left < right) {
            long mid = (left + right) / 2;
            if (findTrailingZeroes(mid) < k) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        if (findTrailingZeroes(left) != k) {
            return 0;
        }
        int count = 1;
        long i = 1;
        while (findTrailingZeroes(left + i) == k) {
            count++;
            i++;
        }
        i = 1;
        while (left - i >= 0 && findTrailingZeroes(left - i) == k) {
            count++;
            i++;
        }
        return count;
    }

    private static long findTrailingZeroes(long x) {
        long count = 0;
        long i = 5;
        while (x / i >= 1) {
            count += x / i;
            i *= 5;
        }
        return count;
    }
}

