class Solution {
    public static int rotatedDigits(int n) {
        int count = 0;
        for (int i = 1; i <= n; i++) {
            int rotated = rotateNumber(i);
            if (rotated != -1 && rotated != i) {
                count++;
            }
        }
        return count;
    }

    private static int rotateNumber(int num) {
        StringBuilder sb = new StringBuilder();
        int x = num;
        while (x > 0) {
            int d = x % 10;
            char rd;
            switch (d) {
                case 0: rd = '0'; break;
                case 1: rd = '1'; break;
                case 8: rd = '8'; break;
                case 2: rd = '5'; break;
                case 5: rd = '2'; break;
                case 6: rd = '9'; break;
                case 9: rd = '6'; break;
                default: return -1;
            }
            sb.append(rd);
            x /= 10;
        }
        sb.reverse();
        return Integer.parseInt(sb.toString());
    }
}

