class Solution {
    public static int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] flight : flights) {
            int from = flight[0];
            int to = flight[1];
            int price = flight[2];
            graph[from].add(new int[]{to, price});
        }
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{src, 0, k + 1});
        int[] prices = new int[n];
        Arrays.fill(prices, Integer.MAX_VALUE);
        prices[src] = 0;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int city = cur[0];
            int price = cur[1];
            int stops = cur[2];
            if (city == dst) {
                prices[dst] = Math.min(prices[dst], price);
            }
            if (stops == 0) {
                continue;
            }
            for (int[] edge : graph[city]) {
                int neighbor = edge[0];
                int neighborPrice = edge[1];
                int newPrice = price + neighborPrice;
                if (newPrice < prices[neighbor]) {
                    prices[neighbor] = newPrice;
                    queue.offer(new int[]{neighbor, newPrice, stops - 1});
                }
            }
        }
        return prices[dst] == Integer.MAX_VALUE ? -1 : prices[dst];
    }
}

