class Solution {
    public static double champagneTower(int poured, int query_row, int query_glass) {
        double[][] champagne = new double[query_row + 1][query_row + 1];
        champagne[0][0] = poured;
        for (int i = 0; i < query_row; i++) {
            for (int j = 0; j <= i; j++) {
                if (champagne[i][j] > 1.0) {
                    double excess = (champagne[i][j] - 1.0) / 2.0;
                    champagne[i + 1][j] += excess;
                    champagne[i + 1][j + 1] += excess;
                    champagne[i][j] = 1.0;
                }
            }
        }
        return Math.min(1.0, champagne[query_row][query_glass]);
    }
}

