class Solution {
    public static boolean splitArraySameAverage(int[] nums) {
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }
        int n = nums.length;
        for (int i = 1; i <= n / 2; i++) {
            if ((sum * i) % n != 0) {
                continue;
            }
            int target = (int) (sum * i / n);
            boolean[] dp = new boolean[target + 1];
            dp[0] = true;
            for (int num : nums) {
                for (int j = target; j >= num; j--) {
                    dp[j] = dp[j] || dp[j - num];
                }
            }
            if (dp[target] && i != n - i) {
                return true;
            }
        }
        return false;
    }
}

