            if (dfs(i, graph, color)) {
                result.add(i);
            }
        }
        return result;
    }

    private static boolean dfs(int node, int[][] graph, int[] color) {
        if (color[node] > 0) {
            return color[node] == 2;
        }
        color[node] = 1;
        for (int neighbor : graph[node]) {
            if (!dfs(neighbor, graph, color)) {
                return false;
            }
        }
        color[node] = 2;
        return true;
    }
}

import java.util.*;

class Solution {
    public static int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] copy = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, copy[i], 0, n);
        }
        for (int[] hit : hits) {
            int r = hit[0], c = hit[1];
            if (copy[r][c] == 1) {
                copy[r][c] = 0;
            }
        }
        DSU dsu = new DSU(m * n + 1);
        int top = m * n;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (copy[i][j] == 1) {
                    int idx = i * n + j;
                    if (i == 0) {
                        dsu.union(idx, top);
                    }
                    if (i > 0 && copy[i - 1][j] == 1) {
                        dsu.union(idx, (i - 1) * n + j);
                    }
                    if (j > 0 && copy[i][j - 1] == 1) {
                        dsu.union(idx, i * n + (j - 1));
                    }
                }
            }
        }
        int[] result = new int[hits.length];
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (grid[r][c] == 0) {
                result[k] = 0;
                continue;
            }
            int preSize = dsu.getSize(top);
            int idx = r * n + c;
            copy[r][c] = 1;
            if (r == 0) {
                dsu.union(idx, top);
            }
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) {
                    dsu.union(idx, nr * n + nc);
                }
            }
            int postSize = dsu.getSize(top);
            result[k] = Math.max(0, postSize - preSize - 1);
        }
        return result;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;
            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }

        int getSize(int x) {
            return size[find(x)];
        }
    }
}

