class Solution {
    public static int expressiveWords(String s, String[] words) {
        int count = 0;
        for (String word : words) {
            int i = 0, j = 0;
            while (i < s.length() && j < word.length()) {
                if (s.charAt(i) != word.charAt(j)) break;
                int countS = 0, countWord = 0;
                char charS = s.charAt(i);
                char charWord = word.charAt(j);
                while (i < s.length() && s.charAt(i) == charS) { countS++; i++; }
                while (j < word.length() && word.charAt(j) == charWord) { countWord++; j++; }
                if (countWord > countS || (countS < 3 && countS != countWord)) break;
            }
            if (i == s.length() && j == word.length()) count++;
        }
        return count;
    }
}

