class Solution {
    public static int numComponents(ListNode head, int[] nums) {
        Set<Integer> numSet = new HashSet<>();
        for (int n : nums) {
            numSet.add(n);
        }
        int count = 0;
        boolean inComponent = false;
        while (head != null) {
            if (numSet.contains(head.val) && !inComponent) {
                count++;
                inComponent = true;
            }
            if (!numSet.contains(head.val)) {
                inComponent = false;
            }
            head = head.next;
        }
        return count;
    }
}

