class Solution {
    public static int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) return 0;
        Map<Integer, List<Integer>> busStops = new HashMap<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                busStops.computeIfAbsent(stop, k -> new ArrayList<>()).add(i);
            }
        }
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{source, 0});
        Set<Integer> visitedStops = new HashSet<>();
        visitedStops.add(source);
        Set<Integer> visitedBuses = new HashSet<>();
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int stop = cur[0];
            int busCount = cur[1];
            if (stop == target) return busCount;
            List<Integer> buses = busStops.get(stop);
            if (buses != null) {
                for (int bus : buses) {
                    if (visitedBuses.contains(bus)) continue;
                    visitedBuses.add(bus);
                    for (int nextStop : routes[bus]) {
                        if (visitedStops.contains(nextStop)) continue;
                        visitedStops.add(nextStop);
                        queue.offer(new int[]{nextStop, busCount + 1});
                    }
                }
            }
        }
        return -1;
    }
}

