class Solution {
    public static List<String> ambiguousCoordinates(String s) {
        s = s.substring(1, s.length() - 1);
        List<String> result = new ArrayList<>();
        for (int i = 1; i < s.length(); i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);
            List<String> leftNums = generateNumbers(left);
            List<String> rightNums = generateNumbers(right);
            for (String leftNum : leftNums) {
                for (String rightNum : rightNums) {
                    result.add("(" + leftNum + ", " + rightNum + ")");
                }
            }
        }
        Collections.sort(result);
        return result;
    }

    private static List<String> generateNumbers(String s) {
        List<String> res = new ArrayList<>();
        int n = s.length();
        if (n == 1) {
            res.add(s);
            return res;
        }
        if (s.charAt(0) == '0' && s.charAt(n - 1) == '0') {
            return res;
        }
        if (s.charAt(0) == '0') {
            if (s.charAt(n - 1) != '0') {
                res.add("0." + s.substring(1));
            }
            return res;
        }
        if (s.charAt(n - 1) == '0') {
            res.add(s);
            return res;
        }
        res.add(s);
        for (int i = 1; i < n; i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);
            if (right.charAt(right.length() - 1) == '0') {
                continue;
            }
            res.add(left + "." + right);
        }
        return res;
    }
}

import java.lang.Math;

class Solution {
    public static double largestSumOfAverages(int[] nums, int k) {
        int n = nums.length;
        double[] prefixSum = new double[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }
        double[][] dp = new double[n][k + 1];
        for (int i = 0; i < n; i++) {
            dp[i][1] = prefixSum[i + 1] / (i + 1);
        }
        for (int j = 2; j <= k; j++) {
            for (int i = j - 1; i < n; i++) {
                for (int x = j - 2; x < i; x++) {
                    double candidate = dp[x][j - 1] + (prefixSum[i + 1] - prefixSum[x + 1]) / (i - x);
                    if (candidate > dp[i][j]) {
                        dp[i][j] = candidate;
                    }
                }
            }
        }
        return dp[n - 1][k];
    }
}

