class Solution {
    public static int racecar(int target) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 1, 0});
        Set<String> visited = new HashSet<>();
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int position = cur[0];
            int speed = cur[1];
            int steps = cur[2];
            if (position == target) {
                return steps;
            }
            String state = position + "," + speed;
            if (visited.contains(state)) {
                continue;
            }
            visited.add(state);
            queue.offer(new int[]{position + speed, speed * 2, steps + 1});
            queue.offer(new int[]{position, -1, steps + 1});
        }
        return -1;
    }
}

