class Solution {
    public static int numFactoredBinaryTrees(int[] arr) {
        final int MOD = 1_000_000_007;
        Arrays.sort(arr);
        Map<Integer, Long> dp = new HashMap<>();
        for (int val : arr) {
            dp.put(val, 1L);
        }
        for (int i = 0; i < arr.length; i++) {
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];
                    Long otherCount = dp.get(other);
                    if (otherCount != null) {
                        long cur = dp.get(arr[i]);
                        long add = (dp.get(arr[j]) * otherCount) % MOD;
                        dp.put(arr[i], (cur + add) % MOD);
                    }
                }
            }
        }
        long total = 0;
        for (long count : dp.values()) {
            total = (total + count) % MOD;
        }
        return (int) total;
    }
}

