public class Solution {
    public static int numFriendRequests(int[] ages) {
        int[] freq = new int[121];
        for (int age : ages) {
            if (age >= 0 && age <= 120) {
                freq[age]++;
            }
        }
        int[] prefix = new int[121];
        for (int i = 1; i <= 120; i++) {
            prefix[i] = prefix[i - 1] + freq[i];
        }
        long totalRequests = 0;
        for (int age = 15; age <= 120; age++) {
            int count = freq[age];
            if (count == 0) continue;
            int low = (int) (0.5 * age + 7);
            if (low >= age) continue;
            int eligible = prefix[age] - prefix[low];
            totalRequests += (long) count * (eligible - 1);
        }
        return (int) totalRequests;
    }
}

