class Solution {
    public static int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        if (n == 0) return 0;
        int[][] jobDifficultyAndProfit = new int[n][2];
        for (int i = 0; i < n; i++) {
            jobDifficultyAndProfit[i][0] = difficulty[i];
            jobDifficultyAndProfit[i][1] = profit[i];
        }
        Arrays.sort(jobDifficultyAndProfit, (a, b) -> Integer.compare(a[0], b[0]));
        int[] maxProfitSoFar = new int[n];
        maxProfitSoFar[0] = jobDifficultyAndProfit[0][1];
        for (int i = 1; i < n; i++) {
            maxProfitSoFar[i] = Math.max(maxProfitSoFar[i - 1], jobDifficultyAndProfit[i][1]);
        }
        int totalMaxProfit = 0;
        for (int w : worker) {
            int left = 0, right = n - 1;
            while (left <= right) {
                int mid = (left + right) >>> 1;
                if (jobDifficultyAndProfit[mid][0] <= w) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            if (right >= 0) {
                totalMaxProfit += maxProfitSoFar[right];
            }
        }
        return totalMaxProfit;
    }
}

