class Solution {
    public static int countUniqueChars(String s) {
        long result = 0;
        int n = s.length();
        int[] last = new int[26];
        int[] prev = new int[26];
        Arrays.fill(last, -1);
        Arrays.fill(prev, -1);
        for (int i = 0; i < n; i++) {
            int idx = s.charAt(i) - 'A';
            int lastIdx = last[idx];
            int prevIdx = prev[idx];
            if (lastIdx != -1) {
                result += (long) (lastIdx - prevIdx) * (i - lastIdx);
            }
            prev[idx] = lastIdx;
            last[idx] = i;
        }
        for (int c = 0; c < 26; c++) {
            if (last[c] != -1) {
                result += (long) (last[c] - prev[c]) * (n - last[c]);
            }
        }
        return (int) result;
    }
}

