class Solution {
    public static int largestIsland(int[][] grid) {
        int n = grid.length;
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int maxArea = 0;
        int index = 2;
        Map<Integer, Integer> area = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    area.put(index, dfs(grid, i, j, index, directions));
                    maxArea = Math.max(maxArea, area.get(index));
                    index++;
                }
            }
        }
        if (index == 2) return 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    int sum = 0;
                    Set<Integer> seen = new HashSet<>();
                    for (int[] d : directions) {
                        int x = i + d[0];
                        int y = j + d[1];
                        if (x >= 0 && x < n && y >= 0 && y < n) {
                            int neighborIdx = grid[x][y];
                            if (neighborIdx > 1 && seen.add(neighborIdx)) {
                                sum += area.get(neighborIdx);
                            }
                        }
                    }
                    maxArea = Math.max(maxArea, sum + 1);
                }
            }
        }
        return maxArea;
    }

    private static int dfs(int[][] grid, int i, int j, int index, int[][] directions) {
        int n = grid.length;
        grid[i][j] = index;
        int count = 1;
        for (int[] d : directions) {
            int x = i + d[0];
            int y = j + d[1];
            if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 1) {
                count += dfs(grid, x, y, index, directions);
            }
        }
        return count;
    }
}

