class Solution {
    public static List<List<Integer>> largeGroupPositions(String s) {
        List<List<Integer>> result = new ArrayList<>();
        int groupSize = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                groupSize++;
            } else {
                if (groupSize >= 3) {
                    List<Integer> interval = new ArrayList<>(2);
                    interval.add(i - groupSize);
                    interval.add(i - 1);
                    result.add(interval);
                }
                groupSize = 1;
            }
        }
        if (groupSize >= 3) {
            List<Integer> interval = new ArrayList<>(2);
            interval.add(s.length() - groupSize);
            interval.add(s.length() - 1);
            result.add(interval);
        }
        return result;
    }
}

