class Solution {
    public static String findAndReplace(String s, int[] indices, String[] sources, String[] targets) {
        int n = indices.length;
        Map<Integer, Integer> indexToOp = new HashMap<>();
        for (int i = 0; i < n; i++) {
            indexToOp.put(indices[i], i);
        }
        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            if (indexToOp.containsKey(i)) {
                int op = indexToOp.get(i);
                String src = sources[op];
                if (i + src.length() <= s.length() && s.substring(i, i + src.length()).equals(src)) {
                    result.append(targets[op]);
                    i += src.length();
                    continue;
                }
            }
            result.append(s.charAt(i));
            i++;
        }
        return result.toString();
    }
}

