class Solution {
    public static int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        int[] count = new int[n];
        int[] res = new int[n];
        dfs(0, -1, graph, count, res);
        dfs2(0, -1, graph, count, res, n);
        return res;
    }

    private static void dfs(int node, int parent, List<Integer>[] graph, int[] count, int[] res) {
        count[node] = 1;
        for (int child : graph[node]) {
            if (child != parent) {
                dfs(child, node, graph, count, res);
                count[node] += count[child];
                res[node] += res[child] + count[child];
            }
        }
    }

    private static void dfs2(int node, int parent, List<Integer>[] graph, int[] count, int[] res, int n) {
        for (int child : graph[node]) {
            if (child != parent) {
                res[child] = res[node] + n - 2 * count[child];
                dfs2(child, node, graph, count, res, n);
            }
        }
    }
}

