class Solution {
    public static int largestOverlap(int[][] img1, int[][] img2) {
        int n = img1.length;
        int maxOverlap = 0;
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                int overlap = 0;
                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                            overlap += img1[x][y] & img2[nx][ny];
                        }
                    }
                }
                maxOverlap = Math.max(maxOverlap, overlap);
            }
        }
        return maxOverlap;
    }
}

