class Solution {
    public static int numSimilarGroups(String[] strs) {
        Map<String, String> parent = new HashMap<>();
        for (String s : strs) {
            parent.put(s, s);
        }
        for (int i = 0; i < strs.length; i++) {
            for (int j = i + 1; j < strs.length; j++) {
                if (isSimilar(strs[i], strs[j])) {
                    union(strs[i], strs[j], parent);
                }
            }
        }
        Set<String> groups = new HashSet<>();
        for (String s : strs) {
            groups.add(find(s, parent));
        }
        return groups.size();
    }

    private static String find(String x, Map<String, String> parent) {
        if (!parent.get(x).equals(x)) {
            parent.put(x, find(parent.get(x), parent));
        }
        return parent.get(x);
    }

    private static void union(String x, String y, Map<String, String> parent) {
        String rootX = find(x, parent);
        String rootY = find(y, parent);
        if (!rootX.equals(rootY)) {
            parent.put(rootX, rootY);
        }
    }

    private static boolean isSimilar(String x, String y) {
        int diff = 0;
        for (int i = 0; i < x.length(); i++) {
            if (x.charAt(i) != y.charAt(i)) {
                diff++;
            }
            if (diff > 2) {
                return false;
            }
        }
        return diff == 0 || diff == 2;
    }
}

