class Solution {
    public static int numMagicSquaresInside(int[][] grid) {
        int count = 0;
        for (int i = 0; i <= grid.length - 3; i++) {
            for (int j = 0; j <= grid[0].length - 3; j++) {
                int[][] subgrid = new int[3][3];
                for (int k = 0; k < 3; k++) {
                    System.arraycopy(grid[i + k], j, subgrid[k], 0, 3);
                }
                if (isMagicSquare(subgrid)) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean isMagicSquare(int[][] subgrid) {
        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int val = subgrid[i][j];
                if (val < 1 || val > 9) {
                    return false;
                }
                set.add(val);
            }
        }
        if (set.size() != 9) {
            return false;
        }
        int sum = subgrid[0][0] + subgrid[0][1] + subgrid[0][2];
        for (int i = 0; i < 3; i++) {
            if (subgrid[i][0] + subgrid[i][1] + subgrid[i][2] != sum) {
                return false;
            }
            if (subgrid[0][i] + subgrid[1][i] + subgrid[2][i] != sum) {
                return false;
            }
        }
        if (subgrid[0][0] + subgrid[1][1] + subgrid[2][2] != sum) {
            return false;
        }
        if (subgrid[0][2] + subgrid[1][1] + subgrid[2][0] != sum) {
            return false;
        }
        return true;
    }
}

