class Solution {
    public static List<Integer> splitIntoFibonacci(String num) {
        List<Integer> result = new ArrayList<>();
        backtrack(num, 0, new ArrayList<>(), result);
        return result;
    }

    private static boolean backtrack(String num, int start, List<Long> path, List<Integer> result) {
        if (start == num.length() && path.size() >= 3) {
            for (Long v : path) {
                result.add(v.intValue());
            }
            return true;
        }
        for (int i = 1; i <= num.length() - start; i++) {
            String substr = num.substring(start, start + i);
            if (substr.length() > 1 && substr.charAt(0) == '0') continue;
            long currNum = Long.parseLong(substr);
            if (path.size() < 2) {
                path.add(currNum);
                if (backtrack(num, start + i, path, result)) {
                    return true;
                }
                path.remove(path.size() - 1);
            } else {
                long sum = path.get(path.size() - 1) + path.get(path.size() - 2);
                if (currNum == sum) {
                    path.add(currNum);
                    if (backtrack(num, start + i, path, result)) {
                        return true;
                    }
                    path.remove(path.size() - 1);
                }
            }
        }
        return false;
    }
}

public class Solution {
