class Solution {
    public static int rectangleArea(int[][] rectangles) {
        List<int[]> events = new ArrayList<>();
        for (int[] r : rectangles) {
            events.add(new int[]{r[0], 1, r[1], r[3]});
            events.add(new int[]{r[2], -1, r[1], r[3]});
        }
        events.sort((a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> active = new ArrayList<>();
        long area = 0;
        final int MOD = 1_000_000_007;
        int prevX = events.get(0)[0];
        for (int[] e : events) {
            int x = e[0];
            int width = x - prevX;
            if (width > 0 && !active.isEmpty()) {
                List<int[]> segs = new ArrayList<>(active);
                segs.sort((a, b) -> Integer.compare(a[0], b[0]));
                long coveredY = 0;
                int curStart = segs.get(0)[0];
                int curEnd = segs.get(0)[1];
                for (int i = 1; i < segs.size(); i++) {
                    int s = segs.get(i)[0];
                    int eY = segs.get(i)[1];
                    if (s > curEnd) {
                        coveredY += curEnd - curStart;
                        curStart = s;
                        curEnd = eY;
                    } else {
                        curEnd = Math.max(curEnd, eY);
                    }
                }
                coveredY += curEnd - curStart;
                area = (area + width * coveredY) % MOD;
            }
            if (e[1] == 1) {
                active.add(new int[]{e[2], e[3]});
            } else {
                for (int i = 0; i < active.size(); i++) {
                    int[] a = active.get(i);
                    if (a[0] == e[2] && a[1] == e[3]) {
                        active.remove(i);
                        break;
                    }
                }
            }
            prevX = x;
        }
        return (int) area;
    }
}

