class Solution {
    public static void findSecretWord(List<String> wordlist, Master master, int allowedGuesses) {
        List<String> possibleWords = new ArrayList<>(wordlist);
        Random rand = new Random();
        for (int i = 0; i < allowedGuesses; i++) {
            String guess = possibleWords.get(rand.nextInt(possibleWords.size()));
            int matches = master.guess(guess);
            if (matches == 6) return;
            List<String> filtered = new ArrayList<>();
            for (String word : possibleWords) {
                int matchCount = 0;
                for (int j = 0; j < 6; j++) {
                    if (word.charAt(j) == guess.charAt(j)) matchCount++;
                }
                if (matchCount == matches) {
                    filtered.add(word);
                }
            }
            possibleWords = filtered;
        }
    }
}

