class Solution {
    private int maxDepth;
    private List<TreeNode> deepestNodes;
    private TreeNode result;

    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        maxDepth = 0;
        deepestNodes = new ArrayList<>();
        result = null;
        dfs(root, 0);
        result = findLCA(root, 0);
        return result;
    }

    private void dfs(TreeNode node, int depth) {
        if (node == null) return;
        if (depth > maxDepth) {
            maxDepth = depth;
            deepestNodes.clear();
            deepestNodes.add(node);
        } else if (depth == maxDepth) {
            deepestNodes.add(node);
        }
        dfs(node.left, depth + 1);
        dfs(node.right, depth + 1);
    }

    private TreeNode findLCA(TreeNode node, int depth) {
        if (node == null) return null;
        if (deepestNodes.contains(node)) return node;
        TreeNode left = findLCA(node.left, depth + 1);
        TreeNode right = findLCA(node.right, depth + 1);
        if (left != null && right != null) return node;
        return left != null ? left : right;
    }
}

