class Solution {
    public static List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        Map<Integer, TreeNode> parentMap = new HashMap<>();
        buildParentMap(root, null, parentMap);
        Set<Integer> visited = new HashSet<>();
        List<Integer> result = new ArrayList<>();
        dfs(target, 0, k, parentMap, visited, result);
        return result;
    }

    private static void buildParentMap(TreeNode node, TreeNode parent, Map<Integer, TreeNode> parentMap) {
        if (node != null) {
            parentMap.put(node.val, parent);
            buildParentMap(node.left, node, parentMap);
            buildParentMap(node.right, node, parentMap);
        }
    }

    private static void dfs(TreeNode node, int distance, int k, Map<Integer, TreeNode> parentMap,
                            Set<Integer> visited, List<Integer> result) {
        if (node == null || visited.contains(node.val)) {
            return;
        }
        visited.add(node.val);
        if (distance == k) {
            result.add(node.val);
        }
        if (distance < k) {
            dfs(node.left, distance + 1, k, parentMap, visited, result);
            dfs(node.right, distance + 1, k, parentMap, visited, result);
            dfs(parentMap.get(node.val), distance + 1, k, parentMap, visited, result);
        }
    }
}

class Solution {
    public static int maxDistToClosest(int[] seats) {
        int maxDistance = 0;
        int left = -1;
        for (int i = 0; i < seats.length; i++) {
            if (seats[i] == 1) {
                if (left == -1) {
                    maxDistance = Math.max(maxDistance, i);
                } else {
                    maxDistance = Math.max(maxDistance, (i - left) / 2);
                }
                left = i;
            }
        }
        maxDistance = Math.max(maxDistance, seats.length - 1 - left);
        return maxDistance;
    }
}

