class Solution {
    public static int minRefuelStops(int target, int startFuel, int[][] stations) {
        int currentFuel = startFuel;
        int stops = 0;
        int previousStation = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i <= stations.length; i++) {
            int distance = i < stations.length ? stations[i][0] - previousStation : target - previousStation;
            while (!pq.isEmpty() && currentFuel < distance) {
                currentFuel += pq.poll();
                stops++;
            }
            if (currentFuel < distance) {
                return -1;
            }
            if (i < stations.length) {
                pq.offer(stations[i][1]);
                previousStation = stations[i][0];
            }
            currentFuel -= distance;
        }
        return stops;
    }
}

