class Solution {
    public static int matrixScore(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int i = 0; i < rows; i++) {
            if (grid[i][0] == 0) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = 1 - grid[i][j];
                }
            }
        }
        for (int j = 1; j < cols; j++) {
            int ones = 0;
            int zeros = 0;
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] == 1) {
                    ones++;
                } else {
                    zeros++;
                }
            }
            if (zeros > ones) {
                for (int i = 0; i < rows; i++) {
                    grid[i][j] = 1 - grid[i][j];
                }
            }
        }
        int score = 0;
        for (int i = 0; i < rows; i++) {
            int rowScore = 0;
            for (int j = 0; j < cols; j++) {
                rowScore += grid[i][j] * (1 << (cols - 1 - j));
            }
            score += rowScore;
        }
        return score;
    }
}

public class Solution {
    public static boolean lemonadeChange(int[] bills) {
        int fiveDollarBills = 0, tenDollarBills = 0;
        for (int i = 0; i < bills.length; i++) {
            if (bills[i] == 5) {
                fiveDollarBills++;
            } else if (bills[i] == 10) {
                if (fiveDollarBills == 0) {
                    return false;
                }
                fiveDollarBills--;
                tenDollarBills++;
            } else {
                if (tenDollarBills > 0 && fiveDollarBills > 0) {
                    tenDollarBills--;
                    fiveDollarBills--;
                } else if (fiveDollarBills >= 3) {
                    fiveDollarBills -= 3;
                } else {
                    return false;
                }
            }
        }
        return true;
    }
}

