class Solution {
    public static int robotSim(int[] commands, int[][] obstacles) {
        int maxDistance = 0;
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int currentDirection = 0;
        int[] currentPosition = {0, 0};
        Set<String> obstacleSet = new HashSet<>();
        for (int[] obstacle : obstacles) {
            obstacleSet.add(obstacle[0] + "," + obstacle[1]);
        }
        for (int command : commands) {
            if (command < 0) {
                currentDirection = (currentDirection + (command == -1 ? 1 : -1) + 4) % 4;
            } else {
                for (int i = 0; i < command; i++) {
                    int nextX = currentPosition[0] + directions[currentDirection][0];
                    int nextY = currentPosition[1] + directions[currentDirection][1];
                    String key = nextX + "," + nextY;
                    if (obstacleSet.contains(key)) {
                        break;
                    }
                    currentPosition[0] = nextX;
                    currentPosition[1] = nextY;
                    int distance = currentPosition[0] * currentPosition[0] + currentPosition[1] * currentPosition[1];
                    maxDistance = Math.max(maxDistance, distance);
                }
            }
        }
        return maxDistance;
    }
}

