class Solution {
    public static int[] fairCandySwap(int[] aliceSizes, int[] bobSizes) {
        long sumA = 0;
        long sumB = 0;
        for (int v : aliceSizes) {
            sumA += v;
        }
        for (int v : bobSizes) {
            sumB += v;
        }
        long diff = (sumA - sumB) / 2;
        Set<Integer> bobSet = new HashSet<>();
        for (int v : bobSizes) {
            bobSet.add(v);
        }
        for (int a : aliceSizes) {
            int b = (int) (a - diff);
            if (bobSet.contains(b)) {
                return new int[]{a, b};
            }
        }
        return new int[0];
    }
}

import java.lang.Math;

class Solution {
    public static int nthMagicalNumber(long n, long a, long b) {
        long MOD = 1_000_000_007L;
        long left = Math.min(a, b);
        long right = n * Math.min(a, b);
        long lcm = lcm(a, b);
        while (left < right) {
            long mid = (left + right) / 2;
            long count = mid / a + mid / b - mid / lcm;
            if (count < n) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return (int)(left % MOD);
    }

    private static long gcd(long x, long y) {
        while (y != 0) {
            long temp = x % y;
            x = y;
            y = temp;
        }
        return x;
    }

    private static long lcm(long x, long y) {
        return x / gcd(x, y) * y;
    }
}

