class Solution {
    public static char decodeAtIndex(String s, int k) {
        long size = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                size *= (c - '0');
            } else {
                size++;
            }
        }
        long kk = k;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                size /= (c - '0');
                kk %= size;
                if (kk == 0) {
                    kk = size;
                }
            } else {
                if (kk == size) {
                    return c;
                }
                size--;
            }
        }
        return '\0';
    }
}

class Solution {
    public static int superEggDrop(int k, int n) {
        int[][] dp = new int[k + 1][n + 1];
        int m = 0;
        while (dp[k][m] < n) {
            m++;
            for (int i = 1; i <= k; i++) {
                dp[i][m] = dp[i - 1][m - 1] + dp[i][m - 1] + 1;
            }
        }
        return m;
    }
}

public class Solution {
    public static int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 0;
        for (int pile : piles) {
            if (pile > right) {
                right = pile;
            }
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            long hoursNeeded = 0;
            for (int pile : piles) {
                hoursNeeded += (pile + mid - 1) / mid;
            }
            if (hoursNeeded > h) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

