class Solution {
    public static int reachableNodes(int[][] edges, int maxMoves, int n) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], cnt = e[2];
            int w = cnt + 1;
            graph[u].add(new int[]{v, w});
            graph[v].add(new int[]{u, w});
        }
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, 0});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            for (int[] edge : graph[u]) {
                int v = edge[0];
                int w = edge[1];
                long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new long[]{nd, v});
                }
            }
        }
        long result = 0;
        for (int i = 0; i < n; i++) {
            if (dist[i] <= maxMoves) result++;
        }
        for (int[] e : edges) {
            int u = e[0], v = e[1], cnt = e[2];
            long fromU = dist[u] <= maxMoves ? Math.max(0, maxMoves - dist[u]) : 0;
            long fromV = dist[v] <= maxMoves ? Math.max(0, maxMoves - dist[v]) : 0;
            result += Math.min(cnt, fromU + fromV);
        }
        return (int) result;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static List<int[]> spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        List<int[]> result = new ArrayList<>();
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int directionIndex = 0;
        int steps = 1;
        int stepsCount = 0;
        int row = rStart;
        int col = cStart;
        result.add(new int[]{row, col});
        while (result.size() < rows * cols) {
            int newRow = row + directions[directionIndex][0];
            int newCol = col + directions[directionIndex][1];
            if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
                result.add(new int[]{newRow, newCol});
            }
            row = newRow;
            col = newCol;
            stepsCount++;
            if (stepsCount == steps) {
                stepsCount = 0;
                directionIndex = (directionIndex + 1) % 4;
                if (directionIndex % 2 == 0) {
                    steps++;
                }
            }
        }
        return result;
    }
}

