class Solution {
    public TreeNode constructFromPrePost(int[] preorder, int[] postorder) {
        return buildTree(preorder, postorder, 0, preorder.length - 1, 0, postorder.length - 1);
    }

    private TreeNode buildTree(int[] preorder, int[] postorder, int preStart, int preEnd, int postStart, int postEnd) {
        if (preStart > preEnd) return null;
        TreeNode root = new TreeNode(preorder[preStart]);
        if (preStart == preEnd) return root;
        int leftChildIndex = preStart + 1;
        int leftChildPostIndex = postStart;
        while (postorder[leftChildPostIndex] != preorder[leftChildIndex]) {
            leftChildPostIndex++;
        }
        int leftTreeLength = leftChildPostIndex - postStart + 1;
        root.left = buildTree(preorder, postorder, leftChildIndex, leftChildIndex + leftTreeLength - 1, postStart, leftChildPostIndex);
        root.right = buildTree(preorder, postorder, leftChildIndex + leftTreeLength, preEnd, leftChildPostIndex + 1, postEnd - 1);
        return root;
    }
}

