class Solution {
    public static int numSpecialEquivGroups(String[] words) {
        Set<String> groups = new HashSet<>();
        for (String word : words) {
            StringBuilder evenChars = new StringBuilder();
            StringBuilder oddChars = new StringBuilder();
            for (int i = 0; i < word.length(); i++) {
                if (i % 2 == 0) {
                    evenChars.append(word.charAt(i));
                } else {
                    oddChars.append(word.charAt(i));
                }
            }
            char[] evenArray = evenChars.toString().toCharArray();
            char[] oddArray = oddChars.toString().toCharArray();
            Arrays.sort(evenArray);
            Arrays.sort(oddArray);
            String sortedWord = new String(evenArray) + new String(oddArray);
            groups.add(sortedWord);
        }
        return groups.size();
    }
}

