class Solution {
    public static int numPermsDISequence(String s) {
        int n = s.length();
        int MOD = 1_000_000_007;
        long[][] dp = new long[n + 1][n + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            char c = s.charAt(i - 1);
            if (c == 'I') {
                long sum = 0;
                for (int j = 0; j <= i; j++) {
                    dp[i][j] = sum;
                    if (j < i) {
                        sum = (sum + dp[i - 1][j]) % MOD;
                    }
                }
            } else {
                long sum = 0;
                for (int j = i - 1; j >= 0; j--) {
                    sum = (sum + dp[i - 1][j]) % MOD;
                    dp[i][j] = sum;
                }
            }
        }
        long res = 0;
        for (int j = 0; j <= n; j++) {
            res = (res + dp[n][j]) % MOD;
        }
        return (int) res;
    }
}

import java.util.List;
