class Solution {
    public static List<TreeNode> allPossibleFBT(int n) {
        if (n % 2 == 0) return new ArrayList<>();
        if (n == 1) {
            List<TreeNode> base = new ArrayList<>();
            base.add(new TreeNode(0));
            return base;
        }
        List<TreeNode> result = new ArrayList<>();
        for (int i = 1; i < n; i += 2) {
            List<TreeNode> leftTrees = allPossibleFBT(i);
            List<TreeNode> rightTrees = allPossibleFBT(n - i - 1);
            for (TreeNode left : leftTrees) {
                for (TreeNode right : rightTrees) {
                    TreeNode root = new TreeNode(0);
                    root.left = left;
                    root.right = right;
                    result.add(root);
                }
            }
        }
        return result;
    }
}

import java.util.*;

class FreqStack {
    private final Map<Integer, Integer> frequencyMap = new HashMap<>();
    private final Map<Integer, Deque<Integer>> frequencyToElements = new HashMap<>();
    private int maxFrequency = 0;

    public void push(int x) {
        frequencyMap.put(x, frequencyMap.getOrDefault(x, 0) + 1);
        int freq = frequencyMap.get(x);
        if (freq > maxFrequency) {
            maxFrequency = freq;
        }
        frequencyToElements.computeIfAbsent(freq, k -> new ArrayDeque<>()).addLast(x);
    }

    public int pop() {
        Deque<Integer> stack = frequencyToElements.get(maxFrequency);
        int removed = stack.removeLast();
        frequencyMap.put(removed, frequencyMap.get(removed) - 1);
        if (stack.isEmpty()) {
            maxFrequency--;
        }
        return removed;
    }
}

import java.util.Arrays;

class Solution {
    public static int sumSubseqWidths(int[] nums) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(nums);
        int n = nums.length;
        long[] pow2 = new long[n];
        if (n > 0) {
            pow2[0] = 1;
            for (int i = 1; i < n; i++) {
                pow2[i] = (pow2[i - 1] << 1) % MOD;
            }
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            long diff = (pow2[i] - pow2[n - 1 - i] + MOD) % MOD;
            sum = (sum + (nums[i] & 0xffffffffL) * diff) % MOD;
        }
        return (int) sum;
    }
}

