public class Solution {
    public static int atMostNGivenDigitSet(String[] digits, int n) {
        int m = digits.length;
        String s = Integer.toString(n);
        int len = s.length();
        int count = 0;
        for (int l = 1; l < len; l++) {
            count += pow(m, l);
        }
        for (int i = 0; i < len; i++) {
            char cur = s.charAt(i);
            int smaller = 0;
            for (String d : digits) {
                char dc = d.charAt(0);
                if (i == 0 && dc == '0') {
                    continue;
                }
                if (dc < cur) {
                    smaller++;
                } else {
                    break;
                }
            }
            int remaining = len - i - 1;
            count += smaller * pow(m, remaining);
            boolean found = false;
            for (String d : digits) {
                if (d.charAt(0) == cur) {
                    if (i == 0 && d.charAt(0) == '0') {
                        continue;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                return count;
            }
        }
        return count + 1;
    }

    private static int pow(int base, int exp) {
        int result = 1;
        for (int i = 0; i < exp; i++) {
            result *= base;
        }
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public static int sumSubarrayMins(int[] arr) {
        final int MOD = 1_000_000_007;
        int n = arr.length;
        if (n == 0) return 0;
        int[] left = new int[n];
        int[] right = new int[n];
        Arrays.fill(left, -1);
        Arrays.fill(right, n);
        int[] stack = new int[n];
        int sz = 0;
        for (int i = 0; i < n; i++) {
            while (sz > 0 && arr[stack[sz - 1]] >= arr[i]) {
                sz--;
            }
            if (sz > 0) {
                left[i] = stack[sz - 1];
            }
            stack[sz++] = i;
        }
        sz = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (sz > 0 && arr[stack[sz - 1]] > arr[i]) {
                sz--;
            }
            if (sz > 0) {
                right[i] = stack[sz - 1];
            }
            stack[sz++] = i;
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            long count = (long) (i - left[i]) * (right[i] - i);
            sum = (sum + count * arr[i]) % MOD;
        }
        return (int) sum;
    }
}

