class Solution {
    public static int snakesAndLadders(int[][] board) {
        int n = board.length;
        int[] cells = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int idx = (i % 2 == 0) ? i * n + j : i * n + n - j - 1;
                cells[idx] = board[n - i - 1][j];
            }
        }
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{0, 0});
        Set<Integer> visited = new HashSet<>();
        visited.add(0);
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int curr = cur[0];
            int rolls = cur[1];
            if (curr == n * n - 1) {
                return rolls;
            }
            for (int dice = 1; dice <= 6; dice++) {
                int next = curr + dice;
                if (next >= n * n) {
                    continue;
                }
                if (cells[next] != -1) {
                    next = cells[next] - 1;
                }
                if (!visited.contains(next)) {
                    queue.offer(new int[]{next, rolls + 1});
                    visited.add(next);
                }
            }
        }
        return -1;
    }
}

