class Solution {
    public static int smallestRangeII(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int result = nums[n - 1] - nums[0];
        for (int i = 0; i < n - 1; i++) {
            int high = Math.max(nums[i] + k, nums[n - 1] - k);
            int low = Math.min(nums[0] + k, nums[i + 1] - k);
            result = Math.min(result, high - low);
        }
        return result;
    }
}

