public class Solution {
    public static int[] topVotedCandidate(int[] persons, int[] times, int[] queries) {
        Map<Integer, Integer> voteCount = new HashMap<>();
        int leader = 0;
        List<Integer> result = new ArrayList<>();
        Map<Integer, Integer> leaderAtTime = new HashMap<>();

        for (int i = 0; i < persons.length; i++) {
            int person = persons[i];
            voteCount.putIfAbsent(person, 0);
            voteCount.put(person, voteCount.get(person) + 1);
            int personVotes = voteCount.get(person);
            int leaderVotes = voteCount.getOrDefault(leader, 0);
            if (personVotes >= leaderVotes || (personVotes == leaderVotes && i > leader)) {
                leader = person;
            }
            leaderAtTime.put(times[i], leader);
        }

        for (int queryTime : queries) {
            // FIXED: original scanned forward for the smallest recorded time >= queryTime,
            // incorrectly using a future vote. Correct answer uses the largest recorded
            // time <= queryTime, found via backward scan.
            Integer leaderAtQueryTime = null;
            for (int j = times.length - 1; j >= 0; j--) {
                if (times[j] <= queryTime) {
                    leaderAtQueryTime = leaderAtTime.get(times[j]);
                    break;
                }
            }
            result.add(leaderAtQueryTime);
        }

        int[] resArray = new int[result.size()];
        for (int i = 0; i < result.size(); i++) resArray[i] = result.get(i);
        return resArray;
    }
}

import java.util.*;

class Solution {
    public static int catMouseGame(int[][] graph) {
        int n = graph.length;
        int[][][] result = new int[n][n][2]; // 0 unknown, 1 mouse win, 2 cat win
        int[][][] degree = new int[n][n][2];

        // compute out degree for each state
        for (int m = 0; m < n; m++) {
            for (int c = 0; c < n; c++) {
                degree[m][c][0] = graph[m].length; // mouse turn
                int cnt = 0;
                for (int nb : graph[c]) {
                    if (nb != 0) cnt++; // cat cannot move to hole
                }
                degree[m][c][1] = cnt; // cat turn
            }
        }

        Deque<int[]> queue = new ArrayDeque<>();

        // terminal states
        for (int m = 0; m < n; m++) {
            for (int c = 0; c < n; c++) {
                // mouse reaches hole -> mouse wins
                if (m == 0) {
                    for (int t = 0; t < 2; t++) {
                        if (result[m][c][t] == 0) {
                            result[m][c][t] = 1;
                            queue.offer(new int[]{m, c, t});
                        }
                    }
                }
                // cat catches mouse (and not at hole) -> cat wins
                if (m == c && m != 0) {
                    for (int t = 0; t < 2; t++) {
                        if (result[m][c][t] == 0) {
                            result[m][c][t] = 2;
                            queue.offer(new int[]{m, c, t});
                        }
                    }
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int m = cur[0], c = cur[1], turn = cur[2];
            int curRes = result[m][c][turn];

            // find all parent states that can move to (m,c,turn)
            int prevTurn = 1 - turn;
            if (prevTurn == 0) { // previous was mouse's turn
                // cat stayed, mouse moved from some prevM to m
                for (int prevM : graph[m]) {
                    if (result[prevM][c][prevTurn] != 0) continue;
                    // if current result is mouse win, mouse (who moved) can force win
                    if (curRes == 1) {
                        result[prevM][c][prevTurn] = 1;
                        queue.offer(new int[]{prevM, c, prevTurn});
                    } else {
                        degree[prevM][c][prevTurn]--;
                        if (degree[prevM][c][prevTurn] == 0) {
                            result[prevM][c][prevTurn] = 2;
                            queue.offer(new int[]{prevM, c, prevTurn});
                        }
                    }
                }
            } else { // previous was cat's turn
                // mouse stayed, cat moved from some prevC to c (cannot be 0)
                for (int prevC : graph[c]) {
                    if (prevC == 0) continue; // cat cannot be at hole
                    if (result[m][prevC][prevTurn] != 0) continue;
                    if (curRes == 2) {
                        result[m][prevC][prevTurn] = 2;
                        queue.offer(new int[]{m, prevC, prevTurn});
                    } else {
                        degree[m][prevC][prevTurn]--;
                        if (degree[m][prevC][prevTurn] == 0) {
                            result[m][prevC][prevTurn] = 1;
                            queue.offer(new int[]{m, prevC, prevTurn});
                        }
                    }
                }
            }
        }

        return result[1][2][0];
    }
}

