public class Solution {
    public static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int x) { this.val = x; }
    }

    public static class CBTInserter {
        TreeNode root;
        Deque<TreeNode> queue = new ArrayDeque<>();

        CBTInserter(TreeNode root) {
            this.root = root;
            Deque<TreeNode> bfs = new ArrayDeque<>();
            bfs.add(root);
            while (!bfs.isEmpty()) {
                TreeNode node = bfs.poll();
                if (node.left == null || node.right == null) queue.add(node);
                if (node.left != null) bfs.add(node.left);
                if (node.right != null) bfs.add(node.right);
            }
        }

        public int insert(int val) {
            TreeNode node = new TreeNode(val);
            TreeNode parent = queue.peek();
            if (parent.left == null) parent.left = node;
            else { parent.right = node; queue.poll(); }
            queue.add(node);
            return parent.val;
        }

        public TreeNode get_root() {
            return root;
        }
    }

    public static CBTInserter CBTInserter(TreeNode root) {
        return new CBTInserter(root);
    }
}

class Solution {
    public static int[] sortArrayByParityII(int[] nums) {
        int evenIndex = 0, oddIndex = 1;
        while (evenIndex < nums.length && oddIndex < nums.length) {
            if (nums[evenIndex] % 2 == 1) {
                while (nums[oddIndex] % 2 == 1) oddIndex += 2;
                int temp = nums[evenIndex];
                nums[evenIndex] = nums[oddIndex];
                nums[oddIndex] = temp;
            }
            if (nums[oddIndex] % 2 == 0) {
                while (nums[evenIndex] % 2 == 0) evenIndex += 2;
                int temp = nums[oddIndex];
                nums[oddIndex] = nums[evenIndex];
                nums[evenIndex] = temp;
            }
            evenIndex += 2;
            oddIndex += 2;
        }
        return nums;
    }
}

