class Solution {
    public static long threeSumMulti(int[] arr, int target) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : arr) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        int[] uniq = freq.keySet().stream().mapToInt(Integer::intValue).sorted().toArray();
        long count = 0;
        int m = uniq.length;
        for (int i = 0; i < m; i++) {
            int a = uniq[i];
            for (int j = i; j < m; j++) {
                int b = uniq[j];
                int c = target - a - b;
                if (!freq.containsKey(c) || c < b) continue;
                long fa = freq.get(a);
                long fb = freq.get(b);
                long fc = freq.get(c);
                if (a == b && b == c) {
                    count += combination((int) fa, 3);
                } else if (a == b) {
                    count += combination((int) fa, 2) * fc;
                } else if (b == c) {
                    count += combination((int) fb, 2) * fa;
                } else {
                    count += fa * fb * fc;
                }
            }
        }
        return count;
    }

    private static long combination(int n, int k) {
        if (k == 2) {
            return (long) n * (n - 1) / 2;
        } else if (k == 3) {
            return (long) n * (n - 1) * (n - 2) / 6;
        }
        return 0;
    }
}

