class Solution {
    public static int minFallingPathSum(int[][] matrix) {
        int n = matrix.length;
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            dp[0][i] = matrix[0][i];
        }
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j == 0) {
                    dp[i][j] = matrix[i][j] + Math.min(dp[i - 1][j], dp[i - 1][j + 1]);
                } else if (j == n - 1) {
                    dp[i][j] = matrix[i][j] + Math.min(dp[i - 1][j - 1], dp[i - 1][j]);
                } else {
                    int minPrev = Math.min(dp[i - 1][j - 1], dp[i - 1][j]);
                    minPrev = Math.min(minPrev, dp[i - 1][j + 1]);
                    dp[i][j] = matrix[i][j] + minPrev;
                }
            }
        }
        int minSum = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            minSum = Math.min(minSum, dp[n - 1][i]);
        }
        return minSum;
    }
}

import java.util.*;

public class Solution {
    public static int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (graph[i][j] == 1) {
                    union(i, j, parent, size);
                }
            }
        }
        int[] infected = new int[n];
        for (int node : initial) {
            int root = find(node, parent);
            infected[root]++;
        }
        int res = -1;
        int maxSave = 0;
        for (int node : initial) {
            int root = find(node, parent);
            if (infected[root] == 1) {
                if (size[root] > maxSave) {
                    maxSave = size[root];
                    res = node;
                } else if (size[root] == maxSave) {
                    res = Math.min(res, node);
                }
            }
        }
        if (res == -1) {
            int min = Integer.MAX_VALUE;
            for (int node : initial) {
                if (node < min) min = node;
            }
            res = min;
        }
        return res;
    }
    private static int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }
    private static void union(int x, int y, int[] parent, int[] size) {
        int rootX = find(x, parent);
        int rootY = find(y, parent);
        if (rootX != rootY) {
            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }
    }
}

import java.util.*;

class Solution {
    public static int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        Arrays.sort(initial);
        int bestNode = initial[0];
        int bestInfected = Integer.MAX_VALUE;
        for (int remove : initial) {
            boolean[] visited = new boolean[n];
            visited[remove] = true;
            int infected = 0;
            for (int src : initial) {
                if (src == remove || visited[src]) continue;
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(src);
                visited[src] = true;
                while (!stack.isEmpty()) {
                    int u = stack.pop();
                    infected++;
                    for (int v = 0; v < n; v++) {
                        if (graph[u][v] == 1 && !visited[v]) {
                            visited[v] = true;
                            stack.push(v);
                        }
                    }
                }
            }
            if (infected < bestInfected) {
                bestInfected = infected;
                bestNode = remove;
            }
        }
        return bestNode;
    }
}

