class Solution {
    public static int knightDialer(int n) {
        final long MOD = 1_000_000_007L;
        int[][] moves = {
            {4, 6},
            {6, 8},
            {7, 9},
            {4, 8},
            {0, 3, 9},
            {},
            {0, 1, 7},
