        }
        return (int) total;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int shortestBridge(int[][] grid) {
        int n = grid.length;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        Deque<int[]> queue = new ArrayDeque<>();

        boolean found = false;
        for (int i = 0; i < n && !found; i++) {
            for (int j = 0; j < n && !found; j++) {
                if (grid[i][j] == 1) {
                    dfs(i, j, grid, queue);
                    found = true;
                }
            }
        }

        int distance = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int k = 0; k < size; k++) {
                int[] cur = queue.poll();
                int x = cur[0];
                int y = cur[1];
                for (int[] d : dirs) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
                    if (grid[nx][ny] == 1) {
                        return distance;
                    }
                    if (grid[nx][ny] == 0) {
                        grid[nx][ny] = 2;
                        queue.offer(new int[]{nx, ny});
                    }
                }
            }
            distance++;
        }
        return -1;
    }

    private static void dfs(int i, int j, int[][] grid, Deque<int[]> queue) {
        int n = grid.length;
        if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] != 1) {
            return;
        }
        grid[i][j] = 2;
        queue.offer(new int[]{i, j});
        dfs(i - 1, j, grid, queue);
        dfs(i + 1, j, grid, queue);
        dfs(i, j - 1, grid, queue);
        dfs(i, j + 1, grid, queue);
    }
}

