class Solution {
    public static String[] reorderLogFiles(String[] logs) {
        List<String> letterLogs = new ArrayList<>();
        List<String> digitLogs = new ArrayList<>();
        for (String log : logs) {
            String token = log.split(" ")[1];
            try {
                Integer.parseInt(token);
                digitLogs.add(log);
            } catch (NumberFormatException e) {
                letterLogs.add(log);
            }
        }
        Collections.sort(letterLogs, (a, b) -> {
            String contentA = a.substring(a.indexOf(' ') + 1);
            String contentB = b.substring(b.indexOf(' ') + 1);
            int cmp = contentA.compareTo(contentB);
            if (cmp != 0) return cmp;
            return a.compareTo(b);
        });
        List<String> result = new ArrayList<>(letterLogs);
        result.addAll(digitLogs);
        return result.toArray(new String[0]);
    }
}

