class Solution {
    public static int[] movesToStamp(String stamp, String target) {
        int n = target.length();
        int m = stamp.length();
        char[] t = target.toCharArray();
        boolean[] visited = new boolean[n];
        List<Integer> result = new ArrayList<>();
        int stamped = 0;
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i <= n - m; i++) {
                if (!visited[i] && canStamp(t, i, stamp)) {
                    int count = 0;
                    for (int j = 0; j < m; j++) {
                        if (t[i + j] != '?') {
                            t[i + j] = '?';
                            count++;
                        }
                    }
                    if (count > 0) {
                        visited[i] = true;
                        changed = true;
                        stamped += count;
                        result.add(i);
                        if (stamped == n) {
                            break;
                        }
                        break;
                    }
                }
            }
        }
        if (stamped != n) return new int[0];
        Collections.reverse(result);
        int[] ans = new int[result.size()];
        for (int i = 0; i < result.size(); i++) ans[i] = result.get(i);
        return ans;
    }

    private static boolean canStamp(char[] t, int pos, String stamp) {
        int m = stamp.length();
        boolean hasNonQuestion = false;
        for (int j = 0; j < m; j++) {
            char tc = t[pos + j];
            char sc = stamp.charAt(j);
            if (tc != '?' && tc != sc) return false;
            if (tc != '?') hasNonQuestion = true;
        }
        return hasNonQuestion;
    }
}

