class Solution {
    public static int distinctSubseqII(String s) {
        final long MOD = 1_000_000_007L;
        int n = s.length();
        long[] dp = new long[n + 1];
        int[] last = new int[26];
        for (int i = 0; i < 26; i++) {
            last[i] = -1;
        }
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            dp[i] = (dp[i - 1] * 2) % MOD;
            int idx = s.charAt(i - 1) - 'a';
            if (last[idx] != -1) {
                dp[i] = (dp[i] - dp[last[idx]] + MOD) % MOD;
            }
            last[idx] = i - 1;
        }
        return (int) ((dp[n] - 1 + MOD) % MOD);
    }
}

