public class Solution {
    public static String largestTimeFromDigits(int[] arr) {
        int[] maxTime = new int[]{-1};
        permute(arr, 0, arr.length - 1, maxTime);
        if (maxTime[0] == -1) {
            return "";
        }
        int hours = maxTime[0] / 100;
        int minutes = maxTime[0] % 100;
        String hoursStr = String.format("%02d", hours);
        String minutesStr = String.format("%02d", minutes);
        return hoursStr + ":" + minutesStr;
    }

    private static void permute(int[] arr, int start, int end, int[] maxTime) {
        if (start == end) {
            String time = "" + arr[0] + arr[1] + ":" + arr[2] + arr[3];
            if (isValidTime(time)) {
                int numeric = Integer.parseInt(time.replace(":", ""));
                maxTime[0] = Math.max(maxTime[0], numeric);
            }
        } else {
            for (int i = start; i <= end; i++) {
                int temp = arr[start];
                arr[start] = arr[i];
                arr[i] = temp;
                permute(arr, start + 1, end, maxTime);
                temp = arr[start];
                arr[start] = arr[i];
                arr[i] = temp;
            }
        }
    }

    private static boolean isValidTime(String time) {
        String[] parts = time.split(":");
        int hours = Integer.parseInt(parts[0]);
        int minutes = Integer.parseInt(parts[1]);
        return hours >= 0 && hours <= 23 && minutes >= 0 && minutes <= 59;
    }
}

