class Solution {
    public static int removeStones(int[][] stones) {
        Map<String, String> parent = new HashMap<>();
        Map<String, Integer> rank = new HashMap<>();

        java.util.function.BiFunction<String, Map<String, String>, String> find = new java.util.function.BiFunction<String, Map<String, String>, String>() {
            @Override
            public String apply(String x, Map<String, String> p) {
                if (!parent.containsKey(x)) {
                    parent.put(x, x);
                    rank.put(x, 0);
                }
                if (parent.get(x).equals(x)) {
                    return x;
                }
                String root = this.apply(parent.get(x), p);
                parent.put(x, root);
                return root;
            }
        };

        java.util.function.BiConsumer<String, String> union = (x, y) -> {
            String rootX = find.apply(x, parent);
            String rootY = find.apply(y, parent);
            if (rootX.equals(rootY)) return;
            int rankX = rank.get(rootX);
            int rankY = rank.get(rootY);
            if (rankX > rankY) {
                parent.put(rootY, rootX);
            } else if (rankX < rankY) {
                parent.put(rootX, rootY);
            } else {
                parent.put(rootY, rootX);
                rank.put(rootX, rankX + 1);
            }
        };

        for (int i = 0; i < stones.length; i++) {
            for (int j = i + 1; j < stones.length; j++) {
                if (stones[i][0] == stones[j][0] || stones[i][1] == stones[j][1]) {
                    String keyI = stones[i][0] + "," + stones[i][1];
                    String keyJ = stones[j][0] + "," + stones[j][1];
                    union.accept(keyI, keyJ);
                }
            }
        }

        Set<String> groups = new HashSet<>();
        for (int[] stone : stones) {
            String key = stone[0] + "," + stone[1];
            groups.add(find.apply(key, parent));
        }

        return stones.length - groups.size();
    }
}

