import java.util.*;

class Solution {
    public static int largestComponentSize(int[] nums) {
        Map<Integer, List<Integer>> primeFactors = new HashMap<>();
        for (int num : nums) {
            List<Integer> factors = getPrimeFactors(num);
            primeFactors.put(num, factors);
        }

        Map<Integer, Integer> parent = new HashMap<>();
        for (int num : nums) {
            parent.put(num, num);
        }

        for (int num1 : nums) {
            for (int num2 : nums) {
                if (num1 != num2) {
                    int commonFactor = getCommonFactor(primeFactors.get(num1), primeFactors.get(num2));
                    if (commonFactor != -1) {
                        union(parent, num1, num2);
                    }
                }
            }
        }

        Map<Integer, Integer> componentSizes = new HashMap<>();
        for (int num : nums) {
            int root = find(parent, num);
            componentSizes.put(root, componentSizes.getOrDefault(root, 0) + 1);
        }

        int maxSize = 0;
        for (int size : componentSizes.values()) {
            if (size > maxSize) {
                maxSize = size;
            }
        }
        return maxSize;
    }

    private static List<Integer> getPrimeFactors(int n) {
        List<Integer> factors = new ArrayList<>();
        int num = n;
        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                factors.add(i);
                while (num % i == 0) {
                    num /= i;
                }
            }
        }
        if (num > 1) {
            factors.add(num);
        }
        return factors;
    }

    private static int getCommonFactor(List<Integer> list1, List<Integer> list2) {
        Set<Integer> set = new HashSet<>(list1);
        for (int val : list2) {
            if (set.contains(val)) {
                return val;
            }
        }
        return -1;
    }

    private static int find(Map<Integer, Integer> parent, int x) {
        int p = parent.get(x);
        if (p != x) {
            p = find(parent, p);
            parent.put(x, p);
        }
        return p;
    }

    private static void union(Map<Integer, Integer> parent, int a, int b) {
        int rootA = find(parent, a);
        int rootB = find(parent, b);
        if (rootA != rootB) {
            parent.put(rootA, rootB);
        }
    }
}

