class Solution {
    public static int minDeletionSize(String[] strs) {
        if (strs == null || strs.length <= 1) return 0;
        int rows = strs.length;
        int cols = strs[0].length();
        boolean[] sorted = new boolean[rows - 1];
        int deletions = 0;
        for (int c = 0; c < cols; c++) {
            boolean delete = false;
            for (int r = 0; r < rows - 1; r++) {
                if (!sorted[r] && strs[r].charAt(c) > strs[r + 1].charAt(c)) {
                    delete = true;
                    break;
                }
            }
            if (delete) {
                deletions++;
                continue;
            }
            for (int r = 0; r < rows - 1; r++) {
                if (!sorted[r] && strs[r].charAt(c) < strs[r + 1].charAt(c)) {
                    sorted[r] = true;
                }
            }
        }
        return deletions;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int tallestBillboard(int[] rods) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int rod : rods) {
            Map<Integer, Integer> newDp = new HashMap<>(dp);
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int diff = entry.getKey();
                int taller = entry.getValue();

                int diffAddTaller = diff + rod;
                int tallerAddTaller = taller + rod;
                newDp.put(diffAddTaller, Math.max(newDp.getOrDefault(diffAddTaller, 0), tallerAddTaller));

                int diffAddShorter = Math.abs(diff - rod);
                int tallerAddShorter = taller + Math.max(rod - diff, 0);
                newDp.put(diffAddShorter, Math.max(newDp.getOrDefault(diffAddShorter, 0), tallerAddShorter));
            }
            dp = newDp;
        }
        return dp.getOrDefault(0, 0);
    }
}

