public class Solution {
    public static int[] prisonAfterNDays(int[] cells, int n) {
        StringBuilder sb = new StringBuilder();
        for (int c : cells) sb.append(c);
        String state = sb.toString();
        Map<String, Integer> map = new HashMap<>();
        int days = 0;
        while (days < n) {
            if (map.containsKey(state)) {
                int cycleLength = days - map.get(state);
                int remainingDays = (n - days) % cycleLength;
                for (int i = 0; i < remainingDays; i++) {
                    state = getNextState(state);
                }
                break;
            }
            map.put(state, days);
            state = getNextState(state);
            days++;
        }
        int[] result = new int[state.length()];
        for (int i = 0; i < state.length(); i++) {
            result[i] = state.charAt(i) - '0';
        }
        return result;
    }

    private static String getNextState(String state) {
        char[] arr = state.toCharArray();
        char[] next = new char[arr.length];
        next[0] = '0';
        next[arr.length - 1] = '0';
        for (int i = 1; i < arr.length - 1; i++) {
            next[i] = (arr[i - 1] == arr[i + 1]) ? '1' : '0';
        }
        return new String(next);
    }
}

