class Solution {
    public static int maxWidthRamp(int[] nums) {
        int n = nums.length;
        int[] indices = new int[n];
        int top = -1;
        for (int i = 0; i < n; i++) {
            if (top == -1 || nums[i] <= nums[indices[top]]) {
                indices[++top] = i;
            }
        }
        int maxWidth = 0;
        for (int j = n - 1; j >= 0; j--) {
            while (top >= 0 && nums[indices[top]] <= nums[j]) {
                int iIdx = indices[top--];
                int width = j - iIdx;
                if (width > maxWidth) {
                    maxWidth = width;
                }
            }
        }
        return maxWidth;
    }
}

