class Solution {
    public static int leastOperators(int x, int target) {
        List<Long> powers = new ArrayList<>();
        long cur = 1;
        while (cur <= target) {
            powers.add(cur);
            cur *= x;
        }
        powers.add(cur); // include the next power for possible overshoot
        int idx = powers.size() - 1;
        Map<Long, Integer> memo = new HashMap<>();
        int result = dfs(idx, target, powers, memo);
        return result - 1;
    }

    private static int dfs(int idx, long target, List<Long> powers, Map<Long, Integer> memo) {
        long key = ((long) idx << 32) | target;
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        int ans;
        if (target == 0) {
            ans = 0;
        } else if (idx == 0) {
            ans = (int) (target * 2);
        } else {
            long p = powers.get(idx);
            long a = target / p;
            long b = target % p;
            int use = (int) (a * idx + dfs(idx - 1, b, powers, memo));
            int useNext = (int) ((a + 1) * idx + dfs(idx - 1, p - b, powers, memo));
            ans = Math.min(use, useNext);
        }
        memo.put(key, ans);
        return ans;
    }
}

