class Solution {
    public static double minAreaFreeRect(int[][] points) {
        int n = points.length;
        Map<Key, List<int[]>> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int x1 = points[i][0];
            int y1 = points[i][1];
            for (int j = i + 1; j < n; j++) {
                int x2 = points[j][0];
                int y2 = points[j][1];
                long midX = (long) x1 + x2;
                long midY = (long) y1 + y2;
                long dist2 = (long) (x1 - x2) * (x1 - x2) + (long) (y1 - y2) * (y1 - y2);
                Key key = new Key(midX, midY, dist2);
                map.computeIfAbsent(key, k -> new ArrayList<>()).add(new int[]{i, j});
            }
        }
        double minArea = Double.POSITIVE_INFINITY;
        for (List<int[]> list : map.values()) {
            int size = list.size();
            for (int a = 0; a < size; a++) {
                int[] p1 = list.get(a);
                int i = p1[0];
                for (int b = a + 1; b < size; b++) {
                    int[] p2 = list.get(b);
                    int k = p2[0];
                    int l = p2[1];
                    // vertices: i (from first pair), k and l (from second pair)
                    long vx = points[k][0] - points[i][0];
                    long vy = points[k][1] - points[i][1];
                    long wx = points[l][0] - points[i][0];
                    long wy = points[l][1] - points[i][1];
                    double area = Math.abs(vx * wy - vy * wx);
                    if (area < minArea && area > 0) {
                        minArea = area;
                    }
                }
            }
        }
        return minArea == Double.POSITIVE_INFINITY ? 0 : minArea;
    }

    private static class Key {
        long midX, midY, dist2;
        Key(long mx, long my, long d2) {
            this.midX = mx;
            this.midY = my;
            this.dist2 = d2;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Key)) return false;
            Key k = (Key) o;
            return midX == k.midX && midY == k.midY && dist2 == k.dist2;
        }
        @Override
        public int hashCode() {
            return Objects.hash(midX, midY, dist2);
        }
    }
}

