class Solution {
    public static List<String> spellchecker(String[] wordlist, String[] queries) {
        Set<String> original = new HashSet<>(Arrays.asList(wordlist));
        Map<String, String> lowerMap = new HashMap<>();
        Map<String, String> devowelMap = new HashMap<>();
        for (String w : wordlist) {
            String lower = w.toLowerCase();
            lowerMap.putIfAbsent(lower, w);
            String devowel = devowel(lower);
            devowelMap.putIfAbsent(devowel, w);
        }
        List<String> result = new ArrayList<>(queries.length);
        for (String q : queries) {
            if (original.contains(q)) {
                result.add(q);
            } else {
                String lower = q.toLowerCase();
                if (lowerMap.containsKey(lower)) {
                    result.add(lowerMap.get(lower));
                } else {
                    String devowel = devowel(lower);
                    if (devowelMap.containsKey(devowel)) {
                        result.add(devowelMap.get(devowel));
                    } else {
                        result.add("");
                    }
                }
            }
        }
        return result;
    }
    private static String devowel(String s) {
        StringBuilder sb = new StringBuilder(s.length());
        for (char c : s.toCharArray()) {
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                sb.append('*');
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

