class Solution {
    public static List<Integer> numsSameConsecDiff(int n, int k) {
        List<Integer> result = new ArrayList<>();
        if (n == 1) {
            result.add(0);
        }
        for (int i = 1; i <= 9; i++) {
            dfs(result, i, n - 1, k);
        }
        Collections.sort(result);
        return result;
    }

    private static void dfs(List<Integer> result, int num, int remaining, int k) {
        if (remaining == 0) {
            result.add(num);
            return;
        }
        int lastDigit = num % 10;
        int next1 = lastDigit + k;
        int next2 = lastDigit - k;
        if (next1 >= 0 && next1 <= 9) {
            dfs(result, num * 10 + next1, remaining - 1, k);
        }
        if (k != 0 && next2 >= 0 && next2 <= 9) {
            dfs(result, num * 10 + next2, remaining - 1, k);
        }
    }
}

