        Set<Integer> set = new HashSet<>();
        long curX = 1;
        while (curX <= bound) {
            long curY = 1;
            while (curX + curY <= bound) {
                set.add((int) (curX + curY));
                if (y == 1) break;
                curY *= y;
            }
            if (x == 1) break;
            curX *= x;
