class Solution {
    // Classic selection-sort-by-flips: for each unsorted suffix (size shrinking from n down
    // to 2), flip the max element to the front, then flip it into its final position at the
    // end of the current suffix. At most 2 flips per element, so at most 2n operations total.
    public List<Integer> pancakeSort(int[] arr) {
        List<Integer> ops = new ArrayList<>();
        int n = arr.length;
        for (int size = n; size > 1; size--) {
            int maxIdx = 0;
            for (int i = 1; i < size; i++) if (arr[i] > arr[maxIdx]) maxIdx = i;
            if (maxIdx == size - 1) continue;
            if (maxIdx != 0) {
                flip(arr, maxIdx + 1);
                ops.add(maxIdx + 1);
            }
            flip(arr, size);
            ops.add(size);
        }
        return ops;
    }
    private void flip(int[] arr, int k) {
        int l = 0, r = k - 1;
        while (l < r) { int t = arr[l]; arr[l] = arr[r]; arr[r] = t; l++; r--; }
    }
}

