import java.math.BigInteger;

class Solution {
    public static boolean isRationalEqual(String s, String t) {
        Fraction f1 = toFraction(splitRational(s));
        Fraction f2 = toFraction(splitRational(t));
        return f1.equals(f2);
    }

    private static String[] splitRational(String s) {
        int lParen = s.indexOf('(');
        int rParen = s.indexOf(')');
        String repeating = "";
        if (lParen != -1 && rParen != -1 && rParen > lParen) {
            repeating = s.substring(lParen + 1, rParen);
        }
        String withoutParen = (lParen != -1) ? s.substring(0, lParen) : s;
        int dot = withoutParen.indexOf('.');
        String integerPart;
        String nonRepeating;
        if (dot != -1) {
            integerPart = withoutParen.substring(0, dot);
            nonRepeating = withoutParen.substring(dot + 1);
        } else {
            integerPart = withoutParen;
            nonRepeating = "";
        }
        return new String[]{integerPart, nonRepeating, repeating};
    }

    private static Fraction toFraction(String[] parts) {
        BigInteger integerPart = new BigInteger(parts[0].isEmpty() ? "0" : parts[0]);
        String nonRep = parts[1];
        String rep = parts[2];
        int m = nonRep.length();
        int n = rep.length();

        if (n == 0) {
            BigInteger denom = BigInteger.TEN.pow(m);
            BigInteger numer = integerPart.multiply(denom);
            if (!nonRep.isEmpty()) {
                numer = numer.add(new BigInteger(nonRep));
            }
            return new Fraction(numer, denom);
        } else {
            BigInteger powM = BigInteger.TEN.pow(m);
            BigInteger powN = BigInteger.TEN.pow(n);
            BigInteger denom = powM.multiply(powN.subtract(BigInteger.ONE));
            BigInteger nonRepVal = nonRep.isEmpty() ? BigInteger.ZERO : new BigInteger(nonRep);
            BigInteger repVal = new BigInteger(rep);
            BigInteger numer = integerPart.multiply(denom)
                    .add(nonRepVal.multiply(powN.subtract(BigInteger.ONE)))
                    .add(repVal);
            return new Fraction(numer, denom);
        }
    }

    private static class Fraction {
        private final BigInteger num;
        private final BigInteger den;

        Fraction(BigInteger num, BigInteger den) {
            if (den.signum() == 0) {
                throw new IllegalArgumentException("Denominator cannot be zero");
            }
            if (den.signum() < 0) {
                num = num.negate();
                den = den.negate();
            }
            BigInteger g = num.gcd(den);
            this.num = num.divide(g);
            this.den = den.divide(g);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Fraction)) return false;
            Fraction other = (Fraction) o;
            return this.num.equals(other.num) && this.den.equals(other.den);
        }

        @Override
        public int hashCode() {
            return num.hashCode() * 31 + den.hashCode();
        }
    }
}

