class Solution {
    public static int oddEvenJumps(int[] arr) {
        int n = arr.length;
        if (n == 0) return 0;
        int[] oddNext = new int[n];
        int[] evenNext = new int[n];
        Arrays.fill(oddNext, -1);
        Arrays.fill(evenNext, -1);
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;

        Arrays.sort(idx, (i, j) -> {
            if (arr[i] != arr[j]) return Integer.compare(arr[i], arr[j]);
            return Integer.compare(i, j);
        });
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i : idx) {
            while (!stack.isEmpty() && i > stack.peekLast()) {
                oddNext[stack.removeLast()] = i;
            }
            stack.addLast(i);
        }

        Arrays.sort(idx, (i, j) -> {
            if (arr[i] != arr[j]) return Integer.compare(arr[j], arr[i]);
            return Integer.compare(i, j);
        });
        stack.clear();
        for (int i : idx) {
            while (!stack.isEmpty() && i > stack.peekLast()) {
                evenNext[stack.removeLast()] = i;
            }
            stack.addLast(i);
        }

        boolean[] canOdd = new boolean[n];
        boolean[] canEven = new boolean[n];
        canOdd[n - 1] = true;
        canEven[n - 1] = true;
        for (int i = n - 2; i >= 0; i--) {
            if (oddNext[i] != -1 && canEven[oddNext[i]]) canOdd[i] = true;
            if (evenNext[i] != -1 && canOdd[evenNext[i]]) canEven[i] = true;
        }
        int count = 0;
        for (boolean b : canOdd) if (b) count++;
        return count;
    }
}

