public class Solution {
    public static int uniquePathsIII(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int nonObstacles = 0;
        int startX = 0, startY = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    nonObstacles++;
                } else if (grid[i][j] == 1) {
                    startX = i;
                    startY = j;
                }
            }
        }
        int[] count = new int[1];
        backtrack(startX, startY, 0, grid, m, n, nonObstacles, count);
        return count[0];
    }

    private static void backtrack(int x, int y, int steps, int[][] grid, int m, int n, int nonObstacles, int[] count) {
        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] == -1 || grid[x][y] == -2) {
            return;
        }
        if (grid[x][y] == 2 && steps == nonObstacles + 1) {
            count[0]++;
        }
        int temp = grid[x][y];
        grid[x][y] = -2;
        backtrack(x + 1, y, steps + 1, grid, m, n, nonObstacles, count);
        backtrack(x - 1, y, steps + 1, grid, m, n, nonObstacles, count);
        backtrack(x, y + 1, steps + 1, grid, m, n, nonObstacles, count);
        backtrack(x, y - 1, steps + 1, grid, m, n, nonObstacles, count);
        grid[x][y] = temp;
    }
}

