class Solution {
    public static String stringWithoutAAAorBBB(int a, int b) {
        StringBuilder sb = new StringBuilder();
        while (a > 0 || b > 0) {
            if (a > 0 && (sb.length() < 2 || !(sb.charAt(sb.length() - 1) == 'a' && sb.charAt(sb.length() - 2) == 'a')) && feasible(a - 1, b)) {
                sb.append('a');
                a--;
            } else if (b > 0 && (sb.length() < 2 || !(sb.charAt(sb.length() - 1) == 'b' && sb.charAt(sb.length() - 2) == 'b')) && feasible(a, b - 1)) {
                sb.append('b');
                b--;
            } else if (a > 0) {
                sb.append('a');
                a--;
            } else {
                sb.append('b');
                b--;
            }
        }
        return sb.toString();
    }

    private static boolean feasible(int a, int b) {
        int max = Math.max(a, b);
        int min = Math.min(a, b);
        return max <= 2 * (min + 1);
    }
}

