class Solution {
    private static class Result {
        Integer parent;
        int depth;
        Result(Integer p, int d) {
            parent = p;
            depth = d;
        }
    }

    private static Result dfs(TreeNode node, Integer parent, int depth, int target) {
        if (node == null) return null;
        if (node.val == target) return new Result(parent, depth);
        Result left = dfs(node.left, node.val, depth + 1, target);
        if (left != null) return left;
        return dfs(node.right, node.val, depth + 1, target);
    }

    public static boolean isCousins(TreeNode root, int x, int y) {
        Result xRes = dfs(root, null, 0, x);
        Result yRes = dfs(root, null, 0, y);
        if (xRes == null || yRes == null) return false;
        boolean sameDepth = xRes.depth == yRes.depth;
        boolean differentParent = (xRes.parent == null ? yRes.parent != null : !xRes.parent.equals(yRes.parent));
        return sameDepth && differentParent;
    }
}

