class Solution {
    public static int minKBitFlips(int[] nums, int k) {
        int flips = 0;
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < nums.length; i++) {
            if (!queue.isEmpty() && queue.peekFirst() + k == i) {
                queue.pollFirst();
            }
            if ((nums[i] == 0 && queue.size() % 2 == 0) || (nums[i] == 1 && queue.size() % 2 == 1)) {
                if (i + k > nums.length) {
                    return -1;
                }
                queue.addLast(i);
                flips++;
            }
        }
        return flips;
    }
}

