public class Solution {
    private static int count;

    private static boolean isPerfectSquare(int num) {
        int r = (int) Math.sqrt(num);
        return r * r == num;
    }

    private static void backtrack(int[] nums, boolean[] used, int depth, int prev) {
        if (depth == nums.length) {
            count++;
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
            if (depth > 0 && !isPerfectSquare(prev + nums[i])) continue;
            used[i] = true;
            backtrack(nums, used, depth + 1, nums[i]);
            used[i] = false;
        }
    }

    public static int numSquarefulPerms(int[] nums) {
        Arrays.sort(nums);
        count = 0;
        boolean[] used = new boolean[nums.length];
        backtrack(nums, used, 0, 0);
        return count;
    }
}

