class Solution {
    public static List<String> findCommonCharacters(String[] words) {
        if (words == null || words.length == 0) {
            return new ArrayList<>();
        }
        Map<Character, Integer> commonChars = new HashMap<>();
        for (char c : words[0].toCharArray()) {
            commonChars.put(c, commonChars.getOrDefault(c, 0) + 1);
        }
        for (int i = 1; i < words.length; i++) {
            Map<Character, Integer> currentWord = new HashMap<>();
            for (char c : words[i].toCharArray()) {
                currentWord.put(c, currentWord.getOrDefault(c, 0) + 1);
            }
            Iterator<Map.Entry<Character, Integer>> it = commonChars.entrySet().iterator();
            while (it.hasNext()) {
                Map.Entry<Character, Integer> entry = it.next();
                char c = entry.getKey();
                if (currentWord.containsKey(c)) {
                    entry.setValue(Math.min(entry.getValue(), currentWord.get(c)));
                } else {
                    it.remove();
                }
            }
        }
        List<String> result = new ArrayList<>();
        for (Map.Entry<Character, Integer> entry : commonChars.entrySet()) {
            char c = entry.getKey();
            int count = entry.getValue();
            for (int i = 0; i < count; i++) {
                result.add(String.valueOf(c));
            }
        }
        return result;
    }
}

