class Solution {
    public static int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Set<String> lampSet = new HashSet<>();
        for (int[] lamp : lamps) {
            lampSet.add(lamp[0] + "," + lamp[1]);
        }
        int[] rowCounts = new int[n];
        int[] colCounts = new int[n];
        int[] diagonal1Counts = new int[2 * n - 1];
        int[] diagonal2Counts = new int[2 * n - 1];
        for (int[] lamp : lamps) {
            int row = lamp[0];
            int col = lamp[1];
            rowCounts[row]++;
            colCounts[col]++;
            diagonal1Counts[row + col]++;
            diagonal2Counts[row - col + n - 1]++;
        }
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int row = queries[i][0];
            int col = queries[i][1];
            result[i] = (rowCounts[row] > 0 || colCounts[col] > 0 || diagonal1Counts[row + col] > 0 || diagonal2Counts[row - col + n - 1] > 0) ? 1 : 0;
            for (int r = Math.max(0, row - 1); r <= Math.min(n - 1, row + 1); r++) {
                for (int c = Math.max(0, col - 1); c <= Math.min(n - 1, col + 1); c++) {
                    String key = r + "," + c;
                    if (lampSet.contains(key)) {
                        lampSet.remove(key);
                        rowCounts[r]--;
                        colCounts[c]--;
                        diagonal1Counts[r + c]--;
                        diagonal2Counts[r - c + n - 1]--;
                    }
                }
            }
        }
        return result;
    }
}

