public class Solution {
    public static int clumsy(int n) {
        List<Object> stack = new ArrayList<>();
        stack.add(n);
        n--;
        String[] operations = {"*", "/", "+", "-"};
        int opIndex = 0;
        while (n > 0) {
            String operation = operations[opIndex % 4];
            if (operation.equals("*")) {
                int top = (int) stack.remove(stack.size() - 1);
                stack.add(top * n);
            } else if (operation.equals("/")) {
                int top = (int) stack.remove(stack.size() - 1);
                stack.add(top / n);
            } else {
                stack.add(operation.charAt(0));
                stack.add(n);
            }
            opIndex++;
            n--;
        }
        int result = (int) stack.get(0);
        for (int i = 1; i < stack.size(); i += 2) {
            char op = (char) stack.get(i);
            int num = (int) stack.get(i + 1);
            if (op == '+') {
                result += num;
            } else {
                result -= num;
            }
        }
        return result;
    }
}

