class Solution {
    public int[] nextLargerNodes(ListNode head) {
        List<Integer> values = new ArrayList<>();
        ListNode currentNode = head;
        while (currentNode != null) {
            values.add(currentNode.val);
            currentNode = currentNode.next;
        }
        int n = values.size();
        int[] result = new int[n];
        int[] stack = new int[n];
        int stackSize = 0;
        for (int i = 0; i < n; i++) {
            while (stackSize > 0 && values.get(stack[stackSize - 1]) < values.get(i)) {
                result[stack[--stackSize]] = values.get(i);
            }
            stack[stackSize++] = i;
        }
        return result;
    }
}

