class Solution {
    public static int numEnclaves(int[][] grid) {
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int rows = grid.length;
        int cols = grid[0].length;
        for (int i = 0; i < rows; i++) {
            dfs(grid, i, 0, rows, cols, directions);
            dfs(grid, i, cols - 1, rows, cols, directions);
        }
        for (int j = 0; j < cols; j++) {
            dfs(grid, 0, j, rows, cols, directions);
            dfs(grid, rows - 1, j, rows, cols, directions);
        }
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                count += grid[i][j];
            }
        }
        return count;
    }

    private static void dfs(int[][] grid, int row, int col, int rows, int cols, int[][] directions) {
        if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] == 0) {
            return;
        }
        grid[row][col] = 0;
        for (int[] dir : directions) {
            dfs(grid, row + dir[0], col + dir[1], rows, cols, directions);
        }
    }
}

