    public static TreeNode recoverFromPreorder(String traversal) {
        index = 0;
        return dfs(0, traversal);
    }
    private static TreeNode dfs(int depth, String traversal) {
        int value = 0;
        while (index < traversal.length() && traversal.charAt(index) != '-') {
            value = value * 10 + (traversal.charAt(index) - '0');
            index++;
        }
        TreeNode node = new TreeNode(value);
        while (index < traversal.length()) {
            int save = index;
            int childDepth = 0;
            while (index < traversal.length() && traversal.charAt(index) == '-') {
                childDepth++;
                index++;
            }
            if (childDepth == depth + 1) {
                if (node.left == null) {
                    node.left = dfs(childDepth, traversal);
                } else {
                    node.right = dfs(childDepth, traversal);
                }
            } else {
                index = save;
                break;
            }
        }
        return node;
    }
}

