class Solution {
    public static int[][] colorBorder(int[][] grid, int row, int col, int color) {
        int componentColor = grid[row][col];
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        Set<String> visited = new HashSet<>();
        Set<String> border = new HashSet<>();
        dfs(row, col, grid, componentColor, directions, visited, border);
        for (String coord : border) {
            String[] parts = coord.split(",");
            int r = Integer.parseInt(parts[0]);
            int c = Integer.parseInt(parts[1]);
            grid[r][c] = color;
        }
        return grid;
    }

    private static void dfs(int r, int c, int[][] grid, int componentColor, int[][] directions,
                            Set<String> visited, Set<String> border) {
        visited.add(r + "," + c);
        boolean isBorder = r == 0 || r == grid.length - 1 || c == 0 || c == grid[0].length - 1;
        if (!isBorder) {
            for (int[] d : directions) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length ||
                    grid[nr][nc] != componentColor) {
                    isBorder = true;
                    break;
                }
            }
        }
        if (isBorder) {
            border.add(r + "," + c);
        }
        for (int[] d : directions) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length &&
                grid[nr][nc] == componentColor && !visited.contains(nr + "," + nc)) {
                dfs(nr, nc, grid, componentColor, directions, visited, border);
            }
        }
    }
}

