class Solution {
    public static int maxUncrossedLines(int[] nums1, int[] nums2) {
        Map<String, Integer> memo = new HashMap<>();
        return dp(0, 0, nums1, nums2, memo);
    }

    private static int dp(int i, int j, int[] nums1, int[] nums2, Map<String, Integer> memo) {
        String key = i + "," + j;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        if (i == nums1.length || j == nums2.length) {
            return 0;
        }
        if (nums1[i] == nums2[j]) {
            int result = 1 + dp(i + 1, j + 1, nums1, nums2, memo);
            memo.put(key, result);
            return result;
        }
        int result = Math.max(dp(i + 1, j, nums1, nums2, memo), dp(i, j + 1, nums1, nums2, memo));
        memo.put(key, result);
        return result;
    }
}

