class Solution {
    public static int minScoreTriangulation(int[] values) {
        int n = values.length;
        int[][] dp = new int[n][n];
        for (int length = 2; length < n; length++) {
            for (int i = 0; i < n - length; i++) {
                int j = i + length;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i + 1; k < j; k++) {
                    long candidate = (long) dp[i][k] + dp[k][j] + (long) values[i] * values[k] * values[j];
                    if (candidate < dp[i][j]) {
                        dp[i][j] = (int) candidate;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

