        Arrays.sort(stones);
        int n = stones.length;
        int maxMoves = Math.max(stones[n - 1] - stones[1] - n + 2, stones[n - 2] - stones[0] - n + 2);
        int maxInWindow = 0;
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (j < n && stones[j] - stones[i] + 1 <= n) {
                j++;
            }
            maxInWindow = Math.max(maxInWindow, j - i);
        }
        int minMoves;
        if (maxInWindow == n) {
            minMoves = 0;
        } else if (maxInWindow == n - 1) {
            boolean special = (stones[n - 2] - stones[0] == n - 2 && stones[n - 1] - stones[n - 2] > 2) ||
                               (stones[n - 1] - stones[1] == n - 2 && stones[1] - stones[0] > 2);
            minMoves = special ? 2 : 1;
        } else {
            minMoves = n - maxInWindow;
        }
        return new int[]{minMoves, maxMoves};
    }
}

import java.util.*;

class Solution {
    public static boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<String> blockedSet = new HashSet<>();
        for (int[] b : blocked) {
            blockedSet.add(b[0] + "," + b[1]);
        }
        int limit = blocked.length * (blocked.length - 1) / 2;
        return bfs(source, target, blockedSet, limit) && bfs(target, source, blockedSet, limit);
    }

    private static boolean bfs(int[] start, int[] goal, Set<String> blockedSet, int limit) {
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        Queue<int[]> q = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        q.offer(start);
        visited.add(start[0] + "," + start[1]);
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (cur[0] == goal[0] && cur[1] == goal[1]) {
                return true;
            }
            if (visited.size() > limit) {
                return true;
            }
            for (int[] d : dirs) {
                int nx = cur[0] + d[0];
                int ny = cur[1] + d[1];
                if (nx >= 0 && nx < 1_000_000 && ny >= 0 && ny < 1_000_000) {
                    String key = nx + "," + ny;
                    if (!blockedSet.contains(key) && !visited.contains(key)) {
                        visited.add(key);
                        q.offer(new int[]{nx, ny});
                    }
                }
            }
        }
        return false;
    }
}

