class Solution {
    public static int[] gardenNoAdj(int n, int[][] paths) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : paths) {
            int x = edge[0] - 1;
            int y = edge[1] - 1;
            graph[x].add(y);
            graph[y].add(x);
        }
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            boolean[] used = new boolean[5];
            for (int neighbor : graph[i]) {
                used[result[neighbor]] = true;
            }
            for (int j = 1; j <= 4; j++) {
                if (!used[j]) {
                    result[i] = j;
                    break;
                }
            }
        }
        return result;
    }
}

