class Solution {
    public static String longestDupSubstring(String s) {
        int left = 1, right = s.length();
        String longest = "";
        while (left <= right) {
            int mid = (left + right) / 2;
            Set<String> set = new HashSet<>();
            boolean found = false;
            for (int i = 0; i <= s.length() - mid; i++) {
                String substr = s.substring(i, i + mid);
                if (set.contains(substr)) {
                    longest = substr;
                    found = true;
                    break;
                }
                set.add(substr);
            }
            if (found) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return longest;
    }
}

