class Solution {
    public static int numberOfSubmatricesThatSumToTarget(int[][] matrix, int target) {
        int count = 0;
        int rows = matrix.length;
        int cols = matrix[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                matrix[i][j] += matrix[i][j - 1];
            }
        }
        for (int left = 0; left < cols; left++) {
            for (int right = left; right < cols; right++) {
                Map<Integer, Integer> sumMap = new HashMap<>();
                sumMap.put(0, 1);
                int currentSum = 0;
                for (int i = 0; i < rows; i++) {
                    currentSum += matrix[i][right] - (left > 0 ? matrix[i][left - 1] : 0);
                    count += sumMap.getOrDefault(currentSum - target, 0);
                    sumMap.put(currentSum, sumMap.getOrDefault(currentSum, 0) + 1);
                }
            }
        }
        return count;
    }
}

