class Solution {
    public static int numTilePossibilities(String tiles) {
        int[] count = new int[1];
        Map<Character, Integer> tileCounts = new HashMap<>();
        for (char tile : tiles.toCharArray()) {
            tileCounts.put(tile, tileCounts.getOrDefault(tile, 0) + 1);
        }
        backtrack(tileCounts, count);
        return count[0];
    }

    private static void backtrack(Map<Character, Integer> tileCounts, int[] count) {
        for (Map.Entry<Character, Integer> entry : tileCounts.entrySet()) {
            int val = entry.getValue();
            if (val > 0) {
                count[0]++;
                entry.setValue(val - 1);
                backtrack(tileCounts, count);
                entry.setValue(val);
            }
        }
    }
}

