class Solution {
    public static int[] duplicateZeros(int[] arr) {
        int n = arr.length;
        int possibleDups = 0;
        int i = 0;
        while (i + possibleDups < n) {
            if (arr[i] == 0) {
                if (i + possibleDups == n - 1) {
                    arr[n - 1] = 0;
                    n -= 1;
                    break;
                }
                possibleDups++;
            }
            i++;
        }
        int last = n - 1 - possibleDups;
        for (int j = last; j >= 0; j--) {
            if (arr[j] == 0) {
                arr[j + possibleDups] = 0;
                possibleDups--;
                arr[j + possibleDups] = 0;
            } else {
                arr[j + possibleDups] = arr[j];
            }
        }
        return arr;
    }
}

