class Solution {
    public static double[] sampleStatistics(int[] count) {
        int min = -1, max = -1;
        long sum = 0;
        long total = 0;
        int mode = 0;
        int maxCount = 0;
        for (int i = 0; i < count.length; i++) {
            if (count[i] > 0) {
                if (min == -1) min = i;
                max = i;
                sum += (long) i * count[i];
                total += count[i];
                if (count[i] > maxCount) {
                    maxCount = count[i];
                    mode = i;
                }
            }
        }
        double mean = (double) sum / total;
        double median;
        long leftPos = (total + 1) / 2;
        long rightPos = (total % 2 == 0) ? (total / 2 + 1) : leftPos;
        long cumulative = 0;
        int leftVal = 0, rightVal = 0;
        for (int i = 0; i < count.length; i++) {
            cumulative += count[i];
            if (cumulative >= leftPos && leftVal == 0) leftVal = i;
            if (cumulative >= rightPos) {
                rightVal = i;
                break;
            }
        }
        median = (leftVal + rightVal) / 2.0;
        mean = Math.round(mean * 100000.0) / 100000.0;
        median = Math.round(median * 100000.0) / 100000.0;
        return new double[]{min, max, mean, median, mode};
    }
}

