        return new ArrayList<>(new TreeSet<>(result));
    }

    private static Set<String> parseExpression(String s, int[] idx) {
        Set<String> result = parseTerm(s, idx);
        while (idx[0] < s.length() && s.charAt(idx[0]) == ',') {
            idx[0]++;
            Set<String> next = parseTerm(s, idx);
            result.addAll(next);
        }
        return result;
    }

    private static Set<String> parseTerm(String s, int[] idx) {
        Set<String> result = new LinkedHashSet<>();
        result.add("");
        while (idx[0] < s.length() && s.charAt(idx[0]) != '}' && s.charAt(idx[0]) != ',') {
            Set<String> factor = parseFactor(s, idx);
            Set<String> newResult = new LinkedHashSet<>();
            for (String prefix : result) {
                for (String suffix : factor) {
                    newResult.add(prefix + suffix);
                }
            }
            result = newResult;
        }
        return result;
    }

    private static Set<String> parseFactor(String s, int[] idx) {
        char ch = s.charAt(idx[0]);
        if (ch == '{') {
            idx[0]++;
            Set<String> inner = parseExpression(s, idx);
            idx[0]++; // skip '}'
            return inner;
        } else {
            idx[0]++;
            return Collections.singleton(String.valueOf(ch));
        }
    }
}

