class Solution {
    public static int[] distributeCandies(int candies, int num_people) {
        int[] distribution = new int[num_people];
        int i = 0;
        int candyCount = 1;
        while (candies > 0) {
            int give = Math.min(candies, candyCount);
            distribution[i] += give;
            candies -= give;
            i = (i + 1) % num_people;
            candyCount++;
        }
        return distribution;
    }
}

