class Solution {
    public static List<Integer> pathInZigZagTree(int label) {
        LinkedList<Integer> path = new LinkedList<>();
        while (label >= 1) {
            path.addFirst(label);
            if (label == 1) {
                break;
            }
            int level = 32 - Integer.numberOfLeadingZeros(label);
            int left = 1 << (level - 1);
            int right = (1 << level) - 1;
            label = (left + right - label) / 2;
        }
        return path;
    }
}

