class Solution {
    public static int minHeightShelves(int[][] books, int shelfWidth) {
        int n = books.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int currWidth = 0;
            int currHeight = 0;
            for (int j = i - 1; j >= 0; j--) {
                currWidth += books[j][0];
                if (currWidth > shelfWidth) {
                    break;
                }
                currHeight = Math.max(currHeight, books[j][1]);
                dp[i] = Math.min(dp[i], dp[j] + currHeight);
            }
        }
        return dp[n];
    }
}

