import java.util.*;

class Solution {
    public static boolean parseBoolExpr(String expression) {
        if (expression.length() == 1) {
            return expression.equals("t");
        }
        char operator = expression.charAt(0);
        List<String> operands = new ArrayList<>();
        StringBuilder temp = new StringBuilder();
        int count = 0;
        for (int i = 2; i < expression.length() - 1; i++) {
            char c = expression.charAt(i);
            if (c == '(') {
                count++;
                temp.append(c);
            } else if (c == ')') {
                count--;
                temp.append(c);
            } else if (c == ',' && count == 0) {
                operands.add(temp.toString());
                temp.setLength(0);
            } else {
                temp.append(c);
            }
        }
        operands.add(temp.toString());
        if (operator == '!') {
            return !parseBoolExpr(operands.get(0));
        } else if (operator == '&') {
            for (String operand : operands) {
                if (!parseBoolExpr(operand)) {
                    return false;
                }
            }
            return true;
        } else { // operator == '|'
            for (String operand : operands) {
                if (parseBoolExpr(operand)) {
                    return true;
                }
            }
            return false;
        }
    }
}

