class Solution {
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        List<TreeNode> result = new ArrayList<>();
        Set<Integer> set = new HashSet<>();
        for (int v : to_delete) set.add(v);
        TreeNode newRoot = dfs(root, set, result);
        if (newRoot != null) result.add(newRoot);
        return result;
    }

    private TreeNode dfs(TreeNode node, Set<Integer> set, List<TreeNode> result) {
        if (node == null) return null;
        if (set.contains(node.val)) {
            TreeNode left = dfs(node.left, set, result);
            TreeNode right = dfs(node.right, set, result);
            if (left != null) result.add(left);
            if (right != null) result.add(right);
            return null;
        } else {
            node.left = dfs(node.left, set, result);
            node.right = dfs(node.right, set, result);
            return node;
        }
    }
}

