class Solution {
    static class Wrapper {
        int maxDepth = -1;
        TreeNode lca = null;
    }
    public static TreeNode lcaDeepestLeaves(TreeNode root) {
        Wrapper w = new Wrapper();
        dfs(root, 0, w);
        return w.lca;
    }
    private static void dfs(TreeNode node, int depth, Wrapper w) {
        if (node == null) return;
        if (node.left == null && node.right == null && depth > w.maxDepth) {
            w.maxDepth = depth;
            w.lca = node;
        }
        if (node.left != null) dfs(node.left, depth + 1, w);
        if (node.right != null) dfs(node.right, depth + 1, w);
        if (node.left != null && node.right != null && depth + 1 == w.maxDepth) {
            w.lca = node;
        }
    }
}

