class Solution {
    public static int longestWPI(int[] hours) {
        int n = hours.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + (hours[i] > 8 ? 1 : -1);
        }
        int[] stack = new int[n + 1];
        int top = 0;
        for (int i = 0; i <= n; i++) {
            if (top == 0 || pref[i] < pref[stack[top - 1]]) {
                stack[top++] = i;
            }
        }
        int max = 0;
        for (int i = n; i >= 0; i--) {
            while (top > 0 && pref[i] > pref[stack[top - 1]]) {
                max = Math.max(max, i - stack[top - 1]);
                top--;
            }
        }
        return max;
    }
}

import java.util.*;

class Solution {
    public static int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int n = req_skills.length;
        int m = people.size();
        Map<String, Integer> skillToIndex = new HashMap<>();
        for (int i = 0; i < n; i++) {
            skillToIndex.put(req_skills[i], i);
        }
        @SuppressWarnings("unchecked")
        List<Integer>[][] dp = new ArrayList[1 << n][m + 1];
        for (int i = 0; i < m; i++) {
            int skillSet = getSkillSet(people.get(i), skillToIndex);
            dp[skillSet][i] = new ArrayList<>(Arrays.asList(i));
        }
        for (int mask = 0; mask < (1 << n); mask++) {
            for (int i = 0; i < m; i++) {
                if (dp[mask][i] == null) continue;
                for (int j = i + 1; j < m; j++) {
                    int newMask = mask | getSkillSet(people.get(j), skillToIndex);
                    if (dp[newMask][j + 1] == null || dp[newMask][j + 1].size() > dp[mask][i].size() + 1) {
                        dp[newMask][j + 1] = new ArrayList<>(dp[mask][i]);
                        dp[newMask][j + 1].add(j);
                    }
                }
            }
        }
        int fullMask = (1 << n) - 1;
        int minSize = Integer.MAX_VALUE;
        List<Integer> result = null;
        for (int i = 0; i <= m; i++) {
            if (dp[fullMask][i] != null && dp[fullMask][i].size() < minSize) {
                minSize = dp[fullMask][i].size();
                result = dp[fullMask][i];
            }
        }
        int[] ans = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            ans[i] = result.get(i);
        }
        return ans;
    }

    private static int getSkillSet(List<String> personSkills, Map<String, Integer> skillToIndex) {
        int mask = 0;
        for (String skill : personSkills) {
            Integer idx = skillToIndex.get(skill);
            if (idx != null) {
                mask |= (1 << idx);
            }
        }
        return mask;
    }
}

