import java.util.Deque;

public class Solution {
    public static int mctFromLeafValues(int[] arr) {
        long result = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(Integer.MAX_VALUE);
        for (int num : arr) {
            while (stack.peek() <= num) {
                int mid = stack.pop();
                int left = stack.peek();
                result += (long) mid * Math.min(left, num);
            }
            stack.push(num);
        }
        while (stack.size() > 2) {
            int top = stack.pop();
            int next = stack.peek();
            result += (long) top * next;
        }
        return (int) result;
    }
}

