            }
            if (ny > curY) {
                for (int k = 0; k < ny - curY; k++) sb.append('R');
            }
            sb.append('!');
            curX = nx;
            curY = ny;
        }
        return sb.toString();
    }
}

import java.util.Arrays;

class Solution {
    public static int stoneGameII(int[] piles) {
        int n = piles.length;
        int[] suffixSum = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixSum[i] = suffixSum[i + 1] + piles[i];
        }
        int[][] memo = new int[n][n + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(memo[i], -1);
        }
        return dp(0, 1, n, suffixSum, memo);
    }

    private static int dp(int i, int m, int n, int[] suffixSum, int[][] memo) {
        if (i + 2 * m >= n) {
            return suffixSum[i];
        }
        if (memo[i][m] != -1) {
            return memo[i][m];
        }
        int best = Integer.MIN_VALUE;
        for (int x = 1; x <= 2 * m; x++) {
            int opponent = dp(i + x, Math.max(m, x), n, suffixSum, memo);
            int current = suffixSum[i] - opponent;
            if (current > best) {
                best = current;
            }
        }
        memo[i][m] = best;
        return best;
    }
}

import java.lang.Math;

class Solution {
    public static long movesToMakeZigzag(int[] nums) {
        long movesEvenValley = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i % 2 == 0) {
                int left = i > 0 ? nums[i - 1] : Integer.MAX_VALUE;
                int right = i < nums.length - 1 ? nums[i + 1] : Integer.MAX_VALUE;
                int minNeighbor = Math.min(left, right);
                if (nums[i] >= minNeighbor) {
                    movesEvenValley += (long) (nums[i] - minNeighbor + 1);
                }
            }
        }
        long movesOddValley = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i % 2 == 1) {
                int left = i > 0 ? nums[i - 1] : Integer.MAX_VALUE;
                int right = i < nums.length - 1 ? nums[i + 1] : Integer.MAX_VALUE;
                int minNeighbor = Math.min(left, right);
                if (nums[i] >= minNeighbor) {
                    movesOddValley += (long) (nums[i] - minNeighbor + 1);
                }
            }
        }
        return Math.min(movesEvenValley, movesOddValley);
    }
}

public class Solution {
    public static int longestCommonSubsequence(String text1, String text2) {
        int[][] dp = new int[text1.length() + 1][text2.length() + 1];
        for (int i = 1; i <= text1.length(); i++) {
            for (int j = 1; j <= text2.length(); j++) {
                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }
        return dp[text1.length()][text2.length()];
    }
}

