class Solution {
    public static int longestDecomposition(String text) {
        int left = 0;
        int right = text.length() - 1;
        int count = 0;
        while (left <= right) {
            boolean found = false;
            int maxLen = (right - left + 1) / 2;
            for (int len = 1; len <= maxLen; len++) {
                boolean equal = true;
                for (int k = 0; k < len; k++) {
                    if (text.charAt(left + k) != text.charAt(right - len + 1 + k)) {
                        equal = false;
                        break;
                    }
                }
                if (equal) {
                    count += 2;
                    left += len;
                    right -= len;
                    found = true;
                    break;
                }
            }
            if (!found) {
                count++;
                break;
            }
        }
        return count;
    }
}

public static boolean btreeGameWinningMove(TreeNode root, int n, int x) {
    TreeNode target = findTarget(root, x);
    int leftCount = countSize(target.left);
    int rightCount = countSize(target.right);
    int parentCount = n - leftCount - rightCount - 1;
    double half = n / 2.0;
    return leftCount > half || rightCount > half || parentCount > half;
}
private static TreeNode findTarget(TreeNode node, int x) {
    if (node == null) return null;
    if (node.val == x) return node;
    TreeNode left = findTarget(node.left, x);
    if (left != null) return left;
    return findTarget(node.right, x);
}
private static int countSize(TreeNode node) {
    if (node == null) return 0;
    return 1 + countSize(node.left) + countSize(node.right);
}

