public class Solution {
    public static class SnapshotArray {
        private int currentId;
        private Map<Integer, List<int[]>> snapshots;
        public SnapshotArray(int length) {
            currentId = 0;
            snapshots = new HashMap<>();
            for (int i = 0; i < length; i++) {
                snapshots.put(i, new ArrayList<>());
            }
        }
        public void set(int index, int val) {
            snapshots.get(index).add(new int[]{currentId, val});
        }
        public int snap() {
            currentId++;
            return currentId - 1;
        }
        public int get(int index, int snap_id) {
            List<int[]> values = snapshots.get(index);
            int left = 0, right = values.size() - 1;
            while (left <= right) {
                int mid = (left + right) >>> 1;
                if (values.get(mid)[0] <= snap_id) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            return right >= 0 ? values.get(right)[1] : 0;
        }
    }
}

