class Solution {
    public static BiFunction<Integer, Integer, Integer> MajorityChecker(final int[] arr, final int threshold) {
        return (left, right) -> {
            Map<Integer, Integer> counts = new HashMap<>();
            for (int i = left; i <= right; i++) {
                int val = arr[i];
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                if (entry.getValue() >= threshold) {
                    return entry.getKey();
                }
            }
            return -1;
        };
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int countCharacters(String[] words, String chars) {
        int totalLength = 0;
        Map<Character, Integer> charsCount = new HashMap<>();
        for (char c : chars.toCharArray()) {
            charsCount.put(c, charsCount.getOrDefault(c, 0) + 1);
        }
        for (String word : words) {
            Map<Character, Integer> wordCount = new HashMap<>();
            boolean canBeFormed = true;
            for (char c : word.toCharArray()) {
                wordCount.put(c, wordCount.getOrDefault(c, 0) + 1);
                if (wordCount.get(c) > charsCount.getOrDefault(c, 0)) {
                    canBeFormed = false;
                    break;
                }
            }
            if (canBeFormed) {
                totalLength += word.length();
            }
        }
        return totalLength;
    }
}

