import java.lang.Math;

class Solution {
    public static int largest1BorderedSquare(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int maxSideLength = Math.min(rows, cols);
        int maxArea = 0;
        for (int sideLength = 1; sideLength <= maxSideLength; sideLength++) {
            for (int i = 0; i <= rows - sideLength; i++) {
                for (int j = 0; j <= cols - sideLength; j++) {
                    if (hasAllOnesOnBorder(grid, i, j, sideLength)) {
                        maxArea = Math.max(maxArea, sideLength * sideLength);
                    }
                }
            }
        }
        return maxArea;
    }

    private static boolean hasAllOnesOnBorder(int[][] grid, int row, int col, int side) {
        int endRow = row + side - 1;
        int endCol = col + side - 1;
        for (int c = col; c <= endCol; c++) {
            if (grid[row][c] != 1 || grid[endRow][c] != 1) {
                return false;
            }
        }
        for (int r = row + 1; r < endRow; r++) {
            if (grid[r][col] != 1 || grid[r][endCol] != 1) {
                return false;
            }
        }
        return true;
    }
}

