class Solution {
    public static List<Boolean> canMakePali(String s, int[][] queries) {
        List<Boolean> result = new ArrayList<>();
        for (int[] query : queries) {
            String substring = s.substring(query[0], query[1] + 1);
            int k = query[2];
            result.add(isPaliPossible(substring, k));
        }
        return result;
    }

    private static boolean isPaliPossible(String substring, int k) {
        Map<Character, Integer> charCount = new HashMap<>();
        for (char ch : substring.toCharArray()) {
            charCount.put(ch, charCount.getOrDefault(ch, 0) + 1);
        }
        int oddCount = 0;
        for (int count : charCount.values()) {
            if ((count & 1) != 0) oddCount++;
        }
        // minimum replacements needed = oddCount / 2 (integer division)
        return oddCount / 2 <= k;
    }
}

