class Solution {
    public static int numPrimeArrangements(int n) {
        long mod = 1000000007L;
        int primeCount = 0;
        for (int i = 1; i <= n; i++) {
            if (isPrime(i)) primeCount++;
        }
        long primePermutations = 1;
        long nonPrimePermutations = 1;
        for (int i = 1; i <= primeCount; i++) {
            primePermutations = (primePermutations * i) % mod;
        }
        for (int i = 1; i <= n - primeCount; i++) {
            nonPrimePermutations = (nonPrimePermutations * i) % mod;
        }
        return (int) ((primePermutations * nonPrimePermutations) % mod);
    }

    private static boolean isPrime(int num) {
        if (num <= 1) return false;
        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

