class Solution {
    public static int[] findNumOfValidWords(String[] words, String[] puzzles) {
        int[] result = new int[puzzles.length];
        Map<Integer, Integer> wordMap = new HashMap<>();
        for (String word : words) {
            int bitmask = 0;
            for (int i = 0; i < word.length(); i++) {
                char c = word.charAt(i);
                bitmask |= 1 << (c - 'a');
            }
            wordMap.put(bitmask, wordMap.getOrDefault(bitmask, 0) + 1);
        }
        for (int i = 0; i < puzzles.length; i++) {
            int puzzleBitmask = 0;
            String puzzle = puzzles[i];
            for (int j = 0; j < puzzle.length(); j++) {
                char c = puzzle.charAt(j);
                puzzleBitmask |= 1 << (c - 'a');
            }
            int submask = puzzleBitmask;
            int firstLetterMask = 1 << (puzzle.charAt(0) - 'a');
            while (submask > 0) {
                if (wordMap.containsKey(submask) && (submask & firstLetterMask) != 0) {
                    result[i] += wordMap.get(submask);
                }
                submask = (submask - 1) & puzzleBitmask;
            }
        }
        return result;
    }
}

class Solution {
    public static int distanceBetweenBusStops(int[] distance, int start, int destination) {
        if (start > destination) {
            int temp = start;
            start = destination;
            destination = temp;
        }
        int clockwiseDistance = 0;
        for (int i = start; i < destination; i++) {
            clockwiseDistance += distance[i];
        }
        int totalDistance = 0;
        for (int i = 0; i < distance.length; i++) {
            totalDistance += distance[i];
        }
        int counterclockwiseDistance = totalDistance - clockwiseDistance;
        return Math.min(clockwiseDistance, counterclockwiseDistance);
    }
}

import java.util.*;

class DinnerPlates {
    private final int capacity;
    private final List<List<Integer>> stacks;
    private final PriorityQueue<Integer> available; // min-heap, lazy deletion of stale/full entries

    public DinnerPlates(int capacity) {
        this.capacity = capacity;
        this.stacks = new ArrayList<>();
        this.available = new PriorityQueue<>();
    }

    public void push(int val) {
        while (!available.isEmpty() && (available.peek() >= stacks.size() || stacks.get(available.peek()).size() >= capacity)) {
            available.poll();
        }
        if (available.isEmpty()) {
            List<Integer> newStack = new ArrayList<>();
            newStack.add(val);
            stacks.add(newStack);
            if (capacity > 1) available.add(stacks.size() - 1);
        } else {
            int idx = available.peek();
            stacks.get(idx).add(val);
            if (stacks.get(idx).size() >= capacity) available.poll();
        }
    }

    public int pop() {
        while (!stacks.isEmpty() && stacks.get(stacks.size() - 1).isEmpty()) stacks.remove(stacks.size() - 1);
        if (stacks.isEmpty()) return -1;
        return popAtStack(stacks.size() - 1);
    }

    public int popAtStack(int index) {
        if (index >= stacks.size() || stacks.get(index).isEmpty()) return -1;
        boolean wasFull = stacks.get(index).size() == capacity;
        int val = stacks.get(index).remove(stacks.get(index).size() - 1);
        if (wasFull) available.add(index);
        while (!stacks.isEmpty() && stacks.get(stacks.size() - 1).isEmpty()) stacks.remove(stacks.size() - 1);
        return val;
    }
}

