class Solution {
    public static String reverseParentheses(String s) {
        Deque<StringBuilder> stack = new ArrayDeque<>();
        stack.push(new StringBuilder());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                stack.push(new StringBuilder());
            } else if (c == ')') {
                StringBuilder reversed = stack.pop();
                reversed.reverse();
                stack.peek().append(reversed);
            } else {
                stack.peek().append(c);
            }
        }
        return stack.peek().toString();
    }
}

public class Solution {
    public static int maximumSum(int[] arr) {
        int n = arr.length;
        int[] forward = new int[n];
        int[] backward = new int[n];
        int maxSum = arr[0];
        forward[0] = arr[0];
        for (int i = 1; i < n; i++) {
            forward[i] = Math.max(arr[i], forward[i - 1] + arr[i]);
            maxSum = Math.max(maxSum, forward[i]);
        }
        backward[n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            backward[i] = Math.max(arr[i], backward[i + 1] + arr[i]);
            maxSum = Math.max(maxSum, backward[i]);
        }
        for (int i = 1; i < n - 1; i++) {
            maxSum = Math.max(maxSum, forward[i - 1] + backward[i + 1]);
        }
        return maxSum;
    }
}

import java.lang.*;

class Solution {
    public static int kConcatenationMaxSum(int[] arr, int k) {
        long MOD = 1_000_000_007L;
        long total = 0;
        for (int v : arr) total += v;
        long maxSub = Long.MIN_VALUE;
        long cur = 0;
        for (int v : arr) {
            cur = Math.max((long) v, cur + v);
            maxSub = Math.max(maxSub, cur);
        }
        long maxPrefix = Long.MIN_VALUE;
        cur = 0;
        for (int v : arr) {
            cur += v;
            maxPrefix = Math.max(maxPrefix, cur);
        }
        long maxSuffix = Long.MIN_VALUE;
        cur = 0;
        for (int i = arr.length - 1; i >= 0; i--) {
            cur += arr[i];
            maxSuffix = Math.max(maxSuffix, cur);
        }
        long answer;
        if (k == 1) {
            answer = maxSub;
        } else {
            long combined = maxSuffix + maxPrefix;
            if (total > 0) {
                combined += (long) (k - 2) * total;
            }
            answer = Math.max(maxSub, combined);
        }
        answer = Math.max(0, answer);
        answer %= MOD;
        return (int) answer;
    }
}

class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        int[] sorted2 = Arrays.stream(arr2).distinct().sorted().toArray();
        long NEG_INF = Long.MIN_VALUE;
        // dp maps "last value placed" -> minimum operations to reach a valid strictly-increasing
        // prefix ending in that value
        Map<Long, Integer> dp = new HashMap<>();
        dp.put(NEG_INF, 0);
        for (int num : arr1) {
            Map<Long, Integer> newDp = new HashMap<>();
            for (Map.Entry<Long, Integer> entry : dp.entrySet()) {
                long prev = entry.getKey();
                int ops = entry.getValue();
                if (num > prev) {
                    newDp.merge((long) num, ops, Math::min); // keep original value, no operation
                }
                int idx = upperBound(sorted2, prev);
                if (idx < sorted2.length) {
                    long repl = sorted2[idx]; // smallest arr2 value strictly greater than prev
                    newDp.merge(repl, ops + 1, Math::min); // replace with it, costs 1 operation
                }
            }
            if (newDp.isEmpty()) return -1;
            dp = newDp;
        }
        return Collections.min(dp.values());
    }

    private int upperBound(int[] arr, long x) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] <= x) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

