class Solution {
    public static List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (List<Integer> edge : connections) {
            int u = edge.get(0);
            int v = edge.get(1);
            graph[u].add(v);
            graph[v].add(u);
        }

        boolean[] visited = new boolean[n];
        int[] low = new int[n];
        int[] disc = new int[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        List<List<Integer>> critical = new ArrayList<>();
        int[] time = new int[]{0};

        dfs(0, graph, visited, disc, low, parent, critical, time);
        return critical;
    }

    private static void dfs(int u, List<Integer>[] graph, boolean[] visited, int[] disc, int[] low,
                            int[] parent, List<List<Integer>> critical, int[] time) {
        visited[u] = true;
        disc[u] = time[0];
        low[u] = time[0];
        time[0]++;

        for (int v : graph[u]) {
            if (!visited[v]) {
                parent[v] = u;
                dfs(v, graph, visited, disc, low, parent, critical, time);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > disc[u]) {
                    critical.add(Arrays.asList(u, v));
                }
            } else if (v != parent[u]) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }
}

