class Solution {
    public static int equalSubstring(String s, String t, int maxCost) {
        int maxLength = 0;
        int left = 0;
        int currentCost = 0;
        for (int right = 0; right < s.length(); right++) {
            currentCost += Math.abs(s.charAt(right) - t.charAt(right));
            while (currentCost > maxCost) {
                currentCost -= Math.abs(s.charAt(left) - t.charAt(left));
                left++;
            }
            maxLength = Math.max(maxLength, right - left + 1);
        }
        return maxLength;
    }
}

import java.lang.Math;

class Solution {
    public static long nthUglyNumber(long n, long a, long b, long c) {
        long left = 1;
        long right = n * Math.min(a, Math.min(b, c));
        while (left < right) {
            long mid = left + (right - left) / 2;
            long count = mid / a + mid / b + mid / c
                    - mid / lcm(a, b) - mid / lcm(b, c) - mid / lcm(a, c)
                    + mid / lcm(lcm(a, b), c);
            if (count < n) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private static long gcd(long x, long y) {
        while (y != 0) {
            long t = x % y;
            x = y;
            y = t;
        }
        return x;
    }

    private static long lcm(long x, long y) {
        long g = gcd(x, y);
        long div = x / g;
        if (div > Long.MAX_VALUE / y) {
            return Long.MAX_VALUE;
        }
        return div * y;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static String removeDuplicates(String s, int k) {
        Deque<int[]> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!stack.isEmpty() && (char) stack.peekLast()[0] == c) {
                stack.peekLast()[1]++;
                if (stack.peekLast()[1] == k) {
                    stack.pollLast();
                }
            } else {
                stack.addLast(new int[]{c, 1});
            }
        }
        StringBuilder result = new StringBuilder();
        for (int[] pair : stack) {
            for (int i = 0; i < pair[1]; i++) {
                result.append((char) pair[0]);
            }
        }
        return result.toString();
    }
}

import java.util.*;

class Solution {
    public static String smallestStringWithSwaps(String s, List<List<Integer>> pairs) {
        int n = s.length();
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
        for (List<Integer> p : pairs) {
            int x = p.get(0);
            int y = p.get(1);
            union(parent, rank, x, y);
        }
        Map<Integer, List<Character>> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int group = find(parent, i);
            map.computeIfAbsent(group, k -> new ArrayList<>()).add(s.charAt(i));
        }
        Map<Integer, Queue<Character>> queueMap = new HashMap<>();
        for (Map.Entry<Integer, List<Character>> entry : map.entrySet()) {
            List<Character> list = entry.getValue();
            Collections.sort(list);
            Queue<Character> q = new LinkedList<>();
            for (char c : list) {
                q.offer(c);
            }
            queueMap.put(entry.getKey(), q);
        }
        char[] result = new char[n];
        for (int i = 0; i < n; i++) {
            int group = find(parent, i);
            result[i] = queueMap.get(group).poll();
        }
        return new String(result);
    }

    private static int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    private static void union(int[] parent, int[] rank, int x, int y) {
        int rootX = find(parent, x);
        int rootY = find(parent, y);
        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
}

public class Solution {
    static class Node {
        int value;
        Node[] forward;
        Node(int value, int level) {
            this.value = value;
            this.forward = new Node[level];
        }
    }
    static class Skiplist {
        int levels;
        int maxValue;
        Node head;
        java.util.Random rand = new java.util.Random();
        Skiplist() {
            this.levels = 16;
            this.maxValue = 1 << 15;
            this.head = new Node(this.maxValue, this.levels);
        }
        int randomLevel() {
            int lvl = 1;
            while (rand.nextDouble() < 0.5 && lvl < levels) lvl++;
            return lvl;
        }
        public boolean search(int target) {
            Node curr = head;
            for (int i = levels - 1; i >= 0; i--) {
                while (curr.forward[i] != null && curr.forward[i].value < target) curr = curr.forward[i];
            }
            return curr.forward[0] != null && curr.forward[0].value == target;
        }
        public void add(int num) {
            Node[] update = new Node[levels];
            Node curr = head;
            for (int i = levels - 1; i >= 0; i--) {
                while (curr.forward[i] != null && curr.forward[i].value < num) curr = curr.forward[i];
                update[i] = curr;
            }
            int lvl = randomLevel();
            Node newNode = new Node(num, lvl);
            for (int i = 0; i < lvl; i++) {
                newNode.forward[i] = update[i].forward[i];
                update[i].forward[i] = newNode;
            }
        }
        public boolean erase(int num) {
            Node[] update = new Node[levels];
            Node curr = head;
            for (int i = levels - 1; i >= 0; i--) {
                while (curr.forward[i] != null && curr.forward[i].value < num) curr = curr.forward[i];
                update[i] = curr;
            }
            if (curr.forward[0] != null && curr.forward[0].value == num) {
                for (int i = 0; i < levels; i++) {
                    if (update[i].forward[i] != null && update[i].forward[i].value == num) {
                        update[i].forward[i] = update[i].forward[i].forward[i];
                    } else break;
                }
                return true;
            }
            return false;
        }
    }
    public static Skiplist Skiplist() {
        return new Skiplist();
    }
}

import java.util.*;

public class H3 {
    static List<Integer> topo(List<List<Integer>> adj, int[] indegIn, int count) {
        int[] indeg = indegIn.clone();
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < count; i++) if (indeg[i] == 0) q.add(i);
        List<Integer> order = new ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            order.add(u);
            for (int v : adj.get(u)) {
                if (--indeg[v] == 0) q.add(v);
            }
        }
        return order.size() == count ? order : null;
    }

    static int[] sortItems(int n, int m, int[] groupIn, List<List<Integer>> beforeItems) {
        int[] group = groupIn.clone();
        int nextGroupId = m;
        for (int i = 0; i < n; i++) {
            if (group[i] == -1) group[i] = nextGroupId++;
        }
        int totalGroups = nextGroupId;

        List<List<Integer>> itemAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) itemAdj.add(new ArrayList<>());
        int[] itemIndeg = new int[n];
        List<List<Integer>> groupAdj = new ArrayList<>();
        for (int i = 0; i < totalGroups; i++) groupAdj.add(new ArrayList<>());
        int[] groupIndeg = new int[totalGroups];

        for (int i = 0; i < n; i++) {
            for (int b : beforeItems.get(i)) {
                itemAdj.get(b).add(i);
                itemIndeg[i]++;
                if (group[b] != group[i]) {
                    groupAdj.get(group[b]).add(group[i]);
                    groupIndeg[group[i]]++;
                }
            }
        }

        List<Integer> itemOrder = topo(itemAdj, itemIndeg, n);
        if (itemOrder == null) return new int[0];
        List<Integer> groupOrder = topo(groupAdj, groupIndeg, totalGroups);
        if (groupOrder == null) return new int[0];

        List<List<Integer>> itemsByGroup = new ArrayList<>();
        for (int i = 0; i < totalGroups; i++) itemsByGroup.add(new ArrayList<>());
        for (int item : itemOrder) itemsByGroup.get(group[item]).add(item);

        int[] result = new int[n];
        int idx = 0;
        for (int g : groupOrder) {
            for (int item : itemsByGroup.get(g)) result[idx++] = item;
        }
        return result;
    }

    static boolean isValid(int n, int[] group, List<List<Integer>> beforeItems, int[] order) {
        if (order.length != n) return false;
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) pos[order[i]] = i;
        for (int i = 0; i < n; i++) {
            for (int b : beforeItems.get(i)) {
                if (pos[b] > pos[i]) return false;
            }
        }
        Map<Integer, int[]> seen = new HashMap<>();
        for (int idx = 0; idx < n; idx++) {
            int g = group[order[idx]];
            if (g == -1) continue;
            if (!seen.containsKey(g)) seen.put(g, new int[]{idx, idx});
            else seen.get(g)[1] = idx;
        }
        for (Map.Entry<Integer, int[]> e : seen.entrySet()) {
            int g = e.getKey();
            for (int idx = e.getValue()[0]; idx <= e.getValue()[1]; idx++) {
                if (group[order[idx]] != g) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int n = 8, m = 2;
        int[] group = {-1,-1,1,0,0,1,0,-1};
        List<List<Integer>> before = Arrays.asList(
            Arrays.asList(), Arrays.asList(6), Arrays.asList(5), Arrays.asList(6),
            Arrays.asList(3,6), Arrays.asList(), Arrays.asList(), Arrays.asList()
        );
        int[] got = sortItems(n, m, group, before);
        System.out.println(Arrays.toString(got) + " valid? " + isValid(n, group, before, got));

        List<List<Integer>> before2 = Arrays.asList(
            Arrays.asList(), Arrays.asList(6), Arrays.asList(5), Arrays.asList(6),
            Arrays.asList(3), Arrays.asList(), Arrays.asList(4), Arrays.asList()
        );
        int[] got2 = sortItems(n, m, group, before2);
        System.out.println("size=" + got2.length + " expected 0");
    }
}

import java.util.*;

class Solution {
    public static int minimumMoves(int[][] grid) {
        int n = grid.length;
        boolean[][][] visited = new boolean[n][n][2];
        Deque<int[]> queue = new ArrayDeque<>();
        // state: row, col, orientation (0 = horizontal, 1 = vertical), steps
        queue.offer(new int[]{0, 0, 0, 0});
        visited[0][0][0] = true;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            int ori = cur[2];
            int steps = cur[3];
            if (r == n - 1 && c == n - 2 && ori == 0) {
                return steps;
            }
            if (ori == 0) { // horizontal
                // move right
                if (c + 2 < n && grid[r][c + 2] == 0 && !visited[r][c + 1][0]) {
                    visited[r][c + 1][0] = true;
                    queue.offer(new int[]{r, c + 1, 0, steps + 1});
                }
                // move down
                if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0 && !visited[r + 1][c][0]) {
                    visited[r + 1][c][0] = true;
                    queue.offer(new int[]{r + 1, c, 0, steps + 1});
                }
                // rotate clockwise to vertical
                if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c][1]) {
                    visited[r][c][1] = true;
                    queue.offer(new int[]{r, c, 1, steps + 1});
                }
            } else { // vertical
                // move down
                if (r + 2 < n && grid[r + 2][c] == 0 && !visited[r + 1][c][1]) {
                    visited[r + 1][c][1] = true;
                    queue.offer(new int[]{r + 1, c, 1, steps + 1});
                }
                // move right
                if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c + 1][1]) {
                    visited[r][c + 1][1] = true;
                    queue.offer(new int[]{r, c + 1, 1, steps + 1});
                }
                // rotate counterclockwise to horizontal
                if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c][0]) {
                    visited[r][c][0] = true;
                    queue.offer(new int[]{r, c, 0, steps + 1});
                }
            }
        }
        return -1;
    }
}

public class Solution {
    public static int minCostToMoveChips(int[] position) {
        int evenCount = 0;
        int oddCount = 0;
        for (int i = 0; i < position.length; i++) {
            if (position[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        return Math.min(evenCount, oddCount);
    }
}

