class Solution {
    public static int longestSubsequence(int[] arr, int difference) {
        int maxLength = 0;
        Map<Integer, Integer> sequenceLengths = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            int previousElement = arr[i] - difference;
            int currentLength = sequenceLengths.getOrDefault(previousElement, 0) + 1;
            sequenceLengths.put(arr[i], currentLength);
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
        }
        return maxLength;
    }
}

