class Solution {
    public static int getMaximumGold(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int[] maxGold = new int[1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 0) {
                    Set<String> visited = new HashSet<>();
                    visited.add(i + "," + j);
                    backtrack(i, j, grid[i][j], visited, grid, m, n, directions, maxGold);
                }
            }
        }
        return maxGold[0];
    }

    private static void backtrack(int row, int col, int currentGold, Set<String> visited,
                                  int[][] grid, int m, int n, int[][] directions, int[] maxGold) {
        maxGold[0] = Math.max(maxGold[0], currentGold);
        for (int i = 0; i < 4; i++) {
            int newRow = row + directions[i][0];
            int newCol = col + directions[i][1];
            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n &&
                grid[newRow][newCol] != 0 && !visited.contains(newRow + "," + newCol)) {
                visited.add(newRow + "," + newCol);
                backtrack(newRow, newCol, currentGold + grid[newRow][newCol], visited,
                          grid, m, n, directions, maxGold);
                visited.remove(newRow + "," + newCol);
            }
        }
    }
}

