class Solution {
    public static List<Integer> circularPermutation(int n, int start) {
        int total = 1 << n;
        List<Integer> gray = new ArrayList<>(total);
        for (int i = 0; i < total; i++) {
            gray.add(i ^ (i >> 1));
        }
        int idx = gray.indexOf(start);
        List<Integer> result = new ArrayList<>(total);
        for (int i = 0; i < total; i++) {
            result.add(gray.get((idx + i) % total));
        }
        return result;
    }
}

