class Solution {
    public static List<int[]> findSolution(int function_id, int z) {
        List<int[]> result = new ArrayList<>();
        for (int x = 1; x <= z; x++) {
            for (int y = 1; y <= z; y++) {
                if (f(x, y, function_id) == z) {
                    result.add(new int[]{x, y});
                }
            }
        }
        return result;
    }
    private static int f(int x, int y, int function_id) {
        if (function_id == 1) {
            return x + y;
        }
        if (function_id == 2) {
            return x * y;
        }
        return 0;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int maxLength(String[] arr) {
        int[] maxLen = new int[1];
        backtrack(arr, 0, "", maxLen);
        return maxLen[0];
    }

    private static void backtrack(String[] arr, int start, String path, int[] maxLen) {
        if (isUnique(path)) {
            maxLen[0] = Math.max(maxLen[0], path.length());
        }
        for (int i = start; i < arr.length; i++) {
            if (hasDuplicate(path + arr[i])) continue;
            backtrack(arr, i + 1, path + arr[i], maxLen);
        }
    }

    private static boolean isUnique(String str) {
        Set<Character> set = new HashSet<>();
        for (char c : str.toCharArray()) {
            if (set.contains(c)) return false;
            set.add(c);
        }
        return true;
    }

    private static boolean hasDuplicate(String str) {
        Set<Character> set = new HashSet<>();
        for (char c : str.toCharArray()) {
            if (set.contains(c)) return true;
            set.add(c);
        }
        return false;
    }
}

