class Solution {
    public static int balancedString(String s) {
        int n = s.length();
        int target = n / 4;
        int[] total = new int[4];
        for (int i = 0; i < n; i++) {
            total[charToIndex(s.charAt(i))]++;
        }
        boolean alreadyBalanced = true;
        for (int i = 0; i < 4; i++) {
            if (total[i] != target) {
                alreadyBalanced = false;
                break;
            }
        }
        if (alreadyBalanced) return 0;
        int[] window = new int[4];
        int left = 0;
        int minLen = n;
        for (int right = 0; right < n; right++) {
            window[charToIndex(s.charAt(right))]++;
            while (left <= right && isValid(total, window, target)) {
                minLen = Math.min(minLen, right - left + 1);
                window[charToIndex(s.charAt(left))]--;
                left++;
            }
        }
        return minLen;
    }

    private static boolean isValid(int[] total, int[] window, int target) {
        for (int i = 0; i < 4; i++) {
            if (total[i] - window[i] > target) return false;
        }
        return true;
    }

    private static int charToIndex(char c) {
        switch (c) {
            case 'Q': return 0;
            case 'W': return 1;
            case 'E': return 2;
            case 'R': return 3;
            default: return -1;
        }
    }
}

