class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    private static class NodeInfo {
        TreeNode node;
        int val;
        NodeInfo(TreeNode node, int val) {
            this.node = node;
            this.val = val;
        }
    }

    public static Set<Integer> FindElements(TreeNode root) {
        Set<Integer> values = new HashSet<>();
        if (root == null) return values;
        Deque<NodeInfo> stack = new ArrayDeque<>();
        stack.push(new NodeInfo(root, 0));
        while (!stack.isEmpty()) {
            NodeInfo cur = stack.pop();
            TreeNode node = cur.node;
            int val = cur.val;
            node.val = val;
            values.add(val);
            if (node.left != null) stack.push(new NodeInfo(node.left, 2 * val + 1));
            if (node.right != null) stack.push(new NodeInfo(node.right, 2 * val + 2));
        }
        return values;
    }
}

public class Solution {
    public static int maxSumDivisibleByThree(int[] nums) {
        int INF = Integer.MIN_VALUE / 2;
        int[] dp = new int[]{0, INF, INF};
        for (int i = 0; i < nums.length; i++) {
            int cur = nums[i];
            int mod = cur % 3;
            int[] next = dp.clone();
            for (int r = 0; r < 3; r++) {
                int newR = (r + mod) % 3;
                int candidate = dp[r] + cur;
                if (candidate > next[newR]) {
                    next[newR] = candidate;
                }
            }
            dp[0] = next[0];
            dp[1] = next[1];
            dp[2] = next[2];
        }
        return dp[0];
    }
}

