import java.util.*;

class Solution {
    public static List<List<String>> suggestedProducts(List<String> products, String searchWord) {
        Collections.sort(products);
        List<List<String>> result = new ArrayList<>();
        int n = products.size();
        StringBuilder prefix = new StringBuilder();
        for (int i = 0; i < searchWord.length(); i++) {
            prefix.append(searchWord.charAt(i));
            String prefStr = prefix.toString();
            int start = lowerBound(products, prefStr);
            List<String> suggestions = new ArrayList<>();
            for (int j = start; j < Math.min(start + 3, n); j++) {
                String prod = products.get(j);
                if (prod.startsWith(prefStr)) {
                    suggestions.add(prod);
                } else {
                    break;
                }
            }
            result.add(suggestions);
        }
        return result;
    }

    private static int lowerBound(List<String> list, String target) {
        int left = 0;
        int right = list.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (list.get(mid).compareTo(target) < 0) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

