class Solution {
    public int minPushBox(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[] startPlayer = new int[2];
        int[] startBox = new int[2];
        int[] target = new int[2];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'S') {
                    startPlayer[0] = i;
                    startPlayer[1] = j;
                } else if (grid[i][j] == 'B') {
                    startBox[0] = i;
                    startBox[1] = j;
                } else if (grid[i][j] == 'T') {
                    target[0] = i;
                    target[1] = j;
                }
            }
        }
        if (startBox[0] == target[0] && startBox[1] == target[1]) {
            return 0;
        }
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        boolean[][][][] visited = new boolean[m][n][m][n];
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{startBox[0], startBox[1], startPlayer[0], startPlayer[1], 0});
        visited[startBox[0]][startBox[1]][startPlayer[0]][startPlayer[1]] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int bx = cur[0], by = cur[1], px = cur[2], py = cur[3], pushes = cur[4];
            if (bx == target[0] && by == target[1]) {
                return pushes;
            }
            for (int[] d : dirs) {
                int nbx = bx + d[0];
                int nby = by + d[1];
                int reqPx = bx - d[0];
                int reqPy = by - d[1];
                if (!inBounds(nbx, nby, m, n) || !inBounds(reqPx, reqPy, m, n)) continue;
                if (grid[nbx][nby] == '#') continue;
                if (grid[reqPx][reqPy] == '#') continue;
                if (!canReach(grid, px, py, reqPx, reqPy, bx, by)) continue;
                if (visited[nbx][nby][bx][by]) continue;
                visited[nbx][nby][bx][by] = true;
                q.offer(new int[]{nbx, nby, bx, by, pushes + 1});
            }
        }
        return -1;
    }

    private boolean inBounds(int x, int y, int m, int n) {
        return x >= 0 && x < m && y >= 0 && y < n;
    }

    private boolean canReach(char[][] grid, int sx, int sy, int tx, int ty, int boxX, int boxY) {
        int m = grid.length, n = grid[0].length;
        if (sx == tx && sy == ty) return true;
        boolean[][] seen = new boolean[m][n];
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{sx, sy});
        seen[sx][sy] = true;
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] d : dirs) {
                int nx = cur[0] + d[0];
                int ny = cur[1] + d[1];
                if (!inBounds(nx, ny, m, n) || seen[nx][ny]) continue;
                if (grid[nx][ny] == '#') continue;
                if (nx == boxX && ny == boxY) continue;
                if (nx == tx && ny == ty) return true;
                seen[nx][ny] = true;
                q.offer(new int[]{nx, ny});
            }
        }
        return false;
    }
}

