class Solution {
    public static int subtractProductAndSum(int n) {
        int product = 1;
        int sum = 0;
        int num = Math.abs(n);
        if (num == 0) return 0;
        while (num > 0) {
            int digit = num % 10;
            product *= digit;
            sum += digit;
            num = num / 10;
        }
        return product - sum;
    }
}

