class Solution {
    public static int smallestDivisor(int[] nums, int threshold) {
        int left = 1;
        int right = 0;
        for (int num : nums) {
            if (num > right) {
                right = num;
            }
        }
        while (left < right) {
            int mid = (left + right) / 2;
            long total = 0;
            for (int i = 0; i < nums.length; i++) {
                total += (nums[i] + mid - 1) / mid;
                if (total > threshold) {
                    break;
                }
            }
            if (total <= threshold) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

