public class Solution {
    public static CombinationIterator CombinationIterator(String characters, int combinationLength) {
        List<String> allCombos = new ArrayList<>();
        List<Character> combo = new ArrayList<>();
        int n = characters.length();
        backtrack(0, characters, combinationLength, combo, allCombos, n);
        return new CombinationIterator(allCombos);
    }

    private static void backtrack(int start, String characters, int combinationLength, List<Character> combo, List<String> allCombos, int n) {
        if (combo.size() == combinationLength) {
            StringBuilder sb = new StringBuilder();
            for (char c : combo) {
                sb.append(c);
            }
            allCombos.add(sb.toString());
            return;
        }
        for (int i = start; i < n; i++) {
            combo.add(characters.charAt(i));
            backtrack(i + 1, characters, combinationLength, combo, allCombos, n);
            combo.remove(combo.size() - 1);
        }
    }

    public static class CombinationIterator {
        private final List<String> allCombos;
        private int pos = 0;

        public CombinationIterator(List<String> allCombos) {
            this.allCombos = allCombos;
        }

        public String next() {
            return allCombos.get(pos++);
        }

        public boolean hasNext() {
            return pos < allCombos.size();
        }
    }
}

