class Solution {
    public static int minFallingPathSum(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        int[] prev = grid[0].clone();
        for (int i = 1; i < n; i++) {
            int min1 = Integer.MAX_VALUE;
            int min2 = Integer.MAX_VALUE;
            int idxMin1 = -1;
            for (int j = 0; j < n; j++) {
                int val = prev[j];
                if (val < min1) {
                    min2 = min1;
                    min1 = val;
                    idxMin1 = j;
                } else if (val < min2) {
                    min2 = val;
                }
            }
            int[] cur = new int[n];
            for (int j = 0; j < n; j++) {
                int bestPrev = (j == idxMin1) ? min2 : min1;
                cur[j] = grid[i][j] + bestPrev;
            }
            prev = cur;
        }
        int answer = prev[0];
        for (int v : prev) {
            if (v < answer) answer = v;
        }
        return answer;
    }
}

