class Solution {
    public static int minFlips(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int start = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    start |= 1 << (i * n + j);
                }
            }
        }
        int[] flipMasks = new int[m * n];
        int[][] dirs = {{0,0},{1,0},{-1,0},{0,1},{0,-1}};
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int mask = 0;
                for (int[] d : dirs) {
                    int x = i + d[0];
                    int y = j + d[1];
                    if (x >= 0 && x < m && y >= 0 && y < n) {
                        mask |= 1 << (x * n + y);
                    }
                }
                flipMasks[idx++] = mask;
            }
        }
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        Map<Integer, Integer> dist = new HashMap<>();
        queue.add(start);
        dist.put(start, 0);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            int steps = dist.get(cur);
            if (cur == 0) return steps;
            for (int mask : flipMasks) {
                int nxt = cur ^ mask;
                if (!dist.containsKey(nxt)) {
                    dist.put(nxt, steps + 1);
                    queue.add(nxt);
                }
            }
        }
        return -1;
    }
}

