public class Solution {
    public static int maxSideLength(int[][] mat, int threshold) {
        int rows = mat.length;
        int cols = mat[0].length;
        long[][] prefix = new long[rows + 1][cols + 1];
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                prefix[r][c] = mat[r - 1][c - 1] + prefix[r - 1][c] + prefix[r][c - 1] - prefix[r - 1][c - 1];
            }
        }
        int low = 0, high = Math.min(rows, cols);
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (canFit(mid, prefix, rows, cols, threshold)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean canFit(int size, long[][] prefix, int rows, int cols, int threshold) {
        for (int r = 0; r + size <= rows; r++) {
            for (int c = 0; c + size <= cols; c++) {
                long sum = prefix[r + size][c + size] - prefix[r][c + size] - prefix[r + size][c] + prefix[r][c];
                if (sum <= threshold) {
                    return true;
                }
            }
        }
        return false;
    }
}

