import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int shortestPath(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        if (m == 1 && n == 1) return 0;
        if (k >= m + n - 2) return m + n - 2;

        int[][] dirs = { {1, 0}, {-1, 0}, {0, 1}, {0, -1} };

        int[][] visited = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                visited[i][j] = -1;
            }
        }
        visited[0][0] = k;

        class Node {
            int r, c, left;
            Node(int r, int c, int left) {
                this.r = r;
                this.c = c;
                this.left = left;
            }
        }

        Deque<Node> queue = new ArrayDeque<>();
        queue.offer(new Node(0, 0, k));
        int steps = 0;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            steps++;
            for (int i = 0; i < levelSize; i++) {
                Node cur = queue.poll();
                for (int[] d : dirs) {
                    int nr = cur.r + d[0];
                    int nc = cur.c + d[1];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                    if (nr == m - 1 && nc == n - 1) return steps;
                    int cell = grid[nr][nc];
                    int newLeft = cell == 1 ? cur.left - 1 : cur.left;
                    if (newLeft < 0) continue;
                    if (visited[nr][nc] >= newLeft) continue;
                    visited[nr][nc] = newLeft;
                    queue.offer(new Node(nr, nc, newLeft));
                }
            }
        }

        return -1;
    }
}

