class Solution {
    public static boolean canDivideArray(int[] nums, int k) {
        if (nums.length % k != 0) return false;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        List<Integer> sorted = new ArrayList<>(freq.keySet());
        Collections.sort(sorted);
        for (int start : sorted) {
            int count = freq.get(start);
            if (count > 0) {
                for (int i = 0; i < k; i++) {
                    int cur = start + i;
                    int curCount = freq.getOrDefault(cur, 0);
                    if (curCount < count) return false;
                    freq.put(cur, curCount - count);
                }
            }
        }
        return true;
    }
}

