class Solution {
    public static int maxFreq(String s, int maxLetters, int minSize, int maxSize) {
        if (s.length() < minSize) return 0;
        Map<String, Integer> freqMap = new HashMap<>();
        int[] charCount = new int[26];
        int distinct = 0;
        int best = 0;
        for (int i = 0; i < minSize; i++) {
            int idx = s.charAt(i) - 'a';
            if (charCount[idx] == 0) distinct++;
            charCount[idx]++;
        }
        for (int start = 0; start + minSize <= s.length(); start++) {
            if (distinct <= maxLetters) {
                String sub = s.substring(start, start + minSize);
                int newCount = freqMap.getOrDefault(sub, 0) + 1;
                freqMap.put(sub, newCount);
                if (newCount > best) best = newCount;
            }
            if (start + minSize < s.length()) {
                int leftIdx = s.charAt(start) - 'a';
                int rightIdx = s.charAt(start + minSize) - 'a';
                charCount[leftIdx]--;
                if (charCount[leftIdx] == 0) distinct--;
                if (charCount[rightIdx] == 0) distinct++;
                charCount[rightIdx]++;
            }
        }
        return best;
    }
}

