public class Solution {
    public int findBestValue(int[] arr, int target) {
        int n = arr.length;
        Arrays.sort(arr);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + arr[i];
        }
        int max = arr[n - 1];
        int low = 0, high = max;
        while (low < high) {
            int mid = (low + high) >>> 1;
            long sum = computeSum(arr, prefix, mid);
            if (sum < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        int best = low;
        long bestDiff = Math.abs(computeSum(arr, prefix, best) - target);
        if (best > 0) {
            long diffPrev = Math.abs(computeSum(arr, prefix, best - 1) - target);
            if (diffPrev < bestDiff || (diffPrev == bestDiff && best - 1 < best)) {
                best = best - 1;
                bestDiff = diffPrev;
            }
        }
        return best;
    }

    private long computeSum(int[] arr, long[] prefix, int v) {
        int n = arr.length;
        int l = 0, r = n;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] <= v) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        int idx = l; // first index with arr[idx] > v
        return prefix[idx] + (long) v * (n - idx);
    }
}

