class Solution {
    private static final int MOD = 1_000_000_007;

    public int[] pathsWithMaxScore(String[] board) {
        int n = board.length;
        int[][] maxScore = new int[n][n];
        long[][] ways = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(maxScore[i], -1);
        }

        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                char c = board[i].charAt(j);
                if (c == 'X') {
                    continue;
                }
                if (i == n - 1 && j == n - 1) { // start 'S'
                    maxScore[i][j] = 0;
                    ways[i][j] = 1;
                    continue;
                }

                int maxPrev = -1;
                long cnt = 0;

                // from down
                if (i + 1 < n && maxScore[i + 1][j] != -1) {
                    int val = maxScore[i + 1][j];
                    if (val > maxPrev) {
                        maxPrev = val;
                        cnt = ways[i + 1][j];
                    } else if (val == maxPrev) {
                        cnt = (cnt + ways[i + 1][j]) % MOD;
                    }
                }
                // from right
                if (j + 1 < n && maxScore[i][j + 1] != -1) {
                    int val = maxScore[i][j + 1];
                    if (val > maxPrev) {
                        maxPrev = val;
                        cnt = ways[i][j + 1];
                    } else if (val == maxPrev) {
                        cnt = (cnt + ways[i][j + 1]) % MOD;
                    }
                }
                // from down-right diagonal
                if (i + 1 < n && j + 1 < n && maxScore[i + 1][j + 1] != -1) {
                    int val = maxScore[i + 1][j + 1];
                    if (val > maxPrev) {
                        maxPrev = val;
                        cnt = ways[i + 1][j + 1];
                    } else if (val == maxPrev) {
                        cnt = (cnt + ways[i + 1][j + 1]) % MOD;
                    }
                }

                if (maxPrev == -1) {
                    continue; // unreachable
                }

                int add = 0;
                if (c >= '1' && c <= '9') {
                    add = c - '0';
                }
                // 'E' contributes 0, 'S' already handled
                maxScore[i][j] = maxPrev + add;
                ways[i][j] = cnt % MOD;
            }
        }

        if (maxScore[0][0] == -1) {
            return new int[]{0, 0};
        }
        return new int[]{maxScore[0][0], (int) (ways[0][0] % MOD)};
    }
}

