class Solution {
    public int maxCandies(int[] status, int[] candies, int[][] keys, int[][] containedBoxes, int[] initialBoxes) {
        int n = status.length;
        boolean[] haveBox = new boolean[n];
        boolean[] haveKey = new boolean[n];
        boolean[] opened = new boolean[n];
        for (int b : initialBoxes) {
            haveBox[b] = true;
        }
        int total = 0;
        boolean progress = true;
        while (progress) {
            progress = false;
            for (int i = 0; i < n; i++) {
                if (haveBox[i] && !opened[i] && (status[i] == 1 || haveKey[i])) {
                    opened[i] = true;
                    progress = true;
                    total += candies[i];
                    for (int k : keys[i]) {
                        haveKey[k] = true;
                    }
                    for (int b : containedBoxes[i]) {
                        haveBox[b] = true;
                    }
                }
            }
        }
        return total;
    }
}

