class Solution {
    public static String decryptString(String s) {
        StringBuilder decoded = new StringBuilder();
        int i = s.length() - 1;
        while (i >= 0) {
            int num;
            if (s.charAt(i) == '#') {
                num = (s.charAt(i - 2) - '0') * 10 + (s.charAt(i - 1) - '0');
                i -= 3;
            } else {
                num = s.charAt(i) - '0';
                i -= 1;
            }
            char letter = (char) ('a' + num - 1);
            decoded.append(letter);
        }
        decoded.reverse();
        return decoded.toString();
    }
}

