class Solution {
    public static boolean canReach(int[] arr, int start) {
        int n = arr.length;
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();

        queue.add(start);
        visited[start] = true;

        while (!queue.isEmpty()) {
            int idx = queue.poll();

            if (arr[idx] == 0) return true;

            int jump = arr[idx];
            int forward = idx + jump;
            int backward = idx - jump;

            if (forward < n && !visited[forward]) {
                visited[forward] = true;
                queue.add(forward);
            }
            if (backward >= 0 && !visited[backward]) {
                visited[backward] = true;
                queue.add(backward);
            }
        }

        return false;
    }
}

class Solution {
    public static int[] findZeroSumArray(int n) {
        java.util.List<Integer> result = new java.util.ArrayList<>();
        if (n % 2 == 0) {
            for (int i = 1; i <= n/2; i++) { result.add(i); result.add(-i); }
        } else {
            if (n == 1) result.add(0);
            else if (n == 3) { result.add(-1); result.add(0); result.add(1); }
            else {
                result.add(-1); result.add(1);
                int sumPos = 0;
                for (int i = 3; i <= n-1; i++) { result.add(i); sumPos += i; }
                result.add(-sumPos);
            }
        }
        java.util.Collections.sort(result);
        int[] arr = new int[result.size()];
        for (int i = 0; i < arr.length; i++) arr[i] = result.get(i);
        return arr;
    }
}

import java.util.*;

class Solution {
    public boolean isSolvable(String[] words, String result) {
        // collect distinct letters
        boolean[] present = new boolean[26];
        List<Character> letters = new ArrayList<>();
        Set<Character> leading = new HashSet<>();

        for (String w : words) {
            if (w.length() > 1) leading.add(w.charAt(0));
            for (char c : w.toCharArray()) {
                if (!present[c - 'A']) {
                    present[c - 'A'] = true;
                    letters.add(c);
                }
            }
        }
        if (result.length() > 1) leading.add(result.charAt(0));
        for (char c : result.toCharArray()) {
            if (!present[c - 'A']) {
                present[c - 'A'] = true;
                letters.add(c);
            }
        }

        if (letters.size() > 10) return false; // not enough digits

        int[] map = new int[26];
        Arrays.fill(map, -1);
        boolean[] used = new boolean[10];

        return backtrack(0, letters, map, used, leading, words, result);
    }

    private boolean backtrack(int idx, List<Character> letters, int[] map, boolean[] used,
                              Set<Character> leading, String[] words, String result) {
        if (idx == letters.size()) {
            return checkSum(map, words, result);
        }
        char ch = letters.get(idx);
        int ci = ch - 'A';
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && leading.contains(ch)) continue;
            used[d] = true;
            map[ci] = d;
            if (backtrack(idx + 1, letters, map, used, leading, words, result)) {
                return true;
            }
            used[d] = false;
            map[ci] = -1;
        }
        return false;
    }

    private boolean checkSum(int[] map, String[] words, String result) {
        long sum = 0;
        for (String w : words) {
            long val = 0;
            for (char c : w.toCharArray()) {
                val = val * 10 + map[c - 'A'];
            }
            sum += val;
        }
        long resVal = 0;
        for (char c : result.toCharArray()) {
            resVal = resVal * 10 + map[c - 'A'];
        }
        return sum == resVal;
    }
}

