class Solution {
    public static List<String> getWatchedVideosByFriends(List<List<String>> watchedVideos, List<List<Integer>> friends, int id, int level) {
        int n = watchedVideos.size();
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();

        visited[id] = true;
        queue.offer(id);
        int currentLevel = 0;

        while (!queue.isEmpty() && currentLevel < level) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int person = queue.poll();
                for (int nb : friends.get(person)) {
                    if (!visited[nb]) {
                        visited[nb] = true;
                        queue.offer(nb);
                    }
                }
            }
            currentLevel++;
        }

        Map<String, Integer> freq = new HashMap<>();
        for (int person : queue) {
            for (String video : watchedVideos.get(person)) {
                freq.put(video, freq.getOrDefault(video, 0) + 1);
            }
        }

        List<String> result = new ArrayList<>(freq.keySet());
        result.sort((a, b) -> {
            int cmp = Integer.compare(freq.get(a), freq.get(b));
            if (cmp != 0) return cmp;
            return a.compareTo(b);
        });

        return result;
    }
}

