import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int distinctEchoSubstrings(String text) {
        int n = text.length();
        long base = 91138233L;
        long mod1 = 1000000007L;
        long mod2 = 1000000009L;

        long[] pref1 = new long[n + 1];
        long[] pref2 = new long[n + 1];
        long[] pow1 = new long[n + 1];
        long[] pow2 = new long[n + 1];
        pow1[0] = 1;
        pow2[0] = 1;

        for (int i = 0; i < n; i++) {
            int code = text.charAt(i);
            pref1[i + 1] = (pref1[i] * base + code) % mod1;
            pref2[i + 1] = (pref2[i] * base + code) % mod2;
            pow1[i + 1] = (pow1[i] * base) % mod1;
            pow2[i + 1] = (pow2[i] * base) % mod2;
        }

        Set<String> seen = new HashSet<>();

        for (int len = 2; len <= n; len += 2) {
            int half = len >> 1;
            for (int i = 0; i + len <= n; i++) {
                long[] left = getHash(i, i + half, pref1, pref2, pow1, pow2, mod1, mod2);
                long[] right = getHash(i + half, i + len, pref1, pref2, pow1, pow2, mod1, mod2);
                if (left[0] == right[0] && left[1] == right[1]) {
                    long[] whole = getHash(i, i + len, pref1, pref2, pow1, pow2, mod1, mod2);
                    seen.add(whole[0] + "#" + whole[1]);
                }
            }
        }

        return seen.size();
    }

    private static long[] getHash(int l, int r, long[] pref1, long[] pref2, long[] pow1, long[] pow2, long mod1, long mod2) {
        long h1 = (pref1[r] - (pref1[l] * pow1[r - l]) % mod1 + mod1) % mod1;
        long h2 = (pref2[r] - (pref2[l] * pow2[r - l]) % mod2 + mod2) % mod2;
        return new long[]{h1, h2};
    }
}

