class Solution {
    private static final int INF = 1_000_000_000;
    private static int distance(int a, int b) {
        int ra = a / 6, ca = a % 6;
        int rb = b / 6, cb = b % 6;
        return Math.abs(ra - rb) + Math.abs(ca - cb);
    }

    public int minimumDistance(String word) {
        int n = word.length();
        if (n <= 1) return 0;
        int[] dp = new int[27];
        Arrays.fill(dp, INF);
        dp[26] = 0; // both fingers are initially free (represented by 26)

        for (int i = 1; i < n; i++) {
            int prev = word.charAt(i - 1) - 'A';
            int cur = word.charAt(i) - 'A';
            int[] ndp = new int[27];
            Arrays.fill(ndp, INF);
            for (int j = 0; j <= 26; j++) {
                if (dp[j] == INF) continue;
                // Use the finger that typed the previous character
                int cost1 = dp[j] + distance(prev, cur);
                ndp[j] = Math.min(ndp[j], cost1);
                // Use the other finger
                int add = (j == 26) ? 0 : distance(j, cur);
                int cost2 = dp[j] + add;
                ndp[prev] = Math.min(ndp[prev], cost2);
            }
            dp = ndp;
        }

        int ans = INF;
        for (int v : dp) {
            ans = Math.min(ans, v);
        }
        return ans;
    }
}

public class Solution {
    public static int makeConnected(int n, int[][] connections) {
        if (connections.length < n - 1) return -1;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int components = n;
        for (int[] edge : connections) {
            if (union(edge[0], edge[1], parent, rank)) components--;
        }
        return components - 1;
    }
    private static int find(int x, int[] parent) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    private static boolean union(int a, int b, int[] parent, int[] rank) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
        return true;
    }
}

