public class Solution {
    public static int[][] diagonalSort(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        for (int col = 0; col < cols; col++) {
            sortDiagonal(mat, 0, col, rows, cols);
        }
        for (int row = 1; row < rows; row++) {
            sortDiagonal(mat, row, 0, rows, cols);
        }
        return mat;
    }

    private static void sortDiagonal(int[][] mat, int r, int c, int rows, int cols) {
        int i = r, j = c;
        List<Integer> elems = new ArrayList<>();
        while (i < rows && j < cols) {
            elems.add(mat[i][j]);
            i++;
            j++;
        }
        Collections.sort(elems);
        i = r;
        j = c;
        int idx = 0;
        while (i < rows && j < cols) {
            mat[i][j] = elems.get(idx++);
            i++;
            j++;
