class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public int maxProduct(TreeNode root) {
        final BigInteger MOD = new BigInteger("1000000007");
        List<BigInteger> subtreeSums = new ArrayList<>();
        BigInteger total = dfs(root, subtreeSums);
        BigInteger best = BigInteger.ZERO;
        for (BigInteger s : subtreeSums) {
            BigInteger product = s.multiply(total.subtract(s));
            if (product.compareTo(best) > 0) {
                best = product;
            }
        }
        return best.mod(MOD).intValue();
    }

    private BigInteger dfs(TreeNode node, List<BigInteger> sums) {
        if (node == null) return BigInteger.ZERO;
        BigInteger left = dfs(node.left, sums);
        BigInteger right = dfs(node.right, sums);
        BigInteger cur = BigInteger.valueOf(node.val).add(left).add(right);
        sums.add(cur);
        return cur;
    }
}

