public class Solution {
    public int maxJumps(int[] arr, int d) {
        int n = arr.length;
        int[] memo = new int[n];
        int result = 0;
        for (int i = 0; i < n; i++) {
            result = Math.max(result, dfs(i, arr, d, memo));
        }
        return result;
    }

    private int dfs(int i, int[] arr, int d, int[] memo) {
        if (memo[i] != 0) return memo[i];
        int n = arr.length;
        int best = 1;

        // jump to the left
        for (int step = 1; step <= d; step++) {
            int j = i - step;
            if (j < 0) break;
            if (arr[j] >= arr[i]) break;
            best = Math.max(best, 1 + dfs(j, arr, d, memo));
        }

        // jump to the right
        for (int step = 1; step <= d; step++) {
            int j = i + step;
            if (j >= n) break;
            if (arr[j] >= arr[i]) break;
            best = Math.max(best, 1 + dfs(j, arr, d, memo));
        }

        memo[i] = best;
        return best;
    }
}

