class Solution {
    public static int minJumps(int[] arr) {
        int n = arr.length;
        if (n <= 1) return 0;
        Map<Integer, List<Integer>> valueIndices = new HashMap<>();
        for (int i = 0; i < n; i++) {
            valueIndices.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }
        boolean[] visited = new boolean[n];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(0);
        visited[0] = true;
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int s = 0; s < size; s++) {
                int idx = queue.poll();
                if (idx == n - 1) return steps;
                if (idx - 1 >= 0 && !visited[idx - 1]) {
                    visited[idx - 1] = true;
                    queue.add(idx - 1);
                }
                if (idx + 1 < n && !visited[idx + 1]) {
                    visited[idx + 1] = true;
                    queue.add(idx + 1);
                }
                List<Integer> sameVal = valueIndices.getOrDefault(arr[idx], Collections.emptyList());
                for (int j : sameVal) {
                    if (!visited[j]) {
                        visited[j] = true;
                        queue.add(j);
                    }
                }
                valueIndices.put(arr[idx], Collections.emptyList());
            }
            steps++;
        }
        return -1;
    }
}

