class TweetCounts {
    private final Map<String, List<Integer>> data = new HashMap<>();

    private static int lowerBound(List<Integer> arr, int target) {
        int lo = 0, hi = arr.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr.get(mid) < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int upperBound(List<Integer> arr, int target) {
        int lo = 0, hi = arr.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr.get(mid) <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    public void recordTweet(String tweetName, int time) {
        data.computeIfAbsent(tweetName, k -> new ArrayList<>());
        List<Integer> arr = data.get(tweetName);
        int idx = lowerBound(arr, time);
        arr.add(idx, time);
    }

    public int[] getTweetCountsPerFrequency(String freq, String tweetName, int startTime, int endTime) {
        int bucketSize = freq.equals("minute") ? 60 : freq.equals("hour") ? 3600 : 86400;
        int bucketCount = (endTime - startTime) / bucketSize + 1;
        int[] counts = new int[bucketCount];
        List<Integer> arr = data.get(tweetName);
        if (arr == null) {
            return counts;
        }
        int left = lowerBound(arr, startTime);
        int right = upperBound(arr, endTime);
        for (int i = left; i < right; ++i) {
            int bucket = (arr.get(i) - startTime) / bucketSize;
            counts[bucket]++;
        }
        return counts;
    }
}

import java.util.*;

public class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int maxMask = 1 << n;
        List<Integer>[] valid = new List[m];
        for (int i = 0; i < m; i++) {
            int broken = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '#') {
                    broken |= (1 << j);
                }
            }
            valid[i] = new ArrayList<>();
            for (int mask = 0; mask < maxMask; mask++) {
                if ((mask & broken) != 0) continue;               // seat is broken
                if ((mask & (mask << 1)) != 0) continue;          // adjacent in same row
                valid[i].add(mask);
            }
        }
        int[][] dp = new int[m][maxMask];
        for (int[] row : dp) Arrays.fill(row, -1);
        for (int mask : valid[0]) {
            dp[0][mask] = Integer.bitCount(mask);
        }
        for (int i = 1; i < m; i++) {
            for (int mask : valid[i]) {
                int cnt = Integer.bitCount(mask);
                for (int prevMask : valid[i - 1]) {
                    if (dp[i - 1][prevMask] < 0) continue;
                    if ((mask & (prevMask << 1)) != 0) continue; // upper‑left conflict
                    if ((mask & (prevMask >> 1)) != 0) continue; // upper‑right conflict
                    dp[i][mask] = Math.max(dp[i][mask], dp[i - 1][prevMask] + cnt);
                }
            }
        }
        int ans = 0;
        for (int mask = 0; mask < maxMask; mask++) {
            ans = Math.max(ans, dp[m - 1][mask]);
        }
        return ans;
    }
}

