class Solution {
    public static ProductOfNumbers createProductOfNumbers() {
        return new ProductOfNumbers();
    }

    public static class ProductOfNumbers {
        private final List<Long> prefix;

        public ProductOfNumbers() {
            prefix = new ArrayList<>();
            prefix.add(1L);
        }

        public void add(int num) {
            if (num == 0) {
                prefix.clear();
                prefix.add(1L);
            } else {
                prefix.add(prefix.get(prefix.size() - 1) * num);
            }
        }

        public long getProduct(int k) {
            if (k >= prefix.size()) {
                return 0;
            }
            return prefix.get(prefix.size() - 1) / prefix.get(prefix.size() - 1 - k);
        }
    }
}

import java.util.PriorityQueue;
import java.util.Collections;

class Solution {
    public boolean isPossible(int[] target) {
        int n = target.length;
        if (n == 1) {
            return target[0] == 1;
        }
        PriorityQueue<Long> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long total = 0;
        for (int v : target) {
            total += v;
            maxHeap.offer((long) v);
        }
        while (true) {
            long max = maxHeap.poll();
            long rest = total - max;
            if (max == 1 || rest == 1) {
                return true;
            }
            if (rest == 0 || max < rest) {
                return false;
            }
            long prev = max % rest;
            if (prev == 0) {
                return false;
            }
            total = rest + prev;
            maxHeap.offer(prev);
        }
    }
}

