import java.math.BigInteger;

class Solution {
    public static int countOrders(int n) {
        BigInteger MOD = BigInteger.valueOf(1000000007L);
        BigInteger fact = BigInteger.ONE;
        for (int i = 2; i <= 2 * n; i++) {
            fact = fact.multiply(BigInteger.valueOf(i)).mod(MOD);
        }
        BigInteger pow2 = BigInteger.ONE;
        BigInteger base = BigInteger.valueOf(2);
        int exp = n;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                pow2 = pow2.multiply(base).mod(MOD);
            }
            base = base.multiply(base).mod(MOD);
            exp >>= 1;
        }
        BigInteger inv = BigInteger.ONE;
        BigInteger b = pow2;
        BigInteger e = MOD.subtract(BigInteger.valueOf(2));
        while (e.signum() > 0) {
            if (e.testBit(0)) {
                inv = inv.multiply(b).mod(MOD);
            }
            b = b.multiply(b).mod(MOD);
            e = e.shiftRight(1);
        }
        return fact.multiply(inv).mod(MOD).intValue();
    }
}

