import java.lang.Math;

class Solution {
    public static int[] closestDivisors(int num) {
        double bestDiff = Double.POSITIVE_INFINITY;
        int[] bestPair = new int[0];
        for (int product : new int[]{num + 1, num + 2}) {
            int limit = (int)Math.floor(Math.sqrt(product));
            for (int i = limit; i >= 1; i--) {
                if (product % i == 0) {
                    int j = product / i;
                    int diff = Math.abs(i - j);
                    if (diff < bestDiff) {
                        bestDiff = diff;
                        bestPair = new int[]{i, j};
                    }
                    break;
                }
            }
        }
        return bestPair;
    }
}

