public class Solution {
    public String largestMultipleOfThree(int[] digits) {
        int[] cnt = new int[10];
        int sum = 0;
        for (int d : digits) {
            cnt[d]++;
            sum += d;
        }
        int rem = sum % 3;
        if (rem != 0) {
            if (!removeDigits(cnt, rem, 1)) {
                if (!removeDigits(cnt, 3 - rem, 2)) {
                    return "";
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int d = 9; d >= 0; d--) {
            for (int i = 0; i < cnt[d]; i++) {
                sb.append(d);
            }
        }
        if (sb.length() == 0) {
            return "";
        }
        if (sb.charAt(0) == '0') {
            return "0";
        }
        return sb.toString();
    }

    private boolean removeDigits(int[] cnt, int remainder, int needed) {
        for (int d = 0; d <= 9 && needed > 0; d++) {
            if (d % 3 == remainder) {
                while (cnt[d] > 0 && needed > 0) {
                    cnt[d]--;
                    needed--;
                }
            }
        }
        return needed == 0;
    }
}

