class Solution {
    private static class MinHeap {
        private final List<int[]> heap = new ArrayList<>();
        void push(int c, int i, int j) {
            heap.add(new int[]{c, i, j});
            int idx = heap.size() - 1;
            while (idx > 0) {
                int p = (idx - 1) >> 1;
                if (heap.get(p)[0] <= heap.get(idx)[0]) break;
                int[] tmp = heap.get(p);
                heap.set(p, heap.get(idx));
                heap.set(idx, tmp);
                idx = p;
            }
        }
        int[] pop() {
            int[] top = heap.get(0);
            int[] last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                int idx = 0;
                while (true) {
                    int l = idx * 2 + 1;
                    int r = idx * 2 + 2;
                    int smallest = idx;
                    if (l < heap.size() && heap.get(l)[0] < heap.get(smallest)[0]) smallest = l;
                    if (r < heap.size() && heap.get(r)[0] < heap.get(smallest)[0]) smallest = r;
                    if (smallest == idx) break;
                    int[] tmp = heap.get(smallest);
                    heap.set(smallest, heap.get(idx));
                    heap.set(idx, tmp);
                    idx = smallest;
                }
            }
            return top;
        }
        boolean isEmpty() {
            return heap.isEmpty();
        }
    }

    public static int minCost(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int INF = 1_000_000_000;
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, INF);
        MinHeap heap = new MinHeap();
        dist[0][0] = 0;
        heap.push(0, 0, 0);
        int[][] dirs = {
            {0, 1, 1},
            {0, -1, 2},
            {1, 0, 3},
            {-1, 0, 4}
        };
        while (!heap.isEmpty()) {
            int[] cur = heap.pop();
            int cost = cur[0];
            int i = cur[1];
            int j = cur[2];
            if (cost != dist[i][j]) continue;
            if (i == m - 1 && j == n - 1) return cost;
            for (int[] d : dirs) {
                int ni = i + d[0];
                int nj = j + d[1];
                if (ni < 0 || nj < 0 || ni >= m || nj >= n) continue;
                int newCost = cost + (grid[i][j] == d[2] ? 0 : 1);
                if (newCost < dist[ni][nj]) {
                    dist[ni][nj] = newCost;
                    heap.push(newCost, ni, nj);
                }
            }
        }
        return dist[m - 1][n - 1];
    }
}

