        int leftZig = node.left != null ? 1 + leftChild[1] : 0;
        int rightZig = node.right != null ? 1 + rightChild[0] : 0;
        best = Math.max(best, Math.max(leftZig, rightZig));
        return new int[]{leftZig, rightZig};
    }
}

