class Solution {
    public static int longestEvenVowelSubstring(String s) {
        int[] firstPos = new int[32];
        Arrays.fill(firstPos, -2);
        firstPos[0] = -1;
        int mask = 0;
        int maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int bit = "aeiou".indexOf(ch);
            if (bit != -1) {
                mask ^= 1 << bit;
            }
            if (firstPos[mask] != -2) {
                int len = i - firstPos[mask];
                if (len > maxLen) {
                    maxLen = len;
                }
            } else {
                firstPos[mask] = i;
            }
        }
        return maxLen;
    }
}

