class Solution {
    private int maxSum = 0;

    public int maxSumBST(TreeNode root) {
        dfs(root);
        return maxSum;
    }

    private Result dfs(TreeNode node) {
        if (node == null) {
            return new Result(true, 0, Integer.MAX_VALUE, Integer.MIN_VALUE);
        }
        Result left = dfs(node.left);
        Result right = dfs(node.right);
        boolean isBST = left.isBST && right.isBST && node.val > left.max && node.val < right.min;
        if (isBST) {
            int curSum = node.val + left.sum + right.sum;
            if (curSum > maxSum) {
                maxSum = curSum;
            }
            int curMin = Math.min(node.val, left.min);
            int curMax = Math.max(node.val, right.max);
            return new Result(true, curSum, curMin, curMax);
        } else {
            return new Result(false, 0, 0, 0);
        }
    }

    private static class Result {
        boolean isBST;
        int sum;
        int min;
        int max;
        Result(boolean isBST, int sum, int min, int max) {
            this.isBST = isBST;
            this.sum = sum;
            this.min = min;
            this.max = max;
        }
    }
}

