public class Solution {
    public static int numOfMinutes(int n, int headID, int[] manager, int[] informTime) {
        List<Integer>[] subordinates = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            subordinates[i] = new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            int m = manager[i];
            if (m != -1) {
                subordinates[m].add(i);
            }
        }
        return dfs(headID, subordinates, informTime);
    }

    private static int dfs(int emp, List<Integer>[] subordinates, int[] informTime) {
        if (subordinates[emp].isEmpty()) {
            return 0;
        }
        int maxChildTime = 0;
        for (int sub : subordinates[emp]) {
            int childTime = dfs(sub, subordinates, informTime);
            if (childTime > maxChildTime) {
                maxChildTime = childTime;
            }
        }
        return informTime[emp] + maxChildTime;
    }
}

