public class Solution {
    public static double frogPosition(int n, int[][] edges, int t, int target) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }
        boolean[] visited = new boolean[n + 1];
        double[] result = new double[1];
        dfs(1, 0, 1.0, graph, visited, t, target, result);
        return result[0];
    }

    private static void dfs(int node, int time, double prob, List<Integer>[] graph, boolean[] visited, int t, int target, double[] result) {
        visited[node] = true;
        if (time == t) {
            if (node == target) {
                result[0] += prob;
            }
            visited[node] = false;
            return;
        }
        int unvisitedCount = 0;
        for (int v : graph[node]) {
            if (!visited[v]) {
                unvisitedCount++;
            }
        }
        if (unvisitedCount == 0) {
            if (node == target) {
                result[0] += prob;
            }
            visited[node] = false;
            return;
        }
        double nextProb = prob / unvisitedCount;
        for (int v : graph[node]) {
            if (!visited[v]) {
                dfs(v, time + 1, nextProb, graph, visited, t, target, result);
            }
        }
        visited[node] = false;
    }
}

public class Solution {
    public class CustomStack {
        private final int maxSize;
        private final int[] stack;
        private final int[] inc;
        private int size;
        public CustomStack(int maxSize) {
            this.maxSize = maxSize;
            this.stack = new int[maxSize];
            this.inc = new int[maxSize];
            this.size = 0;
        }
        public void push(int x) {
            if (size < maxSize) {
                stack[size++] = x;
            }
        }
        public int pop() {
            if (size == 0) return -1;
            int i = size - 1;
            int val = stack[i] + inc[i];
            size--;
            if (i > 0) {
                inc[i - 1] += inc[i];
            }
            inc[i] = 0;
            return val;
        }
        public void increment(int k, int val) {
            int idx = Math.min(k, size) - 1;
            if (idx >= 0) {
                inc[idx] += val;
            }
        }
    }
}

