class Solution {
    public static List<Integer> luckyNumbers(int[][] matrix) {
        int rowCount = matrix.length;
        if (rowCount == 0) return new ArrayList<>();
        int colCount = matrix[0].length;

        int[] rowMins = new int[rowCount];
        int[] colMaxes = new int[colCount];
        Arrays.fill(rowMins, Integer.MAX_VALUE);
        Arrays.fill(colMaxes, Integer.MIN_VALUE);

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                int val = matrix[i][j];
                if (val < rowMins[i]) rowMins[i] = val;
                if (val > colMaxes[j]) colMaxes[j] = val;
            }
        }

        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                int val = matrix[i][j];
                if (val == rowMins[i] && val == colMaxes[j]) {
                    result.add(val);
                }
            }
        }

        return result;
    }
}

