public class Solution {
    private static int power(int x, Map<Integer, Integer> memo) {
        if (memo.containsKey(x)) return memo.get(x);
        int next = (x % 2 == 0) ? x / 2 : 3 * x + 1;
        int p = 1 + power(next, memo);
        memo.put(x, p);
        return p;
    }

    public static int getKth(int lo, int hi, int k) {
        Map<Integer, Integer> memo = new HashMap<>();
        memo.put(1, 0);
        List<Node> list = new ArrayList<>();
        for (int i = lo; i <= hi; i++) {
            list.add(new Node(i, power(i, memo)));
        }
        list.sort((a, b) -> a.pow == b.pow ? a.num - b.num : a.pow - b.pow);
        return list.get(k - 1).num;
    }

    private static class Node {
