class Solution {
    public static int findDistanceValue(int[] arr1, int[] arr2, int d) {
        Arrays.sort(arr2);
        int distanceCount = 0;
        for (int i = 0; i < arr1.length; i++) {
            int val = arr1[i];
            int left = 0, right = arr2.length - 1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (arr2[mid] < val) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            boolean ok = true;
            if (left < arr2.length && Math.abs(arr2[left] - val) <= d) ok = false;
            if (right >= 0 && Math.abs(arr2[right] - val) <= d) ok = false;
            if (ok) distanceCount++;
        }
        return distanceCount;
    }
}

