class Solution {
    public static boolean hasValidPath(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        int[] opposite = {1, 0, 3, 2};

        int[][] allowed = new int[7][];
        allowed[1] = new int[]{2, 3}; // left, right
        allowed[2] = new int[]{0, 1}; // up, down
        allowed[3] = new int[]{2, 1}; // left, down
        allowed[4] = new int[]{3, 1}; // right, down
        allowed[5] = new int[]{2, 0}; // left, up
        allowed[6] = new int[]{3, 0}; // right, up

        boolean[][] visited = new boolean[m][n];
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{0, 0});
        visited[0][0] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            if (r == m - 1 && c == n - 1) {
                return true;
            }
            for (int dir : allowed[grid[r][c]]) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                    boolean connectsBack = false;
                    for (int d : allowed[grid[nr][nc]]) {
                        if (d == opposite[dir]) {
                            connectsBack = true;
                            break;
                        }
                    }
                    if (connectsBack) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }
        return false;
    }
}

