class Solution {
    public int maxSizeSlices(int[] slices) {
        int m = slices.length;
        int n = m / 3;
        int[] first = Arrays.copyOfRange(slices, 0, m - 1);
        int[] second = Arrays.copyOfRange(slices, 1, m);
        return Math.max(solve(first, n), solve(second, n));
    }

    private int solve(int[] arr, int picks) {
        int len = arr.length;
        int[][] dp = new int[len + 1][picks + 1];
        int NEG = Integer.MIN_VALUE / 4;
        for (int i = 0; i <= len; i++) {
            Arrays.fill(dp[i], NEG);
        }
        for (int i = 0; i <= len; i++) {
            dp[i][0] = 0;
        }
        for (int i = 1; i <= len; i++) {
            for (int j = 1; j <= picks; j++) {
                int notTake = dp[i - 1][j];
                int take = NEG;
                if (i >= 2) {
                    take = dp[i - 2][j - 1] + arr[i - 1];
                } else if (i == 1 && j == 1) {
                    take = arr[i - 1];
                }
                dp[i][j] = Math.max(notTake, take);
            }
        }
        return dp[len][picks];
    }
}

import java.util.*;

class Solution {
    public static long sumFourDivisors(int[] nums) {
        long total = 0;
        for (int n : nums) {
            int divisorCount = 0;
            long divisorSum = 0;
            for (int i = 1; i * i <= n; i++) {
                if (n % i == 0) {
                    divisorCount++;
                    divisorSum += i;
                    int other = n / i;
                    if (other != i) {
                        divisorCount++;
                        divisorSum += other;
                    }
                    if (divisorCount > 4) {
                        break;
                    }
                }
            }
            if (divisorCount == 4) {
                total += divisorSum;
            }
        }
        return total;
    }
}

class Solution {
    public static String longestHappyPrefix(String s) {
        int n = s.length();
        if (n == 0) {
            return "";
        }
        int[] pi = new int[n];
        int j = 0;
        for (int i = 1; i < n; i++) {
            while (j > 0 && s.charAt(i) != s.charAt(j)) {
                j = pi[j - 1];
            }
            if (s.charAt(i) == s.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }
        int longestLen = pi[n - 1];
        return s.substring(0, longestLen);
    }
}

