class UndergroundSystem {
    private static class Pair {
        String station;
        int time;
        Pair(String station, int time) {
            this.station = station;
            this.time = time;
        }
    }

    private static class Stat {
        long totalTime;
        int trips;
        Stat(long totalTime, int trips) {
            this.totalTime = totalTime;
            this.trips = trips;
        }
    }

    private final Map<Integer, Pair> active;
    private final Map<String, Stat> stats;

    public UndergroundSystem() {
        active = new HashMap<>();
        stats = new HashMap<>();
    }

    public void checkIn(int id, String stationName, int t) {
        active.put(id, new Pair(stationName, t));
    }

    public void checkOut(int id, String stationName, int t) {
        Pair info = active.get(id);
        int travelTime = t - info.time;
        String routeKey = info.station + "|" + stationName;
        Stat cur = stats.get(routeKey);
        if (cur != null) {
            cur.totalTime += travelTime;
            cur.trips += 1;
        } else {
            stats.put(routeKey, new Stat(travelTime, 1));
        }
        active.remove(id);
    }

    public double getAverageTime(String startStation, String endStation) {
        String key = startStation + "|" + endStation;
        Stat data = stats.get(key);
        return (double) data.totalTime / data.trips;
    }
}

public class Solution {
    public static int countTeams(int[] rating) {
        int n = rating.length;
        int total = 0;
        for (int j = 0; j < n; j++) {
            int leftLess = 0, leftGreater = 0;
            for (int i = 0; i < j; i++) {
                if (rating[i] < rating[j]) leftLess++;
                else if (rating[i] > rating[j]) leftGreater++;
            }
            int rightGreater = 0, rightLess = 0;
            for (int k = j + 1; k < n; k++) {
                if (rating[k] > rating[j]) rightGreater++;
                else if (rating[k] < rating[j]) rightLess++;
            }
            total += leftLess * rightGreater + leftGreater * rightLess;
        }
        return total;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public int findGoodStrings(String s1, String s2, String evil) {
        int n = s1.length();
        int m = evil.length();

        // build prefix function for evil
        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && evil.charAt(i) != evil.charAt(j)) {
                j = pi[j - 1];
            }
            if (evil.charAt(i) == evil.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }

        // build automaton transitions
        int[][] nxt = new int[m + 1][26];
        for (int state = 0; state <= m; state++) {
            for (int ch = 0; ch < 26; ch++) {
                if (state < m && ch == evil.charAt(state) - 'a') {
                    nxt[state][ch] = state + 1;
                } else {
                    if (state == 0) {
                        nxt[state][ch] = 0;
                    } else {
                        nxt[state][ch] = nxt[pi[state - 1]][ch];
                    }
                }
            }
        }

        long[][][][] dp = new long[n + 1][2][2][m];
        dp[0][1][1][0] = 1;

        for (int pos = 0; pos < n; pos++) {
            for (int low = 0; low <= 1; low++) {
                for (int high = 0; high <= 1; high++) {
                    for (int k = 0; k < m; k++) {
                        long cur = dp[pos][low][high][k];
                        if (cur == 0) continue;
                        char lowChar = low == 1 ? s1.charAt(pos) : 'a';
                        char highChar = high == 1 ? s2.charAt(pos) : 'z';
                        for (char c = lowChar; c <= highChar; c++) {
                            int idx = c - 'a';
                            int nk = nxt[k][idx];
                            if (nk == m) continue; // contains evil, skip
                            int nLow = (low == 1 && c == lowChar) ? 1 : 0;
                            int nHigh = (high == 1 && c == highChar) ? 1 : 0;
                            dp[pos + 1][nLow][nHigh][nk] = (dp[pos + 1][nLow][nHigh][nk] + cur) % MOD;
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int low = 0; low <= 1; low++) {
            for (int high = 0; high <= 1; high++) {
                for (int k = 0; k < m; k++) {
                    ans = (ans + dp[n][low][high][k]) % MOD;
                }
            }
        }
        return (int) ans;
    }
}

