class Solution {
    public static int countLargestGroup(int n) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 1; i <= n; i++) {
            int sum = digitSum(i);
            freq.put(sum, freq.getOrDefault(sum, 0) + 1);
        }
        int maxSize = 0;
        for (int cnt : freq.values()) {
            if (cnt > maxSize) maxSize = cnt;
        }
        int answer = 0;
        for (int cnt : freq.values()) {
            if (cnt == maxSize) answer++;
        }
        return answer;
    }

    private static int digitSum(int x) {
        int s = 0;
        while (x > 0) {
            s += x % 10;
            x /= 10;
        }
        return s;
    }
}

class Solution {
    public static boolean checkOverlap(double radius, double xCenter, double yCenter, double x1, double y1, double x2, double y2) {
        double closestX = Math.max(x1, Math.min(xCenter, x2));
        double closestY = Math.max(y1, Math.min(yCenter, y2));
        double dx = xCenter - closestX;
        double dy = yCenter - closestY;
        return dx * dx + dy * dy <= radius * radius;
    }
}

