class Solution {
    public int[] processQueries(int[] queries, int m) {
        int n = queries.length;
        int size = m + n + 2;
        FenwickTree bit = new FenwickTree(size);
        int[] pos = new int[m + 1];
        for (int i = 1; i <= m; i++) {
            int p = i + n;
            pos[i] = p;
            bit.add(p, 1);
        }
        int[] ans = new int[n];
        int nextFree = n;
        for (int i = 0; i < n; i++) {
            int x = queries[i];
            int curPos = pos[x];
            ans[i] = bit.sum(curPos - 1);
            bit.add(curPos, -1);
            bit.add(nextFree, 1);
            pos[x] = nextFree;
            nextFree--;
        }
        return ans;
    }

    private static class FenwickTree {
        int[] tree;
        FenwickTree(int n) {
            tree = new int[n + 1];
        }
        void add(int idx, int delta) {
            for (int i = idx; i < tree.length; i += i & -i) {
                tree[i] += delta;
            }
        }
        int sum(int idx) {
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += tree[i];
            }
            return res;
        }
    }
}

