class Solution {
    public static int numberOfSteps(String s) {
        if (s.equals("1")) return 0;
        int steps = 0;
        int carry = 0;
        for (int i = s.length() - 1; i > 0; i--) {
            int bit = s.charAt(i) - '0';
            int sum = bit + carry;
            if (sum == 0) {
                steps += 1;
            } else if (sum == 1) {
                steps += 2;
                carry = 1;
            } else {
                steps += 1;
            }
        }
        steps += carry;
        return steps;
    }
}

