class Solution {
    public static int findMinFibonacciNumbers(int k) {
        List<Integer> fib = new ArrayList<>();
        fib.add(1);
        fib.add(1);
        while (fib.get(fib.size() - 1) < k) {
            int size = fib.size();
            fib.add(fib.get(size - 1) + fib.get(size - 2));
        }
        int count = 0;
        int remaining = k;
        while (remaining > 0) {
            int left = 0;
            int right = fib.size() - 1;
            while (left < right) {
                int mid = (left + right + 1) / 2;
                if (fib.get(mid) <= remaining) {
                    left = mid;
                } else {
                    right = mid - 1;
                }
            }
            remaining -= fib.get(left);
            count++;
        }
        return count;
    }
}

