class Solution {
    public static int restoreArray(String s, int k) {
        final int MOD = 1000000007;
        int n = s.length();
        int maxLen = Integer.toString(k).length();
        int[] dp = new int[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int len = 1; len <= maxLen; len++) {
                if (i - len < 0) break;
                if (s.charAt(i - len) == '0') continue;
                String sub = s.substring(i - len, i);
                long val = Long.parseLong(sub);
                if (val > k) break;
                dp[i] = (int) ((dp[i] + dp[i - len]) % MOD);
            }
        }
        return dp[n];
    }
}

