        final long MOD = 1_000_000_007L;
        long same = 6;
        long diff = 6;
        for (int i = 2; i <= n; i++) {
            long newSame = (same * 3 + diff * 2) % MOD;
            long newDiff = (same * 2 + diff * 2) % MOD;
