        long total = 3L << (n - 1);
        if (k > total) return "";
        StringBuilder sb = new StringBuilder();
        char prev = 0;
        for (int i = 0; i < n; i++) {
            for (char c = 'a'; c <= 'c'; c++) {
                if (c == prev) continue;
                long cnt = 1L << (n - i - 1);
                if (k > cnt) {
                    k -= cnt;
