class Solution {
    public static String reformatString(String s) {
        List<Character> letters = new ArrayList<>();
        List<Character> digits = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch >= '0' && ch <= '9') {
                digits.add(ch);
            } else {
                letters.add(ch);
            }
        }
        if (Math.abs(letters.size() - digits.size()) > 1) {
            return "";
        }
        boolean startWithLetter = letters.size() > digits.size();
        List<Character> first = startWithLetter ? letters : digits;
        List<Character> second = startWithLetter ? digits : letters;
        StringBuilder result = new StringBuilder();
        int n = Math.max(first.size(), second.size());
        for (int i = 0; i < n; i++) {
            if (i < first.size()) result.append(first.get(i));
            if (i < second.size()) result.append(second.get(i));
        }
        return result.toString();
    }
}

