class Solution {
    public static int minNumberOfFrogs(String croakOfFrogs) {
        if (croakOfFrogs == null || croakOfFrogs.length() % 5 != 0) {
            return -1;
        }
        int[] map = new int[128];
        map['c'] = 0;
        map['r'] = 1;
        map['o'] = 2;
        map['a'] = 3;
        map['k'] = 4;
        int[] cnt = new int[5];
        int frogs = 0;
        int maxFrogs = 0;
        for (int i = 0; i < croakOfFrogs.length(); i++) {
            char ch = croakOfFrogs.charAt(i);
            int idx = map[ch];
            if (idx == 0) {
                cnt[0]++;
                frogs++;
                if (frogs > maxFrogs) {
                    maxFrogs = frogs;
                }
            } else {
                if (cnt[idx - 1] == 0) {
                    return -1;
                }
                cnt[idx - 1]--;
                cnt[idx]++;
                if (idx == 4) {
                    frogs--;
                }
            }
        }
        return frogs == 0 ? maxFrogs : -1;
    }
}

