public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countArrays(int n, int m, int k) {
        if (k == 0 || k > n) return 0;
        long[][][] dp = new long[n + 1][m + 1][k + 1];
        for (int v = 1; v <= m; v++) {
            dp[1][v][1] = 1;
        }
        for (int pos = 1; pos < n; pos++) {
            for (int max = 1; max <= m; max++) {
                for (int cnt = 1; cnt <= k; cnt++) {
                    long cur = dp[pos][max][cnt];
                    if (cur == 0) continue;
                    dp[pos + 1][max][cnt] = (dp[pos + 1][max][cnt] + cur * max) % MOD;
                    if (cnt + 1 <= k) {
                        for (int x = max + 1; x <= m; x++) {
                            dp[pos + 1][x][cnt + 1] = (dp[pos + 1][x][cnt + 1] + cur) % MOD;
                        }
                    }
                }
            }
        }
        long ans = 0;
        for (int max = 1; max <= m; max++) {
            ans = (ans + dp[n][max][k]) % MOD;
        }
        return (int) ans;
    }
}

public class Solution {
    public static int maxScore(String s) {
        int n = s.length();
        int totalOnes = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') totalOnes++;
        }
        int zerosLeft = 0;
        int onesSeen = 0;
        int maxScore = 0;
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) == '0') zerosLeft++; else onesSeen++;
            int score = zerosLeft + (totalOnes - onesSeen);
            if (score > maxScore) maxScore = score;
        }
        return maxScore;
    }
}

