                result.add(diag.get(k));
            }
        }
        return result;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int constrainedSubsequenceSum(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] dp = new int[n];
        Deque<Integer> deque = new ArrayDeque<>();
        dp[0] = nums[0];
        int answer = dp[0];
        deque.addLast(0);
        for (int i = 1; i < n; i++) {
            while (!deque.isEmpty() && deque.peekFirst() < i - k) {
                deque.pollFirst();
            }
            int bestPrev = dp[deque.peekFirst()] > 0 ? dp[deque.peekFirst()] : 0;
            dp[i] = nums[i] + bestPrev;
            if (dp[i] > answer) answer = dp[i];
            while (!deque.isEmpty() && dp[deque.peekLast()] <= dp[i]) {
                deque.pollLast();
            }
            deque.addLast(i);
        }
        return answer;
    }
}

