class Solution {
    public int maxDiff(int num) {
        String s = Integer.toString(num);
        char[] chars = s.toCharArray();

        // Compute maximum possible number
        char replaceForMax = 0;
        for (char c : chars) {
            if (c != '9') {
                replaceForMax = c;
                break;
            }
        }
        int maxVal;
        if (replaceForMax == 0) {
            maxVal = num;
        } else {
            char[] maxChars = chars.clone();
            for (int i = 0; i < maxChars.length; i++) {
                if (maxChars[i] == replaceForMax) {
                    maxChars[i] = '9';
                }
            }
            maxVal = Integer.parseInt(new String(maxChars));
        }

        // Compute minimum possible number
        char[] minChars = chars.clone();
        if (minChars[0] != '1') {
            char replaceForMin = minChars[0];
            for (int i = 0; i < minChars.length; i++) {
                if (minChars[i] == replaceForMin) {
                    minChars[i] = '1';
                }
            }
        } else {
            char replaceForMin = 0;
            for (int i = 1; i < minChars.length; i++) {
                if (minChars[i] != '0' && minChars[i] != minChars[0]) {
                    replaceForMin = minChars[i];
                    break;
                }
            }
            if (replaceForMin != 0) {
                for (int i = 0; i < minChars.length; i++) {
                    if (minChars[i] == replaceForMin) {
                        minChars[i] = '0';
                    }
                }
            }
        }
        int minVal = Integer.parseInt(new String(minChars));

        return maxVal - minVal;
    }
}

