class Solution {
    public static int numberWays(List<List<Integer>> hats) {
        final int MOD = 1_000_000_007;
        int n = hats.size();
        int totalMask = 1 << n;
        List<Integer>[] peopleForHat = new ArrayList[41];
        for (int i = 0; i <= 40; i++) {
            peopleForHat[i] = new ArrayList<>();
        }
        for (int person = 0; person < n; person++) {
            for (int h : hats.get(person)) {
                peopleForHat[h].add(person);
            }
        }
        long[] dp = new long[totalMask];
        dp[0] = 1;
        for (int hat = 1; hat <= 40; hat++) {
            List<Integer> candidates = peopleForHat[hat];
            if (candidates.isEmpty()) continue;
            for (int mask = totalMask - 1; mask >= 0; mask--) {
                long curWays = dp[mask];
                if (curWays == 0) continue;
                for (int p : candidates) {
                    if ((mask & (1 << p)) == 0) {
                        int newMask = mask | (1 << p);
                        dp[newMask] = (dp[newMask] + curWays) % MOD;
                    }
                }
            }
        }
        return (int) dp[totalMask - 1];
    }
}

import java.util.*;

class Solution {
    private static class MinHeap {
        private final List<int[]> heap = new ArrayList<>();

        int size() {
            return heap.size();
        }

        void push(int[] node) {
            heap.add(node);
            int i = heap.size() - 1;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (heap.get(p)[0] <= heap.get(i)[0]) break;
                Collections.swap(heap, p, i);
                i = p;
            }
        }

        int[] pop() {
            if (heap.isEmpty()) return null;
            int[] top = heap.get(0);
            int[] last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                int i = 0;
                while (true) {
                    int l = i * 2 + 1;
                    int r = i * 2 + 2;
                    int smallest = i;
                    if (l < heap.size() && heap.get(l)[0] < heap.get(smallest)[0]) smallest = l;
                    if (r < heap.size() && heap.get(r)[0] < heap.get(smallest)[0]) smallest = r;
                    if (smallest == i) break;
                    Collections.swap(heap, i, smallest);
                    i = smallest;
                }
            }
            return top;
        }
    }

    public static int kthSmallestSum(int[][] mat, int k) {
        int[] sums = mat[0].clone();
        for (int rowIdx = 1; rowIdx < mat.length; rowIdx++) {
            int[] row = mat[rowIdx];
            MinHeap heap = new MinHeap();
            int limit = Math.min(k, sums.length);
            for (int i = 0; i < limit; i++) {
                heap.push(new int[]{sums[i] + row[0], i, 0});
            }
            List<Integer> newSumsList = new ArrayList<>();
            while (newSumsList.size() < k && heap.size() > 0) {
                int[] node = heap.pop();
                int total = node[0];
                int i = node[1];
                int j = node[2];
                newSumsList.add(total);
                if (j + 1 < row.length) {
                    heap.push(new int[]{sums[i] + row[j + 1], i, j + 1});
                }
            }
            sums = new int[newSumsList.size()];
            for (int i = 0; i < newSumsList.size(); i++) {
                sums[i] = newSumsList.get(i);
            }
        }
        return sums[k - 1];
    }
}

