class Solution {
    public int countTriplets(int[] arr) {
        int n = arr.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] ^ arr[i];
        }
        HashMap<Integer, long[]> map = new HashMap<>();
        long ans = 0;
        for (int idx = 0; idx <= n; idx++) {
            int val = pref[idx];
            if (map.containsKey(val)) {
                long[] data = map.get(val);
                long cnt = data[0];
                long sumIdx = data[1];
                ans += cnt * (idx - 1) - sumIdx;
            }
            long[] data = map.getOrDefault(val, new long[2]);
            data[0] += 1;
            data[1] += idx;
            map.put(val, data);
        }
        return (int) ans;
    }
}

