    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    private int rows;
    private int cols;
    private int[][] prefix;
    private int[][][] memo;

    public int ways(String[] pizza, int k) {
        rows = pizza.length;
        cols = pizza[0].length();
        buildPrefix(pizza);
        memo = new int[rows][cols][k];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }
        return dfs(0, 0, k - 1);
    }

    private void buildPrefix(String[] pizza) {
        prefix = new int[rows + 1][cols + 1];
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                int add = pizza[i - 1].charAt(j - 1) == 'A' ? 1 : 0;
                prefix[i][j] = prefix[i - 1][j] + prefix[i][j - 1] - prefix[i - 1][j - 1] + add;
            }
        }
    }

    private boolean hasApple(int r1, int c1, int r2, int c2) {
        int total = prefix[r2 + 1][c2 + 1] - prefix[r1][c2 + 1] - prefix[r2 + 1][c1] + prefix[r1][c1];
        return total > 0;
    }

    private int dfs(int r, int c, int cuts) {
        if (!hasApple(r, c, rows - 1, cols - 1)) {
            return 0;
        }
        if (cuts == 0) {
            return 1;
        }
        if (memo[r][c][cuts] != -1) {
            return memo[r][c][cuts];
        }
        long ways = 0;
        // Horizontal cuts
        for (int nr = r + 1; nr < rows; nr++) {
            if (hasApple(r, c, nr - 1, cols - 1)) {
                ways += dfs(nr, c, cuts - 1);
            }
        }
        // Vertical cuts
        for (int nc = c + 1; nc < cols; nc++) {
            if (hasApple(r, c, rows - 1, nc - 1)) {
                ways += dfs(r, nc, cuts - 1);
            }
        }
        ways %= MOD;
        memo[r][c][cuts] = (int) ways;
        return memo[r][c][cuts];
    }
}

