public class Solution {
    public static String rearrangeWords(String text) {
        String[] originalWords = text.split(" ");
        List<String> lowerWords = new ArrayList<>(originalWords.length);
        for (String w : originalWords) {
            lowerWords.add(w.toLowerCase());
        }
        class Indexed {
            String word;
            int idx;
            Indexed(String word, int idx) {
                this.word = word;
                this.idx = idx;
            }
        }
        List<Indexed> indexed = new ArrayList<>(lowerWords.size());
        for (int i = 0; i < lowerWords.size(); i++) {
            indexed.add(new Indexed(lowerWords.get(i), i));
        }
        Collections.sort(indexed, new Comparator<Indexed>() {
            @Override
            public int compare(Indexed a, Indexed b) {
                int lenDiff = a.word.length() - b.word.length();
                if (lenDiff != 0) {
                    return lenDiff;
                }
                return a.idx - b.idx;
            }
        });
        List<String> sorted = new ArrayList<>(indexed.size());
        for (Indexed obj : indexed) {
            sorted.add(obj.word);
        }
        if (!sorted.isEmpty()) {
            String first = sorted.get(0);
            if (!first.isEmpty()) {
                sorted.set(0, first.substring(0, 1).toUpperCase() + first.substring(1));
            }
        }
        return String.join(" ", sorted);
    }
}

