class Solution {
    public static String largestNumber(int[] cost, int target) {
        int[] dpLen = new int[target + 1];
        Arrays.fill(dpLen, -1);
        dpLen[0] = 0;
        for (int i = 1; i <= target; i++) {
            for (int d = 1; d <= 9; d++) {
                int c = cost[d - 1];
                if (i >= c && dpLen[i - c] != -1) {
                    dpLen[i] = Math.max(dpLen[i], dpLen[i - c] + 1);
                }
            }
        }
        if (dpLen[target] == -1) {
            return "0";
        }
        int remaining = target;
        int length = dpLen[target];
        StringBuilder result = new StringBuilder();
        for (int d = 9; d >= 1; d--) {
            int c = cost[d - 1];
            while (remaining >= c && dpLen[remaining - c] == length - 1) {
                result.append(d);
                remaining -= c;
                length--;
            }
        }
        return result.toString();
    }
}

