            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static int maxDarts(double[][] darts, double r) {
        int n = darts.length;
        if (n == 0) return 0;
        final double TWO_PI = Math.PI * 2;
        final double EPS = 1e-9;
        int best = 1;

        for (int i = 0; i < n; ++i) {
            List<double[]> events = new ArrayList<>();

            for (int j = 0; j < n; ++j) {
                if (i == j) continue;
                double dx = darts[j][0] - darts[i][0];
                double dy = darts[j][1] - darts[i][1];
                double d = Math.hypot(dx, dy);
                if (d > 2 * r + EPS) continue;

                double theta = Math.atan2(dy, dx);
                double delta = Math.acos(d / (2 * r));

                double start = theta - delta;
                double end = theta + delta;

                if (start < 0) start += TWO_PI;
                if (end < 0) end += TWO_PI;
                if (start >= TWO_PI) start -= TWO_PI;
                if (end >= TWO_PI) end -= TWO_PI;

                if (start > end) {
                    events.add(new double[]{start, 1});
                    events.add(new double[]{TWO_PI, -1});
                    events.add(new double[]{0, 1});
                    events.add(new double[]{end, -1});
                } else {
                    events.add(new double[]{start, 1});
                    events.add(new double[]{end, -1});
                }
            }

            events.sort((a, b) -> {
                double diff = a[0] - b[0];
                if (Math.abs(diff) > EPS) return diff > 0 ? 1 : -1;
                return Double.compare(b[1], a[1]);
            });

            int cur = 0;
            for (double[] ev : events) {
                cur += (int) ev[1];
                if (cur + 1 > best) best = cur + 1;
            }
        }

        return best;
    }
}

