            for (int i = 0; i < numCourses; i++) {
                if (reach[i][k]) {
                    for (int j = 0; j < numCourses; j++) {
                        if (reach[k][j]) {
                            reach[i][j] = true;
                        }
                    }
                }
            }
        }
        boolean[] answer = new boolean[queries.length];
        for (int idx = 0; idx < queries.length; idx++) {
            int u = queries[idx][0];
            int v = queries[idx][1];
            answer[idx] = reach[u][v];
        }
        return answer;
    }
}

