class Solution {
    public static long maxDotProduct(int[] nums1, int[] nums2) {
        int m = nums1.length;
        int n = nums2.length;
        long[][] dp = new long[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            Arrays.fill(dp[i], Long.MIN_VALUE);
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                long prod = (long) nums1[i - 1] * nums2[j - 1];
                long best = prod;
                if (dp[i - 1][j] > best) best = dp[i - 1][j];
                if (dp[i][j - 1] > best) best = dp[i][j - 1];
                if (dp[i - 1][j - 1] != Long.MIN_VALUE) {
                    long extend = dp[i - 1][j - 1] + prod;
                    if (extend > best) best = extend;
                }
                dp[i][j] = best;
            }
        }
        return dp[m][n];
    }
}

