class Solution {
    public static long maxArea(int h, int w, int[] horizontalCuts, int[] verticalCuts) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(horizontalCuts);
        Arrays.sort(verticalCuts);
        int maxHeight = Math.max(horizontalCuts[0], h - horizontalCuts[horizontalCuts.length - 1]);
        for (int i = 1; i < horizontalCuts.length; i++) {
            int gap = horizontalCuts[i] - horizontalCuts[i - 1];
            if (gap > maxHeight) maxHeight = gap;
        }
        int maxWidth = Math.max(verticalCuts[0], w - verticalCuts[verticalCuts.length - 1]);
        for (int i = 1; i < verticalCuts.length; i++) {
            int gap = verticalCuts[i] - verticalCuts[i - 1];
            if (gap > maxWidth) maxWidth = gap;
        }
        return ((long) maxHeight * maxWidth) % MOD;
    }
}

