class Solution {
    public int cherryPickup(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][][] dp = new int[rows][cols][cols];
        for (int c1 = 0; c1 < cols; c1++) {
            for (int c2 = 0; c2 < cols; c2++) {
                dp[rows - 1][c1][c2] = grid[rows - 1][c1] + (c1 == c2 ? 0 : grid[rows - 1][c2]);
            }
        }
        for (int r = rows - 2; r >= 0; r--) {
            for (int c1 = 0; c1 < cols; c1++) {
                for (int c2 = 0; c2 < cols; c2++) {
                    int best = 0;
                    for (int d1 = -1; d1 <= 1; d1++) {
                        int nc1 = c1 + d1;
                        if (nc1 < 0 || nc1 >= cols) continue;
                        for (int d2 = -1; d2 <= 1; d2++) {
                            int nc2 = c2 + d2;
                            if (nc2 < 0 || nc2 >= cols) continue;
                            best = Math.max(best, dp[r + 1][nc1][nc2]);
                        }
                    }
                    dp[r][c1][c2] = grid[r][c1] + (c1 == c2 ? 0 : grid[r][c2]) + best;
                }
            }
        }
        return dp[0][0][cols - 1];
    }
}

import java.util.*;

public class Solution {
    private static double[][] comb;
    private static double numerator;
    private static double denominator;
    private static int half;

    public double getProbability(int[] balls) {
        int total = 0;
        for (int b : balls) total += b;
        half = total / 2;
        int max = 0;
        for (int b : balls) max = Math.max(max, b);
        precomputeComb(max);
        numerator = 0.0;
        denominator = 0.0;
        dfs(balls, 0, 0, 0, 0, 1.0);
        double prob = numerator / denominator;
        return Math.round(prob * 100000.0) / 100000.0;
    }

    private void precomputeComb(int max) {
        comb = new double[max + 1][max + 1];
        for (int i = 0; i <= max; i++) {
            comb[i][0] = comb[i][i] = 1.0;
            for (int j = 1; j < i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }
    }

    private void dfs(int[] balls, int idx, int selected, int distinct1, int distinct2, double weight) {
        if (idx == balls.length) {
            if (selected == half) {
                denominator += weight;
                if (distinct1 == distinct2) {
                    numerator += weight;
                }
            }
            return;
        }
        int cnt = balls[idx];
        for (int take = 0; take <= cnt; take++) {
            int newSelected = selected + take;
            if (newSelected > half) continue;
            int newDistinct1 = distinct1 + (take > 0 ? 1 : 0);
            int newDistinct2 = distinct2 + ((cnt - take) > 0 ? 1 : 0);
            double newWeight = weight * comb[cnt][take];
            dfs(balls, idx + 1, newSelected, newDistinct1, newDistinct2, newWeight);
        }
    }
}

import java.util.HashSet;

class Solution {
    public static boolean hasAllCodes(String s, int k) {
        if (s.length() < k) return false;
        int totalCodes = 1 << k;
        HashSet<Integer> seen = new HashSet<>();
        int mask = totalCodes - 1;
        int hash = 0;
        for (int i = 0; i < s.length(); i++) {
            hash = ((hash << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen.add(hash);
                if (seen.size() == totalCodes) return true;
            }
        }
        return seen.size() == totalCodes;
    }
}

