class Solution {
    public static int minReorder(int n, int[][] connections) {
        Set<String> directed = new HashSet<>();
        for (int[] edge : connections) {
            directed.add(edge[0] + "->" + edge[1]);
        }

        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : connections) {
            int a = edge[0];
            int b = edge[1];
            adj[a].add(b);
            adj[b].add(a);
        }

        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        visited[0] = true;
        int reversals = 0;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    if (directed.contains(u + "->" + v)) {
                        reversals++;
                    }
                    stack.push(v);
                }
            }
        }

        return reversals;
    }
}

class BrowserHistory {
