public class Solution {
    public static int minCost(int[] houses, int[][] cost, int m, int n, int target) {
        long INF = (long) 1e15;
        long[][] dp = new long[target + 1][n + 1];
        for (int t = 0; t <= target; t++) {
            for (int c = 0; c <= n; c++) {
                dp[t][c] = INF;
            }
        }
        if (houses[0] != 0) {
            dp[1][houses[0]] = 0;
        } else {
            for (int c = 1; c <= n; c++) {
                dp[1][c] = cost[0][c - 1];
            }
        }
        for (int i = 1; i < m; i++) {
            long[][] newDp = new long[target + 1][n + 1];
            for (int t = 0; t <= target; t++) {
                for (int c = 0; c <= n; c++) {
                    newDp[t][c] = INF;
                }
            }
            int[] possibleColors;
            if (houses[i] != 0) {
                possibleColors = new int[]{houses[i]};
            } else {
                possibleColors = new int[n];
                for (int idx = 0; idx < n; idx++) {
                    possibleColors[idx] = idx + 1;
                }
            }
            for (int prevT = 1; prevT <= target; prevT++) {
                for (int prevC = 1; prevC <= n; prevC++) {
                    long prevCost = dp[prevT][prevC];
                    if (prevCost == INF) continue;
                    for (int curC : possibleColors) {
                        long addCost = houses[i] == 0 ? cost[i][curC - 1] : 0;
                        int curT = (curC == prevC) ? prevT : prevT + 1;
                        if (curT > target) continue;
                        long total = prevCost + addCost;
                        if (total < newDp[curT][curC]) {
                            newDp[curT][curC] = total;
                        }
                    }
                }
            }
            dp = newDp;
        }
        long answer = INF;
        for (int c = 1; c <= n; c++) {
            answer = Math.min(answer, dp[target][c]);
        }
        return answer == INF ? -1 : (int) answer;
    }
}

