class Solution {
    public static int[] strongestValues(int[] arr, int k) {
        int[] sorted = arr.clone();
        Arrays.sort(sorted);
        int n = sorted.length;
        int centre = sorted[(n - 1) / 2];
        int left = 0;
        int right = n - 1;
        int[] result = new int[k];
        int idx = 0;
        while (idx < k) {
            int leftDiff = Math.abs(sorted[left] - centre);
            int rightDiff = Math.abs(sorted[right] - centre);
            if (rightDiff > leftDiff || (rightDiff == leftDiff && sorted[right] > sorted[left])) {
                result[idx++] = sorted[right];
                right--;
            } else {
                result[idx++] = sorted[left];
                left++;
            }
        }
        return result;
    }
}

