public class Solution {
    public int minSumOfLengths(int[] arr, int target) {
        int n = arr.length;
        int INF = Integer.MAX_VALUE / 2;
        int[] bestLeft = new int[n];
        Arrays.fill(bestLeft, INF);
        long sum = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            sum += arr[right];
            while (sum > target && left <= right) {
                sum -= arr[left++];
            }
            if (sum == target) {
                int len = right - left + 1;
                bestLeft[right] = Math.min(bestLeft[right], len);
            }
        }
        for (int i = 1; i < n; i++) {
            bestLeft[i] = Math.min(bestLeft[i], bestLeft[i - 1]);
        }
        sum = 0;
        left = 0;
        int answer = INF;
        for (int right = 0; right < n; right++) {
            sum += arr[right];
            while (sum > target && left <= right) {
                sum -= arr[left++];
            }
            if (sum == target) {
                int len = right - left + 1;
                if (left > 0 && bestLeft[left - 1] < INF) {
                    answer = Math.min(answer, bestLeft[left - 1] + len);
                }
            }
        }
        return answer == INF ? -1 : answer;
    }
}

