class Solution {
    public static long allocateMailboxes(int[] houses, int k) {
        Arrays.sort(houses);
        int n = houses.length;
        if (k >= n) return 0L;

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + houses[i];
        }

        long[][] cost = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int mid = (i + j) / 2;
                long left = (long) houses[mid] * (mid - i) - (prefix[mid] - prefix[i]);
                long right = (prefix[j + 1] - prefix[mid + 1]) - (long) houses[mid] * (j - mid);
                cost[i][j] = left + right;
            }
        }

        long[][] dp = new long[k + 1][n];
        for (int m = 0; m <= k; m++) {
            Arrays.fill(dp[m], Long.MAX_VALUE);
        }
        for (int i = 0; i < n; i++) {
            dp[1][i] = cost[0][i];
        }

        for (int m = 2; m <= k; m++) {
            for (int i = m - 1; i < n; i++) {
                long best = Long.MAX_VALUE;
                for (int p = m - 2; p < i; p++) {
                    long cur = dp[m - 1][p] + cost[p + 1][i];
                    if (cur < best) best = cur;
                }
                dp[m][i] = best;
            }
        }
        return dp[k][n - 1];
    }
}

