class Solution {
    public static int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) {
            return -1;
        }
        int low = bloomDay[0];
        int high = bloomDay[0];
        for (int day : bloomDay) {
            if (day < low) low = day;
            if (day > high) high = day;
        }
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canMake(bloomDay, mid, m, k)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean canMake(int[] bloomDay, int day, int m, int k) {
        int bouquets = 0;
        int consecutive = 0;
        for (int bloom : bloomDay) {
            if (bloom <= day) {
                consecutive++;
                if (consecutive == k) {
                    bouquets++;
                    consecutive = 0;
                    if (bouquets >= m) {
                        return true;
                    }
                }
            } else {
                consecutive = 0;
            }
        }
        return false;
    }
}

