public class Solution {
    public static int kthAncestor(int[] parent, int node, int k) {
        int n = parent.length;
        int maxPower = 0;
        while ((1 << maxPower) <= n) {
            maxPower++;
        }
        int[][] up = new int[maxPower][n];
        for (int p = 0; p < maxPower; p++) {
            for (int v = 0; v < n; v++) {
                up[p][v] = -1;
            }
        }
        for (int v = 0; v < n; v++) {
            up[0][v] = parent[v];
        }
        for (int p = 1; p < maxPower; p++) {
            for (int v = 0; v < n; v++) {
                int mid = up[p - 1][v];
                up[p][v] = (mid == -1) ? -1 : up[p - 1][mid];
            }
        }
        int cur = node;
        int bit = 0;
        while (k > 0 && cur != -1) {
            if ((k & 1) == 1) {
                cur = up[bit][cur];
            }
            k >>= 1;
            bit++;
        }
        return cur;
    }
}

