class Solution {
    public static int numSubseq(int[] nums, int target) {
        final long MOD = 1000000007L;
        int n = nums.length;
        if (n == 0) return 0;
        Arrays.sort(nums);
        long[] pow2 = new long[n];
        pow2[0] = 1;
        for (int i = 1; i < n; i++) {
            pow2[i] = (pow2[i - 1] * 2) % MOD;
        }
        int left = 0;
        int right = n - 1;
        long ans = 0;
        while (left <= right) {
            if ((long) nums[left] + nums[right] <= target) {
                ans = (ans + pow2[right - left]) % MOD;
                left++;
            } else {
                right--;
            }
        }
        return (int) ans;
    }
}

