class Solution {
    public int[] avoidFlood(int[] rains) {
        int n = rains.length;
        int[] ans = new int[n];
        Arrays.fill(ans, 1); // placeholder for dry days
        Map<Integer, Integer> lastRain = new HashMap<>();
        TreeSet<Integer> dryDays = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            int lake = rains[i];
            if (lake == 0) {
                dryDays.add(i);
                ans[i] = 1; // will be replaced if needed
            } else {
                if (lastRain.containsKey(lake)) {
                    Integer dry = dryDays.higher(lastRain.get(lake));
                    if (dry == null) {
                        return new int[0];
                    }
                    ans[dry] = lake;
                    dryDays.remove(dry);
                }
                ans[i] = -1;
                lastRain.put(lake, i);
            }
        }
        // remaining dry days can stay as 1 (any lake)
        return ans;
    }
}

