class Solution {
    private static class Edge {
        int u, v, w, idx;
        Edge(int u, int v, int w, int idx) {
            this.u = u;
            this.v = v;
            this.w = w;
            this.idx = idx;
        }
    }

    private static class DSU {
        int[] parent, rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        boolean union(int a, int b) {
            int pa = find(a), pb = find(b);
            if (pa == pb) return false;
            if (rank[pa] < rank[pb]) {
                parent[pa] = pb;
            } else if (rank[pa] > rank[pb]) {
                parent[pb] = pa;
            } else {
                parent[pb] = pa;
                rank[pa]++;
            }
            return true;
        }
    }

    private int kruskal(int n, Edge[] edges, int skipIdx, Edge forceEdge) {
        DSU dsu = new DSU(n);
        int total = 0;
        int used = 0;
        if (forceEdge != null) {
            if (dsu.union(forceEdge.u, forceEdge.v)) {
                total += forceEdge.w;
                used++;
            }
        }
        for (Edge e : edges) {
            if (e.idx == skipIdx) continue;
            if (forceEdge != null && e.idx == forceEdge.idx) continue;
            if (dsu.union(e.u, e.v)) {
                total += e.w;
                used++;
                if (used == n - 1) break;
            }
        }
        return used == n - 1 ? total : Integer.MAX_VALUE;
    }

    public List<List<Integer>> findCriticalAndPseudoCriticalEdges(int n, int[][] edges) {
        Edge[] edgeObjs = new Edge[edges.length];
        for (int i = 0; i < edges.length; i++) {
            edgeObjs[i] = new Edge(edges[i][0], edges[i][1], edges[i][2], i);
        }
        Arrays.sort(edgeObjs, Comparator.comparingInt(e -> e.w));

        int mstWeight = kruskal(n, edgeObjs, -1, null);
        List<Integer> critical = new ArrayList<>();
        List<Integer> pseudo = new ArrayList<>();

        for (Edge e : edgeObjs) {
            int weightWithout = kruskal(n, edgeObjs, e.idx, null);
            if (weightWithout > mstWeight) {
                critical.add(e.idx);
            } else {
                int weightWith = kruskal(n, edgeObjs, -1, e);
                if (weightWith == mstWeight) {
                    pseudo.add(e.idx);
                }
            }
        }

        List<List<Integer>> result = new ArrayList<>();
        result.add(critical);
        result.add(pseudo);
        return result;
    }
}

