class Solution {
    public static boolean canPair(int[] arr, int k) {
        Map<Integer, Integer> remainderCount = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            int r = ((arr[i] % k) + k) % k;
            remainderCount.put(r, remainderCount.getOrDefault(r, 0) + 1);
        }
        for (Map.Entry<Integer, Integer> entry : remainderCount.entrySet()) {
            int r = entry.getKey();
            int cnt = entry.getValue();
            if (r == 0) {
                if (cnt % 2 != 0) return false;
            } else if (k % 2 == 0 && r == k / 2) {
                if (cnt % 2 != 0) return false;
            } else {
                int complement = (k - r) % k;
                int complementCnt = remainderCount.getOrDefault(complement, 0);
                if (cnt != complementCnt) return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int maxValueOfEquation(int[][] points, int k) {
        int n = points.length;
        int best = Integer.MIN_VALUE;
        Deque<Integer> dq = new ArrayDeque<>();

        for (int j = 0; j < n; j++) {
            int xj = points[j][0];
            int yj = points[j][1];

            while (!dq.isEmpty() && xj - points[dq.peekFirst()][0] > k) {
                dq.pollFirst();
            }

            if (!dq.isEmpty()) {
                int i = dq.peekFirst();
                int candidate = (points[i][1] - points[i][0]) + yj + xj;
                if (candidate > best) {
                    best = candidate;
                }
            }

            int curVal = yj - xj;
            while (!dq.isEmpty() && (points[dq.peekLast()][1] - points[dq.peekLast()][0]) <= curVal) {
                dq.pollLast();
            }
            dq.offerLast(j);
        }
        return best;
    }
}

