class Solution {
    public static boolean stoneGameIV(int n) {
        List<Integer> squares = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            squares.add(i * i);
        }
        boolean[] win = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            for (int s : squares) {
                if (s > i) break;
                if (!win[i - s]) {
                    win[i] = true;
                    break;
                }
            }
        }
        return win[n];
    }
}

