class Solution {
    public static int[] countSubTrees(int n, int[][] edges, String labels) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        int[] answer = new int[n];
        dfs(0, -1, graph, labels, answer);
        return answer;
    }

    private static int[] dfs(int node, int parent, List<Integer>[] graph, String labels, int[] answer) {
        int[] freq = new int[26];
        for (int nxt : graph[node]) {
            if (nxt == parent) continue;
            int[] childFreq = dfs(nxt, node, graph, labels, answer);
            for (int i = 0; i < 26; i++) {
                freq[i] += childFreq[i];
            }
        }
        int idx = labels.charAt(node) - 'a';
        freq[idx]++;
        answer[node] = freq[idx];
        return freq;
    }
}

