public class Solution {
    public static double bestPositionSum(double[][] positions) {
        int n = positions.length;
        if (n == 0) return 0;
        double cx = 0, cy = 0;
        for (int i = 0; i < n; ++i) {
            cx += positions[i][0];
            cy += positions[i][1];
        }
        cx /= n;
        cy /= n;
        final double EPS = 1e-7;
        while (true) {
            double numX = 0, numY = 0, denom = 0;
            boolean moved = false;
            for (int i = 0; i < n; ++i) {
                double dx = cx - positions[i][0];
                double dy = cy - positions[i][1];
                double dist = Math.hypot(dx, dy);
                if (dist == 0) {
                    cx = positions[i][0];
                    cy = positions[i][1];
                    moved = true;
                    break;
                }
                double w = 1.0 / dist;
                numX += positions[i][0] * w;
                numY += positions[i][1] * w;
                denom += w;
            }
            double nextX = numX / denom;
            double nextY = numY / denom;
            if (Math.hypot(nextX - cx, nextY - cy) < EPS) {
                break;
            }
            cx = nextX;
            cy = nextY;
        }
        double total = 0;
        for (int i = 0; i < n; ++i) {
            total += Math.hypot(cx - positions[i][0], cy - positions[i][1]);
        }
        return Math.round(total * 1e5) / 1e5;
    }
}

