class Solution {
    public static List<String> maxNumOfSubstrings(String s) {
        int n = s.length();
        int[] left = new int[26];
        int[] right = new int[26];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);
        for (int i = 0; i < n; ++i) {
            int idx = s.charAt(i) - 'a';
            if (left[idx] == -1) left[idx] = i;
            right[idx] = i;
        }
        List<int[]> intervals = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            int idx = s.charAt(i) - 'a';
            if (i != left[idx]) continue;
            int start = i;
            int end = right[idx];
            int j = start;
            boolean ok = true;
            while (j <= end) {
                int curIdx = s.charAt(j) - 'a';
                if (left[curIdx] < start) {
                    ok = false;
                    break;
                }
                end = Math.max(end, right[curIdx]);
                ++j;
            }
            if (ok) intervals.add(new int[]{start, end});
        }
        intervals.sort((a, b) -> Integer.compare(a[1], b[1]));
        List<int[]> chosen = new ArrayList<>();
        int lastEnd = -1;
        for (int[] interval : intervals) {
            if (interval[0] > lastEnd) {
                chosen.add(interval);
                lastEnd = interval[1];
            }
        }
        chosen.sort((a, b) -> {
            int lenA = a[1] - a[0];
            int lenB = b[1] - b[0];
            if (lenA != lenB) return Integer.compare(lenA, lenB);
            return Integer.compare(a[0], b[0]);
        });
        List<String> result = new ArrayList<>();
        for (int[] iv : chosen) {
            result.add(s.substring(iv[0], iv[1] + 1));
        }
        return result;
    }
}

