class Solution {
    public static int numberOfSubarrays(int[] arr) {
        final long MOD = 1000000007L;
        long evenCount = 1;
        long oddCount = 0;
        int prefixParity = 0;
        long result = 0;
        for (int i = 0; i < arr.length; i++) {
            prefixParity ^= (arr[i] & 1);
            if (prefixParity == 1) {
                result = (result + evenCount) % MOD;
                oddCount++;
            } else {
                result = (result + oddCount) % MOD;
                evenCount++;
            }
        }
        return (int) result;
    }
}

