public class Solution {
    public static int numberOfGoodSplits(String s) {
        int n = s.length();
        int[] prefix = new int[n];
        int[] suffix = new int[n];
        boolean[] seenLeft = new boolean[26];
        int distinctLeft = 0;
        for (int i = 0; i < n; i++) {
            int idx = s.charAt(i) - 'a';
            if (!seenLeft[idx]) {
                seenLeft[idx] = true;
                distinctLeft++;
            }
            prefix[i] = distinctLeft;
        }
        boolean[] seenRight = new boolean[26];
        int distinctRight = 0;
        for (int i = n - 1; i >= 0; i--) {
            int idx = s.charAt(i) - 'a';
            if (!seenRight[idx]) {
                seenRight[idx] = true;
                distinctRight++;
            }
            suffix[i] = distinctRight;
        }
        int goodSplits = 0;
        for (int i = 1; i < n; i++) {
            if (prefix[i - 1] == suffix[i]) {
                goodSplits++;
            }
        }
        return goodSplits;
    }
}

