class Solution {
    public static int minSwaps(int[][] grid) {
        int n = grid.length;
        int[] rightOne = new int[n];
        for (int i = 0; i < n; i++) {
            int pos = -1;
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    pos = j;
                    break;
                }
            }
            rightOne[i] = pos;
        }

        int steps = 0;
        for (int i = 0; i < n; i++) {
            if (rightOne[i] <= i) continue;
            int j = i + 1;
            while (j < n && rightOne[j] > i) {
                j++;
            }
            if (j == n) return -1;
            while (j > i) {
                int temp = rightOne[j];
                rightOne[j] = rightOne[j - 1];
                rightOne[j - 1] = temp;
                steps++;
                j--;
            }
        }
        return steps;
    }
}

