class Solution {
    private int goodPairs;
    public int countPairs(TreeNode root, int distance) {
        goodPairs = 0;
        dfs(root, distance);
        return goodPairs;
    }
    private List<Integer> dfs(TreeNode node, int distance) {
        if (node == null) return new ArrayList<>();
        if (node.left == null && node.right == null) {
            List<Integer> leaf = new ArrayList<>();
            leaf.add(1);
            return leaf;
        }
        List<Integer> leftDist = dfs(node.left, distance);
        List<Integer> rightDist = dfs(node.right, distance);
        for (int l : leftDist) {
            for (int r : rightDist) {
                if (l + r <= distance) goodPairs++;
            }
        }
        List<Integer> up = new ArrayList<>();
        for (int d : leftDist) {
            if (d + 1 <= distance) up.add(d + 1);
        }
        for (int d : rightDist) {
            if (d + 1 <= distance) up.add(d + 1);
        }
        return up;
    }
}

