class Solution {
    public int getLengthOfOptimalCompression(String s, int k) {
        int n = s.length();
        int INF = 1_000_000;
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], INF);
        }
        for (int j = 0; j <= k; j++) {
            dp[0][j] = 0;
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                // delete current character
                if (j > 0) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j - 1]);
                }
                int cnt = 0;
                int del = 0;
                for (int p = i; p >= 1; p--) {
                    if (s.charAt(p - 1) == s.charAt(i - 1)) {
                        cnt++;
                    } else {
                        del++;
                    }
                    if (j - del < 0) continue;
                    int add = encodedLength(cnt);
                    dp[i][j] = Math.min(dp[i][j], dp[p - 1][j - del] + add);
                }
            }
        }
        return dp[n][k];
    }

    private int encodedLength(int count) {
        if (count == 1) return 1;
        if (count < 10) return 2;
        if (count < 100) return 3;
        return 4;
    }
}

