class Solution {
    public static boolean canConvertStringInKMoves(String s, String t, int k) {
        int[] need = new int[26];
        for (int i = 0; i < s.length(); i++) {
            int a = s.charAt(i) - 'a';
            int b = t.charAt(i) - 'a';
            if (a == b) continue;
            int diff = (b - a + 26) % 26;
            need[diff]++;
        }
        for (int diff = 1; diff < 26; diff++) {
            int cnt = need[diff];
            if (cnt == 0) continue;
            if (diff > k) return false;
            int maxMoves = (k - diff) / 26 + 1;
            if (cnt > maxMoves) return false;
        }
        return true;
    }
}

