class Solution {
    public static int findWinner(int[] arr, int k) {
        if (k >= arr.length - 1) {
            int max = arr[0];
            for (int i = 1; i < arr.length; i++) {
                if (arr[i] > max) {
                    max = arr[i];
                }
            }
            return max;
        }
        Deque<Integer> queue = new ArrayDeque<>();
        for (int val : arr) {
            queue.addLast(val);
        }
        int cur = queue.pollFirst();
        int win = 0;
        while (win < k) {
            int next = queue.pollFirst();
            if (cur > next) {
                win++;
                queue.addLast(next);
            } else {
                queue.addLast(cur);
                cur = next;
                win = 1;
            }
        }
        return cur;
    }
}

