class Solution {
    public static int findKthMissing(int[] arr, int k) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (missingCount(arr, mid) < k) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        int prevMissing = left > 0 ? missingCount(arr, left - 1) : 0;
        int prevValue = left > 0 ? arr[left - 1] : 0;
        return prevValue + (k - prevMissing);
    }

    private static int missingCount(int[] arr, int i) {
        return arr[i] - (i + 1);
    }
}

