class Solution {
    public static int longestAwesome(String s) {
        final int INF = (int)1e9;
        int[] first = new int[1 << 10];
        Arrays.fill(first, INF);
        first[0] = -1;
        int mask = 0;
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            int digit = s.charAt(i) - '0';
            mask ^= (1 << digit);
            best = Math.max(best, i - first[mask]);
            for (int d = 0; d < 10; d++) {
                int cand = mask ^ (1 << d);
                best = Math.max(best, i - first[cand]);
            }
            if (first[mask] == INF) {
                first[mask] = i;
            }
        }
        return best;
    }
}

