public class Solution {
    public char findKthBit(int n, int k) {
        return kthBit(n, k);
    }

    private char kthBit(int n, int k) {
        if (n == 1) {
            return '0';
        }
        int mid = 1 << (n - 1);
        if (k == mid) {
            return '1';
        } else if (k < mid) {
            return kthBit(n - 1, k);
        } else {
            int len = (1 << n) - 1;
            int mirroredPos = len - k + 1;
            char bit = kthBit(n - 1, mirroredPos);
            return bit == '0' ? '1' : '0';
        }
    }
}

