class Solution {
    public static boolean detectCycle(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int[][] dirs = {
            {1, 0},
            {-1, 0},
            {0, 1},
            {0, -1}
        };
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, grid[i][j], grid, visited, dirs)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean dfs(int x, int y, int px, int py, char ch,
                               char[][] grid, boolean[][] visited, int[][] dirs) {
        visited[x][y] = true;
        for (int[] d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                continue;
            }
            if (grid[nx][ny] != ch) {
                continue;
            }
            if (!visited[nx][ny]) {
                if (dfs(nx, ny, x, y, ch, grid, visited, dirs)) {
                    return true;
                }
            } else if (nx != px || ny != py) {
                return true;
            }
        }
        return false;
    }
}

