public class Solution {
    public int findLatestStep(int[] arr, int m) {
        int n = arr.length;
        if (m == n) return n;
        int[] start = new int[n + 2];
        int[] end = new int[n + 2];
        int[] count = new int[n + 1];
        int answer = -1;
        for (int i = 0; i < n; i++) {
            int pos = arr[i];
            int leftLen = end[pos - 1];
            int rightLen = start[pos + 1];
            int newLen = leftLen + 1 + rightLen;
            if (leftLen > 0) count[leftLen]--;
            if (rightLen > 0) count[rightLen]--;
            count[newLen]++;
            start[pos - leftLen] = newLen;
            end[pos + rightLen] = newLen;
            if (count[m] > 0) answer = i + 1;
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;
    private long[] fact;
    private long[] invFact;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        precomputeFactorials(n);
        TreeNode root = null;
        for (int v : nums) {
            root = insert(root, v);
        }
        long ways = dfs(root)[1];
        long ans = (ways - 1 + MOD) % MOD;
        return (int) ans;
    }

    private void precomputeFactorials(int n) {
        fact = new long[n + 1];
        invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }
    }

    private long modPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * b % MOD;
            }
            b = b * b % MOD;
            exp >>= 1;
        }
        return result;
    }

    private long nCr(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    private TreeNode insert(TreeNode node, int val) {
        if (node == null) {
            return new TreeNode(val);
        }
        if (val < node.val) {
            node.left = insert(node.left, val);
        } else {
            node.right = insert(node.right, val);
        }
        return node;
    }

    private long[] dfs(TreeNode node) {
        if (node == null) {
            return new long[]{0, 1};
        }
        long[] left = dfs(node.left);
        long[] right = dfs(node.right);
        long leftSize = left[0];
        long rightSize = right[0];
        long leftWays = left[1];
        long rightWays = right[1];
        long totalSize = leftSize + rightSize + 1;
        long comb = nCr((int) (leftSize + rightSize), (int) leftSize);
        long ways = comb * leftWays % MOD * rightWays % MOD;
        return new long[]{totalSize, ways};
    }
}

