class Solution {
    public static boolean hasPattern(int[] arr, int m, int k) {
        int n = arr.length;
        if (m <= 0 || k <= 0) return false;
        if (m * k > n) return false;
        if (k == 1) return m <= n;
        for (int i = 0; i <= n - m * k; i++) {
            int repeats = 1;
            while (repeats < k) {
                boolean same = true;
                for (int j = 0; j < m; j++) {
                    if (arr[i + j] != arr[i + repeats * m + j]) {
                        same = false;
                        break;
                    }
                }
                if (!same) break;
                repeats++;
            }
            if (repeats >= k) return true;
        }
        return false;
    }
}

class Solution {
    public static int getMaxLen(int[] nums) {
        int maxPos = 0;
        int posLen = 0;
        int negLen = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (x == 0) {
                posLen = 0;
                negLen = 0;
            } else if (x > 0) {
                posLen = posLen + 1;
                if (negLen > 0) {
                    negLen = negLen + 1;
                }
            } else {
                int oldPos = posLen;
                int oldNeg = negLen;
                posLen = (oldNeg > 0) ? oldNeg + 1 : 0;
                negLen = oldPos + 1;
            }
            if (posLen > maxPos) {
                maxPos = posLen;
            }
        }
        return maxPos;
    }
}

