class Solution {
    public static int countRoutes(int[] locations, int start, int finish, int fuel) {
        final int MOD = 1_000_000_007;
        int n = locations.length;
        int[][] memo = new int[n][fuel + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(memo[i], -1);
        }
        return dfs(start, fuel, locations, finish, memo, MOD);
    }

    private static int dfs(int city, int remaining, int[] locations, int finish, int[][] memo, int MOD) {
        if (memo[city][remaining] != -1) {
            return memo[city][remaining];
        }
        int ways = (city == finish) ? 1 : 0;
        int n = locations.length;
        for (int next = 0; next < n; next++) {
            if (next == city) continue;
            int cost = Math.abs(locations[city] - locations[next]);
            if (cost <= remaining) {
                ways = (int) ((ways + dfs(next, remaining - cost, locations, finish, memo, MOD)) % MOD);
            }
        }
        memo[city][remaining] = ways;
        return ways;
    }
}

