class Solution {
    public static long numberOfWays(String s) {
        final int MOD = 1000000007;
        int n = s.length();
        int totalOnes = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') totalOnes++;
        }

        if (totalOnes % 3 != 0) return 0;

        if (totalOnes == 0) {
            long ways = ((long) (n - 1) * (n - 2) / 2) % MOD;
            return ways;
        }

        int target = totalOnes / 3;
        int onesSeen = 0;
        int zerosAfterFirst = 0;
        int zerosAfterSecond = 0;
        int i = 0;

        while (i < n) {
            if (s.charAt(i) == '1') onesSeen++;
            if (onesSeen == target) {
                i++;
                while (i < n && s.charAt(i) == '0') {
                    zerosAfterFirst++;
                    i++;
                }
                break;
            }
            i++;
        }

        while (i < n) {
            if (s.charAt(i) == '1') onesSeen++;
            if (onesSeen == 2 * target) {
                i++;
                while (i < n && s.charAt(i) == '0') {
                    zerosAfterSecond++;
                    i++;
                }
                break;
            }
            i++;
        }

        long ways = ((long) (zerosAfterFirst + 1) * (zerosAfterSecond + 1)) % MOD;
        return ways;
    }
}

