class Solution {
    public static int shortestSubarrayToRemove(int[] arr) {
        int n = arr.length;
        int prefixEnd = 0;
        while (prefixEnd + 1 < n && arr[prefixEnd] <= arr[prefixEnd + 1]) {
            prefixEnd++;
        }
        if (prefixEnd == n - 1) return 0;
        int suffixStart = n - 1;
        while (suffixStart - 1 >= 0 && arr[suffixStart - 1] <= arr[suffixStart]) {
            suffixStart--;
        }
        int minRemove = Math.min(n - prefixEnd - 1, suffixStart);
        int i = 0, j = suffixStart;
        while (i <= prefixEnd && j < n) {
            while (j < n && arr[j] < arr[i]) j++;
            if (j < n) {
                minRemove = Math.min(minRemove, j - i - 1);
            }
            i++;
        }
        return minRemove;
    }
}

import java.util.*;

class Solution {
    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int size) {
            parent = new int[size + 1];
            rank = new int[size + 1];
            for (int i = 1; i <= size; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return false;
            if (rank[ra] < rank[rb]) {
                int temp = ra;
                ra = rb;
                rb = temp;
            }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) {
                rank[ra]++;
            }
            return true;
        }
    }

    public static int maxNumEdgesToRemove(int n, int[][] edges) {
        DSU alice = new DSU(n);
        DSU bob = new DSU(n);
        int used = 0;

        for (int[] edge : edges) {
            int type = edge[0];
            int u = edge[1];
            int v = edge[2];
            if (type == 3) {
                boolean a = alice.union(u, v);
                boolean b = bob.union(u, v);
                if (a || b) used++;
            }
        }

        for (int[] edge : edges) {
            int type = edge[0];
            int u = edge[1];
            int v = edge[2];
            if (type == 1) {
                if (alice.union(u, v)) used++;
            } else if (type == 2) {
                if (bob.union(u, v)) used++;
            }
        }

        if (componentCount(alice, n) != 1 || componentCount(bob, n) != 1) {
            return -1;
        }

        return edges.length - used;
    }

    private static int componentCount(DSU ds, int n) {
        int cnt = 0;
        for (int i = 1; i <= n; i++) {
            if (ds.find(i) == i) cnt++;
        }
        return cnt;
    }
}

