class Solution {
    public static int minCost(String colors, int[] neededTime) {
        int totalTime = 0;
        int i = 0;
        while (i < colors.length()) {
            int maxInBlock = neededTime[i];
            int sumInBlock = neededTime[i];
            int j = i + 1;
            while (j < colors.length() && colors.charAt(j) == colors.charAt(i)) {
                sumInBlock += neededTime[j];
                if (neededTime[j] > maxInBlock) {
                    maxInBlock = neededTime[j];
                }
                j++;
            }
            totalTime += sumInBlock - maxInBlock;
            i = j;
        }
