class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        Map<Long, Integer> prodMap1 = new HashMap<>();
        Map<Long, Integer> prodMap2 = new HashMap<>();
        buildProductMap(prodMap1, nums1);
        buildProductMap(prodMap2, nums2);
        long total = 0;
        for (int x : nums1) {
            long sq = (long) x * x;
            total += prodMap2.getOrDefault(sq, 0);
        }
        for (int x : nums2) {
            long sq = (long) x * x;
            total += prodMap1.getOrDefault(sq, 0);
        }
        return (int) total;
    }

    private void buildProductMap(Map<Long, Integer> map, int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long product = (long) arr[i] * arr[j];
                map.put(product, map.getOrDefault(product, 0) + 1);
            }
        }
    }
}

