class Solution {
    public static int countUnhappyFriends(int n, int[][] preferences, int[][] pairs) {
        int[] partner = new int[n];
        for (int[] pair : pairs) {
            int a = pair[0];
            int b = pair[1];
            partner[a] = b;
            partner[b] = a;
        }

        int[][] rank = new int[n][n];
        for (int i = 0; i < n; i++) {
            int[] list = preferences[i];
            for (int pos = 0; pos < list.length; pos++) {
                rank[i][list[pos]] = pos;
            }
        }

        boolean[] unhappy = new boolean[n];

        for (int x = 0; x < n; x++) {
            int y = partner[x];
            for (int u : preferences[x]) {
                if (u == y) break;
                int v = partner[u];
                if (rank[u][x] < rank[u][v]) {
                    unhappy[x] = true;
                    break;
                }
            }
        }

        int ans = 0;
        for (boolean flag : unhappy) {
            if (flag) ans++;
        }
        return ans;
    }
}

