    public static boolean isTransformable(String s, String t) {
        int n = s.length();
        List<ArrayDeque<Integer>> pos = new ArrayList<>(10);
        for (int i = 0; i < 10; i++) {
            pos.add(new ArrayDeque<>());
        }
        for (int i = 0; i < n; i++) {
            int d = s.charAt(i) - '0';
            pos.get(d).add(i);
        }
        for (int i = 0; i < n; i++) {
            int need = t.charAt(i) - '0';
            if (pos.get(need).isEmpty()) {
                return false;
            }
            int idx = pos.get(need).pollFirst();
            for (int d = 0; d < need; d++) {
                if (!pos.get(d).isEmpty() && pos.get(d).peekFirst() < idx) {
                    return false;
                }
            }
        }
        return true;
    }
}

