public class Solution {
    public static long sumOddLengthSubarrays(int[] arr) {
        int n = arr.length;
        long total = 0;
        for (int i = 0; i < n; i++) {
            long left = i + 1;
            long right = n - i;
            long leftOdd = (left + 1) / 2;
            long leftEven = left / 2;
            long rightOdd = (right + 1) / 2;
            long rightEven = right / 2;
            long oddSubarrays = leftOdd * rightOdd + leftEven * rightEven;
            total += arr[i] * oddSubarrays;
        }
        return total;
    }
}

import java.util.HashMap;

class Solution {
    public static int minSubarray(int[] nums, int p) {
        long total = 0;
        for (int num : nums) {
            total += num;
        }
        int need = (int) (total % p);
        if (need == 0) {
            return 0;
        }
        HashMap<Integer, Integer> map = new HashMap<>();
        map.put(0, 0);
        int prefix = 0;
        int n = nums.length;
        int answer = n + 1;
        for (int i = 1; i <= n; i++) {
            prefix = (int) ((prefix + (long) nums[i - 1]) % p);
            int target = (prefix - need + p) % p;
            Integer idx = map.get(target);
            if (idx != null) {
                answer = Math.min(answer, i - idx);
            }
            map.put(prefix, i);
        }
        return (answer == n + 1 || answer == n) ? -1 : answer;
    }
}

class Solution {
    public static String reorderSpaces(String text) {
        int totalSpaces = 0;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == ' ') totalSpaces++;
        }
        String[] words = text.trim().split("\\s+");
        int wordCount = words.length;
        if (wordCount == 1) {
            return words[0] + " ".repeat(totalSpaces);
        }
        int spacesBetween = totalSpaces / (wordCount - 1);
        int extraSpaces = totalSpaces - spacesBetween * (wordCount - 1);
        String middle = " ".repeat(spacesBetween);
        return String.join(middle, words) + " ".repeat(extraSpaces);
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int maxUniqueSplit(String s) {
        Set<String> used = new HashSet<>();
        int[] best = new int[1];
        dfs(s, 0, 0, used, best);
        return best[0];
    }

    private static void dfs(String s, int start, int count, Set<String> used, int[] best) {
        if (start == s.length()) {
            if (count > best[0]) best[0] = count;
            return;
        }
        for (int end = start + 1; end <= s.length(); end++) {
            String sub = s.substring(start, end);
            if (!used.contains(sub)) {
                used.add(sub);
                dfs(s, end, count + 1, used, best);
                used.remove(sub);
            }
        }
    }
}

import java.util.*;

class Solution {
    public static boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length;
        int n = targetGrid[0].length;
        Map<Integer, int[]> rect = new HashMap<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int col = targetGrid[r][c];
                if (!rect.containsKey(col)) {
                    rect.put(col, new int[]{r, r, c, c});
                } else {
                    int[] cur = rect.get(col);
                    cur[0] = Math.min(cur[0], r);
                    cur[1] = Math.max(cur[1], r);
                    cur[2] = Math.min(cur[2], c);
                    cur[3] = Math.max(cur[3], c);
                }
            }
        }
        Set<Integer> colors = rect.keySet();
        Map<Integer, Integer> indegree = new HashMap<>();
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        for (int col : colors) {
            indegree.put(col, 0);
            graph.put(col, new HashSet<>());
        }
        for (int col : colors) {
            int[] bounds = rect.get(col);
            int minR = bounds[0], maxR = bounds[1], minC = bounds[2], maxC = bounds[3];
            for (int r = minR; r <= maxR; r++) {
                for (int c = minC; c <= maxC; c++) {
                    int inner = targetGrid[r][c];
                    if (inner != col) {
                        Set<Integer> set = graph.get(col);
                        if (set.add(inner)) {
                            indegree.put(inner, indegree.get(inner) + 1);
                        }
                    }
                }
            }
        }
        Queue<Integer> queue = new ArrayDeque<>();
        for (int col : colors) {
            if (indegree.get(col) == 0) {
                queue.offer(col);
            }
        }
        int visited = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            visited++;
            for (int nxt : graph.get(cur)) {
                indegree.put(nxt, indegree.get(nxt) - 1);
                if (indegree.get(nxt) == 0) {
                    queue.offer(nxt);
                }
            }
        }
        return visited == colors.size();
    }
}

import java.math.BigInteger;

class Solution {
    public static int maxProductPath(int[][] grid) {
        final BigInteger MOD = new BigInteger("1000000007");
        int rows = grid.length;
        int cols = grid[0].length;
        BigInteger[][] maxDP = new BigInteger[rows][cols];
        BigInteger[][] minDP = new BigInteger[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                BigInteger val = BigInteger.valueOf(grid[i][j]);

                if (i == 0 && j == 0) {
                    maxDP[i][j] = val;
                    minDP[i][j] = val;
                    continue;
                }

                BigInteger curMax = null;
                BigInteger curMin = null;

                if (i > 0) {
                    BigInteger cand1 = maxDP[i - 1][j].multiply(val);
                    BigInteger cand2 = minDP[i - 1][j].multiply(val);
                    if (curMax == null || cand1.compareTo(curMax) > 0) curMax = cand1;
                    if (curMin == null || cand1.compareTo(curMin) < 0) curMin = cand1;
                    if (cand2.compareTo(curMax) > 0) curMax = cand2;
                    if (cand2.compareTo(curMin) < 0) curMin = cand2;
                }
                if (j > 0) {
                    BigInteger cand3 = maxDP[i][j - 1].multiply(val);
                    BigInteger cand4 = minDP[i][j - 1].multiply(val);
                    if (curMax == null || cand3.compareTo(curMax) > 0) curMax = cand3;
                    if (curMin == null || cand3.compareTo(curMin) < 0) curMin = cand3;
                    if (cand4.compareTo(curMax) > 0) curMax = cand4;
                    if (cand4.compareTo(curMin) < 0) curMin = cand4;
                }

                maxDP[i][j] = curMax;
                minDP[i][j] = curMin;
            }
        }

        BigInteger finalMax = maxDP[rows - 1][cols - 1];
        if (finalMax.signum() < 0) {
            return -1;
        }
        return finalMax.mod(MOD).intValue();
    }
}

import java.util.Arrays;

class Solution {
    public static int maxSumRangeQuery(int[] nums, int[][] requests) {
        final int MOD = 1_000_000_007;
        int n = nums.length;
        int[] diff = new int[n + 1];
        for (int[] req : requests) {
            int l = req[0];
            int r = req[1];
            diff[l] += 1;
            if (r + 1 < n) diff[r + 1] -= 1;
        }
        int[] freq = new int[n];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            freq[i] = cur;
        }
        Arrays.sort(nums);
        Arrays.sort(freq);
        long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            ans = (ans + ((long) nums[i] * freq[i]) % MOD) % MOD;
        }
        return (int) ans;
    }
}

import java.util.*;

class Solution {
    public int minCostConnectTwoGroups(int[][] cost) {
        int m = cost.length;
        int n = cost[0].length;
        int maxMask = 1 << n;
        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[maxMask];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i < m; i++) {
            long[] ndp = new long[maxMask];
            Arrays.fill(ndp, INF);
            for (int mask = 0; mask < maxMask; mask++) {
                if (dp[mask] == INF) continue;
                for (int j = 0; j < n; j++) {
                    int newMask = mask | (1 << j);
                    long newCost = dp[mask] + cost[i][j];
                    if (newCost < ndp[newMask]) {
                        ndp[newMask] = newCost;
                    }
                }
            }
            dp = ndp;
        }
        long[] minCostSecond = new long[n];
        Arrays.fill(minCostSecond, INF);
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < m; i++) {
                if (cost[i][j] < minCostSecond[j]) {
                    minCostSecond[j] = cost[i][j];
                }
            }
        }
        long answer = INF;
        for (int mask = 0; mask < maxMask; mask++) {
            long total = dp[mask];
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) == 0) {
                    total += minCostSecond[j];
                }
            }
            if (total < answer) answer = total;
        }
        return (int) answer;
    }
}

