class Solution {
    public static int maximumRequests(int n, int[][] requests) {
        int m = requests.length;
        int best = 0;
        int limit = 1 << m;
        for (int mask = 0; mask < limit; mask++) {
            int[] balance = new int[n];
            int used = 0;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) {
                    int from = requests[i][0];
                    int to = requests[i][1];
                    balance[from]--;
                    balance[to]++;
                    used++;
                }
            }
            boolean ok = true;
            for (int b = 0; b < n; b++) {
                if (balance[b] != 0) {
                    ok = false;
                    break;
                }
            }
            if (ok && used > best) {
                best = used;
            }
        }
        return best;
    }
}

