class Solution {
    public static int maxProfit(int[] customers, int boardingCost, int runningCost) {
        int waiting = 0;
        int profit = 0;
        int maxProfit = 0;
        int bestRot = -1;
        int rotations = 0;
        for (int i = 0; i < customers.length || waiting > 0; i++) {
            if (i < customers.length) waiting += customers[i];
            int board = Math.min(4, waiting);
            waiting -= board;
            rotations++;
            profit += board * boardingCost - runningCost;
            if (profit > maxProfit) {
                maxProfit = profit;
                bestRot = rotations;
            }
        }
        return maxProfit > 0 ? bestRot : -1;
    }
}

