public class Solution {
    private final Map<String, List<String>> children;
    private final Set<String> dead;
    private final String kingName;

    public Solution(String kingName) {
        this.kingName = kingName;
        this.children = new HashMap<>();
        this.dead = new HashSet<>();
        this.children.put(kingName, new ArrayList<>());
    }

    public void birth(String parentName, String childName) {
        children.computeIfAbsent(parentName, k -> new ArrayList<>()).add(childName);
        children.put(childName, new ArrayList<>());
    }

    public void death(String name) {
        dead.add(name);
    }

    public List<String> getInheritanceOrder() {
        List<String> order = new ArrayList<>();
        dfs(kingName, order);
        return order;
    }

    private void dfs(String person, List<String> order) {
        if (!dead.contains(person)) {
            order.add(person);
        }
        List<String> childs = children.get(person);
        if (childs != null) {
            for (String child : childs) {
                dfs(child, order);
            }
        }
    }
}

