class Solution {
    public static List<String> alertNames(String[] keyName, String[] keyTime) {
        Map<String, List<Integer>> minutesMap = new HashMap<>();
        for (int i = 0; i < keyName.length; i++) {
            String name = keyName[i];
            String[] parts = keyTime[i].split(":");
            int minutes = Integer.parseInt(parts[0]) * 60 + Integer.parseInt(parts[1]);
            minutesMap.computeIfAbsent(name, k -> new ArrayList<>()).add(minutes);
        }
        Set<String> alerted = new HashSet<>();
        for (Map.Entry<String, List<Integer>> entry : minutesMap.entrySet()) {
            List<Integer> times = entry.getValue();
            Collections.sort(times);
            for (int i = 0; i + 2 < times.size(); i++) {
                if (times.get(i + 2) - times.get(i) <= 60) {
                    alerted.add(entry.getKey());
                    break;
                }
            }
        }
        List<String> result = new ArrayList<>(alerted);
        Collections.sort(result);
        return result;
    }
}

import java.util.PriorityQueue;

class Solution {
    public static int[][] restoreMatrix(int[] rowSum, int[] colSum) {
        int rows = rowSum.length;
        int cols = colSum.length;
        int[][] matrix = new int[rows][cols];
        int[] colRemain = colSum.clone();
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> {
            if (colRemain[a] != colRemain[b]) return Integer.compare(colRemain[a], colRemain[b]);
            return Integer.compare(a, b);
        });
        for (int j = 0; j < cols; j++) {
            if (colRemain[j] > 0) pq.add(j);
        }
        for (int i = 0; i < rows; i++) {
            int need = rowSum[i];
            while (need > 0) {
                int col = pq.peek();
                int take = Math.min(need, colRemain[col]);
                matrix[i][col] = take;
                need -= take;
                colRemain[col] -= take;
                if (colRemain[col] == 0) pq.poll();
            }
        }
        return matrix;
    }
}

