import java.util.ArrayDeque;
import java.util.Deque;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

class Solution {
    public static boolean evenOddTree(TreeNode root) {
        if (root == null) return true;
        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int level = 0;
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            int prev = (level % 2 == 0) ? Integer.MIN_VALUE : Integer.MAX_VALUE;
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                if (level % 2 == 0) {
                    if (node.val % 2 == 0 || node.val <= prev) return false;
                } else {
                    if (node.val % 2 == 1 || node.val >= prev) return false;
                }
                prev = node.val;
                if (node.left != null) queue.add(node.left);
                if (node.right != null) queue.add(node.right);
            }
            level++;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int maxVisiblePoints(int[][] points, double angle, int[] location) {
        int sameLocation = 0;
        for (int[] p : points) {
            if (p[0] == location[0] && p[1] == location[1]) {
                sameLocation++;
            }
        }

        List<Double> angleList = new ArrayList<>();
        for (int[] p : points) {
            if (p[0] == location[0] && p[1] == location[1]) continue;
            double deg = Math.toDegrees(Math.atan2(p[1] - location[1], p[0] - location[0]));
            if (deg < 0) deg += 360;
            angleList.add(deg);
        }

        if (angle >= 360) return points.length;

        double[] angles = new double[angleList.size()];
        for (int i = 0; i < angleList.size(); i++) {
            angles[i] = angleList.get(i);
        }
        Arrays.sort(angles);

        int n = angles.length;
        double[] extended = new double[n * 2];
        for (int i = 0; i < n; i++) {
            extended[i] = angles[i];
            extended[i + n] = angles[i] + 360;
        }

        int maxInWindow = 0;
        int left = 0;
        for (int right = 0; right < extended.length; right++) {
            while (extended[right] - extended[left] > angle) {
                left++;
            }
            int windowSize = right - left + 1;
            if (windowSize > maxInWindow) {
                maxInWindow = windowSize;
            }
        }

        return maxInWindow + sameLocation;
    }
}

