class Solution {
    public static int minimumOneBitOperations(int n) {
        if (n == 0) return 0;
        if (n == 1) return 1;
        int msbPos = 31 - Integer.numberOfLeadingZeros(n);
        int highestPower = 1 << msbPos;
        int remaining = n - highestPower;
        return ((1 << (msbPos + 1)) - 1) - minimumOneBitOperations(remaining);
    }
}

