public class Solution {
    public boolean checkPalindromeFormation(String a, String b) {
        return check(a, b) || check(b, a);
    }

    private boolean check(String a, String b) {
        int i = 0, j = a.length() - 1;
        while (i < j && a.charAt(i) == b.charAt(j)) {
            i++;
            j--;
        }
        if (i >= j) return true;
        return isPalindrome(a, i, j) || isPalindrome(b, i, j);
    }

    private boolean isPalindrome(String s, int l, int r) {
        while (l < r) {
            if (s.charAt(l) != s.charAt(r)) return false;
            l++;
            r--;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            graph[u].add(v);
            graph[v].add(u);
        }

        int[] ans = new int[n - 1];
        int totalMasks = 1 << n;

        for (int mask = 1; mask < totalMasks; mask++) {
            int size = Integer.bitCount(mask);
            if (size == 1) continue; // diameter would be 0, not counted

            // Find a starting node in the subset
            int start = Integer.numberOfTrailingZeros(mask);

            // Check connectivity
            boolean[] visited = new boolean[n];
            Deque<Integer> queue = new ArrayDeque<>();
            visited[start] = true;
            queue.add(start);
            int visitedCount = 0;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                visitedCount++;
                for (int v : graph[u]) {
                    if ((mask & (1 << v)) != 0 && !visited[v]) {
                        visited[v] = true;
                        queue.add(v);
                    }
                }
            }

            if (visitedCount != size) continue; // not a connected subtree

            // First BFS to find farthest node from start
            int farNode = bfsFarthest(start, mask, graph);

            // Second BFS from farNode to get diameter
            int diameter = bfsMaxDist(farNode, mask, graph);

            if (diameter > 0) {
                ans[diameter - 1]++; // diameter is at least 1 here
            }
        }

        return ans;
    }

    private int bfsFarthest(int src, int mask, List<Integer>[] graph) {
        int n = graph.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Deque<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.add(src);
        int far = src;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if ((mask & (1 << v)) != 0 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > dist[far]) {
                        far = v;
                    }
                }
            }
        }
        return far;
    }

    private int bfsMaxDist(int src, int mask, List<Integer>[] graph) {
        int n = graph.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Deque<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.add(src);
        int max = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if ((mask & (1 << v)) != 0 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > max) {
                        max = dist[v];
                    }
                }
            }
        }
        return max;
    }
}

import java.util.Arrays;

class Solution {
    public static double meanOfArray(int[] arr) {
        int n = arr.length;
        int removeCount = (int) Math.floor(n * 0.05);
        Arrays.sort(arr);
        double sum = 0;
        for (int i = removeCount; i < n - removeCount; i++) {
            sum += arr[i];
        }
        return sum / (n - 2 * removeCount);
    }
}

