class Solution {
    public static int maximalNetworkRank(int n, int[][] roads) {
        int[] degree = new int[n];
        Set<Integer>[] adjacent = new Set[n];
        for (int i = 0; i < n; i++) {
            adjacent[i] = new HashSet<>();
        }
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            degree[a]++;
            degree[b]++;
            adjacent[a].add(b);
            adjacent[b].add(a);
        }
        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = degree[i] + degree[j];
                if (adjacent[i].contains(j)) {
                    rank--;
                }
                if (rank > best) {
                    best = rank;
                }
            }
        }
        return best;
    }
}

import java.lang.Math;

class Solution {
    public static int[] bestCoordinate(int[][] towers, int radius) {
        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
        for (int[] tower : towers) {
            int x = tower[0];
            int y = tower[1];
            if (x < minX) minX = x;
            if (x > maxX) maxX = x;
            if (y < minY) minY = y;
            if (y > maxY) maxY = y;
        }
        minX -= radius;
        maxX += radius;
        minY -= radius;
        maxY += radius;

        int bestX = 0, bestY = 0, bestQuality = -1;

        for (int cx = minX; cx <= maxX; cx++) {
            for (int cy = minY; cy <= maxY; cy++) {
                int total = 0;
                for (int[] tower : towers) {
                    int tx = tower[0];
                    int ty = tower[1];
                    int q = tower[2];
                    int dx = tx - cx;
                    int dy = ty - cy;
                    double dist = Math.sqrt(dx * dx + dy * dy);
                    if (dist <= radius) {
                        total += (int) Math.floor(q / (1.0 + dist));
                    }
                }
                if (total > bestQuality || (total == bestQuality && (cx < bestX || (cx == bestX && cy < bestY)))) {
                    bestQuality = total;
                    bestX = cx;
                    bestY = cy;
                }
            }
        }
        return new int[]{bestX, bestY};
    }
}

