class Solution {
    public static int largestSubstringBetweenEqualChars(String s) {
        Map<Character, Integer> firstPos = new HashMap<>();
        Map<Character, Integer> lastPos = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (!firstPos.containsKey(ch)) {
                firstPos.put(ch, i);
            }
            lastPos.put(ch, i);
        }
        int maxLen = -1;
        for (Map.Entry<Character, Integer> entry : firstPos.entrySet()) {
            char ch = entry.getKey();
            int first = entry.getValue();
            int last = lastPos.get(ch);
            if (last > first) {
                int curLen = last - first - 1;
                if (curLen > maxLen) {
                    maxLen = curLen;
                }
            }
        }
        return maxLen;
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfSets(int n, int k) {
        int max = n + k - 1;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }
        int r = 2 * k;
        if (r > max) return 0;
        long ans = fact[max];
        ans = ans * invFact[r] % MOD;
        ans = ans * invFact[max - r] % MOD;
        return (int) ans;
    }

    private long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

