class Solution {
    public static FancySequence createFancySequence() {
        return new FancySequence();
    }

    // FIXED: was `private static class`, which made the returned type inaccessible
    // to any caller outside Solution (a compile error: "is defined in an
    // inaccessible class or interface"). Changed to public static so callers can
    // actually use the object returned by createFancySequence().
    public static class FancySequence {
        private static final long MOD = 1000000007L;
        private final List<Long> values = new ArrayList<>();
        private final List<Long> mulAt = new ArrayList<>();
        private final List<Long> addAt = new ArrayList<>();
        private long curMul = 1L;
        private long curAdd = 0L;

        public void append(int val) {
            values.add((long) val);
            mulAt.add(curMul);
            addAt.add(curAdd);
        }

        public void addAll(int inc) {
            curAdd = (curAdd + inc) % MOD;
        }

        public void multAll(int m) {
            curMul = (curMul * m) % MOD;
            curAdd = (curAdd * m) % MOD;
        }

        public int getIndex(int idx) {
            if (idx < 0 || idx >= values.size()) return -1;
            long v = values.get(idx);
            long m0 = mulAt.get(idx);
            long a0 = addAt.get(idx);
            long inv = modPow(m0, MOD - 2);
            long factor = (curMul * inv) % MOD;
            // FIXED: must subtract a0*factor (not a0*inv) - see js_algo fix note.
            long add = ((curAdd - (a0 * factor) % MOD) % MOD + MOD) % MOD;
            long res = (v * factor + add) % MOD;
            return (int) res;
        }

        private long modPow(long base, long exp) {
            long result = 1L;
            while (exp > 0) {
                if ((exp & 1L) == 1L) result = (result * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return result;
        }
    }
}

