class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        visited.add(s);
        queue.offer(s);
        String best = s;
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (cur.compareTo(best) < 0) {
                best = cur;
            }
            String added = addOperation(cur, a);
            if (visited.add(added)) {
                queue.offer(added);
            }
            String rotated = rotateOperation(cur, b);
            if (visited.add(rotated)) {
                queue.offer(rotated);
            }
        }
        return best;
    }

    private String addOperation(String s, int a) {
        char[] chars = s.toCharArray();
        for (int i = 1; i < chars.length; i += 2) {
            int digit = chars[i] - '0';
            digit = (digit + a) % 10;
            chars[i] = (char) (digit + '0');
        }
        return new String(chars);
    }

    private String rotateOperation(String s, int b) {
        int n = s.length();
        b = b % n;
        if (b == 0) return s;
        String part1 = s.substring(n - b);
        String part2 = s.substring(0, n - b);
        return part1 + part2;
    }
}

