class Solution {
    public static boolean[] checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        int m = l.length;
        boolean[] answer = new boolean[m];
        for (int i = 0; i < m; i++) {
            int start = l[i];
            int end = r[i];
            int len = end - start + 1;
            if (len <= 2) {
                answer[i] = true;
                continue;
            }
            int min = nums[start];
            int max = nums[start];
            for (int j = start + 1; j <= end; j++) {
                int v = nums[j];
                if (v < min) min = v;
                if (v > max) max = v;
            }
            if ((max - min) % (len - 1) != 0) {
                answer[i] = false;
                continue;
            }
            int diff = (max - min) / (len - 1);
            if (diff == 0) {
                answer[i] = true;
                continue;
            }
            boolean[] seen = new boolean[len];
            boolean ok = true;
            for (int j = start; j <= end && ok; j++) {
                int v = nums[j];
                if ((v - min) % diff != 0) {
                    ok = false;
                    break;
                }
                int idx = (v - min) / diff;
                if (idx < 0 || idx >= len || seen[idx]) {
                    ok = false;
                    break;
                }
                seen[idx] = true;
            }
            answer[i] = ok;
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public static int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;

        class Cell {
            int val;
            int row;
            int col;
            Cell(int v, int r, int c) {
                this.val = v;
                this.row = r;
                this.col = c;
            }
        }

        List<Cell> cells = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells.add(new Cell(matrix[i][j], i, j));
            }
        }

        cells.sort(Comparator.comparingInt(c -> c.val));

        int[][] answer = new int[m][n];
        int[] rank = new int[m + n];

        int idx = 0;
        while (idx < cells.size()) {
            List<Cell> sameVal = new ArrayList<>();
            int curVal = cells.get(idx).val;
            while (idx < cells.size() && cells.get(idx).val == curVal) {
                sameVal.add(cells.get(idx));
                idx++;
            }

            Map<Integer, Integer> parent = new HashMap<>();

            java.util.function.Function<Integer, Integer> find = new java.util.function.Function<Integer, Integer>() {
                @Override
                public Integer apply(Integer x) {
                    if (!parent.containsKey(x)) parent.put(x, x);
                    while (!parent.get(x).equals(x)) {
                        parent.put(x, parent.get(parent.get(x)));
                        x = parent.get(x);
                    }
                    return x;
                }
            };

            java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
                int ra = find.apply(a);
                int rb = find.apply(b);
                if (ra != rb) parent.put(ra, rb);
            };

            for (Cell cell : sameVal) {
                union.accept(cell.row, m + cell.col);
            }

            Map<Integer, Integer> compMax = new HashMap<>();
            for (Cell cell : sameVal) {
                int root = find.apply(cell.row);
                int curMax = Math.max(rank[cell.row], rank[m + cell.col]);
                compMax.put(root, Math.max(compMax.getOrDefault(root, 0), curMax));
            }

            for (Cell cell : sameVal) {
                int root = find.apply(cell.row);
                int newRank = compMax.get(root) + 1;
                answer[cell.row][cell.col] = newRank;
                rank[cell.row] = newRank;
                rank[m + cell.col] = newRank;
            }
        }

        return answer;
    }
}

