public class Solution {
    public static int numWays(String[] words, String target) {
        final int MOD = 1_000_000_007;
        int m = words[0].length();
        int n = target.length();
        int[][] count = new int[26][m];
        for (String w : words) {
            for (int pos = 0; pos < m; pos++) {
                int idx = w.charAt(pos) - 'a';
                count[idx][pos]++;
            }
        }
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int pos = 0; pos < m; pos++) {
            int limit = Math.min(n, pos + 1);
            for (int i = limit; i >= 1; i--) {
                int charIdx = target.charAt(i - 1) - 'a';
                int ways = count[charIdx][pos];
                if (ways != 0) {
                    dp[i] = (dp[i] + dp[i - 1] * ways) % MOD;
                }
            }
        }
        return (int) dp[n];
    }
}

