        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s.charAt(i) != t.charAt(j)) {
                    int left = 0;
                    while (i - 1 - left >= 0 && j - 1 - left >= 0 && s.charAt(i - 1 - left) == t.charAt(j - 1 - left)) {
                        left++;
                    }
                    int right = 0;
                    while (i + 1 + right < n && j + 1 + right < m && s.charAt(i + 1 + right) == t.charAt(j + 1 + right)) {
                        right++;
                    }
                    ans += (long) (left + 1) * (right + 1);
                }
            }
        }
        return (int) ans;
    }
}

