class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0];
        int col = destination[1];
        int max = row + col;
        long[][] comb = new long[max + 1][max + 1];
        for (int i = 0; i <= max; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }
        int h = col;
        int v = row;
        long kLong = k;
        StringBuilder sb = new StringBuilder();
        while (h > 0 && v > 0) {
            long cnt = comb[h - 1 + v][v];
            if (kLong <= cnt) {
                sb.append('H');
                h--;
            } else {
                sb.append('V');
                kLong -= cnt;
                v--;
            }
        }
        while (h-- > 0) sb.append('H');
        while (v-- > 0) sb.append('V');
        return sb.toString();
    }
}

