class Solution {
    public static int createSortedArray(int[] instructions) {
        final int MOD = 1_000_007;
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        List<Integer> uniqList = new ArrayList<>();
        for (int v : sorted) {
            if (uniqList.isEmpty() || uniqList.get(uniqList.size() - 1) != v) {
                uniqList.add(v);
            }
        }
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < uniqList.size(); i++) {
            indexMap.put(uniqList.get(i), i + 1);
        }
        Fenwick bit = new Fenwick(uniqList.size());
        long total = 0;
        for (int i = 0; i < instructions.length; i++) {
            int idx = indexMap.get(instructions[i]);
            int less = bit.prefixSum(idx - 1);
            int greater = i - bit.prefixSum(idx);
            total = (total + Math.min(less, greater)) % MOD;
            bit.add(idx, 1);
        }
        return (int) total;
    }

    private static class Fenwick {
        private final int n;
        private final int[] tree;
        Fenwick(int size) {
            this.n = size;
            this.tree = new int[size + 1];
        }
        void add(int i, int delta) {
            while (i <= n) {
                tree[i] += delta;
                i += i & -i;
            }
        }
        int prefixSum(int i) {
            int sum = 0;
            while (i > 0) {
                sum += tree[i];
                i -= i & -i;
            }
            return sum;
        }
    }
}

import java.util.Arrays;
import java.util.Collections;

class Solution {
    public static int maxProfit(int[] inventory, int orders) {
        final long MOD = 1000000007L;
        final long INV2 = 500000004L;
        Integer[] inv = new Integer[inventory.length];
        for (int i = 0; i < inventory.length; i++) {
            inv[i] = inventory[i];
        }
        Arrays.sort(inv, Collections.reverseOrder());
        int n = inv.length + 1;
        long[] invLong = new long[n];
        for (int i = 0; i < inv.length; i++) {
            invLong[i] = inv[i];
        }
        invLong[n - 1] = 0;
        long profit = 0;
        long ord = orders;
        for (int i = 0; i < n - 1 && ord > 0; i++) {
            long cur = invLong[i];
            long nxt = invLong[i + 1];
            long cnt = i + 1;
            long diff = cur - nxt;
            long balls = diff * cnt;
            if (ord >= balls) {
                long sum = ((cur + nxt + 1) % MOD) * (diff % MOD) % MOD;
                sum = sum * INV2 % MOD;
                profit = (profit + sum * (cnt % MOD)) % MOD;
                ord -= balls;
            } else {
                long full = ord / cnt;
                long rem = ord % cnt;
                long low = cur - full;
                long sumFull = ((cur + low + 1) % MOD) * (full % MOD) % MOD;
                sumFull = sumFull * INV2 % MOD;
                profit = (profit + sumFull * (cnt % MOD)) % MOD;
                profit = (profit + (rem % MOD) * (low % MOD)) % MOD;
                ord = 0;
            }
        }
        return (int) (profit % MOD);
    }
}

import java.util.*;

class Solution {
    public static boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int v : nums) {
            freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
        }
        int[] freqs = new int[freqMap.size()];
        int idx = 0;
        for (int val : freqMap.values()) {
            freqs[idx++] = val;
        }

        int m = quantity.length;
        int fullMask = (1 << m) - 1;

        Integer[] qObj = new Integer[m];
        for (int i = 0; i < m; i++) qObj[i] = quantity[i];
        Arrays.sort(qObj, Collections.reverseOrder());
        for (int i = 0; i < m; i++) quantity[i] = qObj[i];

        int[] subsetSum = new int[1 << m];
        for (int mask = 1; mask < (1 << m); mask++) {
            int lsb = mask & -mask;
            int bitIdx = Integer.numberOfTrailingZeros(lsb);
            subsetSum[mask] = subsetSum[mask ^ lsb] + quantity[bitIdx];
        }

        Map<String, Boolean> memo = new HashMap<>();
        return dfs(fullMask, 0, freqs, quantity, subsetSum, memo);
    }

    private static boolean dfs(int mask, int i, int[] freqs, int[] quantity, int[] subsetSum, Map<String, Boolean> memo) {
        if (mask == 0) return true;
        if (i == freqs.length) return false;
        String key = mask + "," + i;
        if (memo.containsKey(key)) return memo.get(key);

        if (dfs(mask, i + 1, freqs, quantity, subsetSum, memo)) {
            memo.put(key, true);
            return true;
        }

        for (int sub = mask; sub != 0; sub = (sub - 1) & mask) {
            if (subsetSum[sub] <= freqs[i]) {
                if (dfs(mask ^ sub, i + 1, freqs, quantity, subsetSum, memo)) {
                    memo.put(key, true);
                    return true;
                }
            }
        }

        memo.put(key, false);
        return false;
    }
}

