class Solution {
    public static int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) return result;
        int steps = Math.abs(k);
        int window = 0;
        if (k > 0) {
            for (int i = 1; i <= steps; i++) {
                window += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = window;
                window -= code[(i + 1) % n];
                window += code[(i + steps + 1) % n];
            }
        } else {
            for (int i = 0; i < steps; i++) {
                window += code[(n - 1 - i + n) % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = window;
                window -= code[(i - steps + n) % n];
                window += code[i];
            }
        }
        return result;
    }
}

class Solution {
    public static int minDeletion(String s) {
        int totalA = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 'a') totalA++;
        }
        int bCount = 0;
        int aSeen = 0;
        int answer = totalA;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == 'b') bCount++;
            else aSeen++;
            int deletions = bCount + (totalA - aSeen);
            if (deletions < answer) answer = deletions;
        }
        return answer;
    }
}

