class Solution {
    public static int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> forbiddenSet = new HashSet<>();
        for (int v : forbidden) {
            forbiddenSet.add(v);
        }
        int maxForbidden = 0;
        for (int v : forbidden) {
            if (v > maxForbidden) maxForbidden = v;
        }
        int limit = Math.max(maxForbidden, x) + a + b;

        Set<String> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0, 0}); // position, prevBack (0 false, 1 true), steps
        visited.add("0,0");

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int pos = cur[0];
            boolean prevBack = cur[1] == 1;
            int steps = cur[2];
            if (pos == x) return steps;

            int forward = pos + a;
            if (forward <= limit && !forbiddenSet.contains(forward)) {
                String key = forward + ",0";
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.offer(new int[]{forward, 0, steps + 1});
                }
            }

            if (!prevBack) {
                int backward = pos - b;
                if (backward >= 0 && !forbiddenSet.contains(backward)) {
                    String key = backward + ",1";
                    if (!visited.contains(key)) {
                        visited.add(key);
                        queue.offer(new int[]{backward, 1, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
}

