import java.util.Collections;

class Solution {
    public static boolean areCloseStrings(String word1, String word2) {
        if (word1.length() != word2.length()) return false;
        int[] cnt1 = new int[26];
        int[] cnt2 = new int[26];
        int aCode = (int) 'a';
        for (int i = 0; i < word1.length(); i++) {
            cnt1[word1.charAt(i) - aCode]++;
            cnt2[word2.charAt(i) - aCode]++;
        }
        for (int i = 0; i < 26; i++) {
            if ((cnt1[i] == 0) != (cnt2[i] == 0)) return false;
        }
        ArrayList<Integer> freq1 = new ArrayList<>();
        ArrayList<Integer> freq2 = new ArrayList<>();
        for (int i = 0; i < 26; i++) {
            if (cnt1[i] > 0) freq1.add(cnt1[i]);
            if (cnt2[i] > 0) freq2.add(cnt2[i]);
        }
        Collections.sort(freq1);
        Collections.sort(freq2);
        for (int i = 0; i < freq1.size(); i++) {
            if (!freq1.get(i).equals(freq2.get(i))) return false;
        }
        return true;
    }
}

