class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        long[] prefEven = new long[n + 1];
        long[] prefOdd = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefEven[i + 1] = prefEven[i];
            prefOdd[i + 1] = prefOdd[i];
            if ((i & 1) == 0) {
                prefEven[i + 1] += nums[i];
            } else {
                prefOdd[i + 1] += nums[i];
            }
        }
        long totalEven = prefEven[n];
        long totalOdd = prefOdd[n];
        int count = 0;
        for (int i = 0; i < n; i++) {
            long leftEven = prefEven[i];
            long leftOdd = prefOdd[i];
            long rightEven = totalEven - prefEven[i + 1];
            long rightOdd = totalOdd - prefOdd[i + 1];
            long newEven = leftEven + rightOdd;
            long newOdd = leftOdd + rightEven;
            if (newEven == newOdd) {
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    private static int best;

    public static int maxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int totalCells = m * n;
        int[] grid = new int[totalCells];
        int[] base = new int[3];
        base[1] = 120;
        base[2] = 40;
        int[][] adjDelta = new int[3][3];
        adjDelta[1][1] = -60;
        adjDelta[1][2] = -10;
        adjDelta[2][1] = -10;
        adjDelta[2][2] = 40;
        best = 0;
        dfs(0, introvertsCount, extrovertsCount, 0, grid, totalCells, n, base, adjDelta);
        return best;
    }

    private static void dfs(int pos, int introLeft, int extroLeft, int current, int[] grid,
                            int totalCells, int n, int[] base, int[][] adjDelta) {
        if (pos == totalCells) {
            if (current > best) best = current;
            return;
        }
        if (introLeft == 0 && extroLeft == 0) {
            if (current > best) best = current;
            return;
        }

        // Option 1: leave empty
        dfs(pos + 1, introLeft, extroLeft, current, grid, totalCells, n, base, adjDelta);

        int row = pos / n;
        int col = pos % n;
        int left = col > 0 ? grid[pos - 1] : 0;
        int up = row > 0 ? grid[pos - n] : 0;

        // Option 2: place introvert
        if (introLeft > 0) {
            int add = base[1];
            if (left != 0) add += adjDelta[1][left];
            if (up != 0) add += adjDelta[1][up];
            grid[pos] = 1;
            dfs(pos + 1, introLeft - 1, extroLeft, current + add, grid, totalCells, n, base, adjDelta);
            grid[pos] = 0;
        }

        // Option 3: place extrovert
        if (extroLeft > 0) {
            int add = base[2];
            if (left != 0) add += adjDelta[2][left];
            if (up != 0) add += adjDelta[2][up];
            grid[pos] = 2;
            dfs(pos + 1, introLeft, extroLeft - 1, current + add, grid, totalCells, n, base, adjDelta);
            grid[pos] = 0;
        }
    }
}

