class Solution {
    public static int minInitialEnergy(int[][] tasks) {
        Arrays.sort(tasks, (a, b) -> Integer.compare(b[1] - b[0], a[1] - a[0]));
        long energy = 0;
        long answer = 0;
        for (int[] task : tasks) {
            int actual = task[0];
            int minimum = task[1];
            if (energy < minimum) {
                answer += minimum - energy;
                energy = minimum;
            }
            energy -= actual;
        }
        return (int) answer;
    }
}

