class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

class Solution {
    public static ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        ListNode prevA = null;
        ListNode cur = list1;
        for (int i = 0; i < a; i++) {
            prevA = cur;
            cur = cur.next;
        }
        ListNode postB = cur;
        for (int i = a; i <= b; i++) {
            postB = postB.next;
        }
        ListNode tail2 = list2;
        while (tail2.next != null) {
            tail2 = tail2.next;
        }
        if (prevA != null) {
            prevA.next = list2;
        } else {
            list1 = list2;
        }
        tail2.next = postB;
        return list1;
    }
}

public class Solution {
    public static String smallestString(int n, int k) {
        int extra = k - n;
        char[] chars = new char[n];
        java.util.Arrays.fill(chars, 'a');
        for (int i = n - 1; i >= 0 && extra > 0; i--) {
            int add = Math.min(25, extra);
            chars[i] = (char) ('a' + add);
            extra -= add;
        }
        return new String(chars);
    }
}

import java.util.*;
class FrontMiddleBackQueue {
    private Deque<Integer> left = new ArrayDeque<>();
    private Deque<Integer> right = new ArrayDeque<>();
    public void pushFront(int val) {
        left.addFirst(val);
        if (left.size() > right.size() + 1) right.addFirst(left.removeLast());
    }
    public void pushMiddle(int val) {
        if (left.size() > right.size()) right.addFirst(left.removeLast());
        left.addLast(val);
    }
    public void pushBack(int val) {
        right.addLast(val);
        if (left.size() < right.size()) left.addLast(right.removeFirst());
    }
    public int popFront() {
        if (left.isEmpty() && right.isEmpty()) return -1;
        int val = left.isEmpty() ? right.removeFirst() : left.removeFirst();
        if (left.size() < right.size()) left.addLast(right.removeFirst());
        return val;
    }
    public int popMiddle() {
        if (left.isEmpty() && right.isEmpty()) return -1;
        int val = left.removeLast();
        if (left.size() < right.size()) left.addLast(right.removeFirst());
        return val;
    }
    public int popBack() {
        if (left.isEmpty() && right.isEmpty()) return -1;
        int val = right.isEmpty() ? left.removeLast() : right.removeLast();
        if (left.size() > right.size() + 1) right.addFirst(left.removeLast());
        return val;
    }
}

import java.util.ArrayList;

class Solution {
    public static int minimumDeviation(int[] nums) {
        class MaxHeap {
            private final ArrayList<Integer> data = new ArrayList<>();
            int peek() {
                return data.get(0);
            }
            void push(int val) {
                ArrayList<Integer> a = data;
                a.add(val);
                int i = a.size() - 1;
                while (i > 0) {
                    int p = (i - 1) >> 1;
                    if (a.get(p) >= a.get(i)) break;
                    int tmp = a.get(p);
                    a.set(p, a.get(i));
                    a.set(i, tmp);
                    i = p;
                }
            }
            int pop() {
                ArrayList<Integer> a = data;
                int top = a.get(0);
                int last = a.remove(a.size() - 1);
                if (!a.isEmpty()) {
                    a.set(0, last);
                    int i = 0;
                    while (true) {
                        int l = i * 2 + 1;
                        int r = i * 2 + 2;
                        int largest = i;
                        if (l < a.size() && a.get(l) > a.get(largest)) largest = l;
                        if (r < a.size() && a.get(r) > a.get(largest)) largest = r;
                        if (largest == i) break;
                        int tmp = a.get(i);
                        a.set(i, a.get(largest));
                        a.set(largest, tmp);
                        i = largest;
                    }
                }
                return top;
            }
        }

        MaxHeap heap = new MaxHeap();
        int currentMin = Integer.MAX_VALUE;
        for (int x : nums) {
            if ((x & 1) == 1) x *= 2;
            heap.push(x);
            if (x < currentMin) currentMin = x;
        }
        int best = heap.peek() - currentMin;
        while ((heap.peek() & 1) == 0) {
            int maxVal = heap.pop();
            int reduced = maxVal / 2;
            heap.push(reduced);
            if (reduced < currentMin) currentMin = reduced;
            int deviation = heap.peek() - currentMin;
            if (deviation < best) best = deviation;
        }
        return best;
    }
}

