import java.util.Arrays;

public class Solution {
    public static int[] mostCompetitive(int[] nums, int k) {
        int[] stack = new int[k];
        int top = 0;
        for (int i = 0; i < nums.length; i++) {
            while (top > 0 && stack[top - 1] > nums[i] && (top - 1 + (nums.length - i) >= k)) {
                top--;
            }
            if (top < k) {
                stack[top++] = nums[i];
            }
        }
        return Arrays.copyOf(stack, k);
    }
}

import java.util.Arrays;

class Solution {
    public static int maxOperations(int[] nums, int k) {
        Arrays.sort(nums);
        int left = 0;
        int right = nums.length - 1;
        int operations = 0;
        while (left < right) {
            int sum = nums[left] + nums[right];
            if (sum == k) {
                operations++;
                left++;
                right--;
            } else if (sum < k) {
                left++;
            } else {
                right--;
            }
        }
        return operations;
    }
}

