class Solution {
    public static int concatenatedBinary(int n) {
        final long MOD = 1000000007L;
        long result = 0L;
        long pow2 = 1L;
        for (int i = 1; i <= n; i++) {
            if ((i & (i - 1)) == 0) {
                pow2 = (pow2 * 2L) % MOD;
            }
            result = (result * pow2 + i) % MOD;
        }
        return (int) result;
    }
}

import java.util.*;

class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int pairs = n / 2;
        int maxSum = 2 * limit;
        int[] diff = new int[maxSum + 2];
        for (int i = 0; i < pairs; i++) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int low = Math.min(a, b) + 1;
            int high = Math.max(a, b) + limit;
            diff[low] -= 1;
            diff[high + 1] += 1;
            int sum = a + b;
            diff[sum] -= 1;
            diff[sum + 1] += 1;
        }
        int cur = 0;
        int result = Integer.MAX_VALUE;
        int base = 2 * pairs;
        for (int t = 2; t <= maxSum; t++) {
            cur += diff[t];
            int moves = base + cur;
            if (moves < result) {
                result = moves;
            }
        }
        return result;
    }
}

