class Solution {
    public static long[] sumOfAbsoluteDifferences(int[] nums) {
        int n = nums.length;
        long[] prefix = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += nums[i];
            prefix[i] = sum;
        }
        long total = sum;
        long[] result = new long[n];
        for (int i = 0; i < n; i++) {
            int leftCount = i;
            int rightCount = n - i - 1;
            long leftSum = leftCount > 0 ? prefix[i - 1] : 0;
            long rightSum = total - prefix[i];
            result[i] = (long) nums[i] * leftCount - leftSum + rightSum - (long) nums[i] * rightCount;
        }
        return result;
    }
}

