import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] ports = new int[n];
        int[] weight = new int[n];
        for (int i = 0; i < n; i++) {
            ports[i] = boxes[i][0];
            weight[i] = boxes[i][1];
        }

        int[] pre = new int[n];
        pre[0] = 0;
        for (int i = 1; i < n; i++) {
            pre[i] = pre[i - 1] + (ports[i] != ports[i - 1] ? 1 : 0);
        }

        int[] dp = new int[n + 1];
        dp[0] = 0;

        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(0);

        int left = 0;
        int curWeight = 0;

        for (int i = 1; i <= n; i++) {
            curWeight += weight[i - 1];

            while (i - left > maxBoxes || curWeight > maxWeight) {
                curWeight -= weight[left];
                left++;
            }

            while (!deque.isEmpty() && deque.peekFirst() < left) {
                deque.pollFirst();
            }

            int bestIdx = deque.peekFirst();
            dp[i] = dp[bestIdx] + (pre[i - 1] - pre[bestIdx]) + 2;

            if (i < n) {
                int value = dp[i] - pre[i];
                while (!deque.isEmpty() && (dp[deque.peekLast()] - pre[deque.peekLast()]) >= value) {
                    deque.pollLast();
                }
                deque.addLast(i);
            }
        }

        return dp[n];
    }
}

import java.util.*;

class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        int groupSize = n / k;
        int[] cnt = new int[n + 1];
        for (int v : nums) {
            cnt[v]++;
            if (cnt[v] > k) return -1;
        }
        int totalMask = (1 << n) - 1;
        int INF = Integer.MAX_VALUE / 4;
        int[] incompat = new int[1 << n];
        Arrays.fill(incompat, -1);
        for (int mask = 0; mask <= totalMask; mask++) {
            if (Integer.bitCount(mask) != groupSize) continue;
            int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
            int valMask = 0;
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                if ((mask >> i & 1) == 1) {
                    int v = nums[i];
                    if ((valMask >> v & 1) == 1) {
                        ok = false;
                        break;
                    }
                    valMask |= 1 << v;
                    if (v < min) min = v;
                    if (v > max) max = v;
                }
            }
            if (ok) incompat[mask] = max - min;
        }
        List<Integer> valid = new ArrayList<>();
        for (int mask = 0; mask <= totalMask; mask++) {
            if (incompat[mask] != -1) valid.add(mask);
        }
        int[] dp = new int[1 << n];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 0; mask <= totalMask; mask++) {
            if (dp[mask] == INF) continue;
            for (int sub : valid) {
                if ((mask & sub) != 0) continue;
                int newMask = mask | sub;
                dp[newMask] = Math.min(dp[newMask], dp[mask] + incompat[sub]);
            }
        }
        return dp[totalMask] == INF ? -1 : dp[totalMask];
    }
}

import java.util.Arrays;

class Solution {
    public static int maxHeight(int[][] cuboids) {
        for (int[] c : cuboids) {
            Arrays.sort(c);
        }
        Arrays.sort(cuboids, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
            return Integer.compare(a[2], b[2]);
        });
        int n = cuboids.length;
        int[] dp = new int[n];
        int best = 0;
        for (int i = 0; i < n; ++i) {
            int h = cuboids[i][2];
            dp[i] = h;
            for (int j = 0; j < i; ++j) {
                if (cuboids[j][0] <= cuboids[i][0] &&
                    cuboids[j][1] <= cuboids[i][1] &&
                    cuboids[j][2] <= cuboids[i][2]) {
                    dp[i] = Math.max(dp[i], dp[j] + h);
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

