class Solution {
    public static long maxErasureValue(int[] nums) {
        Map<Integer, Integer> lastSeen = new HashMap<>();
        int left = 0;
        long currentSum = 0;
        long best = 0;
        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];
            if (lastSeen.containsKey(val) && lastSeen.get(val) >= left) {
                while (left <= lastSeen.get(val)) {
                    currentSum -= nums[left];
                    left++;
                }
            }
            currentSum += val;
            lastSeen.put(val, right);
            if (currentSum > best) {
                best = currentSum;
            }
        }
        return best;
    }
}

import java.util.Arrays;

class Solution {
    public static boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        Arrays.sort(edgeList, (a, b) -> Integer.compare(a[2], b[2]));
        int m = queries.length;
        int[][] indexedQueries = new int[m][4];
        for (int i = 0; i < m; i++) {
            indexedQueries[i][0] = queries[i][0];
            indexedQueries[i][1] = queries[i][1];
            indexedQueries[i][2] = queries[i][2];
            indexedQueries[i][3] = i;
        }
        Arrays.sort(indexedQueries, (a, b) -> Integer.compare(a[2], b[2]));
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        boolean[] answer = new boolean[m];
        int e = 0;
        for (int i = 0; i < m; i++) {
            int p = indexedQueries[i][0];
            int q = indexedQueries[i][1];
            int limit = indexedQueries[i][2];
            int idx = indexedQueries[i][3];
            while (e < edgeList.length && edgeList[e][2] < limit) {
                union(parent, rank, edgeList[e][0], edgeList[e][1]);
                e++;
            }
            answer[idx] = find(parent, p) == find(parent, q);
        }
        return answer;
    }

    private static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static void union(int[] parent, int[] rank, int x, int y) {
        int rx = find(parent, x);
        int ry = find(parent, y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank[rx]++;
        }
    }
}

class Solution {
    public String maximumBinaryString(String binary) {
        int n = binary.length();
        int zeros = 0;
        for (char c : binary.toCharArray()) if (c == '0') zeros++;
        if (zeros == 0) return binary;
        int prefixOnes = 0;
        while (binary.charAt(prefixOnes) == '1') prefixOnes++;
        int zeroPos = prefixOnes + zeros - 1;
        char[] res = new char[n];
        for (int i = 0; i < n; i++) res[i] = (i == zeroPos) ? '0' : '1';
        return new String(res);
    }
}

