public class Solution {
    public static long minMoves(int[] nums, int k) {
        List<Integer> positions = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 1) {
                positions.add(i);
            }
        }
        int m = positions.size();
        if (k <= 1) {
            return 0L;
        }
        long[] prefix = new long[m + 1];
        for (int i = 0; i < m; i++) {
            long adjusted = (long) positions.get(i) - i;
            prefix[i + 1] = prefix[i] + adjusted;
        }
        long answer = Long.MAX_VALUE;
        for (int start = 0; start + k - 1 < m; start++) {
            int end = start + k - 1;
            int mid = start + k / 2;
            long medianAdjusted = (long) positions.get(mid) - mid;
            long leftCount = mid - start;
            long rightCount = end - mid;
            long leftSum = prefix[mid] - prefix[start];
            long rightSum = prefix[end + 1] - prefix[mid + 1];
            long cost = medianAdjusted * leftCount - leftSum + rightSum - medianAdjusted * rightCount;
            if (cost < answer) {
                answer = cost;
            }
        }
        return answer;
    }
}

