import java.util.ArrayList;

class Solution {
    private static class Node {
        int expire;
        int count;
        Node(int expire, int count) {
            this.expire = expire;
            this.count = count;
        }
    }

    public static int maxEatenApples(int[] apples, int[] days) {
        ArrayList<Node> heap = new ArrayList<>();
        int n = apples.length;
        int day = 0;
        int eaten = 0;

        java.util.function.BiConsumer<Integer, Integer> swap = (i, j) -> {
            Node temp = heap.get(i);
            heap.set(i, heap.get(j));
            heap.set(j, temp);
        };

        java.util.function.IntConsumer siftUp = new java.util.function.IntConsumer() {
            public void accept(int idx) {
                while (idx > 0) {
                    int parent = (idx - 1) >> 1;
                    if (heap.get(parent).expire <= heap.get(idx).expire) break;
                    swap.accept(parent, idx);
                    idx = parent;
                }
            }
        };

        java.util.function.IntConsumer siftDown = new java.util.function.IntConsumer() {
            public void accept(int idx) {
                while (true) {
                    int smallest = idx;
                    int left = idx * 2 + 1;
                    int right = left + 1;
                    int len = heap.size();
                    if (left < len && heap.get(left).expire < heap.get(smallest).expire) smallest = left;
                    if (right < len && heap.get(right).expire < heap.get(smallest).expire) smallest = right;
                    if (smallest == idx) break;
                    swap.accept(idx, smallest);
                    idx = smallest;
                }
            }
        };

        java.util.function.Consumer<Node> push = node -> {
            heap.add(node);
            siftUp.accept(heap.size() - 1);
        };

        java.util.function.Supplier<Node> pop = () -> {
            Node top = heap.get(0);
            Node last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                siftDown.accept(0);
            }
            return top;
        };

        while (day < n || !heap.isEmpty()) {
            if (day < n && apples[day] > 0) {
                push.accept(new Node(day + days[day], apples[day]));
            }
            while (!heap.isEmpty() && (heap.get(0).expire <= day || heap.get(0).count == 0)) {
                pop.get();
            }
            if (!heap.isEmpty()) {
                Node cur = heap.get(0);
                cur.count--;
                eaten++;
                if (cur.count == 0) {
                    pop.get();
                }
            }
            day++;
        }
        return eaten;
    }
}

import java.util.*;

class Solution {
    private static class TrieNode {
        TrieNode[] child = new TrieNode[2];
        int cnt = 0;
    }

    private static void insert(TrieNode root, int num) {
        TrieNode node = root;
        node.cnt++;
        for (int i = 30; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (node.child[bit] == null) {
                node.child[bit] = new TrieNode();
            }
            node = node.child[bit];
            node.cnt++;
        }
    }

    private static int query(TrieNode root, int x) {
        if (root.cnt == 0) return -1;
        TrieNode node = root;
        int ans = 0;
        for (int i = 30; i >= 0; i--) {
            int bit = (x >> i) & 1;
            int toggled = bit ^ 1;
            if (node.child[toggled] != null && node.child[toggled].cnt > 0) {
                ans |= (1 << i);
                node = node.child[toggled];
            } else {
                node = node.child[bit];
            }
        }
        return ans;
    }

    public int[] maximizeXor(int[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        int[] ans = new int[q];
        Arrays.sort(nums);
        class Query {
            int x, m, idx;
            Query(int x, int m, int idx) {
                this.x = x;
                this.m = m;
                this.idx = idx;
            }
        }
        Query[] qs = new Query[q];
        for (int i = 0; i < q; i++) {
            qs[i] = new Query(queries[i][0], queries[i][1], i);
        }
        Arrays.sort(qs, Comparator.comparingInt(o -> o.m));
        TrieNode root = new TrieNode();
        int ptr = 0;
        for (Query qu : qs) {
            while (ptr < n && nums[ptr] <= qu.m) {
                insert(root, nums[ptr]);
                ptr++;
            }
            ans[qu.idx] = query(root, qu.x);
        }
        return ans;
    }
}

