class Solution {
    public static int countGoodMeals(int[] deliciousness) {
        final int MOD = 1000000007;
        Map<Integer, Integer> freq = new HashMap<>();
        long result = 0;
        int maxVal = 0;
        for (int v : deliciousness) {
            if (v > maxVal) maxVal = v;
        }
        int limit = 1;
        while (limit <= maxVal * 2) {
            limit <<= 1;
        }
        for (int cur : deliciousness) {
            for (int p = 1; p <= limit; p <<= 1) {
                int need = p - cur;
                Integer count = freq.get(need);
                if (count != null) {
                    result = (result + count) % MOD;
                }
            }
            freq.put(cur, freq.getOrDefault(cur, 0) + 1);
        }
        return (int) result;
    }
}

