class Solution {
    public int waysToSplit(int[] nums) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        long total = prefix[n];
        long MOD = 1_000_000_007L;
        long ans = 0;
        int low = 0, high = 0;
        for (int i = 0; i <= n - 3; i++) {
            long leftSum = prefix[i + 1];
            if (low < i + 1) low = i + 1;
            while (low < n - 1 && prefix[low + 1] - prefix[i + 1] < leftSum) {
                low++;
            }
            if (high < low) high = low;
            while (high < n - 1 && prefix[high + 1] - prefix[i + 1] <= total - prefix[high + 1]) {
                high++;
            }
            if (low <= high - 1) {
                ans = (ans + (high - low)) % MOD;
            }
        }
        return (int) ans;
    }
}

