class Solution {
    public static int minOperations(int[] target, int[] arr) {
        Map<Integer, Integer> pos = new HashMap<>();
        for (int i = 0; i < target.length; i++) {
            pos.put(target[i], i);
        }

        List<Integer> indices = new ArrayList<>();
        for (int v : arr) {
            Integer idx = pos.get(v);
            if (idx != null) {
                indices.add(idx);
            }
        }

        int[] tails = new int[indices.size()];
        int size = 0;
        for (int x : indices) {
            int lo = 0, hi = size;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < x) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            if (lo == size) {
                tails[size++] = x;
            } else {
                tails[lo] = x;
            }
        }

        return target.length - size;
    }
}

