class Solution {
    public static int[] constructDistancedSequence(int n) {
        int len = 2 * n - 1;
        int[] ans = new int[len];
        boolean[] placed = new boolean[n + 1];
        dfs(0, n, len, ans, placed);
        return ans;
    }

    private static boolean dfs(int pos, int n, int len, int[] ans, boolean[] placed) {
        if (pos == len) {
            return true;
        }
        if (ans[pos] != 0) {
            return dfs(pos + 1, n, len, ans, placed);
        }
        for (int num = n; num >= 1; num--) {
            if (num == 1) {
                if (!placed[1]) {
                    ans[pos] = 1;
                    placed[1] = true;
                    if (dfs(pos + 1, n, len, ans, placed)) {
                        return true;
                    }
                    ans[pos] = 0;
                    placed[1] = false;
                }
            } else {
                if (!placed[num]) {
                    int second = pos + num;
                    if (second < len && ans[second] == 0) {
                        ans[pos] = num;
                        ans[second] = num;
                        placed[num] = true;
                        if (dfs(pos + 1, n, len, ans, placed)) {
                            return true;
                        }
                        ans[pos] = 0;
                        ans[second] = 0;
                        placed[num] = false;
                    }
                }
            }
        }
        return false;
    }
}

