class Solution {
    public static int minimumHammingDistance(int[] source, int[] target, int[][] allowedSwaps) {
        int n = source.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
            int ra = find.applyAsInt(a);
            int rb = find.applyAsInt(b);
            if (ra != rb) parent[ra] = rb;
        };

        for (int[] pair : allowedSwaps) union.accept(pair[0], pair[1]);

        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = find.applyAsInt(i);
            groups.computeIfAbsent(root, k -> new ArrayList<>()).add(i);
        }

        int mismatches = 0;
        for (List<Integer> indices : groups.values()) {
            Map<Integer, Integer> srcCount = new HashMap<>();
            for (int idx : indices) {
                int val = source[idx];
                srcCount.put(val, srcCount.getOrDefault(val, 0) + 1);
            }
            for (int idx : indices) {
                int val = target[idx];
                Integer cnt = srcCount.get(val);
                if (cnt != null && cnt > 0) {
                    srcCount.put(val, cnt - 1);
                } else {
                    mismatches++;
                }
            }
        }

        return mismatches;
    }
}

