class Solution {
    public static int calculateMoney(int n) {
        int full = n / 7;
        int rem = n % 7;
        long fullWeeksTotal = 7L * (full * (full + 1) / 2) + 21L * full;
        long remTotal = rem * (full + 1) + (rem * (rem - 1)) / 2;
        return (int) (fullWeeksTotal + remTotal);
    }
}

class Solution {
