        Map<Long, Integer> productCount = new HashMap<>();
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long prod = (long) nums[i] * nums[j];
                productCount.put(prod, productCount.getOrDefault(prod, 0) + 1);
            }
