class Solution {
    public static int numberOfWays(int[][] pairs) {
        Map<Integer, Set<Integer>> adj = new HashMap<>();
        for (int[] p : pairs) {
            int a = p[0];
            int b = p[1];
            adj.computeIfAbsent(a, k -> new HashSet<>()).add(b);
            adj.computeIfAbsent(b, k -> new HashSet<>()).add(a);
        }
        int n = adj.size();
        if (n == 0) return 0;
        Map<Integer, Set<Integer>> full = new HashMap<>();
        for (int node : adj.keySet()) {
            Set<Integer> set = new HashSet<>(adj.get(node));
            set.add(node);
            full.put(node, set);
        }
        List<Integer> roots = new ArrayList<>();
        for (int node : adj.keySet()) {
            if (adj.get(node).size() == n - 1) {
                roots.add(node);
            }
        }
        if (roots.isEmpty()) return 0;
        if (roots.size() > 1) return 2;
        int root = roots.get(0);
        boolean multiple = false;
        for (int node : adj.keySet()) {
            if (node == root) continue;
            Set<Integer> curFull = full.get(node);
            int parent = -1;
            int parentSize = Integer.MAX_VALUE;
            int cntMin = 0;
            for (int nb : adj.get(node)) {
                Set<Integer> nbFull = full.get(nb);
                if (nbFull.containsAll(curFull)) {
                    int sz = nbFull.size();
                    if (sz < parentSize) {
                        parentSize = sz;
                        parent = nb;
                        cntMin = 1;
                    } else if (sz == parentSize) {
                        cntMin++;
                    }
                }
            }
            if (parent == -1) return 0;
            if (cntMin > 1) multiple = true;
        }
        return multiple ? 2 : 1;
    }
}

class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

class Solution {
    public static ListNode swapNodes(ListNode head, int k) {
        ListNode kthFromStart = head;
        for (int i = 1; i < k; i++) {
            kthFromStart = kthFromStart.next;
        }
        ListNode kthFromEnd = head;
        ListNode fast = kthFromStart;
        while (fast.next != null) {
            fast = fast.next;
            kthFromEnd = kthFromEnd.next;
        }
        int tmp = kthFromStart.val;
        kthFromStart.val = kthFromEnd.val;
        kthFromEnd.val = tmp;
        return head;
    }
}

