public class Solution {
    public static int minimumTimeRequired(int[] jobs, int k) {
        Arrays.sort(jobs);
        int n = jobs.length;
        int[] desc = new int[n];
        for (int i = 0; i < n; i++) {
            desc[i] = jobs[n - 1 - i];
        }
        int low = 0, high = 0;
        for (int t : desc) {
            low = Math.max(low, t);
            high += t;
        }
        int[] workloads = new int[k];
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canAssign(desc, workloads, 0, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean canAssign(int[] jobs, int[] workloads, int idx, int limit) {
        if (idx == jobs.length) {
            return true;
        }
        int cur = jobs[idx];
        for (int i = 0; i < workloads.length; i++) {
            if (workloads[i] + cur <= limit) {
                workloads[i] += cur;
                if (canAssign(jobs, workloads, idx + 1, limit)) {
                    workloads[i] -= cur;
                    return true;
                }
                workloads[i] -= cur;
            }
            if (workloads[i] == 0 || workloads[i] + cur == limit) {
                break;
            }
        }
        return false;
    }
}

