class Solution {
    public static int minimumTeachings(int n, List<List<Integer>> languages, int[][] friendships) {
        List<Set<Integer>> userLangSets = new ArrayList<>(languages.size());
        for (List<Integer> arr : languages) {
            userLangSets.add(new HashSet<>(arr));
        }
        Set<Integer> candidates = new HashSet<>();
        for (int[] pair : friendships) {
            int u = pair[0];
            int v = pair[1];
            Set<Integer> setU = userLangSets.get(u - 1);
            Set<Integer> setV = userLangSets.get(v - 1);
            boolean canTalk = false;
            for (int lang : setU) {
                if (setV.contains(lang)) {
                    canTalk = true;
                    break;
                }
            }
            if (!canTalk) {
                candidates.add(u);
                candidates.add(v);
            }
        }
        if (candidates.isEmpty()) return 0;
        int answer = Integer.MAX_VALUE;
        for (int lang = 1; lang <= n; ++lang) {
            int teach = 0;
            for (int user : candidates) {
                if (!userLangSets.get(user - 1).contains(lang)) {
                    teach++;
                }
            }
            if (teach < answer) answer = teach;
        }
        return answer;
    }
}

