class Solution {
    public static int[] decodeXorPermutation(int[] encoded) {
        int n = encoded.length + 1;
        int totalXor = 0;
        for (int i = 1; i <= n; i++) {
            totalXor ^= i;
        }
        int xorExceptFirst = 0;
        for (int i = 1; i < encoded.length; i += 2) {
            xorExceptFirst ^= encoded[i];
        }
        int[] perm = new int[n];
        perm[0] = totalXor ^ xorExceptFirst;
        for (int i = 0; i < encoded.length; i++) {
            perm[i + 1] = perm[i] ^ encoded[i];
        }
        return perm;
    }
}

