class Solution {
    public static int largestSubmatrix(int[][] matrix) {
        if (matrix == null || matrix.length == 0) return 0;
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[] heights = new int[cols];
        int maxArea = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                heights[c] = matrix[r][c] == 1 ? heights[c] + 1 : 0;
            }
            Integer[] sorted = new Integer[cols];
            for (int i = 0; i < cols; i++) sorted[i] = heights[i];
            Arrays.sort(sorted, Collections.reverseOrder());
            for (int i = 0; i < cols; i++) {
                int area = sorted[i] * (i + 1);
                if (area > maxArea) maxArea = area;
            }
        }
        return maxArea;
    }
}

class Solution {
    int[] dirs = {0, 1, 0, -1, 0};
    int m, n, nFloors, catJumpV, mouseJumpV;
    char[][] grid;
    Boolean[][][] memo;

    public boolean canMouseWin(String[] gridArr, int catJump, int mouseJump) {
        m = gridArr.length;
        n = gridArr[0].length();
        grid = new char[m][n];
        catJumpV = catJump; mouseJumpV = mouseJump;
        int cat = 0, mouse = 0;
        nFloors = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = gridArr[i].charAt(j);
                if (grid[i][j] != '#') nFloors++;
                if (grid[i][j] == 'C') cat = h(i, j);
                else if (grid[i][j] == 'M') mouse = h(i, j);
            }
        }
        memo = new Boolean[m * n][m * n][nFloors * 2 + 1];
        return dp(cat, mouse, 0);
    }
    private int h(int i, int j) { return i * n + j; }

    private boolean dp(int cat, int mouse, int turn) {
        if (turn == nFloors * 2) return false;
        if (memo[cat][mouse][turn] != null) return memo[cat][mouse][turn];
        boolean result;
        if (turn % 2 == 0) {
            int i = mouse / n, j = mouse % n;
            result = false;
            outer:
            for (int k = 0; k < 4; k++) {
                for (int jump = 0; jump <= mouseJumpV; jump++) {
                    int x = i + dirs[k] * jump, y = j + dirs[k + 1] * jump;
                    if (x < 0 || x == m || y < 0 || y == n) break;
                    if (grid[x][y] == '#') break;
                    if (grid[x][y] == 'F') { result = true; break outer; }
                    if (dp(cat, h(x, y), turn + 1)) { result = true; break outer; }
                }
            }
        } else {
            int i = cat / n, j = cat % n;
            result = true;
            outer2:
            for (int k = 0; k < 4; k++) {
                for (int jump = 0; jump <= catJumpV; jump++) {
                    int x = i + dirs[k] * jump, y = j + dirs[k + 1] * jump;
                    if (x < 0 || x == m || y < 0 || y == n) break;
                    if (grid[x][y] == '#') break;
                    if (grid[x][y] == 'F') { result = false; break outer2; }
                    int nextCat = h(x, y);
                    if (nextCat == mouse) { result = false; break outer2; }
                    if (!dp(nextCat, mouse, turn + 1)) { result = false; break outer2; }
                }
            }
        }
        memo[cat][mouse][turn] = result;
        return result;
    }
}

