class Solution {
    public static int countBalls(int lowLimit, int highLimit) {
        Map<Integer, Integer> boxCounts = new HashMap<>();
        int maxBalls = 0;
        for (int num = lowLimit; num <= highLimit; num++) {
            int sum = 0;
            int x = num;
            while (x > 0) {
                sum += x % 10;
                x = x / 10;
            }
            int newCount = boxCounts.getOrDefault(sum, 0) + 1;
            boxCounts.put(sum, newCount);
            if (newCount > maxBalls) {
                maxBalls = newCount;
            }
        }
        return maxBalls;
    }
}

