public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int[] waysToMakeArray(int[][] queries) {
        int q = queries.length;
        int maxN = 0;
        for (int[] query : queries) {
            maxN = Math.max(maxN, query[0]);
        }
        int limit = maxN + 30; // enough for any exponent up to k <= 10^4
        long[] fact = new long[limit + 1];
        long[] invFact = new long[limit + 1];
        fact[0] = 1;
        for (int i = 1; i <= limit; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[limit] = modPow(fact[limit], MOD - 2);
        for (int i = limit; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        int[] ans = new int[q];
        for (int idx = 0; idx < q; idx++) {
            int n = queries[idx][0];
            int k = queries[idx][1];
            long ways = 1;
            int temp = k;
            for (int p = 2; p * p <= temp; p++) {
                if (temp % p == 0) {
                    int exp = 0;
                    while (temp % p == 0) {
                        temp /= p;
                        exp++;
                    }
                    ways = ways * nCr(exp + n - 1, n - 1, fact, invFact) % MOD;
                }
            }
            if (temp > 1) { // remaining prime factor
                ways = ways * nCr(1 + n - 1, n - 1, fact, invFact) % MOD;
            }
            ans[idx] = (int) ways;
        }
        return ans;
    }

    private static long nCr(int N, int R, long[] fact, long[] invFact) {
        if (R < 0 || R > N) return 0;
        return fact[N] * invFact[R] % MOD * invFact[N - R] % MOD;
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = res * b % MOD;
            }
            b = b * b % MOD;
            exp >>= 1;
        }
        return res;
    }
}

