class Solution {
    public static boolean checkPartitioning(String s) {
        int n = s.length();
        if (n < 3) return false;
        boolean[][] isPal = new boolean[n][n];
        for (int len = 1; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j) && (len <= 2 || isPal[i + 1][j - 1])) {
                    isPal[i][j] = true;
                }
            }
        }
        for (int i = 1; i <= n - 2; i++) {
            if (!isPal[0][i - 1]) continue;
            for (int j = i + 1; j <= n - 1; j++) {
                if (isPal[i][j - 1] && isPal[j][n - 1]) {
                    return true;
                }
            }
        }
        return false;
    }
}

