class Solution {
    public static long minAbsDifference(int[] nums, int goal) {
        int n = nums.length;
        int mid = n / 2;
        int[] left = Arrays.copyOfRange(nums, 0, mid);
        int[] right = Arrays.copyOfRange(nums, mid, n);

        long[] leftSums = genSums(left);
        long[] rightSums = genSums(right);
        Arrays.sort(rightSums);

        long best = Long.MAX_VALUE;

        for (long s1 : leftSums) {
            long need = (long) goal - s1;
            int idx = lowerBound(rightSums, need);

            if (idx < rightSums.length) {
                long cur = Math.abs(s1 + rightSums[idx] - goal);
                if (cur < best) best = cur;
            }
            if (idx > 0) {
                long cur = Math.abs(s1 + rightSums[idx - 1] - goal);
                if (cur < best) best = cur;
            }
            if (best == 0) return 0;
        }

        return best;
    }

    private static long[] genSums(int[] arr) {
        int m = arr.length;
        int total = 1 << m;
        long[] sums = new long[total];
        for (int mask = 0; mask < total; mask++) {
            long s = 0;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) s += arr[i];
            }
            sums[mask] = s;
        }
        return sums;
    }

    private static int lowerBound(long[] arr, long target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

