class Solution {
    public static int minimumLength(String s) {
        int l = 0;
        int r = s.length() - 1;
        while (l < r && s.charAt(l) == s.charAt(r)) {
            char ch = s.charAt(l);
            while (l <= r && s.charAt(l) == ch) {
                l++;
            }
            while (r >= l && s.charAt(r) == ch) {
                r--;
            }
        }
        return l > r ? 0 : r - l + 1;
    }
}

import java.util.*;

public class Solution {
    public boolean canChoose(int[][] groups, int[] nums) {
        int pos = 0;
        for (int[] group : groups) {
            boolean found = false;
            while (pos + group.length <= nums.length) {
                int j = 0;
                while (j < group.length && nums[pos + j] == group[j]) {
                    j++;
                }
                if (j == group.length) {
                    found = true;
                    pos += group.length;
                    break;
                }
                pos++;
            }
            if (!found) {
                return false;
            }
        }
        return true;
    }
}

public class Solution {
    public static int minChanges(String s) {
        int mismatches0 = 0, mismatches1 = 0;
        for (int i = 0; i < s.length(); i++) {
            char expected0 = (i % 2 == 0) ? '0' : '1';
            char expected1 = (i % 2 == 0) ? '1' : '0';
            if (s.charAt(i) != expected0) mismatches0++;
            if (s.charAt(i) != expected1) mismatches1++;
        }
        return Math.min(mismatches0, mismatches1);
    }
}

