class Solution {
    public static int countHomogenous(String s) {
        final long MOD = 1000000007L;
        long total = 0;
        long runLength = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                runLength++;
            } else {
                total = (total + (runLength * (runLength + 1) / 2)) % MOD;
                runLength = 1;
            }
        }
        total = (total + (runLength * (runLength + 1) / 2)) % MOD;
        return (int) total;
    }
}

import java.util.*;

class Solution {
    public String longestNiceSubstring(String s) {
        return helper(s, 0, s.length());
    }

    private String helper(String s, int l, int r) {
        if (r - l < 2) {
            return "";
        }

        boolean[] lower = new boolean[26];
        boolean[] upper = new boolean[26];
        for (int i = l; i < r; i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lower[c - 'a'] = true;
            } else {
                upper[c - 'A'] = true;
            }
        }

        // Find a character that is unbalanced
        char splitChar = 0;
        for (int i = l; i < r; i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c) && !upper[c - 'a']) {
                splitChar = c;
                break;
            }
            if (Character.isUpperCase(c) && !lower[c - 'A']) {
                splitChar = c;
                break;
            }
        }

        // If no split character, the whole substring is nice
        if (splitChar == 0) {
            return s.substring(l, r);
        }

        String best = "";
        int start = l;
        for (int i = l; i < r; i++) {
            if (s.charAt(i) == splitChar) {
                String candidate = helper(s, start, i);
                if (candidate.length() > best.length()) {
                    best = candidate;
                }
                start = i + 1;
            }
        }
        // Process the final segment after the last split character
        String candidate = helper(s, start, r);
        if (candidate.length() > best.length()) {
            best = candidate;
        }

        return best;
    }
}

class Solution {
    public static String largestMerge(String word1, String word2) {
        int i = 0, j = 0;
        StringBuilder merge = new StringBuilder();
        while (i < word1.length() || j < word2.length()) {
            if (i == word1.length()) {
                merge.append(word2.substring(j));
                break;
            }
            if (j == word2.length()) {
                merge.append(word1.substring(i));
                break;
            }
            if (suffixGreater(word1, word2, i, j)) {
                merge.append(word1.charAt(i));
                i++;
            } else {
                merge.append(word2.charAt(j));
                j++;
            }
        }
        return merge.toString();
    }

    private static boolean suffixGreater(String word1, String word2, int p, int q) {
        while (p < word1.length() && q < word2.length()) {
            if (word1.charAt(p) != word2.charAt(q)) {
                return word1.charAt(p) > word2.charAt(q);
            }
            p++;
            q++;
        }
        return p < word1.length();
    }
}

import java.util.*;

class Solution {
    public int[] getCoprimeAncestors(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        boolean[][] coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }
        int[] ans = new int[n];
        int[] depth = new int[n];
        int[] lastSeen = new int[51];
        Arrays.fill(lastSeen, -1);
        int[] prevLast = new int[n];
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, -1, 0}); // node, parent, stage (0=enter,1=exit)
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int parent = cur[1];
            int stage = cur[2];
            if (stage == 0) {
                int bestNode = -1;
                int bestDepth = -1;
                int val = nums[node];
                for (int v = 1; v <= 50; v++) {
                    if (coprime[val][v] && lastSeen[v] != -1) {
                        int cand = lastSeen[v];
                        if (depth[cand] > bestDepth) {
                            bestDepth = depth[cand];
                            bestNode = cand;
                        }
                    }
                }
                ans[node] = bestNode;
                prevLast[node] = lastSeen[val];
                lastSeen[val] = node;
                stack.push(new int[]{node, parent, 1});
                for (int child : graph[node]) {
                    if (child == parent) continue;
                    depth[child] = depth[node] + 1;
                    stack.push(new int[]{child, node, 0});
                }
            } else {
                int val = nums[node];
                lastSeen[val] = prevLast[node];
            }
        }
        return ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.*;

class Solution {
    public static int longestPalindromeFromSubsequences(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        String rev2 = new StringBuilder(word2).reverse().toString();
        int[] prev = new int[m + 1];
        int[] cur = new int[m + 1];
        for (int i = 1; i <= n; i++) {
            cur[0] = 0;
            char c1 = word1.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                if (c1 == rev2.charAt(j - 1)) {
                    cur[j] = prev[j - 1] + 1;
                } else {
                    cur[j] = prev[j] > cur[j - 1] ? prev[j] : cur[j - 1];
                }
            }
            int[] temp = prev;
            prev = cur;
            cur = temp;
        }
        int k = prev[m];
        boolean hasCommon = false;
        boolean[] present = new boolean[256];
        for (int i = 0; i < n; i++) {
            present[word1.charAt(i)] = true;
        }
        for (int i = 0; i < m; i++) {
            if (present[word2.charAt(i)]) {
                hasCommon = true;
                break;
            }
        }
        int ans = 2 * k;
        if (hasCommon) {
            ans = Math.max(ans, 2 * k + 1);
        }
        return ans;
    }
}

