class Solution {
    public static int closestDessertCost(int[] baseCosts, int[] toppingCosts, int target) {
        List<Integer> toppingSums = new ArrayList<>();
        dfs(0, 0, toppingCosts, toppingSums);
        int best = Integer.MAX_VALUE;
        for (int base : baseCosts) {
            for (int top : toppingSums) {
                int total = base + top;
                int diff = Math.abs(total - target);
                int bestDiff = Math.abs(best - target);
                if (diff < bestDiff || (diff == bestDiff && total < best)) {
                    best = total;
                }
            }
        }
        return best;
    }

    private static void dfs(int i, int cur, int[] toppingCosts, List<Integer> toppingSums) {
        if (i == toppingCosts.length) {
            toppingSums.add(cur);
            return;
        }
        for (int cnt = 0; cnt < 3; cnt++) {
            dfs(i + 1, cur + cnt * toppingCosts[i], toppingCosts, toppingSums);
        }
    }
}

import java.util.*;

class Solution {
    public static double[] carFleetII(int[][] cars) {
        int n = cars.length;
        double[] answer = new double[n];
        Arrays.fill(answer, -1.0);
        Deque<Integer> stack = new ArrayDeque<>();

        for (int i = n - 1; i >= 0; i--) {
            int posI = cars[i][0];
            int speedI = cars[i][1];

            while (!stack.isEmpty()) {
                int j = stack.peek();
                int posJ = cars[j][0];
                int speedJ = cars[j][1];

                if (speedI <= speedJ) {
                    stack.pop();
                    continue;
                }

                double collideTime = (double) (posJ - posI) / (speedI - speedJ);

                if (answer[j] == -1.0 || collideTime <= answer[j]) {
                    break;
                }

                stack.pop();
            }

            if (!stack.isEmpty()) {
                int j = stack.peek();
                int posJ = cars[j][0];
                int speedJ = cars[j][1];
                answer[i] = (double) (posJ - posI) / (speedI - speedJ);
            }

            stack.push(i);
        }

        return answer;
    }
}

import java.lang.Math;

class Solution {
    public static int minOperations(int[] nums1, int[] nums2) {
        int sum1 = 0, sum2 = 0;
        for (int v : nums1) sum1 += v;
        for (int v : nums2) sum2 += v;

        if (sum1 == sum2) return 0;

        if (sum1 > sum2) {
            int[] tmpArr = nums1;
            nums1 = nums2;
            nums2 = tmpArr;
            int tmpSum = sum1;
            sum1 = sum2;
            sum2 = tmpSum;
        }

        int diff = sum2 - sum1;

        int[] cnt = new int[6];
        for (int v : nums1) cnt[6 - v]++;
        for (int v : nums2) cnt[v - 1]++;

        int ops = 0;
        for (int g = 5; g >= 1 && diff > 0; g--) {
            if (cnt[g] == 0) continue;
            int need = (diff + g - 1) / g;
            int use = Math.min(cnt[g], need);
            diff -= use * g;
            ops += use;
        }

        return diff > 0 ? -1 : ops;
    }
}

class Solution {
    public static int minElements(int[] nums, int limit, int goal) {
        long currentSum = 0;
        for (int v : nums) {
            currentSum += v;
        }
        long diff = (long) goal - currentSum;
        long absDiff = Math.abs(diff);
        return (int) ((absDiff + limit - 1) / limit);
    }
}

