class Solution {
    public static long sumBeauty(String s) {
        int n = s.length();
        long answer = 0;
        for (int i = 0; i < n; i++) {
            int[] freq = new int[26];
            for (int j = i; j < n; j++) {
                int idx = s.charAt(j) - 'a';
                freq[idx]++;
                int maxFreq = 0;
                int minFreq = Integer.MAX_VALUE;
                for (int k = 0; k < 26; k++) {
                    if (freq[k] > 0) {
                        if (freq[k] > maxFreq) maxFreq = freq[k];
                        if (freq[k] < minFreq) minFreq = freq[k];
                    }
                }
                answer += maxFreq - minFreq;
            }
        }
        return answer;
    }
}

