class Solution {
    public static int minOperations(int[] nums, int k) {
        int n = nums.length;
        int period = k; // groups are based on distance k
        @SuppressWarnings("unchecked")
        Map<Integer, Integer>[] freqMaps = new HashMap[period];
        int[] sizes = new int[period];
        for (int i = 0; i < period; i++) {
            freqMaps[i] = new HashMap<>();
        }
        for (int i = 0; i < n; i++) {
            int r = i % period;
            sizes[r]++;
            int val = nums[i];
            Map<Integer, Integer> map = freqMaps[r];
            map.put(val, map.getOrDefault(val, 0) + 1);
        }
        final int MAX = 1024;
        int[] dpPrev = new int[MAX];
        Arrays.fill(dpPrev, -1_000_000);
        dpPrev[0] = 0;
        for (int r = 0; r < period; r++) {
            if (sizes[r] == 0) continue;
            int[] dpCurr = new int[MAX];
            Arrays.fill(dpCurr, -1_000_000);
            for (int v = 0; v < MAX; v++) {
                int freq = freqMaps[r].getOrDefault(v, 0);
                for (int xor = 0; xor < MAX; xor++) {
                    int prev = dpPrev[xor];
                    if (prev < 0) continue;
                    int newXor = xor ^ v;
                    int cand = prev + freq;
                    if (cand > dpCurr[newXor]) dpCurr[newXor] = cand;
                }
            }
            dpPrev = dpCurr;
        }
        int maxFreqSum = dpPrev[0];
        return n - maxFreqSum;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int findCenter(int[][] edges) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            count.put(u, count.getOrDefault(u, 0) + 1);
            count.put(v, count.getOrDefault(v, 0) + 1);
        }
        int needed = edges.length;
        for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
            if (entry.getValue() == needed) {
                return entry.getKey();
            }
        }
        return 0;
    }
}

import java.util.PriorityQueue;

class Solution {
    private static class Info {
        double gain;
        int p;
        int t;
        Info(double gain, int p, int t) {
            this.gain = gain;
            this.p = p;
            this.t = t;
        }
    }

    private static double gain(int p, int t) {
        return ((double) (p + 1) / (t + 1)) - ((double) p / t);
    }

    public static double maxAverageRatio(int[][] classes, int extraStudents) {
        PriorityQueue<Info> heap = new PriorityQueue<>((a, b) -> Double.compare(b.gain, a.gain));
        for (int[] cls : classes) {
            int p = cls[0];
            int t = cls[1];
            heap.offer(new Info(gain(p, t), p, t));
        }
        while (extraStudents-- > 0) {
            Info cur = heap.poll();
            int newP = cur.p + 1;
            int newT = cur.t + 1;
            heap.offer(new Info(gain(newP, newT), newP, newT));
        }
        double sum = 0.0;
        while (!heap.isEmpty()) {
            Info cur = heap.poll();
            sum += (double) cur.p / cur.t;
        }
        double avg = sum / classes.length;
        return Math.round(avg * 100000.0) / 100000.0;
    }
}

