class Solution {
    public static boolean canMakeEqualByOneSwap(String s1, String s2) {
        if (s1.equals(s2)) return true;
        int n = s1.length();
        int[] diff = new int[2];
        int diffCount = 0;
        for (int i = 0; i < n; i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                if (diffCount < 2) {
                    diff[diffCount++] = i;
                } else {
                    return false;
                }
            }
        }
        if (diffCount != 2) return false;
        int i = diff[0];
        int j = diff[1];
        return s1.charAt(i) == s2.charAt(j) && s1.charAt(j) == s2.charAt(i);
    }
}

