class Solution {
    public int maximumScore(int[] nums, int k) {
        int n = nums.length;
        int left = k;
        int right = k;
        int curMin = nums[k];
        int best = curMin;
        while (left > 0 || right < n - 1) {
            if (left == 0) {
                right++;
                curMin = Math.min(curMin, nums[right]);
            } else if (right == n - 1) {
                left--;
                curMin = Math.min(curMin, nums[left]);
            } else {
                if (nums[left - 1] > nums[right + 1]) {
                    left--;
                    curMin = Math.min(curMin, nums[left]);
                } else {
                    right++;
                    curMin = Math.min(curMin, nums[right]);
                }
            }
            int length = right - left + 1;
            best = Math.max(best, curMin * length);
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int maxScore(int[] nums) {
        int m = nums.length;
        int[] memo = new int[1 << m];
        Arrays.fill(memo, -1);
        return dfs(0, nums, memo);
    }

    private int dfs(int mask, int[] nums, int[] memo) {
        int m = nums.length;
        if (mask == (1 << m) - 1) {
            return 0;
        }
        if (memo[mask] != -1) {
            return memo[mask];
        }
        int used = Integer.bitCount(mask);
        int operation = used / 2 + 1;
        int best = 0;
        for (int i = 0; i < m; i++) {
            if ((mask & (1 << i)) != 0) continue;
            for (int j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int newMask = mask | (1 << i) | (1 << j);
                int score = operation * gcd(nums[i], nums[j]) + dfs(newMask, nums, memo);
                if (score > best) {
                    best = score;
                }
            }
        }
        memo[mask] = best;
        return best;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

