import java.util.PriorityQueue;
import java.util.Comparator;

class Solution {
    private static class Node {
        int price;
        long amount;
        Node(int price, long amount) {
            this.price = price;
            this.amount = amount;
        }
    }

    public static int getNumberOfBacklogOrders(int[][] orders) {
        final long MOD = 1_000_000_007L;

        Comparator<Node> buyCmp = (a, b) -> Integer.compare(b.price, a.price);
        Comparator<Node> sellCmp = (a, b) -> Integer.compare(a.price, b.price);

        PriorityQueue<Node> buyHeap = new PriorityQueue<>(buyCmp);
        PriorityQueue<Node> sellHeap = new PriorityQueue<>(sellCmp);

        for (int[] order : orders) {
            int price = order[0];
            long amount = order[1];
            int type = order[2];

            if (type == 0) { // BUY
                while (amount > 0 && !sellHeap.isEmpty() && sellHeap.peek().price <= price) {
                    Node sell = sellHeap.peek();
                    long matched = Math.min(amount, sell.amount);
                    amount -= matched;
                    sell.amount -= matched;
                    if (sell.amount == 0) {
                        sellHeap.poll();
                    }
                }
                if (amount > 0) {
                    buyHeap.offer(new Node(price, amount));
                }
            } else { // SELL
                while (amount > 0 && !buyHeap.isEmpty() && buyHeap.peek().price >= price) {
                    Node buy = buyHeap.peek();
                    long matched = Math.min(amount, buy.amount);
                    amount -= matched;
                    buy.amount -= matched;
                    if (buy.amount == 0) {
                        buyHeap.poll();
                    }
                }
                if (amount > 0) {
                    sellHeap.offer(new Node(price, amount));
                }
            }
        }

        long total = 0;
        for (Node node : buyHeap) {
            total = (total + node.amount) % MOD;
        }
        for (Node node : sellHeap) {
            total = (total + node.amount) % MOD;
        }
        return (int) total;
    }
}

