class Solution {
    public int maxValue(int n, int index, int maxSum) {
        long low = 1;
        long high = maxSum;
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            long left = calcSide(index, mid);
            long right = calcSide(n - index - 1, mid);
            long total = left + right + mid;
            if (total <= maxSum) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return (int) low;
    }

    private long calcSide(long len, long peak) {
        if (len == 0) return 0;
        if (len < peak) {
            long first = peak - 1;
            long last = peak - len;
            return (first + last) * len / 2;
        } else {
            long full = (peak - 1) * peak / 2;
            long rest = len - (peak - 1);
            return full + rest;
        }
    }
}

class Solution {
    public static int maxAscendingSum(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        int maxSum = nums[0];
        int curSum = nums[0];
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > nums[i - 1]) {
                curSum += nums[i];
            } else {
                curSum = nums[i];
            }
            if (curSum > maxSum) maxSum = curSum;
        }
        return maxSum;
    }
}

