class Solution {
    private static class TrieNode {
        int cnt;
        TrieNode[] child = new TrieNode[2];
    }

    private static void insert(TrieNode root, int num, int maxBit) {
        TrieNode node = root;
        for (int i = maxBit; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (node.child[bit] == null) node.child[bit] = new TrieNode();
            node = node.child[bit];
            node.cnt++;
        }
    }

    private static long query(TrieNode root, int num, int K, int maxBit) {
        if (K < 0) return 0;
        TrieNode node = root;
        long total = 0;
        for (int i = maxBit; i >= 0; i--) {
            if (node == null) break;
            int bitNum = (num >> i) & 1;
            int bitK = (K >> i) & 1;
            if (bitK == 1) {
                if (node.child[bitNum] != null) total += node.child[bitNum].cnt;
                node = node.child[1 - bitNum];
            } else {
                node = node.child[bitNum];
            }
        }
        if (node != null) total += node.cnt;
        return total;
    }

    private static long countLessOrEqual(int[] nums, int bound, int maxBit) {
        TrieNode root = new TrieNode();
        long ans = 0;
        for (int num : nums) {
            ans += query(root, num, bound, maxBit);
            insert(root, num, maxBit);
        }
        return ans;
    }

    public static long countPairs(int[] nums, int low, int high) {
        int maxVal = high;
        for (int v : nums) if (v > maxVal) maxVal = v;
        int maxBit = 0;
        while ((1L << maxBit) <= maxVal) maxBit++;
        maxBit = Math.max(0, maxBit - 1);
        return countLessOrEqual(nums, high, maxBit) - countLessOrEqual(nums, low - 1, maxBit);
    }
}

