public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int maxNiceDivisors(int primeFactors) {
        if (primeFactors <= 4) {
            return primeFactors % (int) MOD;
        }
        long count3 = primeFactors / 3;
        int rem = primeFactors % 3;
        long result;
        if (rem == 0) {
            result = modPow(3, count3);
        } else if (rem == 1) {
            result = modPow(3, count3 - 1);
            result = (result * 4) % MOD;
        } else { // rem == 2
            result = modPow(3, count3);
            result = (result * 2) % MOD;
        }
        return (int) result;
    }

    private long modPow(long base, long exp) {
        long res = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

