        String[] words1 = sentence1.split(" ");
        String[] words2 = sentence2.split(" ");
        int n1 = words1.length, n2 = words2.length;
        int minLen = Math.min(n1, n2);
        int left = 0;
        while (left < minLen && words1[left].equals(words2[left])) {
            left++;
        }
        int right = 0;
        while (right < minLen && words1[n1 - 1 - right].equals(words2[n2 - 1 - right])) {
