class Solution {
    private int B;
    private Map<Long, Integer> memo;

    public int maxHappyGroups(int batchSize, int[] groups) {
        B = batchSize;
        int[] cnt = new int[B];
        for (int g : groups) {
            cnt[g % B]++;
        }
        int base = cnt[0];
        cnt[0] = 0; // already counted
        memo = new HashMap<>();
        int extra = dfs(0, cnt);
        return base + extra;
    }

    private int dfs(int cur, int[] cnt) {
        long key = cur;
        for (int i = 1; i < B; i++) {
            key = (key << 5) | cnt[i];
        }
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int best = 0;
        for (int i = 1; i < B; i++) {
            if (cnt[i] == 0) continue;
            cnt[i]--;
            int nextCur = (cur + i) % B;
            int add = (cur == 0) ? 1 : 0;
            int val = add + dfs(nextCur, cnt);
            if (val > best) best = val;
            cnt[i]++;
        }
        memo.put(key, best);
        return best;
    }
}

