class Solution {
    public static int minimumAbsoluteSumDifference(int[] nums1, int[] nums2) {
        final long MOD = 1_000_000_007L;
        int n = nums1.length;
        int[] sortedVals = nums1.clone();
        Arrays.sort(sortedVals);
        long originalSum = 0;
        long maxGain = 0;
        for (int i = 0; i < n; ++i) {
            long diff = Math.abs((long) nums1[i] - nums2[i]);
            originalSum = (originalSum + diff) % MOD;
            int pos = lowerBound(sortedVals, nums2[i]);
            long best = diff;
            if (pos < n) {
                long cand = Math.abs((long) sortedVals[pos] - nums2[i]);
                if (cand < best) best = cand;
            }
            if (pos > 0) {
                long cand = Math.abs((long) sortedVals[pos - 1] - nums2[i]);
                if (cand < best) best = cand;
            }
            long gain = diff - best;
            if (gain > maxGain) maxGain = gain;
        }
        return (int) ((originalSum - maxGain + MOD) % MOD);
    }

    private static int lowerBound(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (arr[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    }
}

