class Solution {
    public static int minSideJumps(int[] obstacles) {
        int n = obstacles.length - 1;
        int INF = (int) 1e9;
        int[] dp = {1, 0, 1};
        for (int i = 1; i <= n; i++) {
            int blocked = obstacles[i] - 1;
            if (blocked >= 0) dp[blocked] = INF;
            int min = Math.min(dp[0], Math.min(dp[1], dp[2]));
            for (int lane = 0; lane < 3; lane++) {
                if (obstacles[i] == lane + 1) continue;
                dp[lane] = Math.min(dp[lane], 1 + min);
            }
        }
        return Math.min(dp[0], Math.min(dp[1], dp[2]));
    }
}

