class Solution {
    public int countDifferentSubsequenceGCDs(int[] nums) {
        int maxVal = 0;
        for (int v : nums) {
            if (v > maxVal) maxVal = v;
        }
        int[] freq = new int[maxVal + 1];
        for (int v : nums) {
            freq[v]++;
        }
        int count = 0;
        for (int g = 1; g <= maxVal; g++) {
            int curGcd = 0;
            for (int multiple = g; multiple <= maxVal; multiple += g) {
                if (freq[multiple] > 0) {
                    curGcd = gcd(curGcd, multiple);
                    if (curGcd == g) break;
                }
            }
            if (curGcd == g) {
                count++;
            }
        }
        return count;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

