class Solution {
    private static final long MOD = 1_000_000_007L;

    public int minOperations(String s) {
        int n = s.length();
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = powMod(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) {
            cnt[s.charAt(i) - 'a']++;
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int cur = s.charAt(i) - 'a';
            int remaining = n - i - 1;
            for (int c = 0; c < cur; c++) {
                if (cnt[c] == 0) continue;
                cnt[c]--;
                long ways = fact[remaining];
                for (int j = 0; j < 26; j++) {
                    ways = ways * invFact[cnt[j]] % MOD;
                }
                ans = (ans + ways) % MOD;
                cnt[c]++;
            }
            cnt[cur]--;
        }
        return (int) ans;
    }

    private long powMod(long a, long e) {
        long res = 1;
        long base = a % MOD;
        while (e > 0) {
            if ((e & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        return res;
    }
}

import java.util.*;

public class Solution {
    public static class MKAverage {
        private final int m;
        private final int k;
        private final Deque<Integer> queue;
        private final TreeMap<Integer, Integer> low;
        private final TreeMap<Integer, Integer> mid;
        private final TreeMap<Integer, Integer> high;
        private int lowSize;
        private int midSize;
        private int highSize;
        private long sumMid;

        public MKAverage(int m, int k) {
            this.m = m;
            this.k = k;
            this.queue = new ArrayDeque<>();
            this.low = new TreeMap<>();
            this.mid = new TreeMap<>();
            this.high = new TreeMap<>();
            this.lowSize = 0;
            this.midSize = 0;
            this.highSize = 0;
            this.sumMid = 0L;
        }

        public void addElement(int num) {
            queue.addLast(num);
            if (queue.size() <= m) {
                insertIntoMid(num);
                if (queue.size() == m) {
                    rebalance();
                }
            } else {
                int old = queue.pollFirst();
                deleteElement(old);
                insertIntoMid(num);
                rebalance();
            }
        }

        public int calculateMKAverage() {
            if (queue.size() < m) {
                return -1;
            }
            return (int) (sumMid / (m - 2 * k));
        }

        private void insertIntoMid(int val) {
            add(mid, val);
            midSize++;
            sumMid += val;
        }

        private void deleteElement(int val) {
            if (remove(low, val)) {
                lowSize--;
            } else if (remove(high, val)) {
                highSize--;
            } else {
                remove(mid, val);
                midSize--;
                sumMid -= val;
            }
        }

        private void rebalance() {
            while (lowSize < k) {
                int val = mid.firstKey();
                remove(mid, val);
                midSize--;
                sumMid -= val;
                add(low, val);
                lowSize++;
            }
            while (lowSize > k) {
                int val = low.lastKey();
                remove(low, val);
                lowSize--;
                add(mid, val);
                midSize++;
                sumMid += val;
            }
            while (highSize < k) {
                int val = mid.lastKey();
                remove(mid, val);
                midSize--;
                sumMid -= val;
                add(high, val);
                highSize++;
            }
            while (highSize > k) {
                int val = high.firstKey();
                remove(high, val);
                highSize--;
                add(mid, val);
                midSize++;
                sumMid += val;
            }
        }

        private void add(TreeMap<Integer, Integer> map, int val) {
            map.put(val, map.getOrDefault(val, 0) + 1);
        }

        private boolean remove(TreeMap<Integer, Integer> map, int val) {
            Integer cnt = map.get(val);
            if (cnt == null) {
                return false;
            }
            if (cnt == 1) {
                map.remove(val);
            } else {
                map.put(val, cnt - 1);
            }
            return true;
        }
    }
}

