public class Solution {
    public static int[] getMaximumXor(int[] nums, int maximumBit) {
        int mask = (1 << maximumBit) - 1;
        int totalXor = 0;
        for (int v : nums) {
            totalXor ^= v;
        }
        int n = nums.length;
        int[] answer = new int[n];
        for (int i = n - 1, j = 0; i >= 0; i--, j++) {
            answer[j] = mask ^ totalXor;
            totalXor ^= nums[i];
        }
        return answer;
    }
}

