class Solution {
    public static int maxIceCream(int[] costs, int coins) {
        int maxCost = 0;
        for (int c : costs) {
            if (c > maxCost) maxCost = c;
        }

        int[] freq = new int[maxCost + 1];
        for (int c : costs) {
            freq[c]++;
        }

        int bought = 0;
        int remaining = coins;

        for (int price = 1; price <= maxCost && remaining >= price; price++) {
            if (freq[price] == 0) continue;
            int affordable = remaining / price;
            int take = Math.min(freq[price], affordable);
            bought += take;
            remaining -= take * price;
        }

        return bought;
    }
}

