    public static int[] getOrder(int[][] tasks) {
        int n = tasks.length;
        int[][] tasksWithIdx = new int[n][3];
        for (int i = 0; i < n; i++) {
            tasksWithIdx[i][0] = tasks[i][0];
            tasksWithIdx[i][1] = tasks[i][1];
            tasksWithIdx[i][2] = i;
        }
        Arrays.sort(tasksWithIdx, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> heap = new ArrayList<>();
        Comparator<int[]> comp = (a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            return a[1] - b[1];
        };
        java.util.function.Consumer<int[]> heapPush = node -> {
            heap.add(node);
            int i = heap.size() - 1;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (comp.compare(heap.get(p), heap.get(i)) <= 0) break;
                int[] tmp = heap.get(p);
                heap.set(p, heap.get(i));
                heap.set(i, tmp);
                i = p;
            }
        };
        java.util.function.Supplier<int[]> heapPop = () -> {
            int[] top = heap.get(0);
            int lastIdx = heap.size() - 1;
            int[] last = heap.remove(lastIdx);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                int i = 0;
                while (true) {
                    int l = i * 2 + 1;
                    int r = i * 2 + 2;
                    int smallest = i;
                    if (l < heap.size() && comp.compare(heap.get(l), heap.get(smallest)) < 0) smallest = l;
                    if (r < heap.size() && comp.compare(heap.get(r), heap.get(smallest)) < 0) smallest = r;
                    if (smallest == i) break;
                    int[] tmp = heap.get(i);
                    heap.set(i, heap.get(smallest));
                    heap.set(smallest, tmp);
                    i = smallest;
                }
            }
            return top;
        };
        int[] result = new int[n];
        int time = 0, i = 0, resIdx = 0;
        while (resIdx < n) {
            while (i < n && tasksWithIdx[i][0] <= time) {
                heapPush.accept(new int[]{tasksWithIdx[i][1], tasksWithIdx[i][2]});
                i++;
            }
            if (!heap.isEmpty()) {
                int[] node = heapPop.get();
                int proc = node[0];
                int idx = node[1];
                time += proc;
                result[resIdx++] = idx;
            } else {
                time = tasksWithIdx[i][0];
            }
        }
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public static int maxFrequency(int[] nums, int k) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        Arrays.sort(nums);
        int left = 0;
        long windowSum = 0;
        int best = 1;
        for (int right = 0; right < nums.length; right++) {
            windowSum += nums[right];
            while ((long) nums[right] * (right - left + 1) - windowSum > k) {
                windowSum -= nums[left];
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

