class Solution {
    public static int maximumBuildingHeight(int n, int[][] restrictions) {
        List<int[]> list = new ArrayList<>();
        for (int[] r : restrictions) {
            list.add(new int[]{r[0], r[1]});
        }
        list.add(new int[]{1, 0});
        list.sort(Comparator.comparingInt(a -> a[0]));
        for (int i = 1; i < list.size(); i++) {
            int dist = list.get(i)[0] - list.get(i - 1)[0];
            int allowed = list.get(i - 1)[1] + dist;
            if (list.get(i)[1] > allowed) {
                list.get(i)[1] = allowed;
            }
        }
        for (int i = list.size() - 2; i >= 0; i--) {
            int dist = list.get(i + 1)[0] - list.get(i)[0];
            int allowed = list.get(i + 1)[1] + dist;
            if (list.get(i)[1] > allowed) {
                list.get(i)[1] = allowed;
            }
        }
        int answer = 0;
        for (int i = 0; i < list.size() - 1; i++) {
            int leftIdx = list.get(i)[0];
            int leftH = list.get(i)[1];
            int rightIdx = list.get(i + 1)[0];
            int rightH = list.get(i + 1)[1];
            int d = rightIdx - leftIdx;
            int diff = Math.abs(leftH - rightH);
            int localMax = Math.max(leftH, rightH) + (d - diff) / 2;
            if (localMax > answer) {
                answer = localMax;
            }
        }
        int lastIdx = list.get(list.size() - 1)[0];
        int lastH = list.get(list.size() - 1)[1];
        int tailMax = lastH + (n - lastIdx);
        if (tailMax > answer) {
            answer = tailMax;
        }
        return answer;
    }
}

