class Solution {
    public static int longestBeautifulSubstring(String word) {
        char[] vowels = {'a', 'e', 'i', 'o', 'u'};
        int maxLen = 0;
        int curLen = 0;
        int stage = -1;
        for (int i = 0; i < word.length(); i++) {
            char ch = word.charAt(i);
            if (stage >= 0 && ch == vowels[stage]) {
                curLen++;
            } else if (stage + 1 < 5 && ch == vowels[stage + 1]) {
                stage++;
                curLen++;
            } else {
                if (ch == 'a') {
                    stage = 0;
                    curLen = 1;
                } else {
                    stage = -1;
                    curLen = 0;
                }
            }
            if (stage == 4) {
                if (curLen > maxLen) maxLen = curLen;
            }
        }
        return maxLen;
    }
}

