public class Solution {
    public static SeatManagerObj SeatManager(int n) {
        return new SeatManagerObj(n);
    }

    static class SeatManagerObj {
        private final ArrayList<Integer> heap = new ArrayList<>();

        SeatManagerObj(int n) {
            for (int i = 1; i <= n; ++i) {
                heapPush(i);
            }
        }

        private void heapPush(int val) {
            heap.add(val);
            int i = heap.size() - 1;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (heap.get(p) <= heap.get(i)) break;
                int tmp = heap.get(p);
                heap.set(p, heap.get(i));
                heap.set(i, tmp);
                i = p;
            }
        }

        private int heapPop() {
            int min = heap.get(0);
            int last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                int i = 0;
                while (true) {
                    int l = i * 2 + 1;
                    int r = i * 2 + 2;
                    int smallest = i;
                    if (l < heap.size() && heap.get(l) < heap.get(smallest)) smallest = l;
                    if (r < heap.size() && heap.get(r) < heap.get(smallest)) smallest = r;
                    if (smallest == i) break;
                    int tmp = heap.get(i);
                    heap.set(i, heap.get(smallest));
                    heap.set(smallest, tmp);
                    i = smallest;
                }
            }
            return min;
        }

        public int reserve() {
            return heapPop();
        }

        public void release(int seatNumber) {
            heapPush(seatNumber);
        }
    }
}

