class Solution {
    public int[] closestRoom(int[][] rooms, int[][] queries) {
        int n = rooms.length;
        int k = queries.length;
        Room[] roomArr = new Room[n];
        for (int i = 0; i < n; i++) {
            roomArr[i] = new Room(rooms[i][0], rooms[i][1]);
        }
        Arrays.sort(roomArr, (a, b) -> b.size - a.size); // descending by size

        Query[] queryArr = new Query[k];
        for (int i = 0; i < k; i++) {
            queryArr[i] = new Query(queries[i][0], queries[i][1], i);
        }
        Arrays.sort(queryArr, (a, b) -> b.minSize - a.minSize); // descending by minSize

        TreeSet<Integer> ids = new TreeSet<>();
        int[] answer = new int[k];
        int idx = 0;
        for (Query q : queryArr) {
            while (idx < n && roomArr[idx].size >= q.minSize) {
                ids.add(roomArr[idx].id);
                idx++;
            }
            if (ids.isEmpty()) {
                answer[q.index] = -1;
                continue;
            }
            Integer floor = ids.floor(q.preferred);
            Integer ceil = ids.ceiling(q.preferred);
            int bestId = -1;
            long bestDiff = Long.MAX_VALUE;
            if (floor != null) {
                long diff = Math.abs((long) floor - q.preferred);
                bestId = floor;
                bestDiff = diff;
            }
            if (ceil != null) {
                long diff = Math.abs((long) ceil - q.preferred);
                if (diff < bestDiff || (diff == bestDiff && ceil < bestId)) {
                    bestId = ceil;
                    bestDiff = diff;
                }
            }
            answer[q.index] = bestId;
        }
        return answer;
    }

    private static class Room {
        int id;
        int size;
        Room(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    private static class Query {
        int preferred;
        int minSize;
        int index;
        Query(int preferred, int minSize, int index) {
            this.preferred = preferred;
            this.minSize = minSize;
            this.index = index;
        }
    }
}

