class Solution {
    public static int maximumPopulation(int[][] logs) {
        Map<Integer, Integer> diff = new HashMap<>();
        for (int i = 0; i < logs.length; i++) {
            int birth = logs[i][0];
            int death = logs[i][1];
            diff.put(birth, diff.getOrDefault(birth, 0) + 1);
            diff.put(death, diff.getOrDefault(death, 0) - 1);
        }
        List<Integer> years = new ArrayList<>(diff.keySet());
        Collections.sort(years);
        int cur = 0;
        int max = 0;
        int answer = 0;
        for (int i = 0; i < years.size(); i++) {
            int year = years.get(i);
            cur += diff.get(year);
            if (cur > max) {
                max = cur;
                answer = year;
            }
        }
        return answer;
    }
}

import java.math.BigInteger;

public class Solution {
    public boolean splitString(String s) {
        int n = s.length();
        for (int i = 1; i < n; i++) {
            BigInteger first = new BigInteger(s.substring(0, i));
            if (dfs(s, i, first)) {
                return true;
            }
        }
        return false;
    }

    private boolean dfs(String s, int idx, BigInteger prev) {
        if (idx == s.length()) {
            return true;
        }
        BigInteger next = prev.subtract(BigInteger.ONE);
        if (next.signum() < 0) {
            return false;
        }
        for (int i = idx + 1; i <= s.length(); i++) {
            BigInteger cur = new BigInteger(s.substring(idx, i));
            int cmp = cur.compareTo(next);
            if (cmp == 0) {
                if (dfs(s, i, next)) {
                    return true;
                }
            } else if (cmp > 0) {
                break;
            }
        }
        return false;
    }
}

