class Solution {
    public int getMinSwaps(String num, int k) {
        char[] original = num.toCharArray();
        char[] cur = original.clone();
        for (int i = 0; i < k; i++) {
            nextPermutation(cur);
        }
        char[] target = cur;
        List<Character> list = new ArrayList<>();
        for (char c : original) {
            list.add(c);
        }
        int swaps = 0;
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i) == target[i]) {
                continue;
            }
            int j = i + 1;
            while (j < list.size() && list.get(j) != target[i]) {
                j++;
            }
            while (j > i) {
                char temp = list.get(j);
                list.set(j, list.get(j - 1));
                list.set(j - 1, temp);
                swaps++;
                j--;
            }
        }
        return swaps;
    }

    private void nextPermutation(char[] a) {
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        int j = n - 1;
        while (a[j] <= a[i]) {
            j--;
        }
        char tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        int l = i + 1, r = n - 1;
        while (l < r) {
            char t = a[l];
            a[l] = a[r];
            a[r] = t;
            l++;
            r--;
        }
    }
}

