class Solution {
    private static class Node {
        int size;
        int right;
        Node(int size, int right) {
            this.size = size;
            this.right = right;
        }
    }

    public static int[] minInterval(int[][] intervals, int[] queries) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        int n = queries.length;
        int[][] qs = new int[n][2];
        for (int i = 0; i < n; i++) {
            qs[i][0] = queries[i];
            qs[i][1] = i;
        }
        Arrays.sort(qs, (a, b) -> Integer.compare(a[0], b[0]));
        int[] res = new int[n];
        Arrays.fill(res, -1);
        PriorityQueue<Node> heap = new PriorityQueue<>(Comparator.comparingInt(node -> node.size));
        int i = 0;
        for (int[] qIdx : qs) {
            int q = qIdx[0];
            int idx = qIdx[1];
            while (i < intervals.length && intervals[i][0] <= q) {
                int left = intervals[i][0];
                int right = intervals[i][1];
                heap.offer(new Node(right - left + 1, right));
                i++;
            }
            while (!heap.isEmpty() && heap.peek().right < q) {
                heap.poll();
            }
            if (!heap.isEmpty()) {
                res[idx] = heap.peek().size;
            }
        }
        return res;
    }
}

