class Solution {
    public int largestPathValue(String colors, int[][] edges) {
        int n = colors.length();
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        int[] indegree = new int[n];
        for (int[] e : edges) {
            int from = e[0];
            int to = e[1];
            graph[from].add(to);
            indegree[to]++;
        }
        int[][] dp = new int[n][26];
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) queue.add(i);
        }
        int visited = 0;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            visited++;
            int colU = colors.charAt(u) - 'a';
            dp[u][colU] = Math.max(dp[u][colU], 1);
            for (int v : graph[u]) {
                for (int c = 0; c < 26; c++) {
                    int add = (colors.charAt(v) - 'a' == c) ? 1 : 0;
                    dp[v][c] = Math.max(dp[v][c], dp[u][c] + add);
                }
                indegree[v]--;
                if (indegree[v] == 0) queue.add(v);
            }
        }
        if (visited < n) return -1;
        int answer = 0;
        for (int i = 0; i < n; i++) {
            for (int c = 0; c < 26; c++) {
                answer = Math.max(answer, dp[i][c]);
            }
        }
        return answer;
    }
}

