import java.util.ArrayDeque;
import java.util.Deque;
import java.math.BigInteger;

class Solution {
    public static int maxSumMinProduct(int[] nums) {
        int n = nums.length;
        BigInteger MOD = new BigInteger("1000000007");
        BigInteger[] prefix = new BigInteger[n + 1];
        prefix[0] = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i].add(BigInteger.valueOf(nums[i]));
        }
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peekLast()] >= nums[i]) {
                stack.removeLast();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peekLast();
            stack.addLast(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peekLast()] >= nums[i]) {
                stack.removeLast();
            }
            right[i] = stack.isEmpty() ? n : stack.peekLast();
            stack.addLast(i);
        }
        BigInteger maxProd = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            int l = left[i];
            int r = right[i];
            BigInteger subSum = prefix[r].subtract(prefix[l + 1]);
            BigInteger prod = BigInteger.valueOf(nums[i]).multiply(subSum);
            if (prod.compareTo(maxProd) > 0) {
                maxProd = prod;
            }
        }
        return maxProd.mod(MOD).intValue();
    }
}

