class Solution {
    public static int[] incrementalMemoryLeak(int memory1, int memory2) {
        int time = 1;
        while (true) {
            boolean useFirst = memory1 >= memory2;
            if (useFirst ? memory1 < time : memory2 < time) break;
            if (useFirst) {
                memory1 -= time;
            } else {
                memory2 -= time;
            }
            time++;
        }
        return new int[]{time, memory1, memory2};
    }
}

