class Solution {
    public static PairFinder FindSumPairs(int[] nums1, int[] nums2) {
        return new PairFinder(nums1, nums2);
    }

    public static class PairFinder {
        private final int[] nums1;
        private final int[] nums2;
        private final Map<Integer, Integer> freq;

        public PairFinder(int[] nums1, int[] nums2) {
            this.nums1 = nums1;
            this.nums2 = nums2;
            this.freq = new HashMap<>();
            for (int v : nums2) {
                freq.put(v, freq.getOrDefault(v, 0) + 1);
            }
        }

        public void add(int index, int val) {
            int oldVal = nums2[index];
            int newVal = oldVal + val;
            int oldCount = freq.get(oldVal);
            if (oldCount == 1) {
                freq.remove(oldVal);
            } else {
                freq.put(oldVal, oldCount - 1);
            }
            freq.put(newVal, freq.getOrDefault(newVal, 0) + 1);
            nums2[index] = newVal;
        }

        public int count(int tot) {
            int totalPairs = 0;
            for (int x : nums1) {
                totalPairs += freq.getOrDefault(tot - x, 0);
            }
            return totalPairs;
        }
    }
}

