public class Solution {
    public static char[][] rotateTheBox(char[][] boxGrid) {
        int m = boxGrid.length;
        int n = boxGrid[0].length;
        for (int i = 0; i < m; i++) {
            int emptyPos = n - 1;
            for (int j = n - 1; j >= 0; j--) {
                char cell = boxGrid[i][j];
                if (cell == '*') {
                    emptyPos = j - 1;
                } else if (cell == '#') {
                    if (emptyPos != j) {
                        boxGrid[i][emptyPos] = '#';
                        boxGrid[i][j] = '.';
                    }
                    emptyPos--;
                }
            }
        }
        char[][] rotated = new char[n][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rotated[j][m - 1 - i] = boxGrid[i][j];
            }
        }
        return rotated;
    }
}

import java.math.BigInteger;

class Solution {
    public static long sumOfFlooredPairs(int[] nums) {
        int maxVal = 0;
        for (int v : nums) {
            if (v > maxVal) maxVal = v;
        }
        int[] cnt = new int[maxVal + 1];
        for (int v : nums) {
            cnt[v]++;
        }
        int[] pref = new int[maxVal + 1];
        for (int i = 1; i <= maxVal; i++) {
            pref[i] = pref[i - 1] + cnt[i];
        }
        BigInteger answer = BigInteger.ZERO;
        for (int d = 1; d <= maxVal; d++) {
            if (cnt[d] == 0) continue;
            BigInteger freqDen = BigInteger.valueOf(cnt[d]);
            for (int k = 1; k * d <= maxVal; k++) {
                int left = k * d;
                int right = Math.min((k + 1) * d - 1, maxVal);
                int rangeCount = pref[right] - pref[left - 1];
                if (rangeCount == 0) continue;
                BigInteger contrib = freqDen.multiply(BigInteger.valueOf(k)).multiply(BigInteger.valueOf(rangeCount));
                answer = answer.add(contrib);
            }
        }
        return answer.longValue();
    }
}

