class Solution {
    public static int minSwapsAlternating(String s) {
        int n = s.length();
        int zeros = 0, ones = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') zeros++;
            else ones++;
        }
        if (Math.abs(zeros - ones) > 1) return -1;
        if (n % 2 == 0 && zeros != ones) return -1;
        int mismatchesStart0 = 0;
        int mismatchesStart1 = 0;
        for (int i = 0; i < n; i++) {
            char expected0 = (i % 2 == 0) ? '0' : '1';
            char expected1 = (i % 2 == 0) ? '1' : '0';
            if (s.charAt(i) != expected0) mismatchesStart0++;
            if (s.charAt(i) != expected1) mismatchesStart1++;
        }
        if (n % 2 == 0) {
            return Math.min(mismatchesStart0, mismatchesStart1) / 2;
        } else {
            if (zeros > ones) return mismatchesStart0 / 2;
            else return mismatchesStart1 / 2;
        }
    }
}

public class Solution {
    public static boolean longerOnesThanZeros(String s) {
        int maxOnes = 0;
        int maxZeros = 0;
        char currentChar = '\0';
        int currentLen = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == currentChar) {
                currentLen++;
            } else {
                if (currentChar == '1') {
                    maxOnes = Math.max(maxOnes, currentLen);
                } else if (currentChar == '0') {
                    maxZeros = Math.max(maxZeros, currentLen);
                }
                currentChar = ch;
                currentLen = 1;
            }
        }
        if (currentChar == '1') {
            maxOnes = Math.max(maxOnes, currentLen);
        } else if (currentChar == '0') {
            maxZeros = Math.max(maxZeros, currentLen);
        }
        return maxOnes > maxZeros;
    }
}

