class Solution {
    public static long rearrangeSticks(int n, int k) {
        final long MOD = 1_000_000_007L;
        if (k > n) return 0L;
        long[] dp = new long[k + 1];
        dp[0] = 1L;
        for (int i = 1; i <= n; i++) {
            long[] ndp = new long[k + 1];
            int limit = Math.min(i, k);
            for (int j = 1; j <= limit; j++) {
                ndp[j] = (dp[j - 1] + (long) (i - 1) * dp[j]) % MOD;
            }
            dp = ndp;
        }
        return dp[k];
    }
}

