class Solution {
    public static int minSpeedOnTime(int[] dist, double hour) {
        int n = dist.length;
        if (hour <= n - 1) return -1;
        int MAX_SPEED = 10000000;
        int low = 1, high = MAX_SPEED;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (isFeasible(mid, dist, hour)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return isFeasible(low, dist, hour) ? low : -1;
    }

    private static boolean isFeasible(int v, int[] dist, double hour) {
        double total = 0;
        int n = dist.length;
        for (int i = 0; i < n - 1; i++) {
            total += Math.ceil((double) dist[i] / v);
        }
        total += (double) dist[n - 1] / v;
        return total <= hour;
    }
}

