public class Solution {
    public int[] getBiggestThree(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] diag1 = new long[m][n];
        long[][] diag2 = new long[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                diag1[i][j] = grid[i][j];
                if (i > 0 && j > 0) diag1[i][j] += diag1[i - 1][j - 1];
                diag2[i][j] = grid[i][j];
                if (i > 0 && j + 1 < n) diag2[i][j] += diag2[i - 1][j + 1];
            }
        }
        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                set.add(grid[i][j]); // size 0 rhombus
                for (int k = 1; i + 2 * k < m && j - k >= 0 && j + k < n; k++) {
                    int top = grid[i][j];
                    int right = grid[i + k][j + k];
                    int bottom = grid[i + 2 * k][j];
                    int left = grid[i + k][j - k];
                    long sum1 = getDiag1Sum(diag1, i, j, i + k, j + k);
                    long sum2 = getDiag2Sum(diag2, i + k, j + k, i + 2 * k, j);
                    long sum3 = getDiag1Sum(diag1, i + k, j - k, i + 2 * k, j);
                    long sum4 = getDiag2Sum(diag2, i, j, i + k, j - k);
                    long total = sum1 + sum2 + sum3 + sum4 - top - right - bottom - left;
                    set.add((int) total);
                }
            }
        }
        List<Integer> list = new ArrayList<>(set);
        list.sort(Collections.reverseOrder());
        int size = Math.min(3, list.size());
        int[] ans = new int[size];
        for (int i = 0; i < size; i++) ans[i] = list.get(i);
        return ans;
    }

    private long getDiag1Sum(long[][] diag1, int x1, int y1, int x2, int y2) {
        long res = diag1[x2][y2];
        if (x1 > 0 && y1 > 0) res -= diag1[x1 - 1][y1 - 1];
        return res;
    }

    private long getDiag2Sum(long[][] diag2, int x1, int y1, int x2, int y2) {
        long res = diag2[x2][y2];
        if (x1 > 0 && y1 + 1 < diag2[0].length) res -= diag2[x1 - 1][y1 + 1];
        return res;
    }
}

