class Solution {
    public long stoneGameVIII(int[] stones) {
        int n = stones.length;
        long[] pref = new long[n];
        pref[0] = stones[0];
        for (int i = 1; i < n; i++) {
            pref[i] = pref[i - 1] + stones[i];
        }
        long maxVal = Long.MIN_VALUE;
        long curBest = 0; // best value for position i+1
        for (int i = n - 2; i >= 0; i--) {
            long candidate = pref[i + 1] - curBest;
            if (candidate > maxVal) {
                maxVal = candidate;
            }
            curBest = maxVal;
        }
        return curBest;
    }
}

