class Solution {
    public int minSkips(int[] dist, int speed, int hoursBefore) {
        int n = dist.length;
        double INF = 1e18;
        double[] dpPrev = new double[n + 1];
        Arrays.fill(dpPrev, INF);
        dpPrev[0] = 0.0;
        for (int i = 0; i < n; i++) {
            double[] cur = new double[n + 1];
            Arrays.fill(cur, INF);
            double travel = (double) dist[i] / speed;
            for (int j = 0; j <= i; j++) {
                if (dpPrev[j] >= INF) continue;
                double base = dpPrev[j];
                if (i == n - 1) {
                    // last road, just add travel time
                    cur[j] = Math.min(cur[j], base + travel);
                } else {
                    // not skipping this rest
                    double timeNoSkip = Math.ceil(base + travel);
                    cur[j] = Math.min(cur[j], timeNoSkip);
                    // skipping this rest
                    cur[j + 1] = Math.min(cur[j + 1], base + travel);
                }
            }
            dpPrev = cur;
        }
        for (int j = 0; j <= n; j++) {
            if (dpPrev[j] <= hoursBefore + 1e-9) {
                return j;
            }
        }
        return -1;
    }
}

import java.util.Arrays;

class Solution {
    public static int minimumXORSum(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int totalMask = 1 << n;
        int INF = Integer.MAX_VALUE;
        int[] dp = new int[totalMask];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 1; mask < totalMask; mask++) {
            int i = popcount(mask) - 1;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) {
                    int prev = mask ^ (1 << j);
                    if (dp[prev] != INF) {
                        int candidate = dp[prev] + (nums1[i] ^ nums2[j]);
                        if (candidate < dp[mask]) dp[mask] = candidate;
                    }
                }
            }
        }
        return dp[totalMask - 1];
    }

    private static int popcount(int x) {
        int cnt = 0;
        while (x != 0) {
            x &= x - 1;
            cnt++;
        }
        return cnt;
    }
}

