class Solution {
    public int minFlips(String s) {
        int n = s.length();
        String ss = s + s;
        int len = 2 * n;
        int[] diff0 = new int[len];
        int[] diff1 = new int[len];
        for (int i = 0; i < len; i++) {
            char c = ss.charAt(i);
            char expected0 = (i % 2 == 0) ? '0' : '1';
            char expected1 = (i % 2 == 0) ? '1' : '0';
            diff0[i] = (c != expected0) ? 1 : 0;
            diff1[i] = (c != expected1) ? 1 : 0;
        }
        int sum0 = 0, sum1 = 0;
        for (int i = 0; i < n; i++) {
            sum0 += diff0[i];
            sum1 += diff1[i];
        }
        int ans = Math.min(sum0, sum1);
        for (int i = 1; i < n; i++) {
            sum0 = sum0 - diff0[i - 1] + diff0[i + n - 1];
            sum1 = sum1 - diff1[i - 1] + diff1[i + n - 1];
            ans = Math.min(ans, Math.min(sum0, sum1));
        }
        return ans;
    }
}

