public class Solution {
    public static boolean canBeRotated(int[][] mat, int[][] target) {
        int n = mat.length;
        int[][] cur = mat;
        for (int k = 0; k < 4; k++) {
            if (equal(cur, target, n)) {
                return true;
            }
            cur = rotate(cur, n);
        }
        return false;
    }

    private static boolean equal(int[][] a, int[][] b, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] != b[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static int[][] rotate(int[][] a, int n) {
        int[][] res = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                res[j][n - 1 - i] = a[i][j];
            }
        }
        return res;
    }
}

