class Solution {
    public static boolean isCovered(int[][] ranges, int left, int right) {
        int maxCoord = right;
        for (int[] range : ranges) {
            int e = range[1];
            if (e > maxCoord) {
                maxCoord = e;
            }
        }
        int[] diff = new int[maxCoord + 2];
        for (int[] range : ranges) {
            int s = range[0];
            int e = range[1];
            diff[s] += 1;
            diff[e + 1] -= 1;
        }
        int cur = 0;
        for (int i = 0; i <= maxCoord; i++) {
            cur += diff[i];
            if (i >= left && i <= right && cur == 0) {
                return false;
            }
        }
        return true;
    }
}

