class Solution {
    public static int findStudent(int[] chalk, long k) {
        int n = chalk.length;
        long[] prefix = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += chalk[i];
            prefix[i] = total;
        }
        k = k % total;
        int left = 0, right = n - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            if (prefix[mid] > k) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

