class Solution {
    public int largestMagicSquare(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] rowPref = new int[m][n + 1];
        int[][] colPref = new int[m + 1][n];
        int[][] diag1 = new int[m + 1][n + 1];
        int[][] diag2 = new int[m + 1][n + 1];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
                colPref[i + 1][j] = colPref[i][j] + grid[i][j];
                diag1[i + 1][j + 1] = diag1[i][j] + grid[i][j];
            }
        }
        for (int i = 0; i < m; i++) {
            for (int j = n - 1; j >= 0; j--) {
                diag2[i + 1][j] = diag2[i][j + 1] + grid[i][j];
            }
        }

        int maxK = Math.min(m, n);
        for (int k = maxK; k >= 1; k--) {
            for (int i = 0; i + k <= m; i++) {
                for (int j = 0; j + k <= n; j++) {
                    long target = rowPref[i][j + k] - rowPref[i][j];
                    boolean ok = true;
                    for (int r = i; r < i + k && ok; r++) {
                        long sum = rowPref[r][j + k] - rowPref[r][j];
                        if (sum != target) ok = false;
                    }
                    for (int c = j; c < j + k && ok; c++) {
                        long sum = colPref[i + k][c] - colPref[i][c];
                        if (sum != target) ok = false;
                    }
                    if (ok) {
                        long sum = diag1[i + k][j + k] - diag1[i][j];
                        if (sum != target) ok = false;
                    }
                    if (ok) {
                        long sum = diag2[i + k][j] - diag2[i][j + k];
                        if (sum != target) ok = false;
                    }
                    if (ok) return k;
                }
            }
        }
        return 1;
    }
}

public class Solution {
