class Solution {
    public static int maximumRemovals(String s, String p, int[] removable) {
        int n = s.length();

        java.util.function.IntPredicate canRemove = (int k) -> {
            boolean[] deleted = new boolean[n];
            for (int i = 0; i < k; i++) {
                deleted[removable[i]] = true;
            }
            int j = 0;
            for (int i = 0; i < n && j < p.length(); i++) {
                if (!deleted[i] && s.charAt(i) == p.charAt(j)) {
                    j++;
                }
            }
            return j == p.length();
        };

        int low = 0, high = removable.length, ans = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (canRemove.test(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public int minCost(String expression) {
        Deque<long[]> valStack = new ArrayDeque<>();
        Deque<Character> opStack = new ArrayDeque<>();

        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);
            if (c == '0' || c == '1') {
                long[] pair = new long[2];
                if (c == '0') {
                    pair[0] = 0; // already 0
                    pair[1] = 1; // flip to 1
                } else {
                    pair[0] = 1; // flip to 0
                    pair[1] = 0; // already 1
                }
                valStack.push(pair);
            } else if (c == '(') {
                opStack.push(c);
            } else if (c == ')') {
                while (opStack.peek() != '(') {
                    char op = opStack.pop();
                    long[] right = valStack.pop();
                    long[] left = valStack.pop();
                    valStack.push(combine(left, right, op));
                }
                opStack.pop(); // remove '('
            } else if (c == '&' || c == '|') {
                while (!opStack.isEmpty() && opStack.peek() != '(') {
                    char op = opStack.pop();
                    long[] right = valStack.pop();
                    long[] left = valStack.pop();
                    valStack.push(combine(left, right, op));
                }
                opStack.push(c);
            }
        }

        while (!opStack.isEmpty()) {
            char op = opStack.pop();
            long[] right = valStack.pop();
            long[] left = valStack.pop();
            valStack.push(combine(left, right, op));
        }

        long[] finalPair = valStack.pop();
        // Determine original value (cost 0)
        int original = finalPair[0] == 0 ? 0 : 1;
        int answer = original == 0 ? (int) finalPair[1] : (int) finalPair[0];
        return answer;
    }

    private static long[] combine(long[] left, long[] right, char op) {
        long INF = 1_000_000_000L;
        long[] keep = new long[2];
        long[] flip = new long[2];

        // keep operator
        if (op == '&') {
            // result 0
            long a0 = left[0] + Math.min(right[0], right[1]);
            long b0 = right[0] + Math.min(left[0], left[1]);
            keep[0] = Math.min(a0, b0);
            // result 1
            keep[1] = left[1] + right[1];
        } else { // '|'
            // result 0
            keep[0] = left[0] + right[0];
            // result 1
            long a1 = left[1] + Math.min(right[0], right[1]);
            long b1 = right[1] + Math.min(left[0], left[1]);
            keep[1] = Math.min(a1, b1);
        }

        // flip operator (cost +1)
        char flipped = (op == '&') ? '|' : '&';
        if (flipped == '&') {
            long a0 = left[0] + Math.min(right[0], right[1]);
            long b0 = right[0] + Math.min(left[0], left[1]);
            flip[0] = Math.min(a0, b0);
            flip[1] = left[1] + right[1];
        } else {
            flip[0] = left[0] + right[0];
            long a1 = left[1] + Math.min(right[0], right[1]);
            long b1 = right[1] + Math.min(left[0], left[1]);
            flip[1] = Math.min(a1, b1);
        }
        flip[0] += 1;
        flip[1] += 1;

        long[] res = new long[2];
        res[0] = Math.min(keep[0], flip[0]);
        res[1] = Math.min(keep[1], flip[1]);
        return res;
    }
}

