class Solution {
    public static int numberOfFullRounds(String loginTime, String logoutTime) {
        int start = toMinutes(loginTime);
        int end = toMinutes(logoutTime);
        if (end < start) end += 24 * 60;
        int roundStart = (int) Math.ceil(start / 15.0) * 15;
        int roundEnd = (int) Math.floor(end / 15.0) * 15;
        if (roundStart >= roundEnd) return 0;
        return (roundEnd - roundStart) / 15;
    }

    private static int toMinutes(String t) {
        String[] parts = t.split(":");
        int h = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        return h * 60 + m;
    }
}

