class Solution {
    public static int[] minimumAbsoluteDifferenceQueries(int[] nums, int[][] queries) {
        int[] result = new int[queries.length];
        for (int qi = 0; qi < queries.length; ++qi) {
            int l = queries[qi][0];
            int r = queries[qi][1];
            int[] sub = Arrays.copyOfRange(nums, l, r + 1);
            Arrays.sort(sub);
            int minDiff = Integer.MAX_VALUE;
            for (int i = 1; i < sub.length; ++i) {
                int diff = sub[i] - sub[i - 1];
                if (diff == 0) {
                    continue;
                }
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
            result[qi] = (minDiff == Integer.MAX_VALUE) ? -1 : minDiff;
        }
        return result;
    }
}

class Solution {
    Map<Long, int[]> memo = new HashMap<>();

    long key(int l, int r, int n) {
        return ((long) l * 40 + r) * 40 + n;
    }

    int[] dfs(int l, int r, int n) {
        if (l + r == n - 1) return new int[]{1, 1};
        long k = key(l, r, n);
        if (memo.containsKey(k)) return memo.get(k);
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        int m = n >> 1;
        for (int i = 0; i < (1 << m); i++) {
            boolean[] win = new boolean[n];
            for (int j = 0; j < m; j++) {
                if (((i >> j) & 1) != 0) win[j] = true;
                else win[n-1-j] = true;
            }
            if ((n & 1) != 0) win[m] = true;
            win[n-1-l] = false;
            win[n-1-r] = false;
            win[l] = true;
            win[r] = true;
            int a = 0, b = 0, c = 0;
            for (int j = 0; j < n; j++) {
                if (j == l) a = c;
                if (j == r) b = c;
                if (win[j]) c++;
            }
            int[] res = dfs(a, b, c);
            mn = Math.min(mn, res[0] + 1);
            mx = Math.max(mx, res[1] + 1);
        }
        int[] result = new int[]{mn, mx};
        memo.put(k, result);
        return result;
    }

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo.clear();
        return dfs(firstPlayer-1, secondPlayer-1, n);
    }
}

