class Solution {
    public static int[] findPeakGrid(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int top = 0, bottom = m - 1;
        while (top <= bottom) {
            int mid = (top + bottom) / 2;
            int maxCol = 0;
            for (int j = 1; j < n; j++) {
                if (mat[mid][j] > mat[mid][maxCol]) {
                    maxCol = j;
                }
            }
            int up = (mid > 0) ? mat[mid - 1][maxCol] : Integer.MIN_VALUE;
            int down = (mid < m - 1) ? mat[mid + 1][maxCol] : Integer.MIN_VALUE;
            if (mat[mid][maxCol] > up && mat[mid][maxCol] > down) {
                return new int[]{mid, maxCol};
            }
            if (up > mat[mid][maxCol]) {
                bottom = mid - 1;
            } else {
                top = mid + 1;
            }
        }
        return new int[]{-1, -1};
    }
}

