class Solution {
    public static long maxAlternatingSum(int[] nums) {
        long even = 0;
        long odd = Long.MIN_VALUE;
        for (int num : nums) {
            long x = num;
            long candidateEven = x;
            if (odd != Long.MIN_VALUE) {
                candidateEven = Math.max(candidateEven, odd + x);
            }
            long newEven = Math.max(even, candidateEven);
            long newOdd = Math.max(odd, even - x);
            even = newEven;
            odd = newOdd;
        }
        return even;
    }
}

public class Solution {
    public static int countSubIslands(int[][] grid1, int[][] grid2) {
        int rows = grid1.length;
        int cols = grid1[0].length;
        int subIslandCount = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid2[r][c] == 1) {
                    if (dfs(r, c, rows, cols, grid1, grid2)) {
                        subIslandCount++;
                    }
                }
            }
        }
        return subIslandCount;
    }

    private static boolean dfs(int r, int c, int rows, int cols, int[][] grid1, int[][] grid2) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid2[r][c] == 0) {
            return true;
        }
        grid2[r][c] = 0;
        boolean isSub = grid1[r][c] == 1;
        boolean up = dfs(r - 1, c, rows, cols, grid1, grid2);
        boolean down = dfs(r + 1, c, rows, cols, grid1, grid2);
        boolean left = dfs(r, c - 1, rows, cols, grid1, grid2);
        boolean right = dfs(r, c + 1, rows, cols, grid1, grid2);
        return isSub && up && down && left && right;
    }
}

