class Solution {
    public static String removeOccurrences(String s, String part) {
        int m = part.length();
        char[] stack = new char[s.length()];
        int top = -1;
        for (int i = 0; i < s.length(); i++) {
            stack[++top] = s.charAt(i);
            if (top + 1 >= m) {
                boolean match = true;
                for (int j = 0; j < m; j++) {
                    if (stack[top - m + 1 + j] != part.charAt(j)) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    top -= m;
                }
            }
        }
        return new String(stack, 0, top + 1);
    }
}

