class Solution {
    public static boolean canBeIncreasing(int[] nums) {
        int violationIdx = -1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] <= nums[i - 1]) {
                if (violationIdx != -1) return false;
                violationIdx = i;
            }
        }
        if (violationIdx == -1) return true;
        int i = violationIdx;
        boolean canRemovePrev = i == 1 || nums[i] > nums[i - 2];
        boolean canRemoveCurr = i == nums.length - 1 || nums[i + 1] > nums[i - 1];
        return canRemovePrev || canRemoveCurr;
    }
}

