class Solution {
    public static int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = Math.min(m, n) / 2;
        for (int layer = 0; layer < layers; layer++) {
            int top = layer;
            int bottom = m - 1 - layer;
            int left = layer;
            int right = n - 1 - layer;
            List<Integer> elems = new ArrayList<>();
            for (int c = left; c <= right; c++) elems.add(grid[top][c]);
            for (int r = top + 1; r <= bottom; r++) elems.add(grid[r][right]);
            for (int c = right - 1; c >= left; c--) elems.add(grid[bottom][c]);
            for (int r = bottom - 1; r > top; r--) elems.add(grid[r][left]);
            int len = elems.size();
            int rot = k % len;
            List<Integer> rotated = new ArrayList<>(len);
            for (int i = rot; i < len; i++) rotated.add(elems.get(i));
            for (int i = 0; i < rot; i++) rotated.add(elems.get(i));
            int idx = 0;
            for (int c = left; c <= right; c++) grid[top][c] = rotated.get(idx++);
            for (int r = top + 1; r <= bottom; r++) grid[r][right] = rotated.get(idx++);
            for (int c = right - 1; c >= left; c--) grid[bottom][c] = rotated.get(idx++);
            for (int r = bottom - 1; r > top; r--) grid[r][left] = rotated.get(idx++);
        }
        return grid;
    }
}

