class MovieRentingSystem {
    private static class Copy {
        int shop;
        int movie;
        int price;
        Copy(int shop, int movie, int price) {
            this.shop = shop;
            this.movie = movie;
            this.price = price;
        }
    }

    private final Map<Long, Integer> priceMap = new HashMap<>();
    private final Map<Integer, TreeSet<Copy>> available = new HashMap<>();
    private final TreeSet<Copy> rented;

    public MovieRentingSystem(int n, int[][] entries) {
        Comparator<Copy> rentedComp = Comparator
                .comparingInt((Copy c) -> c.price)
                .thenComparingInt(c -> c.shop)
                .thenComparingInt(c -> c.movie);
        rented = new TreeSet<>(rentedComp);

        for (int[] e : entries) {
            int shop = e[0];
            int movie = e[1];
            int price = e[2];
            long key = ((long) shop << 32) | (movie & 0xffffffffL);
            priceMap.put(key, price);
            Copy copy = new Copy(shop, movie, price);
            available.computeIfAbsent(movie, k -> new TreeSet<>(Comparator
                    .comparingInt((Copy c) -> c.price)
                    .thenComparingInt(c -> c.shop)))
                    .add(copy);
        }
    }

    public List<Integer> search(int movie) {
        List<Integer> res = new ArrayList<>();
        TreeSet<Copy> set = available.get(movie);
        if (set == null) return res;
        Iterator<Copy> it = set.iterator();
        while (it.hasNext() && res.size() < 5) {
            res.add(it.next().shop);
        }
        return res;
    }

    public void rent(int shop, int movie) {
        long key = ((long) shop << 32) | (movie & 0xffffffffL);
        int price = priceMap.get(key);
        Copy copy = new Copy(shop, movie, price);
        TreeSet<Copy> set = available.get(movie);
        if (set != null) {
            set.remove(copy);
        }
        rented.add(copy);
    }

    public void drop(int shop, int movie) {
        long key = ((long) shop << 32) | (movie & 0xffffffffL);
        int price = priceMap.get(key);
        Copy copy = new Copy(shop, movie, price);
        rented.remove(copy);
        available.computeIfAbsent(movie, k -> new TreeSet<>(Comparator
                .comparingInt((Copy c) -> c.price)
                .thenComparingInt(c -> c.shop)))
                .add(copy);
    }

    public List<List<Integer>> report() {
        List<List<Integer>> res = new ArrayList<>();
        Iterator<Copy> it = rented.iterator();
        while (it.hasNext() && res.size() < 5) {
            Copy c = it.next();
            List<Integer> pair = new ArrayList<>(2);
            pair.add(c.shop);
            pair.add(c.movie);
            res.add(pair);
        }
        return res;
    }
}

