class Solution {
    public static int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        int[] deadline = new int[n];
        for (int i = 0; i < n; i++) {
            deadline[i] = (dist[i] + speed[i] - 1) / speed[i];
        }
        Arrays.sort(deadline);
        int killed = 0;
        while (killed < n && killed < deadline[killed]) {
            killed++;
        }
        return killed;
    }
