class Solution {
    private static final int MOD = 1_000_000_007;

    public int countOrders(int[] prevRoom) {
        int n = prevRoom.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            int p = prevRoom[i];
            children[p].add(i);
        }

        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        int[] order = new int[n];
        int idx = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int u = stack.pop();
            order[idx++] = u;
            for (int v : children[u]) {
                stack.push(v);
            }
        }

        int[] size = new int[n];
        long[] ways = new long[n];
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int total = 0;
            long w = 1;
            for (int v : children[u]) {
                total += size[v];
                w = w * ways[v] % MOD;
            }
            w = w * fact[total] % MOD;
            for (int v : children[u]) {
                w = w * invFact[size[v]] % MOD;
            }
            size[u] = total + 1;
            ways[u] = w;
        }
        return (int) ways[0];
    }

    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = res * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }
}

