class Solution {
    private static final int MOD1 = 1_000_000_007;
    private static final int MOD2 = 1_000_000_009;
    private static final int BASE = 100_007;

    public int longestCommonSubpath(int n, int[][] paths) {
        int m = paths.length;
        int[] lens = new int[m];
        int maxLen = 0;
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            lens[i] = paths[i].length;
            maxLen = Math.max(maxLen, lens[i]);
            minLen = Math.min(minLen, lens[i]);
        }
        if (minLen == 0) return 0;

        int[] pow1 = new int[maxLen + 1];
        int[] pow2 = new int[maxLen + 1];
        pow1[0] = 1;
        pow2[0] = 1;
        for (int i = 1; i <= maxLen; i++) {
            pow1[i] = (int) ((long) pow1[i - 1] * BASE % MOD1);
            pow2[i] = (int) ((long) pow2[i - 1] * BASE % MOD2);
        }

        int[][] pref1 = new int[m][];
        int[][] pref2 = new int[m][];
        for (int i = 0; i < m; i++) {
            int len = lens[i];
            pref1[i] = new int[len + 1];
            pref2[i] = new int[len + 1];
            for (int j = 0; j < len; j++) {
                pref1[i][j + 1] = (int) (((long) pref1[i][j] * BASE + paths[i][j]) % MOD1);
                pref2[i][j + 1] = (int) (((long) pref2[i][j] * BASE + paths[i][j]) % MOD2);
            }
        }

        int low = 0, high = minLen;
        while (low < high) {
            int mid = (low + high + 1) >>> 1;
            if (existsCommon(mid, pref1, pref2, pow1, pow2, lens)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private boolean existsCommon(int L, int[][] pref1, int[][] pref2, int[] pow1, int[] pow2, int[] lens) {
        if (L == 0) return true;
        Set<Long> common = null;
        for (int i = 0; i < pref1.length; i++) {
            int len = lens[i];
            if (len < L) return false;
            Set<Long> cur = new HashSet<>();
            for (int start = 0; start + L <= len; start++) {
                int h1 = subHash(pref1[i], start, start + L, pow1, MOD1);
                int h2 = subHash(pref2[i], start, start + L, pow2, MOD2);
                long key = ((long) h1 << 32) ^ (h2 & 0xffffffffL);
                cur.add(key);
            }
            if (common == null) {
                common = cur;
            } else {
                common.retainAll(cur);
                if (common.isEmpty()) return false;
            }
        }
        return common != null && !common.isEmpty();
    }

    private int subHash(int[] pref, int l, int r, int[] pow, int mod) {
        long res = pref[r] - (long) pref[l] * pow[r - l] % mod;
        if (res < 0) res += mod;
        return (int) res;
    }
}

