class Solution {
    public static int countSquareSumTriples(int n) {
        int count = 0;
        for (int c = 1; c <= n; c++) {
            long c2 = (long) c * c;
            for (int a = 1; a <= n; a++) {
                long a2 = (long) a * a;
                if (a2 >= c2) break;
                long b2 = c2 - a2;
                int b = (int) Math.sqrt(b2);
                if ((long) b * b == b2 && b >= 1 && b <= n) {
                    count++;
                }
            }
        }
        return count;
    }
}

