class Solution {
    private static final long MOD = 1000000007L;

    public static int countGoodNumbers(long n) {
        long evenCnt = (n + 1) / 2;
        long oddCnt = n / 2;

        long pow5 = powMod(5L, evenCnt);
        long pow4 = powMod(4L, oddCnt);

        long ans = (pow5 * pow4) % MOD;
        return (int) ans;
    }

    private static long powMod(long base, long exp) {
        if (exp == 0) return 1L;
        long half = powMod(base, exp / 2);
        long res = (half * half) % MOD;
        if ((exp & 1L) == 1L) {
            res = (res * base) % MOD;
        }
        return res;
    }
}

