    public TreeNode canMerge(TreeNode[] trees) {
        if (trees == null || trees.length == 0) return null;
        Map<Integer, TreeNode> rootMap = new HashMap<>();
        Set<Integer> leafVals = new HashSet<>();
        for (TreeNode root : trees) {
            rootMap.put(root.val, root);
            if (root.left != null) leafVals.add(root.left.val);
            if (root.right != null) leafVals.add(root.right.val);
        }

        TreeNode root = null;
        for (int val : rootMap.keySet()) {
            if (!leafVals.contains(val)) {
                if (root != null) return null; // more than one possible root
                root = rootMap.get(val);
            }
        }
        if (root == null) return null; // no root found
        rootMap.remove(root.val);

        if (!merge(root, Integer.MIN_VALUE, Integer.MAX_VALUE, rootMap)) return null;
        return rootMap.isEmpty() ? root : null;
    }

    private boolean merge(TreeNode node, int low, int high, Map<Integer, TreeNode> map) {
        if (node == null) return true;
        if (node.val <= low || node.val >= high) return false;

        // Process left child
        if (node.left != null) {
            if (node.left.left == null && node.left.right == null) {
                int leafVal = node.left.val;
                if (map.containsKey(leafVal)) {
                    TreeNode sub = map.remove(leafVal);
                    node.left = sub;
                }
            }
            if (!merge(node.left, low, node.val, map)) return false;
        }

        // Process right child
        if (node.right != null) {
            if (node.right.left == null && node.right.right == null) {
                int leafVal = node.right.val;
                if (map.containsKey(leafVal)) {
                    TreeNode sub = map.remove(leafVal);
                    node.right = sub;
                }
            }
            if (!merge(node.right, node.val, high, map)) return false;
        }

        return true;
    }
}

