class Solution {
    public static int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], t = e[2];
            adj[u].add(new int[]{v, t});
            adj[v].add(new int[]{u, t});
        }
        long INF = Long.MAX_VALUE / 4;
        long[][] best = new long[n][maxTime + 1];
        for (int i = 0; i < n; i++) Arrays.fill(best[i], INF);
        best[0][0] = passingFees[0];
        PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        heap.offer(new long[]{passingFees[0], 0, 0});
        while (!heap.isEmpty()) {
            long[] cur = heap.poll();
            long cost = cur[0];
            int city = (int) cur[1];
            int time = (int) cur[2];
            if (cost != best[city][time]) continue;
            if (city == n - 1) return (int) cost;
            for (int[] edge : adj[city]) {
                int next = edge[0];
                int roadTime = edge[1];
                int newTime = time + roadTime;
                if (newTime > maxTime) continue;
                long newCost = cost + passingFees[next];
                if (newCost < best[next][newTime]) {
                    best[next][newTime] = newCost;
                    heap.offer(new long[]{newCost, next, newTime});
                }
            }
        }
        long answer = INF;
        for (int t = 0; t <= maxTime; t++) {
            answer = Math.min(answer, best[n - 1][t]);
        }
        return answer == INF ? -1 : (int) answer;
    }
}

