class Solution {
    public int countPalindromicSubsequence(String s) {
        int n = s.length();
        if (n < 3) return 0;
        int[] prefix = new int[n];
        int mask = 0;
        for (int i = 0; i < n; i++) {
            prefix[i] = mask;
            mask |= 1 << (s.charAt(i) - 'a');
        }
        int[] suffix = new int[n];
        mask = 0;
        for (int i = n - 1; i >= 0; i--) {
            suffix[i] = mask;
            mask |= 1 << (s.charAt(i) - 'a');
        }
        boolean[][] seen = new boolean[26][26];
        for (int i = 0; i < n; i++) {
            int middle = s.charAt(i) - 'a';
            int common = prefix[i] & suffix[i];
            while (common != 0) {
                int lowbit = common & -common;
                int outer = Integer.numberOfTrailingZeros(lowbit);
                seen[outer][middle] = true;
                common ^= lowbit;
            }
        }
        int count = 0;
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < 26; j++) {
                if (seen[i][j]) count++;
            }
        }
        return count;
    }
}

