class Solution {
    private static final int MOD = 1_000_000_007;

    public int colorTheGrid(int m, int n) {
        int total = (int) Math.pow(3, m);
        List<Integer> validList = new ArrayList<>();
        int[][] colors = new int[total][m];
        for (int mask = 0; mask < total; mask++) {
            int tmp = mask;
            boolean ok = true;
            for (int i = 0; i < m; i++) {
                colors[mask][i] = tmp % 3;
                tmp /= 3;
            }
            for (int i = 0; i < m - 1; i++) {
                if (colors[mask][i] == colors[mask][i + 1]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                validList.add(mask);
            }
        }
        int S = validList.size();
        int[] stateIdx = new int[total];
        Arrays.fill(stateIdx, -1);
        for (int i = 0; i < S; i++) {
            stateIdx[validList.get(i)] = i;
        }

        int[][] compat = new int[S][];
        for (int i = 0; i < S; i++) {
            int maskA = validList.get(i);
            List<Integer> list = new ArrayList<>();
            for (int j = 0; j < S; j++) {
                int maskB = validList.get(j);
                boolean ok = true;
                for (int row = 0; row < m; row++) {
                    if (colors[maskA][row] == colors[maskB][row]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    list.add(j);
                }
            }
            compat[i] = list.stream().mapToInt(Integer::intValue).toArray();
        }

        long[] dpPrev = new long[S];
        long[] dpCurr = new long[S];
        Arrays.fill(dpPrev, 1L);

        for (int col = 2; col <= n; col++) {
            Arrays.fill(dpCurr, 0L);
            for (int i = 0; i < S; i++) {
                long val = dpPrev[i];
                if (val == 0) continue;
                for (int j : compat[i]) {
                    dpCurr[j] = (dpCurr[j] + val) % MOD;
                }
            }
            long[] tmp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = tmp;
        }

        long ans = 0;
        for (long v : dpPrev) {
            ans = (ans + v) % MOD;
        }
        return (int) ans;
    }
}

public class Solution {
    public static int addMinimumRungs(int[] rungs, int dist) {
        int added = 0;
        int prev = 0;
        for (int i = 0; i < rungs.length; i++) {
            int gap = rungs[i] - prev;
            if (gap > dist) {
                added += (gap - 1) / dist;
            }
            prev = rungs[i];
        }
        return added;
    }
}

