class Solution {
    public static int maxPoints(int[][] points) {
        int m = points.length;
        int n = points[0].length;
        int[] dp = points[0].clone();

        for (int i = 1; i < m; i++) {
            int[] left = new int[n];
            int[] right = new int[n];

            left[0] = dp[0];
            for (int j = 1; j < n; j++) {
                left[j] = Math.max(dp[j], left[j - 1] - 1);
            }

            right[n - 1] = dp[n - 1];
            for (int j = n - 2; j >= 0; j--) {
                right[j] = Math.max(dp[j], right[j + 1] - 1);
            }

            int[] newDp = new int[n];
            for (int j = 0; j < n; j++) {
                newDp[j] = points[i][j] + Math.max(left[j], right[j]);
            }
            dp = newDp;
        }

        int ans = dp[0];
        for (int v : dp) {
            if (v > ans) ans = v;
        }
        return ans;
    }
}

