class Solution {
    private static final int MAX_BIT = 20;

    private static class TrieNode {
        TrieNode[] child = new TrieNode[2];
        int cnt;
    }

    private final TrieNode root = new TrieNode();

    private void insert(int num) {
        TrieNode node = root;
        for (int i = MAX_BIT; i >= 0; i--) {
            int b = (num >> i) & 1;
            if (node.child[b] == null) node.child[b] = new TrieNode();
            node = node.child[b];
            node.cnt++;
        }
    }

    private void delete(int num) {
        TrieNode node = root;
        for (int i = MAX_BIT; i >= 0; i--) {
            int b = (num >> i) & 1;
            TrieNode next = node.child[b];
            next.cnt--;
            if (next.cnt == 0) {
                node.child[b] = null;
                return;
            }
            node = next;
        }
    }

    private int query(int num) {
        TrieNode node = root;
        int ans = 0;
        for (int i = MAX_BIT; i >= 0; i--) {
            int b = (num >> i) & 1;
            int want = b ^ 1;
            if (node.child[want] != null && node.child[want].cnt > 0) {
                ans |= (1 << i);
                node = node.child[want];
            } else {
                node = node.child[b];
            }
        }
        return ans;
    }

    public int[] maxGeneticDifference(int[] parents, int[][] queries) {
        int n = parents.length;
        List<Integer>[] tree = new ArrayList[n];
        for (int i = 0; i < n; i++) tree[i] = new ArrayList<>();
        int rootNode = -1;
        for (int i = 0; i < n; i++) {
            if (parents[i] == -1) {
                rootNode = i;
            } else {
                tree[parents[i]].add(i);
            }
        }

        List<int[]>[] qlist = new ArrayList[n];
        for (int i = 0; i < queries.length; i++) {
            int node = queries[i][0];
            int val = queries[i][1];
            if (qlist[node] == null) qlist[node] = new ArrayList<>();
            qlist[node].add(new int[]{i, val});
        }

        int[] ans = new int[queries.length];
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{rootNode, 0}); // 0 = enter, 1 = exit

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int state = cur[1];
            if (state == 0) {
                insert(node);
                if (qlist[node] != null) {
                    for (int[] q : qlist[node]) {
                        ans[q[0]] = query(q[1]);
                    }
                }
                stack.push(new int[]{node, 1});
                List<Integer> children = tree[node];
                for (int i = children.size() - 1; i >= 0; i--) {
                    stack.push(new int[]{children.get(i), 0});
                }
            } else {
                delete(node);
            }
        }
        return ans;
    }
}

