class Solution {
    public static int smallestChair(int[][] times, int targetFriend) {
        int n = times.length;
        class Event {
            int arrival;
            int leave;
            int idx;
            Event(int a, int l, int i) { arrival = a; leave = l; idx = i; }
        }
        List<Event> events = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            events.add(new Event(times[i][0], times[i][1], i));
        }
        events.sort(Comparator.comparingInt(e -> e.arrival));
        PriorityQueue<Integer> free = new PriorityQueue<>();
        PriorityQueue<int[]> occupied = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        int nextChair = 0;
        for (Event e : events) {
            while (!occupied.isEmpty() && occupied.peek()[0] <= e.arrival) {
                free.offer(occupied.poll()[1]);
            }
            if (e.idx == targetFriend) {
                return free.isEmpty() ? nextChair : free.peek();
            }
            int chair = free.isEmpty() ? nextChair++ : free.poll();
            occupied.offer(new int[]{e.leave, chair});
        }
        return -1;
    }
}

