class Solution {
    public static int sumOfDigitsAfterConvert(String s, int k) {
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            int val = s.charAt(i) - 'a' + 1;
            if (val >= 10) {
                total += val / 10 + (val % 10);
            } else {
                total += val;
            }
        }
        for (int repeat = 1; repeat < k; repeat++) {
            int sum = 0;
            while (total > 0) {
                sum += total % 10;
                total /= 10;
            }
            total = sum;
        }
        return total;
    }
}

