class Solution {
    public static int maximumCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = students[0].length;
        int[][] score = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int same = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) same++;
                }
                score[i][j] = same;
            }
        }
        int totalMasks = 1 << m;
        int[] dp = new int[totalMasks];
        Arrays.fill(dp, Integer.MIN_VALUE);
        dp[0] = 0;
        for (int mask = 0; mask < totalMasks; mask++) {
            int studentIdx = Integer.bitCount(mask);
            if (studentIdx >= m) continue;
            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int newMask = mask | (1 << mentor);
                    int cand = dp[mask] + score[studentIdx][mentor];
                    if (cand > dp[newMask]) dp[newMask] = cand;
                }
            }
        }
        return dp[totalMasks - 1];
    }
}

import java.util.*;

class Solution {
    static class TrieNode {
        TreeMap<String, TrieNode> children = new TreeMap<>();
    }

    Map<String, List<TrieNode>> groups = new HashMap<>();
    Set<TrieNode> deleted = new HashSet<>();

    String build(TrieNode node) {
        StringBuilder sb = new StringBuilder("(");
        for (Map.Entry<String, TrieNode> e : node.children.entrySet()) {
            sb.append(e.getKey()).append(build(e.getValue()));
        }
        sb.append(")");
        String s = sb.toString();
        // only non-empty subtrees (has at least one child) can be marked as duplicates
        if (!s.equals("()")) groups.computeIfAbsent(s, k -> new ArrayList<>()).add(node);
        return s;
    }

    void dfs(TrieNode node, List<String> path, List<List<String>> ans) {
        if (deleted.contains(node)) return;
        if (!path.isEmpty()) ans.add(new ArrayList<>(path));
        for (Map.Entry<String, TrieNode> e : node.children.entrySet()) {
            path.add(e.getKey());
            dfs(e.getValue(), path, ans);
            path.remove(path.size() - 1);
        }
    }

    public List<List<String>> deleteDuplicateFolder(List<List<String>> paths) {
        TrieNode root = new TrieNode();
        for (List<String> path : paths) {
            TrieNode node = root;
            for (String p : path) {
                node = node.children.computeIfAbsent(p, k -> new TrieNode());
            }
        }
        build(root);
        for (List<TrieNode> nodes : groups.values()) {
            if (nodes.size() > 1) deleted.addAll(nodes);
        }
        List<List<String>> ans = new ArrayList<>();
        dfs(root, new ArrayList<>(), ans);
        return ans;
    }
}

