class Solution {
    public static int[][] describePainting(int[][] segments) {
        List<int[]> events = new ArrayList<>();
        for (int[] seg : segments) {
            events.add(new int[]{seg[0], seg[2]});
            events.add(new int[]{seg[1], -seg[2]});
        }
        events.sort(Comparator.comparingInt(a -> a[0]));
        List<int[]> result = new ArrayList<>();
        long currentSum = 0;
        int prevPos = -1;
        int i = 0;
        while (i < events.size()) {
            int pos = events.get(i)[0];
            if (prevPos != -1 && currentSum != 0) {
                int sumInt = (int) currentSum;
                result.add(new int[]{prevPos, pos, sumInt});
            }
            while (i < events.size() && events.get(i)[0] == pos) {
                currentSum += events.get(i)[1];
                i++;
            }
            prevPos = pos;
        }
        return result.toArray(new int[0][]);
    }
}

