class Solution {
    public long minimumPerimeter(long neededApples) {
        long low = 0;
        long high = 1;
        while (apples(high) < neededApples) {
            high <<= 1;
        }
        while (low < high) {
            long mid = (low + high) >>> 1;
            if (apples(mid) >= neededApples) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return 8L * low;
    }

    private long apples(long k) {
        // total apples inside square with half-side length k
        // formula: 2 * k * (k + 1) * (2k + 1)
        return 2L * k * (k + 1) * (2L * k + 1);
    }
}

