class Solution {
    public int minWastedSpace(int[] nums, int k) {
        int n = nums.length;
        int[][] waste = new int[n][n];
        for (int i = 0; i < n; i++) {
            int curMax = 0;
            int curSum = 0;
            for (int j = i; j < n; j++) {
                curMax = Math.max(curMax, nums[j]);
                curSum += nums[j];
                waste[i][j] = curMax * (j - i + 1) - curSum;
            }
        }
        int maxBlocks = k + 1;
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[n + 1][maxBlocks + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], INF);
        }
        dp[0][0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int b = 1; b <= maxBlocks && b <= i; b++) {
                for (int p = b - 1; p <= i - 1; p++) {
                    if (dp[p][b - 1] == INF) continue;
                    int w = waste[p][i - 1];
                    dp[i][b] = Math.min(dp[i][b], dp[p][b - 1] + w);
                }
            }
        }
        int ans = INF;
        for (int b = 1; b <= maxBlocks; b++) {
            ans = Math.min(ans, dp[n][b]);
        }
        return ans;
    }
}

