class Solution {
    public static int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        int[] tails = new int[n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            int v = obstacles[i];
            int l = 0, r = size;
            while (l < r) {
                int m = (l + r) >>> 1;
                if (tails[m] > v) {
                    r = m;
                } else {
                    l = m + 1;
                }
            }
            int pos = l;
            ans[i] = pos + 1;
            if (pos == size) {
                tails[size++] = v;
            } else {
                tails[pos] = v;
            }
        }
        return ans;
    }
}

