public class Solution {
    public long maxProduct(String s) {
        int n = s.length();
        int[] d1 = new int[n];
        int l = 0, r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : Math.min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s.charAt(i - k) == s.charAt(i + k)) {
                k++;
            }
            d1[i] = k;
            if (i + k - 1 > r) {
                l = i - k + 1;
                r = i + k - 1;
            }
        }
        int[] bestEnd = new int[n];
        int[] bestStart = new int[n];
        for (int i = 0; i < n; i++) {
            int radius = d1[i];
            int len = 2 * radius - 1;
            int right = i + radius - 1;
            int left = i - radius + 1;
            if (len > bestEnd[right]) bestEnd[right] = len;
            if (len > bestStart[left]) bestStart[left] = len;
        }
        int[] leftMax = new int[n];
        leftMax[0] = bestEnd[0];
        for (int i = 1; i < n; i++) {
            leftMax[i] = Math.max(leftMax[i - 1], bestEnd[i]);
        }
        int[] rightMax = new int[n];
        rightMax[n - 1] = bestStart[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            rightMax[i] = Math.max(rightMax[i + 1], bestStart[i]);
        }
        long ans = 0;
        for (int i = 0; i < n - 1; i++) {
            long prod = (long) leftMax[i] * rightMax[i + 1];
            if (prod > ans) ans = prod;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public long minNonZeroProduct(int p) {
        long pow2p = modPow(2L, p, MOD);
        long maxNum = (pow2p - 1 + MOD) % MOD;
        long other = (pow2p - 2 + MOD) % MOD;
        long exponent = (1L << (p - 1)) - 1;
        long otherPow = modPow(other, exponent, MOD);
        return (maxNum * otherPow) % MOD;
    }

    private long modPow(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

