class Solution {
    public static int latestDayToCross(int row, int col, int[][] cells) {
        int left = 0, right = cells.length, answer = 0;
        while (left <= right) {
            int mid = (left + right) / 2;
            int[][] grid = new int[row][col];
            for (int i = 0; i < mid; i++) {
                int r = cells[i][0];
                int c = cells[i][1];
                grid[r - 1][c - 1] = 1;
            }
            Queue<int[]> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[row][col];
            for (int c = 0; c < col; c++) {
                if (grid[0][c] == 0) {
                    queue.offer(new int[]{0, c});
                    visited[0][c] = true;
                }
            }
            boolean canCross = false;
            int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
            while (!queue.isEmpty()) {
                int[] cur = queue.poll();
                int r = cur[0];
                int c = cur[1];
                if (r == row - 1) {
                    canCross = true;
                    break;
                }
                for (int[] d : dirs) {
                    int nr = r + d[0];
                    int nc = c + d[1];
                    if (nr >= 0 && nr < row && nc >= 0 && nc < col && !visited[nr][nc] && grid[nr][nc] == 0) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            if (canCross) {
                answer = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return answer;
    }
}

