class Solution {
    public static int[] rearrangeArray(int[] nums) {
        int n = nums.length;
        Arrays.sort(nums);
        int[] result = new int[n];
        // Try descending order first
        for (int i = 0; i < n; i++) {
            result[i] = nums[n - 1 - i];
        }
        boolean ok = true;
        for (int i = 1; i < n - 1; i++) {
            if (result[i] * 2 == result[i - 1] + result[i + 1]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            return result;
        }
        // Fallback arrangement: small half, large half, middle (if odd)
        int half = n / 2;
        int idx = 0;
        for (int i = 0; i < half; i++) {
            result[idx++] = nums[i];
        }
        for (int i = n - half; i < n; i++) {
            result[idx++] = nums[i];
        }
        if (n % 2 == 1) {
            result[idx] = nums[half];
        }
        return result;
    }
}

