public class Solution {
    public static long maximumMatrixSum(int[][] matrix) {
        int n = matrix.length;
        long sumAbs = 0;
        int negCount = 0;
        int minAbs = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int[] row = matrix[i];
            for (int j = 0; j < n; j++) {
                int val = row[j];
                int a = Math.abs(val);
                sumAbs += a;
                if (val < 0) {
                    negCount++;
                }
                if (a < minAbs) {
                    minAbs = a;
                }
            }
        }
        long adjustment = (n % 2 == 1 && negCount % 2 == 1) ? 2L * minAbs : 0L;
        return sumAbs - adjustment;
    }
}

