class Solution {
    public static boolean validPath(int n, int[][] edges, int source, int destination) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj[u].add(v);
            adj[v].add(u);
        }
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(source);
        visited[source] = true;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            if (node == destination) {
                return true;
            }
            for (int nb : adj[node]) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.add(nb);
                }
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public static int numberOfWays(int n, int[][] roads) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] r : roads) {
            int u = r[0], v = r[1], w = r[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }

        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        long[] ways = new long[n];
        dist[0] = 0;
        ways[0] = 1;

        List<long[]> heap = new ArrayList<>();
        heap.add(new long[]{0, 0});

        while (!heap.isEmpty()) {
            long[] top = heap.get(0);
            long d = top[0];
            int u = (int) top[1];
            long[] last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                int i = 0;
                while (true) {
                    int l = i * 2 + 1;
                    int r = i * 2 + 2;
                    int smallest = i;
                    if (l < heap.size() && heap.get(l)[0] < heap.get(smallest)[0]) smallest = l;
                    if (r < heap.size() && heap.get(r)[0] < heap.get(smallest)[0]) smallest = r;
                    if (smallest == i) break;
                    long[] tmp = heap.get(i);
                    heap.set(i, heap.get(smallest));
                    heap.set(smallest, tmp);
                    i = smallest;
                }
            }

            if (d != dist[u]) continue;

            for (int[] vw : adj[u]) {
                int v = vw[0];
                int w = vw[1];
                long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    ways[v] = ways[u];
                    heap.add(new long[]{nd, v});
                    int idx = heap.size() - 1;
                    while (idx > 0) {
                        int p = (idx - 1) >> 1;
                        if (heap.get(p)[0] <= heap.get(idx)[0]) break;
                        long[] tmp = heap.get(p);
                        heap.set(p, heap.get(idx));
                        heap.set(idx, tmp);
                        idx = p;
                    }
                } else if (nd == dist[v]) {
                    ways[v] = (ways[v] + ways[u]) % MOD;
                }
            }
        }

        return (int) (ways[n - 1] % MOD);
    }
}

