class Solution {
    public int minimizeDifference(int[][] mat, int target) {
        int m = mat.length;
        int maxPossible = 0;
        for (int[] row : mat) {
            int rowMax = 0;
            for (int v : row) {
                if (v > rowMax) rowMax = v;
            }
            maxPossible += rowMax;
        }
        boolean[] dp = new boolean[maxPossible + 1];
        dp[0] = true;
        for (int[] row : mat) {
            boolean[] ndp = new boolean[maxPossible + 1];
            for (int sum = 0; sum <= maxPossible; sum++) {
                if (!dp[sum]) continue;
                for (int v : row) {
                    int ns = sum + v;
                    if (ns <= maxPossible) {
                        ndp[ns] = true;
                    }
                }
            }
            dp = ndp;
        }
        int minDiff = Integer.MAX_VALUE;
        for (int sum = 0; sum <= maxPossible; sum++) {
            if (dp[sum]) {
                int diff = Math.abs(target - sum);
                if (diff < minDiff) minDiff = diff;
                if (minDiff == 0) break;
            }
        }
        return minDiff;
    }
}

class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int m = Arrays.stream(sums).min().getAsInt();
        m = -m;
        TreeMap<Integer,Integer> st = new TreeMap<>();
        for (int x : sums) st.merge(x+m, 1, Integer::sum);
        removeOne(st, st.firstKey());
        List<Integer> ans = new ArrayList<>();
        ans.add(st.firstKey());
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < (1<<i); j++) {
                if ((j >> (i-1) & 1) == 1) {
                    int s = 0;
                    for (int k = 0; k < i; k++) if ((j>>k&1)==1) s += ans.get(k);
                    removeOne(st, s);
                }
            }
            ans.add(st.firstKey());
        }
        for (int i = 0; i < (1<<n); i++) {
            int s = 0;
            for (int j = 0; j < n; j++) if ((i>>j&1)==1) s += ans.get(j);
            if (s == m) {
                for (int j = 0; j < n; j++) if ((i>>j&1)==1) ans.set(j, -ans.get(j));
                break;
            }
        }
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = ans.get(i);
        return res;
    }
    private void removeOne(TreeMap<Integer,Integer> st, int key) {
        int c = st.get(key);
        if (c == 1) st.remove(key); else st.put(key, c-1);
    }
}

