class Solution {
    public static int numberOfWaysSeparateNumbers(String num) {
        final int MOD = 1_000_000_007;
        int n = num.length();
        char[] chars = num.toCharArray();

        int[][] lcp = new int[n + 1][n + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (chars[i] == chars[j]) {
                    lcp[i][j] = lcp[i + 1][j + 1] + 1;
                }
            }
        }

        int[][] dp = new int[n + 1][n + 1];
        int[][] pref = new int[n + 1][n + 1];

        for (int i = 1; i <= n; i++) {
            for (int len = 1; len <= i; len++) {
                int start = i - len;
                if (chars[start] == '0') {
                    continue;
                }
                if (start == 0) {
                    dp[i][len] = 1;
                } else {
                    long total = 0;
                    if (len > 1) {
                        total = pref[start][len - 1];
                    }
                    if (len <= start) {
                        int a = start - len;
                        int b = start;
                        int common = lcp[a][b];
                        if (common < len && chars[a + common] < chars[b + common]) {
                            total += dp[start][len];
                        }
                    }
                    dp[i][len] = (int) (total % MOD);
                }
                pref[i][len] = (pref[i][len - 1] + dp[i][len]) % MOD;
            }
        }
        return pref[n][n];
    }
}

