class Solution {
    private static class Pair {
        int sessions;
        int cur;
        Pair(int sessions, int cur) {
            this.sessions = sessions;
            this.cur = cur;
        }
    }

    public static int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalMask = 1 << n;
        Pair[] dp = new Pair[totalMask];
        dp[0] = new Pair(1, 0);
        for (int mask = 0; mask < totalMask; mask++) {
            if (dp[mask] == null) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int newMask = mask | (1 << i);
                int cur = dp[mask].cur;
                int sess = dp[mask].sessions;
                int newSess, newCur;
                if (cur + tasks[i] <= sessionTime) {
                    newSess = sess;
                    newCur = cur + tasks[i];
                } else {
                    newSess = sess + 1;
                    newCur = tasks[i];
                }
                Pair candidate = new Pair(newSess, newCur);
                if (dp[newMask] == null || better(candidate, dp[newMask])) {
                    dp[newMask] = candidate;
                }
            }
        }
        return dp[totalMask - 1].sessions;
    }

    private static boolean better(Pair a, Pair b) {
        if (a.sessions != b.sessions) return a.sessions < b.sessions;
        return a.cur < b.cur;
    }
}

