class Solution {
    private static final int MOD = 1_000_000_007;

    private long distinctCount(String s) {
        long dp = 1; // empty subsequence
        long[] last = new long[2]; // last contribution for '0' and '1'
        for (int i = 0; i < s.length(); i++) {
            int ch = s.charAt(i) - '0';
            long newDp = (dp * 2) % MOD;
            newDp = (newDp - last[ch] + MOD) % MOD;
            last[ch] = dp;
            dp = newDp;
        }
        return dp;
    }

    public int numberOfUniqueGoodSubsequences(String binary) {
        long totalDistinct = distinctCount(binary);
        int firstZero = binary.indexOf('0');
        long ans;
        if (firstZero == -1) {
            ans = (totalDistinct - 1 + MOD) % MOD; // exclude empty subsequence
        } else {
            String suffix = binary.substring(firstZero + 1);
            long suffixDistinct = distinctCount(suffix);
            ans = (totalDistinct - suffixDistinct + MOD) % MOD;
        }
        return (int) ans;
    }
}

