public class Solution {
    public static class LockingTreeObj {
        private final int[] parent;
        private final List<Integer>[] children;
        private final int[] lockedBy;
        public LockingTreeObj(int[] parent) {
            this.parent = parent;
            int n = parent.length;
            children = new ArrayList[n];
            for (int i = 0; i < n; i++) children[i] = new ArrayList<>();
            for (int i = 1; i < n; i++) children[parent[i]].add(i);
            lockedBy = new int[n];
            Arrays.fill(lockedBy, -1);
        }
        public boolean lock(int node, int user) {
            if (lockedBy[node] != -1) return false;
            lockedBy[node] = user;
            return true;
        }
        public boolean unlock(int node, int user) {
            if (lockedBy[node] != user) return false;
            lockedBy[node] = -1;
            return true;
        }
        public boolean upgrade(int node, int user) {
            if (lockedBy[node] != -1) return false;
            for (int cur = parent[node]; cur != -1; cur = parent[cur]) {
                if (lockedBy[cur] != -1) return false;
            }
            Deque<Integer> stack = new ArrayDeque<>();
            List<Integer> lockedDescendants = new ArrayList<>();
            stack.push(node);
            while (!stack.isEmpty()) {
                int cur = stack.pop();
                for (int child : children[cur]) {
                    if (lockedBy[child] != -1) lockedDescendants.add(child);
                    stack.push(child);
                }
            }
            if (lockedDescendants.isEmpty()) return false;
            for (int d : lockedDescendants) lockedBy[d] = -1;
            lockedBy[node] = user;
            return true;
        }
    }
    public static LockingTreeObj LockingTree(int[] parent) {
        return new LockingTreeObj(parent);
    }
}

