class Solution {
    public int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            children[parents[i]].add(i);
        }

        int nodeOne = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) {
                nodeOne = i;
                break;
            }
        }

        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        if (nodeOne == -1) {
            return ans;
        }

        boolean[] visitedNode = new boolean[n];
        int maxVal = 100000;
        boolean[] present = new boolean[maxVal + 2]; // indices up to maxVal+1
        int curMex = 1;
        int cur = nodeOne;
        while (cur != -1) {
            addSubtree(cur, children, nums, visitedNode, present);
            while (present[curMex]) {
                curMex++;
            }
            ans[cur] = curMex;
            cur = parents[cur];
        }
        return ans;
    }

    private void addSubtree(int start, List<Integer>[] children, int[] nums,
                            boolean[] visitedNode, boolean[] present) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int node = stack.pop();
            if (visitedNode[node]) continue;
            visitedNode[node] = true;
            int val = nums[node];
            if (val < present.length) {
                present[val] = true;
            }
            for (int child : children[node]) {
                if (!visitedNode[child]) {
                    stack.push(child);
                }
            }
        }
    }
}

