public class Solution {
    public static int countQuadruplets(int[] nums) {
        int n = nums.length;
        int answer = 0;
        Map<Integer, Integer> sumFreq = new HashMap<>();
        for (int k = 2; k < n - 1; k++) {
            for (int i = 0; i < k - 1; i++) {
                int s = nums[i] + nums[k - 1];
                sumFreq.put(s, sumFreq.getOrDefault(s, 0) + 1);
            }
            for (int l = k + 1; l < n; l++) {
                int needed = nums[l] - nums[k];
                if (sumFreq.containsKey(needed)) {
                    answer += sumFreq.get(needed);
                }
            }
        }
        return answer;
    }
}

public class Solution {
    public static String reversePrefix(String word, char ch) {
        int idx = word.indexOf(ch);
        if (idx == -1) {
            return word;
        }
        char[] arr = word.toCharArray();
        int left = 0, right = idx;
        while (left < right) {
            char tmp = arr[left];
            arr[left] = arr[right];
            arr[right] = tmp;
            left++;
            right--;
        }
        return new String(arr);
    }
}

