class Solution {
    private static final int MOD = 1_000_000_007;

    public int firstDayWhereAllRoomsVisited(int[] nextVisit) {
        int n = nextVisit.length;
        long[] dp = new long[n];
        dp[0] = 0;
        for (int i = 1; i < n; i++) {
            long val = (2 * dp[i - 1]) % MOD;
            val = (val - dp[nextVisit[i - 1]] + MOD) % MOD;
            val = (val + 2) % MOD;
            dp[i] = val;
        }
        return (int) dp[n - 1];
    }
}

