class Solution {
    public static int[] findOriginalArray(int[] changed) {
        if (changed.length % 2 != 0) {
            return new int[0];
        }
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : changed) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        int[] sorted = changed.clone();
        Arrays.sort(sorted);
        List<Integer> original = new ArrayList<>();
        for (int v : sorted) {
            int cnt = freq.getOrDefault(v, 0);
            if (cnt == 0) {
                continue;
            }
            if (v == 0) {
                if (cnt % 2 != 0) {
                    return new int[0];
                }
                for (int i = 0; i < cnt / 2; i++) {
                    original.add(0);
                }
                freq.put(0, 0);
                continue;
            }
            int doubleVal = v * 2;
            int doubleCnt = freq.getOrDefault(doubleVal, 0);
            if (doubleCnt < cnt) {
                return new int[0];
            }
            for (int i = 0; i < cnt; i++) {
                original.add(v);
            }
            freq.put(v, 0);
            freq.put(doubleVal, doubleCnt - cnt);
        }
        int[] result = new int[original.size()];
        for (int i = 0; i < original.size(); i++) {
            result[i] = original.get(i);
        }
        return result;
    }
}

