class Solution {
    public static long maxTaxiEarnings(int n, int[][] rides) {
        Arrays.sort(rides, (a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            return a[1] - b[1];
        });

        int m = rides.length;
        int[] starts = new int[m];
        for (int i = 0; i < m; i++) {
            starts[i] = rides[i][0];
        }

        long[] dp = new long[m + 1];
        for (int i = m - 1; i >= 0; i--) {
            long profit = (long) rides[i][1] - rides[i][0] + rides[i][2];

            int lo = i + 1, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (starts[mid] >= rides[i][1]) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            int nextIdx = lo;

            dp[i] = Math.max(dp[i + 1], profit + dp[nextIdx]);
        }

        return dp[0];
    }
}

