class Solution {
    public static String longestSubsequenceRepeatedK(String s, int k) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
        }
        StringBuilder best = new StringBuilder();
        int maxLen = s.length() / k;
        dfs(s, k, freq, new StringBuilder(), best, maxLen);
        return best.toString();
    }

    private static void dfs(String s, int k, int[] freq, StringBuilder cur, StringBuilder best, int maxLen) {
        if (cur.length() > best.length() ||
            (cur.length() == best.length() && cur.toString().compareTo(best.toString()) > 0)) {
            best.setLength(0);
            best.append(cur);
        }
        if (cur.length() == maxLen) {
            return;
        }
        // prune if even adding all remaining possible characters cannot beat best
        if (cur.length() + (maxLen - cur.length()) <= best.length()) {
            return;
        }
        for (char c = 'z'; c >= 'a'; c--) {
            if (freq[c - 'a'] < k) continue;
            cur.append(c);
            if (canForm(cur.toString(), s, k)) {
                dfs(s, k, freq, cur, best, maxLen);
            }
            cur.deleteCharAt(cur.length() - 1);
        }
    }

    private static boolean canForm(String seq, String s, int k) {
        int pos = 0;
        int completed = 0;
        int len = seq.length();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == seq.charAt(pos)) {
                pos++;
                if (pos == len) {
                    completed++;
                    if (completed == k) return true;
                    pos = 0;
                }
            }
        }
        return false;
    }
}

