class Solution {
    public static int minOperations(int[] nums) {
        int n = nums.length;
        Set<Integer> set = new HashSet<>();
        for (int v : nums) {
            set.add(v);
        }
        int[] uniq = new int[set.size()];
        int idx = 0;
        for (int v : set) {
            uniq[idx++] = v;
        }
        Arrays.sort(uniq);
        int maxKeep = 0;
        int left = 0;
        for (int right = 0; right < uniq.length; right++) {
            while (uniq[right] - uniq[left] >= n) {
                left++;
            }
            maxKeep = Math.max(maxKeep, right - left + 1);
        }
        return n - maxKeep;
    }
}

