class Solution {
    public static int sumOfBeauties(int[] nums) {
        int n = nums.length;
        int[] prefixMax = new int[n], suffixMin = new int[n];
        prefixMax[0] = nums[0];
        for (int i = 1; i < n; i++) prefixMax[i] = Math.max(prefixMax[i-1], nums[i]);
        suffixMin[n-1] = nums[n-1];
        for (int i = n-2; i >= 0; i--) suffixMin[i] = Math.min(suffixMin[i+1], nums[i]);
        int total = 0;
        for (int i = 1; i <= n-2; i++) {
            if (prefixMax[i-1] < nums[i] && nums[i] < suffixMin[i+1]) total += 2;
            else if (nums[i-1] < nums[i] && nums[i] < nums[i+1]) total += 1;
        }
        return total;
    }
}

