public class Solution {
    public static class DetectSquaresObj {
        private Map<Integer, Map<Integer, Integer>> points = new HashMap<>();
        public void add(int[] point) {
            int x = point[0];
            int y = point[1];
            points.computeIfAbsent(x, k -> new HashMap<>())
                  .merge(y, 1, Integer::sum);
        }
        public int count(int[] point) {
            int x = point[0];
            int y = point[1];
            if (!points.containsKey(x)) return 0;
            int total = 0;
            Map<Integer, Integer> col = points.get(x);
            for (Map.Entry<Integer, Integer> entry : col.entrySet()) {
                int y2 = entry.getKey();
                int cntY2 = entry.getValue();
                if (y2 == y) continue;
                int d = Math.abs(y2 - y);
                for (int dir : new int[]{-1, 1}) {
                    int x2 = x + dir * d;
                    Map<Integer, Integer> colX2 = points.get(x2);
                    if (colX2 == null) continue;
                    int cnt1 = colX2.getOrDefault(y, 0);
                    int cnt2 = colX2.getOrDefault(y2, 0);
                    total += cntY2 * cnt1 * cnt2;
                }
            }
            return total;
        }
    }
    public static DetectSquaresObj DetectSquares() {
        return new DetectSquaresObj();
    }
}

