class Solution {
    public static long gridGame(int[][] grid) {
        int n = grid[0].length;
        int[] top = grid[0];
        int[] bottom = grid[1];
        long[] suffixTop = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixTop[i] = suffixTop[i + 1] + top[i];
        }
        long[] prefixBottom = new long[n];
        prefixBottom[0] = bottom[0];
        for (int i = 1; i < n; i++) {
            prefixBottom[i] = prefixBottom[i - 1] + bottom[i];
        }
        long answer = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            long topRemain = suffixTop[i + 1];
            long bottomRemain = i > 0 ? prefixBottom[i - 1] : 0;
            long worst = Math.max(topRemain, bottomRemain);
            if (worst < answer) answer = worst;
        }
        return answer;
    }
}

