class Solution {
    public static boolean placeWordInCrossword(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;
        int L = word.length();
        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == '#') continue;
                for (int[] dir : dirs) {
                    int dx = dir[0];
                    int dy = dir[1];
                    int prevX = i - dx;
                    int prevY = j - dy;
                    if (prevX >= 0 && prevX < m && prevY >= 0 && prevY < n && board[prevX][prevY] != '#') {
                        continue;
                    }
                    int endX = i + dx * (L - 1);
                    int endY = j + dy * (L - 1);
                    if (endX < 0 || endX >= m || endY < 0 || endY >= n) {
                        continue;
                    }
                    int afterX = i + dx * L;
                    int afterY = j + dy * L;
                    if (afterX >= 0 && afterX < m && afterY >= 0 && afterY < n && board[afterX][afterY] != '#') {
                        continue;
                    }
                    boolean ok = true;
                    for (int k = 0; k < L; k++) {
                        int x = i + dx * k;
                        int y = j + dy * k;
                        char cell = board[x][y];
                        char expected = (dx == -1 || dy == -1) ? word.charAt(L - 1 - k) : word.charAt(k);
                        if (cell != ' ' && cell != expected) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) return true;
                }
            }
        }
        return false;
    }
}

public class Solution {
    public static int gradeStudents(String s, int[] answers) {
        String[] additiveTerms = s.split("\\+");
        int correct = 0;
        for (String term : additiveTerms) {
            String[] factors = term.split("\\*");
            int product = 1;
            for (String f : factors) {
                product *= Integer.parseInt(f);
            }
            correct += product;
        }
        int leftToRight = s.charAt(0) - '0';
        for (int i = 1; i < s.length(); i += 2) {
            char op = s.charAt(i);
            int val = s.charAt(i + 1) - '0';
            if (op == '+') leftToRight += val;
            else leftToRight *= val;
        }
        int totalPoints = 0;
        for (int ans : answers) {
            if (ans == correct) totalPoints += 5;
            else if (ans == leftToRight) totalPoints += 2;
        }
        return totalPoints;
    }
}

public class Solution {
    public static int maxDifference(int[] nums) {
        if (nums.length < 2) return -1;
        int minSoFar = nums[0];
        int best = -1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > minSoFar) {
                int diff = nums[i] - minSoFar;
                if (diff > best) best = diff;
            }
            if (nums[i] < minSoFar) minSoFar = nums[i];
        }
        return best;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int maximumWays(int[] nums, int k) {
        int n = nums.length;
        long total = 0;
        for (int num : nums) total += num;

        // prefix sums up to index n-2 (possible pivot positions)
        long[] pref = new long[n - 1];
        long sum = 0;
        for (int i = 0; i < n - 1; i++) {
            sum += nums[i];
            pref[i] = sum;
        }

        Map<Long, Integer> leftMap = new HashMap<>();
        Map<Long, Integer> rightMap = new HashMap<>();
        for (long v : pref) {
            rightMap.put(v, rightMap.getOrDefault(v, 0) + 1);
        }

        int answer = 0;
        // original count without any change
        if (total % 2 == 0) {
            long target = total / 2;
            answer = rightMap.getOrDefault(target, 0);
        }

        for (int j = 0; j < n; j++) {
            long delta = (long) k - nums[j];
            long count = 0;

            long sumLeft = total + delta;
            if (sumLeft % 2 == 0) {
                long targetLeft = sumLeft / 2;
                count += leftMap.getOrDefault(targetLeft, 0);
            }

            long sumRight = total - delta;
            if (sumRight % 2 == 0) {
                long targetRight = sumRight / 2;
                count += rightMap.getOrDefault(targetRight, 0);
            }

            if (count > answer) answer = (int) count;

            if (j <= n - 2) {
                long val = pref[j];
                // move val from rightMap to leftMap
                int cur = rightMap.get(val);
                if (cur == 1) rightMap.remove(val);
                else rightMap.put(val, cur - 1);
                leftMap.put(val, leftMap.getOrDefault(val, 0) + 1);
            }
        }

        return answer;
    }
}

