class Solution {
    public static int maxConsecutiveAnswers(String answerKey, int k) {
        return Math.max(longest(answerKey, k, 'T'), longest(answerKey, k, 'F'));
    }

    private static int longest(String answerKey, int k, char target) {
        int n = answerKey.length();
        int left = 0, maxLen = 0, changes = 0;
        for (int right = 0; right < n; right++) {
            if (answerKey.charAt(right) != target) {
                changes++;
            }
            while (changes > k) {
                if (answerKey.charAt(left) != target) {
                    changes--;
                }
                left++;
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

class Solution {
    public static int[] findMissingObservations(int[] rolls, int mean, int n) {
        int m = rolls.length;
        long totalNeeded = (long) mean * (n + m);
        long knownSum = 0;
        for (int v : rolls) knownSum += v;
        long missingSum = totalNeeded - knownSum;
        if (missingSum < n || missingSum > 6L*n) return new int[0];
        int[] result = new int[n];
        java.util.Arrays.fill(result, 1);
        long remaining = missingSum - n;
        for (int i = 0; i < n && remaining > 0; i++) {
            long add = Math.min(5, remaining);
            result[i] += add;
            remaining -= add;
        }
        return result;
    }

}

class Solution {
    public static boolean stoneGameIX(int[] stones) {
        int c0 = 0, c1 = 0, c2 = 0;
        for (int v : stones) {
            int r = v % 3;
            if (r == 0) c0++;
            else if (r == 1) c1++;
            else c2++;
        }
        if (c1 == 0 && c2 == 0) return false;
        if (c0 % 2 == 0) {
            return c1 > 0 && c2 > 0;
        } else {
            return c1 > 2 || c2 > 2;
        }
    }
}

import java.util.*;

public class Solution {
    public static StockPriceObj StockPrice() {
        return new StockPriceObj();
    }

    public static class StockPriceObj {
        private final Map<Integer, Integer> priceMap = new HashMap<>();
        private int latestTimestamp = 0;
        private final List<int[]> maxHeap = new ArrayList<>();
        private final List<int[]> minHeap = new ArrayList<>();
        private final Comparator<int[]> maxComp = (a, b) -> Integer.compare(a[0], b[0]);
        private final Comparator<int[]> minComp = (a, b) -> Integer.compare(b[0], a[0]);

        private void heapPush(List<int[]> heap, int[] item, Comparator<int[]> better) {
            heap.add(item);
            int i = heap.size() - 1;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (better.compare(heap.get(p), heap.get(i)) > 0) break;
                int[] tmp = heap.get(p);
                heap.set(p, heap.get(i));
                heap.set(i, tmp);
                i = p;
            }
        }

        private int[] heapPop(List<int[]> heap, Comparator<int[]> better) {
            int[] top = heap.get(0);
            int[] last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                heapifyDown(heap, 0, better);
            }
            return top;
        }

        private void heapifyDown(List<int[]> heap, int i, Comparator<int[]> better) {
            int n = heap.size();
            while (true) {
                int left = i * 2 + 1;
                int right = i * 2 + 2;
                int best = i;
                if (left < n && better.compare(heap.get(best), heap.get(left)) <= 0) best = left;
                if (right < n && better.compare(heap.get(best), heap.get(right)) <= 0) best = right;
                if (best == i) break;
                int[] tmp = heap.get(i);
                heap.set(i, heap.get(best));
                heap.set(best, tmp);
                i = best;
            }
        }

        private void clean(List<int[]> heap, Comparator<int[]> better) {
            while (!heap.isEmpty()) {
                int[] top = heap.get(0);
                int price = top[0];
                int ts = top[1];
                Integer cur = priceMap.get(ts);
                if (cur == null || cur != price) {
                    heapPop(heap, better);
                } else {
                    break;
                }
            }
        }

        public void update(int timestamp, int price) {
            priceMap.put(timestamp, price);
            if (timestamp >= latestTimestamp) latestTimestamp = timestamp;
            heapPush(maxHeap, new int[]{price, timestamp}, maxComp);
            heapPush(minHeap, new int[]{price, timestamp}, minComp);
        }

        public int current() {
            return priceMap.get(latestTimestamp);
        }

        public int maximum() {
            clean(maxHeap, maxComp);
            return maxHeap.get(0)[0];
        }

        public int minimum() {
            clean(minHeap, minComp);
            return minHeap.get(0)[0];
        }
    }
}

class Solution {
    public static int minMoves(String s) {
        int n = s.length();
        int moves = 0;
        int i = 0;
        while (i < n) {
            if (s.charAt(i) == 'X') {
                moves++;
                i += 3;
            } else {
                i++;
            }
        }
        return moves;
    }
}

import java.util.*;

class Solution {
    public static String smallestSubsequence(String s, int k, char letter, int repetition) {
        int n = s.length();
        int[] suffixLetter = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixLetter[i] = suffixLetter[i + 1] + (s.charAt(i) == letter ? 1 : 0);
        }

        StringBuilder sb = new StringBuilder();
        int cntLetter = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            while (sb.length() > 0) {
                char top = sb.charAt(sb.length() - 1);
                if (c >= top) break;
                int afterCntLetter = cntLetter - (top == letter ? 1 : 0);
                if (afterCntLetter + suffixLetter[i] < repetition) break;
                if (sb.length() - 1 + (n - i) < k) break;
                sb.deleteCharAt(sb.length() - 1);
                if (top == letter) cntLetter--;
            }

            if (sb.length() == k) continue;

            if (c == letter) {
                sb.append(c);
                cntLetter++;
            } else {
                int neededLetter = Math.max(0, repetition - cntLetter);
                if (k - sb.length() > neededLetter && cntLetter + suffixLetter[i + 1] >= repetition) {
                    sb.append(c);
                }
            }
        }

        // If still shorter than k (should not happen), append needed letters from the end
        if (sb.length() < k) {
            for (int i = 0; i < n && sb.length() < k; i++) {
                char c = s.charAt(i);
                if (c == letter && cntLetter < repetition) {
                    sb.append(c);
                    cntLetter++;
                }
            }
        }

        return sb.substring(0, k);
    }
}

import java.util.*;

class Solution {
    public static List<Integer> twoOutOfThree(int[] nums1, int[] nums2, int[] nums3) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int[] arr : new int[][]{nums1, nums2, nums3}) {
            Set<Integer> seen = new HashSet<>();
            for (int v : arr) {
                seen.add(v);
            }
            for (int v : seen) {
                count.put(v, count.getOrDefault(v, 0) + 1);
            }
        }
        List<Integer> result = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
            if (entry.getValue() >= 2) {
                result.add(entry.getKey());
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static long minOperations(int[][] grid, int x) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[] values = new int[rows * cols];
        int idx = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                values[idx++] = grid[i][j];
            }
        }
        Arrays.sort(values);
        int median = values[values.length / 2];
        long ops = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int diff = grid[i][j] - median;
                if (diff % x != 0) {
                    return -1;
                }
                ops += Math.abs(diff) / x;
            }
        }
        return ops;
    }
}

