class Solution {
    public static long minimumMoves(int[] seats, int[] students) {
        Arrays.sort(seats);
        Arrays.sort(students);
        long moves = 0;
        for (int i = 0; i < seats.length; i++) {
            moves += Math.abs(seats[i] - students[i]);
        }
        return moves;
    }
}

public class Solution {
    public static boolean canAliceWin(String colors) {
        int aliceMoves = 0;
        int bobMoves = 0;
        for (int i = 1; i < colors.length() - 1; i++) {
            if (colors.charAt(i - 1) == 'A' && colors.charAt(i) == 'A' && colors.charAt(i + 1) == 'A') aliceMoves++;
            if (colors.charAt(i - 1) == 'B' && colors.charAt(i) == 'B' && colors.charAt(i + 1) == 'B') bobMoves++;
        }
        return aliceMoves > bobMoves;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public long minimumDifference(int[] nums) {
        int n = nums.length / 2;
        long total = 0;
        for (int v : nums) total += v;

        // left half sums grouped by count
        List<Long>[] left = new ArrayList[n + 1];
        // right half sums grouped by count
        List<Long>[] right = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            left[i] = new ArrayList<>();
            right[i] = new ArrayList<>();
        }

        // enumerate subsets of left half
        int leftSize = n;
        int limit = 1 << leftSize;
        for (int mask = 0; mask < limit; mask++) {
            int cnt = Integer.bitCount(mask);
            long sum = 0;
            for (int i = 0; i < leftSize; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += nums[i];
                }
            }
            left[cnt].add(sum);
        }

        // enumerate subsets of right half
        int rightSize = n;
        limit = 1 << rightSize;
        for (int mask = 0; mask < limit; mask++) {
            int cnt = Integer.bitCount(mask);
            long sum = 0;
            for (int i = 0; i < rightSize; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += nums[n + i];
                }
            }
            right[cnt].add(sum);
        }

        // sort each list for binary search
        for (int i = 0; i <= n; i++) {
            Collections.sort(left[i]);
            Collections.sort(right[i]);
        }

        long best = Long.MAX_VALUE;
        long halfTotal = total / 2;

        for (int k = 0; k <= n; k++) {
            List<Long> leftList = left[k];
            List<Long> rightList = right[n - k];
            for (long lSum : leftList) {
                long target = halfTotal - lSum;
                int idx = Collections.binarySearch(rightList, target);
                if (idx >= 0) {
                    long s = lSum + rightList.get(idx);
                    long diff = Math.abs(total - 2 * s);
                    if (diff < best) best = diff;
                } else {
                    int insert = -idx - 1;
                    if (insert < rightList.size()) {
                        long s = lSum + rightList.get(insert);
                        long diff = Math.abs(total - 2 * s);
                        if (diff < best) best = diff;
                    }
                    if (insert - 1 >= 0) {
                        long s = lSum + rightList.get(insert - 1);
                        long diff = Math.abs(total - 2 * s);
                        if (diff < best) best = diff;
                    }
                }
            }
        }

        return best;
    }
}

import java.util.*;

class Solution {
    public long kthSmallestProduct(int[] nums1, int[] nums2, long k) {
        int n = nums1.length;
        int m = nums2.length;
        long[] a = new long[n];
        long[] b = new long[m];
        for (int i = 0; i < n; i++) a[i] = nums1[i];
        for (int i = 0; i < m; i++) b[i] = nums2[i];

        long low = Math.min(Math.min(a[0] * b[0], a[0] * b[m - 1]),
                           Math.min(a[n - 1] * b[0], a[n - 1] * b[m - 1])) - 1;
        long high = Math.max(Math.max(a[0] * b[0], a[0] * b[m - 1]),
                            Math.max(a[n - 1] * b[0], a[n - 1] * b[m - 1])) + 1;

        while (low < high) {
            long mid = low + (high - low) / 2;
            if (countLE(a, b, mid) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private long countLE(long[] a, long[] b, long x) {
        long cnt = 0;
        for (long val : a) {
            if (val > 0) {
                long limit = Math.floorDiv(x, val);
                cnt += upperBound(b, limit);
            } else if (val < 0) {
                long limit = -Math.floorDiv(-x, val); // ceil(x / val)
                int idx = lowerBound(b, limit);
                cnt += b.length - idx;
            } else {
                if (x >= 0) cnt += b.length;
            }
        }
        return cnt;
    }

    private int upperBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] <= target) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }

    private int lowerBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }
}

import java.util.*;

class Solution {
    public static List<Boolean> simpleBank(long[] balance, List<List<Object>> transactions) {
        int n = balance.length;
        List<Boolean> answer = new ArrayList<>();
        for (List<Object> t : transactions) {
            String type = (String) t.get(0);
            if ("transfer".equals(type)) {
                int a = ((Number) t.get(1)).intValue();
                int b = ((Number) t.get(2)).intValue();
                long money = ((Number) t.get(3)).longValue();
                if (a < 1 || a > n || b < 1 || b > n || balance[a - 1] < money) {
                    answer.add(false);
                    continue;
                }
                balance[a - 1] -= money;
                balance[b - 1] += money;
                answer.add(true);
            } else if ("deposit".equals(type)) {
                int a = ((Number) t.get(1)).intValue();
                long money = ((Number) t.get(2)).longValue();
                if (a < 1 || a > n) {
                    answer.add(false);
                    continue;
                }
                balance[a - 1] += money;
                answer.add(true);
            } else if ("withdraw".equals(type)) {
                int a = ((Number) t.get(1)).intValue();
                long money = ((Number) t.get(2)).longValue();
                if (a < 1 || a > n || balance[a - 1] < money) {
                    answer.add(false);
                    continue;
                }
                balance[a - 1] -= money;
                answer.add(true);
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int INF = Integer.MAX_VALUE;
        int[][] dist = new int[n + 1][2];
        for (int i = 1; i <= n; i++) {
            dist[i][0] = INF;
            dist[i][1] = INF;
        }

        Queue<int[]> q = new ArrayDeque<>();
        dist[1][0] = 0;
        q.offer(new int[]{1, 0});

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int d = cur[1];
            for (int nb : graph[node]) {
                int nd = d + 1;
                if (nd < dist[nb][0]) {
                    dist[nb][1] = dist[nb][0];
                    dist[nb][0] = nd;
                    q.offer(new int[]{nb, nd});
                } else if (nd > dist[nb][0] && nd < dist[nb][1]) {
                    dist[nb][1] = nd;
                    q.offer(new int[]{nb, nd});
                }
            }
            if (dist[n][1] != INF) break;
        }

        int steps = dist[n][1];
        int curTime = 0;
        int period = 2 * change;
        for (int i = 0; i < steps; i++) {
            if (curTime % period >= change) {
                curTime += period - (curTime % period);
            }
            curTime += time;
        }
        return curTime;
    }
}

import java.util.*;

class Solution {
    public int networkBecomesIdle(int[][] edges, int[] patience) {
        int n = patience.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = 0;
        dist[0] = 0;
        while (head < tail) {
            int u = queue[head++];
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    queue[tail++] = v;
                }
            }
        }
        int maxTime = 0;
        for (int i = 1; i < n; i++) {
            int roundTrip = dist[i] * 2;
            int p = patience[i];
            int lastSend;
            if (p >= roundTrip) {
                lastSend = 0;
            } else {
                lastSend = ((roundTrip - 1) / p) * p;
            }
            int arrival = lastSend + roundTrip;
            if (arrival > maxTime) maxTime = arrival;
        }
        return maxTime + 1;
    }
}

import java.util.*;

class Solution {
    public static boolean areNumbersAscending(String s) {
        String[] tokens = s.split(" ");
        long prevNumber = Long.MIN_VALUE;
        for (int i = 0; i < tokens.length; i++) {
            String token = tokens[i];
            if (token.matches("^\\d+$")) {
                long curNumber = Long.parseLong(token);
                if (curNumber <= prevNumber) return false;
                prevNumber = curNumber;
            }
        }
        return true;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static long countMaxOrSubsets(int[] nums) {
        int maxOr = 0;
        for (int v : nums) {
            maxOr |= v;
        }
        Map<Integer, Long> cnt = new HashMap<>();
        for (int x : nums) {
            Map<Integer, Long> newCnt = new HashMap<>(cnt);
            for (Map.Entry<Integer, Long> entry : cnt.entrySet()) {
                int curOr = entry.getKey();
                int newOr = curOr | x;
                newCnt.put(newOr, newCnt.getOrDefault(newOr, 0L) + entry.getValue());
            }
            newCnt.put(x, newCnt.getOrDefault(x, 0L) + 1);
            cnt = newCnt;
        }
        return cnt.getOrDefault(maxOr, 0L);
    }
}

import java.util.*;

class Solution {
    private static final List<Integer> balancedNumbers = new ArrayList<>();
    private static boolean initialized = false;

    private static void init() {
        if (initialized) return;
        int[] remaining = new int[10];
        for (int d = 1; d <= 9; d++) remaining[d] = d;
        backtrack(0L, 0, remaining);
        Collections.sort(balancedNumbers);
        initialized = true;
    }

    private static void backtrack(long current, int length, int[] remaining) {
        if (length > 0 && isBalanced(remaining) && current <= Integer.MAX_VALUE) {
            balancedNumbers.add((int) current);
        }
        if (length == 9) return;
        for (int d = 1; d <= 9; d++) {
            if (remaining[d] > 0) {
                long next = current * 10 + d;
                if (next > Integer.MAX_VALUE) continue;
                remaining[d]--;
                backtrack(next, length + 1, remaining);
                remaining[d]++;
            }
        }
    }

    private static boolean isBalanced(int[] remaining) {
        for (int d = 1; d <= 9; d++) {
            if (remaining[d] != 0 && remaining[d] != d) return false;
        }
        return true;
    }

    public static int nextBeautifulNumber(int n) {
        init();
        for (int num : balancedNumbers) {
            if (num > n) return num;
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public int countHighestScoreNodes(int[] parents) {
        int n = parents.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            children[parents[i]].add(i);
        }

        int[] subSize = new int[n];
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, 0}); // node, state (0 = first visit, 1 = after children)

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int state = cur[1];
            if (state == 0) {
                stack.push(new int[]{node, 1});
                for (int child : children[node]) {
                    stack.push(new int[]{child, 0});
                }
            } else {
                int size = 1;
                for (int child : children[node]) {
                    size += subSize[child];
                }
                subSize[node] = size;
            }
        }

        long maxScore = 0;
        int count = 0;
        for (int i = 0; i < n; i++) {
            long score = 1L;
            for (int child : children[i]) {
                score *= subSize[child];
            }
            int rest = n - subSize[i];
            if (rest > 0) {
                score *= rest;
            }
            if (score > maxScore) {
                maxScore = score;
                count = 1;
            } else if (score == maxScore) {
                count++;
            }
        }
        return count;
    }
}

import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.List;

class Solution {
    public static int minimumTime(int n, int[][] relations, int[] time) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        int[] indeg = new int[n];
        for (int[] rel : relations) {
            int u = rel[0] - 1;
            int v = rel[1] - 1;
            adj[u].add(v);
            indeg[v]++;
        }

        int[] finish = new int[n];
        ArrayDeque<Integer> queue = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                finish[i] = time[i];
                queue.add(i);
            } else {
                finish[i] = 0;
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                int candidate = finish[u] + time[v];
                if (candidate > finish[v]) {
                    finish[v] = candidate;
                }
                if (--indeg[v] == 0) {
                    queue.add(v);
                }
            }
        }

        int answer = 0;
        for (int i = 0; i < n; i++) {
            if (finish[i] > answer) {
                answer = finish[i];
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public static int countValidWords(String sentence) {
        String[] tokens = sentence.split(" ");
        int validCount = 0;
        for (String token : tokens) {
            if (token.length() > 0 && isValid(token)) {
                validCount++;
            }
        }
        return validCount;
    }

    private static boolean isValid(String token) {
        int n = token.length();
        int hyphenCount = 0;
        int punctuationCount = 0;
        for (int i = 0; i < n; i++) {
            char c = token.charAt(i);
            if (Character.isDigit(c)) {
                return false;
            }
            if (c == '-') {
                hyphenCount++;
                if (hyphenCount > 1) {
                    return false;
                }
                if (i == 0 || i == n - 1) {
                    return false;
                }
                char prev = token.charAt(i - 1);
                char next = token.charAt(i + 1);
                if (!Character.isLetter(prev) || !Character.isLetter(next)) {
                    return false;
                }
            } else if (c == '!' || c == '.' || c == ',') {
                punctuationCount++;
                if (punctuationCount > 1) {
                    return false;
                }
                if (i != n - 1) {
                    return false;
                }
            } else if (!Character.isLetter(c)) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int[] platesBetweenCandles(String s, int[][] queries) {
        int n = s.length();
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + (s.charAt(i) == '*' ? 1 : 0);
        }
        int[] leftCandle = new int[n];
        int last = -1;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '|') last = i;
            leftCandle[i] = last;
        }
        int[] rightCandle = new int[n];
        int next = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == '|') next = i;
            rightCandle[i] = next;
        }
        int[] ans = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int l = queries[q][0];
            int r = queries[q][1];
            int left = rightCandle[l];
            int right = leftCandle[r];
            ans[q] = (left != -1 && right != -1 && left < right) ? pref[right] - pref[left + 1] : 0;
        }
        return ans;
    }
}

