import java.util.Arrays;

class Solution {
    public static int maxTwoEvents(int[][] events) {
        if (events.length == 0) return 0;
        Arrays.sort(events, (a, b) -> Integer.compare(a[1], b[1]));
        int n = events.length;
        int[] ends = new int[n];
        int[] prefixMax = new int[n];
        for (int i = 0; i < n; i++) {
            ends[i] = events[i][1];
            int val = events[i][2];
            prefixMax[i] = i == 0 ? val : Math.max(prefixMax[i - 1], val);
        }
        int best = 0;
        for (int i = 0; i < n; i++) {
            int start = events[i][0];
            int end = events[i][1];
            int value = events[i][2];
            best = Math.max(best, value);
            int lo = 0, hi = i - 1, idx = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1;
                if (ends[mid] < start) {
                    idx = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            if (idx != -1) {
                best = Math.max(best, value + prefixMax[idx]);
            }
        }
        return best;
    }
}

