class Solution {
    public static int countValidMoveCombinations(String[] pieces, int[][] positions) {
        int n = pieces.length;
        @SuppressWarnings("unchecked")
        List<int[]>[] destLists = new List[n];
        for (int i = 0; i < n; i++) {
            String type = pieces[i];
            int r0 = positions[i][0];
            int c0 = positions[i][1];
            List<int[]> list = new ArrayList<>();
            for (int r = 1; r <= 8; r++) {
                for (int c = 1; c <= 8; c++) {
                    int dr = r - r0;
                    int dc = c - c0;
                    int absDr = Math.abs(dr);
                    int absDc = Math.abs(dc);
                    boolean ok = false;
                    if (type.equals("rook")) {
                        ok = (r == r0 || c == c0);
                    } else if (type.equals("bishop")) {
                        ok = (absDr == absDc);
                    } else {
                        ok = (r == r0 || c == c0 || absDr == absDc);
                    }
                    if (ok) {
                        list.add(new int[]{r, c});
                    }
                }
            }
            destLists[i] = list;
        }
        int[][] chosen = new int[n][];
        int[] count = new int[1];
        dfs(0, n, destLists, positions, chosen, count);
        return count[0];
    }

    private static void dfs(int idx, int n, List<int[]>[] destLists, int[][] positions, int[][] chosen, int[] count) {
        if (idx == n) {
            if (isValid(chosen, positions, n)) {
                count[0]++;
            }
            return;
        }
        for (int[] dest : destLists[idx]) {
            chosen[idx] = dest;
            dfs(idx + 1, n, destLists, positions, chosen, count);
        }
    }

    private static boolean isValid(int[][] destinations, int[][] positions, int n) {
        @SuppressWarnings("unchecked")
        List<int[]>[] paths = new List[n];
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            int startR = positions[i][0];
            int startC = positions[i][1];
            int destR = destinations[i][0];
            int destC = destinations[i][1];
            int dr = Integer.signum(destR - startR);
            int dc = Integer.signum(destC - startC);
            List<int[]> path = new ArrayList<>();
            int r = startR;
            int c = startC;
            path.add(new int[]{r, c});
            while (r != destR || c != destC) {
                r += dr;
                c += dc;
                path.add(new int[]{r, c});
            }
            paths[i] = path;
            if (path.size() > maxLen) {
                maxLen = path.size();
            }
        }
        for (int t = 0; t < maxLen; t++) {
            Set<Integer> seen = new HashSet<>();
            for (int i = 0; i < n; i++) {
                List<int[]> p = paths[i];
                int[] pos = t < p.size() ? p.get(t) : p.get(p.size() - 1);
                int key = pos[0] * 8 + pos[1];
                if (!seen.add(key)) {
                    return false;
                }
            }
        }
        return true;
    }
}

