class Solution {
    public static boolean possiblyEquals(String s1, String s2) {
        Set<String> visited = new HashSet<>();
        return dfs(s1, 0, s2, 0, 0, visited);
    }

    private static boolean dfs(String s1, int i, String s2, int j, int diff, Set<String> visited) {
        String key = i + "," + j + "," + diff;
        if (!visited.add(key)) return false;

        int n1 = s1.length();
        int n2 = s2.length();

        if (i == n1 && j == n2) return diff == 0;

        if (diff > 0) {
            if (j < n2 && Character.isLetter(s2.charAt(j))) {
                if (dfs(s1, i, s2, j + 1, diff - 1, visited)) return true;
            }
        } else if (diff < 0) {
            if (i < n1 && Character.isLetter(s1.charAt(i))) {
                if (dfs(s1, i + 1, s2, j, diff + 1, visited)) return true;
            }
        } else {
            if (i < n1 && j < n2 && Character.isLetter(s1.charAt(i)) && Character.isLetter(s2.charAt(j))) {
                if (s1.charAt(i) == s2.charAt(j)) {
                    if (dfs(s1, i + 1, s2, j + 1, 0, visited)) return true;
                }
            }
        }

        if (i < n1 && Character.isDigit(s1.charAt(i))) {
            int val = 0;
            for (int idx = i; idx < n1 && Character.isDigit(s1.charAt(idx)); idx++) {
                val = val * 10 + (s1.charAt(idx) - '0');
                if (dfs(s1, idx + 1, s2, j, diff + val, visited)) return true;
            }
        }

        if (j < n2 && Character.isDigit(s2.charAt(j))) {
            int val = 0;
            for (int idx = j; idx < n2 && Character.isDigit(s2.charAt(idx)); idx++) {
                val = val * 10 + (s2.charAt(idx) - '0');
                if (dfs(s1, i, s2, idx + 1, diff - val, visited)) return true;
            }
        }

        return false;
    }
}

