class Solution {
    public static int maxPathQuality(int[] values, int[][] edges, int maxTime) {
        int n = values.length;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int t = e[2];
            graph[u].add(new int[]{v, t});
            graph[v].add(new int[]{u, t});
        }

        boolean[] visited = new boolean[n];
        int[] best = new int[1];
        visited[0] = true;
        dfs(0, maxTime, values[0], values, graph, visited, best);
        return best[0];
    }

    private static void dfs(int node, int timeLeft, int quality, int[] values,
                            List<int[]>[] graph, boolean[] visited, int[] best) {
        if (node == 0) {
            if (quality > best[0]) {
                best[0] = quality;
            }
        }
        for (int[] edge : graph[node]) {
            int next = edge[0];
            int cost = edge[1];
            if (cost > timeLeft) {
                continue;
            }
            if (!visited[next]) {
                visited[next] = true;
                dfs(next, timeLeft - cost, quality + values[next], values, graph, visited, best);
                visited[next] = false;
            } else {
                dfs(next, timeLeft - cost, quality, values, graph, visited, best);
            }
        }
    }
}

