class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        if (start == goal) return 0;
        boolean[] visited = new boolean[1001];
        int[] dist = new int[1001];
        Arrays.fill(dist, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        visited[start] = true;
        dist[start] = 0;
        queue.offer(start);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int num : nums) {
                int[] nextVals = {cur + num, cur - num};
                for (int nxt : nextVals) {
                    if (nxt == goal) {
                        return dist[cur] + 1;
                    }
                    if (nxt >= 0 && nxt <= 1000 && !visited[nxt]) {
                        visited[nxt] = true;
                        dist[nxt] = dist[cur] + 1;
                        queue.offer(nxt);
                    }
                }
            }
        }
        return -1;
    }
}

