class Solution {
    public static int countVowelSubstrings(String word) {
        Set<Character> vowelSet = new HashSet<>(Arrays.asList('a', 'e', 'i', 'o', 'u'));
        int n = word.length();
        int total = 0;
        int i = 0;
        while (i < n) {
            if (!vowelSet.contains(word.charAt(i))) {
                i++;
                continue;
            }
            int blockStart = i;
            while (i < n && vowelSet.contains(word.charAt(i))) i++;
            int blockEnd = i;
            total += countBlock(word, blockStart, blockEnd);
        }
        return total;
    }

    private static int countBlock(String word, int start, int end) {
        int total = 0;
        int[] cnt = new int[5];
        int left = start;
        int right = start;
        while (left < end) {
            while (right < end && !allVowels(cnt)) {
                cnt[idx(word.charAt(right))]++;
                right++;
            }
            if (allVowels(cnt)) {
                total += end - right + 1;
            }
            cnt[idx(word.charAt(left))]--;
            left++;
        }
        return total;
    }

    private static int idx(char c) {
        switch (c) {
            case 'a': return 0;
            case 'e': return 1;
            case 'i': return 2;
            case 'o': return 3;
            case 'u': return 4;
            default: return -1;
        }
    }

    private static boolean allVowels(int[] cnt) {
        for (int v : cnt) {
            if (v == 0) return false;
        }
        return true;
    }
}

