class Solution {
    public static int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        Arrays.sort(tasks);
        Arrays.sort(workers);
        int low = 0, high = Math.min(tasks.length, workers.length);
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (canAssign(mid, tasks, workers, pills, strength)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean canAssign(int k, int[] tasks, int[] workers, int pills, int strength) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int w : workers) {
            map.merge(w, 1, Integer::sum);
        }
        int remainingPills = pills;
        for (int i = k - 1; i >= 0; i--) {
            int task = tasks[i];
            Integer key = map.ceilingKey(task);
            if (key != null) {
                decrement(map, key);
                continue;
            }
            if (remainingPills == 0) {
                return false;
            }
            int needed = task - strength;
            if (needed <= 0) {
                Integer first = map.firstKey();
                if (first == null) return false;
                decrement(map, first);
                remainingPills--;
                continue;
            }
            Integer key2 = map.ceilingKey(needed);
            if (key2 == null) {
                return false;
            }
            decrement(map, key2);
            remainingPills--;
        }
        return true;
    }

    private static void decrement(TreeMap<Integer, Integer> map, int key) {
        int cnt = map.get(key);
        if (cnt == 1) {
            map.remove(key);
        } else {
            map.put(key, cnt - 1);
        }
    }
}

public class Solution {
    public static RobotSimulation robotSimulation(int width, int height) {
        return new RobotSimulation(width, height);
    }

    public static class RobotSimulation {
        private final int width, height;
        private int x = 0, y = 0;
        private int dirIdx = 0; // 0:East,1:North,2:West,3:South
        private final int[] dx = {1, 0, -1, 0};
        private final int[] dy = {0, 1, 0, -1};
        private static final String[] DIRS = {"East", "North", "West", "South"};

        public RobotSimulation(int width, int height) {
            this.width = width;
            this.height = height;
        }

        public void move(int num) {
            for (int i = 0; i < num; i++) {
                int nx = x + dx[dirIdx];
                int ny = y + dy[dirIdx];
                if (nx < 0 || nx >= width || ny < 0 || ny >= height) {
                    dirIdx = (dirIdx + 1) % 4;
                    nx = x + dx[dirIdx];
                    ny = y + dy[dirIdx];
                }
                x = nx;
                y = ny;
            }
        }

        public int[] getPos() {
            return new int[]{x, y};
        }

        public String getDir() {
            return DIRS[dirIdx];
        }
    }
}

