class Solution {
    public static int[] mostBeautifulItem(int[][] items, int[] queries) {
        Arrays.sort(items, (a, b) -> Integer.compare(a[0], b[0]));
        int n = items.length;
        int[] prices = new int[n];
        int[] prefBeauty = new int[n];
        int maxBeauty = 0;
        for (int i = 0; i < n; i++) {
            int price = items[i][0];
            int beauty = items[i][1];
            if (beauty > maxBeauty) {
                maxBeauty = beauty;
            }
            prices[i] = price;
            prefBeauty[i] = maxBeauty;
        }
        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int idx = upperBound(prices, queries[i]) - 1;
            answers[i] = idx >= 0 ? prefBeauty[idx] : 0;
        }
        return answers;
    }

    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

