class Solution {
    public static int minimizedMaximum(int n, int[] quantities) {
        int low = 1;
        int high = 0;
        for (int q : quantities) {
            if (q > high) high = q;
        }
        while (low < high) {
            int mid = (low + high) / 2;
            long required = 0;
            for (int q : quantities) {
                required += (q + mid - 1) / mid;
            }
            if (required <= n) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

