class Solution {
    public static ListNode reverseEvenLengthGroups(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prevGroupTail = dummy;
        ListNode cur = head;
        int groupSize = 1;
        while (cur != null) {
            int count = 0;
            ListNode lastNode = null;
            ListNode runner = cur;
            while (count < groupSize && runner != null) {
                lastNode = runner;
                runner = runner.next;
                count++;
            }
            ListNode nextGroupHead = runner;
            if (count % 2 == 0) {
                ListNode prev = nextGroupHead;
                ListNode node = cur;
                for (int i = 0; i < count; i++) {
                    ListNode nxt = node.next;
                    node.next = prev;
                    prev = node;
                    node = nxt;
                }
                prevGroupTail.next = prev;
                prevGroupTail = cur;
            } else {
                prevGroupTail = lastNode;
            }
            cur = nextGroupHead;
            groupSize++;
        }
        return dummy.next;
    }
}

