class Solution {
    public static int wateringPlants(int[] plants, int capacity) {
        int steps = 0;
        int position = -1;
        int water = capacity;
        for (int i = 0; i < plants.length; i++) {
            if (water < plants[i]) {
                steps += position + 1;
                position = -1;
                water = capacity;
            }
            steps += i - position;
            position = i;
            water -= plants[i];
        }
        return steps;
    }
}

import java.util.*;

class Solution {
    public static List<Boolean> processFriendRequests(int n, int[][] restrictions, int[][] requests) {
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        List<Boolean> answer = new ArrayList<>();

        for (int[] req : requests) {
            int u = req[0];
            int v = req[1];
            int ru = find(u, parent);
            int rv = find(v, parent);

            if (ru == rv) {
                answer.add(true);
                continue;
            }

            boolean ok = true;
            for (int[] restr : restrictions) {
                int x = restr[0];
                int y = restr[1];
                int rx = find(x, parent);
                int ry = find(y, parent);
                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                union(ru, rv, parent, rank);
                answer.add(true);
            } else {
                answer.add(false);
            }
        }

        return answer;
    }

    private static int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    private static void union(int x, int y, int[] parent, int[] rank) {
        int rx = find(x, parent);
        int ry = find(y, parent);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank[rx]++;
        }
    }
}

import java.util.*;

class Solution {
    public long sumOfKMirror(int k, int n) {
        long sum = 0;
        int count = 0;
        int length = 1;
        while (count < n) {
            int half = (length + 1) / 2;
            int start = (int) Math.pow(10, half - 1);
            if (half == 1) start = 1;
            int end = (int) Math.pow(10, half) - 1;
            for (int prefix = start; prefix <= end && count < n; ++prefix) {
                long pal = makePalindrome(prefix, length % 2 == 1);
                if (isKPalindrome(pal, k)) {
                    sum += pal;
                    count++;
                }
            }
            length++;
        }
        return sum;
    }

    private long makePalindrome(int prefix, boolean odd) {
        long pal = prefix;
        int x = odd ? prefix / 10 : prefix;
        while (x > 0) {
            pal = pal * 10 + (x % 10);
            x /= 10;
        }
        return pal;
    }

    private boolean isKPalindrome(long num, int k) {
        List<Integer> digits = new ArrayList<>();
        long x = num;
        while (x > 0) {
            digits.add((int) (x % k));
            x /= k;
        }
        int i = 0, j = digits.size() - 1;
        while (i < j) {
            if (!digits.get(i).equals(digits.get(j))) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
}

public class Solution {
    public static int maxDistanceDifferentColors(int[] colors) {
        int n = colors.length;
        if (n == 0) return 0;
        int leftColor = colors[0];
        int rightColor = colors[n - 1];
        if (leftColor != rightColor) return n - 1;
        int maxDist = 0;
        for (int i = 0; i < n; i++) {
            if (colors[i] != rightColor) {
                maxDist = Math.max(maxDist, n - 1 - i);
                break;
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            if (colors[i] != leftColor) {
                maxDist = Math.max(maxDist, i);
                break;
            }
        }
        return maxDist;
    }
}

