public class Solution {
    public static Query RangeFreqQuery(int[] nums) {
        Map<Integer, List<Integer>> positions = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int v = nums[i];
            positions.computeIfAbsent(v, k -> new ArrayList<>()).add(i);
        }
        return new Query(positions);
    }

    private static int lowerBound(List<Integer> arr, int target) {
        int lo = 0, hi = arr.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr.get(mid) < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    private static int upperBound(List<Integer> arr, int target) {
        int lo = 0, hi = arr.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr.get(mid) <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static class Query {
        private final Map<Integer, List<Integer>> positions;

        Query(Map<Integer, List<Integer>> positions) {
            this.positions = positions;
        }

        public int query(int left, int right, int value) {
            List<Integer> list = positions.get(value);
            if (list == null) return 0;
            int l = lowerBound(list, left);
            int r = upperBound(list, right);
            return r - l;
        }
    }
}

