class Solution {
    public int minimumBuckets(String hamsters) {
        int n = hamsters.length();
        char[] arr = hamsters.toCharArray();
        boolean[] bucket = new boolean[n];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] != 'H') continue;
            boolean fed = false;
            if (i > 0 && bucket[i - 1]) fed = true;
            if (i + 1 < n && bucket[i + 1]) fed = true;
            if (fed) continue;
            if (i + 1 < n && arr[i + 1] == '.' && !bucket[i + 1]) {
                bucket[i + 1] = true;
                ans++;
            } else if (i - 1 >= 0 && arr[i - 1] == '.' && !bucket[i - 1]) {
                bucket[i - 1] = true;
                ans++;
            } else {
                return -1;
            }
        }
        return ans;
    }
}

