class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] up = new int[m][n];
        int[][] down = new int[m][n];
        long total = 0;

        // pyramids pointing up
        for (int i = m - 1; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (i == m - 1 || j == 0 || j == n - 1) {
                        up[i][j] = 1;
                    } else {
                        int min = Math.min(up[i + 1][j - 1],
                                Math.min(up[i + 1][j], up[i + 1][j + 1]));
                        up[i][j] = 1 + min;
                    }
                    total += up[i][j] - 1;
                }
            }
        }

        // pyramids pointing down
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (i == 0 || j == 0 || j == n - 1) {
                        down[i][j] = 1;
                    } else {
                        int min = Math.min(down[i - 1][j - 1],
                                Math.min(down[i - 1][j], down[i - 1][j + 1]));
                        down[i][j] = 1 + min;
                    }
                    total += down[i][j] - 1;
                }
            }
        }

        return (int) total;
    }
}

import java.util.Arrays;

public class Solution {
    public static int[] getAverages(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n];
        Arrays.fill(result, -1);
        int windowSize = 2 * k + 1;
        if (windowSize > n) {
            return result;
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += nums[i];
            if (i >= windowSize) {
                sum -= nums[i - windowSize];
            }
            if (i >= windowSize - 1) {
                int center = i - k;
                result[center] = (int) (sum / windowSize);
            }
        }
        return result;
    }
}

