class Solution {
    public static int[] findEvenNumbers(int[] digits) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int d : digits) {
            freq.put(d, freq.getOrDefault(d, 0) + 1);
        }
        Set<Integer> results = new HashSet<>();
        backtrack(0, 0, freq, results);
        return results.stream().sorted().mapToInt(Integer::intValue).toArray();
    }

    private static void backtrack(int pos, int current, Map<Integer, Integer> freq, Set<Integer> results) {
        if (pos == 3) {
            int lastDigit = current % 10;
            if (lastDigit % 2 == 0) {
                results.add(current);
            }
            return;
        }
        for (Integer digit : freq.keySet()) {
            int count = freq.get(digit);
            if (count == 0) continue;
            if (pos == 0 && digit == 0) continue;
            freq.put(digit, count - 1);
            backtrack(pos + 1, current * 10 + digit, freq, results);
            freq.put(digit, count);
        }
    }
}

