public class Solution {
    public static int minimumDeletions(int[] nums) {
        int n = nums.length;
        int minIdx = 0, maxIdx = 0;
        for (int i = 1; i < n; i++) {
            if (nums[i] < nums[minIdx]) minIdx = i;
            if (nums[i] > nums[maxIdx]) maxIdx = i;
        }
        int frontOnly = Math.max(minIdx, maxIdx) + 1;
        int backOnly = Math.max(n - minIdx, n - maxIdx);
        int frontThenBack = Math.min(minIdx, maxIdx) + 1 + (n - Math.max(minIdx, maxIdx));
        int backThenFront = frontThenBack;
        return Math.min(Math.min(frontOnly, backOnly), Math.min(frontThenBack, backThenFront));
    }
}

