class Solution {
    public static List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        boolean[] knows = new boolean[n];
        knows[0] = true;
        knows[firstPerson] = true;

        Arrays.sort(meetings, (a, b) -> Integer.compare(a[2], b[2]));

        int i = 0;
        while (i < meetings.length) {
            int curTime = meetings[i][2];
            List<int[]> group = new ArrayList<>();
            Set<Integer> persons = new HashSet<>();

            while (i < meetings.length && meetings[i][2] == curTime) {
                int x = meetings[i][0];
                int y = meetings[i][1];
                group.add(new int[]{x, y});
                persons.add(x);
                persons.add(y);
                i++;
            }

            Map<Integer, List<Integer>> adj = new HashMap<>();
            for (int p : persons) {
                adj.put(p, new ArrayList<>());
            }
            for (int[] pair : group) {
                int x = pair[0];
                int y = pair[1];
                adj.get(x).add(y);
                adj.get(y).add(x);
            }

            Set<Integer> visited = new HashSet<>();
            for (int start : persons) {
                if (visited.contains(start)) continue;

                Deque<Integer> stack = new ArrayDeque<>();
                List<Integer> component = new ArrayList<>();
                boolean hasSecret = false;
                visited.add(start);
                stack.push(start);

                while (!stack.isEmpty()) {
                    int cur = stack.pop();
                    component.add(cur);
                    if (knows[cur]) hasSecret = true;
                    for (int nb : adj.get(cur)) {
                        if (!visited.contains(nb)) {
                            visited.add(nb);
                            stack.push(nb);
                        }
                    }
                }

                if (hasSecret) {
                    for (int node : component) {
                        knows[node] = true;
                    }
                }
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int idx = 0; idx < n; idx++) {
            if (knows[idx]) result.add(idx);
        }
        return result;
    }
}

