class Solution {
    public static int[] maxSubsequence(int[] nums, int k) {
        int n = nums.length;
        Pair[] pairs = new Pair[n];
        for (int i = 0; i < n; i++) {
            pairs[i] = new Pair(nums[i], i);
        }
        Arrays.sort(pairs, (a, b) -> Integer.compare(b.value, a.value));
        Pair[] selected = Arrays.copyOfRange(pairs, 0, k);
        Arrays.sort(selected, (a, b) -> Integer.compare(a.index, b.index));
        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = selected[i].value;
        }
        return result;
    }

