class Solution {
    public static List<Integer> findGoodDays(int[] security, int time) {
        int n = security.length;
        int[] left = new int[n];
        int[] right = new int[n];
        for (int i = 1; i < n; i++) {
            if (security[i - 1] >= security[i]) left[i] = left[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {
            if (security[i] <= security[i + 1]) right[i] = right[i + 1] + 1;
        }
        List<Integer> result = new ArrayList<>();
        for (int i = time; i < n - time; i++) {
            if (left[i] >= time && right[i] >= time) result.add(i);
        }
        return result;
    }
}

