class Solution {
    public String getDirections(TreeNode root, int startValue, int destValue) {
        String pathToStart = dfs(root, startValue, "");
        String pathToDest = dfs(root, destValue, "");
        int i = 0;
        while (i < pathToStart.length() && i < pathToDest.length() && pathToStart.charAt(i) == pathToDest.charAt(i)) {
            i++;
        }
        String upMoves = "U".repeat(pathToStart.length() - i);
        String downMoves = pathToDest.substring(i);
        return upMoves + downMoves;
    }

    private String dfs(TreeNode node, int target, String curPath) {
        if (node == null) return null;
        if (node.val == target) {
            return curPath;
        }
        String left = dfs(node.left, target, curPath + "L");
        if (left != null) return left;
        String right = dfs(node.right, target, curPath + "R");
        if (right != null) return right;
        return null;
    }
}

