class Solution {
    public int[][] validArrangement(int[][] pairs) {
        Map<Integer, Deque<Integer>> adj = new HashMap<>();
        Map<Integer, Integer> outDeg = new HashMap<>();
        Map<Integer, Integer> inDeg = new HashMap<>();

        for (int[] p : pairs) {
            int u = p[0];
            int v = p[1];
            adj.computeIfAbsent(u, k -> new ArrayDeque<>()).add(v);
            outDeg.put(u, outDeg.getOrDefault(u, 0) + 1);
            inDeg.put(v, inDeg.getOrDefault(v, 0) + 1);
        }

        int start = -1;
        for (int node : outDeg.keySet()) {
            int out = outDeg.getOrDefault(node, 0);
            int in = inDeg.getOrDefault(node, 0);
            if (out - in == 1) {
                start = node;
                break;
            }
        }
        if (start == -1) {
            start = pairs[0][0];
        }

        Deque<Integer> stack = new ArrayDeque<>();
        List<Integer> path = new ArrayList<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int v = stack.peek();
            Deque<Integer> nbrs = adj.get(v);
            if (nbrs != null && !nbrs.isEmpty()) {
                int u = nbrs.pollLast();
                stack.push(u);
            } else {
                path.add(stack.pop());
            }
        }
        Collections.reverse(path);
        int m = pairs.length;
        int[][] result = new int[m][2];
        for (int i = 0; i < m; i++) {
            result[i][0] = path.get(i);
            result[i][1] = path.get(i + 1);
        }
        return result;
    }
}

