class Solution {
    public long subArrayRanges(int[] nums) {
        int n = nums.length;
        long sumMax = 0;
        long sumMin = 0;

        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        // Previous greater (strictly)
        stack.clear();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] <= nums[i]) {
                stack.pop();
            }
            int prev = stack.isEmpty() ? -1 : stack.peek();
            left[i] = i - prev;
            stack.push(i);
        }

        // Next greater or equal
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] < nums[i]) {
                stack.pop();
            }
            int nxt = stack.isEmpty() ? n : stack.peek();
            right[i] = nxt - i;
            stack.push(i);
        }

        for (int i = 0; i < n; i++) {
            sumMax += (long) nums[i] * left[i] * right[i];
        }

        // Previous smaller (strictly)
        stack.clear();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            int prev = stack.isEmpty() ? -1 : stack.peek();
            left[i] = i - prev;
            stack.push(i);
        }

        // Next smaller or equal
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] > nums[i]) {
                stack.pop();
            }
            int nxt = stack.isEmpty() ? n : stack.peek();
            right[i] = nxt - i;
            stack.push(i);
        }

        for (int i = 0; i < n; i++) {
            sumMin += (long) nums[i] * left[i] * right[i];
        }

        return sumMax - sumMin;
    }
}

