public class Solution {
    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.length;
        int[] pos = new int[n];
        int[] amt = new int[n];
        for (int i = 0; i < n; i++) {
            pos[i] = fruits[i][0];
            amt[i] = fruits[i][1];
        }
        long max = 0;
        long cur = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            cur += amt[right];
            while (left <= right && !isFeasible(pos[left], pos[right], startPos, k)) {
                cur -= amt[left];
                left++;
            }
            if (cur > max) {
                max = cur;
            }
        }
        return (int) max;
    }

    private boolean isFeasible(int L, int R, int startPos, int k) {
        if (startPos <= L) {
            return R - startPos <= k;
        } else if (startPos >= R) {
            return startPos - L <= k;
        } else {
            int leftDist = startPos - L;
            int rightDist = R - startPos;
            int steps1 = 2 * leftDist + rightDist;
            int steps2 = 2 * rightDist + leftDist;
            return Math.min(steps1, steps2) <= k;
        }
    }
}

import java.util.*;

class Solution {
    public static int maximumDetonation(int[][] bombs) {
        int n = bombs.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            int xi = bombs[i][0];
            int yi = bombs[i][1];
            int ri = bombs[i][2];
            int ri2 = ri * ri;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                int xj = bombs[j][0];
                int yj = bombs[j][1];
                int dx = xi - xj;
                int dy = yi - yj;
                if (dx * dx + dy * dy <= ri2) {
                    adj[i].add(j);
                }
            }
        }
        int best = 0;
        for (int start = 0; start < n; start++) {
            boolean[] visited = new boolean[n];
            Queue<Integer> queue = new ArrayDeque<>();
            visited[start] = true;
            queue.add(start);
            int count = 0;
            while (!queue.isEmpty()) {
                int cur = queue.poll();
                count++;
                for (int nxt : adj[cur]) {
                    if (!visited[nxt]) {
                        visited[nxt] = true;
                        queue.add(nxt);
                    }
                }
            }
            if (count > best) best = count;
        }
        return best;
    }
}

import java.util.PriorityQueue;

class Solution {
    private static class Location {
        String name;
        int score;
        Location(String name, int score) {
            this.name = name;
            this.score = score;
        }
    }

    // FIXED: fields were `static`, shared across every "instance" (no real instance existed -
    // add/get were static methods), so a second tracker would corrupt/inherit state from the
    // first. Made instance-level. ALSO fixed the algorithm itself: the original never moved a
    // newly-added better-ranked item ahead of an already-revealed one, and get() always
    // returned the worst of the already-revealed set rather than properly re-admitting the
    // next-best remaining candidate - this breaks the required "re-ranking can make get()
    // return the same location again" behavior demonstrated in the official example
    // (confirmed by a 30-trial randomized stress test against a from-scratch reference).
    private final PriorityQueue<Location> best; // worst of current top-k on top
    private final PriorityQueue<Location> rest; // best of the leftovers on top
    private int k = 0;

    public Solution() {
        best = new PriorityQueue<>((a, b) -> {
            if (a.score != b.score) return Integer.compare(a.score, b.score); // lower score = worse = first
            return b.name.compareTo(a.name); // alphabetically later = worse = first
        });
        rest = new PriorityQueue<>((a, b) -> {
            if (a.score != b.score) return Integer.compare(b.score, a.score); // higher score = better = first
            return a.name.compareTo(b.name); // alphabetically first = better = first
        });
    }

    public void add(String name, int score) {
        Location item = new Location(name, score);
        best.offer(item);
        if (best.size() > k) {
            Location moved = best.poll();
            rest.offer(moved);
        }
    }

    public String get() {
        k++;
        if (!rest.isEmpty()) {
            Location moved = rest.poll();
            best.offer(moved);
        }
        return best.peek().name;
    }
}

class Solution {
