class Solution {
    public static String addSpaces(String s, int[] spaces) {
        int idx = 0;
        int n = s.length();
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (idx < spaces.length && i == spaces[idx]) {
                result.append(' ');
                idx++;
            }
            result.append(s.charAt(i));
        }
        return result.toString();
    }
}

