class Solution {
    public static int waterPlants(int[] plants, int capacityA, int capacityB) {
        int i = 0;
        int j = plants.length - 1;
        int waterA = capacityA;
        int waterB = capacityB;
        int refills = 0;

        while (i <= j) {
            if (i == j) {
                if (waterA >= waterB) {
                    if (waterA < plants[i]) {
                        refills++;
                        waterA = capacityA;
                    }
                    waterA -= plants[i];
                } else {
                    if (waterB < plants[j]) {
                        refills++;
                        waterB = capacityB;
                    }
                    waterB -= plants[j];
                }
                break;
            }

            if (waterA < plants[i]) {
                refills++;
                waterA = capacityA;
            }
            waterA -= plants[i];

            if (waterB < plants[j]) {
                refills++;
                waterB = capacityB;
            }
            waterB -= plants[j];

            i++;
            j--;
        }

        return refills;
    }
}

public class Solution {
    public static String firstPalindrome(String[] words) {
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            int left = 0;
            int right = word.length() - 1;
            boolean isPal = true;
            while (left < right) {
                if (word.charAt(left) != word.charAt(right)) {
                    isPal = false;
                    break;
                }
                left++;
                right--;
            }
            if (isPal) {
                return word;
            }
        }
        return "";
    }
}

