class Solution {
    public static int minOperations(int[] arr, int k) {
        int operations = 0;
        for (int offset = 0; offset < k; offset++) {
            List<Integer> subsequence = new ArrayList<>();
            for (int i = offset; i < arr.length; i += k) {
                subsequence.add(arr[i]);
            }
            List<Integer> tails = new ArrayList<>();
            for (int value : subsequence) {
                int left = 0, right = tails.size();
                while (left < right) {
                    int mid = (left + right) >>> 1;
                    if (tails.get(mid) > value) {
                        right = mid;
                    } else {
                        left = mid + 1;
                    }
                }
                if (left == tails.size()) {
                    tails.add(value);
                } else {
                    tails.set(left, value);
                }
            }
            operations += subsequence.size() - tails.size();
        }
        return operations;
    }
}

