class Solution {
    public static List<String> findAllRecipes(String[] recipes, List<List<String>> ingredients, String[] supplies) {
        Map<String, List<String>> adj = new HashMap<>();
        Map<String, Integer> indegree = new HashMap<>();

        for (int i = 0; i < recipes.length; i++) {
            indegree.put(recipes[i], ingredients.get(i).size());
            for (String ing : ingredients.get(i)) {
                adj.computeIfAbsent(ing, k -> new ArrayList<>()).add(recipes[i]);
            }
        }

        Deque<String> queue = new ArrayDeque<>(Arrays.asList(supplies));
        List<String> result = new ArrayList<>();

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            List<String> dependent = adj.get(cur);
            if (dependent == null) continue;
            for (String rec : dependent) {
                indegree.put(rec, indegree.get(rec) - 1);
                if (indegree.get(rec) == 0) {
                    result.add(rec);
                    queue.offer(rec);
                }
            }
        }

        return result;
    }
}

