class Solution {
    public int[] executeInstructions(int n, int[] startPos, String s) {
        int m = s.length();
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            int row = startPos[0];
            int col = startPos[1];
            int cnt = 0;
            for (int j = i; j < m; j++) {
                char c = s.charAt(j);
                if (c == 'L') col--;
                else if (c == 'R') col++;
                else if (c == 'U') row--;
                else if (c == 'D') row++;
                if (row < 0 || row >= n || col < 0 || col >= n) {
                    break;
                }
                cnt++;
            }
            answer[i] = cnt;
        }
        return answer;
    }
}

import java.math.BigInteger;

public class Solution {
    public String product(int left, int right) {
        int count2 = 0;
        int count5 = 0;
        BigInteger result = BigInteger.ONE;
        for (int i = left; i <= right; i++) {
            int x = i;
            while ((x & 1) == 0) {
                count2++;
                x >>= 1;
            }
            while (x % 5 == 0) {
                count5++;
                x /= 5;
            }
            result = result.multiply(BigInteger.valueOf(x));
        }
        int zeros = Math.min(count2, count5);
        int diff = count2 - count5;
        if (diff > 0) {
            result = result.shiftLeft(diff);
        } else if (diff < 0) {
            int d = -diff;
            result = result.multiply(BigInteger.valueOf(5).pow(d));
        }
        String s = result.toString();
        if (s.length() <= 10) {
            return s + "e" + zeros;
        } else {
            String first = s.substring(0, 5);
            String last = s.substring(s.length() - 5);
            return first + "..." + last + "e" + zeros;
        }
    }
}

