class Solution {
    public static long[] sumIntervals(int[] arr) {
        int n = arr.length;
        long[] answer = new long[n];
        Map<Integer, List<Integer>> groups = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int val = arr[i];
            groups.computeIfAbsent(val, k -> new ArrayList<>()).add(i);
        }

        for (List<Integer> indices : groups.values()) {
            int k = indices.size();
            if (k == 1) continue;

            long[] prefix = new long[k];
            prefix[0] = indices.get(0);
            for (int i = 1; i < k; i++) {
                prefix[i] = prefix[i - 1] + indices.get(i);
            }
            long total = prefix[k - 1];

            for (int i = 0; i < k; i++) {
                int idx = indices.get(i);
                int leftCount = i;
                int rightCount = k - 1 - i;
                long leftSum = i > 0 ? prefix[i - 1] : 0;
                long rightSum = total - prefix[i];
                answer[idx] = (long) idx * leftCount - leftSum + rightSum - (long) idx * rightCount;
            }
        }

        return answer;
    }
}

