class Solution {
    public int[] recoverArray(int[] nums) {
        int m = nums.length;
        Arrays.sort(nums);
        for (int i = 1; i < m; i++) {
            int diff = nums[i] - nums[0];
            if (diff <= 0 || diff % 2 != 0) continue;
            int k = diff / 2;
            Map<Integer, Integer> freq = new HashMap<>();
            for (int v : nums) {
                freq.put(v, freq.getOrDefault(v, 0) + 1);
            }
            List<Integer> original = new ArrayList<>();
            boolean ok = true;
            for (int v : nums) {
                int cnt = freq.getOrDefault(v, 0);
                if (cnt == 0) continue;
                int partner = v + 2 * k;
                int cntPartner = freq.getOrDefault(partner, 0);
                if (cntPartner == 0) {
                    ok = false;
                    break;
                }
                freq.put(v, cnt - 1);
                freq.put(partner, cntPartner - 1);
                original.add(v + k);
            }
            if (ok && original.size() == m / 2) {
                int[] res = new int[original.size()];
                for (int j = 0; j < original.size(); j++) {
                    res[j] = original.get(j);
                }
                return res;
            }
        }
        return new int[0];
    }
}

