class ListNode {
    int val;
    ListNode next;
    ListNode(int val) {
        this.val = val;
    }
    ListNode(int val, ListNode next) {
        this.val = val;
        this.next = next;
    }
}

class Solution {
    public static int maxTwinSum(ListNode head) {
        if (head == null) return 0;

        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            fast = fast.next.next;
            slow = slow.next;
        }

        ListNode prev = null, curr = slow;
        while (curr != null) {
            ListNode nxt = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nxt;
        }

        int maxSum = 0;
        ListNode p1 = head, p2 = prev;
        while (p2 != null) {
            int sum = p1.val + p2.val;
            if (sum > maxSum) maxSum = sum;
            p1 = p1.next;
            p2 = p2.next;
        }

        curr = prev;
        prev = null;
        while (curr != null) {
            ListNode nxt = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nxt;
        }

        return maxSum;
    }
}

class Solution {
    public static String capitalizeTitle(String title) {
        String[] words = title.split(" ");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            String transformed;
            if (word.length() < 3) {
                transformed = word.toLowerCase();
            } else {
                transformed = word.substring(0, 1).toUpperCase() + word.substring(1).toLowerCase();
            }
            sb.append(transformed);
            if (i < words.length - 1) {
                sb.append(' ');
            }
        }
        return sb.toString();
    }
}

