public class Solution {
    public int maximumInvitations(int[] favorite) {
        int n = favorite.length;
        List<Integer>[] rev = new ArrayList[n];
        for (int i = 0; i < n; i++) rev[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) rev[favorite[i]].add(i);

        boolean[] inCycle = new boolean[n];
        boolean[] done = new boolean[n];
        int[] idx = new int[n];
        Arrays.fill(idx, -1);
        int maxCycle = 0;

        for (int i = 0; i < n; i++) {
            if (done[i]) continue;
            List<Integer> path = new ArrayList<>();
            int cur = i;
            while (!done[cur] && idx[cur] == -1) {
                idx[cur] = path.size();
                path.add(cur);
                cur = favorite[cur];
            }
            if (!done[cur] && idx[cur] != -1) {
                int cycleLen = path.size() - idx[cur];
                for (int k = idx[cur]; k < path.size(); k++) {
                    inCycle[path.get(k)] = true;
                }
                maxCycle = Math.max(maxCycle, cycleLen);
            }
            for (int node : path) {
                done[node] = true;
                idx[node] = -1;
            }
        }

        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) indeg[i] = rev[i].size();

        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) queue.add(i);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            int v = favorite[u];
            if (dp[v] < dp[u] + 1) dp[v] = dp[u] + 1;
            indeg[v]--;
            if (indeg[v] == 0) queue.add(v);
        }

        int sumPairs = 0;
        for (int i = 0; i < n; i++) {
            int j = favorite[i];
            if (i < j && favorite[j] == i) {
                sumPairs += dp[i] + dp[j];
            }
        }

        return Math.max(maxCycle, sumPairs);
    }
}

