class Solution {
    public static int numberOfBeams(String[] bank) {
        int prevDeviceCount = 0;
        int totalBeams = 0;
        for (String row : bank) {
            int curDeviceCount = 0;
            for (int i = 0; i < row.length(); i++) {
                if (row.charAt(i) == '1') {
                    curDeviceCount++;
                }
            }
            if (curDeviceCount > 0) {
                totalBeams += prevDeviceCount * curDeviceCount;
                prevDeviceCount = curDeviceCount;
            }
        }
        return totalBeams;
    }
}

