class Solution {
    public static int minSwaps(int[] nums) {
        int n = nums.length;
        int totalOnes = 0;
        for (int i = 0; i < n; i++) totalOnes += nums[i];
        if (totalOnes <= 1) return 0;
        int windowOnes = 0;
        for (int i = 0; i < totalOnes; i++) windowOnes += nums[i];
        int minZeros = totalOnes - windowOnes;
        for (int start = 1; start < n; start++) {
            windowOnes -= nums[start - 1];
            int enteringIdx = (start + totalOnes - 1) % n;
            windowOnes += nums[enteringIdx];
            int zeros = totalOnes - windowOnes;
            if (zeros < minZeros) minZeros = zeros;
        }
        return minZeros;
    }
}

