class Solution {
    private static class Seed {
        int plant;
        int grow;
        Seed(int plant, int grow) {
            this.plant = plant;
            this.grow = grow;
        }
    }

    public static int earliestFullBloom(int[] plantTime, int[] growTime) {
        int n = plantTime.length;
        Seed[] seeds = new Seed[n];
        for (int i = 0; i < n; i++) {
            seeds[i] = new Seed(plantTime[i], growTime[i]);
        }
        Arrays.sort(seeds, (a, b) -> b.grow - a.grow);
        int currentDay = 0;
        int earliestAllBloom = 0;
        for (int i = 0; i < n; i++) {
            currentDay += seeds[i].plant;
            earliestAllBloom = Math.max(earliestAllBloom, currentDay + seeds[i].grow);
        }
        return earliestAllBloom;
    }
}

