class Solution {
    public boolean possibleToStamp(int[][] grid, int stampHeight, int stampWidth) {
        int m = grid.length;
        int n = grid[0].length;

        // Prefix sum of the original grid to query number of ones in any rectangle
        int[][] pref = new int[m + 1][n + 1];
        for (int i = 0; i < m; i++) {
            int rowSum = 0;
            for (int j = 0; j < n; j++) {
                rowSum += grid[i][j];
                pref[i + 1][j + 1] = pref[i][j + 1] + rowSum;
            }
        }

        // Difference array to mark coverage of feasible stamps
        int[][] diff = new int[m + 1][n + 1];

        for (int i = 0; i + stampHeight <= m; i++) {
            for (int j = 0; j + stampWidth <= n; j++) {
                int ones = pref[i + stampHeight][j + stampWidth] - pref[i][j + stampWidth]
                         - pref[i + stampHeight][j] + pref[i][j];
                if (ones == 0) {
                    diff[i][j] += 1;
                    diff[i + stampHeight][j] -= 1;
                    diff[i][j + stampWidth] -= 1;
                    diff[i + stampHeight][j + stampWidth] += 1;
                }
            }
        }

        // Compute coverage and verify each zero cell is covered
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) diff[i][j] += diff[i - 1][j];
                if (j > 0) diff[i][j] += diff[i][j - 1];
                if (i > 0 && j > 0) diff[i][j] -= diff[i - 1][j - 1];
                if (grid[i][j] == 0 && diff[i][j] == 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

