class Solution {
    public static List<String> divideString(String s, int k, String fill) {
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += k) {
            String chunk = s.substring(i, Math.min(i + k, s.length()));
            if (chunk.length() < k) {
                chunk = chunk + fill.repeat(k - chunk.length());
            }
            groups.add(chunk);
        }
        return groups;
    }
}

public class Solution {
    public static int maxPoints(int[][] questions) {
        int n = questions.length;
        int[] dp = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            int points = questions[i][0];
            int brain = questions[i][1];
            int take = points + (i + brain + 1 <= n ? dp[i + brain + 1] : 0);
            int skip = dp[i + 1];
            dp[i] = Math.max(take, skip);
        }
        return dp[0];
    }
}

