class Solution {
    public static int countWords(String[] startWords, String[] targetWords) {
        Set<String> startSet = new HashSet<>();
        for (String w : startWords) {
            char[] chars = w.toCharArray();
            Arrays.sort(chars);
            startSet.add(new String(chars));
        }
        int answer = 0;
        for (String t : targetWords) {
            char[] chars = t.toCharArray();
            Arrays.sort(chars);
            String sortedTarget = new String(chars);
            for (int i = 0; i < sortedTarget.length(); i++) {
                if (i > 0 && sortedTarget.charAt(i) == sortedTarget.charAt(i - 1)) continue;
                String candidate = sortedTarget.substring(0, i) + sortedTarget.substring(i + 1);
                if (startSet.contains(candidate)) {
                    answer++;
                    break;
                }
            }
        }
        return answer;
    }
}

