class Solution {
    public static long countHiddenSequences(int[] differences, long lower, long upper) {
        long pref = 0;
        long minPref = 0;
        long maxPref = 0;
        for (int d : differences) {
            pref += d;
            if (pref < minPref) minPref = pref;
            if (pref > maxPref) maxPref = pref;
        }
        long low0 = lower - minPref;
        long high0 = upper - maxPref;
        return high0 >= low0 ? high0 - low0 + 1 : 0;
    }
}

