class Solution {
    public static int maxRunTime(int n, int[] batteries) {
        if (batteries == null || batteries.length < n) return 0;
        long total = 0;
        for (int b : batteries) total += b;
        long low = 0;
        long high = total / n;
        while (low < high) {
            long mid = (low + high + 1) / 2;
            long possible = 0;
            for (int b : batteries) possible += Math.min(b, mid);
            if (possible >= (long) n * mid) low = mid;
            else high = mid - 1;
        }
        return (int) low;
    }
}

