class Solution {
    public String subStr(String s, int power, int modulo, int k, int hashValue) {
        int n = s.length();
        long mod = modulo;
        long pow = power % mod;

        long powerK = 1;
        for (int i = 0; i < k; i++) {
            powerK = (powerK * pow) % mod;
        }

        int start = n - k;
        long cur = 0;
        long mul = 1;
        for (int j = 0; j < k; j++) {
            int val = s.charAt(start + j) - 'a' + 1;
            cur = (cur + val * mul) % mod;
            mul = (mul * pow) % mod;
        }

        int ansIdx = -1;
        if (cur == hashValue) {
            ansIdx = start;
        }

        for (int i = start - 1; i >= 0; i--) {
            int leftVal = s.charAt(i) - 'a' + 1;
            int rightVal = s.charAt(i + k) - 'a' + 1;
            cur = (leftVal + (pow * cur) % mod - (rightVal * powerK) % mod) % mod;
            if (cur < 0) {
                cur += mod;
            }
            if (cur == hashValue) {
                ansIdx = i;
            }
        }

        return s.substring(ansIdx, ansIdx + k);
    }
}

