class Solution {
    public static int maximumGood(int[][] statements) {
        int n = statements.length;
        int best = 0;
        int totalMasks = 1 << n;
        for (int mask = 0; mask < totalMasks; mask++) {
            int goodCount = Integer.bitCount(mask);
            if (goodCount <= best) continue;
            boolean ok = true;
            for (int i = 0; i < n && ok; i++) {
                if (((mask >> i) & 1) == 1) {
                    for (int j = 0; j < n; j++) {
                        int stmt = statements[i][j];
                        if (stmt == 2) continue;
                        boolean jIsGood = ((mask >> j) & 1) == 1;
                        if (stmt == 1 && !jIsGood) {
                            ok = false;
                            break;
                        }
                        if (stmt == 0 && jIsGood) {
                            ok = false;
                            break;
                        }
                    }
                }
            }
            if (ok) best = goodCount;
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int[] groupStrings(String[] words) {
        int n = words.length;
        int[] masks = new int[n];
        DSU dsu = new DSU(n);
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (char ch : words[i].toCharArray()) {
                mask |= 1 << (ch - 'a');
            }
            masks[i] = mask;
            Integer existing = map.get(mask);
            if (existing != null) {
                dsu.union(i, existing);
            } else {
                map.put(mask, i);
            }
        }

        for (int i = 0; i < n; i++) {
            int mask = masks[i];
            // Add or delete a single letter
            for (int c = 0; c < 26; c++) {
                int bit = 1 << c;
                int neighborMask = (mask & bit) != 0 ? (mask ^ bit) : (mask | bit);
                Integer idx = map.get(neighborMask);
                if (idx != null) {
                    dsu.union(i, idx);
                }
            }
            // Replace one letter with another
            for (int c = 0; c < 26; c++) {
                int bitC = 1 << c;
                if ((mask & bitC) == 0) continue; // c must be present to replace
                for (int d = 0; d < 26; d++) {
                    int bitD = 1 << d;
                    if ((mask & bitD) != 0) continue; // d must be absent
                    int neighborMask = (mask ^ bitC) | bitD;
                    Integer idx = map.get(neighborMask);
                    if (idx != null) {
                        dsu.union(i, idx);
                    }
                }
            }
        }

        int groups = 0;
        int maxSize = 0;
        for (int i = 0; i < n; i++) {
            if (dsu.parent[i] == i) groups++;
            maxSize = Math.max(maxSize, dsu.size[dsu.find(i)]);
        }
        return new int[]{groups, maxSize};
    }

    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }
}

