class Solution {
    public static List<Integer> maxScoreDivisions(int[] nums) {
        int n = nums.length;
        int totalOnes = 0;
        for (int v : nums) totalOnes += v;
        int zerosLeft = 0;
        int onesSeen = 0;
        int maxScore = -1;
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            int onesRight = totalOnes - onesSeen;
            int score = zerosLeft + onesRight;
            if (score > maxScore) {
                maxScore = score;
                result.clear();
                result.add(i);
            } else if (score == maxScore) {
                result.add(i);
            }
            if (i < n) {
                if (nums[i] == 0) zerosLeft++;
                else onesSeen++;
            }
        }
        return result;
    }
}

