class Solution {
    public int minCost(int startAt, int moveCost, int pushCost, int targetSeconds) {
        int best = Integer.MAX_VALUE;
        for (int minutes = 0; minutes <= 99; minutes++) {
            int seconds = targetSeconds - minutes * 60;
            if (seconds < 0 || seconds > 99) continue;
            String mm = String.format("%02d", minutes);
            String ss = String.format("%02d", seconds);
            String code = mm + ss; // four digits
            int leadingZeros = 0;
            while (leadingZeros < 4 && code.charAt(leadingZeros) == '0') {
                leadingZeros++;
            }
            for (int omit = 0; omit <= leadingZeros; omit++) {
                String typed = code.substring(omit);
                int cost = computeCost(startAt, moveCost, pushCost, typed);
                if (cost < best) best = cost;
            }
        }
        return best;
    }

    private int computeCost(int startAt, int moveCost, int pushCost, String typed) {
        int cost = 0;
        int prev = startAt;
        for (int i = 0; i < typed.length(); i++) {
            int cur = typed.charAt(i) - '0';
            if (i == 0) {
                if (cur != startAt) cost += moveCost;
            } else {
                if (cur != prev) cost += moveCost;
            }
            cost += pushCost;
            prev = cur;
        }
        return cost;
    }
}

import java.util.PriorityQueue;
import java.util.Collections;

class Solution {
    public static long minimumDifference(int[] nums) {
        int m = nums.length;
        int n = m / 3;

        long[] left = new long[m + 1];
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long sumLeft = 0;
        for (int i = 0; i < n; i++) {
            sumLeft += nums[i];
            maxHeap.add(nums[i]);
        }
        left[n] = sumLeft;
        for (int i = n; i < 2 * n; i++) {
            int val = nums[i];
            if (val < maxHeap.peek()) {
                sumLeft += val - maxHeap.poll();
                maxHeap.add(val);
            }
            left[i + 1] = sumLeft;
        }

        long[] right = new long[m + 1];
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        long sumRight = 0;
        for (int i = m - n; i < m; i++) {
            sumRight += nums[i];
            minHeap.add(nums[i]);
        }
        right[2 * n] = sumRight;
        for (int i = 2 * n - 1; i >= n; i--) {
            int val = nums[i];
            if (val > minHeap.peek()) {
                sumRight += val - minHeap.poll();
                minHeap.add(val);
            }
            right[i] = sumRight;
        }

        long ans = Long.MAX_VALUE;
        for (int i = n; i <= 2 * n; i++) {
            long diff = left[i] - right[i];
            if (diff < ans) {
                ans = diff;
            }
        }
        return ans;
    }
}

