class Solution {
    public static long smallestRearrangedNumber(long num) {
        if (num == 0) return 0;
        long sign = Long.signum(num);
        String absStr = Long.toString(Math.abs(num));
        char[] digits = absStr.toCharArray();
        if (sign >= 0) {
            Arrays.sort(digits);
            if (digits[0] == '0') {
                int firstNonZero = -1;
                for (int i = 1; i < digits.length; i++) {
                    if (digits[i] != '0') {
                        firstNonZero = i;
                        break;
                    }
                }
                if (firstNonZero != -1) {
                    char temp = digits[0];
                    digits[0] = digits[firstNonZero];
                    digits[firstNonZero] = temp;
                }
            }
            return Long.parseLong(new String(digits));
        } else {
            Arrays.sort(digits);
            for (int i = 0, j = digits.length - 1; i < j; i++, j--) {
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
            }
            return Long.parseLong("-" + new String(digits));
        }
    }
}

public class Bitset {
    private final byte[] bits;
    private final int size;
    private boolean flipped;
    private int onesCount;

    public Bitset(int size) {
        this.size = size;
        this.bits = new byte[size];
        this.flipped = false;
        this.onesCount = 0;
    }

    public void fix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 0) {
            bits[idx] = (byte) (flipped ? 0 : 1);
            onesCount++;
        }
    }

    public void unfix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 1) {
            bits[idx] = (byte) (flipped ? 1 : 0);
            onesCount--;
        }
    }

    public void flip() {
        flipped = !flipped;
        onesCount = size - onesCount;
    }

    public int all() {
        return onesCount == size ? 1 : 0;
    }

    public int one() {
        return onesCount > 0 ? 1 : 0;
    }

    public int count() {
        return onesCount;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder(size);
        for (int i = 0; i < size; i++) {
            sb.append(bits[i] ^ (flipped ? 1 : 0));
        }
        return sb.toString();
    }
}

