class Solution {
    public int minOperations(int[] nums) {
        Map<Integer, Integer> evenCount = new HashMap<>();
        Map<Integer, Integer> oddCount = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if ((i & 1) == 0) {
                evenCount.merge(nums[i], 1, Integer::sum);
            } else {
                oddCount.merge(nums[i], 1, Integer::sum);
            }
        }

        int[] evenTop = topTwo(evenCount);
        int[] oddTop = topTwo(oddCount);

        int maxEvenVal = evenTop[0];
        int maxEvenCnt = evenTop[1];
        int secondEvenCnt = evenTop[2];

        int maxOddVal = oddTop[0];
        int maxOddCnt = oddTop[1];
        int secondOddCnt = oddTop[2];

        int n = nums.length;
        if (maxEvenVal != maxOddVal) {
            return n - (maxEvenCnt + maxOddCnt);
        } else {
            int keep1 = maxEvenCnt + secondOddCnt;
            int keep2 = secondEvenCnt + maxOddCnt;
            int keep = Math.max(keep1, keep2);
            return n - keep;
        }
    }

    private int[] topTwo(Map<Integer, Integer> map) {
        int firstVal = -1, firstCnt = 0, secondCnt = 0;
        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            int cnt = e.getValue();
            if (cnt > firstCnt) {
                secondCnt = firstCnt;
                firstCnt = cnt;
                firstVal = e.getKey();
            } else if (cnt > secondCnt) {
                secondCnt = cnt;
            }
        }
        return new int[]{firstVal, firstCnt, secondCnt};
    }
}

