class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int totalPositions = numSlots * 2;
        int maxMask = 1 << totalPositions;
        int[] memo = new int[maxMask];
        Arrays.fill(memo, -1);
        return dfs(0, 0, nums, numSlots, memo);
    }

    private int dfs(int idx, int mask, int[] nums, int numSlots, int[] memo) {
        if (idx == nums.length) {
            return 0;
        }
        if (memo[mask] != -1) {
            return memo[mask];
        }
        int best = 0;
        for (int slot = 1; slot <= numSlots; slot++) {
            for (int pos = 0; pos < 2; pos++) {
                int bit = (slot - 1) * 2 + pos;
                if ((mask & (1 << bit)) == 0) {
                    int newMask = mask | (1 << bit);
                    int candidate = (nums[idx] & slot) + dfs(idx + 1, newMask, nums, numSlots, memo);
                    if (candidate > best) {
                        best = candidate;
                    }
                }
            }
        }
        memo[mask] = best;
        return best;
    }
}

