class Solution {
    public static long[] maximumSplit(long finalSum) {
        if (finalSum % 2 != 0) return new long[0];
        List<Long> result = new ArrayList<>();
        long next = 2;
        long remaining = finalSum;
        while (remaining >= next) {
            result.add(next);
            remaining -= next;
            next += 2;
        }
        if (remaining > 0) result.set(result.size()-1, result.get(result.size()-1) + remaining);
        long[] arr = new long[result.size()];
        for (int i = 0; i < arr.length; i++) arr[i] = result.get(i);
        return arr;
    }
}

