class Solution {
    public static String repeatLimitedString(String s, int repeatLimit) {
        int[] cnt = new int[26];
        for (int i = 0; i < s.length(); i++) {
            cnt[s.charAt(i) - 'a']++;
        }
        StringBuilder res = new StringBuilder();
        int lastIdx = -1;
        int lastRun = 0;
        while (true) {
            int i = 25;
            while (i >= 0 && cnt[i] == 0) i--;
            if (i < 0) break;
            if (i == lastIdx && lastRun == repeatLimit) {
                int j = i - 1;
                while (j >= 0 && cnt[j] == 0) j--;
                if (j < 0) break;
                res.append((char) (j + 'a'));
                cnt[j]--;
                lastIdx = j;
                lastRun = 1;
            } else {
                res.append((char) (i + 'a'));
                cnt[i]--;
                if (i == lastIdx) {
                    lastRun++;
                } else {
                    lastIdx = i;
                    lastRun = 1;
                }
            }
        }
        return res.toString();
    }
}

