        }

        int[] leftLess = new int[n];
        Fenwick bit = new Fenwick(n);
        for (int i = 0; i < n; i++) {
            leftLess[i] = bit.query(p[i]);
            bit.update(p[i] + 1, 1);
        }

        int[] rightGreater = new int[n];
        bit = new Fenwick(n);
        for (int i = n - 1; i >= 0; i--) {
            int totalSeen = bit.query(n);
            int notGreater = bit.query(p[i] + 1);
            rightGreater[i] = totalSeen - notGreater;
            bit.update(p[i] + 1, 1);
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            ans += (long) leftLess[i] * rightGreater[i];
        }
        return ans;
    }

    private static class Fenwick {
        private final int size;
        private final int[] tree;

        Fenwick(int n) {
            size = n;
            tree = new int[n + 2];
        }

        void update(int index, int delta) {
            while (index <= size) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        int query(int index) {
            int sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }
    }
}

