class Solution {
    public static long countPairs(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        long result = 0;
        for (int num : nums) {
            int g = gcd(num, k);
            for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
                int prevG = entry.getKey();
                int cnt = entry.getValue();
                if ((long) g * prevG % k == 0) {
                    result += cnt;
                }
            }
            freq.put(g, freq.getOrDefault(g, 0) + 1);
        }
        return result;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

