class Solution {
    public static int[] sortJumbled(int[] mapping, int[] nums) {
        class Item {
            int orig;
            int mapped;
            int idx;
            Item(int o, int m, int i) {
                orig = o;
                mapped = m;
                idx = i;
            }
        }
        Item[] items = new Item[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            String s = Integer.toString(num);
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < s.length(); j++) {
                int digit = s.charAt(j) - '0';
                sb.append(mapping[digit]);
            }
            int mappedVal = Integer.parseInt(sb.toString());
            items[i] = new Item(num, mappedVal, i);
        }
        Arrays.sort(items, (a, b) -> {
            if (a.mapped != b.mapped) return Integer.compare(a.mapped, b.mapped);
            return Integer.compare(a.idx, b.idx);
        });
        int[] result = new int[nums.length];
        for (int i = 0; i < items.length; i++) {
            result[i] = items[i].orig;
        }
        return result;
    }
}

