class Solution {
    public static List<List<Integer>> getAncestors(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        int[] indeg = new int[n];
        for (int[] e : edges) {
            int from = e[0];
            int to = e[1];
            adj[from].add(to);
            indeg[to]++;
        }
        List<Set<Integer>> ancestors = new ArrayList<>(n);
        for (int i = 0; i < n; i++) ancestors.add(new HashSet<>());
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) queue.add(i);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                ancestors.get(v).add(u);
                for (int anc : ancestors.get(u)) {
                    ancestors.get(v).add(anc);
                }
                indeg[v]--;
                if (indeg[v] == 0) queue.add(v);
            }
        }
        List<List<Integer>> result = new ArrayList<>(n);
        for (Set<Integer> set : ancestors) {
            List<Integer> list = new ArrayList<>(set);
            Collections.sort(list);
            result.add(list);
        }
        return result;
    }
}

