public class Solution {
    public static long minimumTime(int[] time, int totalTrips) {
        long left = 1;
        int min = Integer.MAX_VALUE;
        for (int t : time) {
            if (t < min) min = t;
        }
        long right = (long) min * totalTrips;
        while (left < right) {
            long mid = (left + right) / 2;
            long trips = 0;
            for (int t : time) {
                trips += mid / t;
                if (trips >= totalTrips) break;
            }
            if (trips >= totalTrips) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

