class Solution {
    public long minimumFinishTime(int[][] tires, int changeTime, int numLaps) {
        long INF = Long.MAX_VALUE / 4;
        long[] best = new long[numLaps + 1];
        Arrays.fill(best, INF);
        for (int[] tire : tires) {
            long f = tire[0];
            long r = tire[1];
            long lap = f;
            long sum = 0;
            for (int k = 1; k <= numLaps; k++) {
                sum += lap;
                if (sum < best[k]) best[k] = sum;
                // prepare next lap
                if (lap > INF / r) break; // would overflow, stop
                long nextLap = lap * r;
                if (nextLap > changeTime + f) break; // better to change before next lap
                lap = nextLap;
            }
        }
        long[] dp = new long[numLaps + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= numLaps; i++) {
            dp[i] = best[i];
            for (int j = 1; j < i; j++) {
                if (best[i - j] == INF) continue;
                long cand = dp[j] + changeTime + best[i - j];
                if (cand < dp[i]) dp[i] = cand;
            }
        }
        return dp[numLaps];
    }
}

