class Solution {
    public int[] replaceNonCoprime(int[] nums) {
        int n = nums.length;
        int[] stack = new int[n];
        int sz = 0;
        for (int x : nums) {
            stack[sz++] = x;
            while (sz >= 2) {
                int a = stack[sz - 2];
                int b = stack[sz - 1];
                int g = gcd(a, b);
                if (g > 1) {
                    long lcm = (long) a / g * b;
                    stack[sz - 2] = (int) lcm;
                    sz--; // remove b
                } else {
                    break;
                }
            }
        }
        return Arrays.copyOf(stack, sz);
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

