class Solution {
    public static int minMovesToMakePalindrome(String s) {
        char[] arr = s.toCharArray();
        int i = 0;
        int j = arr.length - 1;
        int moves = 0;
        while (i < j) {
            if (arr[i] == arr[j]) {
                i++;
                j--;
                continue;
            }
            int k = j;
            while (k > i && arr[k] != arr[i]) {
                k--;
            }
            if (k == i) {
                char temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                moves++;
            } else {
                while (k < j) {
                    char temp = arr[k];
                    arr[k] = arr[k + 1];
                    arr[k + 1] = temp;
                    moves++;
                    k++;
                }
                i++;
                j--;
            }
        }
        return moves;
    }
}

