class Solution {
    public static List<Integer> findKDistantIndices(int[] nums, int key, int k) {
        int n = nums.length;
        List<Integer> keyPos = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums[i] == key) {
                keyPos.add(i);
            }
        }
        List<Integer> result = new ArrayList<>();
        int ptr = 0;
        for (int i = 0; i < n; i++) {
            while (ptr < keyPos.size() && keyPos.get(ptr) < i - k) {
                ptr++;
            }
            if (ptr < keyPos.size() && keyPos.get(ptr) <= i + k) {
                result.add(i);
            }
        }
        return result;
    }
}

