class Solution {
    public int maximumTop(int[] nums, int k) {
        int n = nums.length;
        if (k == 0) {
            return nums[0];
        }
        if (n == 1) {
            return (k % 2 == 1) ? -1 : nums[0];
        }
        int max = Integer.MIN_VALUE;
        int limit = Math.min(k - 1, n);
        for (int i = 0; i < limit; i++) {
            if (nums[i] > max) {
                max = nums[i];
            }
        }
        if (k < n) {
            max = Math.max(max, nums[k]);
        }
        return max == Integer.MIN_VALUE ? -1 : max;
    }
}

