class Solution {
    private static final long INF = Long.MAX_VALUE / 4;

    public long minimumWeight(int n, int[][] edges, int src1, int src2, int dest) {
        List<int[]>[] graph = new ArrayList[n];
        List<int[]>[] revGraph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
            revGraph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int from = e[0];
            int to = e[1];
            int w = e[2];
            graph[from].add(new int[]{to, w});
            revGraph[to].add(new int[]{from, w});
        }

        long[] dist1 = dijkstra(graph, src1);
        long[] dist2 = dijkstra(graph, src2);
        long[] distDest = dijkstra(revGraph, dest); // distances to dest in original graph

        long answer = INF;
        for (int v = 0; v < n; v++) {
            if (dist1[v] == INF || dist2[v] == INF || distDest[v] == INF) continue;
            long total = dist1[v] + dist2[v] + distDest[v];
            if (total < answer) answer = total;
        }
        return answer == INF ? -1 : answer;
    }

    private long[] dijkstra(List<int[]>[] graph, int src) {
        int n = graph.length;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            for (int[] e : graph[u]) {
                int v = e[0];
                int w = e[1];
                long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new long[]{nd, v});
                }
            }
        }
        return dist;
    }
}

