class Solution {
    public static int minOperations(int[] nums) {
        double total = 0;
        for (int v : nums) total += v;
        double target = total / 2.0;
        PriorityQueue<Double> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int v : nums) heap.offer((double) v);
        double saved = 0;
        int ops = 0;
        while (saved < target) {
            double cur = heap.poll();
            double half = cur / 2.0;
            saved += half;
            heap.offer(half);
            ops++;
        }
        return ops;
    }
}

