class Solution {
    public long maximumSubsequenceCount(String text, String pattern) {
        char first = pattern.charAt(0);
        char second = pattern.charAt(1);
        if (first == second) {
            long cnt = 0;
            for (char c : text.toCharArray()) {
                if (c == first) cnt++;
            }
            return cnt * (cnt + 1) / 2;
        }
        long countFirst = 0;
        long countSecond = 0;
        long base = 0;
        for (char c : text.toCharArray()) {
            if (c == first) {
                countFirst++;
            } else if (c == second) {
                base += countFirst;
                countSecond++;
            }
        }
        long bestIncrease = Math.max(countFirst, countSecond);
        return base + bestIncrease;
    }
}

