class Solution {
    public static int minimumWhiteTiles(String floor, int numCarpets, int carpetLen) {
        int n = floor.length();
        int[] white = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            white[i] = white[i - 1] + (floor.charAt(i - 1) == '1' ? 1 : 0);
        }
        int[][] dp = new int[numCarpets + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            dp[0][i] = white[i];
        }
        for (int c = 1; c <= numCarpets; c++) {
            for (int i = 1; i <= n; i++) {
                int best = dp[c][i - 1] + (floor.charAt(i - 1) == '1' ? 1 : 0);
                int prevIdx = i - carpetLen >= 0 ? i - carpetLen : 0;
                best = Math.min(best, dp[c - 1][prevIdx]);
                dp[c][i] = best;
            }
        }
        return dp[numCarpets][n];
    }
}

