public class Solution {
    public int[] maximumBobPoints(int numArrows, int[] aliceArrows) {
        int n = 12;
        int bestScore = -1;
        int bestMask = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            int arrowsNeeded = 0;
            int score = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    arrowsNeeded += aliceArrows[i] + 1;
                    score += i;
                }
            }
            if (arrowsNeeded <= numArrows && score > bestScore) {
                bestScore = score;
                bestMask = mask;
            }
        }
        int[] bobArrows = new int[n];
        int used = 0;
        for (int i = 0; i < n; i++) {
            if ((bestMask & (1 << i)) != 0) {
                bobArrows[i] = aliceArrows[i] + 1;
                used += bobArrows[i];
            }
        }
        bobArrows[0] += numArrows - used;
        return bobArrows;
    }
}

