class Solution {
    public int[] longestRepeatingSubstring(String s, String queryCharacters, int[] queryIndices) {
        int n = s.length();
        char[] arr = s.toCharArray();
        TreeMap<Integer, Interval> intervals = new TreeMap<>();
        TreeMap<Integer, Integer> lenCount = new TreeMap<>();

        // Initialize intervals
        int i = 0;
        while (i < n) {
            int j = i;
            while (j + 1 < n && arr[j + 1] == arr[i]) {
                j++;
            }
            Interval iv = new Interval(i, j, arr[i]);
            intervals.put(i, iv);
            addLen(lenCount, iv.length());
            i = j + 1;
        }

        int k = queryCharacters.length();
        int[] answer = new int[k];

        for (int q = 0; q < k; q++) {
            char newChar = queryCharacters.charAt(q);
            int idx = queryIndices[q];

            if (arr[idx] != newChar) {
                // Find interval containing idx
                Map.Entry<Integer, Interval> entry = intervals.floorEntry(idx);
                Interval cur = entry.getValue();
                int curStart = entry.getKey();
                int curEnd = cur.end;
                char curChar = cur.ch;

                // Remove old interval length
                removeLen(lenCount, cur.length());
                intervals.remove(curStart);

                // Left part after removal
                if (curStart <= idx - 1) {
                    Interval leftPart = new Interval(curStart, idx - 1, curChar);
                    intervals.put(curStart, leftPart);
                    addLen(lenCount, leftPart.length());
                }
                // Right part after removal
                if (idx + 1 <= curEnd) {
                    Interval rightPart = new Interval(idx + 1, curEnd, curChar);
                    intervals.put(idx + 1, rightPart);
                    addLen(lenCount, rightPart.length());
                }

                // Merge with possible neighboring intervals of newChar
                int newStart = idx;
                int newEnd = idx;

                Map.Entry<Integer, Interval> leftEntry = intervals.lowerEntry(idx);
                if (leftEntry != null) {
                    Interval leftInt = leftEntry.getValue();
                    if (leftInt.end == idx - 1 && leftInt.ch == newChar) {
                        newStart = leftEntry.getKey();
                        removeLen(lenCount, leftInt.length());
                        intervals.remove(leftEntry.getKey());
                    }
                }

                Map.Entry<Integer, Interval> rightEntry = intervals.ceilingEntry(idx + 1);
                if (rightEntry != null) {
                    Interval rightInt = rightEntry.getValue();
                    if (rightInt.start == idx + 1 && rightInt.ch == newChar) {
                        newEnd = rightInt.end;
                        removeLen(lenCount, rightInt.length());
                        intervals.remove(rightEntry.getKey());
                    }
                }

                Interval merged = new Interval(newStart, newEnd, newChar);
                intervals.put(newStart, merged);
                addLen(lenCount, merged.length());

                arr[idx] = newChar;
            }

            answer[q] = lenCount.lastKey();
        }

        return answer;
    }

    private void addLen(TreeMap<Integer, Integer> map, int len) {
        map.merge(len, 1, Integer::sum);
    }

    private void removeLen(TreeMap<Integer, Integer> map, int len) {
        int cnt = map.get(len);
        if (cnt == 1) {
            map.remove(len);
        } else {
            map.put(len, cnt - 1);
        }
    }
}

class Interval {
    int start;
