public class Solution {
    public int minDeletion(int[] nums) {
        int pairs = 0;
        int waiting = -1;
        for (int x : nums) {
            if (waiting == -1) {
                waiting = x;
            } else {
                if (x > waiting) {
                    pairs++;
                    waiting = -1;
                } else {
                    waiting = x;
                }
            }
        }
        return nums.length - pairs * 2;
    }
}

import java.util.*;

class Solution {
    public static int maxValueOfCoins(int[][] piles, int k) {
        List<long[]> pref = new ArrayList<>();
        for (int[] p : piles) {
            long[] pre = new long[p.length + 1];
            pre[0] = 0;
            for (int i = 0; i < p.length; i++) {
                pre[i + 1] = pre[i] + p[i];
            }
            pref.add(pre);
        }

        long sentinel = Long.MIN_VALUE / 4;
        long[] dp = new long[k + 1];
        Arrays.fill(dp, sentinel);
        dp[0] = 0;

        for (int i = 0; i < piles.length; i++) {
            long[] curPref = pref.get(i);
            int sz = curPref.length - 1;
            long[] next = new long[k + 1];
            Arrays.fill(next, sentinel);

            for (int taken = 0; taken <= k; taken++) {
                int maxX = Math.min(sz, taken);
                for (int x = 0; x <= maxX; x++) {
                    if (dp[taken - x] == sentinel) continue;
                    long candidate = dp[taken - x] + curPref[x];
                    if (candidate > next[taken]) {
                        next[taken] = candidate;
                    }
                }
            }
            dp = next;
        }

        return (int) dp[k];
    }
}

