class Solution {
    public long[] kthPalindrome(int[] queries, int intLength) {
        int halfLen = (intLength + 1) / 2;
        long start = (long) Math.pow(10, halfLen - 1);
        long total = 9L * (long) Math.pow(10, halfLen - 1);
        long[] ans = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long k = queries[i];
            if (k > total) {
                ans[i] = -1;
            } else {
                long left = start + k - 1;
                String leftStr = Long.toString(left);
                StringBuilder sb = new StringBuilder(leftStr);
                String rev;
                if (intLength % 2 == 0) {
                    rev = sb.reverse().toString();
                } else {
                    rev = sb.deleteCharAt(sb.length() - 1).reverse().toString();
                }
                String palindromeStr = leftStr + rev;
                ans[i] = Long.parseLong(palindromeStr);
            }
        }
        return ans;
    }
}

