public class Solution {
    public static long numberOfWays(String s) {
        int n = s.length();
        if (n < 3) return 0;
        int totalZero = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') totalZero++;
        }
        int totalOne = n - totalZero;
        int prefixZero = 0;
        int prefixOne = 0;
        long answer = 0;
        for (int j = 0; j < n; j++) {
            long left, right;
            if (s.charAt(j) == '0') {
                left = prefixOne;
                right = totalOne - prefixOne;
            } else {
                left = prefixZero;
                right = totalZero - prefixZero;
            }
            answer += left * right;
            if (s.charAt(j) == '0') {
                prefixZero++;
            } else {
                prefixOne++;
            }
        }
        return answer;
    }
}

