public class Solution {
    public static int maximumCandies(int[] candies, int k) {
        int maxPile = 0;
        for (int v : candies) {
            if (v > maxPile) maxPile = v;
        }
        int low = 1, high = maxPile, best = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            int total = 0;
            for (int v : candies) {
                total += v / mid;
                if (total >= k) break;
            }
            if (total >= k) {
                best = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return best;
    }
}

