public class Solution {
    public static EncrypterObj Encrypter(String[] keys, String[] values, String[] dictionary) {
        Map<Character, String> encMap = new HashMap<>();
        for (int i = 0; i < keys.length; i++) {
            encMap.put(keys[i].charAt(0), values[i]);
        }
        Map<String, Integer> dictCount = new HashMap<>();
        for (String word : dictionary) {
            StringBuilder enc = new StringBuilder();
            boolean possible = true;
            for (int j = 0; j < word.length(); j++) {
                char ch = word.charAt(j);
                String pair = encMap.get(ch);
                if (pair == null) {
                    possible = false;
                    break;
                }
                enc.append(pair);
            }
            if (possible) {
                String encStr = enc.toString();
                dictCount.put(encStr, dictCount.getOrDefault(encStr, 0) + 1);
            }
        }
        return new EncrypterObj(encMap, dictCount);
    }

    public static class EncrypterObj {
        private final Map<Character, String> encMap;
        private final Map<String, Integer> dictCount;

        EncrypterObj(Map<Character, String> encMap, Map<String, Integer> dictCount) {
            this.encMap = encMap;
            this.dictCount = dictCount;
        }

        public String encrypt(String word) {
            StringBuilder enc = new StringBuilder();
            for (int i = 0; i < word.length(); i++) {
                char ch = word.charAt(i);
                String pair = encMap.get(ch);
                if (pair == null) return "";
                enc.append(pair);
            }
            return enc.toString();
        }

        public int decrypt(String code) {
            return dictCount.getOrDefault(code, 0);
        }
    }
}

