public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int maxProduct(int[] nums, int k) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int v : nums) {
            pq.offer((long) v);
        }
        for (int i = 0; i < k; i++) {
            long cur = pq.poll();
            cur++;
            pq.offer(cur);
        }
        long result = 1L;
        while (!pq.isEmpty()) {
            result = (result * (pq.poll() % MOD)) % MOD;
        }
        return (int) result;
    }
}

