class Solution {
    public String minimizeResult(String expression) {
        int plusIdx = expression.indexOf('+');
        int n = expression.length();
        long bestVal = Long.MAX_VALUE;
        int bestI = 0, bestJ = n - 1;
        for (int i = 0; i < plusIdx; i++) {
            String leftOutsideStr = expression.substring(0, i);
            long leftOutside = leftOutsideStr.isEmpty() ? 1 : Long.parseLong(leftOutsideStr);
            String insideLeftStr = expression.substring(i, plusIdx);
            long insideLeft = Long.parseLong(insideLeftStr);
            for (int j = plusIdx + 1; j < n; j++) {
                String insideRightStr = expression.substring(plusIdx + 1, j + 1);
                long insideRight = Long.parseLong(insideRightStr);
                String rightOutsideStr = expression.substring(j + 1);
                long rightOutside = rightOutsideStr.isEmpty() ? 1 : Long.parseLong(rightOutsideStr);
                long val = leftOutside * (insideLeft + insideRight) * rightOutside;
                if (val < bestVal) {
                    bestVal = val;
                    bestI = i;
                    bestJ = j;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(expression, 0, bestI);
        sb.append('(');
        sb.append(expression, bestI, plusIdx);
        sb.append('+');
        sb.append(expression, plusIdx + 1, bestJ + 1);
        sb.append(')');
        sb.append(expression, bestJ + 1, n);
        return sb.toString();
    }
}

