class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        Arrays.sort(flowers);
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + flowers[i];
        }
        long[] suffixNeed = new long[n + 1];
        suffixNeed[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            long need = Math.max(0, target - flowers[i]);
            suffixNeed[i] = suffixNeed[i + 1] + need;
        }
        long ans = 0;
        for (int k = 0; k <= n; k++) {
            long costComplete = suffixNeed[n - k];
            if (costComplete > newFlowers) break;
            long remaining = newFlowers - costComplete;
            if (k == n) {
                ans = Math.max(ans, (long) full * n);
                continue;
            }
            int left = 0;
            int right = target - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                int cnt = lowerBound(flowers, n - k, mid);
                long cost = (long) mid * cnt - pref[cnt];
                if (cost <= remaining) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            int best = right;
            long total = (long) full * k + (long) partial * best;
            ans = Math.max(ans, total);
        }
        return ans;
    }

    private int lowerBound(int[] arr, int length, int target) {
        int lo = 0, hi = length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] >= target) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }
}

