class Solution {
    public long maximumScore(int[] scores, int[][] edges) {
        int n = scores.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            if (adj[u] == null) adj[u] = new ArrayList<>();
            if (adj[v] == null) adj[v] = new ArrayList<>();
            adj[u].add(v);
            adj[v].add(u);
        }

        List<Integer>[] top = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            if (adj[i] == null) continue;
            List<Integer> list = adj[i];
            list.sort((a, b) -> Integer.compare(scores[b], scores[a])); // descending by score
            int limit = Math.min(3, list.size());
            List<Integer> t = new ArrayList<>(limit);
            for (int k = 0; k < limit; k++) {
                t.add(list.get(k));
            }
            top[i] = t;
        }

        long ans = -1;
        for (int[] e : edges) {
            int b = e[0];
            int c = e[1];
            List<Integer> nb = top[b];
            List<Integer> nc = top[c];
            if (nb == null || nc == null) continue;
            for (int a : nb) {
                if (a == c) continue;
                for (int d : nc) {
                    if (d == b) continue;
                    if (a == d) continue;
                    long sum = (long) scores[a] + scores[b] + scores[c] + scores[d];
                    if (sum > ans) ans = sum;
                }
            }
        }
        return ans;
    }
}

