            freq.put(d, freq.getOrDefault(d, 0) + 1);
        }
        int total = 0;
        for (int cnt : freq.values()) {
            if (cnt == 1) return -1;
            if (cnt % 3 == 0) {
                total += cnt / 3;
            } else if (cnt % 3 == 2) {
                total += cnt / 3 + 1;
            } else {
                total += (cnt - 4) / 3 + 2;
            }
        }
        return total;
    }
}

