class Solution {
    public int maxTrailingZeros(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] cnt2 = new int[m][n];
        int[][] cnt5 = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = grid[i][j];
                int c2 = 0, c5 = 0;
                while (val % 2 == 0) {
                    c2++;
                    val /= 2;
                }
                while (val % 5 == 0) {
                    c5++;
                    val /= 5;
                }
                cnt2[i][j] = c2;
                cnt5[i][j] = c5;
            }
        }

        int[][] rowPref2 = new int[m][n];
        int[][] rowPref5 = new int[m][n];
        for (int i = 0; i < m; i++) {
            int sum2 = 0, sum5 = 0;
            for (int j = 0; j < n; j++) {
                sum2 += cnt2[i][j];
                sum5 += cnt5[i][j];
                rowPref2[i][j] = sum2;
                rowPref5[i][j] = sum5;
            }
        }

        int[][] colPref2 = new int[m][n];
        int[][] colPref5 = new int[m][n];
        for (int j = 0; j < n; j++) {
            int sum2 = 0, sum5 = 0;
            for (int i = 0; i < m; i++) {
                sum2 += cnt2[i][j];
                sum5 += cnt5[i][j];
                colPref2[i][j] = sum2;
                colPref5[i][j] = sum5;
            }
        }

        int answer = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int cell2 = cnt2[i][j];
                int cell5 = cnt5[i][j];

                int up2 = colPref2[i][j];
                int up5 = colPref5[i][j];
                int down2 = colPref2[m - 1][j] - colPref2[i][j] + cell2;
                int down5 = colPref5[m - 1][j] - colPref5[i][j] + cell5;
                int left2 = rowPref2[i][j];
                int left5 = rowPref5[i][j];
                int right2 = rowPref2[i][n - 1] - rowPref2[i][j] + cell2;
                int right5 = rowPref5[i][n - 1] - rowPref5[i][j] + cell5;

                // straight paths
                answer = Math.max(answer, Math.min(up2, up5));
                answer = Math.max(answer, Math.min(down2, down5));
                answer = Math.max(answer, Math.min(left2, left5));
                answer = Math.max(answer, Math.min(right2, right5));

                // L-shaped paths
                int total2, total5;

                total2 = up2 + left2 - cell2;
                total5 = up5 + left5 - cell5;
                answer = Math.max(answer, Math.min(total2, total5));

                total2 = up2 + right2 - cell2;
                total5 = up5 + right5 - cell5;
                answer = Math.max(answer, Math.min(total2, total5));

                total2 = down2 + left2 - cell2;
                total5 = down5 + left5 - cell5;
                answer = Math.max(answer, Math.min(total2, total5));

                total2 = down2 + right2 - cell2;
                total5 = down5 + right5 - cell5;
                answer = Math.max(answer, Math.min(total2, total5));
            }
        }
        return answer;
    }
}

