        List<Integer> result = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            if (entry.getValue() == arrayCount) {
                result.add(entry.getKey());
            }
        }
        Collections.sort(result);
        return result;
    }
}

import java.util.*;

class Solution {
    public int[] countRectangles(int[][] rectangles, int[][] points) {
        Arrays.sort(rectangles, (a, b) -> Integer.compare(b[0], a[0]));
        int m = points.length;
        Point[] pts = new Point[m];
        for (int i = 0; i < m; i++) {
            pts[i] = new Point(points[i][0], points[i][1], i);
        }
        Arrays.sort(pts, (p1, p2) -> Integer.compare(p2.x, p1.x));
        BIT bit = new BIT(101);
        int[] ans = new int[m];
        int rIdx = 0;
        for (Point p : pts) {
            while (rIdx < rectangles.length && rectangles[rIdx][0] >= p.x) {
                int h = rectangles[rIdx][1];
                bit.add(h, 1);
                rIdx++;
            }
            int total = bit.sum(100);
            int less = bit.sum(p.y - 1);
            ans[p.idx] = total - less;
        }
        return ans;
    }

    static class Point {
        int x, y, idx;
        Point(int x, int y, int idx) {
            this.x = x;
            this.y = y;
            this.idx = idx;
        }
    }

    static class BIT {
        int[] tree;
        int n;
        BIT(int n) {
            this.n = n;
            tree = new int[n + 2];
        }
        void add(int idx, int delta) {
            for (int i = idx; i <= n; i += i & -i) {
                tree[i] += delta;
            }
        }
        int sum(int idx) {
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += tree[i];
            }
            return res;
        }
    }
}

