class Solution {
    private static int answer;

    public static int longestPath(int[] parent, String s) {
        int n = parent.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            int p = parent[i];
            graph[p].add(i);
            graph[i].add(p);
        }
        answer = 1;
        dfs(0, -1, graph, s);
        return answer;
    }

    private static int dfs(int node, int prev, List<Integer>[] graph, String s) {
        int best1 = 0, best2 = 0;
        for (int nxt : graph[node]) {
            if (nxt == prev) continue;
            int childLen = dfs(nxt, node, graph, s);
            if (s.charAt(nxt) == s.charAt(node)) continue;
            if (childLen > best1) {
                best2 = best1;
                best1 = childLen;
            } else if (childLen > best2) {
                best2 = childLen;
            }
        }
        answer = Math.max(answer, best1 + best2 + 1);
        return best1 + 1;
    }
}

