import java.util.Set;

class Solution {
    public static int countLatticePoints(int[][] circles) {
        Set<String> visited = new HashSet<>();
        for (int i = 0; i < circles.length; i++) {
            int cx = circles[i][0];
            int cy = circles[i][1];
            int r = circles[i][2];
            int rSq = r * r;
            for (int x = cx - r; x <= cx + r; x++) {
                int dx = x - cx;
                int dxSq = dx * dx;
                if (dxSq > rSq) continue;
                int dyMax = (int) Math.floor(Math.sqrt(rSq - dxSq));
                for (int y = cy - dyMax; y <= cy + dyMax; y++) {
                    visited.add(x + "," + y);
                }
            }
        }
        return visited.size();
    }
}

