class Solution {
    public static int[] fullBloomFlowers(int[][] flowers, int[] people) {
        int n = flowers.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = flowers[i][0];
            ends[i] = flowers[i][1];
        }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int[] result = new int[people.length];
        for (int i = 0; i < people.length; i++) {
            int t = people[i];
            int started = upperBound(starts, t);
            int finished = lowerBound(ends, t);
            result[i] = started - finished;
        }
        return result;
    }

    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

import java.lang.Math;

class Solution {
    public static int minimumAverageDifference(int[] nums) {
        int n = nums.length;
        long totalSum = 0;
        for (int v : nums) totalSum += v;

        int bestIdx = 0;
        long minDiff = Long.MAX_VALUE;
        long prefixSum = 0;

        for (int i = 0; i < n; i++) {
            prefixSum += nums[i];
            long leftAvg = prefixSum / (i + 1);

            int rightCount = n - i - 1;
            long rightAvg = rightCount > 0 ? (totalSum - prefixSum) / rightCount : 0;

            long diff = Math.abs(leftAvg - rightAvg);

            if (diff < minDiff) {
                minDiff = diff;
                bestIdx = i;
            }
        }

        return bestIdx;
    }
}

