class Solution {
    public static int countKDivisibleSubarrays(int[] nums, int k, int p) {
        final long MOD1 = 1000000007L;
        final long MOD2 = 1000000009L;
        final int BASE = 100007;
        int n = nums.length;
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int divCnt = 0;
            long h1 = 0;
            long h2 = 0;
            for (int j = i; j < n; j++) {
                if (nums[j] % p == 0) divCnt++;
                if (divCnt > k) break;
                h1 = (h1 * BASE + nums[j]) % MOD1;
                h2 = (h2 * BASE + nums[j]) % MOD2;
                String key = h1 + "," + h2;
                seen.add(key);
            }
        }
        return seen.size();
    }
}

