public class Solution {
    private static final int MOD = 1_000_000_007;
    public int countTexts(String pressedKeys) {
        int n = pressedKeys.length();
        int[] dp3 = new int[n + 1];
        int[] dp4 = new int[n + 1];
        dp3[0] = 1;
        dp4[0] = 1;
        for (int i = 1; i <= n; i++) {
            long sum3 = dp3[i - 1];
            if (i >= 2) sum3 += dp3[i - 2];
            if (i >= 3) sum3 += dp3[i - 3];
            dp3[i] = (int) (sum3 % MOD);
            long sum4 = dp4[i - 1];
            if (i >= 2) sum4 += dp4[i - 2];
            if (i >= 3) sum4 += dp4[i - 3];
            if (i >= 4) sum4 += dp4[i - 4];
            dp4[i] = (int) (sum4 % MOD);
        }
        long result = 1;
        int i = 0;
        while (i < n) {
            char c = pressedKeys.charAt(i);
            int j = i;
            while (j < n && pressedKeys.charAt(j) == c) j++;
            int len = j - i;
            int ways = (c == '7' || c == '9') ? dp4[len] : dp3[len];
            result = (result * ways) % MOD;
            i = j;
        }
        return (int) result;
    }
}

