public class Solution {
    public boolean hasValidPath(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxLen = m + n; // maximum possible balance
        boolean[][][] dp = new boolean[m][n][maxLen + 1];

        // Initialize start cell
        if (grid[0][0] == '(') {
            dp[0][0][1] = true;
        } else {
            return false; // starting with ')' makes balance negative
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                for (int bal = 0; bal <= maxLen; bal++) {
                    if (!dp[i][j][bal]) continue;

                    // Move right
                    if (j + 1 < n) {
                        int nb = grid[i][j + 1] == '(' ? bal + 1 : bal - 1;
                        if (nb >= 0) {
                            dp[i][j + 1][nb] = true;
                        }
                    }

                    // Move down
                    if (i + 1 < m) {
                        int nb = grid[i + 1][j] == '(' ? bal + 1 : bal - 1;
                        if (nb >= 0) {
                            dp[i + 1][j][nb] = true;
                        }
                    }
                }
            }
        }

        return dp[m - 1][n - 1][0];
    }
}

