class Solution {
    public static int maximumWhiteTiles(int[][] tiles, int carpetLen) {
        Arrays.sort(tiles, (a, b) -> Integer.compare(a[0], b[0]));
        int n = tiles.length;
        int left = 0, right = 0;
        int cur = 0;
        int ans = 0;
        while (left < n) {
            int start = tiles[left][0];
            while (right < n && tiles[right][1] <= start + carpetLen - 1) {
                cur += tiles[right][1] - tiles[right][0] + 1;
                right++;
            }
            int total = cur;
            if (right < n && tiles[right][0] <= start + carpetLen - 1) {
                int covered = start + carpetLen - 1 - tiles[right][0] + 1;
                total += Math.min(covered, tiles[right][1] - tiles[right][0] + 1);
            }
            ans = Math.max(ans, total);
            if (right > left) {
                cur -= tiles[left][1] - tiles[left][0] + 1;
            }
            left++;
            if (right < left) {
                right = left;
            }
        }
        return ans;
    }
}

