class Solution {
    public int largestVariance(String s) {
        int ans = 0;
        int n = s.length();
        for (char a = 'a'; a <= 'z'; a++) {
            for (char b = 'a'; b <= 'z'; b++) {
                if (a == b) continue;
                int cur = 0;
                boolean hasB = false;
                for (int i = 0; i < n; i++) {
                    char c = s.charAt(i);
                    if (c == a) {
                        cur += 1;
                    } else if (c == b) {
                        cur -= 1;
                        hasB = true;
                    } else {
                        continue;
                    }
                    if (hasB) {
                        ans = Math.max(ans, cur);
                    }
                    if (cur < 0 && hasB) {
                        cur = 0;
                        hasB = false;
                    }
                }
            }
        }
        return ans;
    }
}

