class Solution {
    // FIXED: fields were `static` with only static methods (no constructor, no instance),
    // so there was no way to create a fresh CountIntervals - all "instances" would share and
    // corrupt each other's state across test cases. Converted to a proper instance class.
    private final List<int[]> intervals = new ArrayList<>();
    private long total = 0;

    public void add(int left, int right) {
        int lo = 0, hi = intervals.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (intervals.get(mid)[0] < left) lo = mid + 1;
            else hi = mid;
        }
        int idx = lo;
        if (idx > 0 && intervals.get(idx - 1)[1] + 1 >= left) idx--;
        int newL = left, newR = right;
        while (idx < intervals.size() && intervals.get(idx)[0] <= right + 1) {
            int[] seg = intervals.get(idx);
            int l = seg[0], r = seg[1];
            newL = Math.min(newL, l);
            newR = Math.max(newR, r);
            total -= (r - l + 1);
            intervals.remove(idx);
        }
        intervals.add(idx, new int[]{newL, newR});
        total += (newR - newL + 1);
    }

    public long count() {
        return total;
    }
}

