class Solution {
    public long totalStrength(int[] strength) {
        int n = strength.length;
        long MOD = 1_000_000_007L;

        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pre[i + 1] = (pre[i] + strength[i]) % MOD;
        }

        long[] pre2 = new long[n + 2];
        for (int i = 0; i <= n; i++) {
            pre2[i + 1] = (pre2[i] + pre[i]) % MOD;
        }

        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        // previous less element (strict)
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && strength[stack.peek()] > strength[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();
        // next less element (non‑strict to break ties to the right)
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && strength[stack.peek()] >= strength[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int l = left[i];
            int r = right[i];
            long leftCount = i - l;
            long rightCount = r - i;

            long sumRight = (pre2[r + 1] - pre2[i + 1] + MOD) % MOD;
            long sumLeft = (pre2[i + 1] - pre2[l + 1] + MOD) % MOD;

            long term = (leftCount % MOD) * sumRight % MOD;
            term = (term - (rightCount % MOD) * sumLeft % MOD + MOD) % MOD;

            long contrib = (strength[i] % MOD) * term % MOD;
            ans = (ans + contrib) % MOD;
        }

        return ans;
    }
}

