public class Solution {
    public static int minLines(int[][] stockPrices) {
        if (stockPrices.length < 2) return 0;
        Arrays.sort(stockPrices, (a, b) -> Integer.compare(a[0], b[0]));
        int count = 0;
        int[] prevSlope = null;
        for (int i = 1; i < stockPrices.length; i++) {
            int dy = stockPrices[i][1] - stockPrices[i - 1][1];
            int dx = stockPrices[i][0] - stockPrices[i - 1][0];
            int g = gcd(Math.abs(dy), Math.abs(dx));
            dy /= g;
            dx /= g;
            if (dx < 0) {
                dy = -dy;
                dx = -dx;
            }
            if (prevSlope == null || dy != prevSlope[0] || dx != prevSlope[1]) {
                count++;
                prevSlope = new int[]{dy, dx};
            }
        }
        return count;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

