class Solution {
    public static long maximumImportance(int n, int[][] roads) {
        int[] degree = new int[n];
        for (int[] edge : roads) {
            int u = edge[0];
            int v = edge[1];
            degree[u]++;
            degree[v]++;
        }
        int[] sorted = degree.clone();
        Arrays.sort(sorted);
        long totalImportance = 0;
        int currentValue = n;
        for (int i = n - 1; i >= 0; i--) {
            totalImportance += (long) sorted[i] * currentValue;
            currentValue--;
        }
        return totalImportance;
    }
}

