class Solution {
    public static int maxCopies(String s, String target) {
        Map<Character, Integer> sCount = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            sCount.put(ch, sCount.getOrDefault(ch, 0) + 1);
        }

        Map<Character, Integer> tCount = new HashMap<>();
        for (int i = 0; i < target.length(); i++) {
            char ch = target.charAt(i);
            tCount.put(ch, tCount.getOrDefault(ch, 0) + 1);
        }

        int copies = Integer.MAX_VALUE;
        for (Map.Entry<Character, Integer> entry : tCount.entrySet()) {
            char ch = entry.getKey();
            int needed = entry.getValue();
            Integer have = sCount.get(ch);
            if (have == null) {
                return 0;
            }
            copies = Math.min(copies, have / needed);
        }
        return copies == Integer.MAX_VALUE ? 0 : copies;
    }
}

public class Solution {
    public static String discountPrices(String sentence, int discount) {
        String[] words = sentence.split(" ");
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            if (w.length() > 1 && w.charAt(0) == '$' && w.substring(1).matches("\\d+")) {
                double original = Double.parseDouble(w.substring(1));
                double discounted = original * (100 - discount) / 100;
                String formatted = String.format("%.2f", discounted);
                words[i] = "$" + formatted;
            }
        }
        return String.join(" ", words);
    }
}

