class Solution {
    public int totalSteps(int[] nums) {
        Deque<int[]> stack = new ArrayDeque<>();
        int answer = 0;
        for (int x : nums) {
            int days = 0;
            while (!stack.isEmpty() && stack.peek()[0] <= x) {
                days = Math.max(days, stack.pop()[1]);
            }
            if (!stack.isEmpty()) {
                days += 1;
            }
            answer = Math.max(answer, days);
            stack.push(new int[]{x, days});
        }
        return answer;
    }
}

import java.util.Arrays;

class Solution {
    public static Booking BookMyShow(int n, int m) {
        return new Booking(n, m);
    }

    static class Booking {
        private final int n;
        private final int m;
        private final int[] rem;
        private final int[] sum;
        private final int[] mx;

        Booking(int n, int m) {
            this.n = n;
            this.m = m;
            this.rem = new int[n];
            Arrays.fill(this.rem, m);
            int size = 4 * n;
            this.sum = new int[size];
            this.mx = new int[size];
            build(1, 0, n - 1);
        }

        private void build(int node, int l, int r) {
            if (l == r) {
                sum[node] = m;
                mx[node] = m;
            } else {
                int mid = (l + r) >> 1;
                build(node * 2, l, mid);
                build(node * 2 + 1, mid + 1, r);
                pull(node);
            }
        }

        private void pull(int node) {
            sum[node] = sum[node * 2] + sum[node * 2 + 1];
            mx[node] = Math.max(mx[node * 2], mx[node * 2 + 1]);
        }

        private void update(int node, int l, int r, int idx, int val) {
            if (l == r) {
                sum[node] = val;
                mx[node] = val;
            } else {
                int mid = (l + r) >> 1;
                if (idx <= mid) {
                    update(node * 2, l, mid, idx, val);
                } else {
                    update(node * 2 + 1, mid + 1, r, idx, val);
                }
                pull(node);
            }
        }

        private int querySum(int node, int l, int r, int ql, int qr) {
            if (ql > r || qr < l) {
                return 0;
            }
            if (ql <= l && r <= qr) {
                return sum[node];
            }
            int mid = (l + r) >> 1;
            return querySum(node * 2, l, mid, ql, qr) + querySum(node * 2 + 1, mid + 1, r, ql, qr);
        }

        private int queryMax(int node, int l, int r, int ql, int qr) {
            if (ql > r || qr < l) {
                return Integer.MIN_VALUE;
            }
            if (ql <= l && r <= qr) {
                return mx[node];
            }
            int mid = (l + r) >> 1;
            return Math.max(
                queryMax(node * 2, l, mid, ql, qr),
                queryMax(node * 2 + 1, mid + 1, r, ql, qr)
            );
        }

        private int findFirst(int node, int l, int r, int qr, int need) {
            if (l > qr || mx[node] < need) {
                return -1;
            }
            if (l == r) {
                return l;
            }
            int mid = (l + r) >> 1;
            int left = findFirst(node * 2, l, mid, qr, need);
            if (left != -1) {
                return left;
            }
            return findFirst(node * 2 + 1, mid + 1, r, qr, need);
        }

        public int[] gather(int k, int maxRow) {
            if (queryMax(1, 0, n - 1, 0, maxRow) < k) {
                return new int[0];
            }
            int row = findFirst(1, 0, n - 1, maxRow, k);
            int start = m - rem[row];
            rem[row] -= k;
            update(1, 0, n - 1, row, rem[row]);
            return new int[]{row, start};
        }

        public boolean scatter(int k, int maxRow) {
            if (querySum(1, 0, n - 1, 0, maxRow) < k) {
                return false;
            }
            while (k > 0) {
                int row = findFirst(1, 0, n - 1, maxRow, 1);
                int take = Math.min(rem[row], k);
                rem[row] -= take;
                update(1, 0, n - 1, row, rem[row]);
                k -= take;
            }
            return true;
        }
    }
}

