class Solution {
    private Deque<Character> left;
    private Deque<Character> right;

    public Solution() {
        left = new ArrayDeque<>();
        right = new ArrayDeque<>();
    }

    public void addText(String text) {
        for (int i = 0; i < text.length(); i++) {
            left.addLast(text.charAt(i));
        }
    }

    public int deleteText(int k) {
        int deleted = 0;
        while (deleted < k && !left.isEmpty()) {
            left.removeLast();
            deleted++;
        }
        return deleted;
    }

    public String cursorLeft(int k) {
        int moves = Math.min(k, left.size());
        for (int i = 0; i < moves; i++) {
            right.addFirst(left.removeLast());
        }
        return getLeftString();
    }

    public String cursorRight(int k) {
        int moves = Math.min(k, right.size());
        for (int i = 0; i < moves; i++) {
            left.addLast(right.removeFirst());
        }
        return getLeftString();
    }

    private String getLeftString() {
        int total = left.size();
        int start = Math.max(0, total - 10);
        char[] arr = new char[total];
        int idx = 0;
        for (char c : left) {
            arr[idx++] = c;
        }
        return new String(arr, start, total - start);
    }
}

