class Solution {
    public static int minMaxGame(int[] nums) {
        while (nums.length > 1) {
            int[] next = new int[nums.length / 2];
            for (int i = 0; i < nums.length; i += 2) {
                int pairIdx = i / 2;
                if (pairIdx % 2 == 0) {
                    next[pairIdx] = Math.min(nums[i], nums[i + 1]);
                } else {
                    next[pairIdx] = Math.max(nums[i], nums[i + 1]);
                }
            }
            nums = next;
        }
        return nums[0];
    }
}

