class Solution {
    public static List<Integer> successfulPairs(int[] spells, int[] potions, int success) {
        Arrays.sort(potions);
        int m = potions.length;
        List<Integer> result = new ArrayList<>(spells.length);
        for (int spell : spells) {
            int need = (int) ((success + (long) spell - 1) / (long) spell);
            int idx = lowerBound(potions, need);
            result.add(m - idx);
        }
        return result;
    }

    private static int lowerBound(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = left + ((right - left) >> 1);
            if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

