class Solution {
    public static boolean strongPasswordCheckerII(String password) {
        if (password.length() < 8) return false;
        Set<Character> specials = new HashSet<>(Arrays.asList('!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '-', '+'));
        boolean hasLower = false, hasUpper = false, hasDigit = false, hasSpecial = false;
        for (int i = 0; i < password.length(); i++) {
            char ch = password.charAt(i);
            if (i > 0 && ch == password.charAt(i - 1)) return false;
            if (!hasLower && ch >= 'a' && ch <= 'z') {
                hasLower = true;
            } else if (!hasUpper && ch >= 'A' && ch <= 'Z') {
                hasUpper = true;
            } else if (!hasDigit && ch >= '0' && ch <= '9') {
                hasDigit = true;
            } else if (!hasSpecial && specials.contains(ch)) {
                hasSpecial = true;
            }
        }
        return hasLower && hasUpper && hasDigit && hasSpecial;
    }
}

