class Solution {
    public static boolean matchSubstringAfterReplacement(String s, String sub, List<char[]> mappings) {
        Map<Character, Set<Character>> replaceMap = new HashMap<>();
        for (char[] pair : mappings) {
            char oldChar = pair[0];
            char newChar = pair[1];
            replaceMap.computeIfAbsent(oldChar, k -> new HashSet<>()).add(newChar);
        }
        int n = s.length();
        int m = sub.length();
        if (m > n) return false;
        for (int i = 0; i <= n - m; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                char a = sub.charAt(j);
                char b = s.charAt(i + j);
                if (a == b) continue;
                Set<Character> possible = replaceMap.get(a);
                if (possible != null && possible.contains(b)) continue;
                ok = false;
                break;
            }
            if (ok) return true;
        }
        return false;
    }
}

