public class Solution {
    public static double calculateTax(double[][] brackets, double income) {
        double tax = 0;
        double lower = 0;
        for (int i = 0; i < brackets.length; i++) {
            double upper = brackets[i][0];
            double percent = brackets[i][1];
            if (income <= lower) break;
            double portion = Math.min(income, upper) - lower;
            tax += portion * percent / 100;
            lower = upper;
        }
        return tax;
    }
