public class Solution {
    public static long countSubarrays(int[] nums, int k) {
        if (k <= 0) return 0;
        int left = 0;
        long sum = 0;
        long answer = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (left <= right && sum * (right - left + 1) >= k) {
                sum -= nums[left];
                left++;
            }
            answer += right - left + 1;
        }
        return answer;
    }
}

