class Solution {
    public static int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;
        long[] prev = new long[n];
        for (int j = 0; j < n; j++) {
            prev[j] = grid[0][j];
        }
        for (int i = 1; i < m; i++) {
            long[] cur = new long[n];
            for (int j = 0; j < n; j++) {
                cur[j] = Long.MAX_VALUE;
            }
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    long candidate = prev[k] + moveCost[grid[i - 1][k]][j] + grid[i][j];
                    if (candidate < cur[j]) {
                        cur[j] = candidate;
                    }
                }
            }
            prev = cur;
        }
        long ans = Long.MAX_VALUE;
        for (long v : prev) {
            if (v < ans) ans = v;
        }
        return (int) ans;
    }
}

