public class Solution {
    public static int distributeCookies(int[] cookies, int k) {
        Integer[] boxed = new Integer[cookies.length];
        for (int i = 0; i < cookies.length; i++) {
            boxed[i] = cookies[i];
        }
        Arrays.sort(boxed, Collections.reverseOrder());
        for (int i = 0; i < cookies.length; i++) {
            cookies[i] = boxed[i];
        }
        int total = 0;
        for (int v : cookies) {
            total += v;
        }
        int maxBag = cookies[0];
        int low = maxBag, high = total;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canFit(cookies, k, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean canFit(int[] cookies, int k, int limit) {
        int[] load = new int[k];
        return dfs(0, cookies, k, limit, load);
    }

    private static boolean dfs(int idx, int[] cookies, int k, int limit, int[] load) {
        if (idx == cookies.length) {
            return true;
        }
        int cur = cookies[idx];
        for (int i = 0; i < k; i++) {
            if (load[i] + cur <= limit) {
                load[i] += cur;
                if (dfs(idx + 1, cookies, k, limit, load)) {
                    return true;
                }
                load[i] -= cur;
            }
            if (load[i] == 0) {
                break;
            }
        }
        return false;
    }
}

