public class Solution {
    public static int maxProfit(int m, int n, int[][] prices) {
        Map<String, Integer> priceMap = new HashMap<>();
        for (int[] arr : prices) {
            int h = arr[0];
            int w = arr[1];
            int p = arr[2];
            String key = h + "," + w;
            int cur = priceMap.getOrDefault(key, 0);
            if (p > cur) priceMap.put(key, p);
        }
        Integer[][] memo = new Integer[m + 1][n + 1];
        return dfs(m, n, memo, priceMap);
    }

    private static int dfs(int h, int w, Integer[][] memo, Map<String, Integer> priceMap) {
        if (memo[h][w] != null) return memo[h][w];
        int best = priceMap.getOrDefault(h + "," + w, 0);
        for (int cut = 1; cut < w; cut++) {
            int left = dfs(h, cut, memo, priceMap);
            int right = dfs(h, w - cut, memo, priceMap);
            int combined = left + right;
            if (combined > best) best = combined;
        }
        for (int cut = 1; cut < h; cut++) {
            int top = dfs(cut, w, memo, priceMap);
            int bottom = dfs(h - cut, w, memo, priceMap);
            int combined = top + bottom;
            if (combined > best) best = combined;
        }
        memo[h][w] = best;
        return best;
    }
}

