class Solution {
    public static int longestBinarySubsequenceLength(String s, int k) {
        int length = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == '0') {
                length++;
            } else {
                if (length >= 31) continue;
                int weight = 1 << length;
                if (weight <= k) {
                    k -= weight;
                    length++;
                }
            }
        }
        return length;
    }
}

