            for (int j = i + 1; j < 26; j++) {
                if (groups[j].isEmpty()) continue;
                Set<String> smaller = groups[i].size() < groups[j].size() ? groups[i] : groups[j];
                Set<String> larger = smaller == groups[i] ? groups[j] : groups[i];
                int common = 0;
                for (String s : smaller) {
                    if (larger.contains(s)) common++;
                }
                int cntI = groups[i].size();
                int cntJ = groups[j].size();
                answer += (long) (cntI - common) * (cntJ - common) * 2L;
            }
        }
        return answer;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static long countUnreachablePairs(int n, int[][] edges) {
        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
            int ra = find.applyAsInt(a);
            int rb = find.applyAsInt(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int temp = ra;
                ra = rb;
                rb = temp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        };

        for (int[] edge : edges) {
            union.accept(edge[0], edge[1]);
        }

        Map<Integer, Integer> compSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = find.applyAsInt(i);
            compSize.put(root, compSize.getOrDefault(root, 0) + 1);
        }

        long result = 0;
        long remaining = n;
        for (int sz : compSize.values()) {
            remaining -= sz;
            result += (long) sz * remaining;
        }
        return result;
    }
}

import java.util.*;
class Solution {
    public static int countDistinctRollSequences(int n) {
        final long MOD = 1000000007;
        if (n == 1) return 6;
        Map<Long, Long> dp = new HashMap<>();
        for (int a = 1; a <= 6; a++) {
            for (int b = 1; b <= 6; b++) {
                if (a == b || gcd(a, b) != 1) continue;
                long key = b * 10 + a;
                dp.merge(key, 1L, Long::sum);
            }
        }
        for (int len = 3; len <= n; len++) {
            Map<Long, Long> ndp = new HashMap<>();
            for (Map.Entry<Long, Long> e : dp.entrySet()) {
                long key = e.getKey();
                int prev = (int)(key / 10), prevprev = (int)(key % 10);
                long cnt = e.getValue();
                for (int v = 1; v <= 6; v++) {
                    if (v == prev || v == prevprev || gcd(v, prev) != 1) continue;
                    long nkey = v * 10L + prev;
                    ndp.merge(nkey, cnt, (a, b) -> (a + b) % MOD);
                }
            }
            dp = ndp;
        }
        long total = 0;
        for (long v : dp.values()) total = (total + v) % MOD;
        return (int) total;
    }
    private static int gcd(int a, int b) { while (b != 0) { int t = b; b = a % b; a = t; } return a; }
}

