public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countWays(int n) {
        long f0 = 1; // f[0]
        if (n == 0) {
            return 1;
        }
        long f1 = 2; // f[1]
        if (n == 1) {
            long ans = (f1 * f1) % MOD;
            return (int) ans;
        }
        long fn = 0;
        for (int i = 2; i <= n; i++) {
            fn = (f1 + f0) % MOD;
            f0 = f1;
            f1 = fn;
        }
        long ans = (fn * fn) % MOD;
        return (int) ans;
    }
}

