class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; }
}

class Solution {
    public static int[][] spiralMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(matrix[i], -1);
        }
        int top = 0, bottom = m - 1, left = 0, right = n - 1;
        ListNode node = head;
        while (top <= bottom && left <= right) {
            for (int col = left; col <= right; col++) {
                if (node != null) {
                    matrix[top][col] = node.val;
                    node = node.next;
                }
            }
            top++;
            for (int row = top; row <= bottom; row++) {
                if (node != null) {
                    matrix[row][right] = node.val;
                    node = node.next;
                }
            }
            right--;
            if (top <= bottom) {
                for (int col = right; col >= left; col--) {
                    if (node != null) {
                        matrix[bottom][col] = node.val;
                        node = node.next;
                    }
                }
                bottom--;
            }
            if (left <= right) {
                for (int row = bottom; row >= top; row--) {
                    if (node != null) {
                        matrix[row][left] = node.val;
                        node = node.next;
                    }
                }
                left++;
            }
        }
        return matrix;
    }
}

import java.lang.*;

class Solution {
    public static int peopleAwareOfSecret(int n, int delay, int forget) {
        long MOD = 1_000_000_007L;
        long[] dp = new long[n + 1];
        long[] start = new long[n + 1];
        long[] end = new long[n + 1];

        dp[1] = 1;
        if (1 + delay <= n) start[1 + delay] = 1;
        if (1 + forget <= n) end[1 + forget] = 1;

        long active = 0;

        for (int day = 2; day <= n; day++) {
            active = (active + start[day]) % MOD;
            active = (active - end[day] + MOD) % MOD;
            dp[day] = active;

            int actDay = day + delay;
            if (actDay <= n) start[actDay] = (start[actDay] + dp[day]) % MOD;
            int finDay = day + forget;
            if (finDay <= n) end[finDay] = (end[finDay] + dp[day]) % MOD;
        }

        long result = 0;
        for (int i = 1; i <= n; i++) {
            if (i + forget > n) {
                result = (result + dp[i]) % MOD;
            }
        }
        return (int) result;
    }
}

public class Solution {
    public static long maximumScore(int[] nums1, int[] nums2) {
        long sum1 = 0, sum2 = 0;
        for (int i = 0; i < nums1.length; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
        }
        long bestDiff = 0, curDiff = 0;
        long bestNeg = 0, curNeg = 0;
        for (int i = 0; i < nums1.length; i++) {
            long diff = (long) nums2[i] - nums1[i];
            curDiff = Math.max(diff, curDiff + diff);
            bestDiff = Math.max(bestDiff, curDiff);
            long neg = -diff;
            curNeg = Math.max(neg, curNeg + neg);
            bestNeg = Math.max(bestNeg, curNeg);
        }
        return Math.max(sum1 + bestDiff, sum2 + bestNeg);
    }
}

import java.util.*;

class Solution {
    private int[] parent;
    private int[] subtreeXor;
    private int[] tin;
    private int[] tout;
    private int timer;

    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }

        parent = new int[n];
        Arrays.fill(parent, -1);
        subtreeXor = new int[n];
        tin = new int[n];
        tout = new int[n];
        timer = 0;
        dfs(0, -1, nums, adj);

        int totalXor = subtreeXor[0];

        int m = edges.length;
        int[] edgeChild = new int[m];
        for (int i = 0; i < m; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            if (parent[a] == b) {
                edgeChild[i] = a;
            } else {
                edgeChild[i] = b;
            }
        }

        int answer = Integer.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            int childA = edgeChild[i];
            int xorA = subtreeXor[childA];
            for (int j = i + 1; j < m; j++) {
                int childB = edgeChild[j];
                int xorB = subtreeXor[childB];

                int max, min;
                if (isAncestor(childA, childB)) {
                    int xorDesc = xorB;
                    int xorAncMinusDesc = xorA ^ xorB;
                    int xorRest = totalXor ^ xorA;
                    max = Math.max(xorDesc, Math.max(xorAncMinusDesc, xorRest));
                    min = Math.min(xorDesc, Math.min(xorAncMinusDesc, xorRest));
                } else if (isAncestor(childB, childA)) {
                    int xorDesc = xorA;
                    int xorAncMinusDesc = xorB ^ xorA;
                    int xorRest = totalXor ^ xorB;
                    max = Math.max(xorDesc, Math.max(xorAncMinusDesc, xorRest));
                    min = Math.min(xorDesc, Math.min(xorAncMinusDesc, xorRest));
                } else {
                    int xorC = totalXor ^ xorA ^ xorB;
                    max = Math.max(xorA, Math.max(xorB, xorC));
                    min = Math.min(xorA, Math.min(xorB, xorC));
                }
                answer = Math.min(answer, max - min);
            }
        }
        return answer;
    }

    private void dfs(int u, int p, int[] nums, List<Integer>[] adj) {
        parent[u] = p;
        tin[u] = timer++;
        int curXor = nums[u];
        for (int v : adj[u]) {
            if (v == p) continue;
            dfs(v, u, nums, adj);
            curXor ^= subtreeXor[v];
        }
        subtreeXor[u] = curXor;
        tout[u] = timer++;
    }

    private boolean isAncestor(int anc, int desc) {
        return tin[anc] <= tin[desc] && tout[desc] <= tout[anc];
    }
}

