class Solution {
    public static int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> passengerSet = new HashSet<>();
        for (int p : passengers) {
            passengerSet.add(p);
        }
        int pIdx = 0;
        int answer = -1;
        for (int bus : buses) {
            int boarded = 0;
            while (pIdx < passengers.length && passengers[pIdx] <= bus && boarded < capacity) {
                boarded++;
                pIdx++;
            }
            int candidate;
            if (boarded < capacity) {
                candidate = bus;
            } else {
                candidate = passengers[pIdx - 1] - 1;
            }
            while (passengerSet.contains(candidate)) {
                candidate--;
            }
            if (candidate > answer) {
                answer = candidate;
            }
        }
        return answer;
    }
}

