class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        Cell[] cells = new Cell[total];
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx++] = new Cell(grid[i][j], i, j);
            }
        }
        Arrays.sort(cells, (a, b) -> Integer.compare(a.val, b.val));

        long[][] dp = new long[m][n];
        long ans = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (Cell cell : cells) {
            int r = cell.r;
            int c = cell.c;
            long ways = 1; // path consisting of the cell itself
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (grid[nr][nc] < grid[r][c]) {
                    ways += dp[nr][nc];
                }
            }
            ways %= MOD;
            dp[r][c] = ways;
            ans += ways;
            if (ans >= MOD) ans -= MOD;
        }
        return (int) ans;
    }

    private static class Cell {
        int val;
        int r;
        int c;
        Cell(int v, int r, int c) {
            this.val = v;
            this.r = r;
            this.c = c;
        }
    }
}

