class Solution {
    public static boolean canChange(String start, String target) {
        int n = start.length();
        int i = 0, j = 0;
        while (i < n && j < n) {
            while (i < n && start.charAt(i) == '_') i++;
            while (j < n && target.charAt(j) == '_') j++;
            if ((i < n) != (j < n)) return false;
            if (i == n && j == n) break;
            if (start.charAt(i) != target.charAt(j)) return false;
            if (start.charAt(i) == 'L' && i < j) return false;
            if (start.charAt(i) == 'R' && i > j) return false;
            i++;
            j++;
        }
        while (i < n) {
            if (start.charAt(i++) != '_') return false;
        }
        while (j < n) {
            if (target.charAt(j++) != '_') return false;
        }
        return true;
    }
}

import java.util.*;

public class Solution {
    public static SmallestInfiniteSet SmallestInfiniteSet() {
        return new SmallestInfiniteSet();
    }

    private static class SmallestInfiniteSet {
        private final ArrayList<Integer> heap = new ArrayList<>();
        private final HashSet<Integer> inHeap = new HashSet<>();
        private int next = 1;

        public int popSmallest() {
            if (!heap.isEmpty()) {
                int val = heapPop();
                inHeap.remove(val);
                return val;
            }
            return next++;
        }

        public void addBack(int num) {
            if (num < next && !inHeap.contains(num)) {
                heapPush(num);
                inHeap.add(num);
            }
        }

        private void heapPush(int val) {
            heap.add(val);
            int i = heap.size() - 1;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (heap.get(p) <= heap.get(i)) break;
                int tmp = heap.get(p);
                heap.set(p, heap.get(i));
                heap.set(i, tmp);
                i = p;
            }
        }

        private int heapPop() {
            int min = heap.get(0);
            int last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                int i = 0;
                while (true) {
                    int l = i * 2 + 1;
                    int r = i * 2 + 2;
                    int smallest = i;
                    if (l < heap.size() && heap.get(l) < heap.get(smallest)) smallest = l;
                    if (r < heap.size() && heap.get(r) < heap.get(smallest)) smallest = r;
                    if (smallest == i) break;
                    int tmp = heap.get(i);
                    heap.set(i, heap.get(smallest));
                    heap.set(smallest, tmp);
                    i = smallest;
                }
            }
            return min;
        }
    }
}

import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int idealArrays(int n, int maxValue) {
        List<Integer>[] divisors = new ArrayList[maxValue + 1];
        for (int i = 1; i <= maxValue; i++) {
            divisors[i] = new ArrayList<>();
        }
        for (int d = 1; d <= maxValue; d++) {
            for (int m = d; m <= maxValue; m += d) {
                divisors[m].add(d);
            }
        }

        int[] dpPrev = new int[maxValue + 1];
        Arrays.fill(dpPrev, 1);
        int[] dpCurr = new int[maxValue + 1];

        for (int len = 2; len <= n; len++) {
            Arrays.fill(dpCurr, 0);
            for (int v = 1; v <= maxValue; v++) {
                long sum = 0;
                for (int d : divisors[v]) {
                    sum += dpPrev[d];
                    if (sum >= 4L * MOD) sum %= MOD;
                }
                dpCurr[v] = (int) (sum % MOD);
            }
            int[] tmp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = tmp;
        }

        long ans = 0;
        for (int v = 1; v <= maxValue; v++) {
            ans += dpPrev[v];
        }
        return (int) (ans % MOD);
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        int answer = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            long val = nums[i];
            long needed = threshold / val + 1;
            int maxLen = right[i] - left[i] - 1;
            if (needed <= maxLen) {
                answer = Math.min(answer, (int) needed);
            }
        }
        return answer == Integer.MAX_VALUE ? -1 : answer;
    }
}

import java.util.*;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long K = (long) k1 + k2;
        int maxDiff = 0;
        long totalDiff = 0;
        int[] diffs = new int[n];
        for (int i = 0; i < n; i++) {
            int d = Math.abs(nums1[i] - nums2[i]);
            diffs[i] = d;
            totalDiff += d;
            if (d > maxDiff) maxDiff = d;
        }
        if (K >= totalDiff) {
            long remaining = K - totalDiff;
            return (remaining & 1) == 0 ? 0L : 1L;
        }
        int[] freq = new int[maxDiff + 1];
        for (int d : diffs) {
            freq[d]++;
        }
        long ops = K;
        for (int d = maxDiff; d > 0 && ops > 0; d--) {
            if (freq[d] == 0) continue;
            long move = Math.min((long) freq[d], ops);
            freq[d] -= (int) move;
            freq[d - 1] += (int) move;
            ops -= move;
        }
        long ans = 0L;
        for (int d = 0; d <= maxDiff; d++) {
            if (freq[d] != 0) {
                ans += (long) freq[d] * d * d;
            }
        }
        return ans;
    }
}

