class Solution {
    public static int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int n = nums.length;
        int[] answers = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int k = queries[q][0];
            int trim = queries[q][1];
            Item[] items = new Item[n];
            for (int i = 0; i < n; i++) {
                String s = nums[i];
                String trimmed = s.substring(Math.max(0, s.length() - trim));
                int val = Integer.parseInt(trimmed);
                items[i] = new Item(i, val);
            }
            Arrays.sort(items, (a, b) -> {
                if (a.val != b.val) return a.val - b.val;
                return a.idx - b.idx;
            });
            answers[q] = items[k - 1].idx;
        }
        return answers;
    }

    private static class Item {
        int idx;
        int val;
        Item(int idx, int val) {
            this.idx = idx;
            this.val = val;
        }
    }
}

import java.util.Arrays;

class Solution {
    public static int minDeletion(int[] nums, int[] numsDivide) {
        int common = numsDivide[0];
        for (int i = 1; i < numsDivide.length; i++) {
            common = gcd(common, numsDivide[i]);
        }
        Arrays.sort(nums);
        for (int i = 0; i < nums.length; i++) {
            if (common % nums[i] == 0) {
                return i;
            }
        }
        return -1;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

