    public static int maxSumPair(int[] nums) {
        Map<Integer, int[]> top = new HashMap<>();
        int best = -1;
        for (int value : nums) {
            int d = digitSum(value);
            if (!top.containsKey(d)) {
                top.put(d, new int[]{value, Integer.MIN_VALUE});
            } else {
                int[] arr = top.get(d);
                int max1 = arr[0];
                int max2 = arr[1];
                best = Math.max(best, max1 + value);
                if (value > max1) {
                    top.put(d, new int[]{value, max1});
                } else if (value > max2) {
                    arr[1] = value;
                }
            }
        }
        return best;
    }
}

