class Solution {
    public static int shortestImpossibleSequence(int[] rolls, int k) {
        int n = rolls.length;
        List<List<Integer>> pos = new ArrayList<>(k + 1);
        for (int i = 0; i <= k; i++) pos.add(new ArrayList<>());
        for (int i = 0; i < n; i++) {
            pos.get(rolls[i]).add(i);
        }
        for (int v = 1; v <= k; v++) {
            if (pos.get(v).isEmpty()) return 1;
        }
        for (int L = 2; ; L++) {
            if (L > n) return L;
            double totalLD = 1.0;
            for (int i = 0; i < L; i++) totalLD *= (double) k;
            double combLD = 1.0;
            for (int i = 1; i <= L; i++) {
                combLD = combLD * (n - i + 1) / i;
                if (combLD > totalLD) break;
            }
            if (totalLD > combLD) return L;
            long total = 1L;
            for (int i = 0; i < L; i++) total *= (long) k;
            int[] seq = new int[L];
            for (long id = 0; id < total; id++) {
                long tmp = id;
                for (int i = L - 1; i >= 0; i--) {
                    seq[i] = (int) (tmp % k) + 1;
                    tmp /= k;
                }
                int cur = -1;
                boolean ok = true;
                for (int val : seq) {
                    List<Integer> vec = pos.get(val);
                    int idx = Collections.binarySearch(vec, cur + 1);
                    if (idx < 0) idx = -idx - 1;
                    if (idx == vec.size()) {
                        ok = false;
                        break;
                    }
                    cur = vec.get(idx);
                }
                if (!ok) return L;
            }
        }
    }
}

import java.util.*;

public class Solution {
    // FIXED: fields were `static` (shared/corrupted across instances, no constructor to
    // reset) - converted to instance fields. ALSO fixed: add() special-cased number==0 as
    // a delete signal and never stored a genuine 0 value - see fix note in other languages.
    private final Map<Integer, Integer> indexToNum = new HashMap<>();
    private final Map<Integer, MinHeap> numToHeap = new HashMap<>();

    private static class MinHeap {
        private final List<Integer> arr = new ArrayList<>();

        int peek() { return arr.get(0); }

        void push(int val) {
            arr.add(val);
            int i = arr.size() - 1;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (arr.get(p) <= arr.get(i)) break;
                int tmp = arr.get(p);
                arr.set(p, arr.get(i));
                arr.set(i, tmp);
                i = p;
            }
        }

        int pop() {
            if (arr.isEmpty()) return -1;
            int root = arr.get(0);
            int last = arr.remove(arr.size() - 1);
            if (!arr.isEmpty()) {
                arr.set(0, last);
                int i = 0;
                while (true) {
                    int l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                    if (l < arr.size() && arr.get(l) < arr.get(smallest)) smallest = l;
                    if (r < arr.size() && arr.get(r) < arr.get(smallest)) smallest = r;
                    if (smallest == i) break;
                    int tmp = arr.get(i);
                    arr.set(i, arr.get(smallest));
                    arr.set(smallest, tmp);
                    i = smallest;
                }
            }
            return root;
        }

        int size() { return arr.size(); }
    }

    public void add(int number, int index) {
        indexToNum.put(index, number);
        MinHeap heap = numToHeap.get(number);
        if (heap == null) {
            heap = new MinHeap();
            numToHeap.put(number, heap);
        }
        heap.push(index);
    }

    public int query(int number) {
        MinHeap heap = numToHeap.get(number);
        if (heap == null) return -1;
        while (heap.size() > 0) {
            Integer cur = indexToNum.get(heap.peek());
            if (cur != null && cur == number) break;
            heap.pop();
        }
        return heap.size() > 0 ? heap.peek() : -1;
    }
}

