class Solution {
    public static String bestPokerHand(int[] ranks, String[] suits) {
        Map<Integer, Integer> rankCount = new HashMap<>();
        for (int r : ranks) {
            rankCount.put(r, rankCount.getOrDefault(r, 0) + 1);
        }
        boolean isFlush = true;
        for (int i = 1; i < suits.length; i++) {
            if (!suits[i].equals(suits[0])) {
                isFlush = false;
                break;
            }
        }
        Set<Integer> uniqueRanks = new HashSet<>();
        for (int r : ranks) {
            uniqueRanks.add(r);
        }
        boolean isStraight = false;
        if (uniqueRanks.size() == 5) {
            int min = Collections.min(uniqueRanks);
            int max = Collections.max(uniqueRanks);
            if (max - min == 4) {
                isStraight = true;
            }
        }
        int maxCount = 0;
        int pairCount = 0;
        for (int cnt : rankCount.values()) {
            if (cnt > maxCount) maxCount = cnt;
            if (cnt == 2) pairCount++;
        }
        if (isFlush && isStraight) return "Straight Flush";
        if (isFlush) return "Flush";
        if (isStraight) return "Straight";
        if (maxCount >= 3) return "Three of a Kind";
        if (pairCount == 2) return "Two Pairs";
        if (pairCount == 1) return "Pair";
        return "High Card";
    }
}

