public class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        HashSet<Integer> unique = new HashSet<>();
        for (int num : nums) {
            unique.add(num);
        }
        int[] freq = new int[32];
        for (int val : unique) {
            int pc = Integer.bitCount(val);
            freq[pc]++;
        }
        long ans = 0;
        for (int i = 0; i < 32; i++) {
            if (freq[i] == 0) continue;
            for (int j = 0; j < 32; j++) {
                if (freq[j] == 0) continue;
                if (i + j >= k) {
                    ans += (long) freq[i] * freq[j];
                }
            }
        }
        return ans;
    }
}

