class FoodRatings {
    private static class Food implements Comparable<Food> {
        String name;
        int rating;
        Food(String name, int rating) {
            this.name = name;
            this.rating = rating;
        }
        @Override
        public int compareTo(Food other) {
            if (this.rating != other.rating) {
                return other.rating - this.rating;
            }
            return this.name.compareTo(other.name);
        }
    }

    private Map<String, String> foodToCuisine;
    private Map<String, Integer> foodToRating;
    private Map<String, PriorityQueue<Food>> cuisineHeap;

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        foodToCuisine = new HashMap<>();
        foodToRating = new HashMap<>();
        cuisineHeap = new HashMap<>();

        for (int i = 0; i < foods.length; i++) {
            String food = foods[i];
            String cuisine = cuisines[i];
            int rating = ratings[i];

            foodToCuisine.put(food, cuisine);
            foodToRating.put(food, rating);

            cuisineHeap.computeIfAbsent(cuisine, k -> new PriorityQueue<>())
                       .add(new Food(food, rating));
        }
    }

    public void changeRating(String food, int newRating) {
        String cuisine = foodToCuisine.get(food);
        foodToRating.put(food, newRating);
        PriorityQueue<Food> heap = cuisineHeap.get(cuisine);
        heap.add(new Food(food, newRating));
    }

    public String highestRated(String cuisine) {
        PriorityQueue<Food> heap = cuisineHeap.get(cuisine);
        while (true) {
            Food top = heap.peek();
            int currentRating = foodToRating.get(top.name);
            if (top.rating == currentRating) {
                return top.name;
            }
            heap.poll();
        }
    }
}

