class Solution {
    public static int maximumGroups(int[] grades) {
        Arrays.sort(grades);
        int groups = 0;
        long prevSum = 0;
        long curSum = 0;
        int curSize = 0;
        for (int g : grades) {
            curSum += g;
            curSize++;
            if (curSize > groups && curSum > prevSum) {
                groups++;
                prevSum = curSum;
                curSum = 0;
                curSize = 0;
            }
        }
        return groups;
    }
}

