class Solution {
    public static long taskSchedulerII(int[] tasks, int space) {
        Map<Integer, Long> lastDay = new HashMap<>();
        long day = 0;
        long defaultLast = -(space + 1L);
        for (int t : tasks) {
            long prev = lastDay.getOrDefault(t, defaultLast);
            long earliest = Math.max(day + 1, prev + space + 1);
            day = earliest;
            lastDay.put(t, day);
        }
        return day;
    }
}

