class Solution {
    public static int longestCycle(int[] edges) {
        int n = edges.length;
        int[] visited = new int[n];
        int[] depth = new int[n];
        int maxLen = -1;
        int id = 1;
        for (int i = 0; i < n; i++) {
            if (visited[i] != 0) continue;
            int cur = i;
            int step = 0;
            while (cur != -1 && visited[cur] == 0) {
                visited[cur] = id;
                depth[cur] = step;
                cur = edges[cur];
                step++;
            }
            if (cur != -1 && visited[cur] == id) {
                int cycleLen = step - depth[cur];
                if (cycleLen > maxLen) maxLen = cycleLen;
            }
            id++;
        }
        return maxLen;
    }
}

