class Solution {
    public static long minimumReplacement(int[] nums) {
        long operations = 0;
        long limit = nums[nums.length - 1];
        for (int i = nums.length - 2; i >= 0; i--) {
            if (nums[i] <= limit) {
                limit = nums[i];
            } else {
                long parts = (long) Math.ceil((double) nums[i] / limit);
                operations += parts - 1;
                limit = nums[i] / parts;
            }
        }
        return operations;
    }
}

