class Solution {
    public static long countBadPairs(int[] nums) {
        int n = nums.length;
        long totalPairs = (long) n * (n - 1) / 2;
        long goodPairs = 0;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int diff = i - nums[i];
            Integer cnt = freq.get(diff);
            if (cnt != null) {
                goodPairs += cnt;
                freq.put(diff, cnt + 1);
            } else {
                freq.put(diff, 1);
            }
        }
        return totalPairs - goodPairs;
    }
}

