class Solution {
    public int longestIdealString(String s, int k) {
        int[] dp = new int[26];
        int ans = 0;
        for (int i = 0; i < s.length(); i++) {
            int cur = s.charAt(i) - 'a';
            int best = 0;
            int left = Math.max(0, cur - k);
            int right = Math.min(25, cur + k);
            for (int j = left; j <= right; j++) {
                if (dp[j] > best) {
                    best = dp[j];
                }
            }
            dp[cur] = Math.max(dp[cur], best + 1);
            if (dp[cur] > ans) {
                ans = dp[cur];
            }
        }
        return ans;
    }
}

