class Solution {
    public int countSpecialNumbers(int n) {
        String s = Integer.toString(n);
        int len = s.length();
        int count = 0;
        // Count numbers with length less than len
        for (int l = 1; l < len; l++) {
            count += 9 * perm(9, l - 1);
        }
        boolean[] used = new boolean[10];
        for (int i = 0; i < len; i++) {
            int cur = s.charAt(i) - '0';
            for (int d = (i == 0 ? 1 : 0); d < cur; d++) {
                if (!used[d]) {
                    int remaining = len - i - 1;
                    int available = 10 - (i + 1);
                    count += perm(available, remaining);
                }
            }
            if (used[cur]) {
                return count;
            }
            used[cur] = true;
        }
        // n itself has all distinct digits
        return count + 1;
    }

    private int perm(int m, int k) {
        int res = 1;
        for (int i = 0; i < k; i++) {
            res *= (m - i);
        }
        return res;
    }
}

