public class Solution {
    public static String shiftingLettersII(String s, int[][] shifts) {
        int n = s.length();
        int[] diff = new int[n + 1];
        for (int[] sh : shifts) {
            int l = sh[0];
            int r = sh[1];
            int dir = sh[2];
            int delta = dir == 1 ? 1 : -1;
            diff[l] += delta;
            diff[r + 1] -= delta;
        }
        int cur = 0;
        char[] result = new char[n];
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            int shift = ((cur % 26) + 26) % 26;
            int originalCode = s.charAt(i) - 'a';
            int newCode = (originalCode + shift) % 26;
            result[i] = (char) (newCode + 'a');
        }
        return new String(result);
    }
}

