class Solution {
    public static String largestPalindromic(String num) {
        int[] cnt = new int[10];
        for (int i = 0; i < num.length(); i++) {
            cnt[num.charAt(i) - '0']++;
        }
        StringBuilder left = new StringBuilder();
        for (int d = 9; d >= 0; d--) {
            int pairs = cnt[d] / 2;
            if (pairs > 0) {
                if (d == 0 && left.length() == 0) {
                    continue;
                }
                for (int i = 0; i < pairs; i++) {
                    left.append((char) ('0' + d));
                }
                cnt[d] -= pairs * 2;
            }
        }
        String middle = "";
        for (int d = 9; d >= 0; d--) {
            if (cnt[d] > 0) {
                middle = String.valueOf((char) ('0' + d));
                break;
            }
        }
        if (left.length() == 0) {
            if (middle.isEmpty() || middle.equals("0")) {
                return "0";
            }
            return middle;
        }
        String right = new StringBuilder(left).reverse().toString();
        return left + middle + right;
    }
}

