class Solution {
    public static int minRecolors(String blocks, int k) {
        int n = blocks.length();
        int whiteCount = 0;
        for (int i = 0; i < k; i++) {
            if (blocks.charAt(i) == 'W') whiteCount++;
        }
        int minWhite = whiteCount;
        for (int i = k; i < n; i++) {
            if (blocks.charAt(i - k) == 'W') whiteCount--;
            if (blocks.charAt(i) == 'W') whiteCount++;
            if (whiteCount < minWhite) minWhite = whiteCount;
        }
        return minWhite;
    }
}

import java.util.*;

class Solution {
    private static class Node implements Comparable<Node> {
        long sum;
        int idx;
        Node(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }
        public int compareTo(Node other) {
            return Long.compare(this.sum, other.sum);
        }
    }

    public long kthSum(int[] nums, int k) {
        int n = nums.length;
        long base = 0;
        long[] abs = new long[n];
        for (int i = 0; i < n; i++) {
            if (nums[i] > 0) base += nums[i];
            abs[i] = Math.abs((long) nums[i]);
        }
        Arrays.sort(abs);
        PriorityQueue<Node> pq = new PriorityQueue<>();
        if (n > 0) {
            pq.offer(new Node(abs[0], 0));
        }
        List<Long> reductions = new ArrayList<>(k);
        reductions.add(0L); // empty subset
        while (reductions.size() < k && !pq.isEmpty()) {
            Node cur = pq.poll();
            reductions.add(cur.sum);
            int idx = cur.idx;
            if (idx + 1 < n) {
                long replaceSum = cur.sum - abs[idx] + abs[idx + 1];
                long addSum = cur.sum + abs[idx + 1];
                pq.offer(new Node(replaceSum, idx + 1));
                pq.offer(new Node(addSum, idx + 1));
            }
        }
        long kthReduction = reductions.get(k - 1);
        return base - kthReduction;
    }
}

