class Solution {
    public static int amountOfTime(TreeNode root, int start) {
        Map<Integer, List<Integer>> adj = new HashMap<>();
        dfs(root, null, adj);
        Set<Integer> visited = new HashSet<>();
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(start);
        visited.add(start);
        int minutes = -1;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int cur = queue.poll();
                for (int nb : adj.getOrDefault(cur, Collections.emptyList())) {
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.add(nb);
                    }
                }
            }
            minutes++;
        }
        return minutes;
    }

    private static void dfs(TreeNode node, TreeNode parent, Map<Integer, List<Integer>> adj) {
        if (node == null) return;
        adj.computeIfAbsent(node.val, k -> new ArrayList<>());
        if (parent != null) {
            adj.computeIfAbsent(parent.val, k -> new ArrayList<>());
            adj.get(node.val).add(parent.val);
            adj.get(parent.val).add(node.val);
        }
        dfs(node.left, node, adj);
        dfs(node.right, node, adj);
    }
}

