import java.util.Arrays;

class Solution {
    public static int[] longestSubsequenceWithLimitedSum(int[] nums, int[] queries) {
        int n = nums.length;
        int[] sorted = Arrays.copyOf(nums, n);
        Arrays.sort(sorted);
        long[] prefix = new long[n];
        long running = 0;
        for (int i = 0; i < n; i++) {
            running += sorted[i];
            prefix[i] = running;
        }
        int[] answers = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int limit = queries[q];
            int lo = 0, hi = n - 1, best = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (prefix[mid] <= limit) {
                    best = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            answers[q] = best + 1;
        }
        return answers;
    }
}

import java.util.*;

class Solution {
    public static int[][] buildMatrix(int k, int[][] rowConditions, int[][] colConditions) {
        List<Integer> rowOrder = topologicalSort(k, rowConditions);
        List<Integer> colOrder = topologicalSort(k, colConditions);
        if (rowOrder == null || colOrder == null) {
            return new int[0][0];
        }
        int[][] matrix = new int[k][k];
        int[] rowPos = new int[k + 1];
        int[] colPos = new int[k + 1];
        for (int i = 0; i < k; i++) {
            rowPos[rowOrder.get(i)] = i;
            colPos[colOrder.get(i)] = i;
        }
        for (int num = 1; num <= k; num++) {
            int r = rowPos[num];
            int c = colPos[num];
            matrix[r][c] = num;
        }
        return matrix;
    }

    private static List<Integer> topologicalSort(int k, int[][] conditions) {
        List<Integer>[] graph = new ArrayList[k + 1];
        for (int i = 1; i <= k; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] cond : conditions) {
            graph[cond[0]].add(cond[1]);
        }
        int[] state = new int[k + 1]; // 0 = unvisited, 1 = visiting, 2 = visited
        List<Integer> order = new ArrayList<>();
        for (int i = 1; i <= k; i++) {
            if (state[i] == 0) {
                if (!dfs(i, graph, state, order)) {
                    return null;
                }
            }
        }
        Collections.reverse(order);
        return order;
    }

    private static boolean dfs(int node, List<Integer>[] graph, int[] state, List<Integer> order) {
        state[node] = 1;
        for (int nei : graph[node]) {
            if (state[nei] == 1) {
                return false;
            }
            if (state[nei] == 0) {
                if (!dfs(nei, graph, state, order)) {
                    return false;
                }
            }
        }
        state[node] = 2;
        order.add(node);
        return true;
    }
}

