class Solution {
    public static int maxRowsCovered(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[] rowMasks = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    mask |= (1 << j);
                }
            }
            rowMasks[i] = mask;
        }
        int[] best = new int[1];
        dfs(0, 0, 0, numSelect, n, rowMasks, best);
        return best[0];
    }

    private static void dfs(int start, int chosenMask, int chosenCnt, int numSelect, int n, int[] rowMasks, int[] best) {
        if (chosenCnt == numSelect) {
            int covered = 0;
            for (int mask : rowMasks) {
                if ((mask & ~chosenMask) == 0) {
                    covered++;
                }
            }
            if (covered > best[0]) {
                best[0] = covered;
            }
            return;
        }
        for (int col = start; col < n; col++) {
            dfs(col + 1, chosenMask | (1 << col), chosenCnt + 1, numSelect, n, rowMasks, best);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int maxRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        long sumRunning = 0;
        int best = 0;
        Deque<Integer> maxDeque = new ArrayDeque<>();

        for (int right = 0; right < n; right++) {
            sumRunning += runningCosts[right];

            while (!maxDeque.isEmpty() && chargeTimes[maxDeque.peekLast()] <= chargeTimes[right]) {
                maxDeque.pollLast();
            }
            maxDeque.offerLast(right);

            while (left <= right) {
                int currentMax = chargeTimes[maxDeque.peekFirst()];
                long totalCost = currentMax + (long) (right - left + 1) * sumRunning;
                if (totalCost <= budget) {
                    break;
                }
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                sumRunning -= runningCosts[left];
                left++;
            }

            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

import java.lang.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfWays(int startPos, int endPos, int k) {
        long distance = Math.abs((long) endPos - (long) startPos);
        if (distance > k) return 0;
        if ((k - distance) % 2 != 0) return 0;
        long rightMoves = (k + distance) / 2;
        return (int) nCr(k, (int) rightMoves);
    }

    private long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    private long modPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = result * b % MOD;
            }
            b = b * b % MOD;
            e >>= 1;
        }
        return result;
    }
}

