class Solution {
    private static class BusyRoom {
        long end;
        int room;
        BusyRoom(long end, int room) {
            this.end = end;
            this.room = room;
        }
    }

    public static int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, Comparator.comparingInt(a -> a[0]));

        PriorityQueue<Integer> freeRooms = new PriorityQueue<>();
        for (int i = 0; i < n; ++i) {
            freeRooms.offer(i);
        }

        PriorityQueue<BusyRoom> busyRooms = new PriorityQueue<>(
            (a, b) -> {
                int cmp = Long.compare(a.end, b.end);
                if (cmp != 0) return cmp;
                return Integer.compare(a.room, b.room);
            }
        );

        int[] count = new int[n];

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];

            while (!busyRooms.isEmpty() && busyRooms.peek().end <= start) {
                BusyRoom freed = busyRooms.poll();
                freeRooms.offer(freed.room);
            }

            if (!freeRooms.isEmpty()) {
                int room = freeRooms.poll();
                count[room] += 1;
                busyRooms.offer(new BusyRoom(end, room));
            } else {
                BusyRoom earliest = busyRooms.poll();
                int duration = end - start;
                long newEnd = earliest.end + duration;
                count[earliest.room] += 1;
                busyRooms.offer(new BusyRoom(newEnd, earliest.room));
            }
        }

        int bestRoom = 0;
        for (int i = 1; i < n; ++i) {
            if (count[i] > count[bestRoom]) {
                bestRoom = i;
            }
        }
        return bestRoom;
    }
}

