public class Solution {
    public static int tilingRectangle(int n, int m) {
        if (n == m) return 1;
        if (n > m) {
            int tmp = n;
            n = m;
            m = tmp;
        }
        int[] best = new int[]{n * m};
        boolean[][] board = new boolean[n][m];
        dfs(board, 0, 0, best);
        return best[0];
    }

    private static void dfs(boolean[][] board, int filled, int used, int[] best) {
        int rows = board.length;
        int cols = board[0].length;
        if (used >= best[0]) return;
        if (filled == rows * cols) {
            best[0] = used;
            return;
        }
        int r = 0, c = 0;
        outer:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!board[i][j]) {
                    r = i;
                    c = j;
                    break outer;
                }
            }
        }
        int maxSize = Math.min(rows - r, cols - c);
        for (int size = maxSize; size >= 1; size--) {
            if (canPlace(board, r, c, size)) {
                fill(board, r, c, size, true);
                dfs(board, filled + size * size, used + 1, best);
                fill(board, r, c, size, false);
            }
        }
    }

    private static boolean canPlace(boolean[][] board, int x, int y, int size) {
        for (int i = x; i < x + size; i++) {
            for (int j = y; j < y + size; j++) {
                if (board[i][j]) return false;
            }
        }
        return true;
    }

    private static void fill(boolean[][] board, int x, int y, int size, boolean val) {
        for (int i = x; i < x + size; i++) {
            for (int j = y; j < y + size; j++) {
                board[i][j] = val;
            }
        }
    }
}

