class Solution {
    public static List<List<Integer>> reconstructMatrix(int upper, int lower, int[] colsum) {
        int n = colsum.length;
        int[] row0 = new int[n];
        int[] row1 = new int[n];
        int remainingUpper = upper;
        int remainingLower = lower;
        int onesCount = 0;
        for (int i = 0; i < n; i++) {
            if (colsum[i] == 2) {
                row0[i] = 1;
                row1[i] = 1;
                remainingUpper--;
                remainingLower--;
                if (remainingUpper < 0 || remainingLower < 0) {
                    return new ArrayList<>();
                }
            } else if (colsum[i] == 1) {
                onesCount++;
            } else {
                row0[i] = 0;
                row1[i] = 0;
            }
        }
        if (remainingUpper + remainingLower != onesCount) {
            return new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            if (colsum[i] == 1) {
                if (remainingUpper > 0) {
                    row0[i] = 1;
                    row1[i] = 0;
                    remainingUpper--;
                } else {
                    row0[i] = 0;
                    row1[i] = 1;
                    remainingLower--;
                }
            }
        }
        if (remainingUpper != 0 || remainingLower != 0) {
            return new ArrayList<>();
        }
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> top = new ArrayList<>();
        List<Integer> bottom = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            top.add(row0[i]);
            bottom.add(row1[i]);
        }
        result.add(top);
        result.add(bottom);
        return result;
    }
}

