class Solution {
    private static int maxScore;

    public static int maxScoreWords(String[] words, char[] letters, int[] score) {
        Map<Character, Integer> letterCount = new HashMap<>();
        for (char letter : letters) {
            letterCount.put(letter, letterCount.getOrDefault(letter, 0) + 1);
        }
        maxScore = 0;
        backtrack(0, 0, letterCount, words, score);
        return maxScore;
    }

    private static void backtrack(int index, int currentScore, Map<Character, Integer> currentLetterCount,
                                  String[] words, int[] score) {
        maxScore = Math.max(maxScore, currentScore);
        for (int i = index; i < words.length; i++) {
            String word = words[i];
            int wordScore = 0;
            Map<Character, Integer> wordLetterCount = new HashMap<>();
            for (int j = 0; j < word.length(); j++) {
                char letter = word.charAt(j);
                wordLetterCount.put(letter, wordLetterCount.getOrDefault(letter, 0) + 1);
                wordScore += score[letter - 'a'];
            }
            boolean isValid = true;
            for (Map.Entry<Character, Integer> entry : wordLetterCount.entrySet()) {
                char letter = entry.getKey();
                int needed = entry.getValue();
                if (currentLetterCount.getOrDefault(letter, 0) < needed) {
                    isValid = false;
                    break;
                }
            }
            if (isValid) {
                Map<Character, Integer> newLetterCount = new HashMap<>(currentLetterCount);
                for (Map.Entry<Character, Integer> entry : wordLetterCount.entrySet()) {
                    char letter = entry.getKey();
                    int remaining = newLetterCount.get(letter) - entry.getValue();
                    newLetterCount.put(letter, remaining);
                }
                backtrack(i + 1, currentScore + wordScore, newLetterCount, words, score);
            }
        }
    }
}

