class Solution {
    public static int[] smallestSubarraysWithMaximumBitwiseOR(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            int maxOr = 0;
            for (int j = i; j < n; j++) {
                int or = 0;
                for (int k = i; k <= j; k++) {
                    or |= nums[k];
                }
                if (or > maxOr) {
                    maxOr = or;
                    result[i] = j - i + 1;
                } else if (or == maxOr) {
                    if (result[i] == 0) {
                        result[i] = j - i + 1;
                    } else {
                        result[i] = Math.min(result[i], j - i + 1);
                    }
                }
            }
        }
        return result;
    }
}

