public static TreeNode reverseOddLevels(TreeNode root) {
    if (root == null) return null;
    List<TreeNode> queue = new ArrayList<>();
    queue.add(root);
    int level = 0;
    while (!queue.isEmpty()) {
        if (level % 2 == 1) {
            int i = 0, j = queue.size() - 1;
            while (i < j) {
                TreeNode a = queue.get(i), b = queue.get(j);
                int temp = a.val; a.val = b.val; b.val = temp;
                i++; j--;
            }
        }
        List<TreeNode> nextQueue = new ArrayList<>();
        for (TreeNode node : queue) {
            if (node.left != null) nextQueue.add(node.left);
            if (node.right != null) nextQueue.add(node.right);
        }
        queue = nextQueue;
        level++;
    }
    return root;
}

