import java.util.*;

class Solution {
    public static int findLengthOfLCIS(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        List<Integer> uniqList = new ArrayList<>();
        for (int v : sorted) {
            if (uniqList.isEmpty() || uniqList.get(uniqList.size() - 1) != v) {
                uniqList.add(v);
            }
        }
        int m = uniqList.size();
        int size = 1;
        while (size < m) size <<= 1;
        int[] seg = new int[2 * size];
        int result = 1;
        for (int val : nums) {
            int leftVal = val - k;
            int l = lowerBound(uniqList, leftVal);
            int r = lowerBound(uniqList, val) - 1;
            int best = 0;
            if (l <= r) {
                best = query(seg, size, l, r);
            }
            int cur = best + 1;
            int pos = lowerBound(uniqList, val);
            update(seg, size, pos, cur);
            if (cur > result) result = cur;
        }
        return result;
    }

    private static int lowerBound(List<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    private static int query(int[] seg, int size, int l, int r) {
        l += size;
        r += size;
        int res = 0;
        while (l <= r) {
            if ((l & 1) == 1) res = Math.max(res, seg[l++]);
            if ((r & 1) == 0) res = Math.max(res, seg[r--]);
            l >>= 1;
            r >>= 1;
        }
        return res;
    }

    private static void update(int[] seg, int size, int pos, int value) {
        pos += size;
        seg[pos] = Math.max(seg[pos], value);
        for (pos >>= 1; pos > 0; pos >>= 1) {
            seg[pos] = Math.max(seg[pos << 1], seg[(pos << 1) | 1]);
        }
    }
}

