import java.util.*;

class Solution {
    public static long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] parent = new int[n];
        long[] segSum = new long[n];
        boolean[] active = new boolean[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
            int ra = find.applyAsInt(a);
            int rb = find.applyAsInt(b);
            if (ra == rb) return;
            parent[rb] = ra;
            segSum[ra] += segSum[rb];
        };

        long[] answer = new long[n];
        long maxSum = 0;

        for (int i = n - 1; i >= 0; i--) {
            answer[i] = maxSum;
            int idx = removeQueries[i];
            active[idx] = true;
            parent[idx] = idx;
            segSum[idx] = nums[idx];

            if (idx > 0 && active[idx - 1]) union.accept(idx, idx - 1);
            if (idx < n - 1 && active[idx + 1]) union.accept(idx, idx + 1);

            int root = find.applyAsInt(idx);
            if (segSum[root] > maxSum) maxSum = segSum[root];
        }

        return answer;
    }
}

