        }
        for (int i = 0; i < 26; i++) {
            if (freq[i] == 0) continue;
            freq[i]--;
            int common = -1;
            boolean ok = true;
            for (int f : freq) {
                if (f == 0) continue;
                if (common == -1) {
                    common = f;
                } else if (f != common) {
                    ok = false;
                    break;
                }
            }
