class Solution {
    public static int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> vals[i]));
        UnionFind uf = new UnionFind(n);
        int result = n;
        int i = 0;
        while (i < n) {
            int curVal = vals[order[i]];
            int j = i;
            while (j < n && vals[order[j]] == curVal) j++;
            for (int k = i; k < j; k++) {
                int node = order[k];
                for (int nb : graph[node]) {
                    if (vals[nb] <= curVal) {
                        uf.union(node, nb);
                    }
                }
            }
            Map<Integer, Integer> count = new HashMap<>();
            for (int k = i; k < j; k++) {
                int root = uf.find(order[k]);
                count.put(root, count.getOrDefault(root, 0) + 1);
            }
            for (int c : count.values()) {
                result += c * (c - 1) / 2;
            }
            i = j;
        }
        return result;
    }

    private static class UnionFind {
        int[] parent;
        int[] size;
        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                parent[ra] = rb;
                size[rb] += size[ra];
            } else {
                parent[rb] = ra;
                size[ra] += size[rb];
            }
        }
    }
}

