class Solution {
    public static long minimizeXOR(long num1, long num2) {
        int setBitsInNum2 = countSetBits(num2);
        int setBitsInNum1 = countSetBits(num1);
        if (setBitsInNum1 > setBitsInNum2) return num1;
        if (setBitsInNum1 < setBitsInNum2) return smallestNumberWithSetBits(setBitsInNum2);
        return num1;
    }

    private static int countSetBits(long n) {
        int count = 0;
        while (n != 0) {
            count++;
            n &= (n - 1);
        }
        return count;
    }

    private static long smallestNumberWithSetBits(int setBits) {
        if (setBits == 0) return 0L;
        return (1L << setBits) - 1L;
    }
}

