class Solution {
    public static List<Integer> productQueries(int n, List<int[]> queries) {
        List<Long> powers = new ArrayList<>();
        for (int i = 0; (1L << i) <= n; i++) {
            if ((n & (1L << i)) != 0) {
                powers.add(1L << i);
            }
        }
        final long MOD = 1_000_000_007L;
        List<Integer> result = new ArrayList<>();
        for (int[] q : queries) {
            long prod = 1;
            for (int i = q[0]; i <= q[1]; i++) {
                prod = (prod * powers.get(i)) % MOD;
            }
            result.add((int) prod);
        }
        return result;
    }
}

