class Solution {
    public static int subarrayGCD(int[] nums, int k) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int gcd = nums[i];
            for (int j = i; j < nums.length; j++) {
                gcd = getGCD(gcd, nums[j]);
                if (gcd == k) {
                    count++;
                }
            }
        }
        return count;
    }

    private static int getGCD(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

import java.util.*;

class Solution {
    public static int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        long totalSum = 0;
        for (int v : nums) totalSum += v;
        if (totalSum == 0) return n - 1;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        for (int k = n; k >= 1; k--) {
            if (totalSum % k != 0) continue;
            long target = totalSum / k;
            int[] count = new int[1];
            boolean[] invalid = new boolean[1];
            long sum = dfs(0, -1, target, count, invalid, graph, nums);
            if (!invalid[0] && count[0] == k && sum == 0) {
                return k - 1;
            }
        }
        return -1;
    }

    private static long dfs(int node, int parent, long target, int[] count, boolean[] invalid,
                            List<Integer>[] graph, int[] nums) {
        long cur = nums[node];
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            long childSum = dfs(nb, node, target, count, invalid, graph, nums);
            cur += childSum;
        }
        if (cur == target) {
            count[0]++;
            return 0;
        }
        if (cur > target) {
            invalid[0] = true;
        }
        return cur;
    }
}

