class Solution {
    public static long minimizeArrayValue(int[] nums) {
        long result = 0;
        long prefixSum = 0;
        for (int i = 0; i < nums.length; i++) {
            prefixSum += nums[i];
            long candidate = (prefixSum + i) / (i + 1);
            result = Math.max(result, candidate);
        }
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public static int minOperations(int[] nums, int[] target) {
        int n = nums.length;
        int[] a = Arrays.copyOf(nums, n);
        int[] b = Arrays.copyOf(target, n);
        Arrays.sort(a);
        Arrays.sort(b);
        long diff = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] < b[i]) {
                diff += b[i] - a[i];
            }
        }
        return (int) ((diff + 1) / 2);
    }
}

import java.lang.Math;

class Solution {
    public static long minCost(int[] nums, int[] cost) {
        long minCost = Long.MAX_VALUE;
        int minNum = Integer.MAX_VALUE;
        int maxNum = Integer.MIN_VALUE;
        for (int num : nums) {
            if (num < minNum) minNum = num;
            if (num > maxNum) maxNum = num;
        }
        for (int target = minNum; target <= maxNum; target++) {
            long totalCost = 0;
            for (int i = 0; i < nums.length; i++) {
                totalCost += Math.abs(nums[i] - target) * (long) cost[i];
            }
            if (totalCost < minCost) {
                minCost = totalCost;
            }
        }
        return minCost;
    }
}

