class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        int[][] prev = new int[n][k];
        int[][] curr = new int[n][k];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int[] cell = curr[j];
                Arrays.fill(cell, 0);
                int val = grid[i][j];
                if (i == 0 && j == 0) {
                    cell[val % k] = 1;
                } else {
                    if (i > 0) {
                        int[] fromTop = prev[j];
                        for (int r = 0; r < k; r++) {
                            int cnt = fromTop[r];
                            if (cnt != 0) {
                                int nr = (r + val) % k;
                                cell[nr] = (cell[nr] + cnt) % MOD;
                            }
                        }
                    }
                    if (j > 0) {
                        int[] fromLeft = curr[j - 1];
                        for (int r = 0; r < k; r++) {
                            int cnt = fromLeft[r];
                            if (cnt != 0) {
                                int nr = (r + val) % k;
                                cell[nr] = (cell[nr] + cnt) % MOD;
                            }
                        }
                    }
                }
            }
            // prepare for next row
            int[][] temp = prev;
            prev = curr;
            curr = new int[n][k];
        }

        return prev[n - 1][0];
    }
}

import java.util.*;

class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        char[] minSuffix = new char[n];
        char minChar = 'z' + 1;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) < minChar) {
                minChar = s.charAt(i);
            }
            minSuffix[i] = minChar;
        }

        StringBuilder stack = new StringBuilder();
        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < n) {
            stack.append(s.charAt(i));
            while (stack.length() > 0 && (i + 1 == n || stack.charAt(stack.length() - 1) <= minSuffix[i + 1])) {
                result.append(stack.charAt(stack.length() - 1));
                stack.setLength(stack.length() - 1);
            }
            i++;
        }
        while (stack.length() > 0) {
            result.append(stack.charAt(stack.length() - 1));
            stack.setLength(stack.length() - 1);
        }
        return result.toString();
    }
}

