class Solution {
    public static boolean checkDistances(String s, int[] distance) {
        int[] firstPos = new int[26];
        Arrays.fill(firstPos, -1);
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            if (firstPos[idx] == -1) {
                firstPos[idx] = i;
            } else {
                int requiredGap = distance[idx];
                int actualGap = i - firstPos[idx] - 1;
                if (actualGap != requiredGap) {
                    return false;
                }
            }
        }
        return true;
    }
}

