class Solution {
    public static String oddString(String[] words) {
        Map<String, List<String>> differenceMap = new HashMap<>();
        for (String word : words) {
            StringBuilder keyBuilder = new StringBuilder();
            for (int i = 0; i < word.length() - 1; i++) {
                int diff = word.charAt(i + 1) - word.charAt(i);
                keyBuilder.append(diff);
                if (i < word.length() - 2) {
                    keyBuilder.append(',');
                }
            }
            String key = keyBuilder.toString();
            differenceMap.computeIfAbsent(key, k -> new ArrayList<>()).add(word);
        }
        for (Map.Entry<String, List<String>> entry : differenceMap.entrySet()) {
            if (entry.getValue().size() == 1) {
                return entry.getValue().get(0);
            }
        }
        return null;
    }
}

import java.lang.Math;

class Solution {
    public static int averageOfEvenNumbersDivisibleByThree(int[] nums) {
        int sum = 0, count = 0;
        for (int num : nums) {
            if (num % 2 == 0 && num % 3 == 0) {
                sum += num;
                count++;
            }
        }
        if (count == 0) return 0;
        return (int) Math.floor((double) sum / count);
    }
}

