class Solution {
    public static List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        class CreatorInfo {
            long totalViews;
            int maxViews;
            String maxViewId;
            CreatorInfo(long totalViews, int maxViews, String maxViewId) {
                this.totalViews = totalViews;
                this.maxViews = maxViews;
                this.maxViewId = maxViewId;
            }
        }

        Map<String, CreatorInfo> map = new HashMap<>();
        for (int i = 0; i < creators.length; i++) {
            String creator = creators[i];
            String id = ids[i];
            int view = views[i];
            CreatorInfo info = map.get(creator);
            if (info == null) {
                map.put(creator, new CreatorInfo(view, view, id));
            } else {
                info.totalViews += view;
                if (view > info.maxViews || (view == info.maxViews && id.compareTo(info.maxViewId) < 0)) {
                    info.maxViews = view;
                    info.maxViewId = id;
                }
            }
        }

        long maxTotal = 0;
        for (CreatorInfo info : map.values()) {
            if (info.totalViews > maxTotal) {
                maxTotal = info.totalViews;
            }
        }

        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, CreatorInfo> entry : map.entrySet()) {
            CreatorInfo info = entry.getValue();
            if (info.totalViews == maxTotal) {
                List<String> pair = new ArrayList<>(2);
                pair.add(entry.getKey());
                pair.add(info.maxViewId);
                result.add(pair);
            }
        }

        result.sort(Comparator.comparing(list -> list.get(0)));
        return result;
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;

class Solution {
    public static int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        Arrays.fill(result, -1);
        ArrayDeque<Integer> first = new ArrayDeque<>();
        ArrayDeque<Integer> second = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!second.isEmpty() && nums[second.peek()] < nums[i]) {
                result[second.pop()] = nums[i];
            }
            while (!first.isEmpty() && nums[first.peek()] < nums[i]) {
                second.push(first.pop());
            }
            first.push(i);
        }
        return result;
    }
}

