class Solution {
    public static List<String> twoEditWords(List<String> queries, List<String> dictionary) {
        List<String> result = new ArrayList<>();
        for (String query : queries) {
            for (String dictWord : dictionary) {
                if (editsBetween(query, dictWord) <= 2) {
                    result.add(query);
                    break;
                }
            }
        }
        return result;
    }

    private static int editsBetween(String word1, String word2) {
        int edits = 0;
        for (int i = 0; i < word1.length(); i++) {
            if (word1.charAt(i) != word2.charAt(i)) {
                edits++;
            }
            if (edits > 2) {
                return edits;
            }
        }
        return edits;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int maximumSum(int[] nums, int k) {
        int maxSum = 0;
        for (int i = 0; i <= nums.length - k; i++) {
            int currentSum = 0;
            Set<Integer> uniqueElements = new HashSet<>();
            for (int j = i; j < i + k; j++) {
                currentSum += nums[j];
                uniqueElements.add(nums[j]);
            }
            if (uniqueElements.size() == k) {
                maxSum = Math.max(maxSum, currentSum);
            }
        }
        return maxSum;
    }
}

class Solution {
    public static int[] applyOperations(int[] nums) {
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] *= 2;
                nums[i + 1] = 0;
            }
        }
        int left = 0, right = 0;
        while (right < nums.length) {
            if (nums[right] != 0) {
                int temp = nums[left];
                nums[left] = nums[right];
                nums[right] = temp;
                left++;
            }
            right++;
        }
        return nums;
    }
}

