class Solution {
    public static int destroyTargets(int[] nums, int space) {
        Map<Integer, List<Integer>> countMap = new HashMap<>();
        for (int num : nums) {
            int remainder = num % space;
            countMap.computeIfAbsent(remainder, k -> new ArrayList<>()).add(num);
        }
        int maxCount = 0;
        int minSeed = Integer.MAX_VALUE;
        for (List<Integer> group : countMap.values()) {
            int count = group.size();
            if (count > maxCount) {
                maxCount = count;
                minSeed = Collections.min(group);
            } else if (count == maxCount) {
                minSeed = Math.min(minSeed, Collections.min(group));
            }
        }
        return minSeed;
    }
}

private static int getHeight(TreeNode node) {
    if (node == null) return -1;
    int leftHeight = getHeight(node.left);
    int rightHeight = getHeight(node.right);
    return Math.max(leftHeight, rightHeight) + 1;
}

