public class Solution {
    public static long minimumTotalDistance(int[] robot, int[][] factory) {
        Arrays.sort(robot);
        Arrays.sort(factory, (a, b) -> Integer.compare(a[0], b[0]));
        long totalDistance = 0;
        int robotIndex = 0;
        for (int i = 0; i < factory.length; i++) {
            int factoryPosition = factory[i][0];
            int limit = factory[i][1];
            List<Integer> distances = new ArrayList<>();
            while (robotIndex < robot.length && limit > 0) {
                distances.add(Math.abs(robot[robotIndex] - factoryPosition));
                robotIndex++;
                limit--;
            }
            distances.sort(Integer::compareTo);
            for (int d : distances) {
                totalDistance += d;
            }
        }
        return totalDistance;
    }
}

