class Solution {
    public static int longestTaskEmployee(int n, int[][] logs) {
        int previousLeave = 0;
        int maxDuration = 0;
        int employeeId = 0;
        for (int i = 0; i < logs.length; i++) {
            int id = logs[i][0];
            int leaveTime = logs[i][1];
            int duration = leaveTime - previousLeave;
            if (duration > maxDuration || (duration == maxDuration && id < employeeId)) {
                maxDuration = duration;
                employeeId = id;
            }
            previousLeave = leaveTime;
        }
        return employeeId;
    }
}

