class Solution {
    public static int findPivotInteger(int n) {
        long totalSum = ((long) n * (n + 1)) / 2;
        long leftSum = 0;
        for (int x = 1; x <= n; x++) {
            if (leftSum == totalSum - leftSum - x) {
                return x;
            }
            leftSum += x;
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public long mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }

        int[] parent = new int[n];
        int[] distRoot = new int[n];
        Arrays.fill(parent, -1);
        Arrays.fill(distRoot, -1);
        Queue<Integer> q = new ArrayDeque<>();
        q.add(0);
        distRoot[0] = 0;
        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : adj[cur]) {
                if (distRoot[nb] == -1) {
                    distRoot[nb] = distRoot[cur] + 1;
                    parent[nb] = cur;
                    q.add(nb);
                }
            }
        }

        boolean[] onPath = new boolean[n];
        int[] distBob = new int[n];
        Arrays.fill(distBob, -1);
        int cur = bob;
        int step = 0;
        while (true) {
            onPath[cur] = true;
            distBob[cur] = step;
            if (cur == 0) break;
            cur = parent[cur];
            step++;
        }

        long[] profit = new long[n];
        for (int i = 0; i < n; i++) {
            if (!onPath[i]) {
                profit[i] = amount[i];
            } else {
                if (distRoot[i] < distBob[i]) {
                    profit[i] = amount[i];
                } else if (distRoot[i] > distBob[i]) {
                    profit[i] = 0;
                } else {
                    profit[i] = amount[i] / 2;
                }
            }
        }

        long ans = Long.MIN_VALUE;
        Deque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{0, -1, profit[0]});
        while (!stack.isEmpty()) {
            long[] data = stack.pop();
            int node = (int) data[0];
            int parentNode = (int) data[1];
            long sum = data[2];
            boolean isLeaf = (node != 0 && adj[node].size() == 1) || (node == 0 && adj[node].isEmpty());
            if (isLeaf) {
                ans = Math.max(ans, sum);
            }
            for (int nb : adj[node]) {
                if (nb == parentNode) continue;
                stack.push(new long[]{nb, node, sum + profit[nb]});
            }
        }
        return ans;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int countSubarraysWithMedianK(int[] nums, int k) {
        int n = nums.length;
        int pos = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                pos = i;
                break;
            }
        }
        if (pos == -1) {
            return 0;
        }
        Map<Integer, Integer> leftCounts = new HashMap<>();
        int balance = 0;
        leftCounts.put(0, 1);
        for (int i = pos - 1; i >= 0; i--) {
            if (nums[i] > k) {
                balance++;
            } else if (nums[i] < k) {
                balance--;
            }
            leftCounts.put(balance, leftCounts.getOrDefault(balance, 0) + 1);
        }
        int result = leftCounts.getOrDefault(0, 0) + leftCounts.getOrDefault(1, 0);
        int rightBalance = 0;
        for (int i = pos + 1; i < n; i++) {
            if (nums[i] > k) {
                rightBalance++;
            } else if (nums[i] < k) {
                rightBalance--;
            }
            result += leftCounts.getOrDefault(-rightBalance, 0);
            result += leftCounts.getOrDefault(1 - rightBalance, 0);
        }
        return result;
    }
}

import java.util.*;

class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

class Solution {
    public ListNode removeNodes(ListNode head) {
        ListNode prev = null;
        ListNode cur = head;
        while (cur != null) {
            ListNode nxt = cur.next;
            cur.next = prev;
            prev = cur;
            cur = nxt;
        }
        ListNode revHead = prev;

        int maxSeen = Integer.MIN_VALUE;
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        cur = revHead;
        while (cur != null) {
            if (cur.val >= maxSeen) {
                maxSeen = cur.val;
                tail.next = cur;
                tail = cur;
            }
            cur = cur.next;
        }
        tail.next = null;

        prev = null;
        cur = dummy.next;
        while (cur != null) {
            ListNode nxt = cur.next;
            cur.next = prev;
            prev = cur;
            cur = nxt;
        }
        return prev;
    }
}

