class Solution {
    public static int minimumPenalty(String customers) {
        int n = customers.length();
        int totalY = 0;
        for (int i = 0; i < n; i++) {
            if (customers.charAt(i) == 'Y') totalY++;
        }
        int minPenalty = Integer.MAX_VALUE;
        int answer = 0;
        int nBefore = 0;
        int yBefore = 0;
        for (int i = 0; i <= n; i++) {
            int yAfter = totalY - yBefore;
            int penalty = nBefore + yAfter;
            if (penalty < minPenalty) {
                minPenalty = penalty;
                answer = i;
            }
            if (i < n) {
                char c = customers.charAt(i);
                if (c == 'N') nBefore++;
                else if (c == 'Y') yBefore++;
            }
        }
        return answer;
    }
}

