class Solution {
    public int magnificentSets(int n, List<List<Integer>> edges) {
        List<List<Integer>> adj = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (List<Integer> e : edges) {
            int u = e.get(0);
            int v = e.get(1);
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        boolean[] visited = new boolean[n + 1];
        int[] color = new int[n + 1];
        Arrays.fill(color, -1);
        int totalGroups = 0;

        for (int i = 1; i <= n; i++) {
            if (visited[i]) continue;

            List<Integer> comp = new ArrayList<>();
            List<Integer> queue = new ArrayList<>();
            queue.add(i);
            visited[i] = true;
            color[i] = 0;
            comp.add(i);
            boolean bipartite = true;
            for (int qIdx = 0; qIdx < queue.size(); qIdx++) {
                int u = queue.get(qIdx);
                for (int v : adj.get(u)) {
                    if (!visited[v]) {
                        visited[v] = true;
                        color[v] = color[u] ^ 1;
                        queue.add(v);
                        comp.add(v);
                    } else if (color[v] == color[u]) {
                        bipartite = false;
                    }
                }
            }
            if (!bipartite) return -1;

            int diameter = 0;
            for (int start : comp) {
                int[] dist = new int[n + 1];
                Arrays.fill(dist, -1);
                List<Integer> q = new ArrayList<>();
                q.add(start);
                dist[start] = 0;
                for (int idx = 0; idx < q.size(); idx++) {
                    int u = q.get(idx);
                    for (int v : adj.get(u)) {
                        if (dist[v] == -1) {
                            dist[v] = dist[u] + 1;
                            q.add(v);
                        }
                    }
                }
                for (int node : comp) {
                    if (dist[node] > diameter) {
                        diameter = dist[node];
                    }
                }
            }

            totalGroups += diameter + 1;
        }

        return totalGroups;
    }
}

