class Solution {
    public int longestSquareStreak(int[] nums) {
        Arrays.sort(nums);
        Map<Integer, Integer> dp = new HashMap<>();
        int maxLen = 0;
        for (int v : nums) {
            int len = 1;
            int r = (int) Math.sqrt(v);
            if (r * r == v && dp.containsKey(r)) {
                len = dp.get(r) + 1;
            }
            dp.put(v, len);
            if (len > maxLen) {
                maxLen = len;
            }
        }
        return maxLen >= 2 ? maxLen : -1;
    }
}

import java.util.PriorityQueue;

class Solution {
    public static long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        int leftEnd = Math.min(candidates, n);
        int rightStart = Math.max(n - candidates, leftEnd);
        PriorityQueue<Integer> left = new PriorityQueue<>();
        PriorityQueue<Integer> right = new PriorityQueue<>();
        for (int i = 0; i < leftEnd; i++) {
            left.add(costs[i]);
        }
        for (int i = rightStart; i < n; i++) {
            right.add(costs[i]);
        }
        int leftIdx = leftEnd;
        int rightIdx = rightStart - 1;
        long total = 0;
        for (int hired = 0; hired < k; hired++) {
            int leftTop = left.isEmpty() ? Integer.MAX_VALUE : left.peek();
            int rightTop = right.isEmpty() ? Integer.MAX_VALUE : right.peek();
            if (leftTop <= rightTop) {
                total += left.poll();
                if (leftIdx <= rightIdx) {
                    left.add(costs[leftIdx]);
                    leftIdx++;
                }
            } else {
                total += right.poll();
                if (leftIdx <= rightIdx) {
                    right.add(costs[rightIdx]);
                    rightIdx--;
                }
            }
        }
        return total;
    }
}

