class Solution {
    public static int minScore(int n, int[][] roads) {
        List<int[]>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] road : roads) {
            int u = road[0];
            int v = road[1];
            int w = road[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }
        boolean[] visited = new boolean[n + 1];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(1);
        visited[1] = true;
        int minScore = Integer.MAX_VALUE;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            for (int[] edge : adj[node]) {
                int nbr = edge[0];
                int w = edge[1];
                if (w < minScore) {
                    minScore = w;
                }
                if (!visited[nbr]) {
                    visited[nbr] = true;
                    stack.push(nbr);
                }
            }
        }
        return minScore;
    }
}

