class Solution {
    public static long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long INF = 4_000_000_000_000_000_000L;
        long[][] cost = new long[n][n];
        for (int i = 0; i < n; ++i) {
            Arrays.fill(cost[i], INF);
        }
        for (int p = 0; p < n; ++p) {
            for (int i = 0; i < n; ++i) {
                if (nums1[p] == nums2[i]) continue;
                if (p == i) cost[p][i] = 0;
                else cost[p][i] = p + i;
            }
        }

        long[] u = new long[n + 1];
        long[] v = new long[n + 1];
        int[] pMatch = new int[n + 1];
        int[] way = new int[n + 1];

        for (int i = 1; i <= n; ++i) {
            pMatch[0] = i;
            int j0 = 0;
            long[] minv = new long[n + 1];
            Arrays.fill(minv, INF);
            boolean[] used = new boolean[n + 1];
            do {
                used[j0] = true;
                int i0 = pMatch[j0];
                long delta = INF;
                int j1 = 0;
                for (int j = 1; j <= n; ++j) {
                    if (used[j]) continue;
                    long cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
                for (int j = 0; j <= n; ++j) {
                    if (used[j]) {
                        u[pMatch[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (pMatch[j0] != 0);
            do {
                int j1 = way[j0];
                pMatch[j0] = pMatch[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        int[] assignment = new int[n];
        Arrays.fill(assignment, -1);
        for (int j = 1; j <= n; ++j) {
            if (pMatch[j] != 0) {
                assignment[pMatch[j] - 1] = j - 1;
            }
        }

        long total = 0;
        for (int i = 0; i < n; ++i) {
            long c = cost[i][assignment[i]];
            if (c >= INF / 2) return -1;
            total += c;
        }
        return total / 2;
    }
}

