class Allocator {
    private static class Interval {
        int start;
        int end;
        Interval(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    private final List<Interval> free;
    private final Map<Integer, List<int[]>> allocations = new HashMap<>();

    public Allocator(int n) {
        free = new ArrayList<>();
        free.add(new Interval(0, n - 1));
    }

    public int allocate(int size, int mID) {
        for (int i = 0; i < free.size(); i++) {
            Interval interval = free.get(i);
            int length = interval.end - interval.start + 1;
            if (length >= size) {
                int allocStart = interval.start;
                if (length == size) {
                    free.remove(i);
                } else {
                    interval.start += size;
                }
                allocations.computeIfAbsent(mID, k -> new ArrayList<>()).add(new int[]{allocStart, size});
                return allocStart;
            }
        }
        return -1;
    }

    private void freeInterval(int start, int size) {
        int newStart = start;
        int newEnd = start + size - 1;
        int i = 0;
        while (i < free.size() && free.get(i).end < newStart - 1) {
            i++;
        }
        if (i > 0 && free.get(i - 1).end + 1 >= newStart) {
            Interval prev = free.get(i - 1);
            newStart = prev.start;
            newEnd = Math.max(newEnd, prev.end);
            free.remove(i - 1);
            i--;
        }
        while (i < free.size() && free.get(i).start <= newEnd + 1) {
            Interval cur = free.get(i);
            newStart = Math.min(newStart, cur.start);
            newEnd = Math.max(newEnd, cur.end);
            free.remove(i);
        }
        free.add(i, new Interval(newStart, newEnd));
    }

    public int freeMemory(int mID) {
        List<int[]> blocks = allocations.remove(mID);
        if (blocks == null) {
            return 0;
        }
        int freed = 0;
        for (int[] b : blocks) {
            freeInterval(b[0], b[1]);
            freed += b[1];
        }
        return freed;
    }
}

