class Solution {
    public boolean isPossible(int n, int[][] edges) {
        int[] degree = new int[n + 1];
        Set<Long> edgeSet = new HashSet<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            degree[u]++;
            degree[v]++;
            int a = Math.min(u, v);
            int b = Math.max(u, v);
            long key = ((long) a << 32) | (long) b;
            edgeSet.add(key);
        }

        List<Integer> odd = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if ((degree[i] & 1) == 1) {
                odd.add(i);
            }
        }

        int oddCount = odd.size();
        if (oddCount == 0) {
            return true;
        }
        if (oddCount > 4) {
            return false;
        }

        if (oddCount == 2) {
            int a = odd.get(0);
            int b = odd.get(1);
            long keyAB = ((long) Math.min(a, b) << 32) | (long) Math.max(a, b);
            if (!edgeSet.contains(keyAB)) {
                return true;
            }
            for (int c = 1; c <= n; c++) {
                if (c == a || c == b) continue;
                long keyAc = ((long) Math.min(a, c) << 32) | (long) Math.max(a, c);
                long keyBc = ((long) Math.min(b, c) << 32) | (long) Math.max(b, c);
                if (!edgeSet.contains(keyAc) && !edgeSet.contains(keyBc)) {
                    return true;
                }
            }
            return false;
        }

        // oddCount == 4
        int[] o = new int[4];
        for (int i = 0; i < 4; i++) {
            o[i] = odd.get(i);
        }
        int[][] pairings = { {0, 1, 2, 3}, {0, 2, 1, 3}, {0, 3, 1, 2} };
        for (int[] p : pairings) {
            long key1 = ((long) Math.min(o[p[0]], o[p[1]]) << 32) | (long) Math.max(o[p[0]], o[p[1]]);
            long key2 = ((long) Math.min(o[p[2]], o[p[3]]) << 32) | (long) Math.max(o[p[2]], o[p[3]]);
            if (!edgeSet.contains(key1) && !edgeSet.contains(key2)) {
                return true;
            }
        }
        return false;
    }
}

