        Map<Integer, Integer> freq = new HashMap<>();
        for (String w : words) {
            int mask = 0;
            for (int i = 0; i < w.length(); i++) {
                char ch = w.charAt(i);
                mask |= 1 << (ch - 'a');
            }
            freq.put(mask, freq.getOrDefault(mask, 0) + 1);
        }
