public class Solution {
    public int smallestValue(int n) {
        int cur = n;
        while (true) {
            int sum = sumPrimeFactors(cur);
            if (sum == cur) break;
            cur = sum;
        }
        return cur;
    }

    private int sumPrimeFactors(int x) {
        int sum = 0;
        int temp = x;
        for (int p = 2; p * p <= temp; ++p) {
            while (temp % p == 0) {
                sum += p;
                temp /= p;
            }
        }
        if (temp > 1) sum += temp;
        return sum;
    }
}

