class Solution {
    public static List<Integer> topStudents(String[] positive_feedback, String[] negative_feedback, String[] report, int[] student_id, int k) {
        Set<String> posSet = new HashSet<>(Arrays.asList(positive_feedback));
        Set<String> negSet = new HashSet<>(Arrays.asList(negative_feedback));
        Map<Integer, Integer> points = new HashMap<>();
        for (int i = 0; i < report.length; i++) {
            int id = student_id[i];
            String[] words = report[i].split(" ");
            int score = 0;
            for (String w : words) {
                if (posSet.contains(w)) {
                    score += 3;
                } else if (negSet.contains(w)) {
                    score -= 1;
                }
            }
            points.put(id, points.getOrDefault(id, 0) + score);
        }
        List<Student> students = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : points.entrySet()) {
            students.add(new Student(entry.getKey(), entry.getValue()));
        }
        students.sort((a, b) -> {
            if (b.pt != a.pt) return b.pt - a.pt;
            return a.id - b.id;
        });
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k && i < students.size(); i++) {
            result.add(students.get(i).id);
        }
        return result;
    }

