class Solution {
    public int minMinutes(String s, int k) {
        int n = s.length();
        int[] total = new int[3];
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            total[ch - 'a']++;
        }
        if (total[0] < k || total[1] < k || total[2] < k) {
            return -1;
        }
        int[] allowed = new int[3];
        allowed[0] = total[0] - k;
        allowed[1] = total[1] - k;
        allowed[2] = total[2] - k;

        int[] window = new int[3];
        int maxLen = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            int idx = s.charAt(right) - 'a';
            window[idx]++;
            while (window[0] > allowed[0] || window[1] > allowed[1] || window[2] > allowed[2]) {
                int lIdx = s.charAt(left) - 'a';
                window[lIdx]--;
                left++;
            }
            int curLen = right - left + 1;
            if (curLen > maxLen) {
                maxLen = curLen;
            }
        }
        return n - maxLen;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public int countAnagrams(String s) {
        int n = s.length();
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        String[] words = s.split(" ");
        long ans = 1;
        for (String w : words) {
            int len = w.length();
            int[] cnt = new int[26];
            for (int i = 0; i < len; i++) {
                cnt[w.charAt(i) - 'a']++;
            }
            long ways = fact[len];
            for (int c : cnt) {
                if (c > 1) {
                    ways = ways * invFact[c] % MOD;
                }
            }
            ans = ans * ways % MOD;
        }
        return (int) ans;
    }

    private long modPow(long a, long e) {
        long res = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

