class Solution {
    public static int distinctPrimeFactors(int[] nums) {
        Set<Integer> primeSet = new HashSet<>();
        for (int value : nums) {
            long n = value;
            if (n < 2) continue;
            while (n % 2 == 0) {
                primeSet.add(2);
                n /= 2;
            }
            for (long f = 3; f * f <= n; f += 2) {
                while (n % f == 0) {
                    primeSet.add((int) f);
                    n /= f;
                }
            }
            if (n > 1) primeSet.add((int) n);
        }
        return primeSet.size();
    }
}

