class Solution {
    public static int shortestDistance(String[] words, String target, int startIndex) {
        int n = words.length;
        int minDist = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (!words[i].equals(target)) continue;
            int clockwise = (i - startIndex + n) % n;
            int counter = (startIndex - i + n) % n;
            int dist = Math.min(clockwise, counter);
            if (dist < minDist) minDist = dist;
        }
        return minDist == Integer.MAX_VALUE ? -1 : minDist;
    }
}

