import java.util.*;

class Solution {
    public static long minimizeMaximum(int divisor1, int divisor2, int uniqueCnt1, int uniqueCnt2) {
        long d1 = divisor1;
        long d2 = divisor2;
        long cnt1 = uniqueCnt1;
        long cnt2 = uniqueCnt2;
        long g = gcd(d1, d2);
        long lcm = d1 / g * d2;

        long low = 1;
        long high = Math.max(d1, d2) * (cnt1 + cnt2);
        if (high < 1) high = 1;
        while (!can(high, d1, d2, cnt1, cnt2, lcm)) {
            high *= 2;
        }

        while (low < high) {
            long mid = low + (high - low) / 2;
            if (can(mid, d1, d2, cnt1, cnt2, lcm)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean can(long m, long d1, long d2, long cnt1, long cnt2, long lcm) {
        long only1 = m / d2 - m / lcm; // not divisible by d1, divisible by d2
        long only2 = m / d1 - m / lcm; // not divisible by d2, divisible by d1
        long both = m - m / d1 - m / d2 + m / lcm; // not divisible by either

        long needBoth1 = Math.max(0L, cnt1 - only1);
        long needBoth2 = Math.max(0L, cnt2 - only2);
        return needBoth1 + needBoth2 <= both;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

