class Solution {
    public static int numberOfGreatPartitions(int[] nums, int k) {
        final int MOD = 1000000007;
        int total = 0;
        for (int x : nums) {
            total += x;
        }
        if (total < 2 * k) {
            return 0;
        }
        int[] dp = new int[total + 1];
        dp[0] = 1;
        for (int x : nums) {
            for (int s = total; s >= x; s--) {
                dp[s] = (dp[s] + dp[s - x]) % MOD;
            }
        }
        long ans = 0;
        for (int s = k; s <= total - k; s++) {
            ans = (ans + dp[s]) % MOD;
        }
        return (int) ans;
    }
}

