class Solution {
    public static long maxPower(int[] stations, int r, int k) {
        int n = stations.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + stations[i];
        }
        long[] base = new long[n];
        for (int i = 0; i < n; i++) {
            int left = Math.max(0, i - r);
            int right = Math.min(n - 1, i + r);
            base[i] = pref[right + 1] - pref[left];
        }
        long low = 0;
        long high = 0;
        for (long v : base) {
            if (v > high) high = v;
        }
        high += k; // maximum possible minimum power
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            if (canAchieve(base, n, r, k, mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean canAchieve(long[] base, int n, int r, int k, long target) {
        long[] diff = new long[n];
        long curAdd = 0;
        long used = 0;
        for (int i = 0; i < n; i++) {
            curAdd += diff[i];
            long total = base[i] + curAdd;
            if (total < target) {
                long need = target - total;
                used += need;
                if (used > k) return false;
                curAdd += need;
                int pos = Math.min(i + r, n - 1);
                int endIdx = pos + r + 1;
                if (endIdx < n) diff[endIdx] -= need;
            }
        }
        return true;
    }
}

