class Solution {
    public static int maxCount(int[] nums) {
        int n = nums.length;
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (nums[mid] < 0) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        int firstNonNeg = lo;
        lo = 0;
        hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (nums[mid] <= 0) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        int firstPos = lo;
        int negCount = firstNonNeg;
        int posCount = n - firstPos;
        return Math.max(negCount, posCount);
    }
}

