                if (a == b) {
                    if (d1 == d2) return true;
                    continue;
                }
                int newD1 = d1;
                int newD2 = d2;
                if (freq1[a] == 1) newD1--;
                if (freq1[b] == 0) newD1++;
                if (freq2[b] == 1) newD2--;
                if (freq2[a] == 0) newD2++;
                if (newD1 == newD2) return true;
            }
        }
        return false;
    }
}

