public class Solution {
    public static long timeToCrossBridge(int n, int k, int[][] time) {
        int[] right = new int[k], pick = new int[k], left = new int[k], put = new int[k], crossSum = new int[k];
        for (int i = 0; i < k; i++) {
            right[i] = time[i][0]; pick[i] = time[i][1];
            left[i] = time[i][2]; put[i] = time[i][3];
            crossSum[i] = right[i] + left[i];
        }

        Comparator<Integer> effCmp = (a, b) -> {
            if (crossSum[a] != crossSum[b]) return crossSum[b] - crossSum[a]; // higher crossSum first
            return b - a; // higher index first
        };
        PriorityQueue<Integer> waitingLeft = new PriorityQueue<>(effCmp);
        PriorityQueue<Integer> waitingRight = new PriorityQueue<>(effCmp);
        for (int i = 0; i < k; i++) waitingLeft.offer(i);

        PriorityQueue<long[]> workingRight = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        PriorityQueue<long[]> workingLeft = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));

        long currentTime = 0;
        int boxesLeftToPick = n, boxesPut = 0;

        while (boxesPut < n) {
            while (!workingRight.isEmpty() && workingRight.peek()[0] <= currentTime) {
                long[] e = workingRight.poll();
                waitingRight.offer((int) e[1]);
            }
            while (!workingLeft.isEmpty() && workingLeft.peek()[0] <= currentTime) {
                long[] e = workingLeft.poll();
                waitingLeft.offer((int) e[1]);
            }

            if (!waitingRight.isEmpty()) {
                int idx = waitingRight.poll();
                currentTime += left[idx];
                boxesPut++;
                if (boxesPut == n) return currentTime;
                workingLeft.offer(new long[]{currentTime + put[idx], idx});
            } else if (!waitingLeft.isEmpty() && boxesLeftToPick > 0) {
                int idx = waitingLeft.poll();
                boxesLeftToPick--;
                currentTime += right[idx];
                workingRight.offer(new long[]{currentTime + pick[idx], idx});
            } else {
                long next = Long.MAX_VALUE;
                if (!workingRight.isEmpty()) next = Math.min(next, workingRight.peek()[0]);
                if (!workingLeft.isEmpty()) next = Math.min(next, workingLeft.peek()[0]);
                currentTime = next;
            }
        }
        return currentTime;
    }
}

public class Solution {
