class Solution {
    public static long countGoodSubarrays(int[] nums, int k) {
        int n = nums.length;
        if (k == 0) return ((long) n * (n + 1)) / 2;
        Map<Integer, Integer> freq = new HashMap<>();
        int left = 0;
        long pairs = 0;
        long answer = 0;
        for (int right = 0; right < n; right++) {
            int val = nums[right];
            int cnt = freq.getOrDefault(val, 0);
            pairs += cnt;
            freq.put(val, cnt + 1);
            while (pairs >= k) {
                answer += n - right;
                int leftVal = nums[left];
                int leftCnt = freq.get(leftVal);
                pairs -= leftCnt - 1;
                freq.put(leftVal, leftCnt - 1);
                left++;
            }
        }
        return answer;
    }
}

