class Solution {
    public static int maxNonOverlappingPalindromeSubstrings(String s, int k) {
        int count = 0;
        int left = 0;
        while (left < s.length()) {
            boolean found = false;
            for (int right = left + k; right <= s.length(); right++) {
                String substring = s.substring(left, right);
                if (isPalindrome(substring)) {
                    count++;
                    left = right;
                    found = true;
                    break;
                }
            }
            if (!found) {
                left++;
            }
        }
        return count;
    }

    private static boolean isPalindrome(String str) {
        int i = 0;
        int j = str.length() - 1;
        while (i < j) {
            if (str.charAt(i) != str.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
}

