class Solution {
    public static int minimumFuelCost(int[][] roads, int seats) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < roads.length; i++) {
            int a = roads[i][0];
            int b = roads[i][1];
            graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            graph.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }
        int[] res = new int[1];
        dfs(0, -1, graph, seats, res);
        return res[0];
    }

    private static int dfs(int node, int parent, Map<Integer, List<Integer>> graph, int seats, int[] res) {
        int representatives = 1;
        List<Integer> neighbors = graph.get(node);
        if (neighbors != null) {
            for (int child : neighbors) {
                if (child != parent) {
                    representatives += dfs(child, node, graph, seats, res);
                }
            }
        }
        if (node != 0) {
            res[0] += (representatives + seats - 1) / seats;
        }
        return representatives;
    }
}

