class Solution {
    public static String[] splitMessage(String message, int limit) {
        int n = message.length();
        for (int b = 1; b <= n; b++) {
            int[] caps = new int[b + 1];
            boolean ok = true;
            int prefixSum = 0;
            for (int i = 1; i <= b; i++) {
                int suffixLen = 3 + digits(i) + digits(b);
                int cap = limit - suffixLen;
                if (cap < 0) {
                    ok = false;
                    break;
                }
                caps[i] = cap;
                if (i < b) {
                    prefixSum += cap;
                }
            }
            if (!ok) continue;
            int totalCap = prefixSum + caps[b];
            if (prefixSum > n) continue;
            if (totalCap < n) continue;
            List<String> parts = new ArrayList<>();
            int pos = 0;
            for (int i = 1; i <= b; i++) {
                int take = (i == b) ? n - pos : caps[i];
                String segment = message.substring(pos, pos + take);
                pos += take;
                String suffix = "<" + i + "/" + b + ">";
                parts.add(segment + suffix);
            }
            return parts.toArray(new String[0]);
        }
        return new String[0];
    }

    private static int digits(int x) {
        if (x == 0) return 1;
        int cnt = 0;
        while (x > 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }
}

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public static int[] maxPoints(int[][] grid, int[] queries) {
        int m = grid.length;
        int n = grid[0].length;
        int[] answer = new int[queries.length];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int idx = 0; idx < queries.length; idx++) {
            int limit = queries[idx];
            if (grid[0][0] >= limit) {
                answer[idx] = 0;
                continue;
            }
            boolean[][] visited = new boolean[m][n];
            Queue<int[]> q = new ArrayDeque<>();
            q.offer(new int[]{0, 0});
            visited[0][0] = true;
            int count = 1;

            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int r = cur[0];
                int c = cur[1];
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                    if (visited[nr][nc]) continue;
                    if (grid[nr][nc] >= limit) continue;
                    visited[nr][nc] = true;
                    q.offer(new int[]{nr, nc});
                    count++;
                }
            }
            answer[idx] = count;
        }
        return answer;
    }
}

