class Solution {
    public static int beautifulPartitions(String s, int k, int minLength) {
        final int MOD = 1_000_000_007;
        int n = s.length();
        if (k * minLength > n) return 0;
        boolean[] isPrime = new boolean[n];
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            isPrime[i] = c == '2' || c == '3' || c == '5' || c == '7';
        }
        if (!isPrime[0] || isPrime[n - 1]) return 0;
        int[][] dp = new int[n][k + 1];
        for (int i = minLength - 1; i < n; i++) {
            if (!isPrime[i]) {
                dp[i][1] = 1;
            }
        }
        for (int seg = 2; seg <= k; seg++) {
            int[] prefix = new int[n];
            int sum = 0;
            for (int p = 0; p < n; p++) {
                if (p + 1 < n && isPrime[p + 1]) {
                    sum += dp[p][seg - 1];
                    if (sum >= MOD) sum -= MOD;
                }
                prefix[p] = sum;
            }
            for (int i = 0; i < n; i++) {
                if (isPrime[i]) continue;
                int left = i - minLength;
                if (left >= 0) {
                    dp[i][seg] = prefix[left];
                }
            }
        }
        return dp[n - 1][k];
    }
}

