public class Solution {
    public static int[] cycleLengthQueries(int n, int[][] queries) {
        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            int lca = findLCA(a, b);
            int cycleLength = findDepth(a) + findDepth(b) - 2 * findDepth(lca) + 1;
            answer[i] = cycleLength;
        }
        return answer;
    }

    private static int findDepth(int node) {
        return 31 - Integer.numberOfLeadingZeros(node);
    }

    private static int findLCA(int a, int b) {
        int depthA = findDepth(a);
        int depthB = findDepth(b);
        while (depthA > depthB) {
            a = a / 2;
            depthA--;
        }
        while (depthB > depthA) {
            b = b / 2;
            depthB--;
        }
        while (a != b) {
            a = a / 2;
            b = b / 2;
        }
        return a;
    }
}

