        long sumDiff = 0;
        for (int i = 0; i < nums1.length; i++) {
            long diff = (long) nums1[i] - nums2[i];
            if (diff % k != 0) {
                return -1;
            }
            if (diff > 0) {
                totalPositive += diff;
            }
            sumDiff += diff;
        }
        if (sumDiff != 0) {
            return -1;
        }
        return totalPositive / k;
    }
}

import java.util.*;

class Solution {
    private static class DfsResult {
        long[] dist;
        int[] parent;
        DfsResult(long[] dist, int[] parent) {
            this.dist = dist;
            this.parent = parent;
        }
    }

    public static long maxDifferenceBetweenMaxAndMinPriceSum(int n, int[][] edges, int[] price) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        DfsResult first = dfs(0, adj, price);
        int A = 0;
        for (int i = 0; i < n; i++) {
            if (first.dist[i] > first.dist[A]) A = i;
        }

        DfsResult fromA = dfs(A, adj, price);
        int B = A;
        for (int i = 0; i < n; i++) {
            if (fromA.dist[i] > fromA.dist[B]) B = i;
        }

        DfsResult fromB = dfs(B, adj, price);

        long answer = 0;
        for (int i = 0; i < n; i++) {
            long maxPath = Math.max(fromA.dist[i], fromB.dist[i]);
            long cost = maxPath - price[i];
            if (cost > answer) answer = cost;
        }
        return answer;
    }

    private static DfsResult dfs(int start, List<Integer>[] adj, int[] price) {
        int n = adj.length;
        long[] dist = new long[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        dist[start] = price[start];
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : adj[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                dist[v] = dist[u] + price[v];
                stack.push(v);
            }
        }
        return new DfsResult(dist, parent);
    }
}

