class Solution {
    public static int distinctNumbers(int n) {
        Set<Integer> distinctNums = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();
        distinctNums.add(n);
        queue.add(n);
        while (!queue.isEmpty()) {
            int num = queue.poll();
            for (int i = 2; i <= num; i++) {
                if (num % i == 1) {
                    if (!distinctNums.contains(i)) {
                        distinctNums.add(i);
                        queue.add(i);
                    }
                }
            }
        }
        return distinctNums.size();
    }
}

