class Solution {
    public static long countCollisions(int n) {
        long MOD = 1_000_000_007L;
        long total = modPow(2L, n, MOD);
        long result = (total - 2) % MOD;
        if (result < 0) result += MOD;
        return result;
    }

    private static long modPow(long base, long exp, long mod) {
        long res = 1L;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return res;
    }
}

