class Solution {
    public long maxScore(int[] nums1, int[] nums2, int k) {
        int n = nums1.length;
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums2[i];
            pairs[i][1] = nums1[i];
        }
        Arrays.sort(pairs, (a, b) -> Integer.compare(b[0], a[0])); // descending by nums2

        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        long sum = 0;
        long best = 0;

        for (int[] p : pairs) {
            int curNum2 = p[0];
            int curNum1 = p[1];
            minHeap.offer(curNum1);
            sum += curNum1;

            if (minHeap.size() > k) {
                sum -= minHeap.poll();
            }

            if (minHeap.size() == k) {
                long score = sum * curNum2;
                if (score > best) {
                    best = score;
                }
            }
        }
        return best;
    }
}

