class Solution {
    public boolean isPossibleToDisconnect(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] fromStart = new boolean[m][n];
        if (grid[0][0] == 1) {
            fromStart[0][0] = true;
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 1) continue;
                if (i > 0 && fromStart[i - 1][j]) fromStart[i][j] = true;
                if (j > 0 && fromStart[i][j - 1]) fromStart[i][j] = true;
            }
        }

        boolean[][] toEnd = new boolean[m][n];
        if (grid[m - 1][n - 1] == 1) {
            toEnd[m - 1][n - 1] = true;
        }
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] != 1) continue;
                if (i + 1 < m && toEnd[i + 1][j]) toEnd[i][j] = true;
                if (j + 1 < n && toEnd[i][j + 1]) toEnd[i][j] = true;
            }
        }

        if (!fromStart[m - 1][n - 1]) {
            return true;
        }

        int totalSteps = (m - 1) + (n - 1);
        int[] count = new int[totalSteps + 1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (fromStart[i][j] && toEnd[i][j]) {
                    count[i + j]++;
                }
            }
        }

        for (int step = 1; step < totalSteps; step++) {
            if (count[step] == 1) {
                return true;
            }
        }
        return false;
    }
}

