class Solution {
    public static int minimumImpossibleOR(int[] nums) {
        int maxOr = 0;
        for (int v : nums) {
            maxOr |= v;
        }
        for (int x = 1; x <= maxOr + 1; x++) {
            int union = 0;
            for (int v : nums) {
                if ((v | x) == x) {
                    union |= v;
                }
            }
            if (union != x) {
                return x;
            }
        }
        return maxOr + 1;
    }
}

