import java.util.List;

public class Solution {
    public static List<Long> handleSumQueries(int[] nums1, int[] nums2, int[][] queries) {
        int n = nums1.length;
        int[] tree = new int[4 * n];
        boolean[] lazy = new boolean[4 * n];
        build(tree, nums1, 1, 0, n - 1);
        long sumNums2 = 0;
        for (int v : nums2) {
            sumNums2 += v;
        }
        List<Long> answer = new ArrayList<>();
        for (int[] q : queries) {
            int type = q[0];
            if (type == 1) {
                int left = q[1];
                int right = q[2];
                flipRange(tree, lazy, 1, 0, n - 1, left, right);
            } else if (type == 2) {
                int val = q[1];
                sumNums2 += (long) val * tree[1];
            } else if (type == 3) {
                answer.add(sumNums2);
            }
        }
        return answer;
    }

    private static void build(int[] tree, int[] nums1, int idx, int l, int r) {
        if (l == r) {
            tree[idx] = nums1[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(tree, nums1, idx << 1, l, mid);
        build(tree, nums1, idx << 1 | 1, mid + 1, r);
        tree[idx] = tree[idx << 1] + tree[idx << 1 | 1];
    }

    private static void applyFlip(int[] tree, boolean[] lazy, int idx, int l, int r) {
        tree[idx] = (r - l + 1) - tree[idx];
        lazy[idx] = !lazy[idx];
    }

    private static void push(int[] tree, boolean[] lazy, int idx, int l, int r) {
        if (!lazy[idx]) {
            return;
        }
        int mid = (l + r) >> 1;
        applyFlip(tree, lazy, idx << 1, l, mid);
        applyFlip(tree, lazy, idx << 1 | 1, mid + 1, r);
        lazy[idx] = false;
    }

    private static void flipRange(int[] tree, boolean[] lazy, int idx, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) {
            return;
        }
        if (ql <= l && r <= qr) {
            applyFlip(tree, lazy, idx, l, r);
            return;
        }
        push(tree, lazy, idx, l, r);
        int mid = (l + r) >> 1;
        flipRange(tree, lazy, idx << 1, l, mid, ql, qr);
        flipRange(tree, lazy, idx << 1 | 1, mid + 1, r, ql, qr);
        tree[idx] = tree[idx << 1] + tree[idx << 1 | 1];
    }
}

