class Solution {
    public static long minTime(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        long[][] dist = new long[m][n];
        for (long[] row : dist) Arrays.fill(row, Long.MAX_VALUE);
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        long startTime = Math.max(0, grid[0][0]);
        dist[0][0] = startTime;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a,b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{startTime, 0, 0});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long time = top[0]; int r = (int)top[1], c = (int)top[2];
            if (time != dist[r][c]) continue;
            if (r == m-1 && c == n-1) return time;
            for (int[] d : dirs) {
                int nr = r+d[0], nc = c+d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    long arrival = time + 1;
                    if (arrival >= grid[nr][nc]) {
                        if (arrival < dist[nr][nc]) {
                            dist[nr][nc] = arrival;
                            pq.add(new long[]{arrival, nr, nc});
                        }
                    }
                }
            }
        }
        return -1;
    }
}
