class Solution {
    public static int countWays(int[][] ranges) {
        final int MOD = 1000000007;
        Arrays.sort(ranges, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        int components = 0;
        int curMaxEnd = Integer.MIN_VALUE;
        for (int i = 0; i < ranges.length; i++) {
            int s = ranges[i][0];
            int e = ranges[i][1];
            if (s > curMaxEnd) {
                components++;
                curMaxEnd = e;
            } else {
                if (e > curMaxEnd) curMaxEnd = e;
            }
        }
        long result = 1;
        long base = 2;
        int exp = components;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return (int) result;
    }
}

