class Solution {
    public static String findString(int[][] lcp) {
        int n = lcp.length;
        if (n == 0) return "";
        for (int i = 0; i < n; ++i) {
            if (lcp[i].length != n) return "";
        }
        for (int i = 0; i < n; ++i) {
            if (lcp[i][i] != n - i) return "";
            for (int j = i + 1; j < n; ++j) {
                if (lcp[i][j] != lcp[j][i]) return "";
                int maxLen = Math.min(n - i, n - j);
                if (lcp[i][j] > maxLen || lcp[i][j] < 0) return "";
            }
        }
        DSU dsu = new DSU(n);
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int k = lcp[i][j];
                for (int t = 0; t < k; ++t) {
                    dsu.unite(i + t, j + t);
                }
            }
        }
        Map<Integer, Set<Integer>> adjMap = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int k = lcp[i][j];
                int maxLen = Math.min(n - i, n - j);
                if (k < maxLen) {
                    int a = dsu.find(i + k);
                    int b = dsu.find(j + k);
                    if (a == b) return "";
                    adjMap.computeIfAbsent(a, v -> new HashSet<>()).add(b);
                    adjMap.computeIfAbsent(b, v -> new HashSet<>()).add(a);
                }
            }
        }
        int[] compId = new int[n];
        Map<Integer, Integer> rootToIdx = new HashMap<>();
        int idx = 0;
        for (int i = 0; i < n; ++i) {
            int r = dsu.find(i);
            if (!rootToIdx.containsKey(r)) rootToIdx.put(r, idx++);
            compId[i] = rootToIdx.get(r);
        }
        int m = idx;
        List<List<Integer>> adj = new ArrayList<>(m);
        for (int i = 0; i < m; ++i) adj.add(new ArrayList<>());
        for (Map.Entry<Integer, Set<Integer>> entry : adjMap.entrySet()) {
            int u = rootToIdx.get(entry.getKey());
            for (int vRoot : entry.getValue()) {
                int v = rootToIdx.get(vRoot);
                adj.get(u).add(v);
            }
        }
        int[] color = new int[m];
        Arrays.fill(color, -1);
        char[] result = new char[n];
        Arrays.fill(result, 'a');
        for (int i = 0; i < n; ++i) {
            int c = compId[i];
            if (color[c] == -1) {
                boolean[] used = new boolean[26];
                for (int nb : adj.get(c)) {
                    if (color[nb] != -1) used[color[nb]] = true;
                }
                int assign = -1;
                for (int d = 0; d < 26; ++d) {
                    if (!used[d]) {
                        assign = d;
                        break;
                    }
                }
                if (assign == -1) return "";
                color[c] = assign;
            }
            result[i] = (char) ('a' + color[c]);
        }
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                int cnt = 0;
                while (i + cnt < n && j + cnt < n && result[i + cnt] == result[j + cnt]) ++cnt;
                if (cnt != lcp[i][j]) return "";
            }
        }
        return new String(result);
    }

    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] == x) return x;
            parent[x] = find(parent[x]);
            return parent[x];
        }

        void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (size[a] < size[b]) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            parent[b] = a;
            size[a] += size[b];
        }
    }
}

