class Solution {
    public int rootCount(int[][] edges, int[][] guesses, int k) {
        int n = edges.length + 1;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }
        Set<Long> guessSet = new HashSet<>();
        for (int[] g : guesses) {
            guessSet.add(encode(g[0], g[1]));
        }
        int[] initial = new int[1];
        dfsInit(0, -1, graph, guessSet, initial);
        int[] answer = new int[1];
        dfsReroot(0, -1, graph, guessSet, initial[0], k, answer);
        return answer[0];
    }

    private void dfsInit(int node, int parent, List<Integer>[] graph, Set<Long> guessSet, int[] count) {
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            if (guessSet.contains(encode(node, nb))) count[0]++;
            dfsInit(nb, node, graph, guessSet, count);
        }
    }

    private void dfsReroot(int node, int parent, List<Integer>[] graph, Set<Long> guessSet,
                           int curCount, int k, int[] answer) {
        if (curCount >= k) answer[0]++;
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            int nextCount = curCount;
            if (guessSet.contains(encode(node, nb))) nextCount--;
            if (guessSet.contains(encode(nb, node))) nextCount++;
            dfsReroot(nb, node, graph, guessSet, nextCount, k, answer);
        }
    }

    private long encode(int u, int v) {
        return ((long) u << 32) | (v & 0xffffffffL);
    }
}

