class Solution {
    private static final int MOD = 1_000_000_007;

    public int waysToEarnPoints(int target, int[][] types) {
        int[] dp = new int[target + 1];
        dp[0] = 1;
        for (int[] type : types) {
            int count = type[0];
            int marks = type[1];
            int[] next = new int[target + 1];
            for (int cur = 0; cur <= target; cur++) {
                if (dp[cur] == 0) continue;
                long ways = dp[cur];
                for (int k = 0; k <= count; k++) {
                    int nxt = cur + k * marks;
                    if (nxt > target) break;
                    next[nxt] = (int) ((next[nxt] + ways) % MOD);
                }
            }
            dp = next;
        }
        return dp[target];
    }
}

