public class Solution {
    public int minTime(int[][] tasks) {
        Arrays.sort(tasks, (a, b) -> {
            if (a[1] != b[1]) return a[1] - b[1];
            return a[0] - b[0];
        });
        int maxTime = 0;
        for (int[] t : tasks) {
            maxTime = Math.max(maxTime, t[1]);
        }
        boolean[] on = new boolean[maxTime + 2];
        int total = 0;
        for (int[] task : tasks) {
            int start = task[0];
            int end = task[1];
            int dur = task[2];
            int cnt = 0;
            for (int t = start; t <= end; t++) {
                if (on[t]) cnt++;
            }
            int need = dur - cnt;
            for (int t = end; t >= start && need > 0; t--) {
                if (!on[t]) {
                    on[t] = true;
                    total++;
                    need--;
                }
            }
        }
        return total;
    }
}

