class Solution {
    public static int distributeMoney(int money, int children) {
        if (money < children) {
            return -1;
        }
        int extra = money - children;
        int maxEight = extra / 7;
        while (maxEight > 0) {
            int remainingExtra = extra - maxEight * 7;
            if (remainingExtra == 3 && children - maxEight > 0) {
                maxEight--;
            } else {
                break;
            }
        }
        if (maxEight == 0 && extra == 3) {
            return -1;
        }
        return maxEight;
    }
}

