class Solution {
    public static long minRepairTime(int[] ranks, int cars) {
        long low = 0;
        int minRank = Integer.MAX_VALUE;
        for (int r : ranks) {
            if (r < minRank) {
                minRank = r;
            }
        }
        long high = (long) minRank * cars * cars;
        while (low < high) {
            long mid = (low + high) / 2;
            long repaired = 0;
            for (int rank : ranks) {
                repaired += (long) Math.sqrt(mid / (double) rank);
                if (repaired >= cars) {
                    break;
                }
            }
            if (repaired >= cars) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

