class Solution {
    public static long beautifulSubsets(int[] nums, int k) {
        Arrays.sort(nums);
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) {
            cnt.put(x, cnt.getOrDefault(x, 0) + 1);
        }
        List<Integer> values = new ArrayList<>(cnt.keySet());
        Collections.sort(values);
        int m = values.size();

        long totalWays = 1;
        int i = 0;

        while (i < m) {
            long dpPrevPrev = 1;
            long w0 = (long) Math.pow(2, cnt.get(values.get(i))) - 1;
            long dpPrev = 1 + w0;
            i++;

            while (i < m && values.get(i) - values.get(i - 1) == k) {
                long w = (long) Math.pow(2, cnt.get(values.get(i))) - 1;
                long cur = dpPrev + dpPrevPrev * w;
                dpPrevPrev = dpPrev;
                dpPrev = cur;
                i++;
            }

            totalWays *= dpPrev;
        }

        return totalWays - 1;
    }
}

