class Solution {
    public static int passThePillow(int n, int time) {
        if (n == 1) return 1;
        int cycle = 2 * (n - 1);
        int r = time % cycle;
        if (r <= n - 1) {
            return 1 + r;
        } else {
            return n - (r - (n - 1));
        }
    }
}

