class Solution {
    public static boolean primeSubtractionOperation(int[] nums) {
        int max = 0;
        for (int v : nums) {
            if (v > max) max = v;
        }
        boolean[] isPrime = new boolean[max + 1];
        if (max >= 2) {
            Arrays.fill(isPrime, 2, max + 1, true);
            for (int p = 2; p * p <= max; p++) {
                if (isPrime[p]) {
                    for (int multiple = p * p; multiple <= max; multiple += p) {
                        isPrime[multiple] = false;
                    }
                }
            }
        }
        int n = nums.length;
        int next = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] < next) {
                next = nums[i];
                continue;
            }
            int lower = Math.max(2, nums[i] - (next - 1));
            int upper = nums[i] - 1;
            boolean found = false;
            for (int p = lower; p <= upper; p++) {
                if (isPrime[p]) {
                    next = nums[i] - p;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
}

