class Solution {
    public boolean checkValidGrid(int[][] grid) {
        int n = grid.length;
        int total = n * n;
        int[] rowPos = new int[total];
        int[] colPos = new int[total];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = grid[i][j];
                rowPos[val] = i;
                colPos[val] = j;
            }
        }
        if (rowPos[0] != 0 || colPos[0] != 0) {
            return false;
        }
        for (int k = 1; k < total; k++) {
            int dr = Math.abs(rowPos[k] - rowPos[k - 1]);
            int dc = Math.abs(colPos[k] - colPos[k - 1]);
            if (!((dr == 1 && dc == 2) || (dr == 2 && dc == 1))) {
                return false;
            }
        }
        return true;
    }
}

