class Solution {
    public static long[] minOperations(int[] nums, int[] queries) {
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        long[] pref = new long[n + 1];
        pref[0] = 0;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + sorted[i];
        }
        long totalSum = pref[n];
        long[] answers = new long[queries.length];
        for (int idx = 0; idx < queries.length; idx++) {
            int q = queries[idx];
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (sorted[mid] <= q) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            int k = lo;
            long leftCost = (long) q * k - pref[k];
            long rightCost = (totalSum - pref[k]) - (long) q * (n - k);
            answers[idx] = leftCost + rightCost;
        }
        return answers;
    }
}

