class Solution {
    public static int collectCoinsInTree(int[] coins, int[][] edges) {
        int n = coins.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] degree = new int[n];
        for (int i = 0; i < n; i++) degree[i] = adj[i].size();
        boolean[] removed = new boolean[n];
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (degree[i] == 1 && coins[i] == 0) queue.add(i);
        }
        while (!queue.isEmpty()) {
            int u = queue.poll();
            if (removed[u]) continue;
            removed[u] = true;
            degree[u] = 0;
            for (int v : adj[u]) {
                if (removed[v]) continue;
                degree[v]--;
                if (degree[v] == 1 && coins[v] == 0) queue.add(v);
            }
        }
        List<Integer> leaves = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!removed[i] && degree[i] == 1) leaves.add(i);
        }
        for (int round = 0; round < 2; round++) {
            List<Integer> next = new ArrayList<>();
            for (int u : leaves) {
                if (removed[u]) continue;
                removed[u] = true;
                degree[u] = 0;
                for (int v : adj[u]) {
                    if (removed[v]) continue;
                    degree[v]--;
                    if (degree[v] == 1) next.add(v);
                }
            }
            leaves = next;
        }
        int remainingEdges = 0;
        for (int i = 0; i < n; i++) {
            if (!removed[i]) remainingEdges += degree[i];
        }
        remainingEdges /= 2;
        return remainingEdges * 2;
    }
}

