class Solution {
    public static List<List<Integer>> findMatrix(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        int maxFreq = 0;
        for (int v : nums) {
            int cnt = freq.getOrDefault(v, 0) + 1;
            freq.put(v, cnt);
            if (cnt > maxFreq) {
                maxFreq = cnt;
            }
        }
        List<Integer> distinct = new ArrayList<>(freq.keySet());
        distinct.sort((a, b) -> {
            int cmp = Integer.compare(freq.get(b), freq.get(a));
            if (cmp != 0) return cmp;
            return Integer.compare(b, a);
        });
        List<List<Integer>> rows = new ArrayList<>(maxFreq);
        for (int i = 0; i < maxFreq; i++) {
            rows.add(new ArrayList<>());
        }
        for (int num : distinct) {
            int count = freq.get(num);
            for (int i = 0; i < count; i++) {
                rows.get(i).add(num);
            }
        }
        return rows;
    }
}

