public class Solution {
    public static long makeKSubarraySumsEqual(int[] arr, int k) {
        int n = arr.length;
        int g = gcd(n, k);
        long totalOps = 0L;
        int cycleLen = n / g;
        for (int start = 0; start < g; start++) {
            int[] vals = new int[cycleLen];
            int idx = start;
            for (int t = 0; t < cycleLen; t++) {
                vals[t] = arr[idx];
                idx = (idx + k) % n;
            }
            Arrays.sort(vals);
            int median = vals[cycleLen / 2];
            for (int v : vals) {
                totalOps += Math.abs((long) v - median);
            }
        }
        return totalOps;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

