class Solution {
    public static int longestBalancedSubstring(String s) {
        int maxLen = 0;
        char prevRunChar = '\0';
        int prevRunLen = 0;
        int curRunLen = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (i == 0 || c == s.charAt(i - 1)) {
                curRunLen++;
            } else {
                if (prevRunChar == '0' && c == '1') {
                    int candidate = 2 * Math.min(prevRunLen, curRunLen);
                    if (candidate > maxLen) maxLen = candidate;
                }
                prevRunChar = s.charAt(i - 1);
                prevRunLen = curRunLen;
                curRunLen = 1;
            }
        }
        if (s.length() > 0 && prevRunChar == '0' && s.charAt(s.length() - 1) == '1') {
            int candidate = 2 * Math.min(prevRunLen, curRunLen);
            if (candidate > maxLen) maxLen = candidate;
        }
        return maxLen;
    }
}

import java.util.Arrays;

class Solution {
    private static int find(int i, int n, int[] nxt) {
        if (i >= n) return n;
        if (nxt[i] == i) return i;
        nxt[i] = find(nxt[i], n, nxt);
        return nxt[i];
    }

    private static void remove(int i, int n, int[] nxt) {
        nxt[i] = find(i + 2, n, nxt);
    }

    public static int[] minimumReverseOperations(int n, int p, int[] banned, int k) {
        int[] answer = new int[n];
        Arrays.fill(answer, -1);
        int[] nxt = new int[n + 2];
        for (int i = 0; i <= n + 1; i++) {
            nxt[i] = i;
        }

        for (int b : banned) {
            remove(b, n, nxt);
        }

        answer[p] = 0;
        remove(p, n, nxt);
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = p;

        while (head < tail) {
            int x = queue[head++];
            int dMin = Math.max(0, x - (n - k));
            int dMax = Math.min(k - 1, x);
            int L = x + (k - 1) - 2 * dMax;
            int R = x + (k - 1) - 2 * dMin;
            if (L < 0) L = 0;
            if (R >= n) R = n - 1;
            if (L > R) continue;

            int cur = find(L, n, nxt);
            while (cur <= R) {
                answer[cur] = answer[x] + 1;
                queue[tail++] = cur;
                int next = find(cur + 2, n, nxt);
                nxt[cur] = next;
                cur = next;
            }
        }

        return answer;
    }
}

