class Solution {
    public int shortestCycleLength(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }
        int best = Integer.MAX_VALUE;
        for (int start = 0; start < n; start++) {
            int[] dist = new int[n];
            int[] parent = new int[n];
            Arrays.fill(dist, -1);
            Arrays.fill(parent, -1);
            Queue<Integer> q = new ArrayDeque<>();
            dist[start] = 0;
            q.add(start);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        parent[v] = u;
                        q.add(v);
                    } else if (parent[u] != v) {
                        int cycleLen = dist[u] + dist[v] + 1;
                        if (cycleLen < best) best = cycleLen;
                    }
                }
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

public class Solution {
    public static int maxSum(int numOnes, int numZeros, int numNegOnes, int k) {
        int onesPicked = Math.min(numOnes, k);
        int remaining = k - onesPicked;
        int zerosPicked = Math.min(numZeros, remaining);
        remaining -= zerosPicked;
        int negOnesPicked = Math.min(numNegOnes, remaining);
        int sum = onesPicked - negOnesPicked;
        return sum;
    }
}

import java.util.*;

class Solution {
    public int minimumVisitedCells(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        if (m == 1 && n == 1) {
            return 1;
        }

        @SuppressWarnings("unchecked")
        TreeSet<Integer>[] rowSets = new TreeSet[m];
        for (int i = 0; i < m; i++) {
            rowSets[i] = new TreeSet<>();
            for (int j = 0; j < n; j++) {
                rowSets[i].add(j);
            }
        }

        @SuppressWarnings("unchecked")
        TreeSet<Integer>[] colSets = new TreeSet[n];
        for (int j = 0; j < n; j++) {
            colSets[j] = new TreeSet<>();
            for (int i = 0; i < m; i++) {
                colSets[j].add(i);
            }
        }

        int[][] dist = new int[m][n];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }
        dist[0][0] = 1;

        // mark start as visited
        rowSets[0].remove(0);
        colSets[0].remove(0);

        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int i = cur[0];
            int j = cur[1];
            if (i == m - 1 && j == n - 1) {
                return dist[i][j];
            }
            int jump = grid[i][j];
            if (jump == 0) continue;

            // move right in the same row
            int maxCol = Math.min(n - 1, j + jump);
            Integer c = rowSets[i].ceiling(j + 1);
            while (c != null && c <= maxCol) {
                rowSets[i].remove(c);
                colSets[c].remove(i);
                dist[i][c] = dist[i][j] + 1;
                q.add(new int[]{i, c});
                c = rowSets[i].ceiling(j + 1);
            }

            // move down in the same column
            int maxRow = Math.min(m - 1, i + jump);
            Integer r = colSets[j].ceiling(i + 1);
            while (r != null && r <= maxRow) {
                colSets[j].remove(r);
                rowSets[r].remove(j);
                dist[r][j] = dist[i][j] + 1;
                q.add(new int[]{r, j});
                r = colSets[j].ceiling(i + 1);
            }
        }

        return -1;
    }
}

