class Solution {
    public static long maxPoints(int[] reward1, int[] reward2, int k) {
        int n = reward1.length;
        long total = 0;
        long[] diffs = new long[n];
        for (int i = 0; i < n; i++) {
            total += reward2[i];
            diffs[i] = (long) reward1[i] - reward2[i];
        }
        Arrays.sort(diffs);
        for (int i = n - 1; i >= n - k; i--) {
            total += diffs[i];
        }
        return total;
    }
}

