class Solution {
    public static int primeInDiagonal(int[][] nums) {
        if (nums == null || nums.length == 0) return 0;
        int rows = nums.length;
        int cols = nums[0].length;
        int maxPrime = 0;
        for (int i = 0; i < rows; i++) {
            if (i < cols) {
                int val = nums[i][i];
                if (isPrime(val) && val > maxPrime) maxPrime = val;
            }
            int antiCol = cols - 1 - i;
            if (antiCol >= 0 && antiCol < cols) {
                if (i != antiCol) {
                    int val = nums[i][antiCol];
                    if (isPrime(val) && val > maxPrime) maxPrime = val;
                }
            }
        }
        return maxPrime;
    }

    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }
}

import java.util.Arrays;

class Solution {
    public static int minimizeMaxDifference(int[] nums, int p) {
        int n = nums.length;
        if (p == 0) return 0;
        int[] a = Arrays.copyOf(nums, n);
        Arrays.sort(a);
        int low = 0;
        int high = a[n - 1] - a[0];
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canForm(a, mid) >= p) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static int canForm(int[] a, int limit) {
        int cnt = 0;
        int i = 0;
        int n = a.length;
        while (i < n - 1) {
            if (a[i + 1] - a[i] <= limit) {
                cnt++;
                i += 2;
            } else {
                i += 1;
            }
        }
        return cnt;
    }
}

