public class Solution {
    public static class TimeLimitedCache {
        private final Map<Integer, Entry> map = new HashMap<>();
        private int active = 0;
        private static final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();

        private static class Entry {
            int value;
            long expire;
            ScheduledFuture<?> timer;
            Entry(int value, long expire, ScheduledFuture<?> timer) {
                this.value = value;
                this.expire = expire;
                this.timer = timer;
            }
        }

        public boolean set(int key, int value, int duration) {
            long now = System.currentTimeMillis();
            Entry existing = map.get(key);
            boolean stillValid = existing != null && existing.expire > now;
            if (stillValid) {
                existing.timer.cancel(false);
            }
            ScheduledFuture<?> timer = scheduler.schedule(() -> {
                map.remove(key);
                active--;
            }, duration, TimeUnit.MILLISECONDS);
            map.put(key, new Entry(value, now + duration, timer));
            if (!stillValid) {
                active++;
            }
            return stillValid;
        }

        public int get(int key) {
            long now = System.currentTimeMillis();
            Entry entry = map.get(key);
            if (entry != null && entry.expire > now) {
                return entry.value;
            }
            if (entry != null) {
                entry.timer.cancel(false);
                map.remove(key);
                active--;
            }
            return -1;
        }

        public int count() {
            return active;
        }
    }
}

