class Solution {
    public static int[] sumOfDistances(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            groups.computeIfAbsent(v, k -> new ArrayList<>()).add(i);
        }
        for (List<Integer> idxList : groups.values()) {
            int m = idxList.size();
            if (m <= 1) continue;
            long[] pref = new long[m];
            pref[0] = idxList.get(0);
            for (int k = 1; k < m; k++) {
                pref[k] = pref[k - 1] + idxList.get(k);
            }
            long totalSum = pref[m - 1];
            for (int p = 0; p < m; p++) {
                int i = idxList.get(p);
                int leftCount = p;
                long leftSum = p > 0 ? pref[p - 1] : 0L;
                int rightCount = m - p - 1;
                long rightSum = totalSum - leftSum - i;
                long res = (long) i * leftCount - leftSum + rightSum - (long) i * rightCount;
                ans[i] = (int) res;
            }
        }
        return ans;
    }
}

