class Solution {
    public static int[][] snailTraversal(int[] source, int rowsCount, int colsCount) {
        // validate dimensions before allocating/filling - a mismatched or
        // non-positive size means no valid traversal exists, and filling
        // without this check throws ArrayIndexOutOfBoundsException
        if (rowsCount <= 0 || colsCount <= 0 || (long) rowsCount * colsCount != source.length) {
            return new int[0][0];
        }
        int[][] result = new int[rowsCount][colsCount];
        int idx = 0;
        for (int col = 0; col < colsCount; col++) {
            if (col % 2 == 0) {
                for (int row = 0; row < rowsCount; row++) {
                    result[row][col] = source[idx++];
                }
            } else {
                for (int row = rowsCount - 1; row >= 0; row--) {
                    result[row][col] = source[idx++];
                }
            }
        }
        return result;
    }
}

