@FunctionalInterface
interface Func {
    void apply(Object... args);
}

class Solution {
    public static Func debounce(Func fn, long wait) {
        Timer timer = new Timer(true);
        class TaskHolder { TimerTask task; }
        TaskHolder holder = new TaskHolder();
        return (Object... args) -> {
            if (holder.task != null) {
                holder.task.cancel();
            }
            holder.task = new TimerTask() {
                @Override
                public void run() {
                    fn.apply(args);
                }
            };
            timer.schedule(holder.task, wait);
        };
    }
}

