class Solution {
    public static <T> Function<Object[], CompletableFuture<T>> timeLimit(Function<Object[], CompletableFuture<T>> fn, long t) {
        return (Object[] args) -> {
            CompletableFuture<T> result = new CompletableFuture<>();
            ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
            ScheduledFuture<?> timeoutId = scheduler.schedule(() -> result.completeExceptionally(new RuntimeException("Time Limit Exceeded")), t, TimeUnit.MILLISECONDS);
            fn.apply(args).whenComplete((value, err) -> {
                timeoutId.cancel(true);
                scheduler.shutdown();
                if (err != null) {
                    result.completeExceptionally(err);
                } else {
                    result.complete(value);
                }
            });
            return result;
        };
    }
}

