class Graph {
    private List<List<long[]>> adj;
    private List<long[]> heap;

    public Graph(int n, int[][] edges) {
        adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) adj.get(e[0]).add(new long[]{e[1], e[2]});
        heap = new ArrayList<>();
    }

    private void heapPush(long[] item) {
        heap.add(item);
        int i = heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap.get(p)[0] <= heap.get(i)[0]) break;
            long[] tmp = heap.get(p);
            heap.set(p, heap.get(i));
            heap.set(i, tmp);
            i = p;
        }
    }

    private long[] heapPop() {
        long[] top = heap.get(0);
        long[] last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int smallest = i;
                if (l < heap.size() && heap.get(l)[0] < heap.get(smallest)[0]) smallest = l;
                if (r < heap.size() && heap.get(r)[0] < heap.get(smallest)[0]) smallest = r;
                if (smallest == i) break;
                long[] tmp = heap.get(i);
                heap.set(i, heap.get(smallest));
                heap.set(smallest, tmp);
                i = smallest;
            }
        }
        return top;
    }

    public void addEdge(int[] edge) {
        adj.get(edge[0]).add(new long[]{edge[1], edge[2]});
    }

    public long shortestPath(int src, int dst) {
        if (src == dst) return 0;
        int size = adj.size();
        long[] dist = new long[size];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[src] = 0;
        heap.clear();
        heapPush(new long[]{0, src});
        while (!heap.isEmpty()) {
            long[] cur = heapPop();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            if (u == dst) return d;
            for (long[] edge : adj.get(u)) {
                int v = (int) edge[0];
                long w = edge[1];
                long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    heapPush(new long[]{nd, v});
                }
            }
        }
        return -1;
    }
}

