class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public TreeNode replaceValueInTree(TreeNode root) {
        if (root == null) return null;
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        Map<TreeNode, Integer> siblingSumMap = new HashMap<>();
        while (!queue.isEmpty()) {
            int size = queue.size();
            List<TreeNode> level = new ArrayList<>(size);
            long levelSum = 0;
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                level.add(node);
                levelSum += node.val;
            }
            for (TreeNode node : level) {
                int siblingSum = siblingSumMap.getOrDefault(node, node.val);
                node.val = (int) (levelSum - siblingSum);
            }
            siblingSumMap.clear();
            for (TreeNode node : level) {
                if (node.left != null) {
                    if (node.right != null) {
                        int sum = node.left.val + node.right.val;
                        siblingSumMap.put(node.left, sum);
                        siblingSumMap.put(node.right, sum);
                        queue.add(node.left);
                        queue.add(node.right);
                    } else {
                        siblingSumMap.put(node.left, node.left.val);
                        queue.add(node.left);
                    }
                } else if (node.right != null) {
                    siblingSumMap.put(node.right, node.right.val);
                    queue.add(node.right);
                }
            }
        }
        return root;
    }
}

