        int bestDivisor = divisors[0];
        int bestScore = 0;
        for (int i = 0; i < divisors.length; i++) {
            int d = divisors[i];
            int cnt = 0;
            for (int j = 0; j < nums.length; j++) {
                if (nums[j] % d == 0) cnt++;
            }
            if (cnt > bestScore || (cnt == bestScore && d < bestDivisor)) {
