class Solution {
    public long minimumTotalPrice(int n, int[][] edges, int[] price, int[][] trips) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int[] visitCount = new int[n];
        for (int[] trip : trips) {
            int start = trip[0];
            int end = trip[1];
            int[] parent = new int[n];
            Arrays.fill(parent, -1);
            Queue<Integer> q = new ArrayDeque<>();
            q.add(start);
            parent[start] = start;
            while (!q.isEmpty()) {
                int cur = q.poll();
                if (cur == end) break;
                for (int nb : graph[cur]) {
                    if (parent[nb] == -1) {
                        parent[nb] = cur;
                        q.add(nb);
                    }
                }
            }
            int node = end;
            while (true) {
                visitCount[node]++;
                if (node == start) break;
                node = parent[node];
            }
        }

        long[] halfSavings = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            long w = (long) price[i] * visitCount[i];
            total += w;
            halfSavings[i] = w / 2; // price[i] is even, so w is even
        }

        long[] dpNot = new long[n];
        long[] dpYes = new long[n];
        dfs(0, -1, graph, halfSavings, dpNot, dpYes);
        long maxSaved = Math.max(dpNot[0], dpYes[0]);
        return total - maxSaved;
    }

    private void dfs(int u, int parent, List<Integer>[] graph, long[] halfSavings,
                     long[] dpNot, long[] dpYes) {
        dpYes[u] = halfSavings[u];
        dpNot[u] = 0;
        for (int v : graph[u]) {
            if (v == parent) continue;
            dfs(v, u, graph, halfSavings, dpNot, dpYes);
            dpYes[u] += dpNot[v];
            dpNot[u] += Math.max(dpNot[v], dpYes[v]);
        }
    }
}

public class Solution {
    public static long findArrayConcatenationValue(int[] nums) {
        long concatenationValue = 0;
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            if (left < right) {
                concatenationValue += Long.parseLong("" + nums[left] + nums[right]);
                left++;
                right--;
            } else {
                concatenationValue += nums[left];
                left++;
            }
        }
        return concatenationValue;
    }
}

