class Solution {
    public static int maximumNumbers(int[] banned, int n, int maxSum) {
        int sum = 0, count = 0;
        Set<Integer> set = new HashSet<>();
        for (int b : banned) {
            set.add(b);
        }
        for (int i = 1; i <= n; i++) {
            if (!set.contains(i) && sum + i <= maxSum) {
                sum += i;
                count++;
            }
        }
        return count;
    }
}

