class Solution {
    public static int minCapability(int[] nums, int k) {
        int left = nums[0];
        int right = nums[0];
        for (int num : nums) {
            if (num < left) left = num;
            if (num > right) right = num;
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            int count = 0;
            int prev = -2;
            for (int i = 0; i < nums.length; i++) {
                if (nums[i] <= mid && i - prev >= 2) {
                    count++;
                    prev = i;
                }
            }
            if (count < k) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

