class Solution {
    public static int findValidSplit(int[] nums) {
        int n = nums.length;
        if (n < 2) return -1;
        int max = 0;
        for (int v : nums) if (v > max) max = v;
        int[] spf = new int[max + 1];
        for (int i = 2; i <= max; i++) {
            if (spf[i] == 0) {
                for (int j = i; j <= max; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }
        int[] lastPos = new int[max + 1];
        Arrays.fill(lastPos, -1);
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            while (x > 1) {
                int p = spf[x];
                while (x % p == 0) x /= p;
                lastPos[p] = i;
            }
        }
        int curMax = -1;
        for (int i = 0; i < n - 1; i++) {
            int x = nums[i];
            while (x > 1) {
                int p = spf[x];
                while (x % p == 0) x /= p;
                curMax = Math.max(curMax, lastPos[p]);
            }
            if (curMax <= i) return i;
        }
        return -1;
    }
}

