class Solution {
    public static int minimumScore(String s, String t) {
        int n = t.length();
        int[] prev = new int[n + 1];
        int[] cur = new int[n + 1];
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            for (int j = 0; j < n; j++) {
                if (c == t.charAt(j)) {
                    cur[j + 1] = prev[j] + 1;
                } else {
                    cur[j + 1] = Math.max(prev[j + 1], cur[j]);
                }
            }
            int[] temp = prev;
            prev = cur;
            cur = temp;
        }
        return n - prev[n];
    }
}

