class Solution {
    public static int[][] substringXorQueries(String s, int[][] queries) {
        int n = s.length();
        Map<Integer, int[]> best = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int val = 0;
            for (int k = i; k < n && k < i + 30; k++) {
                val = (val << 1) | (s.charAt(k) - '0');
                int[] cur = best.get(val);
                if (cur == null) {
                    best.put(val, new int[]{i, k});
                } else {
                    int curLen = cur[1] - cur[0];
                    int newLen = k - i;
                    if (newLen < curLen || (newLen == curLen && i < cur[0])) {
                        best.put(val, new int[]{i, k});
                    }
                }
            }
        }
        int[][] ans = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            int target = queries[i][0] ^ queries[i][1];
            int[] pos = best.get(target);
            if (pos != null) {
                ans[i][0] = pos[0];
                ans[i][1] = pos[1];
            } else {
                ans[i][0] = -1;
                ans[i][1] = -1;
            }
        }
        return ans;
    }
}

