class Solution {
    public static long minCost(int[] basket1, int[] basket2) {
        Map<Integer, Integer> diffMap = new HashMap<>();
        int globalMin = Integer.MAX_VALUE;
        for (int v : basket1) {
            diffMap.put(v, diffMap.getOrDefault(v, 0) + 1);
            if (v < globalMin) globalMin = v;
        }
        for (int v : basket2) {
            diffMap.put(v, diffMap.getOrDefault(v, 0) - 1);
            if (v < globalMin) globalMin = v;
        }
        List<Integer> extras = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : diffMap.entrySet()) {
            int val = e.getKey();
            int diff = e.getValue();
            if (diff % 2 != 0) return -1;
            int count = Math.abs(diff) / 2;
            for (int i = 0; i < count; i++) {
                extras.add(val);
            }
        }
        Collections.sort(extras);
        long cost = 0;
        int half = extras.size() / 2;
        for (int i = 0; i < half; i++) {
            int val = extras.get(i);
            cost += Math.min(val, 2 * globalMin);
        }
        return cost;
    }
}

