class Solution {
    public static int maximizeWin(int[] prizePositions, int k) {
        int maxPrizes = 0;
        for (int i = 0; i < prizePositions.length; i++) {
            int leftSegmentCount = 0;
            for (int j = 0; j < prizePositions.length; j++) {
                if (prizePositions[j] >= prizePositions[i] && prizePositions[j] <= prizePositions[i] + k) {
                    leftSegmentCount++;
                }
            }
            for (int j = 0; j < prizePositions.length; j++) {
                int rightSegmentCount = 0;
                for (int m = 0; m < prizePositions.length; m++) {
                    if (prizePositions[m] >= prizePositions[j] && prizePositions[m] <= prizePositions[j] + k) {
                        rightSegmentCount++;
                    }
                }
                int overlapping = countOverlappingPrizes(prizePositions, prizePositions[i], prizePositions[i] + k, prizePositions[j], prizePositions[j] + k);
                maxPrizes = Math.max(maxPrizes, leftSegmentCount + rightSegmentCount - overlapping);
            }
        }
        return maxPrizes;
    }

    private static int countOverlappingPrizes(int[] prizePositions, int leftStart, int leftEnd, int rightStart, int rightEnd) {
        int start = Math.max(leftStart, rightStart);
        int end = Math.min(leftEnd, rightEnd);
        if (start > end) {
            return 0;
        }
        int count = 0;
        for (int p : prizePositions) {
            if (p >= start && p <= end) {
                count++;
            }
        }
        return count;
    }
}

import java.util.Arrays;

class Solution {
    public static long countFairPairs(int[] nums, int lower, int upper) {
        Arrays.sort(nums);
        long count = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int left = lowerBound(nums, i + 1, lower - nums[i]);
            int right = upperBound(nums, i + 1, upper - nums[i]);
            count += right - left;
        }
        return count;
    }

    private static int lowerBound(int[] nums, int start, int target) {
        int lo = start, hi = nums.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int upperBound(int[] nums, int start, int target) {
        int lo = start, hi = nums.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

