public class Solution {
    public static long minCost(int[] nums, int k) {
        int n = nums.length;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 4);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            HashMap<Integer, Integer> count = new HashMap<>();
            int uniqueCount = 0;
            for (int j = i - 1; j >= 0; j--) {
                int val = nums[j];
                Integer cnt = count.get(val);
                if (cnt == null) {
                    count.put(val, 1);
                    uniqueCount++;
                } else if (cnt == 1) {
                    count.put(val, 2);
                    uniqueCount--;
                } else {
                    count.put(val, cnt + 1);
                }
                long candidate = dp[j] + k + (i - j - uniqueCount);
                if (candidate < dp[i]) {
                    dp[i] = candidate;
                }
            }
        }
        return dp[n];
    }
}

