class Solution {
    public static int[] countVowelStrings(String[] words, int[][] queries) {
        String vowels = "aeiou";
        int[] vowelCount = new int[words.length];
        for (int i = 0; i < words.length; i++) {
            if (vowels.indexOf(words[i].charAt(0)) != -1 && vowels.indexOf(words[i].charAt(words[i].length() - 1)) != -1) {
                vowelCount[i] = 1;
            }
        }
        for (int i = 1; i < vowelCount.length; i++) {
            vowelCount[i] += vowelCount[i - 1];
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int li = queries[i][0];
            int ri = queries[i][1];
            ans[i] = (ri >= 0 && ri < vowelCount.length) ? vowelCount[ri] : 0;
            ans[i] -= (li - 1 >= 0 && li - 1 < vowelCount.length) ? vowelCount[li - 1] : 0;
        }
        return ans;
    }
}

