class Solution {
    public static long putMarblesInBags(int[] weights, int k) {
        int n = weights.length;
        if (k == 1) return 0L;
        long base = (long) weights[0] + weights[n - 1];
        long[] adj = new long[n - 1];
        for (int i = 0; i < n - 1; i++) {
            adj[i] = (long) weights[i] + weights[i + 1];
        }
        Arrays.sort(adj);
        long minSum = 0, maxSum = 0;
