public class Solution {
    public static boolean makeEqual(String s, String target) {
        int countS = 0, countTarget = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') countS++;
            if (target.charAt(i) == '1') countTarget++;
        }
        if (countS != countTarget) return false;
        boolean[] visited = new boolean[s.length()];
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != target.charAt(i)) {
                boolean found = false;
                for (int j = 0; j < s.length(); j++) {
                    if (!visited[j] && s.charAt(j) == target.charAt(i)) {
                        char newI = (s.charAt(i) == '1' || s.charAt(j) == '1') ? '1' : '0';
                        s = s.substring(0, i) + newI + s.substring(i + 1);
                        char newJ = ((s.charAt(i) == '0' && s.charAt(j) == '1') || (s.charAt(i) == '1' && s.charAt(j) == '0')) ? '1' : '0';
                        s = s.substring(0, j) + newJ + s.substring(j + 1);
                        visited[j] = true;
                        found = true;
                        break;
                    }
                }
                if (!found) return false;
            }
        }
        return true;
    }
}

