class Solution {
    public static int maxNumberofFish(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        int maxFish = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > 0 && !visited[i][j]) {
                    int sum = dfs(grid, i, j, visited);
                    if (sum > maxFish) maxFish = sum;
                }
            }
        }
        return maxFish;
    }

    private static int dfs(int[][] grid, int i, int j, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;
        if (i < 0 || i >= rows || j < 0 || j >= cols) return 0;
        if (grid[i][j] == 0 || visited[i][j]) return 0;
        visited[i][j] = true;
        int sum = grid[i][j];
        sum += dfs(grid, i + 1, j, visited);
        sum += dfs(grid, i - 1, j, visited);
        sum += dfs(grid, i, j + 1, visited);
        sum += dfs(grid, i, j - 1, visited);
        return sum;
    }
}

