interface Generator {
    Result next(Object value);
    Result next();
    void throwException(Object e);
}

class Result {
    boolean done;
    Object value;
    Result(boolean done, Object value) {
        this.done = done;
        this.value = value;
    }
}

class Solution {
    public static Object[] cancellable(Generator generator) {
        AtomicBoolean cancelled = new AtomicBoolean(false);
        CompletableFuture<Object> promise = new CompletableFuture<>();
        Runnable cancel = () -> {
            cancelled.set(true);
            generator.throwException("Cancelled");
        };
        step(generator, generator.next(), promise, cancelled);
        return new Object[]{cancel, promise};
    }

    private static void step(Generator generator, Result next, CompletableFuture<Object> promise, AtomicBoolean cancelled) {
        if (cancelled.get()) {
            generator.throwException("Cancelled");
            return;
        }
        try {
            Result result = next;
            if (result.done) {
                promise.complete(result.value);
            } else {
                @SuppressWarnings("unchecked")
                CompletableFuture<Object> cf = (CompletableFuture<Object>) result.value;
                cf.thenAccept(value -> {
                    if (cancelled.get()) {
                        generator.throwException("Cancelled");
                    } else {
                        step(generator, generator.next(value), promise, cancelled);
                    }
                }).exceptionally(err -> {
                    generator.throwException(err);
                    return null;
                });
            }
        } catch (Throwable e) {
            promise.completeExceptionally(e);
        }
    }
}

class Solution {
