    private static int computeScore(int[] pins) {
        int total = 0;
        int pending = 0;
        for (int i = 0; i < pins.length; i++) {
            int p = pins[i];
            total += p;
            if (pending > 0) {
                total += p;
                pending--;
            }
            if (p == 10) {
                pending += 2;
            }
        }
        return total;
    }
}

