class Solution {
    private static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }
        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    private static class Pair {
        Point point;
        int distance;
        Pair(Point point, int distance) {
            this.point = point;
            this.distance = distance;
        }
    }

    public static int minimumCost(int[] start, int[] target, int[][] specialRoads) {
        Set<Point> pointSet = new HashSet<>();
        Point startPt = new Point(start[0], start[1]);
        Point targetPt = new Point(target[0], target[1]);
        pointSet.add(startPt);
        pointSet.add(targetPt);
        for (int[] road : specialRoads) {
            pointSet.add(new Point(road[0], road[1]));
            pointSet.add(new Point(road[2], road[3]));
        }
        List<Point> points = new ArrayList<>(pointSet);

        Map<Point, Map<Point, Integer>> graph = new HashMap<>();
        for (Point p : points) {
            graph.put(p, new HashMap<>());
        }
        for (int[] road : specialRoads) {
            Point from = new Point(road[0], road[1]);
            Point to = new Point(road[2], road[3]);
            graph.get(from).put(to, road[4]);
        }
        for (int i = 0; i < points.size(); i++) {
            for (int j = 0; j < points.size(); j++) {
                if (i == j) continue;
                Point pi = points.get(i);
                Point pj = points.get(j);
                int cost = Math.abs(pi.x - pj.x) + Math.abs(pi.y - pj.y);
                Map<Point, Integer> edges = graph.get(pi);
                if (!edges.containsKey(pj) || edges.get(pj) > cost) {
                    edges.put(pj, cost);
                }
            }
        }

        Map<Point, Integer> distances = new HashMap<>();
        List<Pair> queue = new ArrayList<>();
        queue.add(new Pair(startPt, 0));
        while (!queue.isEmpty()) {
            Collections.sort(queue, Comparator.comparingInt(p -> p.distance));
            Pair current = queue.remove(0);
            Point point = current.point;
            int distance = current.distance;
            if (distances.containsKey(point) && distances.get(point) <= distance) {
                continue;
            }
            distances.put(point, distance);
            for (Map.Entry<Point, Integer> entry : graph.get(point).entrySet()) {
                Point neighbor = entry.getKey();
                int newDist = distance + entry.getValue();
                if (!distances.containsKey(neighbor) || newDist < distances.get(neighbor)) {
                    queue.add(new Pair(neighbor, newDist));
                }
            }
        }
        return distances.get(targetPt);
    }
}

