class Solution {
    public static String smallestBeautifulString(String s, int k) {
        int n = s.length();
        for (int i = n - 1; i >= 0; i--) {
            for (char ch = (char) (s.charAt(i) + 1); ch < 'a' + k; ch++) {
                if (i > 0 && ch == s.charAt(i - 1)) continue;
                StringBuilder sb = new StringBuilder();
                sb.append(s, 0, i);
                sb.append(ch);
                boolean ok = true;
                for (int j = i + 1; j < n; j++) {
                    char c = 'a';
                    while (c < 'a' + k && c == sb.charAt(j - 1)) {
                        c++;
                    }
                    if (c >= 'a' + k) {
                        ok = false;
                        break;
