        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            Set<Integer> prefixSet = new HashSet<>();
            for (int j = 0; j <= i; j++) {
                prefixSet.add(nums[j]);
            }
            int prefixCount = prefixSet.size();
            Set<Integer> suffixSet = new HashSet<>();
