class Solution {
    public static int minIncrements(int n, int[] cost) {
        long[] inc = new long[1];
        dfs(0, n, cost, inc);
        return (int) inc[0];
    }

    private static long dfs(int i, int n, int[] cost, long[] inc) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left >= n && right >= n) {
            return cost[i];
        }
        long leftSum = 0;
        long rightSum = 0;
        if (left < n) {
            leftSum = dfs(left, n, cost, inc);
        }
        if (right < n) {
            rightSum = dfs(right, n, cost, inc);
        }
        inc[0] += Math.abs(leftSum - rightSum);
        return cost[i] + Math.max(leftSum, rightSum);
    }
}

