class Solution {
    public static FrequencyTracker FrequencyTracker() {
        return new FrequencyTracker();
    }
    public static class FrequencyTracker {
        private final Map<Integer, Integer> freqCount = new HashMap<>();
        private final Map<Integer, Integer> count = new HashMap<>();

        public void add(int num) {
            if (freqCount.containsKey(num)) {
                int f = freqCount.get(num);
                count.put(f, count.get(f) - 1);
                if (count.get(f) == 0) count.remove(f);
            }
            freqCount.put(num, freqCount.getOrDefault(num, 0) + 1);
            int nf = freqCount.get(num);
            count.put(nf, count.getOrDefault(nf, 0) + 1);
        }

        public void remove(int num) {
            if (!freqCount.containsKey(num)) return;
            int f = freqCount.get(num);
            count.put(f, count.get(f) - 1);
            if (count.get(f) == 0) count.remove(f);
            int nf = f - 1;
            if (nf == 0) {
                freqCount.remove(num);
            } else {
                freqCount.put(num, nf);
                count.put(nf, count.getOrDefault(nf, 0) + 1);
            }
        }

        public boolean query(int num) {
            return count.containsKey(num);
        }
    }
}

