public class Solution {
    public static Iterator<Integer> nestedArrayGenerator(Object[] arr) {
        return new Generator(arr);
    }

    private static class Generator implements Iterator<Integer> {
        private static class Frame {
            final Object array;
            final int length;
            int index;
            Frame(Object array) {
                this.array = array;
                this.length = Array.getLength(array);
                this.index = 0;
            }
        }

        private final Deque<Frame> stack = new ArrayDeque<>();
        private Integer nextVal;

        Generator(Object[] root) {
            if (root != null && root.length > 0) {
                stack.push(new Frame(root));
            }
            advance();
        }

        private void advance() {
            nextVal = null;
            while (!stack.isEmpty()) {
                Frame f = stack.peek();
                if (f.index >= f.length) {
                    stack.pop();
                    continue;
                }
                Object elem = Array.get(f.array, f.index++);
                if (elem instanceof Integer) {
                    nextVal = (Integer) elem;
                    return;
                } else if (elem != null && elem.getClass().isArray()) {
                    stack.push(new Frame(elem));
                }
            }
        }

        @Override
        public boolean hasNext() {
            return nextVal != null;
        }

        @Override
        public Integer next() {
            if (nextVal == null) {
                throw new NoSuchElementException();
            }
            Integer result = nextVal;
            advance();
            return result;
        }
    }
}

