class Solution {
    public static int maximumOr(int[] nums, int k) {
        int maxOr = 0;
        int n = nums.length;
        long totalCombinations = 1L << (k * n);
        for (long i = 0; i < totalCombinations; i++) {
            int[] temp = nums.clone();
            int operations = 0;
            for (int j = 0; j < n; j++) {
                for (int bit = 0; bit < k; bit++) {
                    if (((i >> (j * k + bit)) & 1L) == 1L) {
                        temp[j] *= 2;
                        operations++;
                    }
                }
                if (operations > k) {
                    break;
                }
            }
            if (operations > k) {
                continue;
            }
            int or = 0;
            for (int val : temp) {
                or |= val;
            }
            maxOr = Math.max(maxOr, or);
        }
        return maxOr;
    }
}

