class Solution {
    public static int countCompleteComponents(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int a = edge[0];
            int b = edge[1];
            graph[a].add(b);
            graph[b].add(a);
        }
        boolean[] visited = new boolean[n];
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                List<Integer> component = new ArrayList<>();
                dfs(graph, visited, i, component);
                if (isComplete(graph, component)) {
                    count++;
                }
            }
        }
        return count;
    }

    private static void dfs(List<Integer>[] graph, boolean[] visited, int node, List<Integer> component) {
        visited[node] = true;
        component.add(node);
        for (int neighbor : graph[node]) {
            if (!visited[neighbor]) {
                dfs(graph, visited, neighbor, component);
            }
        }
    }

    private static boolean isComplete(List<Integer>[] graph, List<Integer> component) {
        int size = component.size();
        for (int v : component) {
            if (graph[v].size() != size - 1) {
                return false;
            }
        }
        return true;
    }
}

