class Solution {
    public static int maximumMoves(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] memo = new int[rows][cols];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        int result = 0;
        for (int r = 0; r < rows; r++) {
            result = Math.max(result, dfs(grid, memo, r, 0));
        }
        return result;
    }

    private static int dfs(int[][] grid, int[][] memo, int r, int c) {
        if (c == grid[0].length - 1) {
            return 0;
        }
        if (memo[r][c] != -1) {
            return memo[r][c];
        }
        int max = 0;
        int rows = grid.length;
        for (int dr = -1; dr <= 1; dr++) {
            int nr = r + dr;
            int nc = c + 1;
            if (nr >= 0 && nr < rows && grid[nr][nc] > grid[r][c]) {
                max = Math.max(max, 1 + dfs(grid, memo, nr, nc));
            }
        }
        memo[r][c] = max;
        return max;
    }
}

