class Solution {
    public static int minExtraCharacters(String s, List<String> dictionary) {
        int[] dp = new int[s.length() + 1];
        for (int i = 1; i <= s.length(); i++) {
            dp[i] = dp[i - 1] + 1;
            for (String word : dictionary) {
                int wLen = word.length();
                if (i >= wLen && s.substring(i - wLen, i).equals(word)) {
                    dp[i] = Math.min(dp[i], dp[i - wLen]);
                }
            }
        }
        return dp[s.length()];
    }
}

