class Solution {
    public int[][] modifiedGraphEdges(int n, int[][] edges, int source, int destination, int target) {
        final long kMax = 2000000000L;
        List<long[]>[] graph = new List[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) if (e[2] != -1) { graph[e[0]].add(new long[]{e[1], e[2]}); graph[e[1]].add(new long[]{e[0], e[2]}); }
        long d = dijkstra(graph, n, source, destination);
        if (d < target) return new int[0][];
        if (d == target) {
            for (int[] e : edges) if (e[2] == -1) e[2] = (int) kMax;
            return edges;
        }
        for (int i = 0; i < edges.length; i++) {
            if (edges[i][2] != -1) continue;
            edges[i][2] = 1;
            graph[edges[i][0]].add(new long[]{edges[i][1], 1});
            graph[edges[i][1]].add(new long[]{edges[i][0], 1});
            d = dijkstra(graph, n, source, destination);
            if (d <= target) {
                edges[i][2] += (int)(target - d);
                for (int j = i+1; j < edges.length; j++) if (edges[j][2] == -1) edges[j][2] = (int) kMax;
                return edges;
            }
        }
        return new int[0][];
    }
    private long dijkstra(List<long[]>[] graph, int n, int src, int dst) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a,b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0]; int u = (int) top[1];
            if (d > dist[u]) continue;
            for (long[] edge : graph[u]) {
                int v = (int) edge[0]; long w = edge[1];
                if (d + w < dist[v]) { dist[v] = d + w; pq.add(new long[]{dist[v], v}); }
            }
        }
        return dist[dst];
    }
}

import java.util.*;

class Solution {
    public static boolean gcdTraversal(int[] nums) {
        int n = nums.length;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (gcd(nums[i], nums[j]) > 1) {
                    union(parent, rank, i, j);
                }
            }
        }
        int root = find(parent, 0);
        for (int i = 1; i < n; i++) {
            if (find(parent, i) != root) {
                return false;
            }
        }
        return true;
    }

    private static int find(int[] parent, int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent, parent[i]);
    }

    private static void union(int[] parent, int[] rank, int x, int y) {
        int rootX = find(parent, x);
        int rootY = find(parent, y);
        if (rootX == rootY) return;
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

