class Solution {
    public static int[][] differenceOfNumberOnDiagonals(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] answer = new int[m][n];
        Map<Integer, Set<Integer>> diagonalCounts = new HashMap<>();

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int diagonalKey = r - c;
                int antiDiagonalKey = r + c;
                diagonalCounts.computeIfAbsent(diagonalKey, k -> new HashSet<>()).add(grid[r][c]);
                diagonalCounts.computeIfAbsent(antiDiagonalKey, k -> new HashSet<>()).add(grid[r][c]);
            }
        }

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int diagonalKey = r - c;
                int antiDiagonalKey = r + c;
                int diff = diagonalCounts.get(diagonalKey).size() - diagonalCounts.get(antiDiagonalKey).size();
                answer[r][c] = Math.abs(diff);
            }
        }

        return answer;
    }
}

