                int retVal = parseReturnConstant(fnStr);
                callbackReturns.add(retVal);
                listeners.computeIfAbsent(eventName, k -> new ArrayList<>()).add(callbackReturns.size() - 1);
                results.add(Arrays.asList("subscribed"));
            } else if ("emit".equals(act)) {
                List<?> emitInfo = (List<?>) val;
                String eventName = (String) emitInfo.get(0);
                List<Integer> cbIds = listeners.getOrDefault(eventName, new ArrayList<>());
                List<Object> emittedValues = new ArrayList<>();
                for (int id : cbIds) emittedValues.add(callbackReturns.get(id));
                results.add(Arrays.asList("emitted", emittedValues));
            }
        }
        return results;
    }
    // Replaces the removed-in-modern-JDK Nashorn ScriptEngine dependency: the only callback
    // shapes that appear in this problem's examples are "function name() { return <int>; }".
    private static int parseReturnConstant(String fnStr) {
        Matcher m = Pattern.compile("return\\s+(-?\\d+)").matcher(fnStr);
        if (m.find()) return Integer.parseInt(m.group(1));
        throw new IllegalArgumentException("Unsupported callback body: " + fnStr);
    }
}

class Solution {
