class Solution {
    public static int maxCellsInMatrix(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int total = m * n;
        int[][] cells = new int[total][3];
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx][0] = mat[i][j];
                cells[idx][1] = i;
                cells[idx][2] = j;
                idx++;
            }
        }
        Arrays.sort(cells, Comparator.comparingInt(a -> a[0]));
        int[] rowBest = new int[m];
        int[] colBest = new int[n];
        int[][] dp = new int[m][n];
        int answer = 0;
        int i = 0;
        while (i < total) {
            int j = i;
            while (j < total && cells[j][0] == cells[i][0]) {
                j++;
            }
            for (int k = i; k < j; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                dp[r][c] = 1 + Math.max(rowBest[r], colBest[c]);
                answer = Math.max(answer, dp[r][c]);
            }
            for (int k = i; k < j; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                rowBest[r] = Math.max(rowBest[r], dp[r][c]);
                colBest[c] = Math.max(colBest[c], dp[r][c]);
            }
            i = j;
        }
        return answer;
    }
}

