class Solution {
    public static long sumOfMatrixAfterQueries(int n, int[][] queries) {
        boolean[] rowSeen = new boolean[n];
        boolean[] colSeen = new boolean[n];
        int unseenRows = n;
        int unseenCols = n;
        long total = 0;
        for (int i = queries.length - 1; i >= 0; i--) {
            int type = queries[i][0];
            int index = queries[i][1];
            int val = queries[i][2];
            if (type == 0) {
                if (!rowSeen[index]) {
                    total += (long) val * unseenCols;
                    rowSeen[index] = true;
                    unseenRows--;
                }
            } else {
                if (!colSeen[index]) {
                    total += (long) val * unseenRows;
                    colSeen[index] = true;
                    unseenCols--;
                }
            }
        }
        return total;
    }
}

