import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

class Solution {
    public static class Result {
        public long t;
        public List<Object> resolved;
        public Object rejected;
    }

    public static class RejectionException extends Exception {
        public final Result result;
        public RejectionException(Result result) {
            this.result = result;
        }
    }

    public static CompletableFuture<Result> promiseAll(List<Supplier<CompletableFuture<Object>>> functions) {
        CompletableFuture<Result> mainFuture = new CompletableFuture<>();
        Object[] results = new Object[functions.size()];
        AtomicInteger resolvedCount = new AtomicInteger(0);
        long startTime = System.currentTimeMillis();

        for (int i = 0; i < functions.size(); i++) {
            final int index = i;
            Supplier<CompletableFuture<Object>> func = functions.get(i);
            try {
                func.get().whenComplete((res, ex) -> {
                    if (ex == null) {
                        results[index] = res;
                        if (resolvedCount.incrementAndGet() == functions.size()) {
                            long timeTaken = System.currentTimeMillis() - startTime;
                            Result r = new Result();
                            r.t = timeTaken;
                            r.resolved = Arrays.asList(results);
                            mainFuture.complete(r);
                        }
                    } else {
                        long timeTaken = System.currentTimeMillis() - startTime;
                        Result r = new Result();
                        r.t = timeTaken;
                        r.rejected = ex;
                        mainFuture.completeExceptionally(new RejectionException(r));
                    }
                });
            } catch (Throwable e) {
                long timeTaken = System.currentTimeMillis() - startTime;
                Result r = new Result();
                r.t = timeTaken;
                r.rejected = e;
                mainFuture.completeExceptionally(new RejectionException(r));
            }
        }
        return mainFuture;
    }
}

