class Solution {
    public static double calculate(List<String> actions, List<Double> values) {
        double result = values.get(0);
        int index = 1;
        for (int i = 1; i < actions.size() - 1; i++) {
            String act = actions.get(i);
            double val = values.get(index);
            if (act.equals("add")) result += val;
            else if (act.equals("subtract")) result -= val;
            else if (act.equals("multiply")) result *= val;
            else if (act.equals("divide")) {
                if (val == 0) throw new ArithmeticException("Division by zero is not allowed");
                result /= val;
            }
            else if (act.equals("power")) result = Math.pow(result, val);
            index++;
        }
        return result;
    }
}

