class Solution {
    public static long robotMovement(int[] nums, String s, int d) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        long[] positions = new long[n];
        for (int i = 0; i < n; i++) {
            positions[i] = nums[i];
        }
        int[] directions = new int[n];
        for (int i = 0; i < n; i++) {
            directions[i] = s.charAt(i) == 'L' ? -1 : 1;
        }
        for (int i = 0; i < d; i++) {
            for (int j = 0; j < n; j++) {
                positions[j] += directions[j];
            }
            for (int j = 0; j < n - 1; j++) {
                for (int k = j + 1; k < n; k++) {
                    if (positions[j] == positions[k]) {
                        directions[j] *= -1;
                        directions[k] *= -1;
                    }
                }
            }
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                sum = (sum + Math.abs(positions[i] - positions[j])) % MOD;
            }
        }
        return sum;
    }
}

class Solution {
    public static int longestSemiRepetitiveSubstring(String s) {
        int maxLength = 0;
        int left = 0;
        int repeatedCount = 0;
        for (int right = 0; right < s.length(); right++) {
            if (right > 0 && s.charAt(right) == s.charAt(right - 1)) repeatedCount++;
            while (repeatedCount > 1) {
                if (s.charAt(left) == s.charAt(left + 1)) repeatedCount--;
                left++;
            }
            maxLength = Math.max(maxLength, right - left + 1);
        }
        return maxLength;
    }
}

