        char[] arr = s.toCharArray();
        int n = arr.length;
        int i = 0;
        while (i < n - 1 && arr[i] <= arr[i + 1]) {
            i++;
        }
        if (i == n - 1) {
            arr[n - 1] = arr[n - 1] == 'a' ? 'z' : (char) (arr[n - 1] - 1);
        } else {
            while (i < n && arr[i] != 'a') {
                arr[i] = (char) (arr[i] - 1);
                i++;
            }
        }
        return new String(arr);
    }
}

