class Solution {
    public static double totalDistanceTraveled(double mainTank, double additionalTank) {
        double totalDistance = 0;
        double fuelConsumed = 0;
        while (mainTank > 0) {
            double distance = mainTank * 10;
            fuelConsumed = distance / 10;
            if (fuelConsumed > mainTank) {
                distance = mainTank * 10;
                fuelConsumed = mainTank;
            }
            double injections = Math.floor(fuelConsumed / 5);
            double injectedFuel = Math.min(injections, additionalTank);
            mainTank -= fuelConsumed - injectedFuel;
            additionalTank -= injectedFuel;
            totalDistance += distance;
        }
        return totalDistance;
    }
}

