class Solution {
    public static int countSpecialPermutations(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        if (n == 0) return 0;
        boolean[][] ok = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                ok[i][j] = (nums[i] % nums[j] == 0) || (nums[j] % nums[i] == 0);
            }
        }
        int totalMask = 1 << n;
        long[][] dp = new long[totalMask][n];
        for (int i = 0; i < n; i++) {
            dp[1 << i][i] = 1;
        }
        for (int mask = 1; mask < totalMask; mask++) {
            for (int last = 0; last < n; last++) {
                if ((mask & (1 << last)) == 0) continue;
                long cur = dp[mask][last];
                if (cur == 0) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    if (ok[last][nxt]) {
                        int nextMask = mask | (1 << nxt);
                        dp[nextMask][nxt] = (dp[nextMask][nxt] + cur) % MOD;
                    }
                }
            }
        }
        long ans = 0;
        int fullMask = totalMask - 1;
        for (int i = 0; i < n; i++) {
            ans = (ans + dp[fullMask][i]) % MOD;
        }
        return (int) ans;
    }
}

