        int top = 0;
        for (int i = 0; i < s.length(); i++) {
            stack[top++] = s.charAt(i);
            while (top >= 2) {
                char a = stack[top - 2];
                char b = stack[top - 1];
                if ((a == 'A' && b == 'B') || (a == 'C' && b == 'D')) {
