class Solution {
    public long continuousSubarrays(int[] nums) {
        Deque<Integer> maxd = new ArrayDeque<>(), mind = new ArrayDeque<>();
        int l = 0;
        long ans = 0;
        for (int r = 0; r < nums.length; r++) {
            int x = nums[r];
            while (!maxd.isEmpty() && nums[maxd.peekLast()] <= x) maxd.pollLast();
            maxd.addLast(r);
            while (!mind.isEmpty() && nums[mind.peekLast()] >= x) mind.pollLast();
            mind.addLast(r);
            while (nums[maxd.peekFirst()] - nums[mind.peekFirst()] > 2) {
                l++;
                if (maxd.peekFirst() < l) maxd.pollFirst();
                if (mind.peekFirst() < l) mind.pollFirst();
            }
            ans += r - l + 1;
        }
        return ans;
    }
}

public class Solution {
    public static int longestAlternatingSubarray(int[] nums) {
        int maxLen = -1;
        int curLen = 1;
        int prevDiff = 0;
        for (int i = 1; i < nums.length; i++) {
            int diff = nums[i] - nums[i - 1];
            if (Math.abs(diff) == 1 && (prevDiff == 0 || diff * prevDiff == -1)) {
                curLen++;
            } else if (Math.abs(diff) == 1) {
                curLen = 2;
            } else {
                curLen = 1;
            }
            prevDiff = Math.abs(diff) == 1 ? diff : 0;
            if (curLen > maxLen) {
                maxLen = curLen;
            }
        }
        return maxLen >= 2 ? maxLen : -1;
    }
}

