class Solution {
    public static int minimumLength(String[] words) {
        int n = words.length;
        int totalLen = 0;
        for (String w : words) totalLen += w.length();
        int[][] overlap = new int[n][n];
        for (int i = 0; i < n; i++) {
            char last = words[i].charAt(words[i].length() - 1);
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                char first = words[j].charAt(0);
                overlap[i][j] = (last == first) ? 1 : 0;
            }
        }
        int size = 1 << n;
        int[][] dp = new int[size][n];
        for (int[] row : dp) Arrays.fill(row, -1);
        for (int i = 0; i < n; i++) dp[1 << i][i] = 0;
        for (int mask = 0; mask < size; mask++) {
            for (int last = 0; last < n; last++) {
                if (dp[mask][last] == -1) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    int newMask = mask | (1 << nxt);
                    int val = dp[mask][last] + overlap[last][nxt];
                    if (val > dp[newMask][nxt]) dp[newMask][nxt] = val;
                }
            }
        }
        int maxOverlap = 0;
        int fullMask = size - 1;
        for (int i = 0; i < n; i++) {
            if (dp[fullMask][i] > maxOverlap) maxOverlap = dp[fullMask][i];
        }
        return totalLen - maxOverlap;
    }
}

