public class Solution {
    public static int minBeautifulSubstrings(String s) {
        int n = s.length();
        List<String> powers = new ArrayList<>();
        long val = 1;
        while (true) {
            String bin = Long.toBinaryString(val);
            if (bin.length() > n) break;
            powers.add(bin);
            val *= 5;
        }
        int INF = 1_000_000_000;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            for (String b : powers) {
                int len = b.length();
                if (len <= i && s.substring(i - len, i).equals(b)) {
                    dp[i] = Math.min(dp[i], dp[i - len] + 1);
                }
            }
        }
        return dp[n] == INF ? -1 : dp[n];
    }
}

