class Solution {
    public static int maxJumps(int[] nums, int target) {
        int n = nums.length;
        if (n == 0) return -1;
        if (n == 1) return 0;
        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MIN_VALUE);
        dp[0] = 0;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (Math.abs(nums[j] - nums[i]) <= target && dp[j] != Integer.MIN_VALUE) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
        }
        return dp[n - 1] == Integer.MIN_VALUE ? -1 : dp[n - 1];
    }
}

