class Solution {
    public static long sumImbalanceNumbers(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int i = 0; i < n; i++) {
            TreeSet<Integer> set = new TreeSet<>();
            int imbalance = 0;
            for (int j = i; j < n; j++) {
                int x = nums[j];
                if (!set.contains(x)) {
                    Integer lower = set.lower(x);
                    Integer higher = set.higher(x);
                    int before = 0;
                    if (lower != null && higher != null) {
                        if (higher - lower > 1) {
                            before = 1;
                        }
                    }
                    int after = 0;
                    if (lower != null && x - lower > 1) {
                        after++;
                    }
                    if (higher != null && higher - x > 1) {
                        after++;
                    }
                    imbalance += after - before;
                    set.add(x);
                }
                total += imbalance;
            }
        }
        return total;
    }
}

