class Solution {
    public boolean checkArray(int[] nums, int k) {
        int n = nums.length;
        long[] diff = new long[n + 1];
        long cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            long need = nums[i] - cur;
            if (need < 0) {
                return false;
            }
            if (need > 0) {
                if (i + k > n) {
                    return false;
                }
                cur += need;
                diff[i + k] -= need;
            }
        }
        return true;
    }
}

