class Solution {
    public static int maximumBeauty(int[] nums, int k) {
        int n = nums.length;
        long[][] events = new long[2 * n][2];
        for (int i = 0; i < n; i++) {
            long l = (long) nums[i] - k;
            long r = (long) nums[i] + k;
            events[2 * i][0] = l;
            events[2 * i][1] = 1;
            events[2 * i + 1][0] = r + 1;
            events[2 * i + 1][1] = -1;
        }
        Arrays.sort(events, (a, b) -> {
            if (a[0] < b[0]) return -1;
            if (a[0] > b[0]) return 1;
            return Long.compare(a[1], b[1]);
        });
        int cur = 0;
        int max = 0;
        for (long[] e : events) {
            cur += e[1];
            if (cur > max) max = cur;
        }
        return max;
    }
}

