class Solution {
    public static int minimumValidSplit(int[] nums) {
        int n = nums.length;
        int candidate = 0;
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (count == 0) {
                candidate = nums[i];
                count = 1;
            } else if (nums[i] == candidate) {
                count++;
            } else {
                count--;
            }
        }
        int dom = candidate;
        int totalDom = 0;
        for (int v : nums) {
            if (v == dom) totalDom++;
        }
        int leftCount = 0;
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == dom) leftCount++;
            int leftLen = i + 1;
            int rightLen = n - leftLen;
            int rightCount = totalDom - leftCount;
            if (leftCount * 2 > leftLen && rightCount * 2 > rightLen) {
                return i;
            }
        }
        return -1;
    }
}

