public class Solution {
    public long maxScore(int[] nums, int x) {
        int n = nums.length;
        long bestEven = Long.MIN_VALUE / 4;
        long bestOdd = Long.MIN_VALUE / 4;
        long ans = nums[0];
        if ((nums[0] & 1) == 0) {
            bestEven = nums[0];
        } else {
            bestOdd = nums[0];
        }
        for (int i = 1; i < n; i++) {
            long sameParityBest = ((nums[i] & 1) == 0) ? bestEven : bestOdd;
            long oppParityBest = ((nums[i] & 1) == 0) ? bestOdd : bestEven;
            long candidate = Math.max(sameParityBest, oppParityBest - x);
            long cur = nums[i] + candidate;
            ans = Math.max(ans, cur);
            if ((nums[i] & 1) == 0) {
                bestEven = Math.max(bestEven, cur);
            } else {
                bestOdd = Math.max(bestOdd, cur);
            }
        }
        return ans;
    }
}

