class Solution {
    public static int maxPossibleElement(int[] nums) {
        Stack<Integer> stack = new Stack<>();
        int max = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            int cur = nums[i];
            while (!stack.isEmpty() && cur <= stack.peek()) {
                cur += stack.pop();
            }
            stack.push(cur);
            if (cur > max) {
                max = cur;
            }
        }
        return max;
    }
}

