class Solution {
    public long countPalindromePairs(int[] parent, String s) {
        int n = parent.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            children[parent[i]].add(i);
        }

        int[] mask = new int[n];
        int[] stack = new int[n];
        int top = 0;
        stack[top++] = 0;
        mask[0] = 0;
        while (top > 0) {
            int u = stack[--top];
            for (int v : children[u]) {
                char c = s.charAt(v);
                mask[v] = mask[u] ^ (1 << (c - 'a'));
                stack[top++] = v;
            }
        }

        Map<Integer, Integer> freq = new HashMap<>();
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int m = mask[i];
            ans += freq.getOrDefault(m, 0);
            for (int b = 0; b < 26; b++) {
                int m2 = m ^ (1 << b);
                ans += freq.getOrDefault(m2, 0);
            }
            freq.put(m, freq.getOrDefault(m, 0) + 1);
        }
        return ans;
    }
}

