class Solution {
    public static int countWays(int n, int x) {
        final int MOD = 1000000007;
        List<Integer> powers = new ArrayList<>();
        for (int i = 1; ; ++i) {
            long v = (long) Math.pow(i, x);
            if (v > n) break;
            powers.add((int) v);
        }
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int v : powers) {
            for (int s = n; s >= v; --s) {
                dp[s] = (dp[s] + dp[s - v]) % MOD;
            }
        }
        return (int) dp[n];
    }
}

