public class Solution {
    public int maxNumberOfGroups(int[] usageLimits) {
        long total = 0;
        for (int v : usageLimits) {
            total += v;
        }
        int low = 0;
        int high = (int) Math.sqrt(2.0 * total) + 2;
        while (low < high) {
            int mid = (low + high + 1) >>> 1;
            if (canForm(mid, usageLimits)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private boolean canForm(int k, int[] usageLimits) {
        long need = (long) k * (k + 1) / 2;
        long have = 0;
        for (int v : usageLimits) {
            have += Math.min(v, k);
            if (have >= need) {
                return true;
            }
        }
        return have >= need;
    }
}

