class Solution {
    public long countCompleteSubarrays(int[] nums) {
        int n = nums.length;
        Set<Integer> globalSet = new HashSet<>();
        for (int v : nums) {
            globalSet.add(v);
        }
        int totalDistinct = globalSet.size();
        Map<Integer, Integer> freq = new HashMap<>();
        int distinctInWindow = 0;
        long ans = 0;
        int right = 0;
        for (int left = 0; left < n; left++) {
            while (right < n && distinctInWindow < totalDistinct) {
                int val = nums[right];
                int cnt = freq.getOrDefault(val, 0);
                if (cnt == 0) {
                    distinctInWindow++;
                }
                freq.put(val, cnt + 1);
                right++;
            }
            if (distinctInWindow == totalDistinct) {
                ans += n - right + 1;
            }
            int leftVal = nums[left];
            int cntLeft = freq.get(leftVal);
            if (cntLeft == 1) {
                freq.remove(leftVal);
                distinctInWindow--;
            } else {
                freq.put(leftVal, cntLeft - 1);
            }
        }
        return ans;
    }
}

