public class Solution {
    public String shortestString(String a, String b, String c) {
        String[] strs = {a, b, c};
        String best = null;
        int[] idx = {0, 1, 2};
        // generate all permutations of 0,1,2
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (j == i) continue;
                for (int k = 0; k < 3; k++) {
                    if (k == i || k == j) continue;
                    String merged = merge(strs[i], strs[j]);
                    merged = merge(merged, strs[k]);
                    if (best == null || merged.length() < best.length() ||
                        (merged.length() == best.length() && merged.compareTo(best) < 0)) {
                        best = merged;
                    }
                }
            }
        }
        return best;
    }

    private String merge(String s1, String s2) {
        if (s1.contains(s2)) return s1;
        if (s2.contains(s1)) return s2;
        int maxOverlap = 0;
        int limit = Math.min(s1.length(), s2.length());
        for (int len = limit; len > 0; len--) {
            if (s1.regionMatches(s1.length() - len, s2, 0, len)) {
                maxOverlap = len;
                break;
            }
        }
        return s1 + s2.substring(maxOverlap);
    }
}

