public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countSteppingNumbers(String low, String high) {
        String lowMinusOne = subtractOne(low);
        long result = (count(high) - count(lowMinusOne) + MOD) % MOD;
        return (int) result;
    }

    private String subtractOne(String s) {
        if (s.equals("0")) return "0";
        StringBuilder sb = new StringBuilder(s);
        int i = sb.length() - 1;
        while (i >= 0 && sb.charAt(i) == '0') {
            sb.setCharAt(i, '9');
            i--;
        }
        if (i < 0) {
            return "0";
        }
        sb.setCharAt(i, (char) (sb.charAt(i) - 1));
        int start = 0;
        while (start < sb.length() - 1 && sb.charAt(start) == '0') start++;
        return sb.substring(start);
    }

    private long count(String s) {
        char[] digits = s.toCharArray();
        int n = digits.length;
        long[][][][] memo = new long[n + 1][11][2][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 11; j++) {
                for (int t = 0; t < 2; t++) {
                    Arrays.fill(memo[i][j][t], -1L);
                }
            }
        }
        return dfs(0, -1, true, false, digits, memo);
    }

    private long dfs(int pos, int prev, boolean tight, boolean started, char[] digits, long[][][][] memo) {
        if (pos == digits.length) {
            return started ? 1L : 0L;
        }
        int prevIdx = prev + 1;
        int tIdx = tight ? 1 : 0;
        int sIdx = started ? 1 : 0;
        long cached = memo[pos][prevIdx][tIdx][sIdx];
        if (cached != -1) return cached;

        long res = 0;
        int limit = tight ? digits[pos] - '0' : 9;
        for (int d = 0; d <= limit; d++) {
            boolean nextTight = tight && (d == limit);
            if (!started && d == 0) {
                res = (res + dfs(pos + 1, -1, nextTight, false, digits, memo)) % MOD;
            } else if (!started) {
                res = (res + dfs(pos + 1, d, nextTight, true, digits, memo)) % MOD;
            } else {
                if (Math.abs(d - prev) == 1) {
                    res = (res + dfs(pos + 1, d, nextTight, true, digits, memo)) % MOD;
                }
            }
        }
        memo[pos][prevIdx][tIdx][sIdx] = res;
        return res;
    }
}

