class Solution {
    public static int minimumTime(int[] nums1, int[] nums2, int x) {
        int n = nums1.length;
        long total1 = 0, total2 = 0;
        for (int v : nums1) total1 += v;
        for (int v : nums2) total2 += v;
        if (total1 <= x) return 0;

        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a,b) -> nums2[a] - nums2[b]);

        final long NEG = Long.MIN_VALUE/2;
        long[] dp = new long[n+1];
        java.util.Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int i : idx) {
            for (int j = n; j >= 1; j--) {
                if (dp[j-1] == NEG) continue;
                long candidate = dp[j-1] + nums1[i] + (long) nums2[i]*j;
                if (candidate > dp[j]) dp[j] = candidate;
            }
        }
        for (int T = 0; T <= n; T++) {
            int k = Math.min(T, n);
            long savings = dp[k] != NEG ? dp[k] : 0;
            long finalSum = total1 + (long)T*total2 - savings;
            if (finalSum <= x) return T;
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public long maximumElegance(int[][] items, int k) {
        int n = items.length;
        Arrays.sort(items, (a, b) -> Integer.compare(b[0], a[0])); // descending profit

        long sum = 0;
        int distinct = 0;
        boolean[] seen = new boolean[n + 1];
        PriorityQueue<Integer> dupHeap = new PriorityQueue<>();

        for (int i = 0; i < k; i++) {
            int profit = items[i][0];
            int cat = items[i][1];
            sum += profit;
            if (!seen[cat]) {
                seen[cat] = true;
                distinct++;
            } else {
                dupHeap.add(profit);
            }
        }

        long best = sum + (long) distinct * distinct;

        for (int i = k; i < n; i++) {
            int profit = items[i][0];
            int cat = items[i][1];
            if (seen[cat]) continue;
            if (dupHeap.isEmpty()) break;
            int smallestDup = dupHeap.poll();
            sum = sum - smallestDup + profit;
            seen[cat] = true;
            distinct++;
            long elegance = sum + (long) distinct * distinct;
            if (elegance > best) best = elegance;
        }

        return best;
    }
}

