class Solution {
    public static int minimumSeconds(int[] nums) {
        int n = nums.length;
        Map<Integer, List<Integer>> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            map.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }
        int answer = Integer.MAX_VALUE;
        for (List<Integer> positions : map.values()) {
            int maxGap = 0;
            int m = positions.size();
            for (int i = 0; i < m; i++) {
                int cur = positions.get(i);
                int next = positions.get((i + 1) % m);
                int gap = (next - cur - 1 + n) % n;
                if (gap > maxGap) {
                    maxGap = gap;
                }
            }
            int seconds = (maxGap + 1) / 2;
            if (seconds < answer) {
                answer = seconds;
            }
        }
        return answer;
    }
}

class Solution {
    public static boolean canSplitArray(int[] nums, int m) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        boolean[][] dp = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = true;
        }
        for (int len = 2; len <= n; len++) {
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                long sum = prefix[r + 1] - prefix[l];
                if (sum < m) continue;
                for (int k = l; k < r; k++) {
                    if (dp[l][k] && dp[k + 1][r]) {
                        dp[l][r] = true;
                        break;
                    }
                }
            }
        }
        return n > 0 && dp[0][n - 1];
    }
}

