class Solution {
    public static String faultyKeyboard(String s) {
        Deque<Character> result = new ArrayDeque<>();
        boolean reversed = false;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == 'i') {
                reversed = !reversed;
            } else {
                if (!reversed) {
                    result.addLast(ch);
                } else {
                    result.addFirst(ch);
                }
            }
        }
        StringBuilder sb = new StringBuilder(result.size());
        Iterator<Character> it = reversed ? result.descendingIterator() : result.iterator();
        while (it.hasNext()) {
            sb.append(it.next());
        }
        return sb.toString();
    }
}

class ListNode {
    int val; ListNode next;
    ListNode(int val) { this.val = val; }
}
class Solution {
    public static ListNode doubleLinkedList(ListNode head) {
        ListNode prev = null, cur = head;
        while (cur != null) { ListNode nxt = cur.next; cur.next = prev; prev = cur; cur = nxt; }
        ListNode node = prev;
        int carry = 0;
        while (node != null) {
            int sum = node.val * 2 + carry;
            node.val = sum % 10;
            carry = sum / 10;
            if (node.next == null && carry != 0) {
                node.next = new ListNode(carry);
                carry = 0;
                break; // FIX: don't re-process the freshly appended carry digit
            }
            node = node.next;
        }
        cur = prev; prev = null;
        while (cur != null) { ListNode nxt = cur.next; cur.next = prev; prev = cur; cur = nxt; }
        return prev;
    }
}

import java.util.*;

class Node {
    int key;
    double pri;
    int cnt;
    Node left;
    Node right;

    Node(int key) {
        this.key = key;
        this.pri = Math.random();
        this.cnt = 1;
        this.left = null;
        this.right = null;
    }
}

class Solution {
    private static Node rotateRight(Node p) {
        Node q = p.left;
        p.left = q.right;
        q.right = p;
        return q;
    }

    private static Node rotateLeft(Node p) {
        Node q = p.right;
        p.right = q.left;
        q.left = p;
        return q;
    }

    private static Node insert(Node node, int key) {
        if (node == null) return new Node(key);
        if (key == node.key) {
            node.cnt++;
        } else if (key < node.key) {
            node.left = insert(node.left, key);
            if (node.left.pri < node.pri) node = rotateRight(node);
        } else {
            node.right = insert(node.right, key);
            if (node.right.pri < node.pri) node = rotateLeft(node);
        }
        return node;
    }

    private static Node lowerBound(Node node, int key) {
        if (node == null) return null;
        if (node.key >= key) {
            Node left = lowerBound(node.left, key);
            return left != null ? left : node;
        }
        return lowerBound(node.right, key);
    }

    private static Node predecessor(Node node, int key) {
        if (node == null) return null;
        if (node.key < key) {
            Node right = predecessor(node.right, key);
            return right != null ? right : node;
        }
        return predecessor(node.left, key);
    }

    public static int minimumAbsoluteDifference(int[] nums, int x) {
        Node root = null;
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            if (i - x >= 0) {
                root = insert(root, nums[i - x]);
            }
            Node lb = lowerBound(root, nums[i]);
            if (lb != null) {
                best = Math.min(best, Math.abs(lb.key - nums[i]));
            }
            Node pred = predecessor(root, nums[i]);
            if (pred != null) {
                best = Math.min(best, Math.abs(pred.key - nums[i]));
            }
        }
        return best == Integer.MAX_VALUE ? 0 : best;
    }
}

class Solution {
    public static long maxScore(int[] nums, int k) {
        int n = nums.length;
        final long MOD = 1000000007;
        int[] scores = new int[n];
        for (int i = 0; i < n; i++) scores[i] = primeScore(nums[i]);
        int[] left = new int[n], right = new int[n];
        int[] stack = new int[n]; int top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && scores[stack[top]] < scores[i]) top--;
            left[i] = top >= 0 ? stack[top] : -1;
            stack[++top] = i;
        }
        top = -1;
        for (int i = n-1; i >= 0; i--) {
            while (top >= 0 && scores[stack[top]] <= scores[i]) top--;
            right[i] = top >= 0 ? stack[top] : n;
            stack[++top] = i;
        }
        long[] count = new long[n];
        for (int i = 0; i < n; i++) count[i] = (long)(i - left[i]) * (right[i] - i);
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        java.util.Arrays.sort(order, (a, b) -> nums[b] - nums[a]);
        long remaining = k;
        long ans = 1;
        for (int i : order) {
            if (remaining <= 0) break;
            long take = Math.min(count[i], remaining);
            ans = (ans * modpow(nums[i], take, MOD)) % MOD;
            remaining -= take;
        }
        return ans;
    }
    private static int primeScore(int x) {
        int count = 0;
        for (int p = 2; (long)p*p <= x; p++) {
            if (x % p == 0) { count++; while (x % p == 0) x /= p; }
        }
        if (x > 1) count++;
        return count;
    }
    private static long modpow(long base, long exp, long mod) {
        base %= mod;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

