class Solution {
    public static int maxPairSum(int[] nums) {
        int[] first = new int[10];
        int[] second = new int[10];
        for (int i = 0; i < 10; i++) {
            first[i] = -1;
            second[i] = -1;
        }
        for (int i = 0; i < nums.length; i++) {
            int n = nums[i];
            int maxDigit = 0;
            if (n == 0) {
                maxDigit = 0;
            } else {
                while (n > 0) {
                    int d = n % 10;
                    if (d > maxDigit) {
                        maxDigit = d;
                    }
                    n = n / 10;
                }
            }
            if (nums[i] > first[maxDigit]) {
                second[maxDigit] = first[maxDigit];
                first[maxDigit] = nums[i];
            } else if (nums[i] > second[maxDigit]) {
                second[maxDigit] = nums[i];
            }
        }
        int best = -1;
        for (int d = 0; d < 10; d++) {
            if (second[d] != -1) {
                int sum = first[d] + second[d];
                if (sum > best) {
                    best = sum;
                }
            }
        }
        return best;
    }
}

