class Solution {
    public static int minOperations(int[] nums) {
        int dp1 = 0, dp2 = 0, dp3 = 0;
        for (int v : nums) {
            if (v == 1) {
                dp1 = dp1 + 1;
            } else if (v == 2) {
                dp2 = Math.max(dp1, dp2) + 1;
            } else {
                dp3 = Math.max(dp2, dp3) + 1;
            }
        }
        int longest = Math.max(dp1, Math.max(dp2, dp3));
        return nums.length - longest;
    }
}

