import java.util.Arrays;
import java.util.Comparator;

class Solution {
    public static int maxProfit(int n, int[][] offers) {
        Arrays.sort(offers, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                return Integer.compare(a[1], b[1]);
            }
        });

        int m = offers.length;
        int[] ends = new int[m];
        int[] dp = new int[m];

        for (int i = 0; i < m; i++) {
            ends[i] = offers[i][1];
        }

        for (int i = 0; i < m; i++) {
            int start = offers[i][0];
            int gold = offers[i][2];

            int lo = 0, hi = i - 1, prev = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1;
                if (ends[mid] < start) {
                    prev = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }

            int take = gold + (prev >= 0 ? dp[prev] : 0);
            int skip = i > 0 ? dp[i - 1] : 0;
            dp[i] = take > skip ? take : skip;
        }

        return m > 0 ? dp[m - 1] : 0;
    }
}

