public class Solution {
    private int[] digits;
    private int len;
    private int k;
    private int offset;
    private long[][][][] dp;

    public int numberOfBeautifulIntegers(int low, int high, int k) {
        this.k = k;
        long result = countUpTo(high) - countUpTo(low - 1);
        return (int) result;
    }

    private long countUpTo(int n) {
        if (n < 0) return 0;
        String s = Integer.toString(n);
        len = s.length();
        digits = new int[len];
        for (int i = 0; i < len; i++) {
            digits[i] = s.charAt(i) - '0';
        }
        offset = len; // diff ranges from -len to +len
        dp = new long[len][2 * len + 1][k][2];
        for (int i = 0; i < len; i++) {
            for (int d = 0; d < 2 * len + 1; d++) {
                for (int r = 0; r < k; r++) {
                    Arrays.fill(dp[i][d][r], -1L);
                }
            }
        }
        return dfs(0, 0, 0, true, false);
    }

    private long dfs(int pos, int diff, int rem, boolean tight, boolean started) {
        if (pos == len) {
            return (started && diff == 0 && rem == 0) ? 1L : 0L;
        }
        if (!tight) {
            int stIdx = started ? 1 : 0;
            int diffIdx = diff + offset;
            if (dp[pos][diffIdx][rem][stIdx] != -1) {
                return dp[pos][diffIdx][rem][stIdx];
            }
            long ans = 0;
            for (int d = 0; d <= 9; d++) {
                boolean nStarted = started || d != 0;
                int nDiff = diff;
                int nRem = rem;
                if (nStarted) {
                    if (d % 2 == 0) nDiff -= 1;
                    else nDiff += 1;
                    nRem = (rem * 10 + d) % k;
                }
                ans += dfs(pos + 1, nDiff, nRem, false, nStarted);
            }
            dp[pos][diffIdx][rem][stIdx] = ans;
            return ans;
        } else {
            long ans = 0;
            int limit = digits[pos];
            for (int d = 0; d <= limit; d++) {
                boolean nStarted = started || d != 0;
                int nDiff = diff;
                int nRem = rem;
                if (nStarted) {
                    if (d % 2 == 0) nDiff -= 1;
                    else nDiff += 1;
                    nRem = (rem * 10 + d) % k;
                }
                ans += dfs(pos + 1, nDiff, nRem, tight && d == limit, nStarted);
            }
            return ans;
        }
    }
}

