class Solution {
    public int longestEqualSubarray(int[] nums, int k) {
        int n = nums.length;
        int[] cnt = new int[n + 1];
        int left = 0, maxFreq = 0, ans = 0;
        for (int right = 0; right < n; right++) {
            int v = nums[right];
            cnt[v]++;
            if (cnt[v] > maxFreq) {
                maxFreq = cnt[v];
            }
            while ((right - left + 1) - maxFreq > k) {
                cnt[nums[left]]--;
                left++;
            }
            if (maxFreq > ans) {
                ans = maxFreq;
            }
        }
        return ans;
    }
}

