import java.math.BigInteger;

class Solution {
    public static int minimumBeautifulArraySum(int n, int target) {
        BigInteger MOD = BigInteger.valueOf(1000000007L);
        BigInteger N = BigInteger.valueOf(n);
        BigInteger T = BigInteger.valueOf(target);
        BigInteger A = T.divide(BigInteger.valueOf(2));
        BigInteger countUpToTarget = A.add(BigInteger.ONE);
        BigInteger sum;
        if (N.compareTo(A) <= 0) {
            sum = N.multiply(N.add(BigInteger.ONE)).divide(BigInteger.valueOf(2));
        } else if (N.equals(countUpToTarget)) {
            sum = A.multiply(A.add(BigInteger.ONE)).divide(BigInteger.valueOf(2)).add(T);
        } else {
            BigInteger extra = N.subtract(countUpToTarget);
            sum = A.multiply(A.add(BigInteger.ONE)).divide(BigInteger.valueOf(2))
                    .add(T)
                    .add(extra.multiply(T))
                    .add(extra.multiply(extra.add(BigInteger.ONE)).divide(BigInteger.valueOf(2)));
        }
        return sum.mod(MOD).intValue();
    }
}

import java.util.*;

class Solution {
    public static long maxScore(int[] receiver, long k) {
        int n = receiver.length;
        long best = Long.MIN_VALUE;
        long totalSteps = k + 1;
        for (int start = 0; start < n; start++) {
            int cur = start;
            int steps = 0;
            long sum = 0;
            Map<Integer, Integer> visited = new HashMap<>();
            List<Integer> path = new ArrayList<>();
            while (steps < totalSteps) {
                if (visited.containsKey(cur)) {
                    break;
                }
                visited.put(cur, steps);
                path.add(cur);
                sum += cur;
                steps++;
                cur = receiver[cur];
            }
            if (steps == totalSteps) {
                if (sum > best) best = sum;
                continue;
            }
            int cycleStartIdx = visited.get(cur);
            int cycleLen = steps - cycleStartIdx;
            long cycleSum = 0;
            for (int i = cycleStartIdx; i < steps; i++) {
                cycleSum += path.get(i);
            }
            long remaining = totalSteps - steps;
            long fullCycles = remaining / cycleLen;
            sum += fullCycles * cycleSum;
            remaining %= cycleLen;
            for (int i = 0; i < remaining; i++) {
                sum += path.get(cycleStartIdx + i);
            }
            if (sum > best) best = sum;
        }
        return best;
    }
}

