        return duplicate;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxSumAlmostUnique(int[] nums, int m, int k) {
        if (k > nums.length) return 0;
        Map<Integer, Integer> freq = new HashMap<>();
        int distinctCount = 0;
        long windowSum = 0;
        long best = 0;
        for (int i = 0; i < nums.length; i++) {
            int right = nums[i];
            windowSum += right;
            int rightFreq = freq.getOrDefault(right, 0) + 1;
            freq.put(right, rightFreq);
            if (rightFreq == 1) distinctCount++;
            if (i >= k) {
                int left = nums[i - k];
                windowSum -= left;
                int leftFreq = freq.get(left) - 1;
                if (leftFreq == 0) {
                    freq.remove(left);
                    distinctCount--;
                } else {
                    freq.put(left, leftFreq);
                }
            }
            if (i >= k - 1) {
                if (distinctCount >= m && windowSum > best) {
                    best = windowSum;
                }
            }
        }
        return (int) best;
    }
}

