class Solution {
    public static int minOperations(int[] nums, int target) {
        final int MAX_BITS = 31;
        int[] cnt = new int[MAX_BITS];
        for (int v : nums) {
            int e = 0;
            while (v > 1) {
                v >>= 1;
                e++;
            }
            cnt[e]++;
        }
        int ops = 0;
        for (int i = 0; i < MAX_BITS; i++) {
            if (((target >> i) & 1) == 1) {
                if (cnt[i] > 0) {
                    cnt[i]--;
                } else {
                    int j = i + 1;
                    while (j < MAX_BITS && cnt[j] == 0) {
                        j++;
                    }
                    if (j == MAX_BITS) {
                        return -1;
                    }
                    while (j > i) {
                        cnt[j]--;
                        cnt[j - 1] += 2;
                        ops++;
                        j--;
                    }
                    cnt[i]--;
                }
            }
            if (i + 1 < MAX_BITS) {
                cnt[i + 1] += cnt[i] / 2;
            }
        }
        return ops;
    }
}

