class Solution {
    public static int minOperations(String num) {
        int n = num.length();
        int answer = n;
        String[] targets = {"00", "25", "50", "75"};
        for (String t : targets) {
            int i = n - 1;
            while (i >= 0 && num.charAt(i) != t.charAt(1)) i--;
            if (i < 0) continue;
            int j = i - 1;
            while (j >= 0 && num.charAt(j) != t.charAt(0)) j--;
            if (j < 0) continue;
            int deletions = (n - 1 - i) + (i - 1 - j);
            if (deletions < answer) answer = deletions;
        }
        for (int i = 0; i < n; i++) {
            if (num.charAt(i) == '0') {
                answer = Math.min(answer, n - 1);
                break;
            }
        }
        return answer;
    }
}

