        up[0][0] = 0;
        depth[0] = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            for (int[] nb : adj[node]) {
                int to = nb[0];
                int w = nb[1];
                if (!visited[to]) {
                    visited[to] = true;
                    depth[to] = depth[node] + 1;
                    up[0][to] = node;
                    System.arraycopy(pref[node], 0, pref[to], 0, 27);
                    pref[to][w]++; // add edge weight
                    stack.push(to);
                }
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 0; v < n; v++) {
                up[k][v] = up[k - 1][up[k - 1][v]];
            }
        }

        int m = queries.length;
        int[] ans = new int[m];
        for (int i = 0; i < m; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            int l = lca(a, b, depth, up, LOG);
            int pathLen = depth[a] + depth[b] - 2 * depth[l];
            if (pathLen == 0) {
                ans[i] = 0;
                continue;
            }
            int maxCnt = 0;
            for (int w = 1; w <= 26; w++) {
                int cnt = pref[a][w] + pref[b][w] - 2 * pref[l][w];
                if (cnt > maxCnt) maxCnt = cnt;
            }
            ans[i] = pathLen - maxCnt;
        }
        return ans;
    }

    private static int lca(int a, int b, int[] depth, int[][] up, int LOG) {
        if (depth[a] < depth[b]) {
            int tmp = a; a = b; b = tmp;
        }
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; k++) {
            if ((diff & (1 << k)) != 0) {
                a = up[k][a];
            }
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    }
}

