public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long a, long e) {
        long res = 1L;
        a %= MOD;
        while (e > 0) {
            if ((e & 1L) == 1L) {
                res = (res * a) % MOD;
            }
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    public static int countKSubsequences(String s, int k) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
        }

        List<Integer> list = new ArrayList<>();
        for (int f : freq) {
            if (f > 0) list.add(f);
        }

        if (k > list.size()) return 0;

        Collections.sort(list, Collections.reverseOrder());

        int threshold = list.get(k - 1);
        int cntGreater = 0;
        int cntEqual = 0;
        long productGreater = 1L;
        for (int f : list) {
            if (f > threshold) {
                cntGreater++;
                productGreater = (productGreater * f) % MOD;
            } else if (f == threshold) {
                cntEqual++;
            }
        }

        int need = k - cntGreater; // need <= cntEqual

        long powThreshold = modPow(threshold, need);

        int maxN = 26;
        long[] fact = new long[maxN + 1];
        long[] invFact = new long[maxN + 1];
        fact[0] = 1L;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[maxN] = modPow(fact[maxN], MOD - 2);
        for (int i = maxN - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        long comb = fact[cntEqual] * invFact[need] % MOD * invFact[cntEqual - need] % MOD;
        long ans = productGreater * powThreshold % MOD * comb % MOD;
        return (int) ans;
    }
}

