public class Solution {
    public int minimumMoves(int[][] grid) {
        List<int[]> stones = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int cnt = grid[i][j];
                for (int k = 0; k < cnt; k++) {
                    stones.add(new int[]{i, j});
                }
            }
        }
        int n = stones.size(); // should be 9
        int[][] cost = new int[n][n];
        for (int i = 0; i < n; i++) {
            int[] s = stones.get(i);
            for (int j = 0; j < n; j++) {
                int ti = j / 3;
                int tj = j % 3;
                cost[i][j] = Math.abs(s[0] - ti) + Math.abs(s[1] - tj);
            }
        }
        int size = 1 << n;
        int INF = 1_000_000;
        int[] dp = new int[size];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 0; mask < size; mask++) {
            int i = Integer.bitCount(mask);
            if (i >= n) continue;
            int cur = dp[mask];
            if (cur == INF) continue;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) == 0) {
                    int newMask = mask | (1 << j);
                    int newCost = cur + cost[i][j];
                    if (newCost < dp[newMask]) {
                        dp[newMask] = newCost;
                    }
                }
            }
        }
        return dp[size - 1];
    }
}

class Solution {
    static final long MOD = 1_000_000_007L;

    private int[] zFunction(String s) {
        int n = s.length();
        int[] z = new int[n];
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    }

    private int countGood(String s, String t) {
        int n = s.length();
        String combined = t + "#" + s + s;
        int[] z = zFunction(combined);
        int base = n + 1;
        int cnt = 0;
        for (int d = 0; d < n; d++) if (z[base + d] >= n) cnt++;
        return cnt;
    }

    private long[][] matmul(long[][] a, long[][] b) {
        long[][] r = new long[2][2];
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                r[i][j] = (a[i][0]*b[0][j] + a[i][1]*b[1][j]) % MOD;
        return r;
    }

    private long[][] matpow(long[][] m, long p) {
        long[][] r = {{1,0},{0,1}};
        while (p > 0) {
            if ((p & 1) == 1) r = matmul(r, m);
            m = matmul(m, m);
            p >>= 1;
        }
        return r;
    }

    public int numberOfWays(String s, String t, long k) {
        int n = s.length();
        int c = countGood(s, t);
        long g0 = s.equals(t) ? 1 : 0;
        long b0 = 1 - g0;
        long[][] m = {{(c-1+MOD)%MOD, c%MOD}, {(n-c+MOD)%MOD, (n-c-1+MOD)%MOD}};
        long[][] mp = matpow(m, k);
        long ans = (mp[0][0]*g0 + mp[0][1]*b0) % MOD;
        return (int) ans;
    }
}

