public class Solution {
    public static int minRightShifts(int[] nums) {
        int n = nums.length;
        int breakIdx = -1;
        for (int i = 0; i < n; i++) {
            int next = (i + 1) % n;
            if (nums[i] > nums[next]) {
                if (breakIdx != -1) {
                    return -1;
                }
                breakIdx = i;
            }
        }
        if (breakIdx == -1) {
            return 0;
        }
        return (n - (breakIdx + 1)) % n;
    }
}

