class Solution {
    public long countInterestingSubarrays(int[] nums, int modulo, int k) {
        Map<Integer, Long> freq = new HashMap<>();
        freq.put(0, 1L);
        long ans = 0;
        long prefix = 0;
        for (int num : nums) {
            if (num % modulo == k) {
                prefix++;
            }
            int need = (int) ((prefix - k) % modulo);
            if (need < 0) {
                need += modulo;
            }
            ans += freq.getOrDefault(need, 0L);
            int rem = (int) (prefix % modulo);
            freq.put(rem, freq.getOrDefault(rem, 0L) + 1);
        }
        return ans;
    }
}

