class Solution {
    public static int minLengthAfterRemovals(int[] nums) {
        int n = nums.length;
        int maxFreq = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums[j] == nums[i]) {
                j++;
            }
            int freq = j - i;
            if (freq > maxFreq) {
                maxFreq = freq;
            }
            i = j;
        }
        int remaining = n - maxFreq;
        if (maxFreq > remaining) {
            return maxFreq - remaining;
        } else {
            return n % 2;
        }
    }
}

