public class Solution {
    public long maxCompleteSubsetSum(int[] nums) {
        int n = nums.length;
        Map<Integer, Long> sumMap = new HashMap<>();
        for (int idx = 1; idx <= n; ++idx) {
            int core = squareFreePart(idx);
            sumMap.put(core, sumMap.getOrDefault(core, 0L) + nums[idx - 1]);
        }
        long ans = 0;
        for (long v : sumMap.values()) {
            if (v > ans) ans = v;
        }
        return ans;
    }

    private int squareFreePart(int x) {
        int core = 1;
        int num = x;
        for (int p = 2; p * p <= num; ++p) {
            if (num % p == 0) {
                int parity = 0;
                while (num % p == 0) {
                    num /= p;
                    parity ^= 1;
                }
                if (parity == 1) core *= p;
            }
        }
        if (num > 1) core *= num;
        return core;
    }
}

