public class Solution {
    public long maxNumberOfAlloys(int n, int k, long budget, int[][] composition, long[] stock, long[] cost) {
        long low = 0;
        long high = 2_000_000_000L; // sufficient upper bound
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            if (canProduce(mid, n, k, budget, composition, stock, cost)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private boolean canProduce(long target, int n, int k, long budget, int[][] composition, long[] stock, long[] cost) {
        for (int i = 0; i < k; i++) {
            long totalCost = 0;
            for (int j = 0; j < n; j++) {
                long required = target * composition[i][j];
                if (required > stock[j]) {
                    long need = required - stock[j];
                    totalCost += need * cost[j];
                    if (totalCost > budget) {
                        break;
                    }
                }
            }
            if (totalCost <= budget) {
                return true;
            }
        }
        return false;
    }
}

