public class Solution {
    public long maximumSum(int[] maxHeights) {
        int n = maxHeights.length;
        long[] left = new long[n];
        long[] right = new long[n];
        long[] stackVal = new long[n];
        long[] stackCnt = new long[n];
        int top = -1;
        long sum = 0;
        for (int i = 0; i < n; i++) {
            long cnt = 1;
            while (top >= 0 && stackVal[top] > maxHeights[i]) {
                cnt += stackCnt[top];
                sum -= stackVal[top] * stackCnt[top];
                top--;
            }
            top++;
            stackVal[top] = maxHeights[i];
            stackCnt[top] = cnt;
            sum += maxHeights[i] * cnt;
            left[i] = sum;
        }
        top = -1;
        sum = 0;
        for (int i = n - 1; i >= 0; i--) {
            long cnt = 1;
            while (top >= 0 && stackVal[top] > maxHeights[i]) {
                cnt += stackCnt[top];
                sum -= stackVal[top] * stackCnt[top];
                top--;
            }
            top++;
            stackVal[top] = maxHeights[i];
            stackCnt[top] = cnt;
            sum += maxHeights[i] * cnt;
            right[i] = sum;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long total = left[i] + right[i] - maxHeights[i];
            if (total > ans) ans = total;
        }
        return ans;
    }
}

