public class Solution {
    public long beautifulTowers(int[] heights) {
        int n = heights.length;
        long[] leftSum = new long[n];
        long[] rightSum = new long[n];

        for (int i = 0; i < n; i++) {
            long cur = heights[i];
            long sum = cur;
            for (int j = i - 1; j >= 0; j--) {
                cur = Math.min(heights[j], cur);
                sum += cur;
            }
            leftSum[i] = sum;
        }

        for (int i = n - 1; i >= 0; i--) {
            long cur = heights[i];
            long sum = cur;
            for (int j = i + 1; j < n; j++) {
                cur = Math.min(heights[j], cur);
                sum += cur;
            }
            rightSum[i] = sum;
        }

        long best = 0;
        for (int i = 0; i < n; i++) {
            long total = leftSum[i] + rightSum[i] - heights[i];
            if (total > best) {
                best = total;
            }
        }
        return best;
    }
}

import java.util.ArrayList;
import java.util.Arrays;

class Solution {
    public static long countValidPaths(int n, int[][] edges) {
        boolean[] isPrime = new boolean[n + 1];
        if (n >= 2) {
            Arrays.fill(isPrime, 2, n + 1, true);
            for (int i = 2; i * i <= n; i++) {
                if (isPrime[i]) {
                    for (int j = i * i; j <= n; j += i) {
                        isPrime[j] = false;
                    }
                }
            }
        }

        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] compId = new int[n + 1];
        int[] compSize = new int[n + 1];
        int compCnt = 0;
        int[] stack = new int[n];
        int top;
        for (int i = 1; i <= n; i++) {
            if (isPrime[i] || compId[i] != 0) continue;
            compCnt++;
            int size = 0;
            top = 0;
            stack[top++] = i;
            compId[i] = compCnt;
            while (top > 0) {
                int node = stack[--top];
                size++;
                for (int nb : adj[node]) {
                    if (!isPrime[nb] && compId[nb] == 0) {
                        compId[nb] = compCnt;
                        stack[top++] = nb;
                    }
                }
            }
            compSize[compCnt] = size;
        }

        long answer = 0;
        for (int p = 1; p <= n; p++) {
            if (!isPrime[p]) continue;
            long total = 0;
            long sumSq = 0;
            for (int nb : adj[p]) {
                if (isPrime[nb]) continue;
                int sz = compSize[compId[nb]];
                total += sz;
                sumSq += (long) sz * sz;
            }
            if (total == 0) continue;
            long contribution = total + (total * total - sumSq) / 2;
            answer += contribution;
        }
        return answer;
    }
}

