class Solution {
    private static class Result {
        int modSum;
        int compCnt;
        Result(int modSum, int compCnt) {
            this.modSum = modSum;
            this.compCnt = compCnt;
        }
    }

    public static int maxKDivisibleComponents(int n, int[][] edges, int[] values, int k) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }
        Result root = dfs(0, -1, adj, values, k);
        return root.compCnt + (root.modSum == 0 ? 1 : 0);
    }

    private static Result dfs(int u, int parent, List<Integer>[] adj, int[] values, int k) {
        int sumMod = values[u] % k;
        int comps = 0;
        for (int v : adj[u]) {
            if (v == parent) continue;
            Result child = dfs(v, u, adj, values, k);
            if (child.modSum == 0) {
                comps += child.compCnt + 1;
            } else {
                comps += child.compCnt;
                sumMod = (sumMod + child.modSum) % k;
            }
        }
        return new Result(sumMod, comps);
    }
}

