class Solution {
    public long maxTripletValue(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0L;
        long answer = 0L;
        int maxPrefix = nums[0];
        long bestDiff = Long.MIN_VALUE;
        for (int k = 2; k < n; k++) {
            int j = k - 1;
            long diff = (long) maxPrefix - nums[j];
            if (diff > bestDiff) {
                bestDiff = diff;
            }
            if (nums[j] > maxPrefix) {
                maxPrefix = nums[j];
            }
            long candidate = bestDiff * nums[k];
            if (candidate > answer) {
                answer = candidate;
            }
        }
        return answer;
    }
}

public class Solution {
    public static int minOperations(int[] nums, int k) {
        int missing = k;
        boolean[] seen = new boolean[k + 1];
        int ops = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            ops++;
            int v = nums[i];
            if (v <= k && !seen[v]) {
                seen[v] = true;
                missing--;
            }
            if (missing == 0) {
                break;
            }
        }
        return ops;
    }
}

