class Solution {
    public long maxValue(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0L;
        int[] suffixMax = new int[n];
        suffixMax[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixMax[i] = Math.max(nums[i], suffixMax[i + 1]);
        }
        long ans = 0L;
        int maxLeft = nums[0];
        for (int j = 1; j <= n - 2; j++) {
            int maxRight = suffixMax[j + 1];
            int diff = maxLeft - nums[j];
            if (diff > 0) {
                long candidate = (long) diff * (long) maxRight;
                if (candidate > ans) ans = candidate;
            }
            if (nums[j] > maxLeft) maxLeft = nums[j];
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int[] countVisitedNodes(int[] edges) {
        int n = edges.length;
        int[] answer = new int[n];
        int[] state = new int[n]; // 0 = unvisited, 1 = visiting, 2 = processed
        for (int i = 0; i < n; i++) {
            if (state[i] == 0) {
                dfs(i, edges, answer, state);
            }
        }
        return answer;
    }

    private static int dfs(int u, int[] edges, int[] answer, int[] state) {
        if (state[u] == 2) {
            return answer[u];
        }
        if (state[u] == 1) {
            int cur = u;
            int size = 0;
            do {
                size++;
                cur = edges[cur];
            } while (cur != u);
            cur = u;
            do {
                answer[cur] = size;
                state[cur] = 2;
                cur = edges[cur];
            } while (cur != u);
            return answer[u];
        }
        state[u] = 1;
        int v = edges[u];
        if (v == -1) {
            answer[u] = 1;
            state[u] = 2;
            return answer[u];
        }
        int childAns = dfs(v, edges, answer, state);
        if (state[u] != 2) {
            answer[u] = childAns + 1;
            state[u] = 2;
        }
        return answer[u];
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int minimumSizeSubarrayInInfiniteArray(int[] nums, int target) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        prefix[0] = 0;
        Map<Long, Integer> map = new HashMap<>();
        map.put(0L, 0);
        for (int i = 1; i <= n; i++) {
            prefix[i] = prefix[i - 1] + nums[i - 1];
            map.put(prefix[i], i);
        }
        long totalSum = prefix[n];
        long answer = Long.MAX_VALUE;
        for (int s = 0; s < n; s++) {
            long startPref = prefix[s];
            long sumToEnd = totalSum - startPref;
            if (target == sumToEnd) {
                answer = Math.min(answer, (long) (n - s));
                continue;
            }
            if (target < sumToEnd) {
                long needed = target + startPref;
                Integer e = map.get(needed);
                if (e != null && e > s) {
                    answer = Math.min(answer, (long) (e - s));
                }
                continue;
            }
            long remaining = target - sumToEnd;
            long cycles = remaining / totalSum;
            long leftover = remaining - cycles * totalSum;
            if (leftover == 0) {
                long len = (n - s) + cycles * n;
                answer = Math.min(answer, len);
            } else {
                Integer p = map.get(leftover);
                if (p != null) {
                    long len = (n - s) + cycles * n + p;
                    answer = Math.min(answer, len);
                }
            }
        }
        return answer == Long.MAX_VALUE ? -1 : (int) answer;
    }
}

