class Solution {
    public static int[] minimumEdgeReversals(int n, int[][] edges) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            adj[u].add(new int[]{v, 0});
            adj[v].add(new int[]{u, 1});
        }

        int[] answer = new int[n];
        int rootReversals = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, -1});
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int parent = cur[1];
            for (int[] edge : adj[node]) {
                int nei = edge[0];
                int cost = edge[1];
                if (nei == parent) continue;
                rootReversals += cost;
                stack.push(new int[]{nei, node});
            }
        }
        answer[0] = rootReversals;

        Deque<int[]> stack2 = new ArrayDeque<>();
        stack2.push(new int[]{0, -1});
        while (!stack2.isEmpty()) {
            int[] cur = stack2.pop();
            int node = cur[0];
            int parent = cur[1];
            for (int[] edge : adj[node]) {
                int nei = edge[0];
                int cost = edge[1];
                if (nei == parent) continue;
                answer[nei] = answer[node] + (cost == 0 ? 1 : -1);
                stack2.push(new int[]{nei, node});
            }
        }

        return answer;
    }
}

