class Solution {
    public static int minCost(String s1, String s2, int x) {
        int n = s1.length();
        List<Integer> diff = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                diff.add(i);
            }
        }
        int m = diff.size();
        if (m % 2 == 1) {
            return -1;
        }
        int[] dp = new int[m + 1];
        dp[0] = 0;
        if (m >= 1) {
            dp[1] = 1;
        }
        for (int i = 2; i <= m; i++) {
            int costSingle = dp[i - 1] + 1;
            int idxPrev = diff.get(i - 2);
            int idxCurr = diff.get(i - 1);
            int pairCost = (idxCurr == idxPrev + 1) ? Math.min(x, 2) : x;
            int costPair = dp[i - 2] + pairCost;
            dp[i] = Math.min(costSingle, costPair);
        }
        return dp[m];
    }
}

