class Solution {
    public static long maxSumOfSquares(int[] nums, int k) {
        final long MOD = 1000000007L;
        int[] bitCounts = new int[31];
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            for (int b = 0; b < 31; b++) {
                if ((x & (1 << b)) != 0) {
                    bitCounts[b]++;
                }
            }
        }
        long[] arr = new long[k];
        for (int b = 30; b >= 0; b--) {
            int cnt = bitCounts[b];
            int add = 1 << b;
            int limit = cnt < k ? cnt : k;
            for (int i = 0; i < limit; i++) {
                arr[i] += add;
            }
        }
        long ans = 0;
        for (int i = 0; i < k; i++) {
            long v = arr[i];
            ans = (ans + (v * v) % MOD) % MOD;
        }
        return ans;
    }
}

