class Solution {
    public static String shortestBeautifulSubstring(String s, int k) {
        int n = s.length();
        int left = 0, ones = 0;
        int minLen = Integer.MAX_VALUE;

        for (int right = 0; right < n; right++) {
            if (s.charAt(right) == '1') ones++;

            while (ones > k) {
                if (s.charAt(left) == '1') ones--;
                left++;
            }

            while (ones == k && left < n && s.charAt(left) == '0') {
                left++;
            }

            if (ones == k) {
                int curLen = right - left + 1;
                if (curLen < minLen) minLen = curLen;
            }
        }

        if (minLen == Integer.MAX_VALUE) return "";

        String best = "";
        int countOnes = 0;

        for (int i = 0; i < minLen; i++) {
            if (s.charAt(i) == '1') countOnes++;
        }
        if (countOnes == k) best = s.substring(0, minLen);

        for (int start = 1; start + minLen <= n; start++) {
            if (s.charAt(start - 1) == '1') countOnes--;
            if (s.charAt(start + minLen - 1) == '1') countOnes++;

            if (countOnes == k) {
                String sub = s.substring(start, start + minLen);
                if (best.isEmpty() || sub.compareTo(best) < 0) best = sub;
            }
        }

        return best;
    }
}

