public class Solution {
    public static String[] longestSubsequence(String[] words, int[] groups) {
        int n = words.length;
        @SuppressWarnings("unchecked")
        List<String>[] best = new List[n];
        List<String> overall = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<String> cur = new ArrayList<>();
            cur.add(words[i]);
            for (int j = 0; j < i; j++) {
                if (groups[j] != groups[i]) {
                    List<String> candidate = new ArrayList<>(best[j]);
                    candidate.add(words[i]);
                    cur = better(cur, candidate);
                }
            }
            best[i] = cur;
            overall = better(overall, cur);
        }
        return overall.toArray(new String[0]);
    }

    private static List<String> better(List<String> a, List<String> b) {
        if (a.isEmpty()) return b;
        if (b.isEmpty()) return a;
        if (a.size() != b.size()) {
            return a.size() > b.size() ? a : b;
        }
        for (int i = 0; i < a.size(); i++) {
            int cmp = a.get(i).compareTo(b.get(i));
            if (cmp != 0) {
                return cmp < 0 ? a : b;
            }
        }
        return a;
    }
}

