class Solution {
    public int minimumSum(int[] nums) {
        int n = nums.length;
        int ans = Integer.MAX_VALUE;
        for (int j = 1; j < n - 1; j++) {
            int left = Integer.MAX_VALUE;
            for (int i = 0; i < j; i++) {
                if (nums[i] < nums[j] && nums[i] < left) {
                    left = nums[i];
                }
            }
            int right = Integer.MAX_VALUE;
            for (int k = j + 1; k < n; k++) {
                if (nums[k] < nums[j] && nums[k] < right) {
                    right = nums[k];
                }
            }
            if (left != Integer.MAX_VALUE && right != Integer.MAX_VALUE) {
                ans = Math.min(ans, left + nums[j] + right);
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

class Solution {
    public static int[][] constructProductMatrix(int[][] grid) {
        final int MOD = 12345;
        int n = grid.length, m = grid[0].length;
        int total = n*m;
        long[] flat = new long[total];
        int idx=0;
        for (int i=0;i<n;i++) for (int j=0;j<m;j++) flat[idx++] = grid[i][j];
        long[] prefix = new long[total];
        long[] suffix = new long[total];
        prefix[0]=1;
        for (int i=1;i<total;i++) prefix[i] = (prefix[i-1]*flat[i-1])%MOD;
        suffix[total-1]=1;
        for (int i=total-2;i>=0;i--) suffix[i]=(suffix[i+1]*flat[i+1])%MOD;
        int[][] result = new int[n][m];
        idx=0;
        for (int i=0;i<n;i++) for (int j=0;j<m;j++) { result[i][j] = (int)((prefix[idx]*suffix[idx])%MOD); idx++; }
        return result;
    }
}

