class Solution {
    public static int minChanges(String s, int k) {
        int n = s.length();
        if (k >= n) return 0;
        int[][] cost = new int[n][n];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i + len <= n; ++i) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    cost[i][j] = (len == 2) ? 0 : cost[i + 1][j - 1];
                } else {
                    cost[i][j] = (len == 2) ? 1 : cost[i + 1][j - 1] + 1;
                }
            }
        }
        int INF = 1_000_000_000;
        int[][] dp = new int[k + 1][n + 1];
        for (int i = 0; i <= k; ++i) {
            Arrays.fill(dp[i], INF);
        }
        dp[0][0] = 0;
        for (int p = 1; p <= k; ++p) {
            for (int i = 1; i <= n; ++i) {
                for (int t = p - 1; t < i; ++t) {
                    int prev = dp[p - 1][t];
                    if (prev == INF) continue;
                    int cur = prev + cost[t][i - 1];
                    if (cur < dp[p][i]) dp[p][i] = cur;
                }
            }
        }
        return dp[k][n];
    }
}

