class Solution {
    private static int[][][][][] memo;

    public static int longestString(int x, int y, int z) {
        memo = new int[51][51][51][3][3];
        for (int i = 0; i < 51; i++) {
            for (int j = 0; j < 51; j++) {
                for (int k = 0; k < 51; k++) {
                    for (int l = 0; l < 3; l++) {
                        Arrays.fill(memo[i][j][k][l], -1);
                    }
                }
            }
        }
        int maxPieces = dfs(x, y, z, 0, 0);
        return maxPieces * 2;
    }

    private static int dfs(int a, int b, int c, int last, int run) {
        int cached = memo[a][b][c][last][run];
        if (cached != -1) return cached;
        int best = 0;

        if (a > 0) {
            int[] ns = apply(last, run, 'A', 'A');
            if (ns != null) {
                best = Math.max(best, 1 + dfs(a - 1, b, c, ns[0], ns[1]));
            }
        }
        if (b > 0) {
            int[] ns = apply(last, run, 'B', 'B');
            if (ns != null) {
                best = Math.max(best, 1 + dfs(a, b - 1, c, ns[0], ns[1]));
            }
        }
        if (c > 0) {
            int[] ns = apply(last, run, 'A', 'B');
            if (ns != null) {
                best = Math.max(best, 1 + dfs(a, b, c - 1, ns[0], ns[1]));
            }
        }

        memo[a][b][c][last][run] = best;
        return best;
    }

    private static int[] apply(int last, int run, char first, char second) {
        int curLast = last;
        int curRun = run;

        // process first character
        int idx1 = (first == 'A') ? 1 : 2;
        if (curLast == 0) {
            curLast = idx1;
            curRun = 1;
        } else if (curLast == idx1) {
            if (curRun == 2) return null;
            curRun++;
        } else {
            curLast = idx1;
            curRun = 1;
        }

        // process second character
        int idx2 = (second == 'A') ? 1 : 2;
        if (curLast == idx2) {
            if (curRun == 2) return null;
            curRun++;
        } else {
            curLast = idx2;
            curRun = 1;
        }

        return new int[]{curLast, curRun};
    }
}

