class Solution {
    public static int[] findGoodSubset(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[] result = new int[0];
        for (int mask = 1; mask < (1 << m); mask++) {
            ArrayList<Integer> subset = new ArrayList<>();
            int subsetSize = 0;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) {
                    subset.add(i);
