                    sum += grid[subset.get(idx)][j];
                }
                if (sum > subsetSize / 2) {
                    isGood = false;
                    break;
                }
            }
            if (isGood && (result.length == 0 || subsetSize > result.length)) {
                result = new int[subsetSize];
                for (int k = 0; k < subsetSize; k++) {
                    result[k] = subset.get(k);
                }
            }
        }
        return result;
    }
}

