class Solution {
    public static int countBeautifulPairs(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            int first = firstDigit(nums[i]);
            for (int j = i + 1; j < nums.length; j++) {
                int last = nums[j] % 10;
                if (gcd(first, last) == 1) {
                    count++;
                }
            }
        }
        return count;
    }

    private static int firstDigit(int num) {
        num = Math.abs(num);
        while (num >= 10) {
            num /= 10;
        }
        return num;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

import java.util.*;

class Solution {
    static class Robot {
        int position;
        int health;
        boolean direction; // true for 'R', false for 'L'
        Robot(int position, int health, boolean direction) {
            this.position = position;
            this.health = health;
            this.direction = direction;
        }
    }

    public static int[] robotCollisions(int[] positions, int[] healths, char[] directions) {
        int n = positions.length;
        List<Robot> robots = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            robots.add(new Robot(positions[i], healths[i], directions[i] == 'R'));
        }
        robots.sort(Comparator.comparingInt(r -> r.position));
        List<Robot> stack = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Robot cur = robots.get(i);
            if (stack.isEmpty() || cur.direction) {
                stack.add(cur);
            } else {
                // FIX 1: collide while the stack top is moving RIGHT (toward us), not left.
                while (!stack.isEmpty() && stack.get(stack.size() - 1).direction) {
                    Robot topRobot = stack.remove(stack.size() - 1);
                    if (cur.health > topRobot.health) {
                        cur.health -= 1;
                    } else if (cur.health < topRobot.health) {
                        cur = topRobot;
                        cur.health -= 1; // FIX 2: surviving top still pays the 1-health collision cost
                    } else {
                        cur = null;
                        break;
                    }
                }
                if (cur != null) {
                    stack.add(cur);
                }
            }
        }
        Map<Integer, Integer> healthMap = new HashMap<>();
        for (Robot r : stack) healthMap.put(r.position, r.health);
        // FIX 3: destroyed robots are omitted entirely, not zero-padded.
        List<Integer> resultList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (healthMap.containsKey(positions[i])) resultList.add(healthMap.get(positions[i]));
        }
        int[] result = new int[resultList.size()];
        for (int i = 0; i < result.length; i++) result[i] = resultList.get(i);
        return result;
    }
}

