import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int longestSubsequenceSum(int[] nums, int target) {
        Map<Integer, Integer> dp = new HashMap<>();
        for (int num : nums) {
            Map<Integer, Integer> newDp = new HashMap<>(dp);
            if (!newDp.containsKey(num) || newDp.get(num) < 1) {
                newDp.put(num, 1);
            }
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int sum = entry.getKey();
                int len = entry.getValue();
                int newSum = sum + num;
                int newLen = len + 1;
                if (!newDp.containsKey(newSum) || newDp.get(newSum) < newLen) {
                    newDp.put(newSum, newLen);
                }
            }
            dp = newDp;
        }
        return dp.containsKey(target) ? dp.get(target) : -1;
    }
}

public class Solution {
    public static int findKOr(int[] nums, int k) {
        int result = 0;
        for (int bit = 0; bit < 32; bit++) {
            int count = 0;
            for (int i = 0; i < nums.length; i++) {
                if (((nums[i] >> bit) & 1) == 1) {
                    count++;
                    if (count >= k) break;
                }
            }
            if (count >= k) {
                result |= (1 << bit);
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int countSubMultisets(int[] nums, int l, int r) {
        final int MOD = 1_000_000_007;
        int totalSum = 0;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
            totalSum += v;
        }
        int zeroCount = freq.getOrDefault(0, 0);
        freq.remove(0);
        int maxSum = totalSum;
        int[] dp = new int[maxSum + 1];
        dp[0] = 1;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int val = entry.getKey();
            int cnt = entry.getValue();
            int[] prev = dp.clone();
            Arrays.fill(dp, 0);
            for (int rem = 0; rem < val; ++rem) {
                Deque<Integer> deque = new ArrayDeque<>();
                long windowSum = 0;
                for (int sum = rem, k = 0; sum <= maxSum; sum += val, ++k) {
                    int cur = prev[sum];
                    windowSum += cur;
                    if (windowSum >= MOD) windowSum -= MOD;
                    deque.addLast(cur);
                    if (deque.size() > cnt + 1) {
                        int removed = deque.removeFirst();
                        windowSum -= removed;
                        if (windowSum < 0) windowSum += MOD;
                    }
                    dp[sum] = (int) windowSum;
                }
            }
        }
        int factor = zeroCount + 1;
        if (factor != 1) {
            long f = factor;
            for (int i = 0; i <= maxSum; ++i) {
                dp[i] = (int) (dp[i] * f % MOD);
            }
        }
        long ans = 0;
        for (int s = l; s <= r && s <= maxSum; ++s) {
            ans += dp[s];
            if (ans >= MOD) ans -= MOD;
        }
        return (int) ans;
    }
}

