class Solution {
    public static int[] findIndices(int[] nums, int indexDifference, int valueDifference) {
        if (indexDifference <= 0 && valueDifference <= 0) {
            return new int[]{0, 0};
        }
        int maxVal = Integer.MIN_VALUE;
        int maxIdx = -1;
        int minVal = Integer.MAX_VALUE;
        int minIdx = -1;
        for (int i = 0; i < nums.length; i++) {
            int addIdx = i - indexDifference;
            if (addIdx >= 0) {
                int v = nums[addIdx];
                if (v > maxVal) {
                    maxVal = v;
                    maxIdx = addIdx;
                }
                if (v < minVal) {
                    minVal = v;
                    minIdx = addIdx;
                }
            }
            if (maxIdx != -1 && Math.abs(nums[i] - maxVal) >= valueDifference) {
                return new int[]{maxIdx, i};
            }
            if (minIdx != -1 && Math.abs(nums[i] - minVal) >= valueDifference) {
                return new int[]{minIdx, i};
            }
        }
        return new int[]{-1, -1};
    }
}

