class Solution {
    public int minNumberOfGroups(int[] balls) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int v : balls) {
            map.put(v, map.getOrDefault(v, 0) + 1);
        }
        int[] freq = new int[map.size()];
        int idx = 0;
        int minFreq = Integer.MAX_VALUE;
        for (int f : map.values()) {
            freq[idx++] = f;
            if (f < minFreq) minFreq = f;
        }

        int lo = 1, hi = minFreq;
        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            if (feasible(freq, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        int s = lo;
        int groups = 0;
        for (int f : freq) {
            groups += (f + s) / (s + 1); // ceil(f / (s+1))
        }
        return groups;
    }

    private boolean feasible(int[] freq, int s) {
        for (int f : freq) {
            int minGroups = (f + s) / (s + 1); // ceil(f / (s+1))
            int maxGroups = f / s; // floor(f / s)
            if (minGroups > maxGroups) return false;
        }
        return true;
    }
}

