class Solution {
    public static int makeArrayBeautiful(int[] nums, int k) {
        int operations = 0;
        for (int i = 0; i < nums.length - 2; i++) {
            int max = Math.max(nums[i], Math.max(nums[i + 1], nums[i + 2]));
            if (max < k) {
                int diff = k - max;
                operations += diff;
                if (nums[i] == max) {
                    nums[i] += diff;
                } else if (nums[i + 1] == max) {
                    nums[i + 1] += diff;
                } else {
                    nums[i + 2] += diff;
                }
            }
        }
        return operations;
    }
}

