class Solution {
    public static int minimumSum(int[] nums1, int[] nums2) {
        long sum1 = 0, sum2 = 0;
        long zeros1 = 0, zeros2 = 0;
        for (int v : nums1) {
            if (v == 0) zeros1++;
            else sum1 += v;
        }
        for (int v : nums2) {
            if (v == 0) zeros2++;
            else sum2 += v;
        }
        long minSum1 = sum1 + zeros1;
        long minSum2 = sum2 + zeros2;
        if (minSum1 == minSum2) {
            return (int) minSum1;
        }
        long target = Math.max(minSum1, minSum2);
        if (minSum1 < minSum2) {
            return zeros1 == 0 ? -1 : (int) target;
        } else {
            return zeros2 == 0 ? -1 : (int) target;
        }
    }
}

class Solution {
    private List<Integer>[] adj;
    private int[] values;
    public long maximumScoreAfterOperations(int[][] edges, int[] vals) {
        int n = vals.length;
        values = vals;
        adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) { adj[e[0]].add(e[1]); adj[e[1]].add(e[0]); }
        long total = 0;
        for (int v : vals) total += v;
        long kept = f(0, -1);
        return total - kept;
    }
    // Minimum sum of nodes we must leave un-zeroed in this subtree, assuming
    // no ancestor above `node` is already left un-zeroed (so this subtree alone
    // must guarantee every leaf-path underneath keeps at least one nonzero node).
    private long f(int node, int parent) {
        boolean isLeaf = true;
        long childSum = 0;
        for (int c : adj[node]) {
            if (c == parent) continue;
            isLeaf = false;
            childSum += f(c, node);
        }
        if (isLeaf) return values[node];
        return Math.min(values[node], childSum);
    }
}

