class Solution {
    public static int maxPoints(int[][] edges, int[] coins, int k) {
        int n = coins.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        return dfs(0, -1, adj, coins, k);
    }

    private static int dfs(int node, int parent, List<Integer>[] adj, int[] coins, int k) {
        int sumChildren = 0;
        for (int nxt : adj[node]) {
            if (nxt != parent) {
                sumChildren += dfs(nxt, node, adj, coins, k);
            }
        }
        int takeFull = coins[node] - k + sumChildren;
        int takeHalf = coins[node] / 2;
        return Math.max(takeFull, takeHalf);
    }
}

