class Solution {
    private static final int MOD = 1_000_000_007;

    public static int stringCount(int n) {
        long[] pow26 = new long[n + 1];
        long[] pow25 = new long[n + 1];
        long[] pow24 = new long[n + 1];
        long[] pow23 = new long[n + 1];

        pow26[0] = pow25[0] = pow24[0] = pow23[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow26[i] = (pow26[i - 1] * 26) % MOD;
            pow25[i] = (pow25[i - 1] * 25) % MOD;
            pow24[i] = (pow24[i - 1] * 24) % MOD;
            pow23[i] = (pow23[i - 1] * 23) % MOD;
        }

        long total = pow26[n];

        long noL = pow25[n];
        long noT = pow25[n];
        long insufficientE = (pow25[n] + (long) n * pow25[Math.max(0, n - 1)]) % MOD;

        long noLnoT = pow24[n];
        long noLinsufficientE = (pow24[n] + (long) n * pow24[Math.max(0, n - 1)]) % MOD;
        long noTinsufficientE = noLinsufficientE; // same value

        long allThree = (pow23[n] + (long) n * pow23[Math.max(0, n - 1)]) % MOD;

        long result = total;
        result = (result - ((noL + noT) % MOD) + MOD) % MOD;
        result = (result - insufficientE + MOD) % MOD;
        result = (result + noLnoT) % MOD;
        result = (result + noLinsufficientE) % MOD;
        result = (result + noTinsufficientE) % MOD;
        result = (result - allThree + MOD) % MOD;

        return (int) result;
    }
}

import java.util.PriorityQueue;

public class Solution {
    public static long maximumSpending(int[][] values) {
        int m = values.length;
        int n = values[0].length;
        int totalItems = m * n;
        long totalSpending = 0;
        int day = 1;
        PriorityQueue<Node> maxHeap = new PriorityQueue<>((a, b) -> Integer.compare(b.value, a.value));
        for (int i = 0; i < m; i++) {
            maxHeap.offer(new Node(values[i][0], i, 0));
        }
        while (!maxHeap.isEmpty()) {
            Node cur = maxHeap.poll();
            long multiplier = totalItems - day + 1L;
            totalSpending += cur.value * multiplier;
            day++;
            if (cur.item + 1 < n) {
                int nextItem = cur.item + 1;
                maxHeap.offer(new Node(values[cur.shop][nextItem], cur.shop, nextItem));
            }
        }
        return totalSpending;
    }

    private static class Node {
        int value;
        int shop;
        int item;

        Node(int value, int shop, int item) {
            this.value = value;
            this.shop = shop;
            this.item = item;
        }
    }
}

