class Solution {
    private static class Node {
        Node[] children = new Node[2];
        int cnt = 0;
    }

    public static int maximumStrongPairXor(int[] nums) {
        Arrays.sort(nums);
        final int MAX_BIT = 20;
        Node root = new Node();

        java.util.function.IntConsumer insert = (int val) -> {
            Node node = root;
            node.cnt++;
            for (int i = MAX_BIT; i >= 0; i--) {
                int bit = (val >> i) & 1;
                if (node.children[bit] == null) {
                    node.children[bit] = new Node();
                }
                node = node.children[bit];
                node.cnt++;
            }
        };

        java.util.function.IntConsumer remove = (int val) -> {
            Node node = root;
            node.cnt--;
            for (int i = MAX_BIT; i >= 0; i--) {
                int bit = (val >> i) & 1;
                node = node.children[bit];
                node.cnt--;
            }
        };

        java.util.function.IntFunction<Integer> query = (int val) -> {
            Node node = root;
            int xor = 0;
            for (int i = MAX_BIT; i >= 0; i--) {
                int bit = (val >> i) & 1;
                int toggled = bit ^ 1;
                if (node.children[toggled] != null && node.children[toggled].cnt > 0) {
                    xor |= (1 << i);
                    node = node.children[toggled];
                } else {
                    node = node.children[bit];
                }
            }
            return xor;
        };

        int ans = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            while (nums[right] > 2L * nums[left]) {
                remove.accept(nums[left]);
                left++;
            }
            insert.accept(nums[right]);
            int cur = query.apply(nums[right]);
            if (cur > ans) {
                ans = cur;
            }
        }
        return ans;
    }
}

public class Solution {
    public static int maximumStrongPairXor(int[] nums) {
        int maxXor = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int a = nums[i];
                int b = nums[j];
                int mx = a > b ? a : b;
                int mn = a > b ? b : a;
                if (mx <= 2 * mn) {
                    int xor = a ^ b;
                    if (xor > maxXor) {
                        maxXor = xor;
                    }
                }
            }
        }
        return maxXor;
    }
}

class Solution {
    public static long minCoins(int[] prices) {
        int n = prices.length;
        long[] dp = new long[n+1];
        java.util.Arrays.fill(dp, Long.MAX_VALUE/2);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int lo = (i+1)/2;
            for (int j = lo; j <= i; j++) {
                long cost = dp[j-1] + prices[j-1];
                if (cost < dp[i]) dp[i] = cost;
            }
        }
        return dp[n];
    }
}

public class Solution {
    public static long maximumXorProduct(long a, long b, int n) {
        long maxXorProduct = 0;
        long limit = 1L << n;
        for (long x = 0; x < limit; x++) {
            long aXorX = a ^ x;
            long bXorX = b ^ x;
            long product = aXorX * bXorX;
            maxXorProduct = Math.max(maxXorProduct, product);
        }
        return maxXorProduct;
    }
}

