class Solution {
    public static int countBeautifulSubstrings(String s, int k) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                int vowels = 0, consonants = 0;
                for (int p = i; p < j; p++) {
                    char c = s.charAt(p);
                    if ("aeiou".indexOf(c) >= 0) vowels++;
                    else consonants++;
                }
                if (vowels == consonants && (vowels * consonants) % k == 0) count++;
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public static int maxAreaOfSquareHole(int n, int m, int[] hBars, int[] vBars) {
        int[] h = new int[hBars.length + 2];
        h[0] = 0;
        System.arraycopy(hBars, 0, h, 1, hBars.length);
        h[h.length - 1] = n + 1;
        Arrays.sort(h);
        int maxH = 0;
        for (int i = 1; i < h.length; i++) {
            int gap = h[i] - h[i - 1];
            if (gap > maxH) maxH = gap;
        }

        int[] v = new int[vBars.length + 2];
        v[0] = 0;
        System.arraycopy(vBars, 0, v, 1, vBars.length);
        v[v.length - 1] = m + 1;
        Arrays.sort(v);
        int maxV = 0;
        for (int i = 1; i < v.length; i++) {
            int gap = v[i] - v[i - 1];
            if (gap > maxV) maxV = gap;
        }

        int side = Math.min(maxH, maxV);
        return side * side;
    }
}

import java.util.*;

class Solution {
    public static int[] findMeetingBuilding(int[] heights, int[][] queries) {
        SegmentTree st = new SegmentTree(heights);
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            int start = Math.max(a, b);
            int target = Math.max(heights[a], heights[b]);
            int idx = st.findFirst(start, target);
            result[i] = idx;
        }
        return result;
    }

    private static class SegmentTree {
        private final int n;
        private final int[] tree;

        SegmentTree(int[] arr) {
            n = arr.length;
            tree = new int[4 * n];
            build(1, 0, n - 1, arr);
        }

        private void build(int node, int l, int r, int[] arr) {
            if (l == r) {
                tree[node] = arr[l];
            } else {
                int mid = (l + r) >>> 1;
                build(node << 1, l, mid, arr);
                build(node << 1 | 1, mid + 1, r, arr);
                tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
            }
        }

        int findFirst(int start, int target) {
            return findFirst(1, 0, n - 1, start, target);
        }

        private int findFirst(int node, int l, int r, int start, int target) {
            if (r < start || tree[node] < target) {
                return -1;
            }
            if (l == r) {
                return l;
            }
            int mid = (l + r) >>> 1;
            int left = findFirst(node << 1, l, mid, start, target);
            if (left != -1) {
                return left;
            }
            return findFirst(node << 1 | 1, mid + 1, r, start, target);
        }
    }
}

