class Solution {
    public static int findMaximumLength(int[] nums) {
        long prevSum = Long.MIN_VALUE;
        long curSum = 0;
        int count = 0;
        for (int num : nums) {
            curSum += num;
            if (curSum >= prevSum) {
                count++;
                prevSum = curSum;
                curSum = 0;
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public static boolean isSimilarAfterCyclicShifts(int[][] mat, int k) {
        int[][] originalMat = new int[mat.length][];
        for (int i = 0; i < mat.length; i++) {
            originalMat[i] = mat[i].clone();
        }
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < mat.length; j++) {
                int[] row = mat[j];
                int len = row.length;
                if (len <= 1) continue;
                if (j % 2 == 0) {
                    int first = row[0];
                    for (int p = 0; p < len - 1; p++) {
                        row[p] = row[p + 1];
                    }
                    row[len - 1] = first;
                } else {
                    int last = row[len - 1];
                    for (int p = len - 1; p > 0; p--) {
                        row[p] = row[p - 1];
                    }
                    row[0] = last;
                }
            }
        }
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[i].length; j++) {
                if (mat[i][j] != originalMat[i][j]) return false;
            }
        }
        return true;
    }
}

