class Solution {
    public static int makeThreeStringsEqual(String s1, String s2, String s3) {
        int minLen = Math.min(Math.min(s1.length(), s2.length()), s3.length());
        int lcpLen = 0;
        while (lcpLen < minLen && s1.charAt(lcpLen) == s2.charAt(lcpLen) && s2.charAt(lcpLen) == s3.charAt(lcpLen)) {
            lcpLen++;
        }
        if (lcpLen == 0) return -1;
        return (s1.length() - lcpLen) + (s2.length() - lcpLen) + (s3.length() - lcpLen);
    }
}

