class Solution {
    public static int[] makeSmallestArray(int[] nums, int limit) {
        int[] result = nums.clone();
        for (int i = 0; i < result.length; i++) {
            for (int j = i + 1; j < result.length; j++) {
                if (Math.abs(result[i] - result[j]) <= limit) {
                    if (result[i] > result[j]) {
                        int temp = result[i];
                        result[i] = result[j];
                        result[j] = temp;
                    }
                }
            }
        }
        return result;
    }
}

