import java.lang.Math;

class Solution {
    public static int minOperations(String word) {
        int n = word.length();
        if (n == 0) return 0;
        int notChanged = 0;
        int changed = 1;
        for (int i = 1; i < n; i++) {
            int newNotChanged = Integer.MAX_VALUE;
            if (Math.abs(word.charAt(i) - word.charAt(i - 1)) > 1) {
                newNotChanged = notChanged;
            }
            newNotChanged = Math.min(newNotChanged, changed);
            int newChanged = 1 + Math.min(notChanged, changed);
            notChanged = newNotChanged;
            changed = newChanged;
        }
        return Math.min(notChanged, changed);
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long numInfectionSequences(int n, int[] sick) {
        int[] s = sick.clone();
        Arrays.sort(s);
        int totalHealthy = n - s.length;
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }
        long result = fact[totalHealthy];
        // left gap
        int left = s[0];
        result = result * invFact[left] % MOD;
        // right gap
        int right = n - 1 - s[s.length - 1];
        result = result * invFact[right] % MOD;
        // internal gaps
        for (int i = 1; i < s.length; i++) {
            int gap = s[i] - s[i - 1] - 1;
            result = result * invFact[gap] % MOD;
            if (gap > 0) {
                result = result * modPow(2, gap - 1) % MOD;
            }
        }
        return result;
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = res * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }
}

import java.util.*;

class Solution {
    public static int longestSubarray(int[] nums, int k) {
        int maxLength = 0;
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            frequencyMap.put(nums[right], frequencyMap.getOrDefault(nums[right], 0) + 1);
            while (true) {
                boolean exceeds = false;
                for (int count : frequencyMap.values()) {
                    if (count > k) {
                        exceeds = true;
                        break;
                    }
                }
                if (!exceeds) {
                    break;
                }
                int leftVal = nums[left];
                int newCount = frequencyMap.get(leftVal) - 1;
                if (newCount == 0) {
                    frequencyMap.remove(leftVal);
                } else {
                    frequencyMap.put(leftVal, newCount);
                }
                left++;
            }
            maxLength = Math.max(maxLength, right - left + 1);
        }
        return maxLength;
    }
}

