class Solution {
    public static List<Integer> doubleModularExponentiation(int[][] variables, int target) {
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < variables.length; i++) {
            int a = variables[i][0];
            int b = variables[i][1];
            int c = variables[i][2];
            int m = variables[i][3];
            double temp = Math.pow(a, b) % 10;
            double value = Math.pow(temp, c) % m;
            if (value == target) {
                result.add(i);
            }
        }
        return result;
    }
}

class Solution {
    public static int countTestedDevices(int[] batteryPercentages) {
        int testedDevices = 0;
        for (int i = 0; i < batteryPercentages.length; i++) {
            if (batteryPercentages[i] > 0) {
                testedDevices++;
                for (int j = 0; j < batteryPercentages.length; j++) {
                    if (j != i) {
                        batteryPercentages[j]--;
                    }
                }
            }
        }
        return testedDevices;
    }
}

import java.util.Arrays;

class Solution {
    public static int numberOfSubarrays(int[] nums, int k) {
        int count = 0;
        for (int length = 1; length <= nums.length; length++) {
            for (int i = 0; i <= nums.length - length; i++) {
                int[] subarray = Arrays.copyOfRange(nums, i, i + length);
                int maxElement = subarray[0];
                for (int val : subarray) {
                    if (val > maxElement) {
                        maxElement = val;
                    }
                }
                int maxElementCount = 0;
                for (int val : subarray) {
                    if (val == maxElement) {
                        maxElementCount++;
                    }
                }
                if (maxElementCount >= k) {
                    count++;
                }
            }
        }
        return count;
    }
}

