class Solution {
    public static int countGoodPartitions(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        Map<Integer, Integer> firstMap = new HashMap<>();
        Map<Integer, Integer> lastMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            firstMap.putIfAbsent(nums[i], i);
            lastMap.put(nums[i], i);
        }
        int[] firstPos = new int[n];
        int[] lastPos = new int[n];
        for (int i = 0; i < n; i++) {
            firstPos[i] = firstMap.get(nums[i]);
            lastPos[i] = lastMap.get(nums[i]);
        }
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 0; i < n; i++) {
            long ways = 0;
            int minFirst = i;
            int maxLast = i;
            for (int j = i; j >= 0; j--) {
                minFirst = Math.min(minFirst, firstPos[j]);
                maxLast = Math.max(maxLast, lastPos[j]);
                if (maxLast > i) {
                    break;
                }
                if (minFirst == j && maxLast == i) {
                    ways = (ways + dp[j]) % MOD;
                }
            }
            dp[i + 1] = ways;
        }
        return (int) (dp[n] % MOD);
    }
}

