class Solution {
    public static long numberOfSets(int n, int maxDistance, int[][] roads) {
        final int INF = 1_000_000_000;
        int[][] base = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(base[i], INF);
            base[i][i] = 0;
        }
        for (int[] r : roads) {
            int u = r[0];
            int v = r[1];
            int w = r[2];
            if (w < base[u][v]) {
                base[u][v] = w;
                base[v][u] = w;
            }
        }
        long count = 0;
        int totalMasks = 1 << n;
        for (int mask = 0; mask < totalMasks; mask++) {
            // count bits
            int bits = Integer.bitCount(mask);
            if (bits <= 1) {
                count++;
                continue;
            }
            int[][] d = new int[n][n];
            for (int i = 0; i < n; i++) {
                System.arraycopy(base[i], 0, d[i], 0, n);
            }
            // Floyd-Warshall using only active nodes as intermediate
            for (int k = 0; k < n; k++) {
                if ((mask & (1 << k)) == 0) continue;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) == 0) continue;
                    if (d[i][k] == INF) continue;
                    for (int j = 0; j < n; j++) {
                        if ((mask & (1 << j)) == 0) continue;
                        if (d[k][j] == INF) continue;
                        int nd = d[i][k] + d[k][j];
                        if (nd < d[i][j]) d[i][j] = nd;
                    }
                }
            }
            boolean ok = true;
            outer:
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) continue;
                for (int j = i + 1; j < n; j++) {
                    if ((mask & (1 << j)) == 0) continue;
                    if (d[i][j] > maxDistance) {
                        ok = false;
                        break outer;
                    }
                }
            }
            if (ok) count++;
        }
        return count;
    }
}

