class Solution {
    public static int numberOfSubarrays(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i; j < nums.length; j++) {
                List<Integer> merged = new ArrayList<>();
                for (int k = 0; k < i; k++) {
                    merged.add(nums[k]);
                }
                for (int k = j + 1; k < nums.length; k++) {
                    merged.add(nums[k]);
                }
                boolean isIncreasing = true;
                for (int k = 0; k < merged.size() - 1; k++) {
                    if (merged.get(k) >= merged.get(k + 1)) {
                        isIncreasing = false;
                        break;
                    }
                }
                if (isIncreasing) {
                    count++;
                }
            }
        }
        return count;
    }
}

