class Solution {
    public static long minCostToMakeEqualindromic(int[] nums) {
        int n = nums.length;
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) arr[i] = nums[i];
        Arrays.sort(arr);
        List<Long> medians = new ArrayList<>();
        if (n % 2 == 1) {
            medians.add(arr[n / 2]);
        } else {
            medians.add(arr[n / 2 - 1]);
            medians.add(arr[n / 2]);
        }
        Set<Long> candidates = new HashSet<>();
        candidates.add(0L);
        for (long m : medians) {
            String mStr = Long.toString(m);
            int lenM = mStr.length();
            for (int L = Math.max(1, lenM - 2); L <= lenM + 2; L++) {
                int half = (L + 1) / 2;
                long basePrefix;
                if (half <= mStr.length()) {
                    basePrefix = Long.parseLong(mStr.substring(0, half));
                } else {
                    basePrefix = Long.parseLong(mStr) * (long) Math.pow(10, half - mStr.length());
                }
                for (long p = basePrefix - 1; p <= basePrefix + 1; p++) {
                    if (p < 0) continue;
                    boolean odd = (L % 2 == 1);
                    long pal = buildPalindrome(p, odd);
                    if (String.valueOf(pal).length() == L) {
                        candidates.add(pal);
                    }
                }
            }
        }
        long minCost = Long.MAX_VALUE;
        for (long cand : candidates) {
            long cost = 0;
            for (long num : arr) {
                cost += Math.abs(num - cand);
                if (cost >= minCost) break;
            }
            if (cost < minCost) minCost = cost;
        }
        return minCost;
    }

    private static long buildPalindrome(long prefix, boolean odd) {
        long pal = prefix;
        long x = odd ? prefix / 10 : prefix;
        while (x > 0) {
            pal = pal * 10 + (x % 10);
            x /= 10;
        }
        return pal;
    }
}

import java.util.*;

class Solution {
    public static int maxFrequencyScore(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        int maxScore = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            while (left < right) {
                int mid = (left + right) >>> 1;
                long median = nums[mid];
                long leftCost = median * (mid - left) - (prefix[mid] - prefix[left]);
                long rightCost = (prefix[right + 1] - prefix[mid + 1]) - median * (right - mid);
                long totalCost = leftCost + rightCost;
                if (totalCost <= k) {
                    break;
                }
                left++;
            }
            int currentScore = right - left + 1;
            if (currentScore > maxScore) {
                maxScore = currentScore;
            }
        }
        return maxScore;
    }
}

import java.util.Arrays;

class Solution {
    public static int largestPerimeter(int[] nums) {
        Arrays.sort(nums);
        long total = 0;
        for (int v : nums) {
            total += v;
        }
        for (int i = nums.length - 1; i >= 2; i--) {
            if (total - nums[i] > nums[i]) {
                return (int) total;
            }
            total -= nums[i];
        }
        return -1;
    }
}

