class Solution {
    public static long[] placedCoins(int[][] edges, int[] cost) {
        int n = cost.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            adj[a].add(b);
            adj[b].add(a);
        }
        long[] coin = new long[n];
        int[] subtreeSize = new int[n];
        dfs(0, -1, adj, cost, coin, subtreeSize);
        return coin;
    }

    private static long[] dfs(int u, int parent, List<Integer>[] adj, int[] cost,
                              long[] coin, int[] subtreeSize) {
        List<Long> vals = new ArrayList<>();
        vals.add((long) cost[u]);
        int size = 1;

        for (int v : adj[u]) {
            if (v == parent) continue;
            long[] childTop = dfs(v, u, adj, cost, coin, subtreeSize);
            size += subtreeSize[v];
            for (long val : childTop) {
                if (val != Long.MIN_VALUE) vals.add(val);
            }
        }

        Collections.sort(vals, Collections.reverseOrder());
        long[] top = new long[3];
        Arrays.fill(top, Long.MIN_VALUE);
        for (int i = 0; i < Math.min(3, vals.size()); i++) {
            top[i] = vals.get(i);
        }

        subtreeSize[u] = size;
        if (size == 1) {
            coin[u] = 1;
        } else {
            long product = 1;
            int count = 0;
            for (int i = 0; i < 3 && top[i] != Long.MIN_VALUE; i++) {
                product *= top[i];
                count++;
            }
            coin[u] = product > 0 ? product : 0;
        }
        return top;
    }
}

import java.util.*;

class Solution {
    public static int countIncremovableSubarrays(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i; j < nums.length; j++) {
                int remainingSize = i + (nums.length - (j + 1));
                int[] remaining = new int[remainingSize];
                int idx = 0;
                for (int k = 0; k < i; k++) {
                    remaining[idx++] = nums[k];
                }
                for (int k = j + 1; k < nums.length; k++) {
                    remaining[idx++] = nums[k];
                }
                if (isIncreasing(remaining)) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean isIncreasing(int[] arr) {
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] <= arr[i - 1]) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long maximizeSquareArea(int m, int n, int[] hFences, int[] vFences) {
        // Build arrays of vertical fence positions (x‑coordinates)
        long[] vert = new long[hFences.length + 2];
        vert[0] = 1L;
        for (int i = 0; i < hFences.length; i++) vert[i + 1] = hFences[i];
        vert[vert.length - 1] = m;
        Arrays.sort(vert);

        // Build arrays of horizontal fence positions (y‑coordinates)
        long[] horiz = new long[vFences.length + 2];
        horiz[0] = 1L;
        for (int i = 0; i < vFences.length; i++) horiz[i + 1] = vFences[i];
        horiz[horiz.length - 1] = n;
        Arrays.sort(horiz);

        // All possible side lengths from vertical fences
        HashSet<Long> verticalDiffs = new HashSet<>();
        for (int i = 0; i < vert.length; i++) {
            for (int j = i + 1; j < vert.length; j++) {
                verticalDiffs.add(vert[j] - vert[i]);
            }
        }

        long best = -1;
        // Check horizontal differences against the set
        for (int i = 0; i < horiz.length; i++) {
            for (int j = i + 1; j < horiz.length; j++) {
                long diff = horiz[j] - horiz[i];
                if (verticalDiffs.contains(diff) && diff > best) {
                    best = diff;
                }
            }
        }

        if (best <= 0) return -1;
        long sideMod = best % MOD;
        return (sideMod * sideMod) % MOD;
    }
}

import java.util.*;

class Solution {
    private static class Edge {
        String to;
        int cost;
        Edge(String to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    private static long dijkstra(String start, String target, Map<String, List<Edge>> adj) {
        if (start.equals(target)) return 0L;
        String key = start + "|" + target;
        // memoization map stored in a static field
        Long cached = memo.get(key);
        if (cached != null) return cached;

        long INF = Long.MAX_VALUE / 4;
        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a.dist));
        Map<String, Long> dist = new HashMap<>();
        dist.put(start, 0L);
        pq.offer(new Node(start, 0L));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            long d = cur.dist;
            if (d != dist.get(cur.str)) continue;
            if (cur.str.equals(target)) {
                memo.put(key, d);
                return d;
            }
            List<Edge> edges = adj.get(cur.str);
            if (edges == null) continue;
            for (Edge e : edges) {
                long nd = d + e.cost;
                Long old = dist.get(e.to);
                if (old == null || nd < old) {
                    dist.put(e.to, nd);
                    pq.offer(new Node(e.to, nd));
                }
            }
        }
        memo.put(key, INF);
        return INF;
    }

    private static class Node {
        String str;
        long dist;
        Node(String str, long dist) {
            this.str = str;
            this.dist = dist;
        }
    }

    private static Map<String, Long> memo = new HashMap<>();

    public static long minimumCost(String source, String target, String[] original, String[] changed, int[] cost) {
        int n = source.length();
        long INF = Long.MAX_VALUE / 4;

        // Build adjacency maps grouped by length
        Map<Integer, Map<String, List<Edge>>> adjByLen = new HashMap<>();
        for (int i = 0; i < original.length; i++) {
            int len = original[i].length(); // same as changed[i].length()
            Map<String, List<Edge>> map = adjByLen.computeIfAbsent(len, k -> new HashMap<>());
            map.computeIfAbsent(original[i], k -> new ArrayList<>()).add(new Edge(changed[i], cost[i]));
        }

        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                int len = i - j;
                String subS = source.substring(j, i);
                String subT = target.substring(j, i);
                long intervalCost;

                if (subS.equals(subT)) {
                    intervalCost = 0;
                } else {
                    Map<String, List<Edge>> adj = adjByLen.get(len);
                    if (adj == null) continue; // no operations of this length
                    intervalCost = dijkstra(subS, subT, adj);
                    if (intervalCost >= INF) continue;
                }

                if (dp[j] + intervalCost < dp[i]) {
                    dp[i] = dp[j] + intervalCost;
                }
            }
        }

        return dp[n] >= INF ? -1 : dp[n];
    }
}

import java.util.*;

class Solution {
    public static long minimumCost(String source, String target, char[] original, char[] changed, int[] cost) {
        int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[26][26];
        for (int i = 0; i < 26; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int i = 0; i < cost.length; i++) {
            int u = original[i] - 'a';
            int v = changed[i] - 'a';
            if (cost[i] < dist[u][v]) {
                dist[u][v] = cost[i];
            }
        }
        for (int k = 0; k < 26; k++) {
            for (int i = 0; i < 26; i++) {
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < 26; j++) {
                    if (dist[k][j] == INF) continue;
                    int nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) {
                        dist[i][j] = nd;
                    }
                }
            }
        }
        long total = 0;
        int n = source.length();
        for (int i = 0; i < n; i++) {
            int s = source.charAt(i) - 'a';
            int t = target.charAt(i) - 'a';
            if (s == t) continue;
            int d = dist[s][t];
            if (d == INF) return -1;
            total += d;
        }
        return total;
    }
}

import java.util.*;

class Solution {
    private static final long BASE = 91138233L;

    public static int longestSpecialSubstring(String s) {
        int n = s.length();
        long[] pref = new long[n + 1];
        long[] pow = new long[n + 1];
        pow[0] = 1;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] * BASE + s.charAt(i);
            pow[i + 1] = pow[i] * BASE;
        }

        int low = 1, high = n, ans = -1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (exists(s, pref, pow, mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }

    private static boolean exists(String s, long[] pref, long[] pow, int len) {
        int n = s.length();
        if (len > n) return false;
        HashMap<Long, Integer> countMap = new HashMap<>();
        for (int i = 0; i <= n - len; i++) {
            if (s.charAt(i) != s.charAt(i + len - 1)) continue;
            long hash = pref[i + len] - pref[i] * pow[len];
            int cnt = countMap.getOrDefault(hash, 0) + 1;
            if (cnt >= 3) return true;
            countMap.put(hash, cnt);
        }
        return false;
    }
}

