class Solution {
    public static int longestSpecialSubstring(String s) {
        int maxLength = -1;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String substring = s.substring(i, j);
                Set<Character> set = new HashSet<>();
                for (int idx = 0; idx < substring.length(); idx++) {
                    set.add(substring.charAt(idx));
                }
                if (set.size() == 1) {
                    int count = 0;
                    for (int k = 0; k <= s.length() - substring.length(); k++) {
                        if (s.substring(k, k + substring.length()).equals(substring)) {
                            count++;
                        }
                    }
                    if (count >= 3 && substring.length() > maxLength) {
                        maxLength = substring.length();
                    }
                }
            }
        }
        return maxLength;
    }
}

