class Solution {
    public static List<Boolean> canMakePalindrome(String s, List<int[]> queries) {
        int n = s.length();
        List<Boolean> result = new ArrayList<>(queries.size());
        for (int[] q : queries) {
            int a = q[0], b = q[1], c = q[2], d = q[3];
            int[] pool = new int[128];
            for (int i = a; i <= b; i++) pool[s.charAt(i)]++;
            for (int i = c; i <= d; i++) pool[s.charAt(i)]++;
            int[] required = new int[128];
            int totalRequired = 0;
            boolean possible = true;
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                boolean inI = (i >= a && i <= b) || (i >= c && i <= d);
                boolean inJ = (j >= a && j <= b) || (j >= c && j <= d);
                if (!inI && !inJ) {
                    if (s.charAt(i) != s.charAt(j)) {
                        possible = false;
                        break;
                    }
                } else if (inI && !inJ) {
                    required[s.charAt(j)]++;
                    totalRequired++;
                } else if (!inI && inJ) {
                    required[s.charAt(i)]++;
                    totalRequired++;
                }
            }
            if (!possible) {
                result.add(false);
                continue;
            }
            for (int ch = 0; ch < 128; ch++) {
                if (required[ch] > pool[ch]) {
                    possible = false;
                    break;
                }
            }
            if (!possible) {
                result.add(false);
                continue;
            }
            int leftoverPositions = (b - a + 1) + (d - c + 1) - totalRequired;
            if (n % 2 == 1) {
                int mid = n / 2;
                boolean inMid = (mid >= a && mid <= b) || (mid >= c && mid <= d);
                if (inMid) leftoverPositions++;
            }
            int oddLeftover = 0;
            for (int ch = 0; ch < 128; ch++) {
                int left = pool[ch] - required[ch];
                if ((left & 1) == 1) oddLeftover++;
            }
            if (oddLeftover > (leftoverPositions & 1)) possible = false;
            result.add(possible);
        }
        return result;
    }
}

import java.util.*;
class Solution {
    public static int minOperations(int x, int y) {
        if (x == y) return 0;
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{x, 0});
        Set<Integer> visited = new HashSet<>();
        visited.add(x);
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int current = cur[0], steps = cur[1];
            if (current == y) return steps;
            List<Integer> nexts = new ArrayList<>();
            if (current % 5 == 0) nexts.add(current/5);
            if (current % 11 == 0) nexts.add(current/11);
            nexts.add(current+1);
            nexts.add(current-1);
            for (int nxt : nexts) {
                if (nxt <= 0 || visited.contains(nxt)) continue;
                visited.add(nxt);
                q.add(new int[]{nxt, steps+1});
            }
        }
        return -1;
    }
}

