class Solution {
    public static int minMovesToCaptureTheQueen(int a, int b, int c, int d, int e, int f) {
        int rookMoves;
        if (a == e && b == f) {
            rookMoves = 0;
        } else if (a == e || b == f) {
            rookMoves = 1;
        } else {
            rookMoves = 2;
        }
        int bishopMoves = Integer.MAX_VALUE;
        if (c == e && d == f) {
            bishopMoves = 0;
        } else if (Math.abs(c - e) == Math.abs(d - f)) {
            bishopMoves = 1;
        } else if ((c + d) % 2 == (e + f) % 2) {
            bishopMoves = 2;
        }
        int result = Math.min(rookMoves, bishopMoves);
        return result == Integer.MAX_VALUE ? -1 : result;
    }
}

