class Solution {
    public static int maxPartitions(String s, int k) {
        int maxPartitions = 1;
        for (int i = 0; i < s.length(); i++) {
            boolean changed = false;
            for (int j = 97; j <= 122; j++) {
                char ch = (char) j;
                if (ch == s.charAt(i)) continue;
                String newS = s.substring(0, i) + ch + s.substring(i + 1);
                int partitionCount = 0;
                Set<Character> currentDistinctChars = new HashSet<>();
                for (int m = 0; m < newS.length(); m++) {
                    currentDistinctChars.add(newS.charAt(m));
                    if (currentDistinctChars.size() > k) {
                        partitionCount++;
                        currentDistinctChars = new HashSet<>();
                        currentDistinctChars.add(newS.charAt(m));
                    }
                }
                partitionCount++;
                maxPartitions = Math.max(maxPartitions, partitionCount);
                changed = true;
            }
            if (!changed) {
                int partitionCount = 0;
                Set<Character> currentDistinctChars = new HashSet<>();
                for (int m = 0; m < s.length(); m++) {
                    currentDistinctChars.add(s.charAt(m));
                    if (currentDistinctChars.size() > k) {
                        partitionCount++;
                        currentDistinctChars = new HashSet<>();
                        currentDistinctChars.add(s.charAt(m));
                    }
                }
                partitionCount++;
                maxPartitions = Math.max(maxPartitions, partitionCount);
            }
        }
        return maxPartitions;
    }
}

