class Solution {
    public static long findMaximumNumber(long k, int x) {
        long low = 0;
        long high = 1;
        while (accumulatedPrice(high, x) <= k) {
            low = high;
            if (high > Long.MAX_VALUE / 2) {
                high = Long.MAX_VALUE;
                break;
            }
            high <<= 1;
        }
        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            if (accumulatedPrice(mid, x) <= k) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static long accumulatedPrice(long n, int x) {
        long total = 0;
        for (int pos = x; ; pos += x) {
            int bitIdx = pos - 1; // zero‑based index
            if (bitIdx > 61) break; // avoid overflow of shifts
            long pow = 1L << bitIdx;          // 2^bitIdx
            long cycle = pow << 1;            // 2^(bitIdx+1)
            long fullCycles = (n + 1) / cycle;
            long ones = fullCycles * pow;
            long remainder = (n + 1) % cycle;
            long extra = remainder - pow;
            if (extra > 0) ones += extra;
            total += ones;
        }
        return total;
    }
}

