class Solution {
    public static int countCompleteSubstrings(String word, int k) {
        int n = word.length();
        int aCode = (int) 'a';
        int answer = 0;
        for (int d = 1; d <= 26; d++) {
            if (d * k > n) break;
            int[] cnt = new int[26];
            int distinct = 0;
            int good = 0;
            int exceed = 0;
            int left = 0;
            for (int right = 0; right < n; right++) {
                int idx = word.charAt(right) - aCode;
                cnt[idx]++;
                if (cnt[idx] == 1) distinct++;
                if (cnt[idx] == k) good++;
                if (cnt[idx] == k + 1) exceed++;
                while (distinct > d || exceed > 0) {
                    int lIdx = word.charAt(left) - aCode;
                    if (cnt[lIdx] == k) good--;
                    if (cnt[lIdx] == k + 1) {
                        exceed--;
                        good++;
                    }
                    cnt[lIdx]--;
                    if (cnt[lIdx] == 0) distinct--;
                    left++;
                }
                if (distinct == d && (right - left + 1) == d * k && good == d) {
                    answer++;
                }
            }
        }
        return answer;
    }
}

