class Solution {
  public int minOrAfterOperations(int[] nums, int k) {
    final int MAX_BIT = 30;
    int ans = 0;
    int prefixMask = 0;
    for (int i = MAX_BIT; i >= 0; --i) {
      prefixMask |= 1 << i;
      if (getMergeOps(nums, prefixMask, ans) > k)
        ans |= 1 << i;
    }
    return ans;
  }

  private int getMergeOps(int[] nums, int prefixMask, int target) {
    int mergeOps = 0;
    int ands = prefixMask;
    for (final int num : nums) {
      ands &= num;
      if ((ands | target) == target)
        ands = prefixMask;
      else
        ++mergeOps;
    }
    return mergeOps;
  }
}

class Solution {
    public int maximumLength(int[] nums) {
        Map<Long, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge((long) x, 1, Integer::sum);
        int ans = cnt.getOrDefault(1L, 0);
        if (ans % 2 == 0) ans -= 1;
        ans = Math.max(ans, 0);
        cnt.remove(1L);
        final long LIMIT = (long) 4e18;
        for (long x0 : new ArrayList<>(cnt.keySet())) {
            long x = x0;
            int t = 0;
            Set<Long> visitedChain = new HashSet<>();
            boolean overflowed = false;
            while (cnt.containsKey(x) && cnt.get(x) > 1 && !visitedChain.contains(x)) {
                visitedChain.add(x);
                t += 2;
                if (x > LIMIT / x) { overflowed = true; break; }
                x = x * x;
            }
            if (!overflowed && cnt.containsKey(x) && !visitedChain.contains(x)) t += 1;
            else t -= 1;
            ans = Math.max(ans, t);
        }
        return ans;
    }
}

