class Solution {
    public static long countUpperLeftPairs(int[][] points) {
        int n = points.length;
        long count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                int xi = points[i][0], yi = points[i][1];
                int xj = points[j][0], yj = points[j][1];
                if (!(yi > yj && xi <= xj)) continue;
                boolean blocked = false;
                for (int k = 0; k < n && !blocked; k++) {
                    if (k == i || k == j) continue;
                    int xk = points[k][0], yk = points[k][1];
                    if (xi < xk && xk < xj && yi > yk && yk > yj) blocked = true;
                }
                if (!blocked) count++;
            }
        }
        return count;
    }
