import java.lang.Math;

class Solution {
    public static int[][] findGridRegionAverage(int[][] image, int threshold) {
        int m = image.length;
        int n = image[0].length;
        int[][] sum = new int[m][n];
        int[][] cnt = new int[m][n];
        for (int i = 0; i <= m - 3; i++) {
            for (int j = 0; j <= n - 3; j++) {
                boolean ok = true;
                for (int r = 0; r < 3 && ok; r++) {
                    for (int c = 0; c < 3 && ok; c++) {
                        int cur = image[i + r][j + c];
                        if (c < 2 && Math.abs(cur - image[i + r][j + c + 1]) > threshold) {
                            ok = false;
                        }
                        if (r < 2 && Math.abs(cur - image[i + r + 1][j + c]) > threshold) {
                            ok = false;
                        }
                    }
                }
                if (!ok) continue;
                int regionSum = 0;
                for (int r = 0; r < 3; r++) {
                    for (int c = 0; c < 3; c++) {
                        regionSum += image[i + r][j + c];
                    }
                }
                int regionAvg = Math.floorDiv(regionSum, 9);
                for (int r = 0; r < 3; r++) {
                    for (int c = 0; c < 3; c++) {
                        int x = i + r;
                        int y = j + c;
                        sum[x][y] += regionAvg;
                        cnt[x][y] += 1;
                    }
                }
            }
        }
        int[][] result = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                result[i][j] = cnt[i][j] == 0 ? image[i][j] : Math.floorDiv(sum[i][j], cnt[i][j]);
            }
        }
        return result;
    }
}

public class Solution {
    public static int minimumTimeToRevert(String word, int k) {
        int n = word.length();
        int maxT = (n + k - 1) / k;
        for (int t = 1; t <= maxT; ++t) {
            int d = k * t;
            if (d > n) return t;
            boolean ok = true;
            for (int i = 0; i < n - d; ++i) {
                if (word.charAt(i) != word.charAt(i + d)) {
                    ok = false;
                    break;
                }
            }
            if (ok) return t;
        }
        return maxT;
    }
}

