public class Solution {
    public static int countValidPairs(int[][] points) {
        int n = points.length;
        Set<Integer> xSet = new HashSet<>();
        Set<Integer> ySet = new HashSet<>();
        for (int[] p : points) {
            xSet.add(p[0]);
            ySet.add(p[1]);
        }
        List<Integer> xs = new ArrayList<>(xSet);
        List<Integer> ys = new ArrayList<>(ySet);
        Collections.sort(xs);
        Collections.sort(ys);
        Map<Integer, Integer> xIndex = new HashMap<>();
        Map<Integer, Integer> yIndex = new HashMap<>();
        for (int i = 0; i < xs.size(); i++) xIndex.put(xs.get(i), i + 1);
        for (int i = 0; i < ys.size(); i++) yIndex.put(ys.get(i), i + 1);
        int nx = xs.size();
        int ny = ys.size();
        int[][] grid = new int[nx + 1][ny + 1];
        for (int[] p : points) {
            int xi = xIndex.get(p[0]);
            int yi = yIndex.get(p[1]);
            grid[xi][yi] = 1;
        }
        int[][] ps = new int[nx + 1][ny + 1];
        for (int i = 1; i <= nx; i++) {
            int rowSum = 0;
            for (int j = 1; j <= ny; j++) {
                rowSum += grid[i][j];
                ps[i][j] = ps[i - 1][j] + rowSum;
            }
        }
        int ans = 0;
        for (int a = 0; a < n; a++) {
            int xa = points[a][0];
            int ya = points[a][1];
            int xiA = xIndex.get(xa);
            int yiA = yIndex.get(ya);
            for (int b = 0; b < n; b++) {
                if (a == b) continue;
                int xb = points[b][0];
                int yb = points[b][1];
                int xiB = xIndex.get(xb);
                int yiB = yIndex.get(yb);
                if (xa <= xb && ya >= yb && (xa < xb || ya > yb)) {
                    int x1 = xiA;
                    int x2 = xiB;
                    int y1 = yiA;
                    int y2 = yiB;
                    int cnt = ps[x2][y1] - ps[x1 - 1][y1] - ps[x2][y2 - 1] + ps[x1 - 1][y2 - 1];
                    if (cnt == 2) ans++;
                }
            }
        }
        return ans;
    }
}

