class Solution {
    public int maxPalindromes(String[] words) {
        int[] freq = new int[26];
        for (String w : words) {
            for (char c : w.toCharArray()) {
                freq[c - 'a']++;
            }
        }
        long totalPairs = 0;
        long totalSingles = 0;
        for (int cnt : freq) {
            totalPairs += cnt / 2;
            totalSingles += cnt % 2;
        }
        int[] lengths = new int[words.length];
        for (int i = 0; i < words.length; i++) {
            lengths[i] = words[i].length();
        }
        Arrays.sort(lengths);
        int count = 0;
        for (int len : lengths) {
            long needPairs = len / 2;
            if (len % 2 == 0) {
                if (totalPairs >= needPairs) {
                    totalPairs -= needPairs;
                    count++;
                }
            } else {
                long extra = (totalSingles > 0) ? 0 : 1;
                if (totalPairs >= needPairs + extra) {
                    totalPairs -= needPairs;
                    if (totalSingles > 0) {
                        totalSingles--;
                    } else {
                        totalPairs--; // use one pair as the middle character
                    }
                    count++;
                }
            }
        }
        return count;
    }
}

