import java.util.Deque;

class Solution {
    public static String getStringBeforeLastOperation(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (!stack.isEmpty() && stack.peekLast() == ch) {
                stack.removeLast();
            } else {
                stack.addLast(ch);
            }
        }
        StringBuilder sb = new StringBuilder(stack.size());
        for (char c : stack) {
            sb.append(c);
        }
        return sb.toString();
    }
}

