public class Solution {
    public static int maxConsecutiveElements(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        int maxVal = 0;
        for (int v : nums) if (v > maxVal) maxVal = v;
        Arrays.sort(nums);
        boolean[] used = new boolean[maxVal + 2];
        for (int x : nums) {
            if (!used[x]) {
                used[x] = true;
            } else if (x + 1 <= maxVal + 1 && !used[x + 1]) {
                used[x + 1] = true;
            }
        }
        int best = 0, cur = 0;
        for (int i = 0; i < used.length; i++) {
            if (used[i]) {
                cur++;
            } else {
                if (cur > best) best = cur;
                cur = 0;
            }
        }
        if (cur > best) best = cur;
        return best;
    }
}

