class Solution {
    public int maxOperations(int[] nums) {
        int maxVal = 0;
        int[] freq = new int[1001];
        for (int num : nums) {
            freq[num]++;
            if (num > maxVal) maxVal = num;
        }
        int maxSum = maxVal * 2;
        int best = 0;
        for (int sum = 2; sum <= maxSum; sum++) {
            int ops = 0;
            for (int x = 1; x <= sum / 2; x++) {
                int y = sum - x;
                if (y > 1000) continue;
                if (x == y) {
                    ops += freq[x] / 2;
                } else {
                    ops += Math.min(freq[x], freq[y]);
                }
            }
            if (ops > best) best = ops;
        }
        return best;
    }
}

