public class Solution {
    public int longestCommonPrefix(int[] arr1, int[] arr2) {
        HashSet<Integer> prefixes = new HashSet<>();
        for (int num : arr1) {
            int cur = num;
            while (cur > 0) {
                prefixes.add(cur);
                cur /= 10;
            }
        }
        int best = 0;
        for (int num : arr2) {
            int cur = num;
            while (cur > 0) {
                if (prefixes.contains(cur)) {
                    int len = digitCount(cur);
                    if (len > best) {
                        best = len;
                    }
                    break;
                }
                cur /= 10;
            }
        }
        return best;
    }

    private int digitCount(int x) {
        int cnt = 0;
        while (x > 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }
}

