class Solution {
    private static class Node {
        Node[] child = new Node[26];
        int end;
    }

    public long countPrefixAndSuffixPairs(String[] words) {
        Node root = new Node();
        long ans = 0;
        for (String w : words) {
            int n = w.length();
            int[] pi = new int[n];
            for (int i = 1; i < n; i++) {
                int j = pi[i - 1];
                while (j > 0 && w.charAt(i) != w.charAt(j)) {
                    j = pi[j - 1];
                }
                if (w.charAt(i) == w.charAt(j)) {
                    j++;
                }
                pi[i] = j;
            }
            boolean[] isBorder = new boolean[n + 1];
            int len = n;
            while (len > 0) {
                isBorder[len] = true;
                len = pi[len - 1];
            }
            Node node = root;
            for (int i = 0; i < n; i++) {
                int idx = w.charAt(i) - 'a';
                if (node != null) {
                    node = node.child[idx];
                }
                if (isBorder[i + 1] && node != null) {
                    ans += node.end;
                }
            }
            node = root;
            for (int i = 0; i < n; i++) {
                int idx = w.charAt(i) - 'a';
                if (node.child[idx] == null) {
                    node.child[idx] = new Node();
                }
                node = node.child[idx];
            }
            node.end++;
        }
        return ans;
    }
}

