public class Solution {
    private static class Task {
        int deadline;
        long work;
        Task(int deadline, long work) {
            this.deadline = deadline;
            this.work = work;
        }
    }

    private static boolean feasible(int s, int[] nums, ArrayList<Integer>[] pos, int n) {
        List<Task> tasks = new ArrayList<>(n);
        long totalDecrements = 0;
        for (int i = 1; i <= n; ++i) {
            ArrayList<Integer> v = pos[i];
            int latest = -1;
            int lo = 0, hi = v.size() - 1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (v.get(mid) <= s) {
                    latest = v.get(mid);
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            if (latest == -1) return false;
            tasks.add(new Task(latest - 1, (long) nums[i - 1]));
            totalDecrements += nums[i - 1];
        }
        if (totalDecrements > (long) s - n) return false;
        tasks.sort(Comparator.comparingInt(t -> t.deadline));
        long cum = 0;
        for (Task t : tasks) {
            cum += t.work;
            if (cum > t.deadline) return false;
        }
        return true;
    }

    public static int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        int n = nums.length;
        int m = changeIndices.length;
        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] pos = new ArrayList[n + 1];
        for (int i = 1; i <= n; ++i) pos[i] = new ArrayList<>();
        for (int t = 0; t < m; ++t) {
            int idx = changeIndices[t];
            if (1 <= idx && idx <= n) pos[idx].add(t + 1);
        }
        int lo = 1, hi = m, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (feasible(mid, nums, pos, n)) {
                ans = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        int n = nums.length, m = changeIndices.length;
        long numsSum = 0;
        for (int v : nums) numsSum += v;
        Map<Integer,Integer> indexToFirstSecond = new HashMap<>();
        for (int s = 0; s < m; s++) {
            int idx = changeIndices[s] - 1;
            if (nums[idx] > 0 && !indexToFirstSecond.containsKey(idx)) indexToFirstSecond.put(idx, s);
        }
        Map<Integer,Integer> secondToIndex = new HashMap<>();
        for (Map.Entry<Integer,Integer> e : indexToFirstSecond.entrySet())
            secondToIndex.put(e.getValue(), e.getKey());

        int lo = 0, hi = m + 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (canMark(mid, nums, secondToIndex, n, numsSum)) hi = mid; else lo = mid + 1;
        }
        return lo <= m ? lo : -1;
    }

    private boolean canMark(int maxSecond, int[] nums, Map<Integer,Integer> secondToIndex, int n, long numsSum) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        int marks = 0;
        long heapSum = 0;
        for (int second = maxSecond - 1; second >= 0; second--) {
            Integer idx = secondToIndex.get(second);
            if (idx != null) {
                minHeap.offer(nums[idx]);
                heapSum += nums[idx];
                if (marks == 0) {
                    heapSum -= minHeap.poll();
                    marks++;
                } else {
                    marks--;
                }
            } else {
                marks++;
            }
        }
        int heapSize = minHeap.size();
        long decrementAndMarkCost = (numsSum - heapSum) + (n - heapSize);
        long zeroAndMarkCost = (long) heapSize * 2;
        return decrementAndMarkCost + zeroAndMarkCost <= maxSecond;
    }
}

