        PriorityQueue<Long> heap = new PriorityQueue<>();
        for (int v : nums) {
            heap.add((long) v);
        }
        int ops = 0;
        while (heap.size() >= 2) {
            long a = heap.poll();
            long b = heap.poll();
            if (a + b >= k) {
                heap.add(a);
                heap.add(b);
                break;
            }
            heap.add(a + b);
            ops++;
        }
        return ops;
    }
}

import java.util.*;

public class Connectable {
    static int signalSpeed;
    static List<List<int[]>> adj;

    static int dfs(int u, int parent, long dist) {
        int cnt = (dist % signalSpeed == 0) ? 1 : 0;
        for (int[] edge : adj.get(u)) {
            int v = edge[0], w = edge[1];
            if (v == parent) continue;
            cnt += dfs(v, u, dist + w);
        }
        return cnt;
    }

    static int[] countPairsOfConnectableServers(int[][] edges, int ss) {
        int n = edges.length + 1;
        signalSpeed = ss;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] count = new int[n];
        for (int root = 0; root < n; root++) {
            long total = 0, pairs = 0;
            for (int[] edge : adj.get(root)) {
                int child = edge[0], w = edge[1];
                long branchCount = dfs(child, root, w);
                pairs += total * branchCount;
                total += branchCount;
            }
            count[root] = (int) pairs;
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public static void solve() {
        Scanner sc = new Scanner(System.in);
        List<Long> data = new ArrayList<>();
        while (sc.hasNextLong()) {
            data.add(sc.nextLong());
        }
        if (data.isEmpty()) {
            return;
        }
        int idx = 0;
        long n = data.get(idx++);
        ArrayList<Long> nums = new ArrayList<>();
        nums.ensureCapacity((int) n);
        for (long i = 0; i < n; ++i) {
            nums.add(data.get(idx++));
        }
        long k = data.get(idx++);
        for (long i = 0; i < n - 1; ++i) {
            idx += 2;
        }
        long base_sum = 0;
        for (long v : nums) {
            base_sum += v;
        }
        long pos_sum = 0;
        long pos_cnt = 0;
        long min_pos = 0;
        boolean has_min_pos = false;
        long max_neg = 0;
        boolean has_max_neg = false;
        for (long v : nums) {
            long y = v ^ k;
            long diff = y - v;
            if (diff > 0) {
                pos_sum += diff;
                ++pos_cnt;
                if (!has_min_pos || diff < min_pos) {
                    min_pos = diff;
                    has_min_pos = true;
                }
            } else {
                if (!has_max_neg || diff > max_neg) {
                    max_neg = diff;
                    has_max_neg = true;
                }
            }
        }
        long ans;
        if (pos_cnt % 2 == 0) {
            ans = base_sum + pos_sum;
        } else {
            long cand1 = Long.MIN_VALUE;
            if (has_min_pos) cand1 = base_sum + pos_sum - min_pos;
            long cand2 = Long.MIN_VALUE;
            if (has_max_neg) cand2 = base_sum + pos_sum + max_neg;
            ans = Math.max(cand1, cand2);
        }
        System.out.print(ans);
    }
}

