class Solution {
    public int minimumOperations(int[][] grid) {
        int n = grid.length;
        int mid = n / 2;
        int[] yCount = new int[3];
        int[] otherCount = new int[3];
        int ySize = 0;
        int otherSize = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                boolean isY = (i == j && i <= mid) ||
                              (i + j == n - 1 && i <= mid) ||
                              (j == mid && i >= mid);
                int val = grid[i][j];
                if (isY) {
                    ySize++;
                    yCount[val]++;
                } else {
                    otherSize++;
                    otherCount[val]++;
                }
            }
        }
        int answer = Integer.MAX_VALUE;
        for (int a = 0; a < 3; a++) {
            for (int b = 0; b < 3; b++) {
                if (a == b) continue;
                int ops = (ySize - yCount[a]) + (otherSize - otherCount[b]);
                if (ops < answer) answer = ops;
            }
        }
        return answer;
    }
}

