class Solution {
    public static int minBoxes(int[] apple, int[] capacity) {
        int totalApples = 0;
        for (int i = 0; i < apple.length; i++) {
            totalApples += apple[i];
        }
        Arrays.sort(capacity);
        int used = 0;
        int sum = 0;
        int n = capacity.length;
        while (used < n && sum < totalApples) {
            sum += capacity[n - 1 - used];
            used++;
        }
        return used;
    }
}

