        long total = 0;
        for (int i = 0; i < nums.length; i++) {
            int n = nums[i];
            int maxDigit = 0;
            int digitCount = 0;
            while (n > 0) {
                int d = n % 10;
                if (d > maxDigit) maxDigit = d;
                n = n / 10;
                digitCount++;
            }
            long encrypted = 0;
            for (int j = 0; j < digitCount; j++) {
                encrypted = encrypted * 10 + maxDigit;
            }
            total += encrypted;
        }
        return total;
    }
}

