class Solution {
    public static long maximumStrength(long[] nums, int k) {
        int n = nums.length;
        final long NEG_INF = Long.MIN_VALUE / 4;
        long[][][] f = new long[n+1][k+1][2];
        for (long[][] row : f) for (long[] cell : row) Arrays.fill(cell, NEG_INF);
        f[0][0][0] = 0;
        for (int i = 1; i <= n; i++) {
            long x = nums[i-1];
            for (int j = 0; j <= k; j++) {
                long sign = (j % 2 == 1) ? 1 : -1;
                long val = sign * x * (k - j + 1);
                f[i][j][0] = Math.max(f[i-1][j][0], f[i-1][j][1]);
                f[i][j][1] = (f[i-1][j][1] != NEG_INF) ? f[i-1][j][1] + val : NEG_INF;
                if (j > 0) {
                    long prevBest = Math.max(f[i-1][j-1][0], f[i-1][j-1][1]);
                    if (prevBest != NEG_INF) {
                        f[i][j][1] = Math.max(f[i][j][1], prevBest + val);
                    }
                }
            }
        }
        return Math.max(f[n][k][0], f[n][k][1]);
    }
}

