class Solution {
    public static List<String> shortestUncommonSubstrings(List<String> arr) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String s : arr) {
            Set<String> local = new HashSet<>();
            int m = s.length();
            for (int i = 0; i < m; ++i) {
                for (int len = 1; i + len <= m; ++len) {
                    local.add(s.substring(i, i + len));
                }
            }
            for (String sub : local) {
                cnt.put(sub, cnt.getOrDefault(sub, 0) + 1);
            }
        }

        List<String> answer = new ArrayList<>(arr.size());
        for (String s : arr) {
            Set<String> seen = new HashSet<>();
            String best = "";
            int bestLen = Integer.MAX_VALUE;
            int m = s.length();
            for (int i = 0; i < m; ++i) {
                for (int len = 1; i + len <= m; ++len) {
                    String sub = s.substring(i, i + len);
                    if (!seen.add(sub)) continue;
                    if (cnt.getOrDefault(sub, 0) == 1) {
                        if (len < bestLen || (len == bestLen && sub.compareTo(best) < 0)) {
                            best = sub;
                            bestLen = len;
                        }
                    }
                }
            }
            answer.add(best);
        }
        return answer;
    }
}

