class Solution {
    private static final int MOD = 1_000_000_007;

    public int sumPower(int[] nums, int k) {
        int n = nums.length;
        long[][] dp = new long[n + 1][k + 1];
        dp[0][0] = 1;
        for (int num : nums) {
            for (int t = n - 1; t >= 0; t--) {
                for (int s = 0; s <= k - num; s++) {
                    if (dp[t][s] != 0) {
                        dp[t + 1][s + num] = (dp[t + 1][s + num] + dp[t][s]) % MOD;
                    }
                }
            }
        }
        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = (pow2[i - 1] * 2) % MOD;
        }
        long ans = 0;
        for (int t = 0; t <= n; t++) {
            long cnt = dp[t][k];
            if (cnt != 0) {
                ans = (ans + cnt * pow2[n - t]) % MOD;
            }
        }
        return (int) ans;
    }
}

