class Solution {
    public long[] sumOfMarkedElements(int[] nums, int[][] queries) {
        int n = nums.length;
        int m = queries.length;
        long total = 0L;
        for (int v : nums) total += v;
        boolean[] marked = new boolean[n];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        for (int i = 0; i < n; i++) {
            pq.offer(new int[]{nums[i], i});
        }
        long[] ans = new long[m];
        for (int i = 0; i < m; i++) {
            int idx = queries[i][0];
            int k = queries[i][1];
            if (!marked[idx]) {
                marked[idx] = true;
                total -= nums[idx];
            }
            int cnt = 0;
            while (cnt < k && !pq.isEmpty()) {
                int[] top = pq.peek();
                int val = top[0];
                int id = top[1];
                if (marked[id]) {
                    pq.poll();
                    continue;
                }
                marked[id] = true;
                total -= val;
                pq.poll();
                cnt++;
            }
            ans[i] = total;
        }
        return ans;
    }
}

class Solution {
    public static long minimumMoves(int[] nums, long k, long maxChanges) {
        long n = nums.length;
        long[] cnt = new long[(int)n+1], s = new long[(int)n+1];
        for (int i = 1; i <= n; i++) {
            long x = nums[i-1];
            cnt[i] = cnt[i-1] + x;
            s[i] = s[i-1] + (long)i * x;
        }
        long ans = Long.MAX_VALUE;
        for (int i = 1; i <= n; i++) {
            long x = nums[i-1];
            long t = 0;
            long need = k - x;
            for (int j : new int[]{i-1, i+1}) {
                if (need > 0 && j >= 1 && j <= n && nums[j-1] == 1) { need -= 1; t += 1; }
            }
            long c = Math.min(need, maxChanges);
            need -= c;
            t += c * 2;
            if (need <= 0) { ans = Math.min(ans, t); continue; }
            long l = 2, r = Math.max(i-1, n-i);
            while (l <= r) {
                long mid = (l+r) >> 1;
                long l1 = Math.max(1, i-mid), r1 = Math.max(0, i-2);
                long l2 = Math.min(n+1, i+2), r2 = Math.min(n, i+mid);
                long c1 = cnt[(int)r1] - cnt[(int)l1-1];
                long c2 = cnt[(int)r2] - cnt[(int)l2-1];
                if (c1 + c2 >= need) {
                    long t1 = c1*i - (s[(int)r1] - s[(int)l1-1]);
                    long t2 = s[(int)r2] - s[(int)l2-1] - c2*i;
                    ans = Math.min(ans, t + t1 + t2);
                    r = mid - 1;
                } else l = mid + 1;
            }
        }
        return ans;
    }

class Solution {
    public static int maxLengthSubstringWithTwoOccurrences(String s) {
        int n = s.length();
        if (n == 0) return 0;
        java.util.Map<Character,Integer> cnt = new java.util.HashMap<>();
        int left = 0, maxLen = 0;
        for (int right = 0; right < n; right++) {
            char c = s.charAt(right);
            cnt.merge(c, 1, Integer::sum);
            while (cnt.get(s.charAt(right)) > 2) {
                char lc = s.charAt(left);
                cnt.put(lc, cnt.get(lc)-1);
                left++;
            }
            maxLen = Math.max(maxLen, right-left+1);
        }
        return maxLen;
    }
}

public class Solution {
    public static int minOperationsToReachK(int k) {
        if (k <= 1) return 0;
        int best = k - 1;
        for (int v = 1; v <= k; ++v) {
            int copies = 0;
            if (k > v) {
                copies = (k - 1) / v;
            }
            int ops = (v - 1) + copies;
            if (ops < best) best = ops;
        }
        return best;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    private static class Node {
        Map<Character, Node> children = new HashMap<>();
        int bestIdx = -1;
        int bestLen = Integer.MAX_VALUE;
    }

    private static void updateBest(Node node, int idx, int len) {
        if (len < node.bestLen || (len == node.bestLen && idx < node.bestIdx)) {
            node.bestLen = len;
            node.bestIdx = idx;
        }
    }

    public static int[] longestCommonSuffixQueries(String[] wordsContainer, String[] wordsQuery) {
        Node root = new Node();
        for (int i = 0; i < wordsContainer.length; i++) {
            String word = wordsContainer[i];
            int wLen = word.length();
            Node cur = root;
            updateBest(cur, i, wLen);
            for (int p = wLen - 1; p >= 0; p--) {
                char ch = word.charAt(p);
                cur.children.putIfAbsent(ch, new Node());
                cur = cur.children.get(ch);
                updateBest(cur, i, wLen);
            }
        }

        int[] answer = new int[wordsQuery.length];
        for (int q = 0; q < wordsQuery.length; q++) {
            String query = wordsQuery[q];
            Node cur = root;
            for (int p = query.length() - 1; p >= 0; p--) {
                char ch = query.charAt(p);
                if (!cur.children.containsKey(ch)) {
                    break;
                }
                cur = cur.children.get(ch);
            }
            answer[q] = cur.bestIdx;
        }
        return answer;
    }
}

import java.util.HashMap;
