class Solution {
    public static int[] mostFrequentIDs(int[] nums, int[] freq) {
        Map<Integer, Integer> idCount = new HashMap<>();
        Map<Integer, Integer> freqCount = new HashMap<>();
        int maxFreq = 0;
        int[] ans = new int[nums.length];

        for (int i = 0; i < nums.length; i++) {
            int id = nums[i];
            int delta = freq[i];
            int oldCnt = idCount.getOrDefault(id, 0);
            int newCnt = oldCnt + delta;

            if (oldCnt > 0) {
                int oldFreqNum = freqCount.getOrDefault(oldCnt, 0) - 1;
                if (oldFreqNum == 0) {
                    freqCount.remove(oldCnt);
                } else {
                    freqCount.put(oldCnt, oldFreqNum);
                }
            }

            if (newCnt > 0) {
                idCount.put(id, newCnt);
                freqCount.put(newCnt, freqCount.getOrDefault(newCnt, 0) + 1);
            } else {
                idCount.remove(id);
            }

            if (newCnt > maxFreq) {
                maxFreq = newCnt;
            }
            while (maxFreq > 0 && freqCount.getOrDefault(maxFreq, 0) == 0) {
                maxFreq--;
            }

            ans[i] = maxFreq;
        }

        return ans;
    }
}

public class Solution {
    public static int minLevels(int[] possible) {
        int n = possible.length;
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = possible[i] == 1 ? 1 : -1;
        }
        int total = 0;
        for (int v : values) {
            total += v;
        }
        int pref = 0;
        for (int i = 0; i < n - 1; i++) {
            pref += values[i];
            if (pref > total - pref) {
                return i + 1;
            }
        }
        return -1;
    }
