class Solution {
    public static int minimumSubarrayLength(int[] nums, int k) {
        int n = nums.length;
        int[] bitCount = new int[31];
        int currentOr = 0;
        int left = 0;
        int ans = Integer.MAX_VALUE;
        for (int right = 0; right < n; right++) {
            int val = nums[right];
            for (int b = 0; b < 31; b++) {
                if ((val & (1 << b)) != 0) {
                    bitCount[b]++;
                    if (bitCount[b] == 1) {
                        currentOr |= (1 << b);
                    }
                }
            }
            while (left <= right && currentOr >= k) {
                ans = Math.min(ans, right - left + 1);
                int leftVal = nums[left];
                for (int b = 0; b < 31; b++) {
                    if ((leftVal & (1 << b)) != 0) {
                        bitCount[b]--;
                        if (bitCount[b] == 0) {
                            currentOr &= ~(1 << b);
                        }
                    }
                }
                left++;
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

import java.util.*;

class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        int ans = Integer.MAX_VALUE;
        int left = 0;
        int[] bitCnt = new int[32];
        int currentOR = 0;

        for (int right = 0; right < n; right++) {
            int val = nums[right];
            for (int b = 0; b < 32; b++) {
                if ((val & (1 << b)) != 0) {
                    bitCnt[b]++;
                }
            }
            currentOR = 0;
            for (int b = 0; b < 32; b++) {
                if (bitCnt[b] > 0) {
                    currentOR |= (1 << b);
                }
            }

            while (left <= right && currentOR >= k) {
                ans = Math.min(ans, right - left + 1);
                int removeVal = nums[left];
                for (int b = 0; b < 32; b++) {
                    if ((removeVal & (1 << b)) != 0) {
                        bitCnt[b]--;
                    }
                }
                left++;
                currentOR = 0;
                for (int b = 0; b < 32; b++) {
                    if (bitCnt[b] > 0) {
                        currentOR |= (1 << b);
                    }
                }
            }
        }

        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

