class Solution {
    public static int maxWaterBottles(int numBottles, int numExchange) {
        if (numExchange <= 1) {
            return numBottles;
        }
        int total = numBottles;
        int empty = numBottles;
        while (empty >= numExchange) {
            int newBottles = empty / numExchange;
            total += newBottles;
            empty = empty % numExchange;
        }
        return total;
    }
}

