import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int sumOfPowers(int[] nums, int k) {
        int n = nums.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nums[i];
        Arrays.sort(a);

        TreeSet<Long> diffSet = new TreeSet<>();
        diffSet.add(0L);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                diffSet.add(a[j] - a[i]);
            }
        }
        List<Long> diffs = new ArrayList<>(diffSet); // ascending order

        Map<Long, Long> cntGe = new HashMap<>();
        for (long d : diffs) {
            cntGe.put(d, countAtLeast(a, k, d));
        }

        long prev = 0; // count for larger diff (already processed)
        long ans = 0;
        for (int idx = diffs.size() - 1; idx >= 0; idx--) {
            long d = diffs.get(idx);
            long cur = cntGe.get(d);
            long exact = (cur - prev + MOD) % MOD;
            ans = (ans + exact * (d % MOD)) % MOD;
            prev = cur;
        }
        return (int) ans;
    }

    private static long countAtLeast(long[] a, int k, long d) {
        int n = a.length;
        long[][] dp = new long[k + 1][n];
        for (int i = 0; i < n; i++) dp[1][i] = 1;
        for (int t = 2; t <= k; t++) {
            for (int i = 0; i < n; i++) {
                long sum = 0;
                for (int prev = 0; prev < i; prev++) {
                    if (a[i] - a[prev] >= d) {
                        sum += dp[t - 1][prev];
                        if (sum >= MOD) sum -= MOD;
                    }
                }
                dp[t][i] = sum;
            }
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += dp[k][i];
            if (total >= MOD) total -= MOD;
        }
        return total;
    }
}

