class Solution {
    public static long minimumDistance(List<List<Integer>> points) {
        int n = points.size();
        long[] u = new long[n];
        long[] v = new long[n];
        for (int i = 0; i < n; ++i) {
            long x = points.get(i).get(0);
            long y = points.get(i).get(1);
            u[i] = x + y;
            v[i] = x - y;
        }

        long max_u = Long.MIN_VALUE, second_max_u = Long.MIN_VALUE;
        int cnt_max_u = 0;
        long min_u = Long.MAX_VALUE, second_min_u = Long.MAX_VALUE;
        int cnt_min_u = 0;
        long max_v = Long.MIN_VALUE, second_max_v = Long.MIN_VALUE;
        int cnt_max_v = 0;
        long min_v = Long.MAX_VALUE, second_min_v = Long.MAX_VALUE;
        int cnt_min_v = 0;

        for (int i = 0; i < n; ++i) {
            long val = u[i];
            if (val > max_u) {
                second_max_u = max_u;
                max_u = val;
                cnt_max_u = 1;
            } else if (val == max_u) {
                ++cnt_max_u;
            } else if (val > second_max_u) {
                second_max_u = val;
            }

            if (val < min_u) {
                second_min_u = min_u;
                min_u = val;
                cnt_min_u = 1;
            } else if (val == min_u) {
                ++cnt_min_u;
            } else if (val < second_min_u) {
                second_min_u = val;
            }

            val = v[i];
            if (val > max_v) {
                second_max_v = max_v;
                max_v = val;
                cnt_max_v = 1;
            } else if (val == max_v) {
                ++cnt_max_v;
            } else if (val > second_max_v) {
                second_max_v = val;
            }

            if (val < min_v) {
                second_min_v = min_v;
                min_v = val;
                cnt_min_v = 1;
            } else if (val == min_v) {
                ++cnt_min_v;
            } else if (val < second_min_v) {
                second_min_v = val;
            }
        }

        long answer = Long.MAX_VALUE;
        for (int i = 0; i < n; ++i) {
            long cur_max_u = (u[i] == max_u && cnt_max_u == 1) ? second_max_u : max_u;
            long cur_min_u = (u[i] == min_u && cnt_min_u == 1) ? second_min_u : min_u;
            long cur_max_v = (v[i] == max_v && cnt_max_v == 1) ? second_max_v : max_v;
            long cur_min_v = (v[i] == min_v && cnt_min_v == 1) ? second_min_v : min_v;

            long candidate = Math.max(cur_max_u - cur_min_u, cur_max_v - cur_min_v);
            if (candidate < answer) {
                answer = candidate;
            }
        }
        return answer;
    }
}

class Solution {
    public static int longestMonotonicSubarray(int[] nums) {
        if (nums.length == 0) return 0;
        int incLen = 1;
        int decLen = 1;
        int best = 1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > nums[i - 1]) {
                incLen = incLen + 1;
                decLen = 1;
            } else if (nums[i] < nums[i - 1]) {
                decLen = decLen + 1;
                incLen = 1;
            } else {
                incLen = 1;
                decLen = 1;
            }
            best = Math.max(best, Math.max(incLen, decLen));
        }
        return best;
    }
}

