public class Solution {
    public String getSmallestString(String s, int k) {
        int n = s.length();
        int maxPerPos = 13;
        StringBuilder result = new StringBuilder();
        int remaining = k;
        for (int i = 0; i < n; i++) {
            char original = s.charAt(i);
            boolean found = false;
            for (char c = 'a'; c <= 'z'; c++) {
                int d = distance(original, c);
                if (d <= remaining) {
                    int maxPossible = maxPerPos * (n - i - 1);
                    if (remaining - d <= maxPossible) {
                        result.append(c);
                        remaining -= d;
                        found = true;
                        break;
                    }
                }
            }
            if (!found) {
                return "";
            }
        }
        if (remaining != 0) {
            return "";
        }
        return result.toString();
    }

    private int distance(char a, char b) {
        int diff = Math.abs(a - b);
        return Math.min(diff, 26 - diff);
    }
}

