class Solution {
    public static long countSubarrays(int[] nums) {
        int n = nums.length;
        int[] nextGreater = new int[n];
        Arrays.fill(nextGreater, n);
        int[] stack = new int[n];
        int top = -1;
        for (int i = 0; i < n; ++i) {
            while (top >= 0 && nums[i] > nums[stack[top]]) {
                int idx = stack[top--];
                nextGreater[idx] = i;
            }
            stack[++top] = i;
        }

        Map<Integer, List<Integer>> posMap = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            int v = nums[i];
            posMap.computeIfAbsent(v, k -> new ArrayList<>()).add(i);
        }

        long ans = 0;
        for (Map.Entry<Integer, List<Integer>> entry : posMap.entrySet()) {
            List<Integer> positions = entry.getValue();
            long cnt = 0;
            int prev = -1;
            for (int pos : positions) {
                if (cnt == 0) {
                    cnt = 1;
                    prev = pos;
                } else {
                    if (nextGreater[prev] > pos) {
                        ++cnt;
                    } else {
                        ans += cnt * (cnt + 1) / 2;
                        cnt = 1;
                    }
                    prev = pos;
                }
            }
            ans += cnt * (cnt + 1) / 2;
        }
        return ans;
    }
}

import java.util.*;

public class Solution {
    public static int[] minimumCostWalk(int n, int[][] edges, int[][] query) {
        int[] parent = new int[n];
        int[] sz = new int[n];
        int[] compAnd = new int[n];
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            sz[i] = 1;
            compAnd[i] = ~0;
        }
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (parent[x] == x) return x;
                parent[x] = applyAsInt(parent[x]);
                return parent[x];
            }
        };
        java.util.function.BiConsumer<int[], Integer> unite = (unused, unused2) -> {};
        // Define unite as a lambda using a separate method for clarity
        class DSU {
            void unite(int a, int b, int w) {
                int ra = find.applyAsInt(a);
                int rb = find.applyAsInt(b);
                if (ra == rb) {
                    compAnd[ra] &= w;
                    return;
                }
                int newAnd = compAnd[ra] & compAnd[rb] & w;
                if (sz[ra] < sz[rb]) {
                    int tmp = ra;
                    ra = rb;
                    rb = tmp;
                }
                parent[rb] = ra;
                sz[ra] += sz[rb];
                compAnd[ra] = newAnd;
            }
        }
        DSU dsu = new DSU();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int w = e[2];
            dsu.unite(u, v, w);
        }
        int[] ans = new int[query.length];
        for (int i = 0; i < query.length; ++i) {
            int s = query[i][0];
            int t = query[i][1];
            if (find.applyAsInt(s) != find.applyAsInt(t)) {
                ans[i] = -1;
            } else {
                ans[i] = compAnd[find.applyAsInt(s)];
            }
        }
        return ans;
    }
}

