class Solution {
    public static long[] minimumTime(int n, int[][] edges, long[] disappear) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }
        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        if (0 < disappear[0]) {
            dist[0] = 0;
        } else {
            long[] res = new long[n];
            Arrays.fill(res, -1);
            return res;
        }
        PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        heap.offer(new long[]{0, 0});
        while (!heap.isEmpty()) {
            long[] cur = heap.poll();
            long time = cur[0];
            int node = (int) cur[1];
            if (time != dist[node]) continue;
            if (time >= disappear[node]) continue;
            for (int[] nb : adj[node]) {
                int nbr = nb[0];
                int w = nb[1];
                long newTime = time + w;
                if (newTime < disappear[nbr] && newTime < dist[nbr]) {
                    dist[nbr] = newTime;
                    heap.offer(new long[]{newTime, nbr});
                }
            }
        }
        long[] result = new long[n];
        for (int i = 0; i < n; i++) {
            result[i] = (dist[i] == INF) ? -1 : dist[i];
        }
        return result;
    }
}

