public class Solution {
    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static long lcm(long a, long b, long limit) {
        long g = gcd(a, b);
        long div = a / g;
        if (div > limit / b) {
            return limit + 1;
        }
        return div * b;
    }

    private static long countLe(long X, int[] coins) {
        int n = coins.length;
        long total = 0;
        long limit = X;
        int maxMask = 1 << n;
        for (int mask = 1; mask < maxMask; ++mask) {
            long curLcm = 1;
            boolean overflow = false;
            for (int i = 0; i < n; ++i) {
                if ((mask & (1 << i)) != 0) {
                    curLcm = lcm(curLcm, (long) coins[i], limit);
                    if (curLcm > limit) {
                        overflow = true;
                        break;
                    }
                }
            }
            if (overflow) continue;
            long add = X / curLcm;
            if ((Integer.bitCount(mask) & 1) == 1) {
                total += add;
            } else {
                total -= add;
            }
        }
        return total;
    }

    public static long kthSmallestAmount(int[] coins, long k) {
        long minCoin = Long.MAX_VALUE;
        for (int c : coins) {
            if (c < minCoin) minCoin = c;
        }
        long low = 1;
        long high = minCoin * k;
        while (low < high) {
            long mid = low + (high - low) / 2;
            if (countLe(mid, coins) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

