class Solution {
    public static int countSpecialCharacters(String word) {
        Set<Character> lowerSet = new HashSet<>();
        Set<Character> upperSet = new HashSet<>();
        for (int i = 0; i < word.length(); i++) {
            char ch = word.charAt(i);
            if (ch >= 'a' && ch <= 'z') {
                lowerSet.add(ch);
            } else if (ch >= 'A' && ch <= 'Z') {
                upperSet.add(ch);
            }
        }
        int specialCount = 0;
        for (char lc : lowerSet) {
            char uc = Character.toUpperCase(lc);
            if (upperSet.contains(uc)) {
                specialCount++;
            }
        }
        return specialCount;
    }
}

