                    firstUpper[idx] = i;
                }
            }
        }
        int count = 0;
        for (int i = 0; i < 26; i++) {
            if (lastLower[i] != -1 && firstUpper[i] != INF && lastLower[i] < firstUpper[i]) {
                count++;
            }
        }
        return count;
    }
