public class Solution {
    public static int max_prime_difference(List<Integer> nums) {
        IntPredicate isPrime = x -> {
            if (x < 2) return false;
            if (x == 2) return true;
            if (x % 2 == 0) return false;
            int limit = (int) Math.sqrt(x);
            for (int d = 3; d <= limit; d += 2) {
                if (x % d == 0) return false;
            }
            return true;
        };
        int first = -1;
        int last = -1;
        for (int i = 0; i < nums.size(); i++) {
            if (isPrime.test(nums.get(i))) {
                if (first == -1) first = i;
                last = i;
            }
        }
        if (first == -1) return 0;
        return last - first;
    }
}

import java.util.*;
class Solution {
    public static long minimumSum(long[] nums, long[] andValues) {
        long n = nums.length, m = andValues.length;
        if (m == 0) return 0;
        if (m > n) return -1;
        final long INF = (long)4e18;
        long[][] dp = new long[(int)n+1][(int)m+1];
        for (long[] row : dp) Arrays.fill(row, INF);
        dp[0][0] = 0;
        for (int i = 1; i <= n; i++) {
            long curAnd = 0;
            for (int left = i; left >= 1; left--) {
                if (left == i) curAnd = nums[i-1];
                else curAnd &= nums[left-1];
                for (int k = 1; k <= m; k++) {
                    if (curAnd == andValues[k-1]) {
                        long prev = dp[left-1][k-1];
                        if (prev != INF) {
                            long cand = prev + nums[i-1];
                            if (cand < dp[i][k]) dp[i][k] = cand;
                        }
                    }
                }
            }
        }
        long ans = dp[(int)n][(int)m];
        return ans != INF ? ans : -1;
    }
}

