class Solution {
    public static int countStableBinaryArrays(int zero, int one, int limit) {
        final int MOD = 1000000007;
        int[][][][] dp = new int[zero + 1][one + 1][2][limit + 1];
        if (zero > 0) dp[1][0][0][1] = 1;
        if (one > 0) dp[0][1][1][1] = 1;
        for (int z = 0; z <= zero; ++z) {
            for (int o = 0; o <= one; ++o) {
                for (int last = 0; last <= 1; ++last) {
                    for (int len = 1; len <= limit; ++len) {
                        int cur = dp[z][o][last][len];
                        if (cur == 0) continue;
                        if (last == 0) {
                            if (z < zero && len < limit) {
                                dp[z + 1][o][0][len + 1] = (dp[z + 1][o][0][len + 1] + cur) % MOD;
                            }
                            if (o < one) {
                                dp[z][o + 1][1][1] = (dp[z][o + 1][1][1] + cur) % MOD;
                            }
                        } else {
                            if (o < one && len < limit) {
                                dp[z][o + 1][1][len + 1] = (dp[z][o + 1][1][len + 1] + cur) % MOD;
                            }
                            if (z < zero) {
                                dp[z + 1][o][0][1] = (dp[z + 1][o][0][1] + cur) % MOD;
                            }
                        }
                    }
                }
            }
        }
        int ans = 0;
        for (int last = 0; last <= 1; ++last) {
            for (int len = 1; len <= limit; ++len) {
                ans = (ans + dp[zero][one][last][len]) % MOD;
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static class Edge {
        int to;
        int w;
        Edge(int to, int w) {
            this.to = to;
            this.w = w;
        }
    }

    private static class Node {
        long dist;
        int v;
        Node(long dist, int v) {
            this.dist = dist;
            this.v = v;
        }
    }

    private static long[] dijkstra(int n, int src, List<List<Edge>> adj) {
        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[src] = 0L;
        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a.dist));
        pq.offer(new Node(0L, src));
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            long d = cur.dist;
            int u = cur.v;
            if (d != dist[u]) continue;
            for (Edge e : adj.get(u)) {
                int v = e.to;
                int w = e.w;
                long nd = d + (long) w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new Node(nd, v));
                }
            }
        }
        return dist;
    }

    public static List<Boolean> findEdgesInShortestPaths(int n, List<List<Integer>> edges) {
        List<List<Edge>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (List<Integer> e : edges) {
            int u = e.get(0);
            int v = e.get(1);
            int w = e.get(2);
            adj.get(u).add(new Edge(v, w));
            adj.get(v).add(new Edge(u, w));
        }
        long[] distStart = dijkstra(n, 0, adj);
        long[] distEnd = dijkstra(n, n - 1, adj);
        long INF = Long.MAX_VALUE / 4;
        List<Boolean> answer = new ArrayList<>(edges.size());
        for (int i = 0; i < edges.size(); i++) answer.add(false);
        long shortest = distStart[n - 1];
        if (shortest == INF) return answer;
        for (int i = 0; i < edges.size(); i++) {
            List<Integer> e = edges.get(i);
            int u = e.get(0);
            int v = e.get(1);
            int w = e.get(2);
            long wll = (long) w;
            if (distStart[u] != INF && distEnd[v] != INF) {
                if (distStart[u] + wll + distEnd[v] == shortest) {
                    answer.set(i, true);
                    continue;
                }
            }
            if (distStart[v] != INF && distEnd[u] != INF) {
                if (distStart[v] + wll + distEnd[u] == shortest) {
                    answer.set(i, true);
                }
            }
        }
        return answer;
    }
}

