class Solution {
    public static long minimumArrayEnd(int n, int x) {
        long xx = x;
        if (n == 1) {
            return xx;
        }
        long need = n - 1;
        int pos = 0;
        while (true) {
            if ((xx & (1L << pos)) == 0) {
                need--;
                if (need == 0) {
                    return xx + (1L << pos);
                }
            }
            pos++;
        }
    }
}

