class Solution {
    public static int minOperations(String word, int k) {
        int n = word.length();
        int blockCount = n / k;
        Map<String, Integer> freq = new HashMap<>();

        for (int i = 0; i < n; i += k) {
            String block = word.substring(i, i + k);
            freq.put(block, freq.getOrDefault(block, 0) + 1);
        }

        int maxFreq = 0;
        for (int cnt : freq.values()) {
            if (cnt > maxFreq) {
                maxFreq = cnt;
            }
        }

        return blockCount - maxFreq;
    }
}

