class Solution {
    public static long findMinimumX(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] sorted2 = nums2.clone();
        Arrays.sort(sorted2);
        long best = Long.MAX_VALUE;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int[] remaining = new int[n - 2];
                int idx = 0;
                for (int k = 0; k < n; ++k) {
                    if (k != i && k != j) {
                        remaining[idx++] = nums1[k];
                    }
                }
                Arrays.sort(remaining);
                long x = (long) sorted2[0] - (long) remaining[0];
                boolean ok = true;
                for (int t = 0; t < remaining.length; ++t) {
                    if ((long) remaining[t] + x != (long) sorted2[t]) {
                        ok = false;
                        break;
                    }
                }
                if (ok && x < best) {
                    best = x;
                }
            }
        }
        return best;
    }
}

