class Solution {
    public static int medianUniqueness(int[] nums) {
        long n = nums.length;
        long total = n * (n + 1) / 2;
        long k = (total + 1) / 2;
        int low = 1;
        int high = (int) n;
        while (low < high) {
            int mid = (low + high) / 2;
            if (countAtMost(nums, mid) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static long countAtMost(int[] nums, int limit) {
        Map<Integer, Integer> freq = new HashMap<>();
        int left = 0;
        int distinct = 0;
        long cnt = 0;
        int n = nums.length;
        for (int right = 0; right < n; ++right) {
            int val = nums[right];
            int cur = freq.getOrDefault(val, 0);
            if (cur == 0) {
                ++distinct;
            }
            freq.put(val, cur + 1);
            while (distinct > limit) {
                int lval = nums[left];
                int lcur = freq.get(lval);
                if (lcur == 1) {
                    --distinct;
                }
                freq.put(lval, lcur - 1);
                ++left;
            }
            cnt += right - left + 1;
        }
        return cnt;
    }
}

