public class Solution {
    public static <T> boolean checkGrid(List<List<T>> grid) {
        int rows = grid.size();
        if (rows == 0) return true;
        int cols = grid.get(0).size();
        for (int i = 0; i < rows; i++) {
            T first = grid.get(i).get(0);
            boolean allSame = true;
            for (int j = 1; j < cols; j++) { if (!grid.get(i).get(j).equals(first)) { allSame = false; break; } }
            if (allSame) return false;
        }
        // Added: real LC 3230 also requires every column to be constant top-to-bottom.
        for (int j = 0; j < cols; j++) {
            T first = grid.get(0).get(j);
            for (int i = 1; i < rows; i++) {
