class Solution {
    static final long MOD = 1000000007;

    static long costForTarget(int[] nums, long cost1, long cost2, long target) {
        int n = nums.length;
        long S = 0, D = Long.MIN_VALUE;
        for (int v : nums) {
            long diff = target - v;
            S += diff;
            D = Math.max(D, diff);
        }
        if (cost2 >= 2 * cost1 || n < 2) return S * cost1;
        long rest = S - D;
        if (D <= rest) {
            long pairs = S / 2;
            long odd = S % 2;
            return pairs * cost2 + odd * cost1;
        } else {
            long excess = D - rest;
            return excess * cost1 + rest * cost2;
        }
    }

    public static long minimumCost(int[] nums, int cost1, int cost2) {
        int n = nums.length;
        int maxVal = Integer.MIN_VALUE;
        for (int v : nums) maxVal = Math.max(maxVal, v);

        if (cost2 >= 2L * cost1 || n <= 2) {
            return costForTarget(nums, cost1, cost2, maxVal) % MOD;
        }

        long S0 = 0, D0 = Long.MIN_VALUE;
        for (int v : nums) {
            long diff = maxVal - v;
            S0 += diff;
            D0 = Math.max(D0, diff);
        }
        long rest0 = S0 - D0;
        long excess0 = D0 - rest0;
        long tStar = excess0 <= 0 ? 0 : (excess0 + (n - 2) - 1) / (n - 2);

        long[] candidates = {0, tStar - 1, tStar, tStar + 1};
        long best = Long.MAX_VALUE;
        for (long t : candidates) {
            if (t < 0) continue;
            best = Math.min(best, costForTarget(nums, cost1, cost2, maxVal + t));
        }
        return best % MOD;
    }
}

class Solution {
    public static long maxEnergy(int[] energy, int k) {
        int n = energy.length;
        long[] dp = new long[n];
        for (int i = n - 1; i >= 0; i--) {
            if (i + k < n) {
                dp[i] = energy[i] + dp[i + k];
            } else {
                dp[i] = energy[i];
            }
        }
        long best = dp[0];
        for (int i = 1; i < n; i++) {
            if (dp[i] > best) best = dp[i];
        }
        return best;
    }
}

import java.util.*;

public class Solution {
    public static List<Integer> minCostPermutation(List<Integer> nums) {
        int n = nums.size();
        int fullMask = (1 << n) - 1;
        long INF = 1000000000000000L;

        long[][] cost = new long[n][n];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                cost[i][j] = Math.abs((long) i - (long) nums.get(j));
            }
        }

        long[][] dp = new long[1 << n][n];
        for (int i = 0; i < dp.length; ++i) {
            Arrays.fill(dp[i], INF);
        }
        dp[1 << 0][0] = 0;

        for (int mask = 0; mask <= fullMask; ++mask) {
            for (int last = 0; last < n; ++last) {
                long cur = dp[mask][last];
                if (cur == INF) continue;
                for (int nxt = 0; nxt < n; ++nxt) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    int newMask = mask | (1 << nxt);
                    long newCost = cur + cost[last][nxt];
                    if (newCost < dp[newMask][nxt]) {
                        dp[newMask][nxt] = newCost;
                    }
                }
            }
        }

        long bestTotal = INF;
        for (int last = 0; last < n; ++last) {
            long cur = dp[fullMask][last];
            if (cur == INF) continue;
            long total = cur + cost[last][0];
            if (total < bestTotal) bestTotal = total;
        }

        long[][] extra = new long[1 << n][n];
        for (int i = 0; i < extra.length; ++i) {
            Arrays.fill(extra[i], -1L);
        }

        long extraCost = extraCost(1 << 0, 0, extra, cost, fullMask, INF);
        // The above call is just to ensure the recursion works; result not used directly.

        List<Integer> perm = new ArrayList<>();
        perm.add(0);
        int mask = 1 << 0;
        int last = 0;
        while (mask != fullMask) {
            for (int nxt = 0; nxt < n; ++nxt) {
                if ((mask & (1 << nxt)) != 0) continue;
                long cur = dp[mask][last];
                long candTotal = cur + cost[last][nxt] + extraCost(mask | (1 << nxt), nxt, extra, cost, fullMask, INF);
                if (candTotal == bestTotal) {
                    perm.add(nxt);
                    mask |= 1 << nxt;
                    last = nxt;
                    break;
                }
            }
        }
        return perm;
    }

    private static long extraCost(int mask, int last, long[][] extra, long[][] cost, int fullMask, long INF) {
        if (extra[mask][last] != -1) return extra[mask][last];
        if (mask == fullMask) {
            extra[mask][last] = cost[last][0];
            return extra[mask][last];
        }
        long best = INF;
        int n = cost.length;
        for (int nxt = 0; nxt < n; ++nxt) {
            if ((mask & (1 << nxt)) != 0) continue;
            long cand = cost[last][nxt] + extraCost(mask | (1 << nxt), nxt, extra, cost, fullMask, INF);
            if (cand < best) best = cand;
        }
        extra[mask][last] = best;
        return best;
    }
}

import java.util.*;

public class Solution {
    static class Item {
        long d;
        String tag;
        Item(long d, String tag) {
            this.d = d;
            this.tag = tag;
        }
    }
    public static int maxPointsInsideSquare(List<long[]> points, List<String> s) {
        int n = points.size();
        List<Item> arr = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            long x = points.get(i)[0];
            long y = points.get(i)[1];
            long d = Math.max(Math.abs(x), Math.abs(y));
            arr.add(new Item(d, s.get(i)));
        }
        arr.sort(Comparator.comparingLong(a -> a.d));
        Set<String> seen = new HashSet<>();
        int count = 0;
        int i = 0;
        while (i < n) {
            long curD = arr.get(i).d;
            Set<String> groupTags = new HashSet<>();
            int j = i;
            while (j < n && arr.get(j).d == curD) {
                String tag = arr.get(j).tag;
                if (seen.contains(tag) || groupTags.contains(tag)) {
                    return count;
                }
                groupTags.add(tag);
                ++j;
            }
            seen.addAll(groupTags);
            count += groupTags.size();
            i = j;
        }
        return count;
    }
}

import java.util.List;

public class Solution {
    public static long sumDigitDifferences(List<Long> nums) {
        long n = nums.size();
        if (n < 2) return 0;
        int digitCount = Long.toString(nums.get(0)).length();
        long totalSum = 0;
        for (int pos = 0; pos < digitCount; ++pos) {
            long[] freq = new long[10];
            long divisor = 1;
            for (int i = 0; i < digitCount - 1 - pos; ++i) {
                divisor *= 10;
            }
            for (int i = 0; i < n; ++i) {
                int digit = (int)((nums.get(i) / divisor) % 10);
                ++freq[digit];
            }
            long totalPairs = n * (n - 1) / 2;
            long sameDigitPairs = 0;
            for (int d = 0; d < 10; ++d) {
                sameDigitPairs += freq[d] * (freq[d] - 1) / 2;
            }
            long diffDigitPairs = totalPairs - sameDigitPairs;
            totalSum += diffDigitPairs;
        }
        return totalSum;
    }
}

