class Solution {
    public static int minBalancedPartitions(String s) {
        int n = s.length();
        final int INF = 1000000000;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; ++i) {
            int[] cnt = new int[26];
            int maxFreq = 0;
            for (int j = i - 1; j >= 0; --j) {
                int idx = s.charAt(j) - 'a';
                ++cnt[idx];
                if (cnt[idx] > maxFreq) {
                    maxFreq = cnt[idx];
                }
                boolean balanced = true;
                for (int k = 0; k < 26; ++k) {
                    if (cnt[k] != 0 && cnt[k] != maxFreq) {
                        balanced = false;
                        break;
                    }
                }
                if (balanced) {
                    dp[i] = Math.min(dp[i], dp[j] + 1);
                }
            }
        }
        return dp[n];
    }
}

