        int ans = Integer.MIN_VALUE;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int minPrev = Integer.MAX_VALUE;
                if (i > 0) minPrev = Math.min(minPrev, minPrefix[i - 1][j]);
                if (j > 0) minPrev = Math.min(minPrev, minPrefix[i][j - 1]);
                if (minPrev != Integer.MAX_VALUE) {
                    ans = Math.max(ans, grid[i][j] - minPrev);
                }
                int curMin = grid[i][j];
                if (i > 0) curMin = Math.min(curMin, minPrefix[i - 1][j]);
                if (j > 0) curMin = Math.min(curMin, minPrefix[i][j - 1]);
                minPrefix[i][j] = curMin;
            }
        }
        return ans == Integer.MIN_VALUE ? -1 : ans;
    }
}

