class Solution {
    static class SegTree {
        int n;
        int[] tree;
        SegTree(int n) { this.n = n; tree = new int[2*n]; }
        void update(int pos, int val) {
            pos += n;
            tree[pos] = val;
            pos >>= 1;
            while (pos >= 1) {
                tree[pos] = Math.max(tree[2*pos], tree[2*pos+1]);
                pos >>= 1;
            }
        }
        int query(int l, int r) {
            if (l > r) return 0;
            int res = 0;
            l += n; r += n+1;
            while (l < r) {
                if ((l & 1) != 0) res = Math.max(res, tree[l++]);
                if ((r & 1) != 0) res = Math.max(res, tree[--r]);
                l >>= 1; r >>= 1;
            }
            return res;
        }
    }

    public boolean[] getResults(int[][] queries) {
        final int MAXX = 50002;
        SegTree seg = new SegTree(MAXX+1);
        TreeSet<Integer> obstacles = new TreeSet<>();
        obstacles.add(0);
        List<Boolean> ans = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int x = q[1];
                Integer succ = obstacles.higher(x);
                int L = obstacles.floor(x);
                if (succ != null) {
                    seg.update(succ, succ - x);
                }
                seg.update(x, x - L);
                obstacles.add(x);
            } else {
                int x = q[1], sz = q[2];
                int last = obstacles.floor(x);
                int trailing = x - last;
                int best = Math.max(seg.query(0, x), trailing);
                ans.add(best >= sz);
            }
        }
        boolean[] arr = new boolean[ans.size()];
        for (int i = 0; i < arr.length; i++) arr[i] = ans.get(i);
        return arr;
    }
}

