public class Solution {
    public static List<Integer> findDistinctColors(int limit, List<int[]> queries) {
        Map<Integer, Integer> ballColor = new HashMap<>();
        Map<Integer, Integer> colorCount = new HashMap<>();
        List<Integer> result = new ArrayList<>(queries.size());

        for (int[] q : queries) {
            int ball = q[0];
            int newColor = q[1];

            if (ballColor.containsKey(ball)) {
                int oldColor = ballColor.get(ball);
                Integer oldCnt = colorCount.get(oldColor);
                if (oldCnt != null) {
                    int newCnt = oldCnt - 1;
                    if (newCnt == 0) {
                        colorCount.remove(oldColor);
                    } else {
                        colorCount.put(oldColor, newCnt);
                    }
                }
            }

            ballColor.put(ball, newColor);
            Integer newCnt = colorCount.get(newColor);
            if (newCnt != null) {
                colorCount.put(newColor, newCnt + 1);
            } else {
                colorCount.put(newColor, 1);
            }

            result.add(colorCount.size());
        }

        return result;
    }
}

