class Solution {
    public static int count_days_without_meetings(int days, List<List<Integer>> meetings) {
        if (meetings.isEmpty()) {
            return days;
        }
        Collections.sort(meetings, new Comparator<List<Integer>>() {
            public int compare(List<Integer> a, List<Integer> b) {
                return Integer.compare(a.get(0), b.get(0));
            }
        });
        int covered = 0;
        int cur_start = meetings.get(0).get(0);
        int cur_end = meetings.get(0).get(1);
        for (int i = 1; i < meetings.size(); ++i) {
            int s = meetings.get(i).get(0);
            int e = meetings.get(i).get(1);
            if (s <= cur_end) {
                if (e > cur_end) {
                    cur_end = e;
                }
            } else {
                covered += cur_end - cur_start + 1;
                cur_start = s;
                cur_end = e;
            }
        }
        covered += cur_end - cur_start + 1;
        int free_days = days - covered;
        return free_days > 0 ? free_days : 0;
    }
}

