class Solution {
    private static final long MOD = 1000000007L;
    private static final long NEG = -(1L << 60);

    private static class Matrix {
        long[][] m = new long[2][2];

        Matrix() {
            this(0, 0, 0, 0);
        }

        Matrix(long a, long b, long c, long d) {
            m[0][0] = a;
            m[0][1] = b;
            m[1][0] = c;
            m[1][1] = d;
        }
    }

    private static Matrix multiply(Matrix A, Matrix B) {
        Matrix C = new Matrix(NEG, NEG, NEG, NEG);
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 2; ++j) {
                long best = NEG;
                for (int k = 0; k < 2; ++k) {
                    if (A.m[i][k] == NEG || B.m[k][j] == NEG) continue;
                    best = Math.max(best, A.m[i][k] + B.m[k][j]);
                }
                C.m[i][j] = best;
            }
        }
        return C;
    }

    private static class SegmentTree {
        int n;
        Matrix[] tree;

        SegmentTree(int[] arr) {
            n = arr.length;
            tree = new Matrix[4 * n];
            build(1, 0, n - 1, arr);
        }

        void update(int idx, int val) {
            update(1, 0, n - 1, idx, val);
        }

        Matrix queryAll() {
            return tree[1];
        }

        private void build(int node, int l, int r, int[] arr) {
            if (l == r) {
                long a = arr[l];
                tree[node] = new Matrix(0, 0, a, NEG);
                return;
            }
            int mid = (l + r) >> 1;
            build(node << 1, l, mid, arr);
            build(node << 1 | 1, mid + 1, r, arr);
            tree[node] = multiply(tree[node << 1 | 1], tree[node << 1]);
        }

        private void update(int node, int l, int r, int idx, int val) {
            if (l == r) {
                long a = val;
                tree[node] = new Matrix(0, 0, a, NEG);
                return;
            }
            int mid = (l + r) >> 1;
            if (idx <= mid) {
                update(node << 1, l, mid, idx, val);
            } else {
                update(node << 1 | 1, mid + 1, r, idx, val);
            }
            tree[node] = multiply(tree[node << 1 | 1], tree[node << 1]);
        }
    }

    public static int maximumSumQueries(int[] nums, int[][] queries) {
        SegmentTree seg = new SegmentTree(nums);
        long total = 0;
        for (int[] q : queries) {
            int pos = q[0];
            int x = q[1];
            seg.update(pos, x);
            Matrix root = seg.queryAll();
            long ans = Math.max(root.m[0][0], root.m[1][0]);
            total = (total + ans) % MOD;
        }
        return (int) total;
    }
}

