class Solution {
    public static long countGoodPairs(int[] nums1, int[] nums2, int k) {
        if (nums1.length == 0 || nums2.length == 0) return 0;
        int maxV = 0;
        for (int v : nums1) {
            if (v > maxV) maxV = v;
        }
        int[] freq = new int[maxV + 1];
        for (int v : nums1) {
            freq[v]++;
        }
        int[] cnt = new int[maxV + 1];
        for (int d = 1; d <= maxV; d++) {
            for (int mult = d; mult <= maxV; mult += d) {
                cnt[d] += freq[mult];
            }
        }
        long ans = 0;
        for (int b : nums2) {
            long target = (long) b * k;
            if (target <= maxV) {
                ans += cnt[(int) target];
            }
        }
        return ans;
    }
}

