class Solution {
    public static int maximumLength(int[] nums, int k) {
        List<HashMap<Integer, Integer>> dp = new ArrayList<>(k + 1);
        for (int i = 0; i <= k; i++) {
            dp.add(new HashMap<>());
        }
        int[] best = new int[k + 1];
        for (int x : nums) {
            int[] prevBest = best.clone();
            for (int t = 0; t <= k; t++) {
                int extend = dp.get(t).getOrDefault(x, 0);
                int cand1 = extend + 1;
                int cand2 = -1;
                if (t > 0) {
                    cand2 = prevBest[t - 1] + 1;
                }
                int newVal = cand1;
                if (cand2 > newVal) {
                    newVal = cand2;
                }
                if (newVal > extend) {
                    dp.get(t).put(x, newVal);
                    if (newVal > best[t]) {
                        best[t] = newVal;
                    }
                }
            }
        }
        int ans = 0;
        for (int t = 0; t <= k; t++) {
            if (best[t] > ans) {
                ans = best[t];
            }
        }
        return ans;
    }
}

