class Solution {
    public static int minAbsDifference(int[] nums, int k) {
        long best = Long.MAX_VALUE;
        List<Integer> cur = new ArrayList<>();
        for (int x : nums) {
            List<Integer> nxt = new ArrayList<>();
            nxt.add(x);
            for (int v : cur) {
                nxt.add(v | x);
            }
            Collections.sort(nxt);
            List<Integer> dedup = new ArrayList<>();
            for (int val : nxt) {
                if (dedup.isEmpty() || val != dedup.get(dedup.size() - 1)) {
                    dedup.add(val);
                }
            }
            cur = dedup;
            for (int v : cur) {
                long diff = Math.abs((long) k - v);
                if (diff < best) {
                    best = diff;
                }
            }
        }
        return (int) best;
    }
}

