class Solution {
    public static int maxLengthGoodSubsequence(int[] nums, int k) {
        @SuppressWarnings("unchecked")
        HashMap<Integer, Integer>[] dp = new HashMap[k + 1];
        for (int i = 0; i <= k; i++) {
            dp[i] = new HashMap<>();
        }
        for (int x : nums) {
            @SuppressWarnings("unchecked")
            HashMap<Integer, Integer>[] old = new HashMap[k + 1];
            for (int i = 0; i <= k; i++) {
                old[i] = new HashMap<>(dp[i]);
            }
            dp[0].put(x, Math.max(dp[0].getOrDefault(x, 0), 1));
            for (int c = 0; c <= k; c++) {
                for (Map.Entry<Integer, Integer> entry : old[c].entrySet()) {
                    int v = entry.getKey();
                    int len = entry.getValue();
                    int nc = c + (v != x ? 1 : 0);
                    if (nc <= k) {
                        HashMap<Integer, Integer> map = dp[nc];
                        map.put(x, Math.max(map.getOrDefault(x, 0), len + 1));
                    }
                }
            }
        }
        int ans = 0;
        for (int c = 0; c <= k; c++) {
            for (int val : dp[c].values()) {
                if (val > ans) {
                    ans = val;
                }
            }
        }
        return ans;
    }
}

