class Solution {
    private static class Fenwick {
        private final int[] bit;
        Fenwick(int n) {
            bit = new int[n + 1];
        }
        void add(int idx, int delta) {
            idx++; // 1‑based
            for (int i = idx; i < bit.length; i += i & -i) {
                bit[i] += delta;
            }
        }
        int sumPrefix(int idx) {
            idx++; // 1‑based
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
        int rangeSum(int l, int r) {
            if (l > r) return 0;
            int right = sumPrefix(r);
            int left = (l > 0) ? sumPrefix(l - 1) : 0;
            return right - left;
        }
    }

    public static List<Integer> countPeaks(int[] nums, int[][] queries) {
        int n = nums.length;
        Fenwick ft = new Fenwick(n);
        byte[] isPeak = new byte[n];
        for (int i = 1; i < n - 1; ++i) {
            byte peak = (byte) ((nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) ? 1 : 0);
            isPeak[i] = peak;
            if (peak == 1) ft.add(i, 1);
        }
        List<Integer> answer = new ArrayList<>();
        for (int[] q : queries) {
            int type = q[0];
            if (type == 1) {
                int l = q[1];
                int r = q[2];
                int left = l + 1;
                int right = r - 1;
                answer.add(ft.rangeSum(left, right));
            } else if (type == 2) {
                int pos = q[1];
                int val = q[2];
                nums[pos] = val;
                for (int i = pos - 1; i <= pos + 1; ++i) {
                    if (i <= 0 || i >= n - 1) continue;
                    byte newPeak = (byte) ((nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) ? 1 : 0);
                    if (newPeak != isPeak[i]) {
                        ft.add(i, newPeak - isPeak[i]);
                        isPeak[i] = newPeak;
                    }
                }
            }
        }
        return answer;
    }
}

class Solution {
