        int n = nums.length;
        int[] diff = new int[n];
        int curFlip = 0;
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            if (i >= k) {
                curFlip -= diff[i - k];
            }
            int currentBit = (nums[i] + curFlip) % 2;
            if (currentBit == 0) {
                if (i + k > n) {
                    return -1;
                }
                diff[i] = 1;
                curFlip += 1;
                ++ans;
            }
        }
        return ans;
    }
