        }
        int maxCnt = 0;
        for (List<Integer> r : requirements) {
            int endi = r.get(0);
            int cnti = r.get(1);
            reqCnt[endi] = cnti;
            if (cnti > maxCnt) {
                maxCnt = cnti;
            }
        }
        int[][] dp = new int[n + 1][maxCnt + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            int[] pref = new int[maxCnt + 1];
            pref[0] = dp[i - 1][0];
            for (int k = 1; k <= maxCnt; k++) {
                int sum = pref[k - 1] + dp[i - 1][k];
                if (sum >= MOD) sum -= MOD;
                pref[k] = sum;
            }
            for (int k = 0; k <= maxCnt; k++) {
                int left = k - (i - 1);
                long val = pref[k];
                if (left > 0) {
                    val -= pref[left - 1];
                    if (val < 0) val += MOD;
                }
                dp[i][k] = (int) val;
            }
            int endIdx = i - 1;
            if (reqCnt[endIdx] != -1) {
                int need = reqCnt[endIdx];
                if (need > endIdx * (endIdx + 1) / 2) {
                    return 0;
                }
                for (int k = 0; k <= maxCnt; k++) {
                    if (k != need) {
                        dp[i][k] = 0;
                    }
                }
            }
        }
        int finalNeed = reqCnt[n - 1];
        if (finalNeed == -1) return 0;
        return dp[n][finalNeed];
    }
}

import java.util.*;

class Solution {
    public static long minAreaThreeRectangles(int[][] grid) {
        int R = grid.length;
        int C = grid[0].length;

        long ans = Long.MAX_VALUE;

        for (int i = 0; i < R - 2; ++i) {
            for (int j = i + 1; j < R - 1; ++j) {
                long a1 = box(grid, R, C, 0, i, 0, C - 1);
                long a2 = box(grid, R, C, i + 1, j, 0, C - 1);
                long a3 = box(grid, R, C, j + 1, R - 1, 0, C - 1);
                if (a1 != -1 && a2 != -1 && a3 != -1) {
                    long sum = a1 + a2 + a3;
                    if (sum < ans) ans = sum;
                }
            }
        }

        for (int i = 0; i < C - 2; ++i) {
            for (int j = i + 1; j < C - 1; ++j) {
                long a1 = box(grid, R, C, 0, R - 1, 0, i);
                long a2 = box(grid, R, C, 0, R - 1, i + 1, j);
                long a3 = box(grid, R, C, 0, R - 1, j + 1, C - 1);
                if (a1 != -1 && a2 != -1 && a3 != -1) {
                    long sum = a1 + a2 + a3;
                    if (sum < ans) ans = sum;
                }
            }
        }

        for (int r = 0; r < R - 1; ++r) {
            for (int c = 0; c < C - 1; ++c) {
                long tl = box(grid, R, C, 0, r, 0, c);
                long tr = box(grid, R, C, 0, r, c + 1, C - 1);
                long bl = box(grid, R, C, r + 1, R - 1, 0, c);
                long br = box(grid, R, C, r + 1, R - 1, c + 1, C - 1);
                boolean[] has = { tl != -1, tr != -1, bl != -1, br != -1 };
                int cnt = (has[0] ? 1 : 0) + (has[1] ? 1 : 0) + (has[2] ? 1 : 0) + (has[3] ? 1 : 0);
                if (cnt == 3) {
                    long sum = (has[0] ? tl : 0) + (has[1] ? tr : 0) + (has[2] ? bl : 0) + (has[3] ? br : 0);
                    if (sum < ans) ans = sum;
                }
            }
        }

        return ans;
    }

    private static long box(int[][] grid, int R, int C, int r1, int r2, int c1, int c2) {
        int minR = R, maxR = -1, minC = C, maxC = -1;
        for (int i = r1; i <= r2; ++i) {
            for (int j = c1; j <= c2; ++j) {
                if (grid[i][j] == 1) {
                    if (i < minR) minR = i;
                    if (i > maxR) maxR = i;
                    if (j < minC) minC = j;
                    if (j > maxC) maxC = j;
                }
            }
        }
        if (maxR == -1) return -1;
        long area = (long) (maxR - minR + 1) * (long) (maxC - minC + 1);
        return area;
    }
}

public class Solution {
    public static int maxHeight(int red, int blue) {
        long total = (long) red + (long) blue;
        long low = 0, high = 1;
        while (high * (high + 1) / 2 <= total) {
            high++;
        }
        while (low < high) {
            long mid = (low + high + 1) / 2;
            long oddRows = (mid + 1) / 2;
            long evenRows = mid / 2;
            long oddBalls = oddRows * oddRows;
            long evenBalls = evenRows * (evenRows + 1);
            boolean ok = ((long) red >= oddBalls && (long) blue >= evenBalls) ||
                         ((long) blue >= oddBalls && (long) red >= evenBalls);
            if (ok) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return (int) low;
    }
}

public class Solution {
    public static int minArea(int[][] grid) {
        int rows = grid.length;
        int cols = rows > 0 ? grid[0].length : 0;
        int top = rows, bottom = -1, left = cols, right = -1;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == 1) {
                    if (r < top) top = r;
                    if (r > bottom) bottom = r;
                    if (c < left) left = c;
                    if (c > right) right = c;
                }
            }
        }
        if (bottom == -1) return 0;
        int height = bottom - top + 1;
        int width = right - left + 1;
        return height * width;
    }
}

