class Solution {
    public static int maxPointsAfterEnemyBattles(int[] enemyEnergies, int currentEnergy) {
        int n = enemyEnergies.length;
        long totalSum = 0;
        for (int i = 0; i < n; i++) {
            totalSum += enemyEnergies[i];
        }
        int maxPoints = 0;
        for (int i = 0; i < n; i++) {
            int energyKept = enemyEnergies[i];
            long totalEnergy = currentEnergy + totalSum - energyKept;
            int points = (int) (totalEnergy / energyKept);
            if (points > maxPoints) {
                maxPoints = points;
            }
        }
        return maxPoints;
    }
}

