import java.util.*;

class Solution {
    private static class DiaRad {
        int diameter;
        int radius;
        DiaRad(int diameter, int radius) {
            this.diameter = diameter;
            this.radius = radius;
        }
    }

    private static class BFSResult {
        int far;
        int[] dist;
        BFSResult(int far, int[] dist) {
            this.far = far;
            this.dist = dist;
        }
    }

    private static DiaRad getDiameterAndRadius(List<List<Integer>> edges) {
        int n = edges.size() + 1;
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (List<Integer> e : edges) {
            int u = e.get(0);
            int v = e.get(1);
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        BFSResult first = bfs(0, adj, n);
        BFSResult second = bfs(first.far, adj, n);
        int diameter = second.dist[second.far];
        int radius = (diameter + 1) / 2;
        return new DiaRad(diameter, radius);
    }

    private static BFSResult bfs(int start, List<List<Integer>> adj, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        int[] q = new int[n];
        int head = 0, tail = 0;
        q[tail++] = start;
        dist[start] = 0;
        int far = start;
        while (head < tail) {
            int cur = q[head++];
            for (int nb : adj.get(cur)) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    q[tail++] = nb;
                    if (dist[nb] > dist[far]) {
                        far = nb;
                    }
                }
            }
        }
        return new BFSResult(far, dist);
    }

    public static int findMinDiameter(List<List<Integer>> edges1, List<List<Integer>> edges2) {
        DiaRad t1 = getDiameterAndRadius(edges1);
        DiaRad t2 = getDiameterAndRadius(edges2);
        int candidate = t1.radius + 1 + t2.radius;
        return Math.max(Math.max(t1.diameter, t2.diameter), candidate);
    }
}

