class Solution {
    public static long countSubarrays(int[] nums, int k) {
        long answer = 0;
        List<int[]> prev = new ArrayList<>();
        for (int x : nums) {
            List<int[]> cur = new ArrayList<>();
            cur.add(new int[]{x, 1});
            for (int[] pair : prev) {
                int newVal = pair[0] & x;
                int[] last = cur.get(cur.size() - 1);
                if (newVal == last[0]) {
                    last[1] += pair[1];
                } else {
                    cur.add(new int[]{newVal, pair[1]});
                }
            }
            for (int[] pair : cur) {
                if (pair[0] == k) {
                    answer += pair[1];
                }
            }
            prev = cur;
        }
        return answer;
    }
}

