public class P3 {
    static long countSubmatrices(char[][] grid) {
        int rows = grid.length;
        int cols = rows > 0 ? grid[0].length : 0;
        long[][] prefX = new long[rows+1][cols+1];
        long[][] prefY = new long[rows+1][cols+1];
        long ans = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                long x = grid[i][j] == 'X' ? 1 : 0;
                long y = grid[i][j] == 'Y' ? 1 : 0;
                prefX[i+1][j+1] = prefX[i][j+1] + prefX[i+1][j] - prefX[i][j] + x;
                prefY[i+1][j+1] = prefY[i][j+1] + prefY[i+1][j] - prefY[i][j] + y;
                if (prefX[i+1][j+1] == prefY[i+1][j+1] && prefX[i+1][j+1] >= 1) ans++;
            }
        }
        return ans;
    }

    public static void main(String[] args) {
