class Solution {
    public static int count_alternating_groups(List<Integer> colors) {
        int n = colors.size();
        if (n < 3) {
            return 0;
        }
        int groups = 0;
        for (int i = 0; i < n; ++i) {
            int left = (i - 1 + n) % n;
            int right = (i + 1) % n;
            if (!colors.get(i).equals(colors.get(left)) && colors.get(left).equals(colors.get(right))) {
                ++groups;
            }
        }
        return groups;
    }
}

