public class Solution {
    public static int constructString(String target, List<String> words, List<Integer> costs) {
        int n = target.length();
        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i < n; ++i) {
            if (dp[i] == INF) continue;
            for (int w = 0; w < words.size(); ++w) {
                String word = words.get(w);
                int len = word.length();
                if (i + len > n) continue;
                if (target.regionMatches(i, word, 0, len)) {
                    int newCost = dp[i] + costs.get(w);
                    if (newCost < dp[i + len]) {
                        dp[i + len] = newCost;
                    }
                }
            }
        }
        return dp[n] == INF ? -1 : dp[n];
    }
}

