class Solution {
    public static long minCost(int m, int n, long[] horizontalCut, long[] verticalCut) {
        Long[] h = new Long[horizontalCut.length];
        for (int i = 0; i < horizontalCut.length; i++) {
            h[i] = horizontalCut[i];
        }
        Long[] v = new Long[verticalCut.length];
        for (int i = 0; i < verticalCut.length; i++) {
            v[i] = verticalCut[i];
        }
        Arrays.sort(h, Collections.reverseOrder());
        Arrays.sort(v, Collections.reverseOrder());

        int i = 0, j = 0;
        long horizPieces = 1, vertPieces = 1;
        long total = 0;

        while (i < h.length && j < v.length) {
            if (h[i] > v[j]) {
                total += h[i] * vertPieces;
                horizPieces++;
                i++;
            } else {
                total += v[j] * horizPieces;
                vertPieces++;
                j++;
            }
        }

        while (i < h.length) {
            total += h[i] * vertPieces;
            i++;
        }

        while (j < v.length) {
            total += v[j] * horizPieces;
            j++;
        }

        return total;
    }
}

