class Solution {
    public static String lexicographicallySmallestString(String s) {
        int n = s.length();
        char[] arr = s.toCharArray();
        for (int i = 0; i + 1 < n; ++i) {
            int d1 = arr[i] - '0';
            int d2 = arr[i + 1] - '0';
            if ((d1 % 2) == (d2 % 2) && d2 < d1) {
                char tmp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = tmp;
                break;
