class Solution {
    public static int minimumLengthAfterOperations(String s) {
        StringBuilder stack = new StringBuilder();
        for (char ch : s.toCharArray()) {
            stack.append(ch);
            while (stack.length() >= 2) {
                char a = stack.charAt(stack.length()-2), b = stack.charAt(stack.length()-1);
                if ((a=='a'&&b=='b')||(a=='b'&&b=='c')) { stack.setLength(stack.length()-2); }
                else break;
            }
        }
        return stack.length();
    }
}

class Solution {
    public int minChanges(int[] nums, int k) {
        int n = nums.length;
        int[] d = new int[k + 2];
        for (int i = 0; i < n / 2; i++) {
            int x = nums[i], y = nums[n - 1 - i];
            if (x > y) { int t = x; x = y; y = t; }
            d[0] += 1;
            d[y - x] -= 1;
            d[y - x + 1] += 1;
            int idx = Math.max(y, k - x) + 1;
            d[idx] += 1;
        }
        int ans = n, s = 0;
        for (int v : d) {
            s += v;
            ans = Math.min(ans, s);
        }
        return ans;
    }
}

public class Solution {
    public static int number_of_bit_changes(int n, int k) {
        if ((n & k) != k) {
            return -1;
        }
        int diff = n ^ k;
        int changes = 0;
        while (diff != 0) {
            diff &= diff - 1;
            changes++;
        }
        return changes;
    }
}

