import java.util.Arrays;

public class Solution {
    public static long countNotSpecial(long l, long r) {
        long total = r - l + 1;
        long low = (long) Math.ceil(Math.sqrt((double) l));
        long high = (long) Math.floor(Math.sqrt((double) r));
        if (low > high) return total;
        int size = (int) (high + 1);
        boolean[] isPrime = new boolean[size];
        Arrays.fill(isPrime, true);
        if (high >= 0) isPrime[0] = false;
        if (high >= 1) isPrime[1] = false;
        long limit = (long) Math.floor(Math.sqrt((double) high));
        for (long i = 2; i <= limit; ++i) {
            if (isPrime[(int) i]) {
                for (long j = i * i; j <= high; j += i) {
                    isPrime[(int) j] = false;
                }
            }
        }
        long primeSquareCount = 0;
        for (long p = low; p <= high; ++p) {
            if (isPrime[(int) p]) ++primeSquareCount;
        }
        return total - primeSquareCount;
    }
}

