public class Solution {
    public static int minFlips(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        int rowFlips = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (grid[i][j] != grid[i][n - 1 - j]) {
                    rowFlips++;
                }
            }
        }
        int colFlips = 0;
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < m / 2; i++) {
                if (grid[i][j] != grid[m - 1 - i][j]) {
                    colFlips++;
                }
            }
        }
        return Math.min(rowFlips, colFlips);
    }
}

import java.util.*;

class Solution {
    static class DSU {
        int[] parent;
        int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (rank[a] < rank[b]) {
                int t = a;
                a = b;
                b = t;
            }
            parent[b] = a;
            if (rank[a] == rank[b]) rank[a]++;
        }
    }

    public static boolean isPathPossible(int xCorner, int yCorner, int[][] circles) {
        int n = circles.length;
        int leftIdx = n;
        int rightIdx = n + 1;
        int bottomIdx = n + 2;
        int topIdx = n + 3;
        DSU dsu = new DSU(n + 4);

        for (int i = 0; i < n; i++) {
            long cx = circles[i][0];
            long cy = circles[i][1];
            long cr = circles[i][2];

            long dxStart = cx;
            long dyStart = cy;
            if (dxStart * dxStart + dyStart * dyStart <= cr * cr) return false;

            long dxEnd = cx - xCorner;
            long dyEnd = cy - yCorner;
            if (dxEnd * dxEnd + dyEnd * dyEnd <= cr * cr) return false;

            // left wall (x = 0)
            double dx = cx;
            if (dx <= cr) {
                double dy = Math.sqrt((double) cr * cr - dx * dx);
                if (cy + dy >= 0 && cy - dy <= yCorner) dsu.unite(i, leftIdx);
            }
            // right wall (x = xCorner)
            dx = xCorner - cx;
            if (dx <= cr) {
                double dy = Math.sqrt((double) cr * cr - dx * dx);
                if (cy + dy >= 0 && cy - dy <= yCorner) dsu.unite(i, rightIdx);
            }
            // bottom wall (y = 0)
            double dy = cy;
            if (dy <= cr) {
                double dx2 = Math.sqrt((double) cr * cr - dy * dy);
                if (cx + dx2 >= 0 && cx - dx2 <= xCorner) dsu.unite(i, bottomIdx);
            }
            // top wall (y = yCorner)
            dy = yCorner - cy;
            if (dy <= cr) {
                double dx2 = Math.sqrt((double) cr * cr - dy * dy);
                if (cx + dx2 >= 0 && cx - dx2 <= xCorner) dsu.unite(i, topIdx);
            }
        }

        for (int i = 0; i < n; i++) {
            long xi = circles[i][0];
            long yi = circles[i][1];
            long ri = circles[i][2];
            for (int j = i + 1; j < n; j++) {
                long xj = circles[j][0];
                long yj = circles[j][1];
                long rj = circles[j][2];
                long dx = xi - xj;
                long dy = yi - yj;
                long dist2 = dx * dx + dy * dy;
                long radSum = ri + rj;
                if (dist2 <= radSum * radSum) dsu.unite(i, j);
            }
        }

        if (dsu.find(leftIdx) == dsu.find(rightIdx)) return false;
        if (dsu.find(bottomIdx) == dsu.find(topIdx)) return false;
        if (dsu.find(leftIdx) == dsu.find(bottomIdx)) return false;
        if (dsu.find(rightIdx) == dsu.find(topIdx)) return false;
        return true;
    }
}

