class Solution {
    public static int numberOfWinningPlayers(int n, List<List<Integer>> pick) {
        @SuppressWarnings("unchecked")
        HashMap<Integer, Integer>[] cnt = new HashMap[n];
        for (int i = 0; i < n; i++) {
            cnt[i] = new HashMap<>();
        }
        for (List<Integer> p : pick) {
            int x = p.get(0);
            int y = p.get(1);
            HashMap<Integer, Integer> map = cnt[x];
            map.put(y, map.getOrDefault(y, 0) + 1);
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (Map.Entry<Integer, Integer> entry : cnt[i].entrySet()) {
                if (entry.getValue() > i) {
                    ans++;
                    break;
                }
            }
        }
        return ans;
    }
}

import java.util.*;
class Solution {
    public static int[] timeTaken(int[][] edges) {
        int n = edges.length + 1;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] result = new int[n];
        for (int src = 0; src < n; src++) {
            int[] dist = new int[n];
            Arrays.fill(dist, -1);
            dist[src] = 0;
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(src);
            int maxDist = 0;
            while (!stack.isEmpty()) {
                int cur = stack.pop();
                for (int nb : adj.get(cur)) {
                    if (dist[nb] == -1) {
                        int w = (nb % 2 == 0) ? 2 : 1;
                        dist[nb] = dist[cur] + w;
                        if (dist[nb] > maxDist) maxDist = dist[nb];
                        stack.push(nb);
                    }
                }
            }
            result[src] = maxDist;
        }
        return result;
    }
}

