class Solution {
    public static int minFlips(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        List<Integer> sizes = new ArrayList<>();
        List<Integer> onesCount = new ArrayList<>();
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (visited[i][j]) continue;
                int[] xs = {i, i, m - 1 - i, m - 1 - i};
                int[] ys = {j, n - 1 - j, j, n - 1 - j};
                int sz = 0;
                int ones = 0;
                for (int k = 0; k < 4; ++k) {
                    int x = xs[k];
                    int y = ys[k];
                    if (!visited[x][y]) {
                        visited[x][y] = true;
                        sz++;
                        ones += grid[x][y];
                    }
                }
                sizes.add(sz);
                onesCount.add(ones);
            }
        }
        long INF = 1L << 60;
        long[] dp = new long[4];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int idx = 0; idx < sizes.size(); ++idx) {
            int sz = sizes.get(idx);
            int ones = onesCount.get(idx);
            long cost0 = ones;
            long cost1 = sz - ones;
            long[] ndp = new long[4];
            Arrays.fill(ndp, INF);
            for (int mod = 0; mod < 4; ++mod) {
                if (dp[mod] == INF) continue;
                ndp[mod] = Math.min(ndp[mod], dp[mod] + cost0);
                int nmod = (mod + sz) % 4;
                ndp[nmod] = Math.min(ndp[nmod], dp[mod] + cost1);
            }
            dp = ndp;
        }
        return (int) dp[0];
    }
}

