class Solution {
    public static List<Double> shortest_distance_after_road_addition_queries_ii(int n, List<int[]> queries) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        List<Double> results = new ArrayList<>();
        double INF = Double.POSITIVE_INFINITY;
        for (int[] q : queries) {
            int l = q[0];
            int r = q[1];
            adj.get(l).add(r);
            double[] dist = new double[n];
            Arrays.fill(dist, INF);
            dist[0] = 0.0;
            for (int i = 0; i < n; i++) {
                if (i + 1 < n && dist[i] + 1.0 < dist[i + 1]) {
                    dist[i + 1] = dist[i] + 1.0;
                }
                for (int to : adj.get(i)) {
                    if (dist[i] + 1.0 < dist[to]) {
                        dist[to] = dist[i] + 1.0;
                    }
                }
            }
            results.add(dist[n - 1]);
        }
        return results;
    }
}

