public class Solution {
    public static int snakePosition(int n, List<String> commands) {
        int row = 0, col = 0;
        for (String cmd : commands) {
            if (cmd.equals("UP")) {
                row--;
            } else if (cmd.equals("DOWN")) {
                row++;
            } else if (cmd.equals("LEFT")) {
                col--;
            } else if (cmd.equals("RIGHT")) {
                col++;
            }
        }
        return row * n + col;
    }
}

import java.util.*;

class Solution {
    private static int good;

    public static int countGoodNodes(List<List<Integer>> edges) {
        int n = edges.size() + 1;
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (List<Integer> e : edges) {
            int a = e.get(0);
            int b = e.get(1);
            adj.get(a).add(b);
            adj.get(b).add(a);
        }
        good = 0;
        dfs(0, -1, adj);
        return good;
    }

    private static int dfs(int u, int parent, List<List<Integer>> adj) {
        List<Integer> childSizes = new ArrayList<>();
        for (int v : adj.get(u)) {
            if (v == parent) continue;
            int sz = dfs(v, u, adj);
            childSizes.add(sz);
        }
        boolean isGood = true;
        if (!childSizes.isEmpty()) {
            int first = childSizes.get(0);
            for (int i = 1; i < childSizes.size(); i++) {
                if (childSizes.get(i) != first) {
                    isGood = false;
                    break;
                }
            }
        }
        if (isGood) good++;
        int total = 1;
        for (int s : childSizes) total += s;
        return total;
    }
}

import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static int find_smallest_missing_integer(int[] nums) {
        long longest_prefix_sum = 0;
        int longest_prefix_length = 0;
        int n = nums.length;
        for (int i = 0; i < n; ++i) {
            long current_prefix_sum = 0;
            int current_prefix_length = 0;
            for (int j = i; j < n; ++j) {
                if (j == i || nums[j] == nums[j - 1] + 1) {
                    current_prefix_sum += nums[j];
                    ++current_prefix_length;
                } else {
                    break;
                }
            }
            if (current_prefix_length > longest_prefix_length) {
                longest_prefix_length = current_prefix_length;
                longest_prefix_sum = current_prefix_sum;
            }
        }
        Set<Integer> num_set = new HashSet<>();
        for (int v : nums) {
            num_set.add(v);
        }
        long smallest_missing_integer = longest_prefix_sum;
        while (num_set.contains((int) smallest_missing_integer)) {
            ++smallest_missing_integer;
        }
        return (int) smallest_missing_integer;
    }
}

import java.util.*;
class NeighborSum {
    int n;
    List<List<Integer>> grid;
    Map<Integer,int[]> pos = new HashMap<>();
    public NeighborSum(List<List<Integer>> grid) {
        this.grid = grid;
        this.n = grid.size();
        for (int i = 0; i < n; i++) for (int j = 0; j < grid.get(i).size(); j++) pos.put(grid.get(i).get(j), new int[]{i,j});
    }
    public int adjacentSum(int value) {
        int[] p = pos.get(value);
        if (p == null) return 0;
        int i = p[0], j = p[1];
        int total = 0;
        if (i > 0) total += grid.get(i-1).get(j);
        if (i < n-1) total += grid.get(i+1).get(j);
        if (j > 0) total += grid.get(i).get(j-1);
        if (j < grid.get(i).size()-1) total += grid.get(i).get(j+1);
        return total;
    }
}

import java.util.*;

public class Solution {
    public static int countMonotonicPairs(int[] nums) {
        final int MOD = 1000000007;
        final int MAX = 50;
        int[] dp = new int[MAX + 1];
        for (int v = 0; v <= nums[0]; ++v) {
            dp[v] = 1;
        }
        for (int i = 0; i + 1 < nums.length; ++i) {
            int diff = nums[i + 1] - nums[i];
            int need = diff > 0 ? diff : 0;
            int[] pref = new int[MAX + 1];
            pref[0] = dp[0];
            for (int v = 1; v <= MAX; ++v) {
                pref[v] = (pref[v - 1] + dp[v]) % MOD;
            }
            int[] next = new int[MAX + 1];
            for (int v = 0; v <= nums[i + 1]; ++v) {
                int limit = v - need;
                if (limit >= 0) {
                    next[v] = pref[limit];
                }
            }
            dp = next;
        }
        int ans = 0;
        int last = nums[nums.length - 1];
        for (int v = 0; v <= last; ++v) {
            ans = (ans + dp[v]) % MOD;
        }
        return ans;
    }
}

import java.lang.Math;

class Solution {
    public static long countDominantOnes(String s) {
        int n = s.length();
        int[] prefOnes = new int[n + 1];
        int[] prefZeros = new int[n + 1];
        for (int i = 0; i < n; ++i) {
            prefOnes[i + 1] = prefOnes[i] + (s.charAt(i) == '1' ? 1 : 0);
            prefZeros[i + 1] = prefZeros[i] + (s.charAt(i) == '0' ? 1 : 0);
        }
        int maxZeros = (int)Math.floor(Math.sqrt((double)n));
        long ans = 0;
        for (int r = 0; r < n; ++r) {
            for (int l = r; l >= 0; --l) {
                int zeros = prefZeros[r + 1] - prefZeros[l];
                if (zeros > maxZeros) break;
                int ones = prefOnes[r + 1] - prefOnes[l];
                if (ones >= zeros * zeros) ++ans;
            }
        }
        return ans;
    }
}

