class Solution {
    public static int[] shortestDistanceAfterRoadAdditionQueriesI(int n, List<List<Integer>> queries) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            adj.get(i).add(i + 1);
        }
        List<Integer> result = new ArrayList<>();
        for (List<Integer> q : queries) {
            int u = q.get(0);
            int v = q.get(1);
            adj.get(u).add(v);
            final int INF = Integer.MAX_VALUE;
            int[] dist = new int[n];
            Arrays.fill(dist, INF);
            Queue<Integer> queue = new ArrayDeque<>();
            dist[0] = 0;
            queue.add(0);
            while (!queue.isEmpty()) {
                int cur = queue.poll();
                int d = dist[cur];
                for (int nxt : adj.get(cur)) {
                    if (dist[nxt] > d + 1) {
                        dist[nxt] = d + 1;
                        queue.add(nxt);
                    }
                }
            }
            result.add(dist[n - 1]);
        }
        int[] resArray = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            resArray[i] = result.get(i);
        }
        return resArray;
    }
}

public class Solution {
    public static long minOperations(int[] nums, int[] target) {
        int n = nums.length;
        long prev = 0;
        long ops = 0;
        for (int i = 0; i < n; i++) {
            long diff = (long) target[i] - (long) nums[i];
            long delta = diff - prev;
            if (delta > 0) {
                ops += delta;
            }
            prev = diff;
        }
        return ops;
    }
}

