class Solution {
    public static long[] alternatingGroups(int[] colors, int[][] queries) {
        int n = colors.length;
        int[] diff = new int[n];
        for (int i = 0; i < n; ++i) {
            diff[i] = (colors[i] != colors[(i + 1) % n]) ? 1 : 0;
        }
        List<Long> result = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int k = q[1];
                int L = k - 1;
                long ans = 0;
                int cur = 0;
                for (int i = 0; i < 2 * n; ++i) {
                    int idx = i % n;
                    if (diff[idx] == 1) {
                        ++cur;
                    } else {
                        cur = 0;
                    }
                    if (cur >= L) {
                        int start = i - (L - 1);
                        if (start < n) {
                            ++ans;
                        }
                    }
                }
                result.add(ans);
            } else {
                int i = q[1];
                int v = q[2];
                if (colors[i] == v) {
                    continue;
                }
                colors[i] = v;
                int left = (i - 1 + n) % n;
                diff[left] = (colors[left] != colors[i]) ? 1 : 0;
                diff[i] = (colors[i] != colors[(i + 1) % n]) ? 1 : 0;
            }
        }
        long[] out = new long[result.size()];
        for (int i = 0; i < result.size(); ++i) {
            out[i] = result.get(i);
        }
        return out;
    }
}

import java.util.*;

class Solution {
    private static class Pair {
        int col;
        long val;
        Pair(int col, long val) {
            this.col = col;
            this.val = val;
        }
    }

    public static long maximumValueSum(int[][] board) {
        int m = board.length;
        int n = board[0].length;
        List<List<Pair>> top = new ArrayList<>(m);
        for (int i = 0; i < m; ++i) {
            List<Pair> cells = new ArrayList<>(n);
            for (int j = 0; j < n; ++j) {
                cells.add(new Pair(j, board[i][j]));
            }
            cells.sort((a, b) -> Long.compare(b.val, a.val));
            int limit = Math.min(3, n);
            top.add(new ArrayList<>(cells.subList(0, limit)));
        }
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                for (int k = j + 1; k < m; ++k) {
                    for (Pair a : top.get(i)) {
                        for (Pair b : top.get(j)) {
                            if (b.col == a.col) continue;
                            for (Pair c : top.get(k)) {
                                if (c.col == a.col || c.col == b.col) continue;
                                long sum = a.val + b.val + c.val;
                                if (sum > ans) ans = sum;
                            }
                        }
                    }
                }
            }
        }
        return ans;
    }
}

