class Solution {
    public static long countKConstraintSubstrings(String s, int k) {
        int n = s.length();
        long ans = 0;
        for (int i = 0; i < n; ++i) {
            int zeros = 0;
            int ones = 0;
            for (int j = i; j < n; ++j) {
                if (s.charAt(j) == '0') ++zeros;
                else ++ones;
                if (zeros <= k || ones <= k) ++ans;
            }
        }
        return ans;
    }
}

