class Solution {
    public static int[] findPowerOfKSizeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n - k + 1];
        for (int i = 0; i <= n - k; i++) {
            boolean increasing = true;
            for (int j = i + 1; j < i + k; j++) {
                if (nums[j] <= nums[j - 1]) {
                    increasing = false;
                    break;
                }
            }
            result[i] = increasing ? nums[i + k - 1] : -1;
        }
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public static long maximumValueSum(int[][] board) {
        int m = board.length;
        int n = board[0].length;
        long NEG_INF = Long.MIN_VALUE / 4;
        long answer = NEG_INF;

        if (m <= n) {
            for (int i = 0; i < m; ++i) {
                for (int j = i + 1; j < m; ++j) {
                    for (int k = j + 1; k < m; ++k) {
                        int[] rows = {i, j, k};
                        long[] dp = new long[8];
                        Arrays.fill(dp, NEG_INF);
                        dp[0] = 0;
                        for (int col = 0; col < n; ++col) {
                            long[] ndp = dp.clone();
                            for (int mask = 0; mask < 8; ++mask) {
                                if (dp[mask] == NEG_INF) continue;
                                for (int r = 0; r < 3; ++r) {
                                    if ((mask & (1 << r)) != 0) continue;
                                    int nmask = mask | (1 << r);
                                    long val = dp[mask] + (long) board[rows[r]][col];
                                    if (val > ndp[nmask]) ndp[nmask] = val;
                                }
                            }
                            dp = ndp;
                        }
                        if (dp[7] > answer) answer = dp[7];
                    }
                }
            }
        } else {
            for (int c1 = 0; c1 < n; ++c1) {
                for (int c2 = c1 + 1; c2 < n; ++c2) {
                    for (int c3 = c2 + 1; c3 < n; ++c3) {
                        int[] cols = {c1, c2, c3};
                        long[] dp = new long[8];
                        Arrays.fill(dp, NEG_INF);
                        dp[0] = 0;
                        for (int row = 0; row < m; ++row) {
                            long[] ndp = dp.clone();
                            for (int mask = 0; mask < 8; ++mask) {
                                if (dp[mask] == NEG_INF) continue;
                                for (int c = 0; c < 3; ++c) {
                                    if ((mask & (1 << c)) != 0) continue;
                                    int nmask = mask | (1 << c);
                                    long val = dp[mask] + (long) board[row][cols[c]];
                                    if (val > ndp[nmask]) ndp[nmask] = val;
                                }
                            }
                            dp = ndp;
                        }
                        if (dp[7] > answer) answer = dp[7];
                    }
                }
            }
        }

        return answer;
    }
}

