public class Solution {
    public static int[] powerOfKSizeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] inc = new int[n];
        for (int i = 1; i < n; ++i) {
            inc[i] = nums[i] > nums[i - 1] ? 1 : 0;
        }
        int sumInc = 0;
        for (int i = 1; i < k; ++i) {
            sumInc += inc[i];
        }
        int[] results = new int[n - k + 1];
        int target = k - 1;
        for (int start = 0; start <= n - k; ++start) {
            if (sumInc == target) {
                results[start] = nums[start + k - 1];
            } else {
                results[start] = -1;
            }
            if (start < n - k) {
                int removeIdx = start + 1;
                int addIdx = start + k;
                sumInc = sumInc - inc[removeIdx] + inc[addIdx];
            }
        }
        return results;
    }
}

import java.util.*;

class Solution {
    static class Fenwick {
        int n;
        long[] bit;
        Fenwick(int size) {
            n = size;
            bit = new long[n + 1];
        }
        void add(int idx, long delta) {
            for (int i = idx; i <= n; i += i & -i) {
                bit[i] += delta;
            }
        }
        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
        long rangeSum(int l, int r) { // inclusive, 0‑based
            return sum(r + 1) - sum(l);
        }
    }

    static class Q {
        int l, r, idx;
        Q(int l, int r, int idx) {
            this.l = l;
            this.r = r;
            this.idx = idx;
        }
    }

    public static long[] countKConstraintSubstrings(String s, int k, int[][] queries) {
        int n = s.length();
        int[] r0 = new int[n];
        int[] r1 = new int[n];
        int right = -1;
        int zeros = 0;
        for (int left = 0; left < n; ++left) {
            while (right + 1 < n && zeros + (s.charAt(right + 1) == '0' ? 1 : 0) <= k) {
                ++right;
                if (s.charAt(right) == '0') ++zeros;
            }
            r0[left] = right;
            if (right >= left) {
                if (s.charAt(left) == '0') --zeros;
            } else {
                right = left - 1;
            }
        }
        right = -1;
        int ones = 0;
        for (int left = 0; left < n; ++left) {
            while (right + 1 < n && ones + (s.charAt(right + 1) == '1' ? 1 : 0) <= k) {
                ++right;
                if (s.charAt(right) == '1') ++ones;
            }
            r1[left] = right;
            if (right >= left) {
                if (s.charAt(left) == '1') --ones;
            } else {
                right = left - 1;
            }
        }
        int[] maxGood = new int[n];
        for (int i = 0; i < n; ++i) {
            maxGood[i] = Math.max(r0[i], r1[i]);
        }
        Fenwick bitCnt = new Fenwick(n);
        Fenwick bitSum = new Fenwick(n);
        Q[] qObjs = new Q[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            qObjs[i] = new Q(queries[i][0], queries[i][1], i);
        }
        Arrays.sort(qObjs, Comparator.comparingInt(a -> a.r));
        long[] ans = new long[queries.length];
        int pos = 0;
        for (Q q : qObjs) {
            while (pos < n && maxGood[pos] <= q.r) {
                bitCnt.add(pos + 1, 1);
                bitSum.add(pos + 1, maxGood[pos]);
                ++pos;
            }
            long len = (long) q.r - q.l + 1;
            long cntLe = bitCnt.rangeSum(q.l, q.r);
            long sumLe = bitSum.rangeSum(q.l, q.r);
            long cntGt = len - cntLe;
            long sumMin = sumLe + (long) q.r * cntGt;
            long sumI = ((long) q.l + q.r) * len / 2;
            ans[q.idx] = sumMin + len - sumI;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static class HeapNode {
        long value;
        int index;
        HeapNode(long value, int index) {
            this.value = value;
            this.index = index;
        }
    }

    private static void heapSwap(List<HeapNode> heap, int i, int j) {
        HeapNode tmp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, tmp);
    }

    private static boolean heapLess(HeapNode a, HeapNode b) {
        if (a.value != b.value) return a.value < b.value;
        return a.index < b.index;
    }

    private static void heapifyUp(List<HeapNode> heap, int pos) {
        while (pos > 0) {
            int parent = (pos - 1) >> 1;
            if (heapLess(heap.get(pos), heap.get(parent))) {
                heapSwap(heap, pos, parent);
                pos = parent;
            } else {
                break;
            }
        }
    }

    private static void heapifyDown(List<HeapNode> heap, int pos) {
        int size = heap.size();
        while (true) {
            int left = pos * 2 + 1;
            int right = left + 1;
            int smallest = pos;
            if (left < size && heapLess(heap.get(left), heap.get(smallest))) smallest = left;
            if (right < size && heapLess(heap.get(right), heap.get(smallest))) smallest = right;
            if (smallest != pos) {
                heapSwap(heap, pos, smallest);
                pos = smallest;
            } else {
                break;
            }
        }
    }

    public static long[] finalArrayState(long[] nums, long k, long multiplier) {
        int n = nums.length;
        if (n == 0) return new long[0];
        List<HeapNode> heap = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            heap.add(new HeapNode(nums[i], i));
            heapifyUp(heap, heap.size() - 1);
        }
        for (long op = 0; op < k; ++op) {
            HeapNode node = heap.get(0);
            node.value *= multiplier;
            nums[node.index] = node.value;
            heapifyDown(heap, 0);
        }
        return nums;
    }
}

