class Solution {
    public static int maxEnergyBoost(int[] energyDrinkA, int[] energyDrinkB) {
        int n = energyDrinkA.length;
        if (n == 0) return 0;
        int a = energyDrinkA[0];
        int b = energyDrinkB[0];
        int s = 0;
        for (int i = 1; i < n; i++) {
            int prevA = a;
            int prevB = b;
            int prevS = s;
            a = Math.max(prevA, prevS) + energyDrinkA[i];
            b = Math.max(prevB, prevS) + energyDrinkB[i];
            s = Math.max(prevA, Math.max(prevB, prevS));
        }
        return Math.max(a, Math.max(b, s));
    }
}

