class Solution {
    public static int countPairs(int[] nums) {
        int n = nums.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums[i] == nums[j]) {
                    count++;
                } else if (canSwapToEqual(nums[i], nums[j]) || canSwapToEqual(nums[j], nums[i])) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean canSwapToEqual(int from, int target) {
        char[] digits = Integer.toString(from).toCharArray();
        int len = digits.length;
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j < len; j++) {
                if (digits[i] == digits[j]) continue;
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
                int swapped = Integer.parseInt(new String(digits));
                if (swapped == target) {
                    return true;
                }
                // swap back
                digits[j] = digits[i];
                digits[i] = temp;
            }
        }
        return false;
    }
}

