class Solution {
    private static Map<Integer, Integer> generateDist(int num) {
        String s = Integer.toString(num);
        int L = s.length();
        Map<String, Integer> visited = new HashMap<>();
        Queue<String> q = new ArrayDeque<>();
        visited.put(s, 0);
        q.add(s);
        while (!q.isEmpty()) {
            String cur = q.poll();
            int d = visited.get(cur);
            if (d == 2) continue;
            char[] arr = cur.toCharArray();
            for (int i = 0; i < L; ++i) {
                for (int j = i + 1; j < L; ++j) {
                    char tmp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = tmp;
                    String nxt = new String(arr);
                    if (!visited.containsKey(nxt)) {
                        visited.put(nxt, d + 1);
                        q.add(nxt);
                    }
                    tmp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = tmp;
                }
            }
        }
        Map<Integer, Integer> result = new HashMap<>();
        for (Map.Entry<String, Integer> e : visited.entrySet()) {
            String str = e.getKey();
            int dist = e.getValue();
            int pos = 0;
            while (pos < str.length() && str.charAt(pos) == '0') pos++;
            String trimmed = pos == str.length() ? "" : str.substring(pos);
            int val = trimmed.isEmpty() ? 0 : Integer.parseInt(trimmed);
            result.merge(val, dist, Math::min);
        }
        return result;
    }

    public static long countAlmostEqualPairsII(int[] nums) {
        int n = nums.length;
        List<Map<Integer, Integer>> reachable = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            reachable.add(generateDist(nums[i]));
        }
        HashMap<Integer, ArrayList<int[]>> map = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            for (Map.Entry<Integer, Integer> e : reachable.get(i).entrySet()) {
                int val = e.getKey();
                int dist = e.getValue();
                map.computeIfAbsent(val, k -> new ArrayList<>()).add(new int[]{i, dist});
            }
        }
        HashSet<Long> seen = new HashSet<>();
        long ans = 0;
        for (ArrayList<int[]> list : map.values()) {
            int m = list.size();
            for (int a = 0; a < m; ++a) {
                int i = list.get(a)[0];
                int di = list.get(a)[1];
                for (int b = a + 1; b < m; ++b) {
                    int j = list.get(b)[0];
                    int dj = list.get(b)[1];
                    if (di + dj <= 2) {
                        long code = (long) i * n + j;
                        if (seen.add(code)) ++ans;
                    }
                }
            }
        }
        return ans;
    }
}

import java.util.PriorityQueue;
import java.util.Comparator;

public class Solution {
    private static long modPow(long base, long exp, long mod) {
        long result = 1 % mod;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return result;
    }

    private static class Node {
        double key;
        int idx;
        Node(double key, int idx) {
            this.key = key;
            this.idx = idx;
        }
    }

    public static int[] finalArrayState(int[] nums, long k, int multiplier) {
        final long MOD = 1000000007L;
        int n = nums.length;
        if (multiplier == 1 || k == 0) {
            int[] res = new int[n];
            for (int i = 0; i < n; ++i) {
                long v = nums[i] % MOD;
                if (v < 0) v += MOD;
                res[i] = (int) v;
            }
            return res;
        }

        long[] cnt = new long[n];
        double logM = Math.log((double) multiplier);
        double[] key = new double[n];
        for (int i = 0; i < n; ++i) {
            if (nums[i] == 0) {
                key[i] = Double.NEGATIVE_INFINITY;
            } else {
                double magnitude = Math.log((double) Math.abs((long) nums[i])) + cnt[i] * logM;
                key[i] = (nums[i] < 0) ? -magnitude : magnitude;
            }
        }

        PriorityQueue<Node> pq = new PriorityQueue<>(new Comparator<Node>() {
            @Override
            public int compare(Node a, Node b) {
                int cmp = Double.compare(a.key, b.key);
                if (cmp != 0) return cmp;
                return Integer.compare(a.idx, b.idx);
            }
        });
        for (int i = 0; i < n; ++i) {
            pq.add(new Node(key[i], i));
        }

        for (long step = 0; step < k; ++step) {
            Node cur = pq.poll();
            int i = cur.idx;
            cnt[i]++;
            if (nums[i] == 0) {
                cur.key = Double.NEGATIVE_INFINITY;
            } else {
                double magnitude = Math.log((double) Math.abs((long) nums[i])) + cnt[i] * logM;
                cur.key = (nums[i] < 0) ? -magnitude : magnitude;
            }
            pq.add(cur);
        }

        int[] result = new int[n];
        for (int i = 0; i < n; ++i) {
            long base = nums[i] % MOD;
            if (base < 0) base += MOD;
            long mult = modPow(multiplier, cnt[i], MOD);
            long val = (base * mult) % MOD;
            result[i] = (int) val;
        }
        return result;
    }
}

