import java.util.*;

class Solution {
    private static class MaxHeap {
        private final List<Integer> heap = new ArrayList<>();

        private void swap(int i, int j) {
            int t = heap.get(i);
            heap.set(i, heap.get(j));
            heap.set(j, t);
        }

        private void bubbleUp(int idx) {
            int i = idx;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (heap.get(p) >= heap.get(i)) break;
                swap(p, i);
                i = p;
            }
        }

        private void bubbleDown(int idx) {
            int i = idx;
            while (true) {
                int largest = i;
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                if (l < heap.size() && heap.get(l) > heap.get(largest)) largest = l;
                if (r < heap.size() && heap.get(r) > heap.get(largest)) largest = r;
                if (largest == i) break;
                swap(i, largest);
                i = largest;
            }
        }

        void push(int val) {
            heap.add(val);
            bubbleUp(heap.size() - 1);
        }

        int popMax() {
            int max = heap.get(0);
            int end = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, end);
                bubbleDown(0);
            }
            return max;
        }

        int peek() {
            return heap.get(0);
        }

        int size() {
            return heap.size();
        }
    }

    public static List<Integer> kthNearestObstacle(List<int[]> queries, int k) {
        MaxHeap heap = new MaxHeap();
        List<Integer> results = new ArrayList<>();
        for (int[] p : queries) {
            int dist = Math.abs(p[0]) + Math.abs(p[1]);
            if (heap.size() < k) {
                heap.push(dist);
            } else if (dist < heap.peek()) {
                heap.popMax();
                heap.push(dist);
            }
            results.add(heap.size() == k ? heap.peek() : -1);
        }
        return results;
    }
}

