class Solution {
    public static int maxScore(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int maxMask = 1 << cols;
        final int NEG = -Integer.MAX_VALUE;
        int[] dp = new int[maxMask];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int i = 0; i < rows; i++) {
            int[] ndp = dp.clone();
            for (int mask = 0; mask < maxMask; mask++) {
                if (dp[mask] == NEG) continue;
                for (int j = 0; j < cols; j++) {
                    if ((mask & (1 << j)) == 0) {
                        int nmask = mask | (1 << j);
                        ndp[nmask] = Math.max(ndp[nmask], dp[mask] + grid[i][j]);
                    }
                }
            }
            dp = ndp;
        }
        int ans = 0;
        for (int mask = 1; mask < maxMask; mask++) {
            ans = Math.max(ans, dp[mask]);
        }
        return ans;
    }
}

class Solution {
    public static long[] maximumSubarrayXor(int[] nums, int[][] queries) {
        int n = nums.length;
        long[][] score = new long[n][n];
        long[][] best = new long[n][n];
        for (int i = 0; i < n; i++) { score[i][i] = nums[i]; best[i][i] = nums[i]; }
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                score[i][j] = score[i][j-1] ^ score[i+1][j];
                best[i][j] = Math.max(score[i][j], Math.max(best[i][j-1], best[i+1][j]));
            }
        }
        long[] result = new long[queries.length];
        for (int k = 0; k < queries.length; k++) result[k] = best[queries[k][0]][queries[k][1]];
        return result;
    }
}

import java.util.*;

class Solution {
    static long answer = 0;
    static int[] cnt = new int[10];
    static long[] fact;
    static int N, K;

    public static long countGoodIntegers(int n, int k) {
        N = n; K = k;
        answer = 0;
        fact = new long[n+1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i-1]*i;
        cnt = new int[10];
        dfs(0, n);
        return answer;
    }

    static void dfs(int digit, int remaining) {
        if (digit == 10) {
            if (remaining != 0) return;
            int oddCnt = 0;
            for (int c : cnt) oddCnt += (c % 2);
            if (oddCnt > 1) return;
            int halfLen = N / 2;
            int[] halfCounts = new int[10];
            for (int d = 0; d < 10; d++) halfCounts[d] = cnt[d] / 2;
            int middleDigit = -1;
            for (int d = 0; d < 10; d++) if (cnt[d] % 2 == 1) { middleDigit = d; break; }
            int[] halfPerm = new int[halfLen];
            int[] used = new int[10];
            boolean[] found = {false};
            backtrack(0, halfLen, halfCounts, middleDigit, halfPerm, used, found);
            return;
        }
        for (int c = 0; c <= remaining; c++) {
            cnt[digit] = c;
            dfs(digit+1, remaining-c);
        }
        cnt[digit] = 0;
    }

    static void backtrack(int pos, int halfLen, int[] halfCounts, int middleDigit, int[] halfPerm, int[] used, boolean[] found) {
        if (found[0]) return;
        if (pos == halfLen) {
            List<Integer> digits = new ArrayList<>();
            for (int v : halfPerm) digits.add(v);
            if (middleDigit != -1) digits.add(middleDigit);
            for (int i = halfLen-1; i >= 0; i--) digits.add(halfPerm[i]);
            if (!digits.isEmpty() && digits.get(0) == 0) return;
            long mod = 0;
            for (int d : digits) mod = (mod*10 + d) % K;
            if (mod == 0) {
                long total = fact[N];
                for (int c : cnt) total /= fact[c];
                if (cnt[0] > 0) {
                    long leadingZero = fact[N-1];
                    leadingZero /= fact[cnt[0]-1];
                    for (int d = 1; d < 10; d++) leadingZero /= fact[cnt[d]];
                    total -= leadingZero;
                }
                answer += total;
                found[0] = true;
            }
            return;
        }
        for (int d = 0; d < 10; d++) {
            if (used[d] < halfCounts[d]) {
                used[d]++;
                halfPerm[pos] = d;
                backtrack(pos+1, halfLen, halfCounts, middleDigit, halfPerm, used, found);
                used[d]--;
                if (found[0]) return;
            }
        }
    }

}

