public class Solution {
    public static int maxScore(int[] start, int d) {
        int n = start.length;
        long[][] intervals = new long[n][2];
        for (int i = 0; i < n; i++) {
            long l = start[i];
            long r = (long) start[i] + d;
            intervals[i][0] = l;
            intervals[i][1] = r;
        }
        Arrays.sort(intervals, (a, b) -> Long.compare(a[0], b[0]));
        long minL = intervals[0][0];
        long maxR = intervals[n - 1][1];
        long lo = 0;
        long hi = maxR - minL + 1;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (feasible(intervals, n, mid)) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return (int) (lo - 1);
    }

    private static boolean feasible(long[][] intervals, int n, long dist) {
        long prev = intervals[0][0];
        for (int i = 1; i < n; i++) {
            long need = prev + dist;
            long pos = intervals[i][0] > need ? intervals[i][0] : need;
            if (pos > intervals[i][1]) {
                return false;
            }
            prev = pos;
        }
        return true;
    }
}

