class Solution {
    public static String convertDateToBinary(String date) {
        String[] parts = date.split("-");
        String yearBin = toBinary(Integer.parseInt(parts[0]));
        String monthBin = toBinary(Integer.parseInt(parts[1]));
        String dayBin = toBinary(Integer.parseInt(parts[2]));
        return yearBin + "-" + monthBin + "-" + dayBin;
    }

    private static String toBinary(int value) {
        if (value == 0) {
            return "0";
        }
        StringBuilder sb = new StringBuilder();
        while (value > 0) {
            sb.append((value & 1) == 1 ? '1' : '0');
            value >>= 1;
        }
        return sb.reverse().toString();
    }
}

