class Solution {
    public static List<Integer> findTwoSneaky(int[] nums) {
        int max = Integer.MIN_VALUE;
        for (int v : nums) {
            if (v > max) {
                max = v;
            }
        }
        int[] freq = new int[max + 1];
        for (int i = 0; i < nums.length; i++) {
            freq[nums[i]]++;
        }
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < freq.length; i++) {
            if (freq[i] == 2) {
                result.add(i);
                if (result.size() == 2) {
                    break;
                }
            }
        }
        return result;
    }
}

