class Solution {
    private static class Point {
        int x;
        int y;
        int idx;
        Point(int x, int y, int idx) {
            this.x = x;
            this.y = y;
            this.idx = idx;
        }
    }

    public static int longestIncreasingPath(int[][] coordinates, int k) {
        int n = coordinates.length;
        List<Point> points = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            points.add(new Point(coordinates[i][0], coordinates[i][1], i));
        }
        points.sort((a, b) -> {
            if (a.x == b.x) return Integer.compare(b.y, a.y);
            return Integer.compare(a.x, b.x);
        });
        int targetPos = -1;
        for (int i = 0; i < n; ++i) {
            if (points.get(i).idx == k) {
                targetPos = i;
                break;
            }
        }
        int[] forward = new int[n];
        Arrays.fill(forward, 1);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (points.get(j).x < points.get(i).x && points.get(j).y < points.get(i).y) {
                    if (forward[j] + 1 > forward[i]) {
                        forward[i] = forward[j] + 1;
                    }
                }
            }
        }
        int[] backward = new int[n];
        Arrays.fill(backward, 1);
        for (int i = n - 1; i >= 0; --i) {
            for (int j = n - 1; j > i; --j) {
                if (points.get(i).x < points.get(j).x && points.get(i).y < points.get(j).y) {
                    if (backward[j] + 1 > backward[i]) {
                        backward[i] = backward[j] + 1;
                    }
                }
            }
        }
        return forward[targetPos] + backward[targetPos] - 1;
    }
}

