        for (int i = 1; i < 5; i++) dp[i] = Long.MIN_VALUE;
        dp[0] = 0L;
        for (long x : b) {
            for (int k = 4; k >= 1; --k) {
                if (dp[k - 1] != Long.MIN_VALUE) {
                    long candidate = dp[k - 1] + a[k - 1] * x;
                    if (candidate > dp[k]) dp[k] = candidate;
                }
            }
        }
        return dp[4];
    }
}

class Solution {
    public long minNumberOfSeconds(int mountainHeight, int[] workerTimes) {
        int maxWt = 0;
        for (int w : workerTimes) maxWt = Math.max(maxWt, w);
        long lo = 0, hi = (long) maxWt * mountainHeight * (mountainHeight + 1) / 2;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (feasible(mid, mountainHeight, workerTimes)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

    private boolean feasible(long t, int height, int[] workerTimes) {
        long total = 0;
        for (int w : workerTimes) {
            total += maxReduction(t, w);
            if (total >= height) return true;
        }
        return total >= height;
    }

    // Max x such that w * x*(x+1)/2 <= t, via binary search (overflow-safe: x bounded well
    // under sqrt(2*Long.MAX/w), and triangular(x) stays small enough for w*triangular to fit a long).
    private long maxReduction(long t, int w) {
        long lo = 0, hi = 2_000_000;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            long triangular = mid * (mid + 1) / 2;
            if ((long) w * triangular <= t) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

