class Solution {
    public static long countSubstrings(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        if (m > n) return 0L;
        int[] need = new int[26];
        int[] have = new int[26];
        for (int i = 0; i < m; ++i) {
            need[word2.charAt(i) - 'a']++;
        }
        int missing = 0;
        for (int v : need) missing += v;
        long ans = 0L;
        int R = 0;
        for (int L = 0; L < n; ++L) {
            while (R < n && missing > 0) {
                int idx = word1.charAt(R) - 'a';
                if (have[idx] < need[idx]) missing--;
                have[idx]++;
                ++R;
            }
            if (missing == 0) {
                ans += (long) (n - (R - 1));
            } else {
                break;
            }
            int idxL = word1.charAt(L) - 'a';
            if (have[idxL] <= need[idxL]) missing++;
            have[idxL]--;
        }
        return ans;
    }
}

