class Solution {
    private static class State {
        boolean reachable = false;
        List<Integer> seq = new ArrayList<>();
    }

    public static List<Integer> getLexicographicallySmallestValidSequence(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        if (m == 0) return new ArrayList<>();
        State[][] dp = new State[m + 1][2];
        for (int i = 0; i <= m; i++) {
            for (int e = 0; e < 2; e++) {
                dp[i][e] = new State();
            }
        }
        dp[0][0].reachable = true;
        for (int idx = 0; idx < n; idx++) {
            for (int i = m - 1; i >= 0; i--) {
                for (int err = 0; err <= 1; err++) {
                    if (!dp[i][err].reachable) continue;
                    int lastPos = -1;
                    if (!dp[i][err].seq.isEmpty()) lastPos = dp[i][err].seq.get(dp[i][err].seq.size() - 1);
                    if (lastPos >= idx) continue;
                    int newErr = err + (word1.charAt(idx) != word2.charAt(i) ? 1 : 0);
                    if (newErr > 1) continue;
                    List<Integer> cand = new ArrayList<>(dp[i][err].seq);
                    cand.add(idx);
                    if (!dp[i + 1][newErr].reachable ||
                        lexicographicallyLess(cand, dp[i + 1][newErr].seq)) {
                        dp[i + 1][newErr].reachable = true;
                        dp[i + 1][newErr].seq = cand;
                    }
                }
            }
        }
        List<Integer> best = null;
        boolean found = false;
        for (int err = 0; err <= 1; err++) {
            if (!dp[m][err].reachable) continue;
            if (!found || lexicographicallyLess(dp[m][err].seq, best)) {
                best = dp[m][err].seq;
                found = true;
            }
        }
        return found ? best : new ArrayList<>();
    }

    private static boolean lexicographicallyLess(List<Integer> a, List<Integer> b) {
        int len = Math.min(a.size(), b.size());
        for (int i = 0; i < len; i++) {
            int av = a.get(i);
            int bv = b.get(i);
            if (av != bv) return av < bv;
        }
        return a.size() < b.size();
    }
}

import java.util.*;

class Solution {
    public static long countSubstrings(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        if (m > n) return 0L;
        int[] need = new int[26];
        for (int i = 0; i < m; ++i) need[word2.charAt(i) - 'a']++;
        int[] diff = new int[26];
        for (int i = 0; i < 26; ++i) diff[i] = -need[i];
        int deficit = 0;
        for (int i = 0; i < 26; ++i) if (need[i] > 0) ++deficit;
        long ans = 0L;
        int r = 0;
        for (int l = 0; l < n; ++l) {
            while (r < n && deficit > 0) {
                int idx = word1.charAt(r) - 'a';
                ++diff[idx];
                if (diff[idx] == 0) --deficit;
                ++r;
            }
            if (deficit > 0) break;
            ans += (long) (n - r + 1);
            int idxL = word1.charAt(l) - 'a';
            --diff[idxL];
            if (diff[idxL] == -1) ++deficit;
        }
        return ans;
    }
}

