class Solution {
    public static int findFirstAlmostEqual(String s, String pattern) {
        int n = s.length();
        int m = pattern.length();
        if (m > n) return -1;
        for (int start = 0; start <= n - m; ++start) {
            int mismatches = 0;
            for (int i = 0; i < m; ++i) {
                if (s.charAt(start + i) != pattern.charAt(i)) {
                    ++mismatches;
                    if (mismatches > 1) break;
                }
            }
            if (mismatches <= 1) return start;
        }
        return -1;
    }
}

