class Solution {
    public static char kthCharacter(long k) {
        if (k <= 0) return '\0';
        long len = 1;
        while (len < k) len <<= 1;
        return solve(k, len);
    }

    private static char solve(long pos, long curLen) {
        if (curLen == 1) return 'a';
        long half = curLen >> 1;
        if (pos <= half) return solve(pos, half);
        char c = solve(pos - half, half);
        return c == 'z' ? 'a' : (char) (c + 1);
    }
}

