class Solution {
    public static char findKthChar(long k, int[] operations) {
        int n = operations.length;
        long[] len = new long[n + 1];
        final long INF = 4000000000000000000L;
        len[0] = 1;
        for (int i = 0; i < n; ++i) {
            long nxt = len[i] * 2;
            if (nxt / 2 != len[i] || nxt > INF) {
                nxt = INF;
            }
            len[i + 1] = nxt;
        }
        long pos = k;
        int shift = 0;
        for (int i = n; i > 0; --i) {
            if (pos > len[i - 1]) {
                pos -= len[i - 1];
                if (operations[i - 1] == 1) {
                    shift = (shift + 1) % 26;
                }
            }
        }
        return (char) ('a' + shift);
    }
}

