public class Solution {
    public static long countVowelConsonantSubstrings(String word, int k) {
        Set<Character> vowels = Set.of('a', 'e', 'i', 'o', 'u');
        int n = word.length();
        int[] prefC = new int[n + 1];
        for (int i = 0; i < n; i++) {
            char ch = word.charAt(i);
            prefC[i + 1] = prefC[i] + (vowels.contains(ch) ? 0 : 1);
        }
        Map<Character, Integer> last = new HashMap<>();
        for (char v : vowels) {
            last.put(v, -1);
        }
        Map<Integer, List<Integer>> positions = new HashMap<>();
        positions.computeIfAbsent(0, key -> new ArrayList<>()).add(0);
        long ans = 0;
        for (int i = 0; i < n; i++) {
