                last.put(ch, i);
            }
            int minLast = Integer.MAX_VALUE;
            for (char v : vowels) {
                minLast = Math.min(minLast, last.get(v));
            }
            if (minLast != -1) {
                int target = prefC[i + 1] - k;
                List<Integer> arr = positions.get(target);
                if (arr != null) {
                    int cnt = upperBound(arr, minLast);
                    ans += cnt;
                }
            }
            positions.computeIfAbsent(prefC[i + 1], key -> new ArrayList<>()).add(i + 1);
        }
        return ans;
    }

    private static int upperBound(List<Integer> list, int value) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) <= value) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

import java.util.*;

class Solution {
    private static int vowelIndex(char c) {
        switch (c) {
            case 'a': return 0;
            case 'e': return 1;
            case 'i': return 2;
            case 'o': return 3;
            case 'u': return 4;
            default: return -1;
        }
    }

    public static long countVowelConsonantSubstrings(String word, int k) {
        int n = word.length();
        int[] latest = new int[5];
        for (int i = 0; i < 5; ++i) latest[i] = -1;
        int leftAtMostK = 0, leftAtMostKm1 = 0;
        int cntConK = 0, cntConKm1 = 0;
        long answer = 0L;

        for (int r = 0; r < n; ++r) {
            int vIdx = vowelIndex(word.charAt(r));
            if (vIdx == -1) {
                ++cntConK;
                ++cntConKm1;
            } else {
                latest[vIdx] = r;
            }

            while (cntConK > k) {
                if (vowelIndex(word.charAt(leftAtMostK)) == -1) --cntConK;
                ++leftAtMostK;
            }

            if (k > 0) {
                while (cntConKm1 > k - 1) {
                    if (vowelIndex(word.charAt(leftAtMostKm1)) == -1) --cntConKm1;
                    ++leftAtMostKm1;
                }
            }

            int minPos = n;
            for (int i = 0; i < 5; ++i) {
                if (latest[i] == -1) {
                    minPos = -1;
                    break;
                }
                if (latest[i] < minPos) minPos = latest[i];
            }

            long cntAtMostK = 0L, cntAtMostKm1 = 0L;
            if (minPos >= leftAtMostK) cntAtMostK = (long) (minPos - leftAtMostK + 1);
            if (k > 0 && minPos >= leftAtMostKm1) cntAtMostKm1 = (long) (minPos - leftAtMostKm1 + 1);

            answer += cntAtMostK - cntAtMostKm1;
        }

        return answer;
    }
}

