class Solution {
    public static int[] removeMethods(int n, int k, int[][] invocations) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] p : invocations) {
            adj.get(p[0]).add(p[1]);
        }

        Set<Integer> suspicious = new HashSet<>();
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(k);
        while (!stack.isEmpty()) {
            int cur = stack.pop();
            if (suspicious.contains(cur)) continue;
            suspicious.add(cur);
            for (int nxt : adj.get(cur)) {
                if (!suspicious.contains(nxt)) {
                    stack.push(nxt);
                }
            }
        }

        for (int[] p : invocations) {
            if (!suspicious.contains(p[0]) && suspicious.contains(p[1])) {
                int[] all = new int[n];
                for (int i = 0; i < n; i++) all[i] = i;
                return all;
            }
        }

        List<Integer> remaining = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!suspicious.contains(i)) remaining.add(i);
        }
        int[] result = new int[remaining.size()];
        for (int i = 0; i < remaining.size(); i++) {
            result[i] = remaining.get(i);
        }
        return result;
    }
}

