class Solution {
    public static int[] constructMinimumBitwiseArray(int[] nums) {
        int[] ans = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int p = nums[i];
            if (p % 2 == 0) {
                ans[i] = -1;
                continue;
            }
            int temp = p;
            int t = 0;
            while ((temp & 1) == 1) {
                t++;
                temp >>= 1;
            }
            int x = p - (1 << (t - 1));
            ans[i] = x;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static long maxBinaryConcat(int[] nums) {
        int[] bitLen = new int[3];
        for (int i = 0; i < 3; ++i) {
            int v = nums[i];
            if (v == 0) {
                bitLen[i] = 1;
            } else {
                bitLen[i] = 32 - Integer.numberOfLeadingZeros(v);
            }
        }

        int[][] perms = {
            {0, 1, 2}, {0, 2, 1},
            {1, 0, 2}, {1, 2, 0},
            {2, 0, 1}, {2, 1, 0}
        };

        long best = 0;
        for (int p = 0; p < 6; ++p) {
            long a = nums[perms[p][0]];
            long b = nums[perms[p][1]];
            long c = nums[perms[p][2]];
            int lenB = bitLen[perms[p][1]];
            int lenC = bitLen[perms[p][2]];
            long val = ((a << lenB) | b) << lenC | c;
            if (val > best) best = val;
        }
        return best;
    }
}

