class Solution {
    public static int[] constructMinimumBitwiseArray(int[] nums) {
        int[] ans = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int p = nums[i];
            int t = 0;
            while ((p & (1 << t)) != 0) {
                t++;
            }
            if (t == 0) {
                ans[i] = -1;
            } else {
                int subtract = 1 << (t - 1);
                ans[i] = p - subtract;
            }
        }
        return ans;
    }
}

