class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) {
        val = x;
    }
}

class Solution {
    private static class Info {
        boolean isPerfect;
        int height;
        int size;
        Info(boolean isPerfect, int height, int size) {
            this.isPerfect = isPerfect;
            this.height = height;
            this.size = size;
        }
    }

    private static Info dfs(TreeNode node, List<Integer> sizes) {
        if (node == null) {
            return new Info(true, -1, 0);
        }
        Info leftInfo = dfs(node.left, sizes);
        Info rightInfo = dfs(node.right, sizes);
        boolean isPerf = leftInfo.isPerfect && rightInfo.isPerfect && leftInfo.height == rightInfo.height;
        int h = Math.max(leftInfo.height, rightInfo.height) + 1;
        int sz = isPerf ? ((1 << (h + 1)) - 1) : Math.max(leftInfo.size, rightInfo.size);
        if (isPerf) {
            sizes.add(sz);
        }
        return new Info(isPerf, h, sz);
    }

    public static int kthLargestPerfectSubtree(TreeNode root, int k) {
        List<Integer> sizes = new ArrayList<>();
        dfs(root, sizes);
        sizes.sort(Collections.reverseOrder());
        if (k <= 0 || k > sizes.size()) {
            return -1;
        }
        return sizes.get(k - 1);
    }
}

