class Solution {
    public static int maxRemovals(String source, String pattern, int[] targetIndices) {
        int n = source.length();
        int totalRemovable = targetIndices.length;
        boolean[] removable = new boolean[n];
        for (int idx : targetIndices) {
            removable[idx] = true;
        }
        // If pattern cannot be a subsequence even after removing all removable chars, answer is 0
        if (!canMatch(source, pattern, removable, totalRemovable)) {
            return 0;
        }
        int low = 0, high = totalRemovable;
        while (low < high) {
            int mid = (low + high) / 2;
            if (canMatch(source, pattern, removable, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        int minimalUsed = low;
        return totalRemovable - minimalUsed;
    }

    private static boolean canMatch(String source, String pattern, boolean[] removable, int allowedUsed) {
        int pLen = pattern.length();
        int[] dp = new int[pLen + 1];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[0] = 0;
        for (int i = 0; i < source.length(); i++) {
            char c = source.charAt(i);
            int cost = removable[i] ? 1 : 0;
            for (int j = pLen; j >= 1; j--) {
                if (c == pattern.charAt(j - 1)) {
                    int newCost = dp[j - 1] + cost;
                    if (newCost < dp[j]) {
                        dp[j] = newCost;
                    }
                }
            }
        }
        return dp[pLen] <= allowedUsed;
    }
}

import java.lang.*;

class Solution {
    private static final int MOD = 1000000007;

    public static int countWinningSequences(String s) {
        int n = s.length();
        int offset = n;
        int range = 2 * n + 1;
        int[] alice = new int[n];
        for (int i = 0; i < n; ++i) {
            char c = s.charAt(i);
            if (c == 'F') alice[i] = 0;
            else if (c == 'W') alice[i] = 1;
            else alice[i] = 2;
        }
        int[][] win = new int[3][3];
        for (int b = 0; b < 3; ++b) {
            for (int a = 0; a < 3; ++a) {
                if (b == a) win[b][a] = 0;
                else if ((b == 0 && a == 2) || (b == 1 && a == 0) || (b == 2 && a == 1))
                    win[b][a] = 1;
                else
                    win[b][a] = -1;
            }
        }
        int[][] dpPrev = new int[4][range];
        dpPrev[3][offset] = 1;
        for (int i = 0; i < n; ++i) {
            int[][] dpCurr = new int[4][range];
            for (int prev = 0; prev < 4; ++prev) {
                for (int sc = 0; sc < range; ++sc) {
                    int ways = dpPrev[prev][sc];
                    if (ways == 0) continue;
                    for (int cur = 0; cur < 3; ++cur) {
                        if (prev != 3 && cur == prev) continue;
                        int delta = win[cur][alice[i]];
                        int nsc = sc + delta;
                        if (nsc < 0 || nsc >= range) continue;
                        int ref = dpCurr[cur][nsc] + ways;
                        if (ref >= MOD) ref -= MOD;
                        dpCurr[cur][nsc] = ref;
                    }
                }
            }
            dpPrev = dpCurr;
        }
        long ans = 0;
        for (int prev = 0; prev < 3; ++prev) {
            for (int sc = offset + 1; sc < range; ++sc) {
                ans += dpPrev[prev][sc];
                if (ans >= MOD) ans -= MOD;
            }
        }
        return (int) (ans % MOD);
    }
}

import java.util.*;
class Solution {
    public static long[] findXSum(int[] nums, int k, int x) {
        int n = nums.length;
        List<Long> result = new ArrayList<>();
        for (int i = 0; i <= n - k; i++) {
            Map<Integer, Integer> freq = new HashMap<>();
            long windowSum = 0;
            for (int idx = i; idx < i+k; idx++) {
                windowSum += nums[idx];
                freq.merge(nums[idx], 1, Integer::sum);
            }
            if (freq.size() <= x) {
                result.add(windowSum);
            } else {
                List<Map.Entry<Integer,Integer>> items = new ArrayList<>(freq.entrySet());
                items.sort((a,b) -> b.getValue() != a.getValue() ? b.getValue()-a.getValue() : b.getKey()-a.getKey());
                long xSum = 0;
                for (int idx = 0; idx < x; idx++) xSum += (long) items.get(idx).getKey() * items.get(idx).getValue();
                result.add(xSum);
            }
        }
        long[] arr = new long[result.size()];
        for (int i = 0; i < arr.length; i++) arr[i] = result.get(i);
        return arr;
    }
}

