class Solution {
    private static final long MOD = 1000000007L;

    private static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static int numberOfWays(int n, int x, int y) {
        int maxN = Math.max(n, x);
        long[] fact = new long[maxN + 1];
        long[] invFact = new long[maxN + 1];
        fact[0] = 1;
        for (int i = 1; i <= maxN; ++i) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[maxN] = modPow(fact[maxN], MOD - 2);
        for (int i = maxN; i > 0; --i) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        long[][] S = new long[n + 1][n + 1];
        S[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= i; ++j) {
                S[i][j] = (j * S[i - 1][j] + S[i - 1][j - 1]) % MOD;
            }
        }

        long ans = 0;
        int limit = Math.min(n, x);
        for (int k = 1; k <= limit; ++k) {
            long ways = fact[x] * invFact[k] % MOD * invFact[x - k] % MOD; // C(x, k)
            ways = ways * fact[k] % MOD;
            ways = ways * S[n][k] % MOD;
            ways = ways * modPow(y, k) % MOD;
            ans = (ans + ways) % MOD;
        }
        return (int) ans;
    }
}

