public class Solution {
    private static final int MAXV = 1000000;
    private static int[] spfAll;

    public static int minimumOperations(int[] nums) {
        if (spfAll == null) {
            spfAll = new int[MAXV + 1];
            for (int i = 0; i <= MAXV; ++i) spfAll[i] = i;
            for (int i = 2; i * i <= MAXV; ++i) {
                if (spfAll[i] == i) {
                    for (int j = i * i; j <= MAXV; j += i) {
                        if (spfAll[j] == j) spfAll[j] = i;
                    }
                }
            }
        }

        final int INF = 1_000_000_000;
        int n = nums.length;
        if (n == 0) return 0;

        int prevOrig = nums[0];
        int prevSpf = (nums[0] == 1) ? 1 : spfAll[nums[0]];
        boolean prevHasSpf = (prevSpf != prevOrig);

        int dp0 = 0;
        int dp1 = prevHasSpf ? 1 : INF;

        for (int i = 1; i < n; ++i) {
            int curOrig = nums[i];
            int curSpf = (nums[i] == 1) ? 1 : spfAll[nums[i]];
            boolean curHasSpf = (curSpf != curOrig);

            int ndp0 = INF;
            int ndp1 = INF;

            if (dp0 < INF) {
                if (prevOrig <= curOrig) ndp0 = Math.min(ndp0, dp0);
                if (curHasSpf && prevOrig <= curSpf) ndp1 = Math.min(ndp1, dp0 + 1);
            }
            if (dp1 < INF) {
                if (prevSpf <= curOrig) ndp0 = Math.min(ndp0, dp1);
                if (curHasSpf && prevSpf <= curSpf) ndp1 = Math.min(ndp1, dp1 + 1);
            }

            dp0 = ndp0;
            dp1 = ndp1;
            prevOrig = curOrig;
            prevSpf = curSpf;
        }

        int ans = Math.min(dp0, dp1);
        return ans >= INF ? -1 : ans;
    }
}

