public class Solution {
    public static long countSubstringsWithKFrequency(String s, int k) {
        int n = s.length();
        long totalSubstrings = (long) n * (n + 1) / 2;
        if (k <= 1) return totalSubstrings;
        int[] freq = new int[26];
        int left = 0;
        long badCount = 0;
        for (int right = 0; right < n; ++right) {
            int idx = s.charAt(right) - 'a';
            ++freq[idx];
            while (freq[idx] >= k) {
                int leftIdx = s.charAt(left) - 'a';
                --freq[leftIdx];
                ++left;
            }
            badCount += (long) (right - left + 1);
        }
        return totalSubstrings - badCount;
    }
}

