class Solution {
    public static boolean[] dfsStringsArePalindromes(int[] parent, String s) {
        int n = parent.length;
        List<List<Integer>> children = new ArrayList<>(n);
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (parent[i] == -1) {
                root = i;
            } else {
                children.get(parent[i]).add(i);
            }
        }
        boolean[] answer = new boolean[n];
        dfs(root, children, s, answer);
        return answer;
    }

    private static int dfs(int u, List<List<Integer>> children, String s, boolean[] answer) {
        int mask = 1 << (s.charAt(u) - 'a');
        for (int v : children.get(u)) {
            mask ^= dfs(v, children, s, answer);
        }
        answer[u] = (mask & (mask - 1)) == 0;
        return mask;
    }
}

import java.util.*;

public class Solution {
    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static long lcm(long a, long b) {
        if (a == 0 || b == 0) return 0;
        return a / gcd(a, b) * b;
    }

    public static long maxFactorScore(int[] nums) {
        int n = nums.length;
        long[] prefGcd = new long[n];
        long[] prefLcm = new long[n];
        long[] suffGcd = new long[n];
        long[] suffLcm = new long[n];

        prefGcd[0] = nums[0];
        prefLcm[0] = nums[0];
        for (int i = 1; i < n; i++) {
            prefGcd[i] = gcd(prefGcd[i - 1], nums[i]);
            prefLcm[i] = lcm(prefLcm[i - 1], nums[i]);
        }

        suffGcd[n - 1] = nums[n - 1];
        suffLcm[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffGcd[i] = gcd(suffGcd[i + 1], nums[i]);
            suffLcm[i] = lcm(suffLcm[i + 1], nums[i]);
        }

        long best = prefLcm[n - 1] * prefGcd[n - 1]; // no removal

        for (int i = 0; i < n; i++) {
            long leftGcd = (i > 0) ? prefGcd[i - 1] : 0;
            long rightGcd = (i < n - 1) ? suffGcd[i + 1] : 0;
            long curGcd;
            if (leftGcd == 0) curGcd = rightGcd;
            else if (rightGcd == 0) curGcd = leftGcd;
            else curGcd = gcd(leftGcd, rightGcd);

            long leftLcm = (i > 0) ? prefLcm[i - 1] : 1;
            long rightLcm = (i < n - 1) ? suffLcm[i + 1] : 1;
            long curLcm = lcm(leftLcm, rightLcm);

            long score = curLcm * curGcd;
            if (score > best) best = score;
        }

        return best;
    }
}

import java.util.*;

class Solution {
    public static int countEqualGcdSubsequencePairs(int[] nums) {
        final int MOD = 1000000007;
        final int MAX = 200;
        int[][] dp = new int[MAX + 1][MAX + 1];
        dp[0][0] = 1;
        for (int x : nums) {
            int[][] ndp = new int[MAX + 1][MAX + 1];
            for (int a = 0; a <= MAX; ++a) {
                for (int b = 0; b <= MAX; ++b) {
                    int cur = dp[a][b];
                    if (cur == 0) continue;
                    ndp[a][b] = (ndp[a][b] + cur) % MOD;
                    int na = (a == 0) ? x : gcd(a, x);
                    ndp[na][b] = (ndp[na][b] + cur) % MOD;
                    int nb = (b == 0) ? x : gcd(b, x);
                    ndp[a][nb] = (ndp[a][nb] + cur) % MOD;
                }
            }
            dp = ndp;
        }
        long ans = 0;
        for (int g = 1; g <= MAX; ++g) {
            ans = (ans + dp[g][g]) % MOD;
        }
        return (int) ans;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.*;

class Solution {
    public static int[] findSubtreeSizes(int[] parent, String s) {
        int n = parent.length;
        List<Integer>[] origChildren = new ArrayList[n];
        for (int i = 0; i < n; i++) origChildren[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            origChildren[parent[i]].add(i);
        }

        int[] newParent = parent.clone();
        int[] savedPrev = new int[n];
        Arrays.fill(savedPrev, -1);
        int[] lastSeen = new int[26];
        Arrays.fill(lastSeen, -1);

        class Item {
            int node;
            int state;
            Item(int node, int state) {
                this.node = node;
                this.state = state;
            }
        }

        Deque<Item> stack = new ArrayDeque<>();
        stack.push(new Item(0, 0));

        while (!stack.isEmpty()) {
            Item cur = stack.pop();
            int u = cur.node;
            if (cur.state == 0) {
                int c = s.charAt(u) - 'a';
                savedPrev[u] = lastSeen[c];
                lastSeen[c] = u;
                stack.push(new Item(u, 1));
                for (int v : origChildren[u]) {
                    int cc = s.charAt(v) - 'a';
                    if (lastSeen[cc] != -1) newParent[v] = lastSeen[cc];
                    else newParent[v] = parent[v];
                    stack.push(new Item(v, 0));
                }
            } else {
                int c = s.charAt(u) - 'a';
                lastSeen[c] = savedPrev[u];
            }
        }

        List<Integer>[] finalChildren = new ArrayList[n];
        for (int i = 0; i < n; i++) finalChildren[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            finalChildren[newParent[i]].add(i);
        }

        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        Deque<Item> stack2 = new ArrayDeque<>();
        stack2.push(new Item(0, 0));
        while (!stack2.isEmpty()) {
            Item cur = stack2.pop();
            int u = cur.node;
            if (cur.state == 0) {
                stack2.push(new Item(u, 1));
                for (int v : finalChildren[u]) {
                    stack2.push(new Item(v, 0));
                }
            } else {
                for (int v : finalChildren[u]) {
                    ans[u] += ans[v];
                }
            }
        }
        return ans;
    }
}

import java.util.*;

public class Solution {
    private static final int MOD = 1000000007;
    public static int originalStringCount(String word, int k) {
        int n = word.length();
        ArrayList<Integer> groups = new ArrayList<>();
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && word.charAt(j) == word.charAt(i)) {
                ++j;
            }
            groups.add(j - i);
            i = j;
        }
        long totalWays = 1;
        for (int g : groups) {
            totalWays = (totalWays * g) % MOD;
        }
        int[] dp = new int[k];
        int[] ndp = new int[k];
        dp[0] = 1;
        for (int g : groups) {
            int limit = Math.min(g, k - 1);
            int[] pref = new int[k];
            pref[0] = dp[0];
            for (int i = 1; i < k; ++i) {
                int val = pref[i - 1] + dp[i];
                if (val >= MOD) val -= MOD;
                pref[i] = val;
            }
            ndp[0] = 0;
            for (int t = 1; t < k; ++t) {
                int left = t - limit;
                if (left < 0) left = 0;
                int sum = pref[t - 1];
                if (left > 0) {
                    sum -= pref[left - 1];
                    if (sum < 0) sum += MOD;
                }
                ndp[t] = sum;
            }
            int[] temp = dp;
            dp = ndp;
            ndp = temp;
        }
        long lessThanK = 0;
        for (int i = 0; i < k; ++i) {
            lessThanK += dp[i];
            if (lessThanK >= MOD) lessThanK -= MOD;
        }
        long ans = (totalWays - lessThanK) % MOD;
        if (ans < 0) ans += MOD;
        return (int) ans;
    }
}

import java.util.*;

public class Solution {
    public static long maxPoints(int n, int k, long[][] stayScore, long[][] travelScore) {
        if (k == 0) return 0L;
        long[] dpPrev = new long[n];
        for (int c = 0; c < n; ++c) dpPrev[c] = stayScore[0][c];
        for (int day = 1; day < k; ++day) {
            long[] dpCurr = new long[n];
            Arrays.fill(dpCurr, Long.MIN_VALUE);
            for (int c = 0; c < n; ++c) {
                long stay = dpPrev[c] + stayScore[day][c];
                long bestTravel = Long.MIN_VALUE;
                for (int p = 0; p < n; ++p) {
                    if (p == c) continue;
                    long cand = dpPrev[p] + travelScore[p][c];
                    if (cand > bestTravel) bestTravel = cand;
                }
                dpCurr[c] = stay > bestTravel ? stay : bestTravel;
            }
            dpPrev = dpCurr;
        }
        long answer = Long.MIN_VALUE;
        for (int c = 0; c < n; ++c) if (dpPrev[c] > answer) answer = dpPrev[c];
        return answer;
    }
}

