class Solution {
    public static int totalLengthAfterTransformations(String s, int t) {
        final int MOD = 1000000007;
        int[] cnt = new int[26];
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            cnt[idx] = (cnt[idx] + 1) % MOD;
        }
        for (int step = 0; step < t; step++) {
            int[] newCnt = new int[26];
            for (int i = 0; i < 26; i++) {
                int val = cnt[i];
                if (val == 0) continue;
                if (i == 25) {
                    newCnt[0] = (int) ((newCnt[0] + (long) val * 2) % MOD);
                } else {
                    newCnt[i + 1] = (newCnt[i + 1] + val) % MOD;
                }
            }
            cnt = newCnt;
        }
        int ans = 0;
        for (int i = 0; i < 26; i++) {
            ans = (ans + cnt[i]) % MOD;
        }
        return ans;
    }
}

public class Solution {
    public static boolean is_balanced_string(String num) {
        int even_sum = 0;
        int odd_sum = 0;
        for (int i = 0; i < num.length(); i++) {
            int digit = num.charAt(i) - '0';
            if (i % 2 == 0) {
                even_sum += digit;
            } else {
                odd_sum += digit;
            }
        }
        return even_sum == odd_sum;
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1000000007L;

    private static long[][] multiplyMatrix(long[][] A, long[][] B) {
        long[][] C = new long[26][26];
        for (int i = 0; i < 26; i++) {
            for (int k = 0; k < 26; k++) {
                long aik = A[i][k];
                if (aik == 0) continue;
                for (int j = 0; j < 26; j++) {
                    C[i][j] = (C[i][j] + aik * B[k][j]) % MOD;
                }
            }
        }
        return C;
    }

    private static long[] multiplyMatrixVector(long[][] A, long[] v) {
        long[] res = new long[26];
        for (int i = 0; i < 26; i++) {
            long sum = 0;
            for (int j = 0; j < 26; j++) {
                sum = (sum + A[i][j] * v[j]) % MOD;
            }
            res[i] = sum;
        }
        return res;
    }

    public static int totalCharactersAfterTransformationsII(String s, int t, int[] nums) {
        long[][] A = new long[26][26];
        for (int c = 0; c < 26; c++) {
            int cnt = nums[c];
            for (int d = 1; d <= cnt; d++) {
                int nxt = (c + d) % 26;
                A[c][nxt] = (A[c][nxt] + 1) % MOD;
            }
        }

        long[] vec = new long[26];
        Arrays.fill(vec, 1L);

        long[][] cur = A;
        long exp = t;
        while (exp > 0) {
            if ((exp & 1L) != 0) {
                vec = multiplyMatrixVector(cur, vec);
            }
            cur = multiplyMatrix(cur, cur);
            exp >>= 1;
        }

        long ans = 0;
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            ans = (ans + vec[idx]) % MOD;
        }
        return (int) ans;
    }
}

import java.util.*;

public class Solution {
    public static long minimumTime(int[][] moveTime) {
        int n = moveTime.length;
        int m = moveTime[0].length;
        long INF = Long.MAX_VALUE / 4;
        long[][][] dist = new long[n][m][2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                dist[i][j][0] = INF;
                dist[i][j][1] = INF;
            }
        }
        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[0][0][0] = 0;
        pq.offer(new State(0L, 0, 0, 0));
        int[] di = {-1, 1, 0, 0};
        int[] dj = {0, 0, -1, 1};
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            long curTime = cur.time;
            int i = cur.i;
            int j = cur.j;
            int par = cur.par;
            if (curTime != dist[i][j][par]) continue;
            long moveCost = (par == 0) ? 1L : 2L;
            int nextPar = 1 - par;
            for (int dir = 0; dir < 4; dir++) {
                int ni = i + di[dir];
                int nj = j + dj[dir];
                if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                long start = Math.max(curTime, (long) moveTime[ni][nj]);
                long arrival = start + moveCost;
                if (arrival < dist[ni][nj][nextPar]) {
                    dist[ni][nj][nextPar] = arrival;
                    pq.offer(new State(arrival, ni, nj, nextPar));
                }
            }
        }
        return Math.min(dist[n - 1][m - 1][0], dist[n - 1][m - 1][1]);
    }

    private static class State implements Comparable<State> {
        long time;
        int i, j, par;

        State(long time, int i, int j, int par) {
            this.time = time;
            this.i = i;
            this.j = j;
            this.par = par;
        }

        public int compareTo(State other) {
            return Long.compare(this.time, other.time);
        }
    }
}

import java.util.PriorityQueue;

class Solution {
    private static class Node implements Comparable<Node> {
        long time;
        int x;
        int y;
        Node(long time, int x, int y) {
            this.time = time;
            this.x = x;
            this.y = y;
        }
        public int compareTo(Node other) {
            return Long.compare(this.time, other.time);
        }
    }

    public static long minimumTime(int[][] moveTime) {
        int n = moveTime.length;
        int m = moveTime[0].length;
        long INF = 4_000_000_000_000_000_000L;
        long[][] dist = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                dist[i][j] = INF;
            }
        }
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[0][0] = 0;
        pq.offer(new Node(0, 0, 0));
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            long t = cur.time;
            int x = cur.x;
            int y = cur.y;
            if (t != dist[x][y]) continue;
            if (x == n - 1 && y == m - 1) break;
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                long arrive = Math.max(t + 1L, (long) moveTime[nx][ny] + 1L);
                if (arrive < dist[nx][ny]) {
                    dist[nx][ny] = arrive;
                    pq.offer(new Node(arrive, nx, ny));
                }
            }
        }
        return dist[n - 1][m - 1];
    }
}

