class Solution {
    public static long smallestDivisibleDigitProduct(long n, long t) {
        long cur = n;
        while (true) {
            long prod = 1;
            long temp = cur;
            if (temp == 0) prod = 0;
            while (temp > 0) {
                int digit = (int) (temp % 10);
                prod *= digit;
                temp /= 10;
                if (prod == 0) break;
            }
            if (prod % t == 0) {
                return cur;
            }
            cur++;
        }
    }
}

import java.util.*;

class Solution {
    public static int countBalancedPermutations(String num) {
        final int MOD = 1000000007;
        int n = num.length();
        int E = (n + 1) / 2;
        int O = n / 2;
        int total = 0;
        int[] cnt = new int[10];
        for (int i = 0; i < n; i++) {
            int d = num.charAt(i) - '0';
            cnt[d]++;
            total += d;
        }
        if ((total & 1) == 1) return 0;
        int target = total / 2;
        if (target > 9 * E) return 0;
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2, MOD);
        for (int i = n; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }
        long[][] dp = new long[E + 1][target + 1];
        dp[0][0] = 1;
        for (int d = 0; d <= 9; d++) {
            int c = cnt[d];
            if (c == 0) continue;
            long[] contrib = new long[c + 1];
            for (int k = 0; k <= c; k++) {
                contrib[k] = invFact[k] * invFact[c - k] % MOD;
            }
            long[][] ndp = new long[E + 1][target + 1];
            for (int e = 0; e <= E; e++) {
                for (int s = 0; s <= target; s++) {
                    long cur = dp[e][s];
                    if (cur == 0) continue;
                    for (int k = 0; k <= c; k++) {
                        int ne = e + k;
                        int ns = s + k * d;
                        if (ne > E || ns > target) continue;
                        ndp[ne][ns] = (ndp[ne][ns] + cur * contrib[k]) % MOD;
                    }
                }
            }
            dp = ndp;
        }
        long ways = dp[E][target];
        ways = ways * fact[E] % MOD * fact[O] % MOD;
        return (int) ways;
    }

    private static long modPow(long a, long e, int mod) {
        long r = 1 % mod;
        long base = a % mod;
        while (e > 0) {
            if ((e & 1) == 1) r = r * base % mod;
            base = base * base % mod;
            e >>= 1;
        }
        return r;
    }
}

