public class Solution {
    public static boolean check(int[] nums, int k) {
        int n = nums.length;
        if (n < 2 * k) return false;
        int[] inc = new int[n - 1];
        for (int i = 0; i < n - 1; ++i) {
            inc[i] = (nums[i] < nums[i + 1]) ? 1 : 0;
        }
        int[] pref = new int[n];
        for (int i = 0; i < n - 1; ++i) {
            pref[i + 1] = pref[i] + inc[i];
        }
        for (int a = 0; a + 2 * k <= n; ++a) {
            int sum1 = pref[a + k - 1] - pref[a];
            int sum2 = pref[a + 2 * k - 1] - pref[a + k];
            if (sum1 == k - 1 && sum2 == k - 1) {
                return true;
            }
        }
        return false;
    }
}

