class Solution {
    public static int maxFrequency(int[] nums, int k, int numOperations) {
        if (k == 0) {
            Map<Integer, Integer> cnt = new HashMap<>();
            int best = 0;
            for (int v : nums) {
                int c = cnt.getOrDefault(v, 0) + 1;
                cnt.put(v, c);
                if (c > best) best = c;
            }
            return best;
        }

        Map<Integer, List<Long>> groups = new HashMap<>(nums.length * 2);
        for (int v : nums) {
            int r = v % k;
            long base = ((long) v - r) / k;
            groups.computeIfAbsent(r, key -> new ArrayList<>()).add(base);
        }

        int answer = 0;
        for (List<Long> bases : groups.values()) {
            Collections.sort(bases);
            long sum = 0;
            int left = 0;
            for (int right = 0; right < bases.size(); ++right) {
                sum += bases.get(right);
                while (bases.get(right) * (right - left + 1) - sum > (long) numOperations) {
                    sum -= bases.get(left);
                    left++;
                }
                int size = right - left + 1;
                if (size > answer) answer = size;
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public static int maxFrequencyAfterOperations(int[] nums, int k, int numOperations) {
        int n = nums.length;
        int[] sorted = Arrays.copyOf(nums, n);
        Arrays.sort(sorted);
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        int ans = 0;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int v = entry.getKey();
            int cntSame = entry.getValue();
            int left = lowerBound(sorted, v - k);
            int right = upperBound(sorted, v + k) - 1;
            int intervalCount = (right >= left) ? (right - left + 1) : 0;
            int cntOther = intervalCount - cntSame;
            int possible = cntSame + Math.min(numOperations, cntOther);
            if (possible > ans) ans = possible;
        }
        return ans;
    }

    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

import java.util.*;

class Solution {
    public static int max_adjacent_increasing_subarrays(int[] nums) {
        int n = nums.length;
        if (n < 2) {
            return 0;
        }
        int[] inc = new int[n];
        inc[n - 1] = 1;
        for (int i = n - 2; i >= 0; --i) {
            inc[i] = (nums[i] < nums[i + 1]) ? inc[i + 1] + 1 : 1;
        }
        java.util.function.IntPredicate can = (int k) -> {
            int limit = n - 2 * k;
            if (limit < 0) return false;
            for (int i = 0; i <= limit; ++i) {
                if (inc[i] >= k && inc[i + k] >= k) {
                    return true;
                }
            }
            return false;
        };
        int low = 0, high = n / 2;
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (can.test(mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
}

class Solution {
    public static int countValidSelections(int[] nums) {
        long total = 0;
        for (int v : nums) total += v;
        long leftSum = 0;
        int zerosEqual = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 0) {
                long rightSum = total - leftSum - nums[i];
                if (leftSum == rightSum) zerosEqual++;
            }
            leftSum += nums[i];
        }
        return zerosEqual * 2;
    }
}

import java.util.*;

class Solution {
    public static String smallestNumber(String num, long t) {
        int[] primes = {2, 3, 5, 7};
        int[] need = new int[4];
        long tmp = t;
        for (int i = 0; i < 4; i++) {
            while (tmp % primes[i] == 0) { need[i]++; tmp /= primes[i]; }
        }
        if (tmp != 1) return "-1";

        int[][] contrib = new int[10][4];
        contrib[2] = new int[]{1,0,0,0};
        contrib[3] = new int[]{0,1,0,0};
        contrib[4] = new int[]{2,0,0,0};
        contrib[5] = new int[]{0,0,1,0};
        contrib[6] = new int[]{1,1,0,0};
        contrib[7] = new int[]{0,0,0,1};
        contrib[8] = new int[]{3,0,0,0};
        contrib[9] = new int[]{0,2,0,0};
        int[] maxPerDigit = {3,2,1,1};

        int n = num.length();
        int[] digits = new int[n];
        for (int i = 0; i < n; i++) digits[i] = num.charAt(i) - '0';

        int firstZero = n;
        for (int i = 0; i < n; i++) if (digits[i] == 0) { firstZero = i; break; }

        if (firstZero == n) {
            int[] exp = new int[4];
            for (int dd : digits) for (int k = 0; k < 4; k++) exp[k] += contrib[dd][k];
            boolean ok = true;
            for (int k = 0; k < 4; k++) if (exp[k] < need[k]) ok = false;
            if (ok) return num;
        }

        int maxI = Math.min(n - 1, firstZero);
        for (int i = maxI; i >= 0; i--) {
            int[] prefixExp = new int[4];
            for (int j = 0; j < i; j++) for (int k = 0; k < 4; k++) prefixExp[k] += contrib[digits[j]][k];
            for (int dgt = digits[i] + 1; dgt <= 9; dgt++) {
                int[] rn = new int[4];
                for (int k = 0; k < 4; k++) rn[k] = Math.max(0, need[k] - prefixExp[k] - contrib[dgt][k]);
                String suf = fillSuffix(rn, n - i - 1, contrib, maxPerDigit);
                if (suf != null) {
                    return num.substring(0, i) + dgt + suf;
                }
            }
        }

        for (int len = n + 1; len <= n + 80; len++) {
            String suf = fillSuffix(need.clone(), len, contrib, maxPerDigit);
            if (suf != null) return suf;
        }
        return "-1";
    }

    private static boolean feasible(int[] remNeed, int slots, int[] maxPerDigit) {
        for (int k = 0; k < 4; k++) if (remNeed[k] > slots * maxPerDigit[k]) return false;
        return true;
    }

    private static String fillSuffix(int[] remNeed, int len, int[][] contrib, int[] maxPerDigit) {
        if (!feasible(remNeed, len, maxPerDigit)) return null;
        return dfs(remNeed, len, contrib, maxPerDigit);
    }

    private static String dfs(int[] remNeed, int len, int[][] contrib, int[] maxPerDigit) {
        if (remNeed[0] == 0 && remNeed[1] == 0 && remNeed[2] == 0 && remNeed[3] == 0) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++) sb.append('1');
            return sb.toString();
        }
        for (int d = 1; d <= 9; d++) {
            int[] nrn = new int[4];
            for (int k = 0; k < 4; k++) nrn[k] = Math.max(0, remNeed[k] - contrib[d][k]);
            if (feasible(nrn, len - 1, maxPerDigit)) {
                String rest = dfs(nrn, len - 1, contrib, maxPerDigit);
                if (rest != null) return "" + d + rest;
            }
        }
        return null;
    }
}

