public class Solution {
    public static long sumGoodSubsequences(int[] nums) {
        final long MOD = 1000000007L;
        if (nums == null || nums.length == 0) return 0L;
        int maxVal = nums[0];
        for (int v : nums) {
            if (v > maxVal) maxVal = v;
        }
        long[] cnt = new long[maxVal + 3];
        long[] sum = new long[maxVal + 3];
        long answer = 0L;
        for (int a : nums) {
            long leftCnt = (a > 0) ? cnt[a - 1] : 0L;
            long rightCnt = cnt[a + 1];
            long leftSum = (a > 0) ? sum[a - 1] : 0L;
            long rightSum = sum[a + 1];
            long addCnt = (1L + leftCnt + rightCnt) % MOD;
            long aMod = ((long) a) % MOD;
            long addSum = (aMod + (leftSum + rightSum) % MOD
                    + (aMod * ((leftCnt + rightCnt) % MOD)) % MOD) % MOD;
            cnt[a] = (cnt[a] + addCnt) % MOD;
            sum[a] = (sum[a] + addSum) % MOD;
            answer = (answer + addSum) % MOD;
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public static int countKReducibleNumbers(String s, int k) {
        final long MOD = 1000000007L;
        int L = s.length();

        long[][] C = new long[L + 1][L + 1];
        for (int i = 0; i <= L; ++i) {
            C[i][0] = 1;
            C[i][i] = 1;
            for (int j = 1; j < i; ++j) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }

        int[] steps = new int[L + 1];
        if (L >= 1) steps[1] = 0;
        for (int c = 2; c <= L; ++c) {
            int pc = Integer.bitCount(c);
            steps[c] = 1 + steps[pc];
        }

        List<Integer> good = new ArrayList<>();
        for (int c = 1; c <= L; ++c) {
            if (steps[c] <= k - 1) good.add(c);
        }

        long total = 0;
        for (int target : good) {
            long ans = 0;
            int onesSoFar = 0;
            for (int i = 0; i < L; ++i) {
                if (s.charAt(i) == '1') {
                    int remaining = L - i - 1;
                    int need = target - onesSoFar;
                    if (need >= 0 && need <= remaining) {
                        ans = (ans + C[remaining][need]) % MOD;
                    }
                    ++onesSoFar;
                    if (onesSoFar > target) break;
                }
            }
            total = (total + ans) % MOD;
        }
        return (int) total;
    }
}

