class Solution {
    public static long shiftDistance(String s, String t, int[] nextCost, int[] previousCost) {
        int n = s.length();
        long[] prefNext = new long[27];
        long[] prefPrev = new long[27];
        for (int i = 0; i < 26; ++i) {
            prefNext[i + 1] = prefNext[i] + nextCost[i];
            prefPrev[i + 1] = prefPrev[i] + previousCost[i];
        }
        long total = 0;
        for (int i = 0; i < n; ++i) {
            int a = s.charAt(i) - 'a';
            int b = t.charAt(i) - 'a';
            long forward;
            if (a <= b) {
                forward = prefNext[b] - prefNext[a];
            } else {
                forward = (prefNext[26] - prefNext[a]) + prefNext[b];
            }
            long backward;
            if (a >= b) {
                backward = prefPrev[a + 1] - prefPrev[b + 1];
            } else {
                backward = prefPrev[a + 1] + (prefPrev[26] - prefPrev[b + 1]);
            }
            total += Math.min(forward, backward);
        }
        return total;
    }
}

import java.lang.Math;

class Solution {
    public static long minimizeMaxDiff(int[] nums) {
        int n = nums.length;
        long base = 0;
        long minV = Long.MAX_VALUE;
        long maxV = Long.MIN_VALUE;
        for (int i = 0; i + 1 < n; ++i) {
            long a = nums[i];
            long b = nums[i + 1];
            if (a != -1 && b != -1) {
                long diff = Math.abs(a - b);
                if (diff > base) base = diff;
            }
            if (a == -1 && b != -1) {
                if (b < minV) minV = b;
                if (b > maxV) maxV = b;
            }
            if (a != -1 && b == -1) {
                if (a < minV) minV = a;
                if (a > maxV) maxV = a;
            }
        }
        if (minV == Long.MAX_VALUE) {
            return 0;
        }
        long diff = maxV - minV;
        long kDiff = (diff + 1) / 2;
        return Math.max(base, kDiff);
    }
}

class Solution {
    public int minZeroArray(int[] nums, int[][] queries) {
        int n = nums.length, m = queries.length;
        if (!feasible(nums, queries, m)) return -1;
        int lo = 0, hi = m;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (feasible(nums, queries, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
    private boolean feasible(int[] nums, int[][] queries, int k) {
        int n = nums.length;
        long[] diff = new long[n+1];
        for (int i = 0; i < k; i++) {
            int l = queries[i][0], r = queries[i][1], val = queries[i][2];
            diff[l] += val;
            diff[r+1] -= val;
        }
        long cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur < nums[i]) return false;
        }
        return true;
    }
}

class Solution {
    public int maxCollectedFruits(int[][] fruits) {
        int n = fruits.length;
        final int INF = Integer.MIN_VALUE/2;
        int[][] f = new int[n][n];
        for (int[] row : f) java.util.Arrays.fill(row, INF);
        f[0][n-1] = fruits[0][n-1];
        for (int i = 1; i < n; i++) {
            for (int j = i+1; j < n; j++) {
                int best = Math.max(f[i-1][j], f[i-1][j-1]);
                if (j+1 < n) best = Math.max(best, f[i-1][j+1]);
                f[i][j] = best + fruits[i][j];
            }
        }
        int[][] g = new int[n][n];
        for (int[] row : g) java.util.Arrays.fill(row, INF);
        g[n-1][0] = fruits[n-1][0];
        for (int j = 1; j < n; j++) {
            for (int i = j+1; i < n; i++) {
                int best = Math.max(g[i][j-1], g[i-1][j-1]);
                if (i+1 < n) best = Math.max(best, g[i+1][j-1]);
                g[i][j] = best + fruits[i][j];
            }
        }
        int ans = f[n-2][n-1] + g[n-1][n-2];
        for (int i = 0; i < n; i++) ans += fruits[i][i];
        return ans;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static boolean canRearrange(String s, String t, int k) {
        int n = s.length();
        if (n != t.length()) return false;
        if (k == 0) return false;
        if (n % k != 0) return false;
        int blockSize = n / k;
        Map<String, Integer> blockCount = new HashMap<>();
        for (int i = 0; i < n; i += blockSize) {
            String block = s.substring(i, i + blockSize);
            blockCount.put(block, blockCount.getOrDefault(block, 0) + 1);
        }
        for (int i = 0; i < n; i += blockSize) {
            String block = t.substring(i, i + blockSize);
            Integer cnt = blockCount.get(block);
            if (cnt == null || cnt == 0) return false;
            blockCount.put(block, cnt - 1);
        }
        return true;
    }
}

