class Solution {
    public static int max_removable_queries(int[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        List<Integer>[] startAt = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            startAt[i] = new ArrayList<>();
        }
        for (int i = 0; i < q; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            startAt[l].add(r);
        }
        PriorityQueue<Integer> startHeap = new PriorityQueue<>();
        PriorityQueue<Integer> selectedHeap = new PriorityQueue<>();
        int active = 0;
        int used = 0;
        for (int i = 0; i < n; i++) {
            for (int r : startAt[i]) {
                startHeap.offer(r);
            }
            while (!selectedHeap.isEmpty() && selectedHeap.peek() < i) {
                selectedHeap.poll();
                active--;
            }
            while (active < nums[i]) {
                if (startHeap.isEmpty()) {
                    return -1;
                }
                int r = startHeap.poll();
                selectedHeap.offer(r);
                active++;
                used++;
            }
        }
        return q - used;
    }
}

