class Solution {
    public static long largestOutlier(int[] nums) {
        long total = 0;
        for (int v : nums) {
            total += v;
        }
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        long best = Long.MIN_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int sumCandidate = nums[i];
            long outlier = total - 2L * sumCandidate;
            Integer count = freq.get((int) outlier);
            if (count == null) continue;
            if (outlier == sumCandidate && count < 2) continue;
            if (outlier > best) best = outlier;
        }
        return best;
    }
}

import java.util.*;
class Solution {
    public static long maxRemainingWeight(int[][] edges, int k) {
        int n = edges.length + 1;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        long[] dpFull = new long[n];
        long[] dpReserved = new long[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0); visited[0] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            order.add(u);
            for (int[] vw : adj.get(u)) {
                if (!visited[vw[0]]) { visited[vw[0]] = true; parent[vw[0]] = u; stack.push(vw[0]); }
            }
        }
        for (int idx = order.size()-1; idx >= 0; idx--) {
            int u = order.get(idx);
            long baseSum = 0;
            List<Long> gains = new ArrayList<>();
            for (int[] vw : adj.get(u)) {
                if (vw[0] == parent[u]) continue;
                baseSum += dpFull[vw[0]];
                long gain = (vw[1] + dpReserved[vw[0]]) - dpFull[vw[0]];
                if (gain > 0) gains.add(gain);
            }
            gains.sort(Collections.reverseOrder());
            int mFull = k, mReserved = Math.max(0, k-1);
            long sumFull = 0;
            for (int i = 0; i < Math.min(mFull, gains.size()); i++) sumFull += gains.get(i);
            long sumReserved = 0;
            for (int i = 0; i < Math.min(mReserved, gains.size()); i++) sumReserved += gains.get(i);
            dpFull[u] = baseSum + sumFull;
            dpReserved[u] = baseSum + sumReserved;
        }
        return dpFull[0];
    }
}

