public class Solution {
    public static int[] maximizeTargetNodes(List<List<Integer>> edges1, List<List<Integer>> edges2, int k) {
        int n = edges1.size() + 1;
        int m = edges2.size() + 1;

        List<List<Integer>> adj1 = buildAdj(n, edges1);
        List<List<Integer>> adj2 = buildAdj(m, edges2);

        short[][] dist1 = allPairsDist(n, adj1);
        short[][] dist2 = allPairsDist(m, adj2);

        short[] countFirst = new short[n];
        for (int i = 0; i < n; ++i) {
            short cnt = 0;
            short[] drow = dist1[i];
            for (int j = 0; j < n; ++j) {
                short d = drow[j];
                if (d != -1 && d <= k) ++cnt;
            }
            countFirst[i] = cnt;
        }

        short[] bestSecond = new short[k + 1];
        for (int v = 0; v < m; ++v) {
            short[] cnt = new short[k + 1];
            short[] drow = dist2[v];
            for (int w = 0; w < m; ++w) {
                short d = drow[w];
                if (d != -1 && d <= k) ++cnt[d];
            }
            for (int r = 1; r <= k; ++r) cnt[r] += cnt[r - 1];
            for (int r = 0; r <= k; ++r) {
                if (cnt[r] > bestSecond[r]) bestSecond[r] = cnt[r];
            }
        }

        short[] answer = new short[n];
        for (int i = 0; i < n; ++i) {
            short maxAdd = 0;
            short[] drow = dist1[i];
            for (int u = 0; u < n; ++u) {
                short d = drow[u];
                int R = k - d - 1;
                if (R >= 0) {
                    short add = bestSecond[R];
                    if (add > maxAdd) maxAdd = add;
                }
            }
            answer[i] = (short) (countFirst[i] + maxAdd);
        }

        int[] result = new int[answer.length];
        for (int i = 0; i < answer.length; ++i) result[i] = answer[i];
        return result;
    }

    private static List<List<Integer>> buildAdj(int num, List<List<Integer>> edges) {
        List<List<Integer>> adj = new ArrayList<>(num);
        for (int i = 0; i < num; ++i) adj.add(new ArrayList<>());
        for (List<Integer> e : edges) {
            int a = e.get(0);
            int b = e.get(1);
            adj.get(a).add(b);
            adj.get(b).add(a);
        }
        return adj;
    }

    private static short[][] allPairsDist(int num, List<List<Integer>> adj) {
        short[][] dist = new short[num][num];
        for (int i = 0; i < num; ++i) Arrays.fill(dist[i], (short) -1);
        int[] queue = new int[num];
        for (int s = 0; s < num; ++s) {
            short[] d = dist[s];
            Arrays.fill(d, (short) -1);
            int head = 0, tail = 0;
            d[s] = 0;
            queue[tail++] = s;
            while (head < tail) {
                int u = queue[head++];
                short du = d[u];
                for (int v : adj.get(u)) {
                    if (d[v] == -1) {
                        d[v] = (short) (du + 1);
                        queue[tail++] = v;
                    }
                }
            }
        }
        return dist;
    }
}

