class Solution {
    public static long smallestAllSetBits(long n) {
        if (n <= 0) {
            return 0L;
        }
        long num = n;
        int len = 0;
        long tmp = num;
        while (tmp > 0) {
            tmp >>>= 1;
            ++len;
        }
        long candidate;
        if (len >= 64) {
            candidate = -1L;
        } else {
            candidate = (1L << len) - 1L;
        }
        if (Long.compareUnsigned(candidate, num) >= 0) {
            return candidate;
        }
        long result;
        if (len + 1 >= 64) {
            result = -1L;
        } else {
            result = (1L << (len + 1)) - 1L;
        }
        return result;
    }
}

