import java.util.PriorityQueue;

public class Solution {
    private static boolean isPrime(long x) {
        if (x <= 1) return false;
        if (x == 2) return true;
        if (x % 2 == 0) return false;
        long r = (long) Math.sqrt((double) x);
        for (long i = 3; i <= r; i += 2) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public static long minimumTransformationCost(long n, long m) {
        String sn = String.valueOf(n);
        String sm = String.valueOf(m);
        int lenN = sn.length();
        int lenM = sm.length();
        if (lenN != lenM) return -1;
        int d = lenN;

        if (isPrime(n) || isPrime(m)) return -1;
        if (n == m) return n;

        int maxVal = 1;
        for (int i = 0; i < d; ++i) maxVal *= 10;
        maxVal -= 1;

        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[maxVal + 1];
        boolean[] visited = new boolean[maxVal + 1];
        for (int i = 0; i <= maxVal; ++i) dist[i] = INF;

        class Node {
            long dist;
            int val;
            Node(long dist, int val) {
                this.dist = dist;
                this.val = val;
            }
        }

        PriorityQueue<Node> heap = new PriorityQueue<>((a, b) -> Long.compare(a.dist, b.dist));

        dist[(int) n] = n;
        heap.add(new Node(n, (int) n));

        while (!heap.isEmpty()) {
            Node top = heap.poll();
            long curDist = top.dist;
            int u = top.val;
            if (visited[u]) continue;
            visited[u] = true;
            if (u == m) return curDist;

            String s = String.valueOf(u);
            if (s.length() < d) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < d - s.length(); ++i) sb.append('0');
                sb.append(s);
                s = sb.toString();
            }

            for (int i = 0; i < d; ++i) {
                int digit = s.charAt(i) - '0';
                if (digit > 0) {
                    if (!(i == 0 && digit == 1)) {
                        char[] tArr = s.toCharArray();
                        tArr[i] = (char) ('0' + (digit - 1));
                        long v = Long.parseLong(new String(tArr));
                        if (!isPrime(v) && curDist + v < dist[(int) v]) {
                            dist[(int) v] = curDist + v;
                            heap.add(new Node(dist[(int) v], (int) v));
                        }
                    }
                }
                if (digit < 9) {
                    char[] tArr = s.toCharArray();
                    tArr[i] = (char) ('0' + (digit + 1));
                    long v = Long.parseLong(new String(tArr));
                    if (!isPrime(v) && curDist + v < dist[(int) v]) {
                        dist[(int) v] = curDist + v;
                        heap.add(new Node(dist[(int) v], (int) v));
                    }
                }
            }
        }

        return -1;
    }
}

import java.util.*;

class Solution {
    private static class DSU {
        int[] parent;
        int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void unite(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) rank[ra]++;
        }
    }

    public static int countComponents(int[] nums, int threshold) {
        int n = nums.length;
        DSU dsu = new DSU(n);
        int[] rep = new int[threshold + 1];
        Arrays.fill(rep, -1);
        for (int i = 0; i < n; i++) {
            int val = nums[i];
            if (val > threshold) continue;
            for (int mult = val; mult <= threshold; mult += val) {
                if (rep[mult] == -1) {
                    rep[mult] = i;
                } else {
                    dsu.unite(i, rep[mult]);
                }
            }
        }
        Set<Integer> components = new HashSet<>();
        for (int i = 0; i < n; i++) {
            components.add(dsu.find(i));
        }
        return components.size();
    }
}

