public class Solution {
    public static int[] maxTargetCount(List<List<Integer>> edges1, List<List<Integer>> edges2) {
        int n = edges1.size() + 1;
        int m = edges2.size() + 1;
        List<List<Integer>> adj1 = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj1.add(new ArrayList<>());
        for (List<Integer> e : edges1) {
            int u = e.get(0);
            int v = e.get(1);
            adj1.get(u).add(v);
            adj1.get(v).add(u);
        }
        List<List<Integer>> adj2 = new ArrayList<>(m);
        for (int i = 0; i < m; i++) adj2.add(new ArrayList<>());
        for (List<Integer> e : edges2) {
            int u = e.get(0);
            int v = e.get(1);
            adj2.get(u).add(v);
            adj2.get(v).add(u);
        }
        int[] color1 = new int[n];
        int[] color2 = new int[m];
        Arrays.fill(color1, -1);
        Arrays.fill(color2, -1);
        Queue<Integer> q = new ArrayDeque<>();
        color1[0] = 0;
        q.add(0);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int nb : adj1.get(v)) {
                if (color1[nb] == -1) {
                    color1[nb] = color1[v] ^ 1;
                    q.add(nb);
                }
            }
        }
        color2[0] = 0;
        q.add(0);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int nb : adj2.get(v)) {
                if (color2[nb] == -1) {
                    color2[nb] = color2[v] ^ 1;
                    q.add(nb);
                }
            }
        }
        long cnt1_0 = 0, cnt1_1 = 0;
        for (int c : color1) {
            if (c == 0) cnt1_0++;
            else cnt1_1++;
        }
        long cnt2_0 = 0, cnt2_1 = 0;
        for (int c : color2) {
            if (c == 0) cnt2_0++;
            else cnt2_1++;
        }
        long add = Math.max(cnt2_0, cnt2_1);
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            long base = (color1[i] == 0) ? cnt1_0 : cnt1_1;
            answer[i] = (int) (base + add);
        }
        return answer;
    }
}

public class Solution {
