class Solution {
    public static int maxAreaRectangle(List<List<Integer>> points) {
        int n = points.size();
        Set<String> pointSet = new HashSet<>();
        for (List<Integer> p : points) {
            pointSet.add(p.get(0) + "," + p.get(1));
        }
        int best = -1;
        for (int i = 0; i < n; ++i) {
            int x1 = points.get(i).get(0);
            int y1 = points.get(i).get(1);
            for (int j = i + 1; j < n; ++j) {
                int x2 = points.get(j).get(0);
                int y2 = points.get(j).get(1);
                if (x1 == x2 || y1 == y2) continue;
                String c1 = x1 + "," + y2;
                String c2 = x2 + "," + y1;
                if (!pointSet.contains(c1) || !pointSet.contains(c2)) continue;
                int minX = Math.min(x1, x2);
                int maxX = Math.max(x1, x2);
                int minY = Math.min(y1, y2);
                int maxY = Math.max(y1, y2);
                boolean ok = true;
                for (List<Integer> p : points) {
                    int x = p.get(0);
                    int y = p.get(1);
                    if ((x == x1 && y == y1) ||
                        (x == x2 && y == y2) ||
                        (x == x1 && y == y2) ||
                        (x == x2 && y == y1)) {
                        continue;
                    }
                    if (x >= minX && x <= maxX && y >= minY && y <= maxY) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    int area = (maxX - minX) * (maxY - minY);
                    if (area > best) best = area;
                }
            }
        }
        return best;
    }
}

