class Solution {
    public static int minOperationsToMakeGood(String s) {
        int n = s.length();
        int[] freq = new int[26];
        for (int i = 0; i < n; ++i) {
            freq[s.charAt(i) - 'a']++;
        }
        int[] sorted = freq.clone();
        Arrays.sort(sorted);
        int[] desc = new int[26];
        for (int i = 0; i < 26; ++i) {
            desc[i] = sorted[25 - i];
        }
        int best = n;
        for (int k = 1; k <= 26 && k <= n; ++k) {
            int sumTop = 0;
            for (int i = 0; i < k; ++i) sumTop += desc[i];
            int extra = n - sumTop;
            for (int f = 1; f <= n; ++f) {
                int surplus = extra;
                int deficit = 0;
                for (int i = 0; i < k; ++i) {
                    int cur = desc[i];
                    if (cur > f) surplus += cur - f;
                    else deficit += f - cur;
                }
                int ops = surplus > deficit ? surplus : deficit;
                if (ops < best) best = ops;
            }
        }
        return best;
    }
}

