class Solution {
    private static class Edge {
        int to;
        double weight;
        Edge(int to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    public static double maxAmountAfterTwoDays(
            String initialCurrency,
            List<List<String>> pairs1,
            double[] rates1,
            List<List<String>> pairs2,
            double[] rates2) {

        Map<String, Integer> id = new HashMap<>();
        java.util.function.Function<String, Integer> getId = s -> {
            Integer existing = id.get(s);
            if (existing != null) return existing;
            int newId = id.size();
            id.put(s, newId);
            return newId;
        };

        getId.apply(initialCurrency);
        for (List<String> p : pairs1) {
            getId.apply(p.get(0));
            getId.apply(p.get(1));
        }
        for (List<String> p : pairs2) {
            getId.apply(p.get(0));
            getId.apply(p.get(1));
        }

        int n = id.size();
        List<List<Edge>> adj1 = new ArrayList<>(n);
        List<List<Edge>> adj2 = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj1.add(new ArrayList<>());
            adj2.add(new ArrayList<>());
        }

        for (int i = 0; i < pairs1.size(); i++) {
            int u = id.get(pairs1.get(i).get(0));
            int v = id.get(pairs1.get(i).get(1));
            double r = rates1[i];
            adj1.get(u).add(new Edge(v, r));
            adj1.get(v).add(new Edge(u, 1.0 / r));
        }

        for (int i = 0; i < pairs2.size(); i++) {
            int u = id.get(pairs2.get(i).get(0));
            int v = id.get(pairs2.get(i).get(1));
            double r = rates2[i];
            adj2.get(u).add(new Edge(v, r));
            adj2.get(v).add(new Edge(u, 1.0 / r));
        }

        int start = id.get(initialCurrency);
        double[] f1 = computeFactors(adj1, start, n);
        double[] f2 = computeFactors(adj2, start, n);

        double best = 1.0;
        for (int i = 0; i < n; i++) {
            if (f1[i] > 0.0 && f2[i] > 0.0) {
                double candidate = f1[i] / f2[i];
                if (candidate > best) best = candidate;
            }
        }
        return best;
    }

    private static double[] computeFactors(List<List<Edge>> adj, int start, int n) {
        double[] f = new double[n];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        f[start] = 1.0;
        q.add(start);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (Edge e : adj.get(u)) {
                int v = e.to;
                double w = e.weight;
                if (f[v] == 0.0) {
                    f[v] = f[u] * w;
                    q.add(v);
                }
            }
        }
        return f;
    }
}

