public class Solution {
    public static int countBeautifulSplits(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;
        int[] prefixMax = new int[n];
        int[] suffixMin = new int[n];
        int curMax = nums[0];
        for (int i = 0; i < n; ++i) {
            if (nums[i] > curMax) curMax = nums[i];
            prefixMax[i] = curMax;
        }
        int curMin = nums[n - 1];
        for (int i = n - 1; i >= 0; --i) {
            if (nums[i] < curMin) curMin = nums[i];
            suffixMin[i] = curMin;
        }
        int count = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (prefixMax[i] == suffixMin[i + 1]) ++count;
        }
        return count;
    }
}

