class Solution {
    public boolean canMakeCuts(int n, int[][] rectangles) {
        // Check horizontal cuts
        if (hasTwoCuts(n, rectangles, true)) return true;
        // Check vertical cuts
        if (hasTwoCuts(n, rectangles, false)) return true;
        return false;
    }

    private boolean hasTwoCuts(int n, int[][] rects, boolean horizontal) {
        // Collect intervals of blocked interior lines
        int m = rects.length;
        int[][] intervals = new int[m][2];
        for (int i = 0; i < m; i++) {
            if (horizontal) {
                intervals[i][0] = rects[i][1]; // startY
                intervals[i][1] = rects[i][3]; // endY
            } else {
                intervals[i][0] = rects[i][0]; // startX
                intervals[i][1] = rects[i][2]; // endX
            }
        }
        Arrays.sort(intervals, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });

        int prev = 0;               // farthest blocked coordinate seen so far
        boolean firstFound = false; // have we already found one valid cut position?

        for (int[] inter : intervals) {
            int l = inter[0];
            int r = inter[1];

            if (prev < l) { // a genuine gap (prev, l)
                if (!firstFound) {
                    firstFound = true;
                } else {
                    return true; // second distinct cut found
                }
            } else if (prev == l) { // touching point at coordinate prev
                if (prev > 0 && prev < n) { // interior point
                    if (!firstFound) {
                        firstFound = true;
                    } else {
                        return true;
                    }
                }
            }
            // extend the blocked region
            if (r > prev) prev = r;
        }

        // Gap after the last interval
        if (prev < n) {
            if (!firstFound) {
                firstFound = true;
            } else {
                return true;
            }
        }

        return false;
    }
}

