class Solution {
    public int minLength(String s, int numOps) {
        int n = s.length();
        List<Integer> runs = new ArrayList<>();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) {
                j++;
            }
            runs.add(j - i);
            i = j;
        }

        int low = 1, high = n;
        while (low < high) {
            int mid = (low + high) / 2;
            long needed = 0;
            for (int len : runs) {
                needed += len / (mid + 1);
                if (needed > numOps) break;
            }
            if (needed <= numOps) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

