public class Solution {
    public int maxDistinctAfterOperations(int[] nums, int k) {
        Arrays.sort(nums);
        long last = Long.MIN_VALUE;
        int count = 0;
        for (int num : nums) {
            long left = (long) num - k;
            long right = (long) num + k;
            long candidate = Math.max(left, last + 1);
            if (candidate <= right) {
                count++;
                last = candidate;
            }
        }
        return count;
    }
}

class Solution {
    private static boolean can(String s, int n, int numOps, int limit) {
        int flips = 0;
        char cur = s.charAt(0);
        int run = 1;
        for (int i = 1; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == cur) {
                run++;
            } else {
                cur = ch;
                run = 1;
            }
            if (run > limit) {
                flips++;
                cur = cur == '0' ? '1' : '0';
                run = 1;
                if (flips > numOps) return false;
            }
        }
        return flips <= numOps;
    }

    public static int smallestLongestSubstring(String s, int numOps) {
        int n = s.length();
        int low = 1, high = n, ans = n;
        while (low <= high) {
            int mid = (low + high) >> 1;
            if (can(s, n, numOps, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

class Solution {
    public static String findLexicographicallyLargestString(String word, int numFriends) {
        int n = word.length();
        int maxLen = n - (numFriends - 1);
        String best = "";
        for (int i = 0; i <= n - maxLen; i++) {
            String sub = word.substring(i, i + maxLen);
            if (sub.compareTo(best) > 0) {
                best = sub;
            }
        }
        return best;
    }
}

