class Solution {
    public static boolean substringMatchingPattern(String s, String p) {
        int starPos = p.indexOf('*');
        String pre = p.substring(0, starPos);
        String suf = p.substring(starPos + 1);
        if (pre.isEmpty() && suf.isEmpty()) return true;
        if (pre.isEmpty()) return s.indexOf(suf) != -1;
        if (suf.isEmpty()) return s.indexOf(pre) != -1;
        for (int i = 0; i <= s.length() - pre.length(); i++) {
            if (s.substring(i, i + pre.length()).equals(pre)) {
                int after = i + pre.length();
                if (s.indexOf(suf, after) != -1) {
                    return true;
                }
            }
        }
        return false;
    }
}

