public class Solution {
    static final long MOD = 1_000_000_007L;

    public static int countArrays(int n, int m, int k) {
        if (k < 0 || k > n - 1) return 0;
        long comb = nCrMod(n - 1, k);
        long pow = modPow(m - 1L, n - k - 1);
        long ans = comb * (m % MOD) % MOD;
        ans = ans * pow % MOD;
        return (int) ans;
    }

    static long nCrMod(int N, int R) {
        if (R < 0 || R > N) return 0;
        long[] fact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        long[] invFact = new long[N + 1];
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }
        return fact[N] * invFact[R] % MOD * invFact[N - R] % MOD;
    }

    static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

class TaskManager {
        List<Node> heap = new ArrayList<>();
        Map<Integer,Node> taskMap = new HashMap<>();
        boolean less(Node a, Node b) { return a.priority != b.priority ? a.priority > b.priority : a.taskId > b.taskId; }
        void swap(int i, int j) { Node t=heap.get(i); heap.set(i,heap.get(j)); heap.set(j,t); heap.get(i).idx=i; heap.get(j).idx=j; }
        void heapifyUp(int i) { while(i>0){int p=(i-1)>>1; if(less(heap.get(i),heap.get(p))){swap(i,p);i=p;} else break;} }
        void heapifyDown(int i) { int n=heap.size(); while(true){int l=i*2+1,r=i*2+2,best=i; if(l<n&&less(heap.get(l),heap.get(best)))best=l; if(r<n&&less(heap.get(r),heap.get(best)))best=r; if(best!=i){swap(i,best);i=best;} else break;} }
        void removeAt(int idx) { swap(idx, heap.size()-1); Node removed=heap.remove(heap.size()-1); taskMap.remove(removed.taskId); if(idx<heap.size()){heapifyUp(idx);heapifyDown(idx);} }
        TaskManager(int[][] tasks) {
            for (int[] t: tasks) { Node node=new Node(t[0],t[1],t[2],heap.size()); heap.add(node); taskMap.put(t[1],node); }
            for (int i=(heap.size()>>1)-1;i>=0;i--) heapifyDown(i);
        }
        void add(int userId,int taskId,int priority) { if(taskMap.containsKey(taskId))return; Node node=new Node(userId,taskId,priority,heap.size()); heap.add(node); taskMap.put(taskId,node); heapifyUp(node.idx); }
        void edit(int taskId,int newPriority) { Node node=taskMap.get(taskId); if(node==null)return; node.priority=newPriority; heapifyUp(node.idx); heapifyDown(node.idx); }
        void rmv(int taskId) { Node node=taskMap.get(taskId); if(node==null)return; removeAt(node.idx); }
        int execTop() { if(heap.isEmpty())return -1; int userId=heap.get(0).userId; removeAt(0); return userId; }
    }

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int maxSubarraySumAfterRemoval(int[] nums) {
        int cur = 0;
        int best = Integer.MIN_VALUE;
        for (int x : nums) {
            cur = Math.max(cur + x, x);
            best = Math.max(best, cur);
        }
        int answer = best;
        Set<Integer> distinct = new HashSet<>();
        for (int x : nums) {
            distinct.add(x);
        }
        for (int v : distinct) {
            int curV = 0;
            int bestV = Integer.MIN_VALUE;
            boolean has = false;
            for (int x : nums) {
                if (x == v) {
                    continue;
                }
                has = true;
                curV = Math.max(curV + x, x);
                bestV = Math.max(bestV, curV);
            }
            if (has) {
                answer = Math.max(answer, bestV);
            }
        }
        return answer;
    }
}

