class Solution {
    public static long maximumCoins(int[][] coins, int k) {
        int n = coins.length;
        // sort by left coordinate
        Arrays.sort(coins, Comparator.comparingInt(a -> a[0]));
        long[] start = new long[n];
        long[] end = new long[n];
        long[] val = new long[n];
        for (int i = 0; i < n; i++) {
            start[i] = coins[i][0];
            end[i] = coins[i][1];
            val[i] = coins[i][2];
        }
        // prefix sum of total coins before each segment
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            long len = end[i] - start[i] + 1;
            pref[i + 1] = pref[i] + len * val[i];
        }

        // helper: total coins in all bags with coordinate <= x
        java.util.function.LongUnaryOperator getSum = (long x) -> {
            if (n == 0 || x < start[0]) return 0L;
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (start[mid] <= x) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            int idx = lo - 1; // last segment with start <= x
            long total = pref[idx];
            if (x >= end[idx]) {
                total += (end[idx] - start[idx] + 1) * val[idx];
            } else {
                total += (x - start[idx] + 1) * val[idx];
            }
            return total;
        };

        long best = 0;
        // consider starting at 1 (or the smallest possible coordinate)
        long L0 = 1;
        long R0 = L0 + k - 1;
        best = Math.max(best, getSum.applyAsLong(R0) - getSum.applyAsLong(L0 - 1));

        for (int i = 0; i < n; i++) {
            long L1 = start[i];
            long R1 = L1 + k - 1;
            long sum1 = getSum.applyAsLong(R1) - getSum.applyAsLong(L1 - 1);
            if (sum1 > best) best = sum1;

            long L2 = end[i] - k + 1;
            if (L2 < 1) L2 = 1;
            long R2 = L2 + k - 1;
            long sum2 = getSum.applyAsLong(R2) - getSum.applyAsLong(L2 - 1);
            if (sum2 > best) best = sum2;
        }
        return best;
    }
}

