public class Solution {
    public int longestProductEquivalentSubarray(int[] nums) {
        int n = nums.length;
        int[] primeMasks = new int[11];
        int[] primes = {2, 3, 5, 7};
        for (int i = 1; i <= 10; i++) {
            int mask = 0;
            for (int j = 0; j < primes.length; j++) {
                if (i % primes[j] == 0) {
                    mask |= 1 << j;
                }
            }
            primeMasks[i] = mask;
        }

        int[] masks = new int[n];
        for (int i = 0; i < n; i++) {
            masks[i] = primeMasks[nums[i]];
        }

        int left = 0;
        int curMask = 0;
        int best = 0;
        for (int right = 0; right < n; right++) {
            int m = masks[right];
            while ((curMask & m) != 0) {
                curMask ^= masks[left];
                left++;
            }
            curMask |= m;
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

