class Solution {
    public static int longestSubsequenceWithDecreasingAdjacentDifference(int[] nums) {
        int n = nums.length;
        final int MAX_DIFF = 300;
        int[][] dp = new int[n][MAX_DIFF + 1];
        int[][] suffix = new int[n][MAX_DIFF + 1];
        int answer = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                int d = Math.abs(nums[i] - nums[j]);
                int best = 2;
                int prev = suffix[j][d];
                if (prev > 0) {
                    int cand = prev + 1;
                    if (cand > best) best = cand;
                }
                if (best > dp[i][d]) {
                    dp[i][d] = best;
                    if (best > answer) answer = best;
                }
            }
            int curMax = 0;
            for (int d = MAX_DIFF; d >= 0; d--) {
                if (dp[i][d] > curMax) curMax = dp[i][d];
                suffix[i][d] = curMax;
            }
        }
        return answer;
    }
}

