class Solution {
    public static int[] maxScore(int[][] intervals) {
        int n = intervals.length;
        Interval[] arr = new Interval[n];
        for (int i = 0; i < n; i++) {
            arr[i] = new Interval(intervals[i][0], intervals[i][1], intervals[i][2], i);
        }
        Arrays.sort(arr, Comparator.comparingInt(a -> a.l));
        int[] starts = new int[n];
        for (int i = 0; i < n; i++) starts[i] = arr[i].l;
        int[] next = new int[n];
        for (int i = 0; i < n; i++) {
            int lo = i + 1, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (starts[mid] > arr[i].r) hi = mid;
                else lo = mid + 1;
            }
            next[i] = lo;
        }

        long[][] dp = new long[n + 1][5];
        int[][] len = new int[n + 1][5];
        int[][][] seq = new int[n + 1][5][4];

        for (int i = n - 1; i >= 0; i--) {
            for (int k = 0; k <= 4; k++) {
                long bestW = dp[i + 1][k];
                int bestL = len[i + 1][k];
                int[] bestSeq = seq[i + 1][k];

                if (k > 0) {
                    long takeW = arr[i].w + dp[next[i]][k - 1];
                    int takeL = 1 + len[next[i]][k - 1];
                    int[] takeSeq = new int[4];
                    takeSeq[0] = arr[i].idx;
                    System.arraycopy(seq[next[i]][k - 1], 0, takeSeq, 1, 3);
                    if (takeW > bestW) {
                        bestW = takeW;
                        bestL = takeL;
                        bestSeq = takeSeq;
                    } else if (takeW == bestW) {
                        int cmp = compareSeq(takeSeq, takeL, bestSeq, bestL);
                        if (cmp < 0) {
                            bestL = takeL;
                            bestSeq = takeSeq;
                        }
                    }
                }

                dp[i][k] = bestW;
                len[i][k] = bestL;
                System.arraycopy(bestSeq, 0, seq[i][k], 0, 4);
            }
        }

        int finalLen = len[0][4];
        int[] result = new int[finalLen];
        System.arraycopy(seq[0][4], 0, result, 0, finalLen);
        Arrays.sort(result);
        return result;
    }

    private static int compareSeq(int[] a, int lenA, int[] b, int lenB) {
        int min = Math.min(lenA, lenB);
        for (int i = 0; i < min; i++) {
            if (a[i] != b[i]) return Integer.compare(a[i], b[i]);
        }
        return Integer.compare(lenA, lenB);
    }

    private static class Interval {
        int l, r;
        long w;
        int idx;
        Interval(int l, int r, int w, int idx) {
            this.l = l;
            this.r = r;
            this.w = w;
            this.idx = idx;
        }
    }
}

class Solution {
    public int minMaxWeight(int n, int[][] edges, int threshold) {
        List<int[]>[] rev = new List[n];
        for (int i = 0; i < n; i++) rev[i] = new ArrayList<>();
        int maxW = 0;
        for (int[] e : edges) {
            rev[e[1]].add(new int[]{e[0], e[2]});
            maxW = Math.max(maxW, e[2]);
        }
        if (!feasible(rev, n, maxW)) return -1;
        int lo = 1, hi = maxW;
        while (lo < hi) {
            int mid = lo + (hi-lo)/2;
            if (feasible(rev, n, mid)) hi = mid; else lo = mid+1;
        }
        return lo;
    }

    private boolean feasible(List<int[]>[] rev, int n, int W) {
        boolean[] visited = new boolean[n];
        visited[0] = true;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(0);
        int count = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] p : rev[u]) {
                int v = p[0], w = p[1];
                if (w <= W && !visited[v]) {
                    visited[v] = true;
                    count++;
                    q.add(v);
                }
            }
        }
        return count == n;
    }
}

