class Solution {
    public static List<Integer> zigzagGridTraversal(int[][] grid) {
        List<Integer> result = new ArrayList<>();
        boolean take = true;
        int rows = grid.length;
        int cols = grid[0].length;
        for (int r = 0; r < rows; r++) {
            if (r % 2 == 0) {
                for (int c = 0; c < cols; c++) {
                    if (take) result.add(grid[r][c]);
                    take = !take;
                }
            } else {
                for (int c = cols - 1; c >= 0; c--) {
                    if (take) result.add(grid[r][c]);
                    take = !take;
                }
            }
        }
        return result;
    }
}

