class Solution {
    public static long minimumCostToMakeArraysIdentical(int[] arr, int[] brr, int k) {
        long total = 0;
        for (int i = 0; i < arr.length; i++) {
            long a = arr[i];
            long b = brr[i];
            long withoutFlip = Math.abs(a - b);
            long withFlip = (long) k + Math.abs(a + b);
            total += withoutFlip < withFlip ? withoutFlip : withFlip;
        }
        return total;
    }
}

