class Solution {
    public int maxProfit(int[][] coins) {
        int m = coins.length;
        int n = coins[0].length;
        long NEG = Long.MIN_VALUE / 4;
        long[][][] dp = new long[m][n][3];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(dp[i][j], NEG);
            }
        }
        dp[0][0][0] = coins[0][0];
        dp[0][0][1] = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                for (int k = 0; k <= 2; k++) {
                    long best = NEG;
                    if (i > 0) {
                        if (dp[i - 1][j][k] != NEG) {
                            best = Math.max(best, dp[i - 1][j][k] + coins[i][j]);
                        }
                        if (k > 0 && dp[i - 1][j][k - 1] != NEG) {
                            best = Math.max(best, dp[i - 1][j][k - 1]); // use a skip on this cell
                        }
                    }
                    if (j > 0) {
                        if (dp[i][j - 1][k] != NEG) {
                            best = Math.max(best, dp[i][j - 1][k] + coins[i][j]);
                        }
                        if (k > 0 && dp[i][j - 1][k - 1] != NEG) {
                            best = Math.max(best, dp[i][j - 1][k - 1]); // use a skip on this cell
                        }
                    }
                    dp[i][j][k] = best;
                }
            }
        }
        long ans = NEG;
        for (int k = 0; k <= 2; k++) {
            ans = Math.max(ans, dp[m - 1][n - 1][k]);
        }
        return (int) ans;
    }
}

class Solution {
    public static int maxCircularAdjacentDiff(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;
        int maxDiff = 0;
        for (int i = 0; i < n; i++) {
            int next = (i + 1) % n;
            int diff = Math.abs(nums[i] - nums[next]);
            if (diff > maxDiff) maxDiff = diff;
        }
        return maxDiff;
    }
}

import java.util.Arrays;

class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long base, long exp) {
        long result = 1L;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1L) == 1L) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }

    private static long modInv(long x) {
        return modPow(x, MOD - 2);
    }

    private static long comb(int m, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > m) return 0L;
        long res = fact[m];
        res = (res * invFact[r]) % MOD;
        res = (res * invFact[m - r]) % MOD;
        return res;
    }

    public static int sumMaxMinSubseq(int[] nums, int k) {
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1L;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[n] = modInv(fact[n]);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
        }
        long ans = 0L;
        int maxChoose = k - 1;
        for (int i = 0; i < n; i++) {
            int left = i;
            int right = n - 1 - i;
            long waysMax = 0L;
            int upMax = Math.min(maxChoose, left);
            for (int t = 0; t <= upMax; t++) {
                waysMax = (waysMax + comb(left, t, fact, invFact)) % MOD;
            }
            long waysMin = 0L;
            int upMin = Math.min(maxChoose, right);
            for (int t = 0; t <= upMin; t++) {
                waysMin = (waysMin + comb(right, t, fact, invFact)) % MOD;
            }
            long val = sorted[i] % MOD;
            long contrib = (val * ((waysMax + waysMin) % MOD)) % MOD;
            ans = (ans + contrib) % MOD;
        }
        return (int) ans;
    }
}

import java.util.*;

class Solution {
    private List<int[]>[] graph;
    private int[] values;
    private long[] prefix;
    private long bestLen;
    private int minNodes;
    private int left;
    private Map<Integer, Integer> lastPos;

    public int[] longestSpecialPath(int[][] edges, int[] nums) {
        int n = nums.length;
        values = nums;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            graph[u].add(new int[]{v, w});
            graph[v].add(new int[]{u, w});
        }
        prefix = new long[n];
        bestLen = 0;
        minNodes = 1;
        left = 0;
        lastPos = new HashMap<>();
        dfs(0, -1, 0L, 0);
        return new int[]{(int) bestLen, minNodes};
    }

    private void dfs(int node, int parent, long edgeLen, int depth) {
        if (depth == 0) {
            prefix[depth] = 0;
        } else {
            prefix[depth] = prefix[depth - 1] + edgeLen;
        }

        int val = values[node];
        Integer prevPosObj = lastPos.get(val);
        int prevPos = prevPosObj == null ? -1 : prevPosObj;

        int savedLeft = left;
        if (prevPos >= left) {
            left = prevPos + 1;
        }

        lastPos.put(val, depth);

        long curLen = prefix[depth] - prefix[left];
        int nodesCount = depth - left + 1;
        if (curLen > bestLen) {
            bestLen = curLen;
            minNodes = nodesCount;
        } else if (curLen == bestLen && nodesCount < minNodes) {
            minNodes = nodesCount;
        }

        for (int[] e : graph[node]) {
            int nxt = e[0];
            long w = e[1];
            if (nxt == parent) continue;
            dfs(nxt, node, w, depth + 1);
        }

        left = savedLeft;
        if (prevPos == -1) {
            lastPos.remove(val);
        } else {
            lastPos.put(val, prevPos);
        }
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;
    private static final long INV6 = modPow(6, MOD - 2);

    private static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public int sumManhattan(int m, int n, int k) {
        int N = m * n;
        // precompute factorials up to N
        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        // combination C(N-2, k-2)
        long comb = fact[N - 2] * invFact[k - 2] % MOD * invFact[N - k] % MOD;

        // compute S_m = m*(m-1)*(m+1)/6  (mod MOD)
        long Sm = ((long) m * (m - 1) % MOD) * (m + 1) % MOD;
        Sm = Sm * INV6 % MOD;

        // compute S_n = n*(n-1)*(n+1)/6  (mod MOD)
        long Sn = ((long) n * (n - 1) % MOD) * (n + 1) % MOD;
        Sn = Sn * INV6 % MOD;

        long n2 = (long) n * n % MOD;
        long m2 = (long) m * m % MOD;

        long D = (n2 * Sm % MOD + m2 * Sn % MOD) % MOD;

        long ans = comb * D % MOD;
        return (int) ans;
    }
}

public class Solution {
    public static int countPartitions(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;
        long total = 0;
        for (int v : nums) total += v;
        if (total % 2 != 0) return 0;
        return n - 1;
    }
}

import java.util.*;
class Solution {
    public static long sumSubarrayMins(int[] nums) {
        long total = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            List<Integer> cur = new ArrayList<>();
            for (int j = i; j < n; j++) {
                int pos = Collections.binarySearch(cur, nums[j]);
                if (pos < 0) pos = -(pos+1);
                cur.add(pos, nums[j]);
                int median = cur.get((cur.size()-1)/2);
                total += median;
            }
        }
        return total;
    }
}

import java.util.*;

class Solution {
    public static long minCost(int n, int[][] cost) {
        if (n == 0) return 0;
        if (n == 1) {
            return Math.min(cost[0][0], Math.min(cost[0][1], cost[0][2]));
        }
        long INF = Long.MAX_VALUE / 4;
        long answer = INF;
        for (int first = 0; first < 3; first++) {
            long dp0 = (first == 0) ? cost[0][0] : INF;
            long dp1 = (first == 1) ? cost[0][1] : INF;
            long dp2 = (first == 2) ? cost[0][2] : INF;
            for (int i = 1; i < n; i++) {
                long ndp0 = cost[i][0] + Math.min(dp1, dp2);
                long ndp1 = cost[i][1] + Math.min(dp0, dp2);
                long ndp2 = cost[i][2] + Math.min(dp0, dp1);
                dp0 = ndp0;
                dp1 = ndp1;
                dp2 = ndp2;
            }
            for (int last = 0; last < 3; last++) {
                if (last == first) continue;
                long val = (last == 0) ? dp0 : (last == 1) ? dp1 : dp2;
                if (val < answer) answer = val;
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public static long maxMinSumAtMostK(int[] nums, int k) {
        int n = nums.length;
        int[] leftGreater = new int[n];
        int[] rightGreater = new int[n];
        int[] leftSmaller = new int[n];
        int[] rightSmaller = new int[n];
        int[] stack = new int[n];
        int top;

        // previous greater (strict)
        top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && nums[stack[top]] <= nums[i]) top--;
            leftGreater[i] = (top >= 0) ? stack[top] : -1;
            stack[++top] = i;
        }

        // next greater or equal
        top = -1;
        for (int i = n - 1; i >= 0; i--) {
            while (top >= 0 && nums[stack[top]] < nums[i]) top--;
            rightGreater[i] = (top >= 0) ? stack[top] : n;
            stack[++top] = i;
        }

        // previous smaller (strict)
        top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && nums[stack[top]] >= nums[i]) top--;
            leftSmaller[i] = (top >= 0) ? stack[top] : -1;
            stack[++top] = i;
        }

        // next smaller or equal
        top = -1;
        for (int i = n - 1; i >= 0; i--) {
            while (top >= 0 && nums[stack[top]] > nums[i]) top--;
            rightSmaller[i] = (top >= 0) ? stack[top] : n;
            stack[++top] = i;
        }

        int S = k + 1;

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            int Lmax = i - leftGreater[i];
            int Rmax = rightGreater[i] - i;
            long pairsMax = countPairs(Lmax, Rmax, S);
            ans += (long) nums[i] * pairsMax;

            int Lmin = i - leftSmaller[i];
            int Rmin = rightSmaller[i] - i;
            long pairsMin = countPairs(Lmin, Rmin, S);
            ans += (long) nums[i] * pairsMin;
        }
        return ans;
    }

    private static long countPairs(int L, int R, int S) {
        int limit = S - R;
        int a = 0;
        if (limit > 0) a = Math.min(L, limit);
        long cnt = (long) a * R;
        int start = a + 1;
        int end = Math.min(L, S - 1);
        if (start <= end) {
            int num = end - start + 1;
            long sum = (long) num * S - ((long) (start + end) * num) / 2;
            cnt += sum;
        }
        return cnt;
    }
}

import java.util.*;

class Solution {
    public static long maxFreeTime(int eventTime, int k, int[] startTime, int[] endTime) {
        int n = startTime.length;
        int m = n + 1;
        long[] gaps = new long[m];
        gaps[0] = startTime[0];
        for (int i = 1; i < n; i++) {
            gaps[i] = (long) startTime[i] - endTime[i - 1];
        }
        gaps[m - 1] = (long) eventTime - endTime[n - 1];
        long totalFree = 0;
        for (long g : gaps) totalFree += g;
        if (k >= m - 1) return totalFree;
        Integer[] idx = new Integer[m];
        for (int i = 0; i < m; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Long.compare(gaps[b], gaps[a]));
        long[] prefix = new long[m + 1];
        prefix[0] = 0;
        for (int i = 0; i < m; i++) {
            prefix[i + 1] = prefix[i] + gaps[idx[i]];
        }
        int[] rank = new int[m];
        for (int i = 0; i < m; i++) {
            rank[idx[i]] = i;
        }
        long answer = 0;
        for (int i = 0; i < m; i++) {
            long sumTopK;
            if (rank[i] < k) {
                sumTopK = prefix[k + 1] - gaps[i];
            } else {
                sumTopK = prefix[k];
            }
            long candidate = gaps[i] + sumTopK;
            if (candidate > answer) answer = candidate;
        }
        return answer;
    }
}

import java.util.*;

public class T2_29 {
    static int[] countMentions(int numberOfUsers, String[][] events) {
        List<String[]> evs = new ArrayList<>(Arrays.asList(events));
        evs.sort((a, b) -> {
            int ta = Integer.parseInt(a[1]), tb = Integer.parseInt(b[1]);
            if (ta != tb) return ta - tb;
            int pa = a[0].equals("OFFLINE") ? 0 : 1;
            int pb = b[0].equals("OFFLINE") ? 0 : 1;
            return pa - pb;
        });

        int[] mentions = new int[numberOfUsers];
        long[] offlineUntil = new long[numberOfUsers];
        Arrays.fill(offlineUntil, -1);

        for (String[] e : evs) {
            String etype = e[0];
            long ts = Long.parseLong(e[1]);
            String content = e[2];
            if (etype.equals("OFFLINE")) {
                int uid = Integer.parseInt(content);
                offlineUntil[uid] = ts + 60;
            } else {
                if (content.equals("ALL")) {
                    for (int i = 0; i < numberOfUsers; i++) mentions[i]++;
                } else if (content.equals("HERE")) {
                    for (int i = 0; i < numberOfUsers; i++) {
                        if (offlineUntil[i] <= ts) mentions[i]++;
                    }
                } else {
                    for (String part : content.split(" ")) {
                        int uid = Integer.parseInt(part.substring(2));
                        mentions[uid]++;
                    }
                }
            }
        }
        return mentions;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(countMentions(2, new String[][]{{"MESSAGE","10","id1 id0"},{"OFFLINE","11","0"},{"MESSAGE","71","HERE"}})) + " expected [2, 2]");
        System.out.println(Arrays.toString(countMentions(2, new String[][]{{"MESSAGE","10","id1 id0"},{"OFFLINE","11","0"},{"MESSAGE","12","ALL"}})) + " expected [2, 2]");
        System.out.println(Arrays.toString(countMentions(2, new String[][]{{"OFFLINE","10","0"},{"MESSAGE","12","HERE"}})) + " expected [0, 1]");
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int maxFrequencyAfterSubarrayOperation(int[] nums, int k) {
        int n = nums.length;
        int originalCount = 0;
        Set<Integer> deltaSet = new HashSet<>();
        deltaSet.add(0);
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                originalCount++;
            }
            deltaSet.add(k - nums[i]);
        }
        int answer = originalCount;
        for (int delta : deltaSet) {
            if (delta == 0) continue;
            int cur = 0;
            int best = 0;
            int target = k - delta;
            for (int i = 0; i < n; i++) {
                if (nums[i] == k) {
                    cur -= 1;
                } else if (nums[i] == target) {
                    cur += 1;
                }
                if (cur < 0) cur = 0;
                if (cur > best) best = cur;
            }
            int candidate = originalCount + best;
            if (candidate > answer) answer = candidate;
        }
        return answer;
    }
}

import java.util.*;

public class Solution {
    public static List<List<Integer>> frequencies_of_shortest_supersequences(List<String> words) {
        Set<Character> lettersSet = new TreeSet<>();
        for (String w : words) {
            for (char c : w.toCharArray()) {
                lettersSet.add(c);
            }
        }
        List<Character> letters = new ArrayList<>(lettersSet);
        int n = letters.size();
        Map<Character, Integer> idx = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            idx.put(letters.get(i), i);
        }

        int[] outMask = new int[n];
        int[] selfLoop = new int[n];
        for (String w : words) {
            char a = w.charAt(0);
            char b = w.charAt(1);
            int i = idx.get(a);
            int j = idx.get(b);
            if (i == j) {
                selfLoop[i] = 1;
            } else {
                outMask[i] |= (1 << j);
            }
        }

        int fullMask = (1 << n) - 1;
        final int INF = 1_000_000_000;
        int[] dpCost = new int[1 << n];
        Arrays.fill(dpCost, INF);
        dpCost[0] = 0;

        for (int mask = 1; mask <= fullMask; ++mask) {
            int best = INF;
            for (int v = 0; v < n; ++v) {
                if ((mask & (1 << v)) != 0) {
                    int prev = mask ^ (1 << v);
                    int costV = Integer.bitCount(outMask[v] & prev);
                    int cand = dpCost[prev] + costV;
                    if (cand < best) best = cand;
                }
            }
            dpCost[mask] = best;
        }

        @SuppressWarnings("unchecked")
        Set<List<Integer>>[] dpVec = new Set[1 << n];
        List<Integer> zeroVec = new ArrayList<>(Collections.nCopies(n, 0));
        dpVec[0] = new HashSet<>();
        dpVec[0].add(zeroVec);

        for (int mask = 1; mask <= fullMask; ++mask) {
            dpVec[mask] = new HashSet<>();
            for (int v = 0; v < n; ++v) {
                if ((mask & (1 << v)) != 0) {
                    int prev = mask ^ (1 << v);
                    int costV = Integer.bitCount(outMask[v] & prev);
                    if (dpCost[mask] == dpCost[prev] + costV) {
                        for (List<Integer> vec : dpVec[prev]) {
                            List<Integer> lst = new ArrayList<>(vec);
                            lst.set(v, lst.get(v) + costV);
                            dpVec[mask].add(lst);
                        }
                    }
                }
            }
        }

        List<List<Integer>> result = new ArrayList<>();
        for (List<Integer> vec : dpVec[fullMask]) {
            List<Integer> freq = new ArrayList<>(Collections.nCopies(26, 0));
            for (int i = 0; i < n; ++i) {
                char ch = letters.get(i);
                int cnt = 1 + selfLoop[i] + vec.get(i);
                freq.set(ch - 'a', cnt);
            }
            result.add(freq);
        }

        result.sort((a, b) -> {
            for (int i = 0; i < 26; ++i) {
                int diff = a.get(i) - b.get(i);
                if (diff != 0) return diff;
            }
            return 0;
        });

        return result;
    }
}

import java.util.*;

class Solution {
    public static String minCostGoodCaption(String caption) {
        final int n = caption.length();
        if (n < 3) return "";
        final int MAX_COST = 1_000_000_000;
        int[][][] dp = new int[n][26][3];
        for (int[][] A : dp) for (int[] B : A) Arrays.fill(B, MAX_COST);
        for (char c = 'a'; c <= 'z'; ++c) dp[n-1][c-'a'][0] = Math.abs(caption.charAt(n-1) - c);
        int minCost = MAX_COST;
        for (int i = n - 2; i >= 0; --i) {
            int newMinCost = MAX_COST;
            for (char c = 'a'; c <= 'z'; ++c) {
                final int j = c - 'a';
                final int changeCost = Math.abs(caption.charAt(i) - c);
                dp[i][j][0] = changeCost + minCost;
                dp[i][j][1] = changeCost + dp[i+1][j][0];
                dp[i][j][2] = changeCost + Math.min(dp[i+1][j][1], dp[i+1][j][2]);
                newMinCost = Math.min(newMinCost, dp[i][j][2]);
            }
            minCost = newMinCost;
        }
        StringBuilder sb = new StringBuilder();
        int cost = MAX_COST;
        int letter = -1;
        for (int c = 25; c >= 0; --c) if (dp[0][c][2] <= cost) { letter = c; cost = dp[0][c][2]; }
        cost -= appendLetter(caption, 0, (char)('a'+letter), sb);
        cost -= appendLetter(caption, 1, (char)('a'+letter), sb);
        cost -= appendLetter(caption, 2, (char)('a'+letter), sb);
        for (int i = 3; i < n; ) {
            final int nextLetter = getNextLetter(dp, i, cost);
            if (nextLetter < letter || Arrays.stream(dp[i][letter]).min().getAsInt() > cost) {
                letter = nextLetter;
                cost -= appendLetter(caption, i, (char)('a'+letter), sb);
                cost -= appendLetter(caption, i+1, (char)('a'+letter), sb);
                cost -= appendLetter(caption, i+2, (char)('a'+letter), sb);
                i += 3;
            } else {
                cost -= appendLetter(caption, i, (char)('a'+letter), sb);
                i += 1;
            }
        }
        return sb.toString();
    }
    private static int getNextLetter(int[][][] dp, int i, int cost) {
        int nextLetter = 26;
        for (int c = 25; c >= 0; --c) if (cost == dp[i][c][2]) nextLetter = c;
        return nextLetter;
    }
    private static int appendLetter(String caption, int i, char letter, StringBuilder sb) {
        sb.append(letter);
        return Math.abs(caption.charAt(i) - letter);
    }
}

