class Solution {
    public static int maxDiffEvenOdd(String s) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            freq[idx] += 1;
        }
        int maxOdd = -1;
        int minEven = Integer.MAX_VALUE;
        for (int i = 0; i < 26; i++) {
            int f = freq[i];
            if (f == 0) continue;
            if ((f & 1) == 1) {
                if (f > maxOdd) maxOdd = f;
            } else {
                if (f < minEven) minEven = f;
            }
        }
        if (maxOdd == -1 || minEven == Integer.MAX_VALUE) return 0;
        return maxOdd - minEven;
    }
}

