import java.lang.Math;

public class Solution {
    public static int maxManhattanDistanceAfterKChanges(String s, int k) {
        int x = 0, y = 0;
        int inward = 0;
        int answer = 0;
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            boolean outward;
            if (c == 'N') outward = (y >= 0);
            else if (c == 'S') outward = (y <= 0);
            else if (c == 'E') outward = (x >= 0);
            else outward = (x <= 0);
            if (!outward) ++inward;
            if (c == 'N') ++y;
            else if (c == 'S') --y;
            else if (c == 'E') ++x;
            else --x;
            int dist = Math.abs(x) + Math.abs(y);
            int best = dist + 2 * Math.min(k, inward);
            if (best > answer) answer = best;
        }
        return answer;
    }
}

import java.util.Arrays;

public class Solution {
    private static long gcd_ll(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static long minimumIncrements(int[] nums, int[] target) {
        int n = nums.length;
        int m = target.length;
        int fullMask = (1 << m) - 1;
        long INF = 4_000_000_000_000_000_000L;

        long[] lcmMask = new long[1 << m];
        Arrays.fill(lcmMask, 1L);
        for (int mask = 1; mask <= fullMask; ++mask) {
            int bit = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << bit);
            long prevL = (prev == 0) ? 1L : lcmMask[prev];
            long t = target[bit];
            long g = gcd_ll(prevL, t);
            long l = prevL / g * t;
            lcmMask[mask] = l;
        }

        long[] dp = new long[1 << m];
        Arrays.fill(dp, INF);
        dp[0] = 0L;

        for (int i = 0; i < n; ++i) {
            long[] costMask = new long[1 << m];
            for (int mask = 1; mask <= fullMask; ++mask) {
                long L = lcmMask[mask];
                long cur = nums[i];
                long mult = (cur + L - 1) / L;
                long nxt = mult * L;
                costMask[mask] = nxt - cur;
            }

            long[] ndp = dp.clone();
            for (int mask = 0; mask <= fullMask; ++mask) {
                if (dp[mask] == INF) continue;
                for (int sub = 0; sub <= fullMask; ++sub) {
                    int nmask = mask | sub;
                    long cand = dp[mask] + costMask[sub];
                    if (cand < ndp[nmask]) ndp[nmask] = cand;
                }
            }
            dp = ndp;
        }

        return dp[fullMask];
    }
}

import java.util.*;

public class Solution {
    private static class Interval {
        int start;
        int end;
        int dur;
        Interval(int s, int e) {
            this.start = s;
            this.end = e;
            this.dur = e - s;
        }
    }

    public int maxFreeTime(int eventTime, int[] startTime, int[] endTime) {
        int n = startTime.length;
        List<Interval> intervals = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            intervals.add(new Interval(startTime[i], endTime[i]));
        }
        intervals.sort(Comparator.comparingInt(a -> a.start));

        int best = 0;
        int prevEnd = 0;
        for (Interval iv : intervals) {
            best = Math.max(best, iv.start - prevEnd);
            prevEnd = iv.end;
        }
        best = Math.max(best, eventTime - prevEnd);

        for (int i = 0; i < n; i++) {
            Interval moved = intervals.get(i);
            List<Interval> remaining = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (j != i) remaining.add(intervals.get(j));
            }

            List<int[]> gaps = new ArrayList<>();
            int prev = 0;
            for (Interval iv : remaining) {
                if (iv.start > prev) {
                    gaps.add(new int[]{prev, iv.start});
                }
                prev = iv.end;
            }
            if (eventTime > prev) {
                gaps.add(new int[]{prev, eventTime});
            }

            for (int[] g : gaps) {
                int gapLen = g[1] - g[0];
                if (gapLen < moved.dur) continue;

                // left-aligned placement
                int newStart = g[0];
                int newEnd = newStart + moved.dur;
                best = Math.max(best, computeMaxGap(remaining, newStart, newEnd, eventTime));

                // right-aligned placement (if different)
                if (gapLen > moved.dur) {
                    newStart = g[1] - moved.dur;
                    newEnd = g[1];
                    best = Math.max(best, computeMaxGap(remaining, newStart, newEnd, eventTime));
                }
            }
        }

        return best;
    }

    private int computeMaxGap(List<Interval> remaining, int newStart, int newEnd, int eventTime) {
        List<Interval> all = new ArrayList<>(remaining);
        int idx = 0;
        while (idx < all.size() && all.get(idx).start < newStart) {
            idx++;
        }
        all.add(idx, new Interval(newStart, newEnd));

        int prevEnd = 0;
        int maxGap = 0;
        for (Interval iv : all) {
            maxGap = Math.max(maxGap, iv.start - prevEnd);
            prevEnd = iv.end;
        }
        maxGap = Math.max(maxGap, eventTime - prevEnd);
        return maxGap;
    }
}

import java.util.*;

public class Solution {
    public static int[][] sortMatrixByDiagonals(int[][] grid) {
        int n = grid.length;
        for (int k = -(n - 1); k <= n - 1; ++k) {
            List<Integer> values = new ArrayList<>();
            List<int[]> positions = new ArrayList<>();
            for (int i = 0; i < n; ++i) {
                int j = i - k;
                if (j >= 0 && j < n) {
                    values.add(grid[i][j]);
                    positions.add(new int[]{i, j});
                }
            }
            if (k >= 0) {
                Collections.sort(values, Collections.reverseOrder());
            } else {
                Collections.sort(values);
            }
            for (int idx = 0; idx < positions.size(); ++idx) {
                int[] pos = positions.get(idx);
                grid[pos[0]][pos[1]] = values.get(idx);
            }
        }
        return grid;
    }
}

import java.util.Arrays;

public class Solution {
    public static int[] assignElements(int[] groups, int[] elements) {
        final int MAXV = 100000;
        final int INF = 1000000000;
        int[] firstIdx = new int[MAXV + 1];
        Arrays.fill(firstIdx, INF);
        for (int i = 0; i < elements.length; ++i) {
            int v = elements[i];
            if (v <= MAXV && firstIdx[v] == INF) {
                firstIdx[v] = i;
            }
        }
        int[] result = new int[groups.length];
        for (int i = 0; i < groups.length; ++i) {
            int g = groups[i];
            int best = INF;
            for (int d = 1; d * d <= g; ++d) {
                if (g % d == 0) {
                    if (d <= MAXV && firstIdx[d] < best) best = firstIdx[d];
                    int d2 = g / d;
                    if (d2 != d && d2 <= MAXV && firstIdx[d2] < best) best = firstIdx[d2];
                }
            }
            result[i] = (best == INF) ? -1 : best;
        }
        return result;
    }
}

class Solution {
    public int maxDifference(String s, int k) {
        int n = s.length();
        char[] digits = "01234".toCharArray();
        long ans = Long.MIN_VALUE;
        for (char a : digits) {
            for (char b : digits) {
                if (a == b) continue;
                int[] cntA = new int[n+1], cntB = new int[n+1], posOfLastB = new int[n+1];
                int last = 0;
                for (int i = 1; i <= n; i++) {
                    cntA[i] = cntA[i-1] + (s.charAt(i-1)==a ? 1:0);
                    cntB[i] = cntB[i-1] + (s.charAt(i-1)==b ? 1:0);
                    if (s.charAt(i-1)==b) last = i;
                    posOfLastB[i] = last;
                }
                int INF = Integer.MAX_VALUE/2;
                int[][] buckets = {{INF,INF},{INF,INF}};
                int ptr = -1;
                for (int r = k; r <= n; r++) {
                    int bound = Math.min(r-k, posOfLastB[r]-1);
                    while (ptr < bound) {
                        ptr++;
                        int pa = cntA[ptr]&1, pb = cntB[ptr]&1;
                        int val = cntA[ptr]-cntB[ptr];
                        if (val < buckets[pa][pb]) buckets[pa][pb] = val;
                    }
                    int paR = cntA[r]&1, pbR = cntB[r]&1;
                    int mv = buckets[1-paR][pbR];
                    if (mv < INF) {
                        long cand = (long)(cntA[r]-cntB[r]) - mv;
                        if (cand > ans) ans = cand;
                    }
                }
            }
        }
        return (int) ans;
    }
}

