public class Solution {
    public static long maxScore(int[] points, long m) {
        long maxP = 0;
        for (int v : points) {
            if (v > maxP) maxP = v;
        }
        long low = 0, high = maxP * m;
        while (low < high) {
            long mid = (low + high + 1) / 2;
            long need = 0;
            for (int v : points) {
                need += (mid + v - 1) / v;
                if (need > m) break;
            }
            if (need <= m) low = mid;
            else high = mid - 1;
        }
        return low;
    }
}

