class Solution {
    public static long countDivisibleSubstrings(String s) {
        long[][] cnt = new long[10][];
        for (int d = 1; d <= 9; ++d) {
            cnt[d] = new long[d];
        }
        long answer = 0;
        for (char ch : s.toCharArray()) {
            int cur = ch - '0';
            long[][] ndcnt = new long[10][];
            for (int d = 1; d <= 9; ++d) {
                ndcnt[d] = new long[d];
                for (int r = 0; r < d; ++r) {
                    long ways = cnt[d][r];
                    if (ways != 0) {
                        int nr = (r * 10 + cur) % d;
                        ndcnt[d][nr] += ways;
                    }
                }
                int nr = cur % d;
                ndcnt[d][nr] += 1;
            }
            if (cur != 0) {
                answer += ndcnt[cur][0];
            }
            cnt = ndcnt;
        }
        return answer;
    }
}

