class Solution {
    public static int sumGoodNumbers(int[] nums, int k) {
        int n = nums.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            boolean good = true;
            int left = i - k;
            if (left >= 0 && !(nums[i] > nums[left])) {
                good = false;
            }
            int right = i + k;
            if (right < n && !(nums[i] > nums[right])) {
                good = false;
            }
            if (good) {
                total += nums[i];
            }
        }
        return total;
    }
}

