public class Solution {
    public static double separateSquares(List<List<Integer>> squares) {
        double total = 0;
        double low = Double.POSITIVE_INFINITY;
        double high = Double.NEGATIVE_INFINITY;
        for (List<Integer> sq : squares) {
            double y = sq.get(1);
            double l = sq.get(2);
            total += l * l;
            low = Math.min(low, y);
            high = Math.max(high, y + l);
        }
        double half = total / 2.0;
        double lo = low;
        double hi = high;
        for (int i = 0; i < 100; ++i) {
            double mid = (lo + hi) / 2;
            if (areaAbove(mid, squares) > half) {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        double result = (lo + hi) / 2;
        return Math.round(result * 100000.0) / 100000.0;
    }

    private static double areaAbove(double h, List<List<Integer>> squares) {
        double sum = 0;
        for (List<Integer> sq : squares) {
            double y = sq.get(1);
            double l = sq.get(2);
            if (h <= y) {
                sum += l * l;
            } else if (h < y + l) {
                sum += (y + l - h) * l;
            }
        }
        return sum;
    }
}

public class Solution {
    public static boolean findSpecialSubstring(String s, int k) {
        if (k <= 0) return false;
        int consecutive = 1;
        for (int i = 1; i < s.length(); ++i) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                ++consecutive;
            } else {
                consecutive = 1;
            }
            if (consecutive >= k) return true;
        }
        return false;
    }
}

