class Solution {
    public static int shortestMatchingSubstring(String s, String p) {
        int first = p.indexOf('*');
        int second = p.indexOf('*', first + 1);
        String A = p.substring(0, first);
        String B = p.substring(first + 1, second);
        String C = p.substring(second + 1);
        int n = s.length();

        List<Integer> startsA = findMatches(s, A);
        List<Integer> startsB = findMatches(s, B);
        List<Integer> startsC = findMatches(s, C);

        int[] nextB = new int[n + 1];
        int[] nextC = new int[n + 1];
        Arrays.fill(nextB, -1);
        Arrays.fill(nextC, -1);

        int idxB = 0;
        for (int pos = 0; pos <= n; ++pos) {
            while (idxB < startsB.size() && startsB.get(idxB) < pos) {
                ++idxB;
            }
            if (idxB < startsB.size()) {
                nextB[pos] = startsB.get(idxB);
            }
        }

        int idxC = 0;
        for (int pos = 0; pos <= n; ++pos) {
            while (idxC < startsC.size() && startsC.get(idxC) < pos) {
                ++idxC;
            }
            if (idxC < startsC.size()) {
                nextC[pos] = startsC.get(idxC);
            }
        }

        int best = Integer.MAX_VALUE;
        int lenA = A.length();
        int lenB = B.length();
        int lenC = C.length();

        for (int i : startsA) {
            int posB = i + lenA;
            int j = nextB[posB];
            if (j == -1) continue;
            int posC = j + lenB;
            int k = nextC[posC];
            if (k == -1) continue;
            int len = (k + lenC) - i;
            if (len < best) best = len;
        }

        return best == Integer.MAX_VALUE ? -1 : best;
    }

    private static List<Integer> findMatches(String s, String sub) {
        ArrayList<Integer> res = new ArrayList<>();
        int n = s.length();
        if (sub.isEmpty()) {
            res.ensureCapacity(n + 1);
            for (int i = 0; i <= n; ++i) {
                res.add(i);
            }
            return res;
        }
        int m = sub.length();
        for (int i = 0; i + m <= n; ++i) {
            if (s.regionMatches(i, sub, 0, m)) {
                res.add(i);
            }
        }
        return res;
    }
}

