class Solution {
    private static int lowerBound(double[] arr, double target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < target) l = m + 1;
            else r = m;
        }
        return l;
    }

    private static class Event {
        double x;
        int type;
        double y1;
        double y2;
        Event(double x, int type, double y1, double y2) {
            this.x = x;
            this.type = type;
            this.y1 = y1;
            this.y2 = y2;
        }
    }

    private static class SegTree {
        int[] cnt;
        double[] len;
        double[] uniqY;
        int m;
        SegTree(int m, double[] uniqY) {
            this.m = m;
            this.uniqY = uniqY;
            int size = (m + 2) * 4;
            cnt = new int[size];
            len = new double[size];
        }
        void update(int node, int l, int r, int ql, int qr, int delta) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                cnt[node] += delta;
            } else {
                int mid = (l + r) >> 1;
                update(node * 2, l, mid, ql, qr, delta);
                update(node * 2 + 1, mid + 1, r, ql, qr, delta);
            }
            if (cnt[node] > 0) {
                len[node] = uniqY[r + 1] - uniqY[l];
            } else if (l == r) {
                len[node] = 0.0;
            } else {
                len[node] = len[node * 2] + len[node * 2 + 1];
            }
        }
    }

    private static double unionArea(List<double[]> rects) {
        if (rects.isEmpty()) return 0.0;
        List<Event> events = new ArrayList<>(rects.size() * 2);
        List<Double> yVals = new ArrayList<>(rects.size() * 2);
        for (double[] r : rects) {
            double x1 = r[0], x2 = r[1], y1 = r[2], y2 = r[3];
            events.add(new Event(x1, 1, y1, y2));
            events.add(new Event(x2, -1, y1, y2));
            yVals.add(y1);
            yVals.add(y2);
        }
        events.sort(Comparator.comparingDouble(e -> e.x));
        Collections.sort(yVals);
        double[] uniqY = new double[yVals.size()];
        int uniqCount = 0;
        for (int i = 0; i < yVals.size(); ++i) {
            double v = yVals.get(i);
            if (i == 0 || v != yVals.get(i - 1)) {
                uniqY[uniqCount++] = v;
            }
        }
        uniqY = Arrays.copyOf(uniqY, uniqCount);
        int m = uniqY.length > 0 ? uniqY.length - 1 : 0;
        if (m == 0) return 0.0;
        SegTree st = new SegTree(m, uniqY);
        double area = 0.0;
        double prevX = events.get(0).x;
        for (Event e : events) {
            double dx = e.x - prevX;
            if (dx != 0.0) area += st.len[1] * dx;
            int y1Idx = lowerBound(uniqY, e.y1);
            int y2Idx = lowerBound(uniqY, e.y2);
            if (y2Idx > 0) --y2Idx;
            if (y1Idx <= y2Idx) st.update(1, 0, m - 1, y1Idx, y2Idx, e.type);
            prevX = e.x;
        }
        return area;
    }

    public static double separateSquaresII(double[][] squares) {
        List<double[]> fullRects = new ArrayList<>(squares.length);
        for (double[] s : squares) {
            double x = s[0], y = s[1], l = s[2];
            fullRects.add(new double[]{x, x + l, y, y + l});
        }
        double totalArea = unionArea(fullRects);
        double halfArea = totalArea / 2.0;

        double low = Double.POSITIVE_INFINITY;
        double high = Double.NEGATIVE_INFINITY;
        for (double[] s : squares) {
            double y = s[1], l = s[2];
            if (y < low) low = y;
            if (y + l > high) high = y + l;
        }

        for (int iter = 0; iter < 60; ++iter) {
            double mid = (low + high) * 0.5;
            List<double[]> rects = new ArrayList<>(squares.length);
            for (double[] s : squares) {
                double x = s[0], y = s[1], l = s[2];
                double y2 = Math.min(y + l, mid);
                if (y2 > y) rects.add(new double[]{x, x + l, y, y2});
            }
            double areaBelow = unionArea(rects);
            if (areaBelow >= halfArea) high = mid;
            else low = mid;
        }
        return high;
    }
}

