public class Solution {
    public static long maxSumWithAtMostK(List<List<Integer>> grid, List<Integer> limits, int k) {
        List<Integer> candidates = new ArrayList<>();
        for (int i = 0; i < grid.size(); i++) {
            List<Integer> row = grid.get(i);
            List<Integer> sorted = new ArrayList<>(row);
            sorted.sort(Collections.reverseOrder());
            int limit_i = 0;
            if (i < limits.size()) {
                limit_i = limits.get(i);
            }
            int take = Math.min(limit_i, sorted.size());
            for (int j = 0; j < take; j++) {
                candidates.add(sorted.get(j));
            }
        }
        candidates.sort(Collections.reverseOrder());
        int limit = Math.min(k, candidates.size());
        long sum = 0;
        for (int i = 0; i < limit; i++) {
            sum += candidates.get(i);
        }
        return sum;
    }
}

