class Solution {
    public static boolean areDigitsEqual(String s) {
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }
        while (digits.length > 2) {
            int[] next = new int[digits.length - 1];
            for (int i = 0; i < next.length; i++) {
                next[i] = (digits[i] + digits[i + 1]) % 10;
            }
            digits = next;
        }
        return digits[0] == digits[1];
    }
}

import java.util.*;

public class Solution {
    public static class Pair {
        public long first;
        public long second;
        public Pair(long first, long second) {
            this.first = first;
            this.second = second;
        }
    }

    private static int lowerBound(long[] arr, long target, int start) {
        int l = start, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < target) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }

    private static boolean feasible(long d, long[] dup, int N, long P, int k) {
        for (int i = 0; i < N; ++i) {
            int cnt = 1;
            long lastPos = dup[i];
            int idx = i;
            while (cnt < k) {
                long target = lastPos + d;
                int j = lowerBound(dup, target, idx + 1);
                if (j >= i + N) break;
                ++cnt;
                lastPos = dup[j];
                idx = j;
            }
            if (cnt == k) {
                long span = lastPos - dup[i];
                if (span <= P - d) return true;
            }
        }
        return false;
    }

    public static long maxMinManhattanDistance(long side, List<Pair> points, int k) {
        long P = 4 * side;
        int m = points.size();
        long[] s = new long[m];
        for (int i = 0; i < m; ++i) {
            long x = points.get(i).first;
            long y = points.get(i).second;
            long pos;
            if (y == 0) {
                pos = x;
            } else if (x == side) {
                pos = side + y;
            } else if (y == side) {
                pos = 3 * side - x;
            } else {
                pos = 4 * side - y;
            }
            s[i] = pos;
        }
        Arrays.sort(s);
        int N = s.length;
        long[] dup = new long[2 * N];
        System.arraycopy(s, 0, dup, 0, N);
        for (int i = 0; i < N; ++i) {
            dup[N + i] = s[i] + P;
        }

        long low = 0, high = P / 2;
        while (low < high) {
            long mid = (low + high + 1) / 2;
            if (feasible(mid, dup, N, P, k)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
}

