class Solution {
    public static String smallestGeneratedString(String str1, String str2) {
        int n = str1.length();
        int m = str2.length();
        int L = n + m - 1;
        char[] word = new char[L];
        for (int i = 0; i < n; ++i) {
            if (str1.charAt(i) == 'T') {
                for (int j = 0; j < m; ++j) {
                    int pos = i + j;
                    char c = str2.charAt(j);
                    if (word[pos] == '\0') {
                        word[pos] = c;
                    } else if (word[pos] != c) {
                        return "";
                    }
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            if (str1.charAt(i) == 'F') {
                boolean alreadyDiff = false;
                for (int j = 0; j < m; ++j) {
                    int pos = i + j;
                    char c = str2.charAt(j);
                    if (word[pos] != '\0' && word[pos] != c) {
                        alreadyDiff = true;
                        break;
                    }
                }
                if (alreadyDiff) continue;
                boolean changed = false;
                for (int j = m - 1; j >= 0; --j) {
                    int pos = i + j;
                    if (word[pos] == '\0') {
                        char c = str2.charAt(j);
                        word[pos] = (c == 'a' ? 'b' : 'a');
                        changed = true;
                        break;
                    }
                }
                if (!changed) return "";
            }
        }
        for (int i = 0; i < L; ++i) {
            if (word[i] == '\0') word[i] = 'a';
        }
        return new String(word);
    }
}

