class Solution {
    public static int minimumRemovalCost(int[] nums) {
        int n = nums.length;
        int[][] maxPos = new int[n][n];
        for (int i = 0; i < n; i++) {
            maxPos[i][i] = i;
            for (int j = i + 1; j < n; j++) {
                int prev = maxPos[i][j - 1];
                maxPos[i][j] = nums[j] > nums[prev] ? j : prev;
            }
        }

        int[][] dp = new int[n][n];
        for (int len = 1; len <= n; len++) {
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                if (l == r) {
                    dp[l][r] = nums[l];
                } else {
                    int m = maxPos[l][r];
                    int left = m > l ? dp[l][m - 1] : 0;
                    int right = m < r ? dp[m + 1][r] : 0;
                    dp[l][r] = nums[m] + Math.min(left, right);
                }
            }
        }
        return dp[0][n - 1];
    }
}

