public class Solution {
    static final long INF = 1000000000000000000L;
    static long mulCap(long a, long b) {
        if (a == 0 || b == 0) return 0;
        if (a > INF / b) return INF;
        long res = a * b;
        return res > INF ? INF : res;
    }
    public static List<Integer> getPermutation(int n, long k) {
        int totalOdd = (n + 1) / 2;
        int totalEven = n / 2;
        long[][][] dp = new long[totalOdd + 1][totalEven + 1][2];
        dp[0][0][0] = 1;
        dp[0][0][1] = 1;
        for (int o = 0; o <= totalOdd; ++o) {
            for (int e = 0; e <= totalEven; ++e) {
                if (o == 0 && e == 0) continue;
                long val0 = 0, val1 = 0;
                if (o > 0) val0 = mulCap((long) o, dp[o - 1][e][1]);
                if (e > 0) val1 = mulCap((long) e, dp[o][e - 1][0]);
                dp[o][e][0] = val0;
                dp[o][e][1] = val1;
            }
        }
        List<Integer> ans = new ArrayList<>();
        boolean[] used = new boolean[n + 1];
        int oddLeft = totalOdd, evenLeft = totalEven;
        int lastParity = -1;
        long K = k;
        for (int pos = 0; pos < n; ++pos) {
            boolean found = false;
            for (int x = 1; x <= n; ++x) {
                if (used[x]) continue;
                int parity = x % 2;
                if (pos > 0 && parity == lastParity) continue;
                int o = oddLeft - (parity == 1 ? 1 : 0);
                int e = evenLeft - (parity == 0 ? 1 : 0);
                long cnt = dp[o][e][parity];
                if (cnt >= K) {
                    ans.add(x);
                    used[x] = true;
                    oddLeft = o;
                    evenLeft = e;
                    lastParity = parity;
                    found = true;
                    break;
                } else {
                    K -= cnt;
                }
            }
            if (!found) {
                return new ArrayList<>();
            }
        }
        return ans;
    }
}

import java.lang.Math;

public class Solution {
    public static int longestPalindromeSubseqAfterOperations(String s, int k) {
        int n = s.length();
        int K = k;
        if (n == 0) return 0;
        int[][][] dp = new int[n][n][K + 1];
        for (int i = 0; i < n; ++i) {
            for (int c = 0; c <= K; ++c) {
                dp[i][i][c] = 1;
            }
        }
        for (int len = 2; len <= n; ++len) {
            for (int l = 0; l + len - 1 < n; ++l) {
                int r = l + len - 1;
                int diff = Math.abs(s.charAt(l) - s.charAt(r));
                int d = Math.min(diff, 26 - diff);
                for (int c = 0; c <= K; ++c) {
                    int best = Math.max(dp[l + 1][r][c], dp[l][r - 1][c]);
                    if (c >= d) {
                        int inner = (l + 1 <= r - 1) ? dp[l + 1][r - 1][c - d] : 0;
                        best = Math.max(best, inner + 2);
                    }
                    dp[l][r][c] = best;
                }
            }
        }
        int ans = 0;
        for (int c = 0; c <= K; ++c) {
            ans = Math.max(ans, dp[0][n - 1][c]);
        }
        return ans;
    }
}

