class Solution {
    public static long maxSumKSubarrays(int[] nums, int k, int m) {
        int n = nums.length;
        long NEG_INF = Long.MIN_VALUE / 4;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + (long) nums[i];
        }

        long[] dpPrev = new long[n + 1];
        Arrays.fill(dpPrev, NEG_INF);
        dpPrev[0] = 0;

        for (int sub = 1; sub <= k; ++sub) {
            long[] dpCurr = new long[n + 1];
            Arrays.fill(dpCurr, NEG_INF);
            long best = NEG_INF;
            for (int i = m; i <= n; ++i) {
                best = Math.max(best, dpPrev[i - m] - pref[i - m]);
                dpCurr[i] = Math.max(dpCurr[i - 1], best + pref[i]);
            }
            dpPrev = dpCurr;
        }
        return dpPrev[n];
    }
}

