class Solution {
    public static int largestAlmostMissingInteger(int[] nums, int k) {
        HashMap<Integer, Integer> windowCount = new HashMap<>();
        int n = nums.length;
        for (int start = 0; start <= n - k; ++start) {
            HashSet<Integer> seen = new HashSet<>();
            for (int i = start; i < start + k; ++i) {
                seen.add(nums[i]);
