class Solution {
    public static int countUnplacedFruits(int[] fruits, int[] baskets) {
        int m = baskets.length;
        int[] sorted = baskets.clone();
        Arrays.sort(sorted);
        int[] parent = new int[m + 1];
        for (int i = 0; i <= m; i++) parent[i] = i;
        int unplaced = 0;
        for (int need : fruits) {
            int idx = upperBound(sorted, need);
            int avail = find(parent, idx);
            if (avail == m) {
                unplaced++;
            } else {
                parent[avail] = find(parent, avail + 1);
            }
        }
        return unplaced;
    }

    private static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

