public class Solution {
    public static long[] chooseKElementsWithMaximumSum(int[] nums1, int[] nums2, int k) {
        int n = nums1.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) {
            idx[i] = i;
        }
        Arrays.sort(idx, (a, b) -> Integer.compare(nums1[a], nums1[b]));
        long[] answer = new long[n];
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        long curSum = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums1[idx[j]] == nums1[idx[i]]) {
                j++;
            }
            for (int p = i; p < j; p++) {
                answer[idx[p]] = curSum;
            }
            for (int p = i; p < j; p++) {
                int val = nums2[idx[p]];
                if (minHeap.size() < k) {
                    minHeap.add(val);
                    curSum += val;
                } else if (k > 0 && val > minHeap.peek()) {
                    curSum -= minHeap.poll();
                    minHeap.add(val);
                    curSum += val;
                }
            }
            i = j;
        }
        return answer;
    }
}

