class Solution {
    private static long countValid(int n, List<int[]> pairs) {
        List<List<Integer>> ending = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            ending.add(new ArrayList<>());
        }
        for (int[] pr : pairs) {
            int a = pr[0];
            int b = pr[1];
            if (a > b) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            ending.get(b).add(a);
        }
        int left = 1;
        long total = 0;
        for (int r = 1; r <= n; r++) {
            for (int a : ending.get(r)) {
                if (a + 1 > left) {
                    left = a + 1;
                }
            }
            if (left <= r) {
                total += r - left + 1;
            }
        }
        return total;
    }

    public static long maxSubarrays(int n, List<int[]> conflictingPairs) {
        long best = 0;
        int m = conflictingPairs.size();
        for (int removeIdx = 0; removeIdx < m; removeIdx++) {
            List<int[]> remaining = new ArrayList<>(m - 1);
            for (int i = 0; i < m; i++) {
                if (i != removeIdx) {
                    remaining.add(conflictingPairs.get(i));
                }
            }
            long cur = countValid(n, remaining);
            if (cur > best) {
                best = cur;
            }
        }
        return best;
    }
}

class Solution {
    private int maxLength = 0, minNodes = 1;
    private List<int[]>[] graph;
    private int[] nums;
    private List<Integer> prefix = new ArrayList<>();
    private Map<Integer,Integer> lastSeenDepth = new HashMap<>();

    public int[] longestSpecialPath(int[][] edges, int[] n0) {
        nums = n0;
        int n = nums.length;
        graph = new List[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
            graph[e[1]].add(new int[]{e[0], e[2]});
        }
        prefix.add(0);
        dfs(0, -1, new int[]{0, 0});
        return new int[]{maxLength, minNodes};
    }
    private void dfs(int u, int prev, int[] leftBoundary) {
        int prevDepth = lastSeenDepth.getOrDefault(nums[u], 0);
        lastSeenDepth.put(nums[u], prefix.size());
        int[] lb = leftBoundary;
        if (prevDepth != 0) {
            int[] combined = {leftBoundary[0], leftBoundary[1], prevDepth};
            Arrays.sort(combined);
            lb = new int[]{combined[1], combined[2]};
        }
        int length = prefix.get(prefix.size() - 1) - prefix.get(lb[0]);
        int nodes = prefix.size() - lb[0];
        if (length > maxLength || (length == maxLength && nodes < minNodes)) {
            maxLength = length;
            minNodes = nodes;
        }
        for (int[] edge : graph[u]) {
            int v = edge[0], w = edge[1];
            if (v == prev) continue;
            prefix.add(prefix.get(prefix.size() - 1) + w);
            dfs(v, u, lb);
            prefix.remove(prefix.size() - 1);
        }
        lastSeenDepth.put(nums[u], prevDepth);
    }
}

