class Solution {
    public static int[] distanceToClosest(int[] nums, int[] queries) {
        int n = nums.length;
        HashMap<Integer, ArrayList<Integer>> positions = new HashMap<>(n * 2);
        for (int i = 0; i < n; ++i) {
            positions.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }
        ArrayList<Integer> answer = new ArrayList<>(queries.length);
        for (int idx : queries) {
            int val = nums[idx];
            List<Integer> vec = positions.get(val);
            if (vec.size() == 1) {
                answer.add(-1);
                continue;
            }
            int posIdx = Collections.binarySearch(vec, idx);
            if (posIdx < 0) {
                posIdx = -posIdx - 1;
            }
            int sz = vec.size();
            int nextIdx = vec.get((posIdx + 1) % sz);
            int prevIdx = vec.get((posIdx + sz - 1) % sz);
            int forward = (nextIdx - idx + n) % n;
            int backward = (idx - prevIdx + n) % n;
            answer.add(Math.min(forward, backward));
        }
        int[] result = new int[answer.size()];
        for (int i = 0; i < answer.size(); ++i) {
            result[i] = answer.get(i);
        }
        return result;
    }
}

