            for (int v : cur) {
                if (v != 0) return false;
            }
            return true;
        };
        if (allZero.getAsBoolean()) return 0;
        for (int i = 0; i < queries.length; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            int val = queries[i][2];
            for (int j = l; j <= r; j++) {
