class Solution {
    private static class TrieNode {
        int[] next;
        int cnt;
        int depth;
        TrieNode() {
            next = new int[26];
            Arrays.fill(next, -1);
            cnt = 0;
            depth = 0;
        }
    }

    public static int[] longestCommonPrefix(List<String> words, int k) {
        int n = words.size();
        if (n - 1 < k) {
            return new int[n];
        }

        List<TrieNode> nodes = new ArrayList<>();
        nodes.add(new TrieNode()); // root at index 0
        int maxWordLen = 0;

        for (String w : words) {
            int cur = 0;
            int d = 0;
            for (int i = 0; i < w.length(); i++) {
                int idx = w.charAt(i) - 'a';
                if (nodes.get(cur).next[idx] == -1) {
                    TrieNode newNode = new TrieNode();
                    newNode.depth = d + 1;
                    nodes.add(newNode);
                    nodes.get(cur).next[idx] = nodes.size() - 1;
                }
                cur = nodes.get(cur).next[idx];
                d++;
                nodes.get(cur).cnt++;
            }
            if (w.length() > maxWordLen) maxWordLen = w.length();
        }

        int[] goodCount = new int[maxWordLen + 1];
        int globalMaxDepth = 0;
        for (int i = 1; i < nodes.size(); i++) {
            TrieNode node = nodes.get(i);
            if (node.cnt >= k) {
                goodCount[node.depth]++;
                if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
            }
        }

        int[] answer = new int[n];

        for (int i = 0; i < n; i++) {
            String w = words.get(i);
            int cur = 0;
            for (int j = 0; j < w.length(); j++) {
                int idx = w.charAt(j) - 'a';
                cur = nodes.get(cur).next[idx];
                TrieNode node = nodes.get(cur);
                if (node.cnt == k) {
                    goodCount[node.depth]--;
                    if (node.depth == globalMaxDepth && goodCount[node.depth] == 0) {
                        while (globalMaxDepth > 0 && goodCount[globalMaxDepth] == 0) {
                            globalMaxDepth--;
                        }
                    }
                }
                node.cnt--;
            }

            answer[i] = globalMaxDepth;

            cur = 0;
            for (int j = 0; j < w.length(); j++) {
                int idx = w.charAt(j) - 'a';
                cur = nodes.get(cur).next[idx];
                TrieNode node = nodes.get(cur);
                node.cnt++;
                if (node.cnt == k) {
                    goodCount[node.depth]++;
                    if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
                }
            }
        }

        return answer;
    }
}

