class Solution {
    private static final long[][][][] memo = new long[11][91][91][2];
    private static final boolean[][][][] seen = new boolean[11][91][91][2];
    private static int[] dig;
    private static int L;
    private static int targetSum;

    private static long dfs(int pos, int sum, int prodMod, int started, boolean tight) {
        if (pos == L) {
            return (started == 1 && sum == targetSum && prodMod == 0) ? 1L : 0L;
        }
        if (!tight && seen[pos][sum][prodMod][started]) {
            return memo[pos][sum][prodMod][started];
        }
        int limit = tight ? dig[pos] : 9;
        long res = 0L;
        for (int d = 0; d <= limit; ++d) {
            int nStarted = (started == 1 || d != 0) ? 1 : 0;
            int nSum = sum + (nStarted == 1 ? d : 0);
            if (nSum > targetSum) continue;
            int nProdMod;
            if (nStarted == 0) {
                nProdMod = prodMod;
            } else {
                if (started == 0) {
                    nProdMod = d % targetSum;
                } else {
                    nProdMod = (int) ((1L * prodMod * (d % targetSum)) % targetSum);
                }
            }
            res += dfs(pos + 1, nSum, nProdMod, nStarted, tight && d == limit);
        }
        if (!tight) {
            seen[pos][sum][prodMod][started] = true;
            memo[pos][sum][prodMod][started] = res;
        }
        return res;
    }

    private static long countUpTo(long X) {
        if (X <= 0) return 0L;
        String s = Long.toString(X);
        L = s.length();
        dig = new int[L];
        for (int i = 0; i < L; ++i) dig[i] = s.charAt(i) - '0';
        long total = 0L;
        for (int S = 1; S <= 90; ++S) {
            targetSum = S;
            for (int i = 0; i <= L; ++i) {
                for (int a = 0; a <= S; ++a) {
                    for (int b = 0; b < S; ++b) {
                        seen[i][a][b][0] = false;
                        seen[i][a][b][1] = false;
                    }
                }
            }
            int initProdMod = 1 % S;
            total += dfs(0, 0, initProdMod, 0, true);
        }
        return total;
    }

    public static long countBeautiful(long l, long r) {
        return countUpTo(r) - countUpTo(l - 1);
    }
}

class Solution {
    public static long minBrewTime(int[] skill, int[] mana) {
        int n = skill.length, m = mana.length;
        long[] done = new long[n];
        for (int j = 0; j < m; j++) {
            long[] idealStart = new long[n];
            for (int i = 1; i < n; i++) idealStart[i] = idealStart[i-1] + (long) skill[i-1]*mana[j];
            long shift = 0;
            for (int i = 0; i < n; i++) shift = Math.max(shift, done[i] - idealStart[i]);
            long[] finish = new long[n];
            for (int i = 0; i < n; i++) {
                long start = idealStart[i] + shift;
                finish[i] = start + (long) skill[i]*mana[j];
            }
            done = finish;
        }
        return done[n-1];
    }
}

