class Solution {
    private static class DSU {
        private int[] parent;
        private int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; ++i) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void unite(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) ++rank[ra];
        }
    }

    public static int numberOfComponents(List<List<Integer>> properties, int k) {
        int n = properties.size();
        if (n == 0) return 0;
        List<HashSet<Integer>> sets = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            HashSet<Integer> set = new HashSet<>();
            for (int v : properties.get(i)) {
                set.add(v);
            }
            sets.add(set);
        }
        DSU dsu = new DSU(n);
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                HashSet<Integer> a = sets.get(i);
                HashSet<Integer> b = sets.get(j);
                HashSet<Integer> small = a;
                HashSet<Integer> large = b;
                if (a.size() > b.size()) {
                    small = b;
                    large = a;
                }
                int common = 0;
                for (int val : small) {
                    if (large.contains(val)) {
                        ++common;
                        if (common >= k) break;
                    }
                }
                if (common >= k) dsu.unite(i, j);
            }
        }
        HashSet<Integer> roots = new HashSet<>();
        for (int i = 0; i < n; ++i) {
            roots.add(dsu.find(i));
        }
        return roots.size();
    }
}

