class Solution {
    int[] runChar, runStart, runEnd, fullLen;
    int[][] spInnerBC, spMinOne, spMaxZero;
    int R;
    final int NEG_INF = Integer.MIN_VALUE/2, POS_INF = Integer.MAX_VALUE/2;

    int[][] buildSparse(int[] arr, boolean isMax) {
        int m = arr.length;
        if (m == 0) return new int[0][0];
        int LOG = 32 - Integer.numberOfLeadingZeros(m);
        int[][] sp = new int[LOG][m];
        sp[0] = arr.clone();
        for (int j = 1; j < LOG; j++) {
            int half = 1 << (j-1);
            for (int i = 0; i + (1<<j) <= m; i++) {
                sp[j][i] = isMax ? Math.max(sp[j-1][i], sp[j-1][i+half]) : Math.min(sp[j-1][i], sp[j-1][i+half]);
            }
        }
        return sp;
    }
    int querySparse(int[][] sp, int l, int r, boolean isMax) {
        if (sp.length == 0 || l > r) return isMax ? NEG_INF : POS_INF;
        int len = r - l + 1;
        int k = 31 - Integer.numberOfLeadingZeros(len);
        int a = sp[k][l], b = sp[k][r - (1<<k) + 1];
        return isMax ? Math.max(a,b) : Math.min(a,b);
    }

    int findRun(int pos) {
        int lo = 0, hi = R-1;
        while (lo < hi) {
            int mid = (lo+hi+1)/2;
            if (runStart[mid] <= pos) lo = mid; else hi = mid-1;
        }
        return lo;
    }

    public int[] maxActiveSectionsAfterTrade(String s, int[][] queries) {
        int n = s.length();
        List<int[]> runsList = new ArrayList<>();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            runsList.add(new int[]{s.charAt(i)-'0', i, j-1});
            i = j;
        }
        R = runsList.size();
        runChar = new int[R]; runStart = new int[R]; runEnd = new int[R]; fullLen = new int[R];
        for (int k = 0; k < R; k++) {
            runChar[k] = runsList.get(k)[0];
            runStart[k] = runsList.get(k)[1];
            runEnd[k] = runsList.get(k)[2];
            fullLen[k] = runEnd[k]-runStart[k]+1;
        }
        int globalTotalOnes = 0;
        for (int k = 0; k < R; k++) if (runChar[k]==1) globalTotalOnes += fullLen[k];

        int[] innerBC = new int[R];
        int[] oneLenOrInf = new int[R];
        int[] zeroLenOrNegInf = new int[R];
        for (int k = 0; k < R; k++) {
            if (runChar[k]==1 && k-1>=0 && k+1<R) innerBC[k] = fullLen[k-1]+fullLen[k+1];
            else innerBC[k] = NEG_INF;
            oneLenOrInf[k] = runChar[k]==1 ? fullLen[k] : POS_INF;
            zeroLenOrNegInf[k] = runChar[k]==0 ? fullLen[k] : NEG_INF;
        }
        spInnerBC = buildSparse(innerBC, true);
        spMinOne = buildSparse(oneLenOrInf, false);
        spMaxZero = buildSparse(zeroLenOrNegInf, true);

        int q = queries.length;
        int[] ans = new int[q];
        for (int qi = 0; qi < q; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            int idxL = findRun(l), idxR = findRun(r);
            if (idxL == idxR) { ans[qi] = globalTotalOnes; continue; }
            int truncFirst = Math.min(runEnd[idxL], r) - l + 1;
            int truncLast = r - Math.max(runStart[idxR], l) + 1;

            int bestExtra = 0;
            int loI = idxL+1, hiI = idxR-1;
            if (loI <= hiI) {
                int minBlock = querySparse(spMinOne, loI, hiI, false);
                int maxZero = querySparse(spMaxZero, loI, hiI, true);
                if (runChar[idxL]==0) maxZero = Math.max(maxZero, truncFirst);
                if (runChar[idxR]==0) maxZero = Math.max(maxZero, truncLast);
                if (minBlock < POS_INF && maxZero > NEG_INF) {
                    bestExtra = Math.max(bestExtra, maxZero - minBlock);
                }
                if (loI+1 <= hiI-1) {
                    bestExtra = Math.max(bestExtra, querySparse(spInnerBC, loI+1, hiI-1, true));
                }
                Set<Integer> boundaryIdx = new LinkedHashSet<>(Arrays.asList(loI, hiI));
                for (int idx : boundaryIdx) {
                    if (runChar[idx] != 1) continue;
                    int B = (idx-1 == idxL) ? truncFirst : (idx-1>=0 ? fullLen[idx-1] : 0);
                    int C = (idx+1 == idxR) ? truncLast : (idx+1<R ? fullLen[idx+1] : 0);
                    bestExtra = Math.max(bestExtra, B+C);
                }
            }
            ans[qi] = globalTotalOnes + bestExtra;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int longestPalindromeAfterConcat(String s, String t) {
        int n = s.length();
        int m = t.length();
        int maxLen = 0;
        for (int i = 0; i <= n; i++) {
            for (int j = i; j <= n; j++) {
                String subS = s.substring(i, j);
                for (int p = 0; p <= m; p++) {
                    for (int q = p; q <= m; q++) {
                        String subT = t.substring(p, q);
                        String combined = subS + subT;
                        if (combined.length() > maxLen && isPal(combined)) {
                            maxLen = combined.length();
                        }
                    }
                }
            }
        }
        return maxLen;
    }

    private static boolean isPal(String str) {
        int i = 0;
        int j = str.length() - 1;
        while (i < j) {
            if (str.charAt(i) != str.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
}

public class Solution {
