            int c = cost[i];
            if (c < best) best = c;
            answer[i] = best;
        }
        return answer;
    }
}

import java.util.*;
class Solution {
    public static long minOperations(int[] nums, int x, int k) {
        int n = nums.length;
        long[] costs = new long[n];
        for (int l = 0; l <= n - x; l++) {
            int[] window = Arrays.copyOfRange(nums, l, l+x);
            Arrays.sort(window);
            int median = window[window.length/2];
            long cost = 0;
            for (int v : window) cost += Math.abs(v - median);
            costs[l] = cost;
        }
        final long INF = Long.MAX_VALUE/2;
        long[][] dp = new long[n+1][k+1];
        for (long[] row : dp) Arrays.fill(row, INF);
        for (int i = 0; i <= n; i++) dp[i][0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = dp[i-1][j];
                if (j > 0 && i-x >= 0 && dp[i-x][j-1] < INF) {
                    long cand = dp[i-x][j-1] + costs[i-x];
                    if (cand < dp[i][j]) dp[i][j] = cand;
                }
            }
        }
        return dp[n][k];
    }
}

class Solution {
    public int maxActiveSectionsAfterTrade(String s) {
        int n = s.length();
        int ans = 0, i = 0;
        int pre = Integer.MIN_VALUE, mx = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            int cur = j - i;
            if (s.charAt(i) == '1') ans += cur;
            else { mx = Math.max(mx, pre + cur); pre = cur; }
            i = j;
        }
        ans += mx;
        return ans;
    }
}

class Solution {
    public long minimumCost(int[] nums, int[] cost, int k) {
        int n = nums.length;
        long[] prefixNums = new long[n + 1];
        long[] prefixCost = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixNums[i + 1] = prefixNums[i] + nums[i];
            prefixCost[i + 1] = prefixCost[i] + cost[i];
        }
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                long val = prefixNums[j + 1] * (prefixCost[j + 1] - prefixCost[i]) +
                           (long) k * (prefixCost[n] - prefixCost[i]) + dp[j + 1];
                dp[i] = Math.min(dp[i], val);
            }
        }
        return dp[0];
    }
}

import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static long maxProductAlternatingSum(int[] nums, long k, long limit) {
        Map<Long, Long> dpEven = new HashMap<>();
        Map<Long, Long> dpOdd = new HashMap<>();
        for (int x : nums) {
            Map<Long, Long> nextEven = new HashMap<>(dpEven);
            Map<Long, Long> nextOdd = new HashMap<>(dpOdd);
            long val = (long) x;
            if (val <= limit) {
                Long existing = nextOdd.get(val);
                if (existing == null || val > existing) {
                    nextOdd.put(val, val);
                }
            }
            for (Map.Entry<Long, Long> p : dpEven.entrySet()) {
                long curProd = p.getValue();
                if (val != 0 && curProd > limit / val) continue;
                long newProd = curProd * val;
                long newSum = p.getKey() + val;
                Long existing = nextOdd.get(newSum);
                if (existing == null || newProd > existing) {
                    nextOdd.put(newSum, newProd);
                }
            }
            for (Map.Entry<Long, Long> p : dpOdd.entrySet()) {
                long curProd = p.getValue();
                if (val != 0 && curProd > limit / val) continue;
                long newProd = curProd * val;
                long newSum = p.getKey() - val;
                Long existing = nextEven.get(newSum);
                if (existing == null || newProd > existing) {
                    nextEven.put(newSum, newProd);
                }
            }
            dpEven = nextEven;
            dpOdd = nextOdd;
        }
        long ans = -1;
        Long valEven = dpEven.get(k);
        if (valEven != null) ans = Math.max(ans, valEven);
        Long valOdd = dpOdd.get(k);
        if (valOdd != null) ans = Math.max(ans, valOdd);
        return ans;
    }
}

import java.util.ArrayList;

class Solution {
    public static int minOperations(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        ArrayList<Integer> tails = new ArrayList<>();
        for (int x : nums) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails.get(mid) <= x) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            if (lo == tails.size()) {
                tails.add(x);
            } else {
                tails.set(lo, x);
            }
        }
        return nums.length - tails.size();
    }
}

