class Solution {
    private static int longestPalindromicSubstring(String str) {
        int n = str.length();
        int best = 0;
        for (int center = 0; center < n; ++center) {
            int l = center, r = center;
            while (l >= 0 && r < n && str.charAt(l) == str.charAt(r)) {
                best = Math.max(best, r - l + 1);
                --l;
                ++r;
            }
            l = center;
            r = center + 1;
            while (l >= 0 && r < n && str.charAt(l) == str.charAt(r)) {
                best = Math.max(best, r - l + 1);
                --l;
                ++r;
            }
        }
        return best;
    }

    public static int longestPalindromeAfterSubstringConcatII(String s, String t) {
        int n = s.length();
        int m = t.length();
        StringBuilder sb = new StringBuilder(t);
        String revT = sb.reverse().toString();

        int[] dpPrev = new int[m + 1];
        int maxLen = 0;
        int maxOdd = 1;

        for (int i = 0; i < n; ++i) {
            int[] dpCurr = new int[m + 1];
            for (int j = 0; j < m; ++j) {
                if (s.charAt(i) == revT.charAt(j)) {
                    dpCurr[j + 1] = dpPrev[j] + 1;
                    int len = dpCurr[j + 1];
                    if (len > maxLen) maxLen = len;

                    boolean canExtendRightInS = i + 1 < n;
                    int startInT = m - 1 - j;
                    boolean canExtendLeftInT = startInT > 0;

                    if (canExtendRightInS || canExtendLeftInT) {
                        int oddLen = 2 * len + 1;
                        if (oddLen > maxOdd) maxOdd = oddLen;
                    }
                }
            }
            dpPrev = dpCurr;
        }

        int bestSingle = Math.max(longestPalindromicSubstring(s), longestPalindromicSubstring(t));
        int bestEven = 2 * maxLen;
        int answer = Math.max(bestSingle, Math.max(bestEven, maxOdd));
        return answer;
    }
}

