public class Router {
    private static class Packet {
        int source;
        int dest;
        int time;
        Packet(int s, int d, int t) {
            this.source = s;
            this.dest = d;
            this.time = t;
        }
    }

    private static class Triple {
        int s, d, t;
        Triple(int s, int d, int t) {
            this.s = s;
            this.d = d;
            this.t = t;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Triple)) return false;
            Triple other = (Triple) o;
            return s == other.s && d == other.d && t == other.t;
        }
        @Override
        public int hashCode() {
            int h1 = Integer.hashCode(s);
            int h2 = Integer.hashCode(d);
            int h3 = Integer.hashCode(t);
            int res = h1;
            res ^= h2 + 0x9e3779b9 + (res << 6) + (res >>> 2);
            res ^= h3 + 0x9e3779b9 + (res << 6) + (res >>> 2);
            return res;
        }
    }

    private final int limit;
    private final Deque<Packet> queue;
    private final HashSet<Triple> packetSet;
    private final HashMap<Integer, TreeMap<Integer, Integer>> destMap;

    public Router(int memoryLimit) {
        this.limit = memoryLimit;
        this.queue = new ArrayDeque<>();
        this.packetSet = new HashSet<>();
        this.destMap = new HashMap<>();
    }

    public boolean addPacket(int source, int destination, int timestamp) {
        Triple key = new Triple(source, destination, timestamp);
        if (packetSet.contains(key)) {
            return false;
        }
        if (queue.size() == limit) {
            Packet old = queue.pollFirst();
            Triple oldKey = new Triple(old.source, old.dest, old.time);
            packetSet.remove(oldKey);
            TreeMap<Integer, Integer> ms = destMap.get(old.dest);
            if (ms != null) {
                Integer cnt = ms.get(old.time);
                if (cnt != null) {
                    if (cnt == 1) ms.remove(old.time);
                    else ms.put(old.time, cnt - 1);
                }
                if (ms.isEmpty()) destMap.remove(old.dest);
            }
        }
        Packet p = new Packet(source, destination, timestamp);
        queue.addLast(p);
        packetSet.add(key);
        destMap.computeIfAbsent(destination, k -> new TreeMap<>())
               .merge(timestamp, 1, Integer::sum);
        return true;
    }

    public int[] forwardPacket() {
        if (queue.isEmpty()) return new int[0];
        Packet p = queue.pollFirst();
        Triple key = new Triple(p.source, p.dest, p.time);
        packetSet.remove(key);
        TreeMap<Integer, Integer> ms = destMap.get(p.dest);
        if (ms != null) {
            Integer cnt = ms.get(p.time);
            if (cnt != null) {
                if (cnt == 1) ms.remove(p.time);
                else ms.put(p.time, cnt - 1);
            }
            if (ms.isEmpty()) destMap.remove(p.dest);
        }
        return new int[]{p.source, p.dest, p.time};
    }

    public int getCount(int destination, int startTime, int endTime) {
        TreeMap<Integer, Integer> ms = destMap.get(destination);
        if (ms == null) return 0;
        NavigableMap<Integer, Integer> sub = ms.subMap(startTime, true, endTime, true);
        int total = 0;
        for (int cnt : sub.values()) {
            total += cnt;
        }
        return total;
    }
}

import java.util.*;

public class Solution {
    public static int countUniqueXorTriplets(int[] nums) {
        final int LIMIT = 2048;
        boolean[] present = new boolean[LIMIT];
        for (int x : nums) {
            if (x >= 0 && x < LIMIT) {
                present[x] = true;
            }
        }

        boolean[] pairXor = new boolean[LIMIT];
        for (int a = 0; a < LIMIT; ++a) {
            if (present[a]) {
                for (int b = 0; b < LIMIT; ++b) {
                    if (present[b]) {
                        pairXor[a ^ b] = true;
                    }
                }
            }
        }

        boolean[] result = new boolean[LIMIT];
        for (int v = 0; v < LIMIT; ++v) {
            if (present[v]) {
                result[v] = true;
            }
        }

        for (int p = 0; p < LIMIT; ++p) {
            if (pairXor[p]) {
                for (int c = 0; c < LIMIT; ++c) {
                    if (present[c]) {
                        result[p ^ c] = true;
                    }
                }
            }
        }

        int count = 0;
        for (int v = 0; v < LIMIT; ++v) {
            if (result[v]) {
                ++count;
            }
        }
        return count;
    }
}

