import java.util.*;

class Solution {
    private static class Edge {
        int to;
        int w;
        Edge(int to, int w) {
            this.to = to;
            this.w = w;
        }
    }

    private static class Fenwick {
        int n;
        long[] bit;
        Fenwick(int n) {
            this.n = n;
            this.bit = new long[n + 2];
        }
        void add(int idx, long val) {
            for (int i = idx; i <= n; i += i & -i) {
                bit[i] += val;
            }
        }
        void rangeAdd(int l, int r, long val) {
            add(l, val);
            add(r + 1, -val);
        }
        long pointQuery(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
    }

    public static List<Long> shortestPathQueries(int n, List<List<Integer>> edges, List<List<Integer>> queries) {
        List<List<Edge>> adj = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (List<Integer> e : edges) {
            int u = e.get(0);
            int v = e.get(1);
            int w = e.get(2);
            adj.get(u).add(new Edge(v, w));
            adj.get(v).add(new Edge(u, w));
        }

        int[] parent = new int[n + 1];
        int[] tin = new int[n + 1];
        int[] tout = new int[n + 1];
        long[] dist = new long[n + 1];
        long[] edgeWeight = new long[n + 1];
        int timer = 0;

        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{1, 0});
        parent[1] = 0;
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int v = cur[0];
            int state = cur[1];
            if (state == 0) {
                tin[v] = ++timer;
                stack.push(new int[]{v, 1});
                for (Edge e : adj.get(v)) {
                    int to = e.to;
                    int w = e.w;
                    if (to == parent[v]) continue;
                    parent[to] = v;
                    edgeWeight[to] = w;
                    dist[to] = dist[v] + w;
                    stack.push(new int[]{to, 0});
                }
            } else {
                tout[v] = timer;
            }
        }

        Fenwick fenwick = new Fenwick(n);
        List<Long> answer = new ArrayList<>();
        for (List<Integer> q : queries) {
            if (q.get(0) == 1) {
                int u = q.get(1);
                int v = q.get(2);
                int wnew = q.get(3);
                int child = (parent[u] == v) ? u : v;
                long delta = (long) wnew - edgeWeight[child];
                edgeWeight[child] = wnew;
                fenwick.rangeAdd(tin[child], tout[child], delta);
            } else {
                int x = q.get(1);
                long cur = dist[x] + fenwick.pointQuery(tin[x]);
                answer.add(cur);
            }
        }
        return answer;
    }
}

import java.util.*;

public class Solution {
    private static final long INF = 2000000000000000000L;
    private static long[][] combTable;

    private static void buildComb(int n) {
        combTable = new long[n + 1][n + 1];
        for (int i = 0; i <= n; ++i) {
            combTable[i][0] = combTable[i][i] = 1L;
            for (int j = 1; j < i; ++j) {
                long v = combTable[i - 1][j - 1] + combTable[i - 1][j];
                combTable[i][j] = v >= INF ? INF : v;
            }
        }
    }

    private static long countPerms(int[] cnt, int total) {
        long res = 1L;
        int remaining = total;
        for (int c : cnt) {
            if (c == 0) continue;
            long ways = combTable[remaining][c];
            if (res > INF / ways) return INF;
            res *= ways;
            if (res >= INF) return INF;
            remaining -= c;
        }
        return res;
    }

    public static String smallestPalindromicRearrangementII(String s, long k) {
        if (k <= 0) return "";
        int[] freq = new int[26];
        for (char ch : s.toCharArray()) freq[ch - 'a']++;

        StringBuilder middle = new StringBuilder();
        int[] halfCnt = new int[26];
        for (int i = 0; i < 26; ++i) {
            if ((freq[i] & 1) == 1) middle.append((char) ('a' + i));
            halfCnt[i] = freq[i] / 2;
        }

        int halfLen = 0;
        for (int v : halfCnt) halfLen += v;
        buildComb(halfLen);

        long totalPerms = countPerms(halfCnt, halfLen);
        if (k > totalPerms) return "";

        StringBuilder left = new StringBuilder(halfLen);
        for (int pos = 0; pos < halfLen; ++pos) {
            for (int i = 0; i < 26; ++i) {
                if (halfCnt[i] == 0) continue;
                halfCnt[i]--;
                long cntPerm = countPerms(halfCnt, halfLen - pos - 1);
                if (k > cntPerm) {
                    k -= cntPerm;
                    halfCnt[i]++; // restore
                } else {
                    left.append((char) ('a' + i));
                    break;
                }
            }
        }

        StringBuilder right = new StringBuilder(left).reverse();
        return left.toString() + middle.toString() + right.toString();
    }
}

