public class Solution {
    public static int maxSizeNonDecreasing(int[] nums) {
        java.util.ArrayList<Integer> stack = new java.util.ArrayList<>();
        for (int cur : nums) {
            while (!stack.isEmpty() && stack.get(stack.size() - 1) > cur) {
                cur = Math.max(stack.get(stack.size() - 1), cur);
                stack.remove(stack.size() - 1);
            }
            stack.add(cur);
        }
        return stack.size();
    }
}

import java.util.*;

class Solution {
    static class Node {
        int prod;
        int[] cnt;
        Node(int k) {
            cnt = new int[k];
        }
    }

    static int K;
    static Node[] seg;
    static int n;

    static Node merge(Node left, Node right) {
        Node res = new Node(K);
        res.prod = (left.prod * right.prod) % K;
        for (int i = 0; i < K; i++) {
            res.cnt[i] = left.cnt[i];
        }
        for (int i = 0; i < K; i++) {
            int shifted = (left.prod * i) % K;
            res.cnt[shifted] += right.cnt[i];
        }
        return res;
    }

    static void build(int idx, int l, int r, int[] arr) {
        if (l == r) {
            Node leaf = new Node(K);
            leaf.prod = arr[l] % K;
            leaf.cnt[leaf.prod] = 1;
            seg[idx] = leaf;
            return;
        }
        int mid = (l + r) >>> 1;
        build(idx * 2, l, mid, arr);
        build(idx * 2 + 1, mid + 1, r, arr);
        seg[idx] = merge(seg[idx * 2], seg[idx * 2 + 1]);
    }

    static void update(int idx, int l, int r, int pos, int val) {
        if (l == r) {
            Node leaf = new Node(K);
            leaf.prod = val % K;
            leaf.cnt[leaf.prod] = 1;
            seg[idx] = leaf;
            return;
        }
        int mid = (l + r) >>> 1;
        if (pos <= mid) update(idx * 2, l, mid, pos, val);
        else update(idx * 2 + 1, mid + 1, r, pos, val);
        seg[idx] = merge(seg[idx * 2], seg[idx * 2 + 1]);
    }

    static Node query(int idx, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return seg[idx];
        int mid = (l + r) >>> 1;
        if (qr <= mid) return query(idx * 2, l, mid, ql, qr);
        if (ql > mid) return query(idx * 2 + 1, mid + 1, r, ql, qr);
        Node left = query(idx * 2, l, mid, ql, qr);
        Node right = query(idx * 2 + 1, mid + 1, r, ql, qr);
        return merge(left, right);
    }

    public static int[] resultArray(int[] nums, int k, int[][] queries) {
        K = k;
        n = nums.length;
        seg = new Node[4 * n];
        build(1, 0, n - 1, nums);
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int index = queries[i][0];
            int value = queries[i][1];
            int start = queries[i][2];
            int xi = queries[i][3];
            update(1, 0, n - 1, index, value);
            int preProd = 1 % K;
            if (start > 0) {
                Node leftPart = query(1, 0, n - 1, 0, start - 1);
                preProd = leftPart.prod;
            }
            Node rangeNode = query(1, 0, n - 1, start, n - 1);
            int cnt = 0;
            for (int r = 0; r < K; r++) {
                if ((preProd * r) % K == xi) {
                    cnt += rangeNode.cnt[r];
                }
            }
            ans[i] = cnt;
        }
        return ans;
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1000000007L;

    private static int[] decimalToBase(String s, int b) {
        if (s.equals("0")) return new int[]{0};
        String cur = s;
        ArrayList<Integer> rev = new ArrayList<>();
        while (!(cur.length() == 1 && cur.charAt(0) == '0')) {
            StringBuilder next = new StringBuilder();
            int carry = 0;
            for (int i = 0; i < cur.length(); i++) {
                int num = carry * 10 + (cur.charAt(i) - '0');
                int q = num / b;
                carry = num % b;
                if (next.length() > 0 || q != 0) {
                    next.append((char) ('0' + q));
                }
            }
            rev.add(carry);
            cur = next.length() == 0 ? "0" : next.toString();
        }
        int n = rev.size();
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = rev.get(n - 1 - i);
        }
        return res;
    }

    private static String decrementString(String s) {
        char[] arr = s.toCharArray();
        int i = arr.length - 1;
        while (i >= 0 && arr[i] == '0') {
            arr[i] = '9';
            i--;
        }
        if (i >= 0) {
            arr[i] = (char) (arr[i] - 1);
        }
        int pos = 0;
        while (pos < arr.length && arr[pos] == '0') pos++;
        if (pos == arr.length) return "0";
        return new String(arr, pos, arr.length - pos);
    }

    private static long countUpTo(int[] digits, int b) {
        int n = digits.length;
        long[][][] memo = new long[n][b][2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < b; j++) {
                memo[i][j][0] = -1;
                memo[i][j][1] = -1;
            }
        }
        return dfs(0, 0, true, false, digits, b, memo);
    }

    private static long dfs(int idx, int prev, boolean tight, boolean started,
                            int[] digits, int b, long[][][] memo) {
        if (idx == digits.length) return 1L;
        int startedIdx = started ? 1 : 0;
        if (!tight && memo[idx][prev][startedIdx] != -1) {
            return memo[idx][prev][startedIdx];
        }
        int limit = tight ? digits[idx] : b - 1;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nstarted = started || d != 0;
            boolean ntight = tight && (d == limit);
            if (!nstarted) {
                res += dfs(idx + 1, 0, ntight, false, digits, b, memo);
            } else {
                if (!started) {
                    res += dfs(idx + 1, d, ntight, true, digits, b, memo);
                } else {
                    if (d >= prev) {
                        res += dfs(idx + 1, d, ntight, true, digits, b, memo);
                    }
                }
            }
            if (res >= MOD) res -= MOD;
        }
        if (!tight) memo[idx][prev][startedIdx] = res % MOD;
        return res % MOD;
    }

    public static void solve() {
        Scanner scanner = new Scanner(System.in);
        String l = scanner.next();
        String r = scanner.next();
        int b = scanner.nextInt();
        int[] rDigits = decimalToBase(r, b);
        long cntR = countUpTo(rDigits, b);
        long cntLMinus = 0;
        if (!l.equals("0")) {
            String lMinus = decrementString(l);
            int[] lDigits = decimalToBase(lMinus, b);
            cntLMinus = countUpTo(lDigits, b);
        }
        long ans = (cntR - cntLMinus) % MOD;
        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }
}

