public class Solution {
    public static int countCells(List<List<Character>> grid, String pattern) {
        int m = grid.size();
        if (m == 0) return 0;
        int n = grid.get(0).size();
        int M = m * n;
        int L = pattern.length();
        if (L > M) return 0;

        StringBuilder rowSb = new StringBuilder(M);
        for (int i = 0; i < m; i++) {
            List<Character> row = grid.get(i);
            for (int j = 0; j < n; j++) {
                rowSb.append(row.get(j));
            }
        }
        String rowStr = rowSb.toString();

        StringBuilder colSb = new StringBuilder(M);
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < m; i++) {
                colSb.append(grid.get(i).get(j));
            }
        }
        String colStr = colSb.toString();

        int[] lps = new int[L];
        for (int i = 1, len = 0; i < L; ) {
            if (pattern.charAt(i) == pattern.charAt(len)) {
                lps[i++] = ++len;
            } else if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }

        List<Integer> rowStarts = getStarts(rowStr, pattern, lps);
        List<Integer> colStarts = getStarts(colStr, pattern, lps);

        int[] horDiff = new int[M + 1];
        int[] verDiff = new int[M + 1];

        for (int start : rowStarts) {
            horDiff[start] += 1;
            if (start + L <= M) horDiff[start + L] -= 1;
        }

        for (int start : colStarts) {
            verDiff[start] += 1;
            if (start + L <= M) verDiff[start + L] -= 1;
        }

        boolean[] horCover = new boolean[M];
        boolean[] verCover = new boolean[M];
        int cur = 0;
        for (int i = 0; i < M; i++) {
            cur += horDiff[i];
            horCover[i] = cur > 0;
        }
        cur = 0;
        for (int i = 0; i < M; i++) {
            cur += verDiff[i];
            verCover[i] = cur > 0;
        }

        int answer = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int idxRow = i * n + j;
                int idxCol = j * m + i;
                if (horCover[idxRow] && verCover[idxCol]) {
                    answer++;
                }
            }
        }
        return answer;
    }

    private static List<Integer> getStarts(String text, String pattern, int[] lps) {
        List<Integer> starts = new ArrayList<>();
        int N = text.length();
        int L = pattern.length();
        int i = 0, j = 0;
        while (i < N) {
            if (text.charAt(i) == pattern.charAt(j)) {
                i++;
                j++;
                if (j == L) {
                    starts.add(i - L);
                    j = lps[j - 1];
                }
            } else if (j != 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return starts;
    }
}

