public class Solution {
    public static long calculateScore(List<String> instructions, List<Integer> values) {
        long score = 0;
        int n = instructions.size();
        boolean[] visited = new boolean[n];
        int idx = 0;
        while (idx >= 0 && idx < n && !visited[idx]) {
            visited[idx] = true;
            if ("add".equals(instructions.get(idx))) {
                score += (long) values.get(idx);
