public class Solution {
    public static long[] findXValue(int[] nums, int k) {
        long[] result = new long[k];
        long[] dp = new long[k];
        for (int v : nums) {
            long[] newDp = new long[k];
            int singleRem = v % k;
            if (singleRem < 0) singleRem += k;
            newDp[singleRem] += 1;
            for (int r = 0; r < k; ++r) {
                long cnt = dp[r];
                if (cnt == 0) continue;
                long prod = (long) r * v;
                int newRem = (int) (prod % k);
                if (newRem < 0) newRem += k;
                newDp[newRem] += cnt;
            }
            for (int r = 0; r < k; ++r) {
                if (newDp[r] != 0) {
                    result[r] += newDp[r];
                }
            }
            dp = newDp;
        }
        return result;
    }
}

import java.util.*;

public class Solution {
    public static boolean[] pathExistenceQueries(int n, int[] nums, int maxDiff, int[][] queries) {
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; ++i) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };

        java.util.function.BiConsumer<Integer, Integer> unionSets = (a, b) -> {
            int ra = find.applyAsInt(a);
            int rb = find.applyAsInt(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
        };

        for (int i = 1; i < n; ++i) {
            if (nums[i] - nums[i - 1] <= maxDiff) {
                unionSets.accept(i, i - 1);
            }
        }

        boolean[] answer = new boolean[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int u = queries[i][0];
            int v = queries[i][1];
            answer[i] = find.applyAsInt(u) == find.applyAsInt(v);
        }
        return answer;
    }
}

