class Solution {
    public static List<Integer> smallestDivisiblePermutation(List<Integer> nums, int k) {
        int n = nums.size();
        int fullMask = (1 << n) - 1;

        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = nums.get(i);

        int[] len = new int[n];
        int[] pow10mod = new int[n];
        for (int i = 0; i < n; i++) {
            int x = arr[i];
            int l = 0;
            while (x > 0) {
                ++l;
                x /= 10;
            }
            len[i] = l;
            int p = 1 % k;
            for (int j = 0; j < l; j++) p = (p * 10) % k;
            pow10mod[i] = p;
        }

        byte[][] memo = new byte[1 << n][k];
        for (int i = 0; i < memo.length; i++) Arrays.fill(memo[i], (byte) -1);

        java.util.function.BiFunction<Integer, Integer, Boolean> can = new java.util.function.BiFunction<Integer, Integer, Boolean>() {
            @Override
            public Boolean apply(Integer mask, Integer rem) {
                if (mask == fullMask) return rem == 0;
                byte stored = memo[mask][rem];
                if (stored != -1) return stored == 1;
                memo[mask][rem] = 0;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) continue;
                    int newRem = (int) (((long) rem * pow10mod[i]) % k);
                    newRem = (newRem + arr[i] % k) % k;
                    if (apply(mask | (1 << i), newRem)) {
                        memo[mask][rem] = 1;
                        break;
                    }
                }
                return memo[mask][rem] == 1;
            }
        };

        if (!can.apply(0, 0)) return new ArrayList<>();

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(arr[a], arr[b]));

        List<Integer> answer = new ArrayList<>();
        int mask = 0, rem = 0;
        for (int pos = 0; pos < n; pos++) {
            for (int idx : order) {
                if ((mask & (1 << idx)) != 0) continue;
                int newRem = (int) (((long) rem * pow10mod[idx]) % k);
                newRem = (newRem + arr[idx] % k) % k;
                if (can.apply(mask | (1 << idx), newRem)) {
                    answer.add(arr[idx]);
                    mask |= (1 << idx);
                    rem = newRem;
                    break;
                }
            }
        }
        return answer;
    }
}

