class Solution {
    public static int[] baseUnitConversion(List<List<Integer>> conversions) {
        final long MOD = 1000000007L;
        int n = conversions.size() + 1;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (List<Integer> conv : conversions) {
            int src = conv.get(0);
            int tgt = conv.get(1);
            int factor = conv.get(2);
            adj[src].add(new int[]{tgt, factor});
        }
        long[] ans64 = new long[n];
        ans64[0] = 1;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int[] p : adj[u]) {
                int v = p[0];
                int factor = p[1];
                ans64[v] = (ans64[u] * factor) % MOD;
                stack.push(v);
            }
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = (int) ans64[i];
        }
        return ans;
    }
}

import java.util.*;

public class Solution {
    public static long maxProfit(int n, List<int[]> edges, long[] score) {
        int[] preMask = new int[n];
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            preMask[v] |= 1 << u;
        }
        int totalMask = (1 << n) - 1;
        final long NEG_INF = Long.MIN_VALUE;
        long[] dp = new long[1 << n];
        Arrays.fill(dp, NEG_INF);
        dp[0] = 0;
        for (int mask = 0; mask <= totalMask; ++mask) {
            long placed = dp[mask];
            if (placed == NEG_INF) continue;
            int pos = Integer.bitCount(mask) + 1;
            for (int v = 0; v < n; ++v) {
                if ((mask & (1 << v)) != 0) continue;
                if ((preMask[v] & ~mask) != 0) continue;
                int nextMask = mask | (1 << v);
                long profit = placed + score[v] * pos;
                if (profit > dp[nextMask]) dp[nextMask] = profit;
            }
        }
        return dp[totalMask];
    }
}

