class Solution {
    public static int[][] fillSpecialGrid(int n) {
        int size = 1 << n;
        int[][] grid = new int[size][size];
        fill(0, 0, size, 0, grid);
        return grid;
    }

    private static void fill(int r, int c, int sz, int start, int[][] grid) {
        if (sz == 1) {
            grid[r][c] = start;
            return;
        }
        int half = sz >> 1;
        int quad = half * half;
        fill(r, c + half, half, start + 0 * quad, grid);
        fill(r + half, c + half, half, start + 1 * quad, grid);
        fill(r + half, c, half, start + 2 * quad, grid);
        fill(r, c, half, start + 3 * quad, grid);
    }
}

