public class Solution {
    public static int countBuildings(int n, List<List<Integer>> buildings) {
        Map<Integer, int[]> rowMap = new HashMap<>();
        Map<Integer, int[]> colMap = new HashMap<>();
        for (List<Integer> b : buildings) {
            int x = b.get(0);
            int y = b.get(1);
            int[] row = rowMap.get(y);
            if (row == null) {
                row = new int[]{x, x};
                rowMap.put(y, row);
            } else {
                if (x < row[0]) row[0] = x;
                if (x > row[1]) row[1] = x;
            }
            int[] col = colMap.get(x);
            if (col == null) {
                col = new int[]{y, y};
                colMap.put(x, col);
            } else {
                if (y < col[0]) col[0] = y;
                if (y > col[1]) col[1] = y;
            }
        }
        int covered = 0;
        for (List<Integer> b : buildings) {
            int x = b.get(0);
            int y = b.get(1);
            int[] row = rowMap.get(y);
            int[] col = colMap.get(x);
            if (x > row[0] && x < row[1] && y > col[0] && y < col[1]) {
                ++covered;
            }
        }
        return covered;
    }
}

class Solution {
    public long minTravelTime(int l, int n, int k, int[] position, int[] time) {
        long INF = Long.MAX_VALUE / 2;
        long[] prefix = new long[n];
        for (int i = 0; i < n - 1; i++) prefix[i + 1] = prefix[i] + time[i];
        long[][][] dp = new long[n + 1][n][k + 1];
        for (long[][] a : dp) for (long[] b : a) java.util.Arrays.fill(b, INF);
        dp[0][0][0] = 0;
        for (int c = 0; c < n - 1; c++) {
            for (int pidx = 0; pidx <= n; pidx++) {
                for (int m = 0; m <= k; m++) {
                    long cost0 = dp[pidx][c][m];
                    if (cost0 >= INF) continue;
                    int p = pidx - 1;
                    long rate = prefix[c + 1] - prefix[p + 1];
                    for (int i2 = c + 1; i2 < n; i2++) {
                        int mergesAdd = i2 - c - 1;
                        int m2 = m + mergesAdd;
                        if (m2 > k) continue;
                        long newcost = cost0 + rate * (position[i2] - position[c]);
                        if (newcost < dp[c + 1][i2][m2]) dp[c + 1][i2][m2] = newcost;
                    }
                }
            }
        }
        long ans = INF;
        for (int pidx = 0; pidx <= n; pidx++) ans = Math.min(ans, dp[pidx][n - 1][k]);
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int[] shortestPathLengths(int n, int[] nums, int maxDiff, int[][] queries) {
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            int diff = nums[a] - nums[b];
            if (diff != 0) return diff;
            return Integer.compare(a, b);
        });
        int[] sortedVals = new int[n];
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) {
            sortedVals[i] = nums[idx[i]];
            pos[idx[i]] = i;
        }
        int[] far = new int[n];
        int r = 0;
        for (int i = 0; i < n; i++) {
            if (r < i) r = i;
            while (r + 1 < n && sortedVals[r + 1] - sortedVals[i] <= maxDiff) {
                r++;
            }
            far[i] = r;
        }
        int LOG = (int) Math.ceil(Math.log(n) / Math.log(2)) + 1;
        int[][] up = new int[LOG][n];
        for (int i = 0; i < n; i++) up[0][i] = far[i];
        for (int k = 1; k < LOG; k++) {
            for (int i = 0; i < n; i++) {
                up[k][i] = up[k - 1][up[k - 1][i]];
            }
        }
        int[] answers = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int u = queries[qi][0];
            int v = queries[qi][1];
            if (u == v) {
                answers[qi] = 0;
                continue;
            }
            int pu = pos[u];
            int pv = pos[v];
            if (pu > pv) {
                int tmp = pu;
                pu = pv;
                pv = tmp;
            }
            int cur = pu;
            int steps = 0;
            for (int k = LOG - 1; k >= 0; k--) {
                int nxt = up[k][cur];
                if (nxt < pv) {
                    cur = nxt;
                    steps += 1 << k;
                }
            }
            if (far[cur] >= pv) {
                answers[qi] = steps + 1;
            } else {
                answers[qi] = -1;
            }
        }
        return answers;
    }
}

