class Solution {
    public static int maxProductTwoDigits(long n) {
        String s = Long.toString(n);
        int[] freq = new int[10];
        for (int i = 0; i < s.length(); ++i) {
            freq[s.charAt(i) - '0']++;
        }
        int first = -1;
        for (int d = 9; d >= 0; --d) {
            if (freq[d] > 0) {
                first = d;
                break;
            }
        }
        if (first == -1) return 0;
        if (freq[first] >= 2) return first * first;
        int second = -1;
        for (int d = first - 1; d >= 0; --d) {
            if (freq[d] > 0) {
                second = d;
                break;
            }
        }
        if (second == -1) return 0;
        return first * second;
    }
}

