class Solution {
    public static int minOperations(int[] nums) {
        int ops = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        for (int h : nums) {
            while (!stack.isEmpty() && stack.peekLast() > h) {
                stack.pollLast();
            }
            if (h > 0 && (stack.isEmpty() || stack.peekLast() < h)) {
                stack.addLast(h);
                ops++;
            }
        }
        return ops;
    }
}

