class Solution {
    public int maxWeightPath(int n, int[][] edges, int k, int t) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int w = e[2];
            adj[u].add(new int[]{v, w});
        }
        int[][] dp = new int[k + 1][n];
        for (int i = 0; i <= k; i++) Arrays.fill(dp[i], -1);
        for (int i = 0; i < n; i++) dp[0][i] = 0;
        for (int used = 0; used < k; used++) {
            for (int u = 0; u < n; u++) {
                int cur = dp[used][u];
                if (cur < 0) continue;
                for (int[] e : adj[u]) {
                    int v = e[0];
                    int w = e[1];
                    int ns = cur + w;
                    if (ns < t && ns > dp[used + 1][v]) {
                        dp[used + 1][v] = ns;
                    }
                }
            }
        }
        int ans = -1;
        for (int v = 0; v < n; v++) {
            ans = Math.max(ans, dp[k][v]);
        }
        return ans;
    }
}

