import java.util.*;

class Solution {
    private int LOG;
    private int[][] up;
    private int[] depth;
    private long[] distRoot;
    private List<int[]>[] adj;

    private int lca(int u, int v) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        int diff = depth[u] - depth[v];
        for (int k = LOG - 1; k >= 0; k--) {
            if ((diff & (1 << k)) != 0) {
                u = up[k][u];
            }
        }
        if (u == v) return u;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][u] != up[k][v]) {
                u = up[k][u];
                v = up[k][v];
            }
        }
        return up[0][u];
    }

    private long distance(int u, int v) {
        int w = lca(u, v);
        return distRoot[u] + distRoot[v] - 2L * distRoot[w];
    }

    public long[] minimumWeightedSubgraph(int[][] edges, int[][] queries) {
        int n = edges.length + 1;
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }

        LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        up = new int[LOG][n];
        depth = new int[n];
        distRoot = new long[n];

        int root = 0;
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(root);
        visited[root] = true;
        up[0][root] = root;
        depth[root] = 0;
        distRoot[root] = 0L;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int[] nb : adj[u]) {
                int v = nb[0];
                int w = nb[1];
                if (!visited[v]) {
                    visited[v] = true;
                    up[0][v] = u;
                    depth[v] = depth[u] + 1;
                    distRoot[v] = distRoot[u] + w;
                    stack.push(v);
                }
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 0; v < n; v++) {
                up[k][v] = up[k - 1][up[k - 1][v]];
            }
        }

        int q = queries.length;
        long[] ans = new long[q];
        for (int i = 0; i < q; i++) {
            int src1 = queries[i][0];
            int src2 = queries[i][1];
            int dest = queries[i][2];
            long d1 = distance(src1, src2);
            long d2 = distance(src1, dest);
            long d3 = distance(src2, dest);
            ans[i] = (d1 + d2 + d3) / 2L;
        }
        return ans;
    }
}

import java.util.*;

public class H5 {
    static long maxScore(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int m = edges.length;
        boolean isCycle = (m == n);

        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[n];
        int start = 0;
        if (!isCycle) {
            for (int i = 0; i < n; i++) {
                if (adj.get(i).size() <= 1) { start = i; break; }
            }
        }
        int prev = -1, cur = start;
        while (cur != -1) {
            order.add(cur);
            visited[cur] = true;
            int nxt = -1;
            for (int nb : adj.get(cur)) {
                if (nb != prev && !visited[nb]) { nxt = nb; break; }
            }
            prev = cur;
            cur = nxt;
            if (isCycle && cur == start) break;
        }

        int k = order.size();
        int[] vals = new int[k];
        for (int i = 0; i < k; i++) vals[i] = k - i;

        Deque<Integer> arrangement = new ArrayDeque<>();
        arrangement.add(vals[0]);
        for (int i = 1; i < k; i++) {
            if (i % 2 == 1) arrangement.addLast(vals[i]);
            else arrangement.addFirst(vals[i]);
        }
        List<Integer> arrList = new ArrayList<>(arrangement);

        int[] value = new int[n];
        for (int idx = 0; idx < k; idx++) value[order.get(idx)] = arrList.get(idx);

        long total = 0;
        for (int i = 0; i < k - 1; i++) total += (long) value[order.get(i)] * value[order.get(i+1)];
        if (isCycle) total += (long) value[order.get(k-1)] * value[order.get(0)];
        return total;
    }

    public static void main(String[] args) {
        System.out.println(maxScore(4, new int[][]{{0,1},{1,2},{2,3}}) + " expected 23");
        System.out.println(maxScore(6, new int[][]{{0,3},{4,5},{2,0},{1,3},{2,4},{1,5}}) + " expected 82");
    }
}

