class Solution {
    public static boolean equalSumGridPartition(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long total = 0;
        long[] rowSum = new long[m];
        long[] colSum = new long[n];
        long mainDiag = 0;
        long antiDiag = 0;
        int diagLen = Math.min(m, n);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = grid[i][j];
                total += val;
                rowSum[i] += val;
                colSum[j] += val;
                if (i == j && i < diagLen) {
                    mainDiag += val;
                }
                if (j == n - 1 - i && i < diagLen) {
                    antiDiag += val;
                }
            }
        }
        if ((total & 1L) == 1L) return false;
        long half = total / 2;
        long prefix = 0;
        for (int i = 0; i < m - 1; i++) {
            prefix += rowSum[i];
            if (prefix == half) return true;
        }
        prefix = 0;
        for (int j = 0; j < n - 1; j++) {
            prefix += colSum[j];
            if (prefix == half) return true;
        }
        if (mainDiag == half) return true;
        if (antiDiag == half) return true;
        return false;
    }
}

