class Solution {
    public static int sumLargestPrimes(String s) {
        int n = s.length();
        Set<Integer> primeSet = new HashSet<>();
        for (int i = 0; i < n; i++) {
            StringBuilder numStr = new StringBuilder();
            for (int j = i; j < n; j++) {
                numStr.append(s.charAt(j));
                int num = Integer.parseInt(numStr.toString());
                if (num >= 2 && isPrime(num)) {
                    primeSet.add(num);
                }
            }
        }
        List<Integer> primes = new ArrayList<>(primeSet);
        primes.sort(Collections.reverseOrder());
        int sum = 0;
        for (int k = 0; k < Math.min(3, primes.size()); k++) {
            sum += primes.get(k);
        }
        return sum;
    }

    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

