class Solution {
    public int maxNonIntersectingSubstrings(String word) {
        int n = word.length();
        if (n < 4) return 0;
        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] pos = new ArrayList[26];
        for (int i = 0; i < 26; i++) pos[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pos[word.charAt(i) - 'a'].add(i);
        }
        List<int[]> intervals = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int c = word.charAt(i) - 'a';
            ArrayList<Integer> list = pos[c];
            int target = i + 3;
            int lo = 0, hi = list.size() - 1, ans = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (list.get(mid) >= target) {
                    ans = list.get(mid);
                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            }
            if (ans != -1) {
                intervals.add(new int[]{i, ans});
            }
        }
        intervals.sort((a, b) -> {
            if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
            return Integer.compare(a[0], b[0]);
        });
        int count = 0;
        int lastEnd = -1;
        for (int[] iv : intervals) {
            if (iv[0] > lastEnd) {
                count++;
                lastEnd = iv[1];
            }
        }
        return count;
    }
}

