class Solution {
    private static int digitSum(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }

    private static class Node {
        int value;
        int digitSum;
        int originalIdx;

        Node(int value, int digitSum, int originalIdx) {
            this.value = value;
            this.digitSum = digitSum;
            this.originalIdx = originalIdx;
        }
    }

    public static int minSwaps(int[] nums) {
        List<Node> withKeys = new ArrayList<>(nums.length);
        for (int i = 0; i < nums.length; i++) {
            withKeys.add(new Node(nums[i], digitSum(nums[i]), i));
        }

        withKeys.sort((a, b) -> {
            if (a.digitSum != b.digitSum) return a.digitSum - b.digitSum;
            return a.value - b.value;
        });

        Map<Integer, Integer> targetPos = new HashMap<>();
        for (int idx = 0; idx < withKeys.size(); idx++) {
            targetPos.put(withKeys.get(idx).value, idx);
        }

        boolean[] visited = new boolean[nums.length];
        int swaps = 0;

        for (int i = 0; i < nums.length; i++) {
            if (visited[i]) continue;
            int cycleLen = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                int nextValue = nums[j];
                j = targetPos.get(nextValue);
                cycleLen++;
            }
            if (cycleLen > 1) swaps += cycleLen - 1;
        }

        return swaps;
    }
}

