public class Solution {
    public int minMoves(String[] matrix) {
        int m = matrix.length;
        int n = matrix[0].length();
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, -1);
        @SuppressWarnings("unchecked")
        List<Integer>[] portals = new ArrayList[26];
        for (int i = 0; i < 26; i++) portals[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            String row = matrix[i];
            for (int j = 0; j < n; j++) {
                char ch = row.charAt(j);
                if (ch >= 'A' && ch <= 'Z') {
                    portals[ch - 'A'].add(i * n + j);
                }
            }
        }
        boolean[] used = new boolean[26];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[0][0] = 0;
        q.add(0);
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        while (!q.isEmpty()) {
            int pos = q.poll();
            int r = pos / n;
            int c = pos % n;
            int curDist = dist[r][c];
            if (r == m - 1 && c == n - 1) {
                return curDist;
            }
            // normal moves
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (matrix[nr].charAt(nc) == '#') continue;
                if (dist[nr][nc] != -1) continue;
                dist[nr][nc] = curDist + 1;
                q.add(nr * n + nc);
            }
            // portal teleport
            char ch = matrix[r].charAt(c);
            if (ch >= 'A' && ch <= 'Z') {
                int idx = ch - 'A';
                if (!used[idx]) {
                    for (int p : portals[idx]) {
                        int pr = p / n;
                        int pc = p % n;
                        if (dist[pr][pc] == -1) {
                            dist[pr][pc] = curDist;
                            q.add(pr * n + pc);
                        }
                    }
                    used[idx] = true;
                }
            }
        }
        return -1;
    }
}

