class Solution {
    public static int[][] minAbsDiffInSlidingSubmatrix(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int rows = m - k + 1;
        int cols = n - k + 1;
        int[][] ans = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                List<Integer> values = new ArrayList<>();
                for (int x = i; x < i + k; x++) {
                    for (int y = j; y < j + k; y++) {
                        values.add(grid[x][y]);
                    }
                }
                Collections.sort(values);
                int minDiff = Integer.MAX_VALUE;
                for (int p = 1; p < values.size(); p++) {
                    int a = values.get(p - 1);
                    int b = values.get(p);
                    if (a == b) continue;
                    int diff = b - a;
                    if (diff < minDiff) minDiff = diff;
                }
                ans[i][j] = (minDiff == Integer.MAX_VALUE) ? 0 : minDiff;
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    static int budget;
    static int[] present, future;
    static List<Integer>[] tree;
    static Map<Long, long[][]> memo = new HashMap<>();

    public static long maxProfitFromStocks(int n, int[] present_, int[] future_, int[][] hierarchy, int budget_) {
        present = present_; future = future_; budget = budget_;
        memo.clear();
        tree = new List[n];
        for (int i = 0; i < n; i++) tree[i] = new ArrayList<>();
        for (int[] e : hierarchy) tree[e[0]-1].add(e[1]-1);
        long[][] res = dp(0, -1);
        long ans = 0;
        for (long v : res[0]) ans = Math.max(ans, v);
        return ans;
    }

    static long[] merge(long[] A, long[] B) {
        long[] merged = new long[A.length];
        Arrays.fill(merged, Long.MIN_VALUE/4);
        for (int i = 0; i < A.length; i++) {
            if (A[i] == Long.MIN_VALUE/4) continue;
            for (int j = 0; i+j < A.length; j++) {
                if (B[j] == Long.MIN_VALUE/4) continue;
                merged[i+j] = Math.max(merged[i+j], A[i]+B[j]);
            }
        }
        return merged;
    }

    static long[][] dp(int u, int parent) {
        long key = (long)(u+1)*100000 + (parent+1);
        if (memo.containsKey(key)) return memo.get(key);
        long[] noDiscount = new long[budget+1];
        long[] withDiscount = new long[budget+1];
        for (int v : tree[u]) {
            if (v == parent) continue;
            long[][] c = dp(v, u);
            noDiscount = merge(noDiscount, c[0]);
            withDiscount = merge(withDiscount, c[1]);
        }
        long[] newDp0 = noDiscount.clone(), newDp1 = noDiscount.clone();
        int fullCost = present[u];
        for (int b = fullCost; b <= budget; b++) {
            long profit = (long) future[u] - fullCost;
            if (withDiscount[b-fullCost] != Long.MIN_VALUE/4) newDp0[b] = Math.max(newDp0[b], withDiscount[b-fullCost]+profit);
        }
        int halfCost = present[u]/2;
        for (int b = halfCost; b <= budget; b++) {
            long profit = (long) future[u] - halfCost;
            if (withDiscount[b-halfCost] != Long.MIN_VALUE/4) newDp1[b] = Math.max(newDp1[b], withDiscount[b-halfCost]+profit);
        }
        long[][] result = {newDp0, newDp1};
        memo.put(key, result);
        return result;
    }

}

