class Solution {
    public static String smallestStringAfterRemovals(String s) {
        int n = s.length();
        if (n == 0) return "";
        java.util.function.BiPredicate<Character, Character> isConsecutive = (a, b) -> {
            int diff = Math.abs(a - b);
            return diff == 1 || diff == 25;
        };
        boolean[][] can = new boolean[n][n];
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                for (int k = i + 1; k <= j; k++) {
                    if (isConsecutive.test(s.charAt(i), s.charAt(k)) &&
                        (i + 1 > k - 1 || can[i + 1][k - 1]) &&
                        (k + 1 > j || can[k + 1][j])) {
                        can[i][j] = true;
                        break;
                    }
                }
            }
        }
        String[][] best = new String[n][n];
        for (int i = 0; i < n; i++) best[i][i] = String.valueOf(s.charAt(i));
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (can[i][j]) {
                    best[i][j] = "";
                    continue;
                }
                String cur = s.substring(i, j + 1);
                for (int m = i; m < j; m++) {
                    String cand = best[i][m] + best[m + 1][j];
                    if (cand.compareTo(cur) < 0) cur = cand;
                }
                best[i][j] = cur;
            }
        }
        return best[0][n - 1];
    }
}

import java.math.BigInteger;

class Solution {
    public boolean canPartition(int[] nums, int target) {
        BigInteger total = BigInteger.ONE;
        for (int v : nums) {
            total = total.multiply(BigInteger.valueOf(v));
        }
        BigInteger targetSq = BigInteger.valueOf(target).multiply(BigInteger.valueOf(target));
        if (!total.equals(targetSq)) {
            return false;
        }
        return dfs(nums, 0, 1L, 0, target);
    }

    private boolean dfs(int[] nums, int idx, long prod, int count, int target) {
        if (prod == target) {
            return count > 0 && count < nums.length;
        }
        if (idx == nums.length || prod > target) {
            return false;
        }
        if (prod <= target / nums[idx]) {
            if (dfs(nums, idx + 1, prod * nums[idx], count + 1, target)) {
                return true;
            }
        }
        return dfs(nums, idx + 1, prod, count, target);
    }
}

