public class Solution {
    public int minimumMoves(String[] classroom, int energy) {
        int m = classroom.length;
        int n = classroom[0].length();
        int startR = -1, startC = -1;
        int[][] litterIdx = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(litterIdx[i], -1);
        }
        List<int[]> litterList = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            String row = classroom[i];
            for (int j = 0; j < n; j++) {
                char ch = row.charAt(j);
                if (ch == 'S') {
                    startR = i;
                    startC = j;
                } else if (ch == 'L') {
                    litterIdx[i][j] = litterList.size();
                    litterList.add(new int[]{i, j});
                }
            }
        }
        int L = litterList.size();
        int allMask = (1 << L) - 1;
        boolean[][][][] visited = new boolean[m][n][energy + 1][1 << L];
        Queue<int[]> q = new ArrayDeque<>();
        int initEnergy = energy;
        visited[startR][startC][initEnergy][0] = true;
        q.offer(new int[]{startR, startC, initEnergy, 0, 0}); // r, c, energy, mask, dist
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], e = cur[2], mask = cur[3], dist = cur[4];
            if (mask == allMask) {
                return dist;
            }
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                char ch = classroom[nr].charAt(nc);
                if (ch == 'X') continue;
                int ne = e - 1;
                if (ne < 0) continue;
                if (ch == 'R') {
                    ne = energy;
                }
                int nmask = mask;
                if (ch == 'L') {
                    int idx = litterIdx[nr][nc];
                    nmask = mask | (1 << idx);
                }
                if (!visited[nr][nc][ne][nmask]) {
                    visited[nr][nc][ne][nmask] = true;
                    q.offer(new int[]{nr, nc, ne, nmask, dist + 1});
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    private static final long NEG = Long.MIN_VALUE / 4;

    public static int maximumGoodSubtreeScore(int[] vals, int[] par) {
        int n = vals.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) children[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            children[par[i]].add(i);
        }

        int[] nodeMask = new int[n];
        for (int i = 0; i < n; i++) {
            int v = vals[i];
            int mask = 0;
            boolean ok = true;
            while (v > 0) {
                int d = v % 10;
                if ((mask & (1 << d)) != 0) {
                    ok = false;
                    break;
                }
                mask |= 1 << d;
                v /= 10;
            }
            nodeMask[i] = ok ? mask : -1;
        }

        long[] maxScore = new long[n];
        dfs(0, children, nodeMask, vals, maxScore);
        long total = 0;
        for (int i = 0; i < n; i++) {
            total = (total + maxScore[i]) % MOD;
        }
        return (int) total;
    }

    private static long[] dfs(int u, List<Integer>[] children, int[] nodeMask, int[] vals, long[] maxScore) {
        long[] dp = new long[1024];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int v : children[u]) {
            long[] childDP = dfs(v, children, nodeMask, vals, maxScore);
            long[] newDP = new long[1024];
            Arrays.fill(newDP, NEG);
            for (int m1 = 0; m1 < 1024; m1++) {
                if (dp[m1] == NEG) continue;
                for (int m2 = 0; m2 < 1024; m2++) {
                    if (childDP[m2] == NEG) continue;
                    if ((m1 & m2) != 0) continue;
                    int nm = m1 | m2;
                    long val = dp[m1] + childDP[m2];
                    if (val > newDP[nm]) newDP[nm] = val;
                }
            }
            for (int m = 0; m < 1024; m++) {
                if (newDP[m] > dp[m]) dp[m] = newDP[m];
            }
        }

        int mask = nodeMask[u];
        if (mask != -1) {
            for (int m = 0; m < 1024; m++) {
                if (dp[m] == NEG) continue;
                if ((m & mask) != 0) continue;
                int nm = m | mask;
                long val = dp[m] + vals[u];
                if (val > dp[nm]) dp[nm] = val;
            }
        }

        long best = 0;
        for (int m = 0; m < 1024; m++) {
            if (dp[m] > best) best = dp[m];
        }
        maxScore[u] = best;
        return dp;
    }
}

class Solution {
    static final int MAXV = 100000;
    static boolean[] IS_PRIME = buildSieve();

    static boolean[] buildSieve() {
        boolean[] isP = new boolean[MAXV + 1];
        Arrays.fill(isP, true);
        isP[0] = isP[1] = false;
        for (int i = 2; (long) i * i <= MAXV; i++)
            if (isP[i]) for (int j = i * i; j <= MAXV; j += i) isP[j] = false;
        return isP;
    }

    public int[] maximizeDistinctPrimeCount(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int idx = queries[qi][0], val = queries[qi][1];
            nums[idx] = val;
            Map<Integer, int[]> positions = new HashMap<>();
            int totalDistinct = 0;
            for (int i = 0; i < n; i++) {
                int v = nums[i];
                if (v <= MAXV && IS_PRIME[v]) {
                    if (!positions.containsKey(v)) {
                        positions.put(v, new int[]{i, i});
                        totalDistinct++;
                    } else {
                        positions.get(v)[1] = i;
                    }
                }
            }
            int[] diff = new int[n + 1];
            for (int[] pr : positions.values()) {
                int first = pr[0], last = pr[1];
                if (last > first) {
                    int l = first + 1, r = last;
                    diff[l] += 1;
                    diff[r + 1] -= 1;
                }
            }
            int bestOverlap = 0, cur = 0;
            for (int p = 1; p < n; p++) {
                cur += diff[p];
                bestOverlap = Math.max(bestOverlap, cur);
            }
            ans[qi] = totalDistinct + bestOverlap;
        }
        return ans;
    }
}

