public class Solution {
    public long maxScore(int[] nums, int k) {
        int n = nums.length;
        long best = 0;
        for (int i = 0; i < n; i++) {
            int oddCount = 0;
            int g = 0;
            for (int j = i; j < n; j++) {
                int val = nums[j];
                g = gcd(g, val);
                if ((val & 1) == 1) {
                    oddCount++;
                }
                long len = j - i + 1;
                long score = len * g;
                if (score > best) {
                    best = score;
                }
                if (oddCount <= k) {
                    long score2 = len * (long) g * 2;
                    if (score2 > best) {
                        best = score2;
                    }
                }
            }
        }
        return best;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

