class Solution {
    private static boolean canMakeTarget(int[] nums, int k, int targetBit) {
        int n = nums.length;
        int[] diff = new int[n + 1];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur ^= diff[i];
            int val = nums[i] == 1 ? 1 : 0;
            if ((val ^ cur) != targetBit) {
                if (i + k > n) {
                    return false;
                }
                cur ^= 1;
                diff[i + k] ^= 1;
            }
        }
        return true;
    }

    public static boolean canMakeEqual(int[] nums, int k) {
        return canMakeTarget(nums, k, 0) || canMakeTarget(nums, k, 1);
    }
}

