class Solution {
    public static int maxYSum(int[] x, int[] y) {
        Map<Integer, Integer> best = new HashMap<>();
        for (int i = 0; i < x.length; i++) {
            int curX = x[i];
            int curY = y[i];
            if (!best.containsKey(curX) || curY > best.get(curX)) {
                best.put(curX, curY);
            }
        }
        int first = Integer.MIN_VALUE, second = Integer.MIN_VALUE, third = Integer.MIN_VALUE;
        for (int val : best.values()) {
            if (val > first) {
                third = second;
                second = first;
                first = val;
            } else if (val > second) {
                third = second;
                second = val;
            } else if (val > third) {
                third = val;
            }
        }
        return third == Integer.MIN_VALUE ? -1 : first + second + third;
    }
}

public class P9 {
    static final long NEG = Long.MIN_VALUE / 2;

    static long maximumProfit(int[] prices, int k) {
        int n = prices.length;
        long[][] f = new long[k+1][3];
        for (long[] row : f) java.util.Arrays.fill(row, NEG);
        f[0][0] = 0;
        for (int j = 1; j <= k; j++) {
            f[j][0] = 0;
            f[j][1] = -prices[0];
            f[j][2] = prices[0];
        }
        for (int i = 1; i < n; i++) {
            long[][] nf = new long[k+1][3];
            for (long[] row : nf) java.util.Arrays.fill(row, NEG);
            nf[0][0] = 0;
            for (int j = 1; j <= k; j++) {
                long best0 = f[j][0];
                if (f[j][1] > NEG) best0 = Math.max(best0, f[j][1] + prices[i]);
                if (f[j][2] > NEG) best0 = Math.max(best0, f[j][2] - prices[i]);
                nf[j][0] = best0;

                long best1 = f[j][1];
                if (f[j-1][0] > NEG) best1 = Math.max(best1, f[j-1][0] - prices[i]);
                nf[j][1] = best1;

                long best2 = f[j][2];
                if (f[j-1][0] > NEG) best2 = Math.max(best2, f[j-1][0] + prices[i]);
                nf[j][2] = best2;
            }
            f = nf;
        }
        return f[k][0];
    }

