import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countPartitions(int[] nums, int k) {
        int n = nums.length;
        long[] dp = new long[n + 1];
        long[] pref = new long[n + 1];
        dp[0] = 1;
        pref[0] = 1;

        Deque<Integer> minDeque = new ArrayDeque<>();
        Deque<Integer> maxDeque = new ArrayDeque<>();
        int left = 0;

        for (int i = 0; i < n; i++) {
            while (!minDeque.isEmpty() && nums[minDeque.peekLast()] >= nums[i]) {
                minDeque.pollLast();
            }
            minDeque.offerLast(i);

            while (!maxDeque.isEmpty() && nums[maxDeque.peekLast()] <= nums[i]) {
                maxDeque.pollLast();
            }
            maxDeque.offerLast(i);

            while (!minDeque.isEmpty() && !maxDeque.isEmpty()
                    && (long) nums[maxDeque.peekFirst()] - (long) nums[minDeque.peekFirst()] > k) {
                if (minDeque.peekFirst() == left) {
                    minDeque.pollFirst();
                }
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                left++;
            }

            int L = left;
            long sum = pref[i];
            if (L > 0) {
                sum = (sum - pref[L - 1] + MOD) % MOD;
            }
            dp[i + 1] = sum;
            pref[i + 1] = (pref[i] + dp[i + 1]) % MOD;
        }

        return (int) dp[n];
    }
}

