public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countUnlockPermutations(int[] complexity) {
        int n = complexity.length;
        int min = Integer.MAX_VALUE;
        int minCount = 0;
        for (int v : complexity) {
            if (v < min) {
                min = v;
                minCount = 1;
            } else if (v == min) {
                minCount++;
            }
        }
        if (complexity[0] != min || minCount != 1) {
            return 0;
        }
        long fact = 1;
        for (int i = 2; i <= n - 1; i++) {
            fact = (fact * i) % MOD;
        }
        return (int) fact;
    }
}

class Solution {
