    public int minOperations(String word1, String word2) {
        W1 = word1; W2 = word2;
        int n = word1.length();
        int[] f = new int[n + 1];
        java.util.Arrays.fill(f, Integer.MAX_VALUE);
        f[0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if (f[j] == Integer.MAX_VALUE) continue;
                int a = calc(j, i - 1, false);
                int b = 1 + calc(j, i - 1, true);
                int t = Math.min(a, b);
                f[i] = Math.min(f[i], f[j] + t);
            }
        }
        return f[n];
    }
}

import java.util.*;

class Solution {
    public static List<Integer> weightedMedianNode(int n, int[][] edges, int[][] queries) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }

        int LOG = (int) Math.ceil(Math.log(n) / Math.log(2)) + 1;
        int[][] parent = new int[LOG][n];
        long[][] upDist = new long[LOG][n];
        int[] depth = new int[n];
        long[] dist = new long[n];
        for (int i = 0; i < LOG; i++) Arrays.fill(parent[i], -1);

        Deque<Integer> stack = new ArrayDeque<>();
        boolean[] visited = new boolean[n];
        stack.push(0);
        visited[0] = true;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            for (int[] nb : adj[node]) {
                int nei = nb[0];
                int w = nb[1];
                if (!visited[nei]) {
                    visited[nei] = true;
                    parent[0][nei] = node;
                    upDist[0][nei] = w;
                    depth[nei] = depth[node] + 1;
                    dist[nei] = dist[node] + w;
                    stack.push(nei);
                }
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 0; v < n; v++) {
                int mid = parent[k - 1][v];
                if (mid != -1) {
                    parent[k][v] = parent[k - 1][mid];
                    upDist[k][v] = upDist[k - 1][v] + upDist[k - 1][mid];
                }
            }
        }

        List<Integer> ans = new ArrayList<>();
        for (int[] q : queries) {
            int u = q[0], v = q[1];
            int w = lca(u, v, LOG, depth, parent);
            long total = dist[u] + dist[v] - 2 * dist[w];
            long target = (total + 1) / 2; // ceil(total/2)
            long du = dist[u] - dist[w];
            if (target <= du) {
                long need = target;
                int cur = u;
                for (int k = LOG - 1; k >= 0; k--) {
                    if (parent[k][cur] != -1 && upDist[k][cur] < need) {
                        need -= upDist[k][cur];
                        cur = parent[k][cur];
                    }
                }
                ans.add(parent[0][cur]);
            } else {
                long upNeeded = total - target;
                int node = climbExact(v, upNeeded, LOG, parent, upDist);
                ans.add(node);
            }
        }
        return ans;
    }

    private static int lca(int a, int b, int LOG, int[] depth, int[][] parent) {
        if (depth[a] < depth[b]) {
            int tmp = a;
            a = b;
            b = tmp;
        }
        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; k--) {
            if (((diff >> k) & 1) == 1) {
                a = parent[k][a];
            }
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (parent[k][a] != -1 && parent[k][a] != parent[k][b]) {
                a = parent[k][a];
                b = parent[k][b];
            }
        }
        return parent[0][a];
    }

    private static int climbExact(int node, long need, int LOG, int[][] parent, long[][] upDist) {
        for (int k = LOG - 1; k >= 0; k--) {
            if (parent[k][node] != -1 && upDist[k][node] <= need) {
                need -= upDist[k][node];
                node = parent[k][node];
            }
        }
        return node;
    }
}

class Solution {
    public int specialTriplets(int[] nums) {
        Map<Integer, Long> right = new HashMap<>();
        Map<Integer, Long> left = new HashMap<>();
        for (int x : nums) right.merge(x, 1L, Long::sum);
        long ans = 0;
        long MOD = 1_000_000_007L;
        for (int x : nums) {
            right.merge(x, -1L, Long::sum);
            int t = 2 * x;
            long l = left.getOrDefault(t, 0L);
            long r = right.getOrDefault(t, 0L);
            ans = (ans + l * r) % MOD;
            left.merge(x, 1L, Long::sum);
        }
        return (int) ans;
    }
}

