class Solution {
    public static int minSwaps(int[] nums) {
        int n = nums.length;
        List<Integer> evenPos = new ArrayList<>();
        List<Integer> oddPos = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (nums[i] % 2 == 0) {
                evenPos.add(i);
            } else {
                oddPos.add(i);
            }
        }

        int evenCnt = evenPos.size();
        int oddCnt = oddPos.size();

        if (Math.abs(evenCnt - oddCnt) > 1) {
            return -1;
        }

        List<String> patterns = new ArrayList<>();
        if (evenCnt >= oddCnt) patterns.add("evenFirst");
        if (oddCnt >= evenCnt) patterns.add("oddFirst");

        long answer = Long.MAX_VALUE;

        for (String pat : patterns) {
            List<Integer> targetEven = new ArrayList<>();

            if (pat.equals("evenFirst")) {
                for (int i = 0; i < n; i += 2) {
                    targetEven.add(i);
                }
            } else {
                for (int i = 1; i < n; i += 2) {
                    targetEven.add(i);
                }
            }

            long swaps = 0;
            for (int i = 0; i < evenCnt; i++) {
                swaps += Math.abs(evenPos.get(i) - targetEven.get(i));
            }

            answer = Math.min(answer, swaps);
        }

        return (int) answer;
    }
}

