public class Solution {
    public long maxArea(int[][] coords) {
        if (coords == null || coords.length < 3) return -1;
        Map<Integer, int[]> xMap = new HashMap<>();
        Map<Integer, int[]> yMap = new HashMap<>();
        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
        int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;

        for (int[] p : coords) {
            int x = p[0];
            int y = p[1];
            minX = Math.min(minX, x);
            maxX = Math.max(maxX, x);
            minY = Math.min(minY, y);
            maxY = Math.max(maxY, y);

            int[] arrX = xMap.get(x);
            if (arrX == null) {
                arrX = new int[]{y, y};
                xMap.put(x, arrX);
            } else {
                arrX[0] = Math.min(arrX[0], y);
                arrX[1] = Math.max(arrX[1], y);
            }

            int[] arrY = yMap.get(y);
            if (arrY == null) {
                arrY = new int[]{x, x};
                yMap.put(y, arrY);
            } else {
                arrY[0] = Math.min(arrY[0], x);
                arrY[1] = Math.max(arrY[1], x);
            }
        }

        long best = 0;

        for (Map.Entry<Integer, int[]> e : xMap.entrySet()) {
            int x = e.getKey();
            int[] minMaxY = e.getValue();
            int base = minMaxY[1] - minMaxY[0];
            if (base <= 0) continue; // need two distinct points on this vertical line
            int height = Math.max(x - minX, maxX - x);
            if (height <= 0) continue;
            long area2 = (long) base * height;
            if (area2 > best) best = area2;
        }

        for (Map.Entry<Integer, int[]> e : yMap.entrySet()) {
            int y = e.getKey();
            int[] minMaxX = e.getValue();
            int base = minMaxX[1] - minMaxX[0];
            if (base <= 0) continue; // need two distinct points on this horizontal line
            int height = Math.max(y - minY, maxY - y);
            if (height <= 0) continue;
            long area2 = (long) base * height;
            if (area2 > best) best = area2;
        }

        return best == 0 ? -1 : best;
    }
}

