class Solution {
    public long maxProduct(int[] nums, int m) {
        int n = nums.length;
        if (m == 1) {
            long ans = Long.MIN_VALUE;
            for (int v : nums) {
                long prod = (long) v * v;
                if (prod > ans) ans = prod;
            }
            return ans;
        }
        int[] prefixMax = new int[n];
        int[] prefixMin = new int[n];
        prefixMax[0] = nums[0];
        prefixMin[0] = nums[0];
        for (int i = 1; i < n; i++) {
            prefixMax[i] = Math.max(prefixMax[i - 1], nums[i]);
            prefixMin[i] = Math.min(prefixMin[i - 1], nums[i]);
        }
        long ans = Long.MIN_VALUE;
        int requiredDist = m - 1;
        for (int j = requiredDist; j < n; j++) {
            int leftIdx = j - requiredDist;
            long maxLeft = prefixMax[leftIdx];
            long minLeft = prefixMin[leftIdx];
            long cur = Math.max(maxLeft * nums[j], minLeft * nums[j]);
            if (cur > ans) ans = cur;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static class Query {
        int l, r, k, idx;
        Query(int l, int r, int k, int idx) {
            this.l = l;
            this.r = r;
            this.k = k;
            this.idx = idx;
        }
    }

    private static void bitAdd(int[] bit, int i, int delta) {
        while (i < bit.length) {
            bit[i] += delta;
            i += i & -i;
        }
    }

    private static int bitFindKth(int[] bit, int k) {
        int idx = 0;
        int mask = 1;
        while (mask < bit.length) mask <<= 1;
        for (mask >>= 1; mask > 0; mask >>= 1) {
            int next = idx + mask;
            if (next < bit.length && bit[next] < k) {
                idx = next;
                k -= bit[next];
            }
        }
        return idx + 1;
    }

    public static int[] kthSmallestPathXor(int[] par, int[] vals, int[][] queries) {
        int n = vals.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            int p = par[i];
            adj[p].add(i);
        }
        int[] pathXor = new int[n];
        int[] tin = new int[n];
        int[] tout = new int[n];
        int[] euler = new int[n];
        int timer = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, 0});
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int state = cur[1];
            if (state == 0) {
                tin[node] = timer;
                euler[timer] = node;
                timer++;
                if (par[node] == -1) pathXor[node] = vals[node];
                else pathXor[node] = pathXor[par[node]] ^ vals[node];
                stack.push(new int[]{node, 1});
                List<Integer> children = adj[node];
                for (int i = children.size() - 1; i >= 0; i--) {
                    stack.push(new int[]{children.get(i), 0});
                }
            } else {
                tout[node] = timer - 1;
            }
        }
        int q = queries.length;
        final int blockSize = Math.max(1, (int) Math.sqrt(n));
        Query[] qObjs = new Query[q];
        for (int i = 0; i < q; i++) {
            int u = queries[i][0];
            int k = queries[i][1];
            qObjs[i] = new Query(tin[u], tout[u], k, i);
        }
        Arrays.sort(qObjs, (a, b) -> {
            int blockA = a.l / blockSize;
            int blockB = b.l / blockSize;
            if (blockA != blockB) return blockA - blockB;
            if ((blockA & 1) == 0) return a.r - b.r;
            return b.r - a.r;
        });
        final int MAX_VAL = 1 << 17;
        int bitSize = MAX_VAL + 2;
        int[] bit = new int[bitSize];
        int[] freq = new int[MAX_VAL];
        int distinctCount = 0;
        int[] ans = new int[q];
        int curL = 0, curR = -1;
        for (Query qq : qObjs) {
            while (curL > qq.l) {
                curL--;
                int node = euler[curL];
                int v = pathXor[node];
                if (freq[v] == 0) {
                    bitAdd(bit, v + 1, 1);
                    distinctCount++;
                }
                freq[v]++;
            }
            while (curR < qq.r) {
                curR++;
                int node = euler[curR];
                int v = pathXor[node];
                if (freq[v] == 0) {
                    bitAdd(bit, v + 1, 1);
                    distinctCount++;
                }
                freq[v]++;
            }
            while (curL < qq.l) {
                int node = euler[curL];
                int v = pathXor[node];
                freq[v]--;
                if (freq[v] == 0) {
                    bitAdd(bit, v + 1, -1);
                    distinctCount--;
                }
                curL++;
            }
            while (curR > qq.r) {
                int node = euler[curR];
                int v = pathXor[node];
                freq[v]--;
                if (freq[v] == 0) {
                    bitAdd(bit, v + 1, -1);
                    distinctCount--;
                }
                curR--;
            }
            if (qq.k > distinctCount) {
                ans[qq.idx] = -1;
            } else {
                int idx = bitFindKth(bit, qq.k);
                ans[qq.idx] = idx - 1;
            }
        }
        return ans;
    }
}

import java.util.*;
class Solution {
    public double minimumTime(int n, int k, int m, int[] time, double[] mul) {
        int FULL = (1 << n) - 1;
        double[][][] dist = new double[1 << n][2][m];
        for (double[][] a : dist) for (double[] b : a) Arrays.fill(b, Double.POSITIVE_INFINITY);
        dist[FULL][0][0] = 0.0;
        PriorityQueue<double[]> pq = new PriorityQueue<>((a, b) -> Double.compare(a[0], b[0]));
        pq.offer(new double[]{0.0, FULL, 0, 0});
        while (!pq.isEmpty()) {
            double[] top = pq.poll();
            double cost = top[0];
            int remaining = (int) top[1];
            int direction = (int) top[2];
            int stage = (int) top[3];
            if (cost > dist[remaining][direction][stage] + 1e-9) continue;
            if (direction == 1 && remaining == 0) return cost;
            if (direction == 0) {
                List<Integer> people = new ArrayList<>();
                for (int i = 0; i < n; i++) if ((remaining & (1 << i)) != 0) people.add(i);
                int maxSz = Math.min(k, people.size());
                for (int sz = 1; sz <= maxSz; sz++) {
                    for (int[] combo : combinations(people.size(), sz)) {
                        double gmax = 0;
                        int newRemaining = remaining;
                        for (int idx : combo) {
                            int i = people.get(idx);
                            gmax = Math.max(gmax, time[i]);
                            newRemaining &= ~(1 << i);
                        }
                        double gtime = gmax * mul[stage];
                        int newStage = (int) ((stage + Math.floor(gtime)) % m);
                        double newCost = cost + gtime;
                        if (newCost < dist[newRemaining][1][newStage] - 1e-9) {
                            dist[newRemaining][1][newStage] = newCost;
                            pq.offer(new double[]{newCost, newRemaining, 1, newStage});
                        }
                    }
                }
            } else {
                for (int i = 0; i < n; i++) {
                    if ((remaining & (1 << i)) != 0) continue;
                    double rtime = time[i] * mul[stage];
                    int newRemaining = remaining | (1 << i);
                    int newStage = (int) ((stage + Math.floor(rtime)) % m);
                    double newCost = cost + rtime;
                    if (newCost < dist[newRemaining][0][newStage] - 1e-9) {
                        dist[newRemaining][0][newStage] = newCost;
                        pq.offer(new double[]{newCost, newRemaining, 0, newStage});
                    }
                }
            }
        }
        return -1.0;
    }
    private List<int[]> combinations(int n, int r) {
        List<int[]> result = new ArrayList<>();
        int[] combo = new int[r];
        for (int i = 0; i < r; i++) combo[i] = i;
        while (true) {
            result.add(combo.clone());
            int i = r - 1;
            while (i >= 0 && combo[i] == i + n - r) i--;
            if (i < 0) break;
            combo[i]++;
            for (int j = i + 1; j < r; j++) combo[j] = combo[j-1] + 1;
        }
        return result;
    }

class Solution {
    static final int MAXV = 100000;
    static boolean[] IS_PRIME_PG = buildSieve();

    static boolean[] buildSieve() {
        boolean[] isP = new boolean[MAXV + 1];
        Arrays.fill(isP, true);
        isP[0] = isP[1] = false;
        for (int i = 2; (long) i * i <= MAXV; i++)
            if (isP[i]) for (int j = i * i; j <= MAXV; j += i) isP[j] = false;
        return isP;
    }

    public long primeSubarray(int[] nums, int k) {
        int n = nums.length;
        int[] marks = new int[n];
        for (int i = 0; i < n; i++) marks[i] = (nums[i] <= MAXV && IS_PRIME_PG[nums[i]]) ? nums[i] : 0;
        TreeMap<Integer, Integer> ms = new TreeMap<>(); // multiset via counted TreeMap
        int j1 = 0, cnt = 0, j2 = 0;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int x = marks[i];
            if (x > 0) { cnt++; ms.merge(x, 1, Integer::sum); }
            while (!ms.isEmpty() && ms.lastKey() - ms.firstKey() > k) {
                int v = marks[j1];
                if (v > 0) {
                    int c = ms.get(v);
                    if (c == 1) ms.remove(v); else ms.put(v, c - 1);
                }
                j1++;
            }
            while (cnt > 1) {
                if (marks[j2] > 0) cnt--;
                j2++;
            }
            ans += j2 - j1;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static boolean hasPrimeFrequency(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        for (int count : freq.values()) {
            if (isPrime(count)) return true;
        }
        return false;
    }

    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }
}

