public class Solution {
    public static int[] recoverDenominations(int[] numWays) {
        int n = numWays.length;
        long[] ways = new long[n + 1];
        ways[0] = 1;
        List<Integer> denoms = new ArrayList<>();

        for (int i = 1; i <= n; i++) {
            long cur = ways[i];
            long target = numWays[i - 1];
            if (cur == target) {
                continue;
            }
            if (cur < target) {
                if (target - cur != 1) {
                    return new int[0];
                }
                denoms.add(i);
                for (int j = i; j <= n; j++) {
                    ways[j] += ways[j - i];
                }
                if (ways[i] != target) {
                    return new int[0];
                }
            } else {
                return new int[0];
            }
        }

        for (int i = 1; i <= n; i++) {
            if (ways[i] != numWays[i - 1]) {
                return new int[0];
            }
        }

        int[] result = new int[denoms.size()];
        for (int i = 0; i < denoms.size(); i++) {
            result[i] = denoms.get(i);
        }
        return result;
    }
}

