class Solution {
    public static int minNodesToIncrease(int n, int[][] edges, int[] cost) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) children[i] = new ArrayList<>();

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] order = new int[n];
        int orderIdx = 0;

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        parent[0] = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            order[orderIdx++] = node;
            for (int nb : adj[node]) {
                if (nb == parent[node]) continue;
                parent[nb] = node;
                children[node].add(nb);
                stack.push(nb);
            }
        }

        int[] maxSum = new int[n];
        int[] touches = new int[n];

        for (int i = orderIdx - 1; i >= 0; i--) {
            int node = order[i];
            List<Integer> childs = children[node];
            if (childs.isEmpty()) {
                maxSum[node] = cost[node];
                touches[node] = 0;
            } else {
                int maxChildSum = Integer.MIN_VALUE;
                for (int ch : childs) {
                    if (maxSum[ch] > maxChildSum) maxChildSum = maxSum[ch];
                }
                int total = 0;
                for (int ch : childs) {
                    total += touches[ch];
                    if (maxSum[ch] < maxChildSum) total += 1;
                }
                maxSum[node] = cost[node] + maxChildSum;
                touches[node] = total;
            }
        }

        return touches[0];
    }
}

