class Solution {
    public static List<String> partitionString(String s) {
        Set<String> used = new HashSet<>();
        List<String> result = new ArrayList<>();
        int n = s.length();
        int i = 0;
        while (i < n) {
            int j = i;
            String cur = null;
            while (j < n) {
                cur = s.substring(i, j + 1);
                if (!used.contains(cur)) {
                    break;
                }
                j++;
            }
            if (j == n) {
                break;
            }
            used.add(cur);
            result.add(cur);
            i = j + 1;
        }
        return result;
    }
}

