public class Solution {
    public int[] longestCommonPrefixAfterRemoval(String[] words) {
        int n = words.length;
        int[] answer = new int[n];
        if (n == 1) {
            answer[0] = 0;
            return answer;
        }

        int m = n - 1; // number of original adjacent pairs
        int[] lcp = new int[m];
        for (int i = 0; i < m; i++) {
            lcp[i] = commonPrefix(words[i], words[i + 1]);
        }

        int[] preMax = new int[m];
        int[] sufMax = new int[m];
        preMax[0] = lcp[0];
        for (int i = 1; i < m; i++) {
            preMax[i] = Math.max(preMax[i - 1], lcp[i]);
        }
        sufMax[m - 1] = lcp[m - 1];
        for (int i = m - 2; i >= 0; i--) {
            sufMax[i] = Math.max(sufMax[i + 1], lcp[i]);
        }

        for (int i = 0; i < n; i++) {
            int best = 0;
            if (i - 2 >= 0) {
                best = Math.max(best, preMax[i - 2]);
            }
            if (i + 1 <= m - 1) {
                best = Math.max(best, sufMax[i + 1]);
            }
            if (i - 1 >= 0 && i + 1 <= n - 1) {
                int newLcp = commonPrefix(words[i - 1], words[i + 1]);
                best = Math.max(best, newLcp);
            }
            answer[i] = best;
        }

        return answer;
    }

    private int commonPrefix(String a, String b) {
        int len = Math.min(a.length(), b.length());
        int i = 0;
        while (i < len && a.charAt(i) == b.charAt(i)) {
            i++;
        }
        return i;
    }
}

import java.util.*;

public class Solution {
    public static int maxStability(int n, int[][] edges, int k) {
        int m = edges.length;
        int[] us = new int[m];
        int[] vs = new int[m];
        int[] ss = new int[m];
        int[] musts = new int[m];
        int maxS = 0;
        for (int i = 0; i < m; i++) {
            us[i] = edges[i][0];
            vs[i] = edges[i][1];
            ss[i] = edges[i][2];
            musts[i] = edges[i][3];
            if (ss[i] > maxS) maxS = ss[i];
        }
        int low = 0;
        int high = maxS * 2;
        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            if (can(mid, n, us, vs, ss, musts, k)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return can(low, n, us, vs, ss, musts, k) ? low : -1;
    }

    private static boolean can(int target, int n, int[] us, int[] vs, int[] ss, int[] musts, int k) {
        DSU dsu = new DSU(n);
        int mustCount = 0;
        for (int i = 0; i < us.length; i++) {
            if (musts[i] == 1) {
                mustCount++;
                if (ss[i] < target) return false;
                if (!dsu.union(us[i], vs[i])) return false;
            }
        }
        if (mustCount > n - 1) return false;
        int usedUpgrades = 0;
        // First use optional edges that already satisfy target
        for (int i = 0; i < us.length; i++) {
            if (musts[i] == 0 && ss[i] >= target) {
                dsu.union(us[i], vs[i]);
            }
        }
        // Then use optional edges that can be upgraded
        for (int i = 0; i < us.length; i++) {
            if (musts[i] == 0 && ss[i] < target && ss[i] * 2 >= target) {
                if (dsu.union(us[i], vs[i])) {
                    usedUpgrades++;
                    if (usedUpgrades > k) return false;
                }
            }
        }
        return dsu.getCount() == 1 && usedUpgrades <= k;
    }

    private static class DSU {
        int[] parent;
        int[] size;
        int count;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            count = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return false;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
            count--;
            return true;
        }

        int getCount() {
            return count;
        }
    }
}

import java.util.*;

class Solution {
    public static int minMaxXor(int[] nums, int k) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] ^ nums[i];
        }
        int low = 0;
        int high = Integer.MAX_VALUE;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (can(pref, n, mid, k)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean can(int[] pref, int n, int limit, int k) {
        boolean[][] dp = new boolean[n + 1][k + 1];
        dp[0][0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                int subXor = pref[i] ^ pref[j];
                if (subXor <= limit) {
                    for (int cnt = 0; cnt < k; cnt++) {
                        if (dp[j][cnt]) {
                            dp[i][cnt + 1] = true;
                        }
                    }
                }
            }
        }
        return dp[n][k];
    }
}

class Solution {
    public long minCost(int m, int n, int[][] waitCost) {
        long[][] f = new long[m][n];
        f[0][0] = 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                long entry = (long)(i+1)*(j+1);
                long best = Long.MAX_VALUE;
                if (i > 0) {
                    long p = f[i-1][j];
                    if (!(i-1 == 0 && j == 0)) p += waitCost[i-1][j];
                    best = Math.min(best, p);
                }
                if (j > 0) {
                    long p = f[i][j-1];
                    if (!(i == 0 && j-1 == 0)) p += waitCost[i][j-1];
                    best = Math.min(best, p);
                }
                f[i][j] = entry + best;
            }
        }
        return f[m-1][n-1];
    }
}

