class Solution {
    private static class Edge {
        int to;
        long start;
        long end;
        Edge(int to, long start, long end) {
            this.to = to;
            this.start = start;
            this.end = end;
        }
    }

    public long minimumTime(int n, int[][] edges) {
        List<List<Edge>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            long s = e[2];
            long t = e[3];
            adj.get(u).add(new Edge(v, s, t));
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[0] = 0;

        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long curTime = cur[0];
            int u = (int) cur[1];
            if (curTime != dist[u]) continue;
            if (u == n - 1) break;
            for (Edge e : adj.get(u)) {
                if (curTime > e.end) continue; // edge already closed
                long wait = Math.max(0, e.start - curTime);
                long depart = curTime + wait;
                if (depart > e.end) continue; // cannot depart within window
                long arrival = depart + 1;
                if (arrival < dist[e.to]) {
                    dist[e.to] = arrival;
                    pq.offer(new long[]{arrival, e.to});
                }
            }
        }

        return dist[n - 1] == INF ? -1 : dist[n - 1];
    }
}

