class Solution {
    public int minimumStabilityFactor(int[] nums, int maxC) {
        int n = nums.length;
        if (maxC >= n) return 0;
        int LOG = 32 - Integer.numberOfLeadingZeros(n);
        int[][] st = new int[LOG][n];
        for (int i = 0; i < n; i++) st[0][i] = nums[i];
        for (int k = 1; k < LOG; k++) {
            int len = 1 << k;
            int half = len >> 1;
            for (int i = 0; i + len <= n; i++) {
                st[k][i] = gcd(st[k - 1][i], st[k - 1][i + half]);
            }
        }
        int[] log = new int[n + 1];
        for (int i = 2; i <= n; i++) log[i] = log[i >> 1] + 1;

        int low = 0, high = n;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (canAchieve(mid, nums, maxC, st, log)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private boolean canAchieve(int L, int[] nums, int maxC, int[][] st, int[] log) {
        int n = nums.length;
        int window = L + 1;
        if (window > n) return true;
        int needed = 0;
        int lastSelected = -1;
        for (int i = 0; i + window - 1 < n; i++) {
            int l = i;
            int r = i + window - 1;
            if (rangeGcd(l, r, st, log) >= 2) {
                if (lastSelected < l) {
                    needed++;
                    if (needed > maxC) return false;
                    lastSelected = r; // select rightmost point of this interval
                }
            }
        }
        return needed <= maxC;
    }

    private int rangeGcd(int l, int r, int[][] st, int[] log) {
        int len = r - l + 1;
        int k = log[len];
        int left = st[k][l];
        int right = st[k][r - (1 << k) + 1];
        return gcd(left, right);
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.*;

class Solution {
    public int minimumTime(int n, int[][] edges, int k) {
        // Sort edges by time in descending order
        Arrays.sort(edges, (a, b) -> Integer.compare(b[2], a[2]));
        DSU dsu = new DSU(n);
        int components = n;
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int time = e[2];
            if (dsu.find(u) != dsu.find(v)) {
                dsu.union(u, v);
                components--;
                if (components < k) {
                    return time;
                }
            }
        }
        // If we never dropped below k components, answer is 0
        return 0;
    }

    private static class DSU {
        int[] parent;
        int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int xr = find(x);
            int yr = find(y);
            if (xr == yr) return;
            if (rank[xr] < rank[yr]) {
                parent[xr] = yr;
            } else if (rank[xr] > rank[yr]) {
                parent[yr] = xr;
            } else {
                parent[yr] = xr;
                rank[xr]++;
            }
        }
    }
}

