class Solution {
    public static int minMovesGrid(int sx, int sy, int tx, int ty) {
        if (sx == tx && sy == ty) return 0;
        Queue<int[]> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        queue.offer(new int[]{sx, sy, 0});
        visited.add(sx + "," + sy);
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];
            int d = cur[2];
            int m = Math.max(x, y);
            int[][] candidates = {{x + m, y}, {x, y + m}};
            for (int[] cand : candidates) {
                int nx = cand[0];
                int ny = cand[1];
                if (nx > tx || ny > ty) continue;
                if (nx == tx && ny == ty) return d + 1;
                String key = nx + "," + ny;
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.offer(new int[]{nx, ny, d + 1});
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public static List<Integer> powerGridMaintenance(int c, List<int[]> connections, List<int[]> queries) {
        int[] parent = new int[c + 1];
        int[] rank = new int[c + 1];
        for (int i = 1; i <= c; i++) parent[i] = i;
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };
        java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
            int ra = find.applyAsInt(a);
            int rb = find.applyAsInt(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
        };
        for (int[] edge : connections) {
            union.accept(edge[0], edge[1]);
        }
        TreeSet<Integer>[] sets = new TreeSet[c + 1];
        for (int i = 1; i <= c; i++) {
            int r = find.applyAsInt(i);
            if (sets[r] == null) sets[r] = new TreeSet<>();
            sets[r].add(i);
        }
        List<Integer> ans = new ArrayList<>();
        for (int[] query : queries) {
            int type = query[0];
            int x = query[1];
            int r = find.applyAsInt(x);
            if (type == 2) {
                if (sets[r] != null) sets[r].remove(x);
            } else {
                if (sets[r] == null) {
                    ans.add(-1);
                } else {
                    Integer val = sets[r].ceiling(x);
                    ans.add(val == null ? -1 : val);
                }
            }
        }
        return ans;
    }
}

