public class Solution {
    public String processString(String s) {
        StringBuilder out = new StringBuilder();
        StringBuilder deleted = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch >= 'a' && ch <= 'z') {
                out.append(ch);
            } else if (ch == '#') {
                if (out.length() > 0) {
                    char c = out.charAt(out.length() - 1);
                    out.deleteCharAt(out.length() - 1);
                    deleted.append(c);
                }
            } else if (ch == '%') {
                if (deleted.length() > 0) {
                    char c = deleted.charAt(deleted.length() - 1);
                    deleted.deleteCharAt(deleted.length() - 1);
                    out.append(c);
                }
            } else if (ch == '*') {
                deleted.setLength(0);
            }
        }
        return out.toString();
    }
}

import java.lang.*;

class Solution {
    public static char getKthChar(String s, int k) {
        int n = s.length();
        int[] len = new int[n + 1];
        len[0] = 0;
        for (int i = 1; i <= n; i++) {
            char ch = s.charAt(i - 1);
            int prev = len[i - 1];
            if (ch >= 'a' && ch <= 'z') {
                len[i] = prev + 1;
            } else if (ch == '*') {
                len[i] = prev > 0 ? prev - 1 : 0;
            } else if (ch == '#') {
                len[i] = prev * 2;
            } else if (ch == '%') {
                len[i] = prev;
            }
        }
        if (k >= len[n]) return '.';
        for (int i = n; i > 0; i--) {
            char ch = s.charAt(i - 1);
            int prev = len[i - 1];
            if (ch >= 'a' && ch <= 'z') {
                if (k == prev) return ch;
            } else if (ch == '*') {
                // nothing
            } else if (ch == '#') {
                if (k >= prev) k = k - prev;
            } else if (ch == '%') {
                k = prev - 1 - k;
            }
        }
        return '.';
    }
}

