class Solution {
    public int minimizeMaximumComponentCost(int n, int[][] edges, int k) {
        if (k >= n) return 0;
        Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
        DSU dsu = new DSU(n);
        int components = n;
        int answer = 0;
        for (int[] e : edges) {
            if (components <= k) break;
            int u = e[0];
            int v = e[1];
            int w = e[2];
            if (dsu.find(u) != dsu.find(v)) {
                dsu.union(u, v);
                answer = w;
                components--;
            }
        }
        return answer;
    }

    private static class DSU {
        int[] parent;
        int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        }
    }
}

import java.util.*;

class Solution {
    public static int longestPalindromePath(int n, int[][] edges, String label) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }
        int maxMask = 1 << n;
        int[][][] dp = new int[maxMask][n][n];
        for (int mask = 0; mask < maxMask; mask++) {
            for (int i = 0; i < n; i++) {
                Arrays.fill(dp[mask][i], -1);
            }
        }
        for (int i = 0; i < n; i++) {
            int mask = 1 << i;
            dp[mask][i][i] = 1;
        }
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            if (label.charAt(u) == label.charAt(v)) {
                int mask = (1 << u) | (1 << v);
                dp[mask][u][v] = Math.max(dp[mask][u][v], 2);
                dp[mask][v][u] = Math.max(dp[mask][v][u], 2);
            }
        }
        for (int mask = 0; mask < maxMask; mask++) {
            for (int l = 0; l < n; l++) {
                for (int r = 0; r < n; r++) {
                    int cur = dp[mask][l][r];
                    if (cur == -1) continue;
                    for (int u : adj[l]) {
                        if ((mask & (1 << u)) != 0) continue;
                        for (int v : adj[r]) {
                            if ((mask & (1 << v)) != 0) continue;
                            if (u == v) continue;
                            if (label.charAt(u) != label.charAt(v)) continue;
                            int newMask = mask | (1 << u) | (1 << v);
                            int newLen = cur + 2;
                            if (dp[newMask][u][v] < newLen) {
                                dp[newMask][u][v] = newLen;
                            }
                        }
                    }
                }
            }
        }
        int ans = 0;
        for (int mask = 0; mask < maxMask; mask++) {
            for (int l = 0; l < n; l++) {
                for (int r = 0; r < n; r++) {
                    ans = Math.max(ans, dp[mask][l][r]);
                }
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int countIslands(int[][] grid, int k) {
        int rows = grid.length;
        if (rows == 0) return 0;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        int islandCount = 0;
        int[][] dirs = {
            {1, 0},
            {-1, 0},
            {0, 1},
            {0, -1}
        };
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > 0 && !visited[r][c]) {
                    int sum = 0;
                    Deque<int[]> stack = new ArrayDeque<>();
                    stack.push(new int[]{r, c});
                    visited[r][c] = true;
                    while (!stack.isEmpty()) {
                        int[] cur = stack.pop();
                        int cr = cur[0];
                        int cc = cur[1];
                        sum += grid[cr][cc];
                        for (int[] dir : dirs) {
                            int nr = cr + dir[0];
                            int nc = cc + dir[1];
                            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] > 0 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                    if (sum % k == 0) islandCount++;
                }
            }
        }
        return islandCount;
    }
}

class Solution {
    public long maxScore(int[][] edges, boolean[] online, long k) {
        int n = online.length;
        List<int[]>[] adj = new List[n];
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) { adj[e[0]].add(new int[]{e[1], e[2]}); indeg[e[1]]++; }
        int[] order = new int[n];
        int oi = 0;
        Deque<Integer> q = new ArrayDeque<>();
        int[] indegCopy = indeg.clone();
        for (int i = 0; i < n; i++) if (indegCopy[i] == 0) q.add(i);
        while (!q.isEmpty()) {
            int u = q.poll();
            order[oi++] = u;
            for (int[] e : adj[u]) if (--indegCopy[e[0]] == 0) q.add(e[0]);
        }
        TreeSet<Integer> costs = new TreeSet<>();
        for (int[] e : edges) costs.add(e[2]);
        List<Integer> sortedCosts = new ArrayList<>(costs);
        int lo = 0, hi = sortedCosts.size()-1, best = -1;
        while (lo <= hi) {
            int mid = (lo+hi)/2;
            int T = sortedCosts.get(mid);
            if (feasible(n, order, adj, online, T, k)) { best = T; lo = mid+1; } else { hi = mid-1; }
        }
        return best;
    }
    private boolean feasible(int n, int[] order, List<int[]>[] adj, boolean[] online, int T, long k) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE/2);
        dist[0] = 0;
        for (int u : order) {
            if (dist[u] >= Long.MAX_VALUE/2) continue;
            if (u != 0 && !online[u]) continue;
            for (int[] e : adj[u]) {
                int v = e[0], cost = e[1];
                if (cost < T) continue;
                if (v != n-1 && !online[v]) continue;
                if (dist[u] + cost < dist[v]) dist[v] = dist[u] + cost;
            }
        }
        return dist[n-1] <= k;
    }
}

import java.util.*;

public class Solution {
    private static final int MAX_BITS = 60;
    private static final long[][] COMB = new long[MAX_BITS + 1][MAX_BITS + 1];
    private static final List<Integer>[] DEPTH_TO_VALUES = new List[6];
    private static final int[] DEPTH = new int[MAX_BITS + 1];

    static {
        for (int i = 0; i <= MAX_BITS; i++) {
            COMB[i][0] = COMB[i][i] = 1L;
            for (int j = 1; j < i; j++) {
                COMB[i][j] = COMB[i - 1][j - 1] + COMB[i - 1][j];
            }
        }
        for (int i = 0; i < DEPTH_TO_VALUES.length; i++) {
            DEPTH_TO_VALUES[i] = new ArrayList<>();
        }
        DEPTH[1] = 0;
        for (int i = 2; i <= MAX_BITS; i++) {
            int pc = Integer.bitCount(i);
            DEPTH[i] = 1 + DEPTH[pc];
        }
        for (int i = 1; i <= MAX_BITS; i++) {
            int d = DEPTH[i];
            if (d < DEPTH_TO_VALUES.length) {
                DEPTH_TO_VALUES[d].add(i);
            }
        }
    }

    private static long countWithPopcount(long n, int t) {
        if (t < 0) return 0L;
        long ans = 0L;
        int ones = 0;
        for (int i = MAX_BITS; i >= 0; i--) {
            if (((n >> i) & 1L) == 1L) {
                int need = t - ones;
                if (need >= 0 && i >= need) {
                    ans += COMB[i][need];
                }
                ones++;
                if (ones > t) break;
            }
        }
        if (ones == t) ans++;
        return ans;
    }

    public static long countIntegers(long n, int k) {
        if (k == 0) {
            return n >= 1 ? 1L : 0L;
        }
        if (k - 1 >= DEPTH_TO_VALUES.length) return 0L;
        long ans = 0L;
        for (int c : DEPTH_TO_VALUES[k - 1]) {
            ans += countWithPopcount(n, c);
        }
        if (k == 1 && n >= 1) {
            ans -= 1L; // exclude the number 1
        }
        return ans;
    }
}

