class Solution {
    public static boolean isDivisibleBySumAndProduct(int n) {
        int sum = 0;
        int product = 1;
        int temp = n;
        while (temp > 0) {
            int digit = temp % 10;
            sum += digit;
            product *= digit;
            temp = temp / 10;
        }
        int total = sum + product;
        return n % total == 0;
    }
}

import java.util.Arrays;

class Solution {
    public static int splitArrayByPrimeIndices(int[] nums) {
        int n = nums.length;
        boolean[] isPrime = new boolean[n];
        if (n > 2) {
            boolean[] primeFlag = new boolean[n];
            Arrays.fill(primeFlag, true);
            primeFlag[0] = false;
            primeFlag[1] = false;
            for (int i = 2; i * i < n; i++) {
                if (primeFlag[i]) {
                    for (int j = i * i; j < n; j += i) {
                        primeFlag[j] = false;
                    }
                }
            }
            for (int i = 2; i < n; i++) {
                if (primeFlag[i]) {
                    isPrime[i] = true;
                }
            }
        }
        long sumPrime = 0;
        long sumNonPrime = 0;
        for (int i = 0; i < n; i++) {
            if (isPrime[i]) {
                sumPrime += nums[i];
            } else {
                sumNonPrime += nums[i];
            }
        }
        long diff = sumPrime - sumNonPrime;
        if (diff < 0) diff = -diff;
        return (int) diff;
    }
}

