class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countTrapezoids(int[][] points) {
        Map<Integer, Integer> yCount = new HashMap<>();
        for (int[] p : points) {
            int y = p[1];
            yCount.put(y, yCount.getOrDefault(y, 0) + 1);
        }

        List<Long> combos = new ArrayList<>();
        for (int cnt : yCount.values()) {
            if (cnt >= 2) {
                long c = cnt;
                long comb = (c * (c - 1) / 2) % MOD;
                combos.add(comb);
            }
        }

        long ans = 0;
        long prefix = 0;
        for (long val : combos) {
            ans = (ans + val * prefix) % MOD;
            prefix = (prefix + val) % MOD;
        }

        return (int) ans;
    }
}

import java.util.*;

class Solution {
    private static class Fenwick {
        private final int n;
        private final int[] bit;
        Fenwick(int n) {
            this.n = n;
            this.bit = new int[n + 1];
        }
        void add(int idx, int delta) {
            for (int i = idx + 1; i <= n; i += i & -i) {
                bit[i] += delta;
            }
        }
        int sumPrefix(int idx) {
            int res = 0;
            for (int i = idx + 1; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
        int rangeSum(int l, int r) {
            if (l > r) return 0;
            return sumPrefix(r) - (l == 0 ? 0 : sumPrefix(l - 1));
        }
    }

    private int popDepth(long x) {
        int d = 0;
        while (x != 1) {
            x = Long.bitCount(x);
            d++;
        }
        return d;
    }

    public int[] numberOfIntegers(long[] nums, int[][] queries) {
        int n = nums.length;
        Fenwick[] trees = new Fenwick[6];
        for (int k = 0; k < 6; k++) {
            trees[k] = new Fenwick(n);
        }
        int[] depthArr = new int[n];
        for (int i = 0; i < n; i++) {
            int d = popDepth(nums[i]);
            depthArr[i] = d;
            trees[d].add(i, 1);
        }

        List<Integer> answers = new ArrayList<>();
        for (int[] q : queries) {
            int type = q[0];
            if (type == 1) {
                int l = q[1];
                int r = q[2];
                int k = q[3];
                int cnt = trees[k].rangeSum(l, r);
                answers.add(cnt);
            } else { // type == 2
                int idx = q[1];
                long val = q[2];
                int oldDepth = depthArr[idx];
                int newDepth = popDepth(val);
                if (oldDepth != newDepth) {
                    trees[oldDepth].add(idx, -1);
                    trees[newDepth].add(idx, 1);
                    depthArr[idx] = newDepth;
                }
                nums[idx] = val;
            }
        }

        int[] result = new int[answers.size()];
        for (int i = 0; i < result.length; i++) {
            result[i] = answers.get(i);
        }
        return result;
    }
}

