class Solution {
    public static long countNumberOfTrapezoids(int[][] points) {
        int n = points.length;
        Map<String, SlopeEntry> slopeMap = new HashMap<>();
        Map<String, Integer> midMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int xi = points[i][0];
            int yi = points[i][1];
            for (int j = i + 1; j < n; j++) {
                int xj = points[j][0];
                int yj = points[j][1];
                long dx = (long) xj - xi;
                long dy = (long) yj - yi;
                long g = gcd(Math.abs(dx), Math.abs(dy));
                dx /= g;
                dy /= g;
                if (dx < 0) {
                    dx = -dx;
                    dy = -dy;
                } else if (dx == 0 && dy < 0) {
                    dy = -dy;
                }
                String slopeKey = dy + "/" + dx;
                long c = dy * xi - dx * yi;
                String lineKey = slopeKey + "/" + c;
                String midKey = (xi + xj) + "," + (yi + yj);
                midMap.put(midKey, midMap.getOrDefault(midKey, 0) + 1);

                SlopeEntry slopeEntry = slopeMap.get(slopeKey);
                if (slopeEntry == null) {
                    slopeEntry = new SlopeEntry();
                    slopeMap.put(slopeKey, slopeEntry);
                }
                slopeEntry.total++;

                slopeEntry.pointDeg.put(i, slopeEntry.pointDeg.getOrDefault(i, 0) + 1);
                slopeEntry.pointDeg.put(j, slopeEntry.pointDeg.getOrDefault(j, 0) + 1);

                LineEntry lineEntry = slopeEntry.lineMap.get(lineKey);
                if (lineEntry == null) {
                    lineEntry = new LineEntry();
                    slopeEntry.lineMap.put(lineKey, lineEntry);
                }
                lineEntry.count++;
                lineEntry.pointDegLine.put(i, lineEntry.pointDegLine.getOrDefault(i, 0) + 1);
                lineEntry.pointDegLine.put(j, lineEntry.pointDegLine.getOrDefault(j, 0) + 1);
            }
        }

        long trapezoidPairs = 0;
        for (SlopeEntry slopeEntry : slopeMap.values()) {
            long m = slopeEntry.total;
            long totalPairs = m * (m - 1) / 2;

            long sharePoint = 0;
            for (int deg : slopeEntry.pointDeg.values()) {
                sharePoint += (long) deg * (deg - 1) / 2;
            }

            long sameLinePairs = 0;
            long sameLineSharePoint = 0;
            for (LineEntry lineEntry : slopeEntry.lineMap.values()) {
                long t = lineEntry.count;
                sameLinePairs += t * (t - 1) / 2;
                for (int degL : lineEntry.pointDegLine.values()) {
                    sameLineSharePoint += (long) degL * (degL - 1) / 2;
                }
            }

            long valid = totalPairs - sharePoint - sameLinePairs + sameLineSharePoint;
            trapezoidPairs += valid;
        }

        long parallelogramCount = 0;
        for (int cnt : midMap.values()) {
            if (cnt > 1) {
                parallelogramCount += (long) cnt * (cnt - 1) / 2;
            }
        }

        return trapezoidPairs - parallelogramCount;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static class SlopeEntry {
        long total = 0;
        Map<Integer, Integer> pointDeg = new HashMap<>();
        Map<String, LineEntry> lineMap = new HashMap<>();
    }

    private static class LineEntry {
        long count = 0;
        Map<Integer, Integer> pointDegLine = new HashMap<>();
    }
}

