class Solution {
    public static long maxLCT(String s) {
        int n = s.length();
        long[] prefixL = new long[n + 1];
        long[] prefixLC = new long[n + 1];
        long[] suffixT = new long[n + 1];
        long[] suffixCT = new long[n + 1];

        long cntL = 0, cntLC = 0;
        for (int i = 0; i < n; i++) {
            prefixL[i] = cntL;
            prefixLC[i] = cntLC;
            char ch = s.charAt(i);
            if (ch == 'L') {
                cntL++;
            } else if (ch == 'C') {
                cntLC += cntL;
            }
        }
        prefixL[n] = cntL;
        prefixLC[n] = cntLC;

        long cntT = 0, cntCT = 0;
        for (int i = n - 1; i >= 0; i--) {
            suffixT[i + 1] = cntT;
            suffixCT[i + 1] = cntCT;
            char ch = s.charAt(i);
            if (ch == 'T') {
                cntT++;
            } else if (ch == 'C') {
                cntCT += cntT;
            }
        }
        suffixT[0] = cntT;
        suffixCT[0] = cntCT;

        long original = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'C') {
                original += prefixL[i] * suffixT[i + 1];
            }
        }

        long bestInc = 0;
        for (int i = 0; i <= n; i++) {
            long incL = suffixCT[i];
            if (incL > bestInc) bestInc = incL;
            long incT = prefixLC[i];
            if (incT > bestInc) bestInc = incT;
            long incC = prefixL[i] * suffixT[i];
            if (incC > bestInc) bestInc = incC;
        }

        return original + bestInc;
    }
}

import java.util.*;
class Solution {
    public static int minJumpsPrimeTeleport(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;
        int maxVal = 0;
        for (int v : nums) maxVal = Math.max(maxVal, v);
        int[] spf = new int[maxVal+1];
        for (int i = 2; i <= maxVal; i++) {
            if (spf[i] == 0) {
                spf[i] = i;
                if ((long)i*i <= maxVal) for (int j = i*i; j <= maxVal; j += i) if (spf[j]==0) spf[j] = i;
            }
        }
        Map<Integer, List<Integer>> primeToIndices = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            Set<Integer> facs = new HashSet<>();
            while (x > 1) {
                int p = spf[x] != 0 ? spf[x] : x;
                facs.add(p);
                while (x % p == 0) x /= p;
            }
            for (int p : facs) primeToIndices.computeIfAbsent(p, k -> new ArrayList<>()).add(i);
        }
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        while (!q.isEmpty()) {
            int cur = q.poll();
            int curDist = dist[cur];
            if (cur == n-1) return curDist;
            for (int nxt : new int[]{cur-1, cur+1}) {
                if (nxt >= 0 && nxt < n && dist[nxt] == -1) { dist[nxt] = curDist+1; q.add(nxt); }
            }
            if (nums[cur] > 1 && spf[nums[cur]] == nums[cur]) {
                int p = nums[cur];
                List<Integer> lst = primeToIndices.getOrDefault(p, new ArrayList<>());
                for (int nxt : lst) if (dist[nxt] == -1) { dist[nxt] = curDist+1; q.add(nxt); }
                lst.clear();
            }
        }
        return -1;
    }
}
