import java.util.*;

class Solution {
    public static int maxXorAndPartition(int[] nums) {
        int n = nums.length;
        int fullMask = (1 << n) - 1;
        int[] xorMask = new int[1 << n];
        int[] andMask = new int[1 << n];
        xorMask[0] = 0;
        andMask[0] = -1;
        for (int mask = 1; mask <= fullMask; mask++) {
            int lowbit = mask & -mask;
            int prev = mask ^ lowbit;
            int idx = Integer.numberOfTrailingZeros(lowbit);
            xorMask[mask] = xorMask[prev] ^ nums[idx];
            andMask[mask] = andMask[prev] & nums[idx];
        }
        int answer = 0;
        for (int maskA = 0; maskA <= fullMask; maskA++) {
            int remaining = fullMask ^ maskA;
            for (int maskB = remaining; ; maskB = (maskB - 1) & remaining) {
                int maskC = fullMask ^ (maskA | maskB);
                int sum = xorMask[maskA] + xorMask[maskB] + (maskC == 0 ? 0 : andMask[maskC]);
                if (sum > answer) answer = sum;
                if (maskB == 0) break;
            }
        }
        return answer;
    }
}

