class Solution {
    public static int minRemovals(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int left = 0;
        int best = 0;
        for (int right = 0; right < n; right++) {
            while ((long) nums[right] > (long) k * nums[left]) {
                left++;
            }
            int windowSize = right - left + 1;
            if (windowSize > best) {
                best = windowSize;
            }
        }
        return n - best;
    }
}

