public class Solution {
    public static int earliestFinishTime(int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
        int n = landStartTime.length;
        int m = waterStartTime.length;

        int[][] land = new int[n][2];
        for (int i = 0; i < n; i++) {
            land[i][0] = landStartTime[i];
            land[i][1] = landStartTime[i] + landDuration[i];
        }
        int[][] water = new int[m][2];
        for (int i = 0; i < m; i++) {
            water[i][0] = waterStartTime[i];
            water[i][1] = waterStartTime[i] + waterDuration[i];
        }

        Arrays.sort(land, Comparator.comparingInt(a -> a[0]));
        Arrays.sort(water, Comparator.comparingInt(a -> a[0]));

        int[] landStarts = new int[n];
        int[] landEnds = new int[n];
        for (int i = 0; i < n; i++) {
            landStarts[i] = land[i][0];
            landEnds[i] = land[i][1];
        }

        int[] waterStarts = new int[m];
        int[] waterEnds = new int[m];
        int[] waterDur = new int[m];
        for (int i = 0; i < m; i++) {
            waterStarts[i] = water[i][0];
            waterEnds[i] = water[i][1];
            waterDur[i] = waterDuration[i];
        }

        int[] waterPrefixMinDur = new int[m];
        for (int i = 0; i < m; i++) {
            if (i == 0) waterPrefixMinDur[i] = waterDur[i];
            else waterPrefixMinDur[i] = Math.min(waterPrefixMinDur[i - 1], waterDur[i]);
        }

        int[] waterSuffixMinEnd = new int[m];
        for (int i = m - 1; i >= 0; i--) {
            if (i == m - 1) waterSuffixMinEnd[i] = waterEnds[i];
            else waterSuffixMinEnd[i] = Math.min(waterEnds[i], waterSuffixMinEnd[i + 1]);
        }

        int[] landPrefixMinDur = new int[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) landPrefixMinDur[i] = landDuration[i];
            else landPrefixMinDur[i] = Math.min(landPrefixMinDur[i - 1], landDuration[i]);
        }

        int[] landSuffixMinEnd = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            if (i == n - 1) landSuffixMinEnd[i] = landEnds[i];
            else landSuffixMinEnd[i] = Math.min(landEnds[i], landSuffixMinEnd[i + 1]);
        }

        long best = Long.MAX_VALUE;

        // land -> water
        for (int i = 0; i < n; i++) {
            int finishLand = landEnds[i];
            int idx = lowerBound(waterStarts, finishLand);
            long cand = Long.MAX_VALUE;
            if (idx < m) {
                cand = Math.min(cand, waterSuffixMinEnd[idx]);
            }
            if (idx > 0) {
                cand = Math.min(cand, (long) finishLand + waterPrefixMinDur[idx - 1]);
            }
            best = Math.min(best, cand);
        }

        // water -> land
        for (int i = 0; i < m; i++) {
            int finishWater = waterEnds[i];
            int idx = lowerBound(landStarts, finishWater);
            long cand = Long.MAX_VALUE;
            if (idx < n) {
                cand = Math.min(cand, landSuffixMinEnd[idx]);
            }
            if (idx > 0) {
                cand = Math.min(cand, (long) finishWater + landPrefixMinDur[idx - 1]);
            }
            best = Math.min(best, cand);
        }

        return best == Long.MAX_VALUE ? -1 : (int) best;
    }

    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

