public class Solution {
    public int earliestFinish(int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
        int n = landStartTime.length;
        int m = waterStartTime.length;
        int INF = Integer.MAX_VALUE / 2;
        int ans = INF;
        for (int i = 0; i < n; i++) {
            int landEnd = landStartTime[i] + landDuration[i];
            for (int j = 0; j < m; j++) {
                int waterEnd = waterStartTime[j] + waterDuration[j];
                // Land ride first, then water ride
                int finishLandFirst = Math.max(landEnd, waterStartTime[j]) + waterDuration[j];
                // Water ride first, then land ride
                int finishWaterFirst = Math.max(waterEnd, landStartTime[i]) + landDuration[i];
                ans = Math.min(ans, Math.min(finishLandFirst, finishWaterFirst));
            }
        }
        return ans;
    }
}

