class Solution {
    public static boolean isTrionicArray(int[] nums) {
        int n = nums.length;
        if (n < 5) return false;
        boolean[] incPrefix = new boolean[n];
        incPrefix[0] = true;
        for (int i = 1; i < n; i++) {
            incPrefix[i] = incPrefix[i - 1] && nums[i - 1] < nums[i];
        }
        boolean[] incSuffix = new boolean[n];
        incSuffix[n - 1] = true;
        for (int i = n - 2; i >= 0; i--) {
            incSuffix[i] = incSuffix[i + 1] && nums[i] < nums[i + 1];
        }
        for (int p = 1; p <= n - 3; p++) {
            if (!incPrefix[p]) continue;
            for (int q = p + 2; q <= n - 3; q++) {
                boolean decreasing = true;
                for (int k = p + 1; k < q; k++) {
                    if (nums[k] <= nums[k + 1]) {
                        decreasing = false;
                        break;
                    }
                }
                if (decreasing && incSuffix[q + 1]) {
                    return true;
                }
            }
        }
        return false;
    }
}

