public class Solution {
    public int[] thresholdMajorityQueries(int[] nums, int[][] queries) {
        int n = nums.length;
        // Compress values
        Map<Integer, Integer> map = new HashMap<>();
        int[] comp = new int[n];
        int idx = 0;
        for (int i = 0; i < n; i++) {
            Integer v = map.get(nums[i]);
            if (v == null) {
                v = idx;
                map.put(nums[i], idx++);
            }
            comp[i] = v;
        }
        int m = idx;
        int[] freq = new int[m];
        int[] seen = new int[m];
        int curMark = 1;

        int q = queries.length;
        int[] ans = new int[q];

        for (int i = 0; i < q; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            int threshold = queries[i][2];

            int maxCount = 0;
            int bestVal = Integer.MAX_VALUE;

            for (int j = l; j <= r; j++) {
                int id = comp[j];
                if (seen[id] != curMark) {
                    freq[id] = 0;
                    seen[id] = curMark;
                }
                int cnt = ++freq[id];
                int val = nums[j];
                if (cnt > maxCount) {
                    maxCount = cnt;
                    bestVal = val;
                } else if (cnt == maxCount && val < bestVal) {
                    bestVal = val;
                }
            }

            ans[i] = (maxCount >= threshold) ? bestVal : -1;
            curMark++;
        }

        return ans;
    }
}

class Solution {
    public long maxSumTrionic(int[] nums) {
        int n = nums.length;
        int i = 0;
        long ans = Long.MIN_VALUE;
        while (i < n) {
            int l = i;
            i += 1;
            while (i < n && nums[i - 1] < nums[i]) i += 1;
            if (i == l + 1) continue;
            int p = i - 1;
            long s = (long) nums[p - 1] + nums[p];
            while (i < n && nums[i - 1] > nums[i]) { s += nums[i]; i += 1; }
            if (i == p + 1 || i == n || nums[i - 1] == nums[i]) continue;
            int q = i - 1;
            s += nums[i];
            i += 1;
            long mx = 0, t = 0;
            while (i < n && nums[i - 1] < nums[i]) { t += nums[i]; i += 1; mx = Math.max(mx, t); }
            s += mx;
            mx = 0; t = 0;
            int j = p - 2;
            while (j >= l) { t += nums[j]; mx = Math.max(mx, t); j -= 1; }
            s += mx;
            ans = Math.max(ans, s);
            i = q;
        }
        return ans;
    }
}

