class Solution {
    public static int minimumTime(String s, int[] order, long k) {
        int n = s.length();
        long total = (long) n * (n + 1) / 2;
        if (k > total) return -1;
        int low = 0, high = n - 1;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (goodCount(mid, n, order, total) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return goodCount(low, n, order, total) >= k ? low : -1;
    }

    private static long goodCount(int t, int n, int[] order, long total) {
        long bad = 0;
        long len = 0;
        for (int i = 0; i < n; i++) {
            if (order[i] > t) {
                len++;
            } else {
                bad += len * (len + 1) / 2;
                len = 0;
            }
        }
        bad += len * (len + 1) / 2;
        return total - bad;
    }
}

