class Solution {
    public static int maxBalancedShipments(int[] weight) {
        int n = weight.length;
        int i = 0;
        int shipments = 0;
        while (i < n) {
            int maxSoFar = weight[i];
            int j = i + 1;
            while (j < n) {
                if (weight[j] > maxSoFar) {
                    maxSoFar = weight[j];
                } else if (weight[j] < maxSoFar) {
                    shipments++;
                    break;
                }
                j++;
            }
            if (j == n) break;
            i = j + 1;
        }
        return shipments;
    }
}

