class Solution {
    public static long maxTotal(int[] value, int[] limit) {
        int n = value.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            if (limit[a] != limit[b]) return Integer.compare(limit[a], limit[b]);
            return Integer.compare(value[b], value[a]);
        });
        int[] lim = new int[n], val = new int[n];
        for (int i = 0; i < n; i++) { lim[i] = limit[idx[i]]; val[i] = value[idx[i]]; }
        int[] status = new int[n];
        int i = 0, j = 0, active = 0;
        long ans = 0;
        while (j < n) {
            int v = val[j], lmt = lim[j];
            if (active < lmt) {
                status[j] = 1;
                ans += v;
                active += 1;
                if (active == lmt) {
                    while (j < n && lim[j] == active) j++;
                } else {
                    j++;
                }
            } else {
                j++;
            }
            while (i < j && lim[i] <= active) {
                active -= status[i];
                i++;
            }
        }
        return ans;
    }
}

