class Solution {
    List<Map<Integer,Integer>> multisetCounts = new ArrayList<>();
    List<Integer> multisetLens = new ArrayList<>();

    void buildMultisets() {
        int[] evenDigits = {2,4,6,8};
        int[] oddChoices = {0,1,3,5,7,9};
        int n = evenDigits.length;
        for (int mask = 0; mask < (1<<n); mask++) {
            List<Integer> combo = new ArrayList<>();
            for (int i = 0; i < n; i++) if ((mask & (1<<i)) != 0) combo.add(evenDigits[i]);
            for (int odd : oddChoices) {
                List<Integer> digits = new ArrayList<>(combo);
                if (odd != 0) digits.add(odd);
                if (digits.isEmpty()) continue;
                Map<Integer,Integer> counts = new TreeMap<>();
                int total = 0;
                for (int d : digits) { counts.put(d, d); total += d; }
                multisetCounts.add(counts);
                multisetLens.add(total);
            }
        }
    }

    Map<Integer,Integer> half; Integer middle;
    void halfMultiset(Map<Integer,Integer> counts) {
        half = new TreeMap<>(); middle = null;
        for (var e : counts.entrySet()) {
            int d = e.getKey(), c = e.getValue();
            if (c % 2 == 1) middle = d;
            half.put(d, c/2);
        }
    }

    String minArrangement(Map<Integer,Integer> counts) {
        halfMultiset(counts);
        List<Character> chars = new ArrayList<>();
        for (var e : half.entrySet()) for (int i = 0; i < e.getValue(); i++) chars.add((char)('0'+e.getKey()));
        Collections.sort(chars);
        StringBuilder sb = new StringBuilder();
        for (char c : chars) sb.append(c);
        String prefix = sb.toString();
        String mid = middle != null ? String.valueOf((char)('0'+middle)) : "";
        return prefix + mid + new StringBuilder(prefix).reverse();
    }

    String bestGreaterArrangement(Map<Integer,Integer> counts, String nStr) {
        int L = 0; for (int v : counts.values()) L += v;
        halfMultiset(counts);
        List<Character> chars = new ArrayList<>();
        for (var e : half.entrySet()) for (int i = 0; i < e.getValue(); i++) chars.add((char)('0'+e.getKey()));
        Collections.sort(chars);
        String mid = middle != null ? String.valueOf((char)('0'+middle)) : "";
        if (chars.isEmpty()) {
            String full = mid;
            return (full.length() == L && full.compareTo(nStr) > 0) ? full : null;
        }
        char[] arr = new char[chars.size()];
        for (int i = 0; i < chars.size(); i++) arr[i] = chars.get(i);
        String best = null;
        boolean hasNext = true;
        do {
            String prefix = new String(arr);
            String rev = new StringBuilder(prefix).reverse().toString();
            String full = prefix + mid + rev;
            if (full.length() == L && full.compareTo(nStr) > 0) {
                if (best == null || full.compareTo(best) < 0) best = full;
            }
            hasNext = nextPermutation(arr);
        } while (hasNext);
        return best;
    }

    boolean nextPermutation(char[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i+1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        char tmp = a[i]; a[i] = a[j]; a[j] = tmp;
        for (int l = i+1, r = a.length-1; l < r; l++, r--) { tmp = a[l]; a[l] = a[r]; a[r] = tmp; }
        return true;
    }

    public long nextSpecialPalindrome(long n) {
        buildMultisets();
        String nStr = String.valueOf(n);
        int L0 = nStr.length();
        Map<Integer, List<Map<Integer,Integer>>> byLen = new TreeMap<>();
        for (int i = 0; i < multisetLens.size(); i++) {
            byLen.computeIfAbsent(multisetLens.get(i), k -> new ArrayList<>()).add(multisetCounts.get(i));
        }
        if (byLen.containsKey(L0)) {
            String best = null;
            for (var counts : byLen.get(L0)) {
                String res = bestGreaterArrangement(counts, nStr);
                if (res != null && (best == null || res.compareTo(best) < 0)) best = res;
            }
            if (best != null) return Long.parseLong(best);
        }
        for (var entry : byLen.entrySet()) {
            if (entry.getKey() <= L0) continue;
            String best = null;
            for (var counts : entry.getValue()) {
                String arrStr = minArrangement(counts);
                if (best == null || arrStr.compareTo(best) < 0) best = arrStr;
            }
            return Long.parseLong(best);
        }
        return -1;
    }
}

import java.util.*;
class Solution {
    public static int minCost(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int inf = Integer.MAX_VALUE / 2;
        int[][][] f = new int[k+1][m][n];
        for (int t = 0; t <= k; t++) for (int i = 0; i < m; i++) Arrays.fill(f[t][i], inf);
        f[0][0][0] = 0;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (i > 0) f[0][i][j] = Math.min(f[0][i][j], f[0][i-1][j] + grid[i][j]);
            if (j > 0) f[0][i][j] = Math.min(f[0][i][j], f[0][i][j-1] + grid[i][j]);
        }
        Map<Integer, List<int[]>> g = new HashMap<>();
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) g.computeIfAbsent(grid[i][j], z -> new ArrayList<>()).add(new int[]{i,j});
        List<Integer> keys = new ArrayList<>(g.keySet());
        keys.sort(Collections.reverseOrder());
        for (int t = 1; t <= k; t++) {
            int mn = inf;
            for (int key : keys) {
                List<int[]> pos = g.get(key);
                for (int[] p : pos) mn = Math.min(mn, f[t-1][p[0]][p[1]]);
                for (int[] p : pos) f[t][p[0]][p[1]] = mn;
            }
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (i > 0) f[t][i][j] = Math.min(f[t][i][j], f[t][i-1][j] + grid[i][j]);
                if (j > 0) f[t][i][j] = Math.min(f[t][i][j], f[t][i][j-1] + grid[i][j]);
            }
        }
        int ans = inf;
        for (int t = 0; t <= k; t++) ans = Math.min(ans, f[t][m-1][n-1]);
        return ans;
    }
}

class Solution {
    public long numberOfPerfectPairs(int[] nums) {
        int n = nums.length;
        long count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long a = nums[i], b = nums[j];
                long mn = Math.min(Math.abs(a - b), Math.abs(a + b));
                long mx = Math.max(Math.abs(a - b), Math.abs(a + b));
                if (mn <= Math.min(Math.abs(a), Math.abs(b)) && mx >= Math.max(Math.abs(a), Math.abs(b))) {
                    count++;
                }
            }
        }
        return count;
    }
}

class Solution {
    public static long maxProfit(int[] prices, int[] strategy, int k) {
        int n = prices.length;
        int h = k / 2;
        long pOriginal = 0;
        for (int i = 0; i < n; i++) pOriginal += (long)strategy[i] * prices[i];
        long newSeg = 0;
        for (int i = h; i < k; i++) newSeg += prices[i];
        long oldSeg = 0;
        for (int i = 0; i < k; i++) oldSeg += (long)strategy[i] * prices[i];
        long maxDelta = Math.max(0L, newSeg - oldSeg);
        for (int j = 1; j <= n - k; j++) {
            oldSeg += -(long)strategy[j-1]*prices[j-1] + (long)strategy[j+k-1]*prices[j+k-1];
            newSeg += -prices[j-1+h] + prices[j+k-1];
            maxDelta = Math.max(maxDelta, newSeg - oldSeg);
        }
        return pOriginal + maxDelta;
    }
}

