class Solution {
    public long minimumSum(int[] nums, int k) {
        long K = k;
        long pref = 0;
        long dp = 0;
        HashMap<Long, Long> best = new HashMap<>();
        best.put(0L, 0L);
        for (int value : nums) {
            pref += value;
            long rem = ((pref % K) + K) % K;
            long cand = dp;
            Long bestVal = best.get(rem);
            if (bestVal != null) {
                long possible = bestVal + pref;
                if (possible > cand) {
                    cand = possible;
                }
            }
            dp = cand;
            long newBest = dp - pref;
            Long cur = best.get(rem);
            if (cur == null || newBest > cur) {
                best.put(rem, newBest);
            }
        }
        long total = pref;
        long maxDeleted = dp;
        return total - maxDeleted;
    }
}

