class Solution {
    public static int maximumWallsDestroyed(int[] robots, int[] distance, int[] walls) {
        int n = robots.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(robots[a], robots[b]));
        int[] pos = new int[n], dist = new int[n];
        for (int i = 0; i < n; i++) { pos[i] = robots[idx[i]]; dist[i] = distance[idx[i]]; }
        int[] w = walls.clone();
        Arrays.sort(w);

        Map<Long, Integer> memo = new HashMap<>();
        return dp(n - 1, 1, pos, dist, w, n, memo);
    }

    private static int dp(int i, int j, int[] pos, int[] dist, int[] w, int n, Map<Long, Integer> memo) {
        if (i < 0) return 0;
        long key = (long) i * 2 + j;
        if (memo.containsKey(key)) return memo.get(key);

        int left = pos[i] - dist[i];
        if (i > 0) left = Math.max(left, pos[i-1] + 1);
        int l = lowerBound(w, left);
        int r = lowerBound(w, pos[i] + 1);
        int optLeft = dp(i - 1, 0, pos, dist, w, n, memo) + (r - l);

        int right = pos[i] + dist[i];
        if (i + 1 < n) {
            if (j == 0) right = Math.min(right, pos[i+1] - dist[i+1] - 1);
            else right = Math.min(right, pos[i+1] - 1);
        }
        l = lowerBound(w, pos[i]);
        r = lowerBound(w, right + 1);
        int optRight = dp(i - 1, 1, pos, dist, w, n, memo) + (r - l);

        int res = Math.max(optLeft, optRight);
        memo.put(key, res);
        return res;
    }

    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

