class Solution {
    public static long twistedMirrorPathCount(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        int m = grid[0].length;
        if (m == 0) return 0;
        long[][][] dp = new long[n][m][3];
        dp[0][0][0] = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int prev = 0; prev <= 2; prev++) {
                    long ways = dp[i][j][prev];
                    if (ways == 0) continue;
                    // move right
                    if (j + 1 < m) {
                        int dir = 1;
                        if (!(grid[i][j] == 1 && dir == prev)) {
                            dp[i][j + 1][dir] += ways;
                        }
                    }
                    // move down
                    if (i + 1 < n) {
                        int dir = 2;
                        if (!(grid[i][j] == 1 && dir == prev)) {
                            dp[i + 1][j][dir] += ways;
                        }
                    }
                }
            }
        }
        long result = 0;
        for (int d = 0; d <= 2; d++) {
            result += dp[n - 1][m - 1][d];
        }
        return result;
    }
}

