class Solution {
    public static boolean canPartitionKDistinct(int[] arr, int k) {
        int n = arr.length;
        if (k <= 0 || n % k != 0) return false;
        int groups = n / k;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int val = arr[i];
            freq.put(val, freq.getOrDefault(val, 0) + 1);
        }
        int maxFreq = 0;
        for (int count : freq.values()) {
            if (count > maxFreq) maxFreq = count;
        }
        return maxFreq <= groups;
    }
}

import java.util.*;
class Solution {
    public static int maxScore(String[] cards, char x) {
        Map<Character,Integer> P=new HashMap<>(), Q=new HashMap<>(); int Z=0;
        for (String c : cards) {
            if (c.indexOf(x)<0) continue;
            char a=c.charAt(0), b=c.charAt(1);
            if (a==x && b==x) Z++;
            else if (a==x) P.merge(b,1,Integer::sum);
            else if (b==x) Q.merge(a,1,Integer::sum);
        }
        int totalP=P.values().stream().mapToInt(i->i).sum();
        int totalQ=Q.values().stream().mapToInt(i->i).sum();
        int maxP=P.values().stream().mapToInt(i->i).max().orElse(0);
        int maxQ=Q.values().stream().mapToInt(i->i).max().orElse(0);
        int total=totalP+totalQ+Z;
        int bottleneck=Math.max(maxP+maxQ, Z);
        return Math.min(total/2, total-bottleneck);
    }
}

