class Solution {
    public static long maxProduct(int[] nums) {
        if (nums.length < 2) return 0;
        int maxVal = 0;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) {
            if (x > maxVal) maxVal = x;
            freq.put(x, freq.getOrDefault(x, 0) + 1);
        }
        int bits = 0;
        while ((1 << bits) <= maxVal) ++bits;
        if (bits == 0) bits = 1;
        int size = 1 << bits;
        int[] best = new int[size];
        Arrays.fill(best, -1);
        for (int x : nums) {
            best[x] = Math.max(best[x], x);
        }
        for (int i = 0; i < bits; ++i) {
            for (int mask = 0; mask < size; ++mask) {
                if ((mask & (1 << i)) != 0) {
                    best[mask] = Math.max(best[mask], best[mask ^ (1 << i)]);
                }
            }
        }
        long ans = 0;
        int fullMask = size - 1;
        for (int x : nums) {
            int complement = fullMask ^ x;
            int y = best[complement];
            if (y == -1) continue;
            if (y == x && freq.get(x) < 2) continue;
            long prod = (long) x * y;
            if (prod > ans) ans = prod;
        }
        return ans;
    }
}

class Solution {
    static final long MOD = 1_000_000_007L;

    private void update(long[] bit, int i, long delta, int m) {
        for (; i <= m; i += i & (-i)) bit[i] = (bit[i] + delta) % MOD;
    }
    private long query(long[] bit, int i) {
        long s = 0;
        for (; i > 0; i -= i & (-i)) s = (s + bit[i]) % MOD;
        return s;
    }

    private long countIncreasing(List<Integer> values) {
        if (values.isEmpty()) return 0;
        List<Integer> sortedUnique = new ArrayList<>(new TreeSet<>(values));
        int m = sortedUnique.size();
        long[] bit = new long[m + 1];
        long total = 0;
        for (int v : values) {
            int r = Collections.binarySearch(sortedUnique, v) + 1;
            long prefix = query(bit, r - 1);
            long dp = (1 + prefix) % MOD;
            update(bit, r, dp, m);
            total = (total + dp) % MOD;
        }
        return total;
    }

    public int sumOfBeauty(int[] nums) {
        int maxv = 0;
        for (int x : nums) maxv = Math.max(maxv, x);
        long[] f = new long[maxv + 1];
        for (int g = 1; g <= maxv; g++) {
            List<Integer> filtered = new ArrayList<>();
            for (int x : nums) if (x % g == 0) filtered.add(x);
            f[g] = countIncreasing(filtered);
        }
        long[] exact = new long[maxv + 2];
        long ans = 0;
        for (int g = maxv; g >= 1; g--) {
            long val = f[g];
            for (int m = 2 * g; m <= maxv; m += g) {
                val = (val - exact[m] % MOD + MOD) % MOD;
            }
            exact[g] = val;
            ans = (ans + (long) g % MOD * exact[g]) % MOD;
        }
        return (int) ans;
    }
}

