class Solution {
    static List<Long> getDivisors(long x){
        List<Long> d = new ArrayList<>();
        for (long i=1;i*i<=x;i++) if (x%i==0){ d.add(i); if (i!=x/i) d.add(x/i);}
        return d;
    }
    static long[] path; static long[] best; static long bestD;
    static void dfs(int i, long x, long mi, long mx){
        if (i==0){
            long d = Math.max(mx,x)-Math.min(mi,x);
            if (d<bestD){ bestD=d; path[i]=x; best=path.clone(); }
            return;
        }
        for (long y : getDivisors(x)){
            path[i]=y;
            dfs(i-1, x/y, Math.min(mi,y), Math.max(mx,y));
        }
    }
    public static long[] balancedKFactorDecomposition(long n, int k){
        path = new long[k]; bestD = Long.MAX_VALUE;
        dfs(k-1, n, Long.MAX_VALUE, 0);
        return best;
    }
}

