class Solution {
    public static long countBinaryPalindromes(long N) {
        if (N < 0) return 0;
        long total = 1; // count zero
        if (N == 0) return total;
        int binLen = Long.toBinaryString(N).length();
        for (int len = 1; len < binLen; len++) {
            int half = (len + 1) / 2;
            total += 1L << (half - 1);
        }
        int halfLen = (binLen + 1) / 2;
        long start = 1L << (halfLen - 1);
        long end = 1L << halfLen;
        for (long prefix = start; prefix < end; prefix++) {
            long palindrome = buildPalindrome(prefix, binLen);
            if (palindrome <= N) total++;
        }
        return total;
    }

    private static long buildPalindrome(long prefix, int totalLen) {
        long pal = prefix;
        long rev = prefix;
        if ((totalLen & 1) == 1) {
            rev >>= 1;
        }
        while (rev > 0) {
            pal = (pal << 1) | (rev & 1);
            rev >>= 1;
        }
        return pal;
    }
}

