public class Solution {
    public int minSplitMerge(int[] nums1, int[] nums2) {
        int n = nums1.length;
        List<Integer> start = new ArrayList<>();
        for (int x : nums1) start.add(x);
        List<Integer> target = new ArrayList<>();
        for (int x : nums2) target.add(x);
        if (start.equals(target)) return 0;

        Set<List<Integer>> visited = new HashSet<>();
        visited.add(start);
        Deque<List<Integer>> queue = new ArrayDeque<>();
        queue.add(start);
        int steps = 0;

        while (!queue.isEmpty()) {
            steps++;
            int size = queue.size();
            for (int s = 0; s < size; s++) {
                List<Integer> cur = queue.poll();
                for (int l = 0; l < n; l++) {
                    for (int r = l; r < n; r++) {
                        List<Integer> sub = new ArrayList<>(cur.subList(l, r + 1));
                        List<Integer> rest = new ArrayList<>(cur.subList(0, l));
                        rest.addAll(cur.subList(r + 1, n));
                        for (int pos = 0; pos <= rest.size(); pos++) {
                            List<Integer> newState = new ArrayList<>(rest.subList(0, pos));
                            newState.addAll(sub);
                            newState.addAll(rest.subList(pos, rest.size()));
                            if (newState.equals(target)) return steps;
                            if (!visited.contains(newState)) {
                                visited.add(newState);
                                queue.add(newState);
                            }
                        }
                    }
                }
            }
        }
        return -1;
    }
}

class Solution {
    static final long MOD = 1_000_000_007L;
    public static long numberOfStableSubsequences(int[] nums) {
        long[][] dp = new long[2][2];
        for (int x : nums) {
            int p = x % 2;
            int op = 1 - p;
            long addP1 = (1 + dp[op][0] + dp[op][1]) % MOD;
            long addP2 = dp[p][0];
            dp[p][0] = (dp[p][0] + addP1) % MOD;
            dp[p][1] = (dp[p][1] + addP2) % MOD;
        }
        return (dp[0][0] + dp[0][1] + dp[1][0] + dp[1][1]) % MOD;
    }
}

