class Solution {
    public static String majorityFrequencyChars(String s) {
        Map<Character, Integer> freq = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            freq.put(ch, freq.getOrDefault(ch, 0) + 1);
        }
        int maxFreq = Collections.max(freq.values());
        List<Character> maxChars = new ArrayList<>();
        for (Map.Entry<Character, Integer> e : freq.entrySet()) {
            if (e.getValue() == maxFreq) {
                maxChars.add(e.getKey());
            }
        }
        List<Character> resultChars = new ArrayList<>();
        if (maxChars.size() >= 2) {
            resultChars.addAll(maxChars);
        } else {
            int secondMax = freq.values().stream()
                    .filter(v -> v != maxFreq)
                    .max(Integer::compare)
                    .orElse(0);
            for (Map.Entry<Character, Integer> e : freq.entrySet()) {
                if (e.getValue() == secondMax) {
                    resultChars.add(e.getKey());
                }
            }
        }
        Collections.sort(resultChars);
        StringBuilder sb = new StringBuilder();
        for (char c : resultChars) {
            sb.append(c);
        }
        return sb.toString();
    }
}

