public class Solution {
    public static int countDistinct(String s, int k) {
        int n = s.length();
        int[] xs = new int[n + 1];
        int[] ys = new int[n + 1];
        for (int i = 0; i < n; i++) {
            xs[i + 1] = xs[i];
            ys[i + 1] = ys[i];
            char c = s.charAt(i);
            if (c == 'L') xs[i + 1]--;
            else if (c == 'R') xs[i + 1]++;
            else if (c == 'U') ys[i + 1]++;
            else if (c == 'D') ys[i + 1]--;
        }
        int totalX = xs[n], totalY = ys[n];
        Set<Long> seen = new HashSet<>();
        for (int i = k; i <= n; i++) {
            int removedX = xs[i] - xs[i - k];
            int removedY = ys[i] - ys[i - k];
            int fx = totalX - removedX, fy = totalY - removedY;
            long key = ((long) fx << 32) ^ (fy & 0xffffffffL);
            seen.add(key);
        }
        return seen.size();
    }
}

