class Solution {
    public static long maxAlternatingSum(int[] arr, int[][] swaps) {
        int n = arr.length;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; ++i) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
            int ra = find.applyAsInt(a);
            int rb = find.applyAsInt(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) rank[ra]++;
        };

        for (int[] pair : swaps) {
            union.accept(pair[0], pair[1]);
        }

        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            int r = find.applyAsInt(i);
            groups.computeIfAbsent(r, k -> new ArrayList<>()).add(i);
        }

        long total = 0;
        for (List<Integer> idxList : groups.values()) {
            List<Integer> values = new ArrayList<>(idxList.size());
            for (int i : idxList) {
                values.add(arr[i]);
            }
            values.sort(Collections.reverseOrder());

            int posCnt = 0;
            for (int i : idxList) {
                if (i % 2 == 0) posCnt++;
            }

            long posSum = 0, negSum = 0;
            for (int k = 0; k < values.size(); ++k) {
                int val = values.get(k);
                if (k < posCnt) posSum += val;
                else negSum += val;
            }
            total += posSum - negSum;
        }

        return total;
    }
}

