class Solution {
    public static long splitArray(int[] nums) {
        int n = nums.length;
        if (n < 2) return -1;
        long[] s = new long[n];
        s[0] = nums[0];
        boolean[] f = new boolean[n];
        boolean[] g = new boolean[n];
        Arrays.fill(f, true);
        Arrays.fill(g, true);
        for (int i = 1; i < n; i++) {
            s[i] = s[i-1] + nums[i];
            f[i] = f[i-1] && nums[i] > nums[i-1];
        }
        for (int i = n-2; i >= 0; i--) {
            g[i] = g[i+1] && nums[i] > nums[i+1];
        }
        long ans = -1;
        boolean found = false;
        for (int i = 0; i < n-1; i++) {
            if (f[i] && g[i+1]) {
                long leftSum = s[i];
                long rightSum = s[n-1] - s[i];
                long diff = Math.abs(leftSum - rightSum);
                if (!found || diff < ans) { ans = diff; found = true; }
            }
        }
        return found ? ans : -1;
    }
}

