class Solution {
    static final long MOD = 1000000007L;
    public static long numberOfZigZagArrays(int n, int m) {
        if (n == 1) return m % MOD;
        long[] dp = new long[m + 2];
        Arrays.fill(dp, 1L); dp[0] = 0;
        for (int i = 2; i <= n; i++) {
            long[] pref = new long[m + 2];
            for (int v = 1; v <= m; v++) pref[v] = (pref[v-1] + dp[v]) % MOD;
            long total = pref[m];
            long[] ndp = new long[m + 2];
            if (i % 2 == 0) { for (int v = 1; v <= m; v++) ndp[v] = pref[v-1]; }
            else { for (int v = 1; v <= m; v++) ndp[v] = (total - pref[v] + MOD) % MOD; }
            dp = ndp;
        }
        long half = 0;
        for (int v = 1; v <= m; v++) half = (half + dp[v]) % MOD;
        return (half * 2) % MOD;
    }
}

