import java.util.*;
class ExamTracker {
    List<Integer> times = new ArrayList<>();
    List<Long> prefix = new ArrayList<>(List.of(0L));
    public void record(int time, int score) {
        times.add(time);
        prefix.add(prefix.get(prefix.size() - 1) + score);
    }
    public long totalScore(int startTime, int endTime) {
        int lo = lowerBound(startTime);
        int hi = upperBound(endTime);
        if (lo >= hi) return 0;
        return prefix.get(hi) - prefix.get(lo);
    }
    private int lowerBound(int key) {
        int lo = 0, hi = times.size();
        while (lo < hi) { int mid = (lo + hi) / 2; if (times.get(mid) < key) lo = mid + 1; else hi = mid; }
        return lo;
    }
    private int upperBound(int key) {
        int lo = 0, hi = times.size();
        while (lo < hi) { int mid = (lo + hi) / 2; if (times.get(mid) <= key) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

class Solution {
    // Run-length compressed stack: each frame is (char, runLength). After pushing a ')',
    // check whether the top run is exactly k ')' sitting on top of a run of >= k '(' -
    // if so, collapse both (this correctly cascades merges without ever rescanning the
    // whole string, unlike a naive repeated string.replace loop which is O(n^2) on
    // adversarial nested inputs - see LeetCode-Feedback #32671/#32675 for reports of
    // exactly that quadratic blowup passing when it shouldn\'t).
    public String removeSubstring(String s, int k) {
        java.util.List<int[]> stk = new java.util.ArrayList<>();
        for (char c : s.toCharArray()) {
            if (!stk.isEmpty() && stk.get(stk.size() - 1)[0] == c) {
                stk.get(stk.size() - 1)[1]++;
            } else {
                stk.add(new int[]{c, 1});
            }
            if (c == ')' && stk.size() > 1) {
                int[] top = stk.get(stk.size() - 1);
                int[] prev = stk.get(stk.size() - 2);
                if (top[1] == k && prev[0] == '(' && prev[1] >= k) {
                    stk.remove(stk.size() - 1);
                    prev[1] -= k;
                    if (prev[1] == 0) stk.remove(stk.size() - 1);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int[] pair : stk) for (int i = 0; i < pair[1]; i++) sb.append((char) pair[0]);
        return sb.toString();
    }
}

