class Solution {
    public static int longestBalancedSubstring(String s) {
        int n = s.length();
        int maxLen = 0;
        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) {
            Arrays.fill(cnt, 0);
            for (int j = i; j < n; j++) {
                int idx = s.charAt(j) - 'a';
                cnt[idx]++;
                int min = Integer.MAX_VALUE;
                int max = Integer.MIN_VALUE;
                for (int k = 0; k < 26; k++) {
                    if (cnt[k] > 0) {
                        if (cnt[k] < min) min = cnt[k];
                        if (cnt[k] > max) max = cnt[k];
                    }
                }
                if (min == max) {
                    int len = j - i + 1;
                    if (len > maxLen) maxLen = len;
                }
            }
        }
        return maxLen;
    }
}

