class Solution {
    public static boolean equalScoreSubstring(String s) {
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            total += s.charAt(i) - 'a' + 1;
        }
        if (total % 2 != 0) return false;
        int target = total / 2;
        int prefix = 0;
        for (int i = 0; i < s.length(); i++) {
            prefix += s.charAt(i) - 'a' + 1;
            if (prefix == target) return true;
        }
        return false;
    }
}

public class Solution {
    public static int longestFibonacciSubarray(int[] arr) {
        int n = arr.length;
        if (n <= 2) return n;
        int maxLen = 2;
        int curLen = 2;
        for (int i = 2; i < n; i++) {
            if (arr[i] == arr[i - 1] + arr[i - 2]) {
                curLen++;
            } else {
                curLen = 2;
            }
            if (curLen > maxLen) maxLen = curLen;
        }
        return maxLen;
    }
}

