class Solution {
    public static long sumOfAncestors(int n, int[][] edges, int[] nums) {
        long[] vals = new long[n];
        for (int i = 0; i < n; i++) {
            long num = nums[i];
            for (long j = 2; j*j <= num; j++) while (num % (j*j) == 0) num /= (j*j);
            vals[i] = num;
        }
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] e : edges) { graph.get(e[0]).add(e[1]); graph.get(e[1]).add(e[0]); }
        long[] ans = {0};
        Map<Long,Integer> history = new HashMap<>();
        dfs(0, -1, vals, graph, ans, history);
        return ans[0];
    }
    private static void dfs(int u, int p, long[] vals, List<List<Integer>> graph, long[] ans, Map<Long,Integer> history) {
        long v = vals[u];
        ans[0] += history.getOrDefault(v, 0);
        history.put(v, history.getOrDefault(v, 0) + 1);
        for (int w : graph.get(u)) if (w != p) dfs(w, u, vals, graph, ans, history);
        history.put(v, history.get(v) - 1);
    }
}

class Solution {
    public static long maximumPartitionFactor(int[][] points) {
        if (points.length < 2) return 0;
        long maxSum = Long.MIN_VALUE, minSum = Long.MAX_VALUE, maxDiff = Long.MIN_VALUE, minDiff = Long.MAX_VALUE;
        for (int[] p : points) {
            long s = p[0] + p[1], d = p[0] - p[1];
            maxSum = Math.max(maxSum, s);
            minSum = Math.min(minSum, s);
            maxDiff = Math.max(maxDiff, d);
            minDiff = Math.min(minDiff, d);
        }
        return Math.max(maxSum - minSum, maxDiff - minDiff);
    }
}

