public class LongestBalancedSubstringII {
    static int calc1(String s) {
        int res = 0, i = 0, n = s.length();
        while (i < n) { int j = i + 1; while (j < n && s.charAt(j) == s.charAt(i)) j++; res = Math.max(res, j - i); i = j; }
        return res;
    }
    static int calc2(String s, char a, char b) {
        int res = 0, i = 0, n = s.length();
        while (i < n) {
            while (i < n && s.charAt(i) != a && s.charAt(i) != b) i++;
            Map<Integer, Integer> pos = new HashMap<>();
            pos.put(0, i - 1);
            int d = 0;
            while (i < n && (s.charAt(i) == a || s.charAt(i) == b)) {
                d += (s.charAt(i) == a) ? 1 : -1;
                if (pos.containsKey(d)) res = Math.max(res, i - pos.get(d)); else pos.put(d, i);
                i++;
            }
        }
        return res;
    }
    static int calc3(String s) {
        Map<String, Integer> pos = new HashMap<>();
        pos.put("0,0", -1);
        int ca = 0, cb = 0, cc = 0, res = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == 'a') ca++; else if (c == 'b') cb++; else cc++;
            String key = (ca - cb) + "," + (cb - cc);
            if (pos.containsKey(key)) res = Math.max(res, i - pos.get(key)); else pos.put(key, i);
        }
        return res;
    }
    static int longestBalancedOptimal(String s) {
        int x = calc1(s);
        int y = Math.max(calc2(s, 'a', 'b'), Math.max(calc2(s, 'b', 'c'), calc2(s, 'a', 'c')));
        int z = calc3(s);
        return Math.max(x, Math.max(y, z));
    }
    static int longestBalancedAlgo(String s) {
        int n = s.length(), best = 0;
        for (int i = 0; i < n; i++) {
            Map<Character, Integer> cnt = new HashMap<>();
            for (int j = i; j < n; j++) {
                cnt.merge(s.charAt(j), 1, Integer::sum);
                int first = cnt.values().iterator().next();
                boolean ok = true;
                for (int v : cnt.values()) if (v != first) { ok = false; break; }
                if (ok) best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }
}

