public class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int countWays(int[][] rows) {
        int n = rows.length;
        int max = 0;
        for (int[] row : rows) {
            for (int v : row) {
                if (v > max) max = v;
            }
        }
        int[] mu = mobius(max);
        long answer = 0;
        for (int d = 1; d <= max; d++) {
            long ways = 1;
            for (int i = 0; i < n; i++) {
                int cnt = 0;
                for (int v : rows[i]) {
                    if (v % d == 0) cnt++;
                }
                ways = (ways * cnt) % MOD;
                if (ways == 0) break;
            }
            if (ways != 0 && mu[d] != 0) {
                answer = (answer + mu[d] * ways) % MOD;
            }
        }
        if (answer < 0) answer += MOD;
        return (int) answer;
    }

    private static int[] mobius(int limit) {
        int[] mu = new int[limit + 1];
        int[] spf = new int[limit + 1];
        for (int i = 2; i <= limit; i++) {
            if (spf[i] == 0) {
                for (int j = i; j <= limit; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }
        mu[1] = 1;
        for (int i = 2; i <= limit; i++) {
            int p = spf[i];
            int j = i / p;
            if (j % p == 0) {
                mu[i] = 0;
            } else {
                mu[i] = -mu[j];
            }
        }
        return mu;
    }
}

