class Solution {
    public static long maxAlternatingSumSquares(int[] arr) {
        long[] squares = new long[arr.length];
        for (int i = 0; i < arr.length; i++) {
            squares[i] = (long) arr[i] * arr[i];
        }
        Arrays.sort(squares);
        int left = 0;
        int right = squares.length - 1;
        long total = 0;
        for (int i = 0; i < squares.length; i++) {
            if ((i & 1) == 0) {
                total += squares[right--];
            } else {
                total -= squares[left++];
            }
        }
        return total;
    }
}

