class Solution {
    public static long minOperations(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long base = 0;
        for (int i = 0; i < n; i++) base += Math.abs(nums1[i] - nums2[i]);
        int target = nums2[n];
        long bestExtra = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int lo = Math.min(nums1[i], nums2[i]), hi = Math.max(nums1[i], nums2[i]);
            long extra;
            if (target < lo) extra = lo - target;
            else if (target > hi) extra = target - hi;
            else extra = 0;
            bestExtra = Math.min(bestExtra, extra);
        }
        return base + 1 + bestExtra;
    }
}

class Solution {
    public long countStableSubarrays(int[] capacity) {
        int n = capacity.length;
        long[] s = new long[n+1];
        for (int i = 1; i <= n; i++) s[i] = s[i-1] + capacity[i-1];
        java.util.Map<Integer, java.util.Map<Long,Integer>> cnt = new java.util.HashMap<>();
        long ans = 0;
        for (int r = 2; r < n; r++) {
            int l = r - 2;
            cnt.computeIfAbsent(capacity[l], k -> new java.util.HashMap<>())
               .merge(capacity[l] + s[l+1], 1, Integer::sum);
            java.util.Map<Long,Integer> inner = cnt.get(capacity[r]);
            if (inner != null) ans += inner.getOrDefault(s[r], 0);
        }
        return ans;
    }
}

