import java.util.*;

class Solution {
    private static String answer;

    public static String smallestPalindromicPermutationGreater(String s, String target) {
        if (s.length() != target.length()) {
            return "";
        }
        int n = s.length();
        int half = n / 2;
        boolean odd = (n % 2 == 1);
        int[] cnt = new int[256];
        for (char ch : s.toCharArray()) {
            cnt[ch]++;
        }
        int oddCount = 0;
        for (int v : cnt) {
            if ((v & 1) == 1) oddCount++;
        }
        if (odd) {
            if (oddCount != 1) return "";
        } else {
            if (oddCount != 0) return "";
        }
        answer = null;
        if (dfs(0, false, new StringBuilder(), cnt, half, odd, target)) {
            return answer;
        }
        return "";
    }

    private static boolean dfs(int pos, boolean greater, StringBuilder left, int[] cnt, int half, boolean odd, String target) {
        if (greater) {
            answer = buildSmallest(cnt, left);
            return true;
        }
        if (pos == half) {
            if (odd) {
                int start = target.charAt(half) + 1;
                for (int c = start; c < 256; c++) {
                    if (cnt[c] > 0) {
                        cnt[c]--;
                        if (allEven(cnt)) {
                            StringBuilder sb = new StringBuilder();
                            sb.append(left);
                            sb.append((char) c);
                            sb.append(new StringBuilder(left).reverse());
                            answer = sb.toString();
                            cnt[c]++;
                            return true;
                        }
                        cnt[c]++;
                    }
                }
                return false;
            } else {
                StringBuilder sb = new StringBuilder();
                sb.append(left);
                sb.append(new StringBuilder(left).reverse());
                if (sb.toString().compareTo(target) > 0) {
                    answer = sb.toString();
                    return true;
                }
                return false;
            }
        }
        int start = target.charAt(pos);
        for (int c = start; c < 256; c++) {
            if (cnt[c] >= 2) {
                cnt[c] -= 2;
                left.append((char) c);
                boolean newGreater = greater || (c > target.charAt(pos));
                if (dfs(pos + 1, newGreater, left, cnt, half, odd, target)) {
                    return true;
                }
                left.setLength(left.length() - 1);
                cnt[c] += 2;
            }
        }
        return false;
    }

    private static boolean allEven(int[] cnt) {
        for (int v : cnt) {
            if ((v & 1) == 1) return false;
        }
        return true;
    }

    private static String buildSmallest(int[] cntOrig, StringBuilder left) {
        int[] cnt = cntOrig.clone();
        StringBuilder sb = new StringBuilder();
        sb.append(left);
        char middle = 0;
        for (int i = 0; i < 256; i++) {
            if ((cnt[i] & 1) == 1) {
                middle = (char) i;
                cnt[i]--;
                break;
            }
        }
        for (int i = 0; i < 256; i++) {
            while (cnt[i] >= 2) {
                sb.append((char) i);
                cnt[i] -= 2;
            }
        }
        String leftPart = sb.toString();
        StringBuilder result = new StringBuilder();
        result.append(leftPart);
        if (middle != 0) result.append(middle);
        result.append(new StringBuilder(leftPart).reverse());
        return result.toString();
    }
}

