class Solution {
    public static long countSubarrays(int[] nums, int x) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        pref[0] = 0;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + (nums[i] == x ? 1 : -1);
        }

        int[] all = pref.clone();
        Arrays.sort(all);
        int uniqCount = 0;
        for (int i = 0; i < all.length; i++) {
            if (i == 0 || all[i] != all[i - 1]) {
                uniqCount++;
            }
        }
        int[] uniq = new int[uniqCount];
        int idx = 0;
        for (int i = 0; i < all.length; i++) {
            if (i == 0 || all[i] != all[i - 1]) {
                uniq[idx++] = all[i];
            }
        }

        Map<Integer, Integer> comp = new HashMap<>();
        for (int i = 0; i < uniq.length; i++) {
            comp.put(uniq[i], i + 1); // 1‑based index for BIT
        }

        int[] bit = new int[uniq.length + 2];

        java.util.function.BiConsumer<Integer, Integer> add = (i, delta) -> {
            int index = i;
            while (index < bit.length) {
                bit[index] += delta;
                index += index & -index;
            }
        };

        java.util.function.Function<Integer, Integer> sum = (i) -> {
            int s = 0;
            int index = i;
            while (index > 0) {
                s += bit[index];
                index -= index & -index;
            }
            return s;
        };

        long ans = 0;
        add.accept(comp.get(pref[0]), 1);
        for (int i = 1; i <= n; i++) {
            int curIdx = comp.get(pref[i]);
            ans += sum.apply(curIdx - 1);
            add.accept(curIdx, 1);
        }
        return ans;
    }
}

class Solution {
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public static long minTime(long[] d, long[] r) {
        long d1 = d[0], d2 = d[1], r1 = r[0], r2 = r[1];
        long lcm = r1 / gcd(r1, r2) * r2;
        long lo = 1, hi = 4000000000L;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long a1 = mid - mid/r1;
            long a2 = mid - mid/r2;
            long atotal = mid - mid/lcm;
            boolean ok = a1 >= d1 && a2 >= d2 && atotal >= d1 + d2;
            if (ok) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

class Solution {
    public static long countSubarrays(int[] nums, int target) {
        int n = nums.length;
        int offset = n + 1;
        int size = 2 * n + 3;
        long[] bit = new long[size];
        long pref = 0, ans = 0;
        add(bit, offset, size);
        for (int x : nums) {
            pref += (x == target) ? 1 : -1;
            int idx = (int) (pref + offset);
            ans += query(bit, idx - 1);
            add(bit, idx, size);
        }
        return ans;
    }
    private static void add(long[] bit, int i, int size) {
        for (; i < size; i += i & -i) bit[i]++;
    }
    private static long query(long[] bit, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
}

