class Solution {
    static final long NEG = Long.MIN_VALUE / 4;
    static long linearBest(int[] a, int k) {
        long[][] f = new long[k + 1][3];
        for (long[] r : f) Arrays.fill(r, NEG);
        f[0][1] = 0;
        for (int x : a) {
            long[][] g = new long[k + 1][3];
            for (int i = 0; i <= k; i++) g[i] = f[i].clone();
            for (int c = 0; c <= k; c++) for (int bi = 0; bi < 3; bi++) {
                long cur = f[c][bi];
                if (cur == NEG) continue;
                int b = bi - 1;
                for (int sign : new int[]{1, -1}) {
                    int nb = b + sign;
                    if (nb < -1 || nb > 1) continue;
                    int nc = c + (nb == 0 ? 1 : 0);
                    if (nc > k) continue;
                    long val = cur + (long) sign * x;
                    if (val > g[nc][nb + 1]) g[nc][nb + 1] = val;
                }
            }
            f = g;
        }
        long best = NEG;
        for (int c = 0; c <= k; c++) best = Math.max(best, f[c][1]);
        return best;
    }
    public static long maxCyclicPartitionScore(int[] nums, int k) {
        int n = nums.length;
        long ans = NEG;
        for (int r = 0; r < n; r++) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nums[(r + i) % n];
            ans = Math.max(ans, linearBest(a, k));
        }
        return ans;
    }
}

