public class Solution {
    public static int longestNonDecreasingAfterOneReplace(int[] arr) {
        int n = arr.length;
        if (n <= 2) return n;
        int[] left = new int[n];
        int[] right = new int[n];
        left[0] = 1;
        for (int i = 1; i < n; i++) {
            left[i] = (arr[i] >= arr[i - 1]) ? left[i - 1] + 1 : 1;
        }
        right[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) {
            right[i] = (arr[i] <= arr[i + 1]) ? right[i + 1] + 1 : 1;
        }
        int best = 1;
        for (int i = 0; i < n; i++) {
            best = Math.max(best, left[i]);
        }
        for (int i = 0; i < n; i++) {
            if (i > 0) best = Math.max(best, left[i - 1] + 1);
            if (i < n - 1) best = Math.max(best, right[i + 1] + 1);
            if (i > 0 && i < n - 1 && arr[i - 1] <= arr[i + 1]) {
                best = Math.max(best, left[i - 1] + 1 + right[i + 1]);
            }
        }
        return Math.min(best, n);
    }
}

