        for (int i = 0; i < nums.length; i++) {
            int val = nums[i];
            positions.computeIfAbsent(val, k -> new ArrayList<>()).add(i);
            List<Integer> list = positions.get(val);
            if (list.size() >= 3) {
                int dist = 2 * (list.get(list.size() - 1) - list.get(list.size() - 3));
