class Solution {
    public static int maxPathScore(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        final int NEG = -1000000000;
        int[][][] f = new int[m][n][k+1];
        for (int[][] a : f) for (int[] b : a) java.util.Arrays.fill(b, NEG);
        f[0][0][0] = 0;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) for (int c = 0; c <= k; c++) {
            if (i == 0 && j == 0) continue;
            int cost = grid[i][j] > 0 ? 1 : 0;
            if (c < cost) continue;
            int best = NEG;
            if (i > 0 && f[i-1][j][c-cost] > NEG) best = Math.max(best, f[i-1][j][c-cost]);
            if (j > 0 && f[i][j-1][c-cost] > NEG) best = Math.max(best, f[i][j-1][c-cost]);
            if (best > NEG) f[i][j][c] = best + grid[i][j];
        }
        int ans = NEG;
        for (int c = 0; c <= k; c++) ans = Math.max(ans, f[m-1][n-1][c]);
        return ans <= NEG ? -1 : ans;
    }
}

