class Solution {
    public int maxBalancedSubarray(int[] nums) {
        Map<Long, Integer> first = new HashMap<>();
        first.put(encode(0, 0), 0);
        int xorv = 0, delta = 0, ans = 0;
        for (int i = 0; i < nums.length; i++) {
            xorv ^= nums[i];
            delta += (nums[i] % 2 == 0) ? 1 : -1; // even:+1, odd:-1
            long key = encode(xorv, delta);
            Integer prev = first.get(key);
            if (prev != null) {
                // subarray between the first occurrence of this (xor,delta) state and now has
                // XOR 0 and equal even/odd counts
                ans = Math.max(ans, i + 1 - prev);
            } else {
                first.put(key, i + 1);
            }
        }
        return ans;
    }

    // pack (xorValue, delta) into one collision-safe key (32 bits each, delta can be negative)
    private long encode(int xorv, int delta) {
        return ((long) xorv << 32) | (delta & 0xFFFFFFFFL);
    }
}

