class Solution {
    // Feasibility: total S=n(n+1)/2, need subset T with sum(T)=(S-target)/2 (must be
    // integer in [0,S]). The final answer is just T's values negated, sorted ascending,
    // followed by the remaining values ascending - so we need the T that makes THAT
    // sorted sequence lexicographically smallest.
    // Key insight: a very negative number always beats everything else at whatever
    // position it lands, so greedily try to put the LARGEST remaining number into T
    // (make it negative) first, provided the rest ({1..x-1}, whose subset sums cover
    // every integer in [0, x(x-1)/2]) can still reach the remaining needed sum.
    public long[] lexSmallestPermutation(int n, long target) {
        long S = (long) n * (n + 1) / 2;
        long diff = S - target;
        if (diff < 0 || diff % 2 != 0) return new long[0];
        long D = diff / 2;
        if (D > S) return new long[0];

        boolean[] neg = new boolean[n + 1];
        long rem = D;
        for (int x = n; x >= 1; x--) {
            long maxRemAfter = (long) (x - 1) * x / 2;
            if (x <= rem && (rem - x) <= maxRemAfter) {
                neg[x] = true;
                rem -= x;
            }
        }
        if (rem != 0) return new long[0];

        java.util.List<Long> negs = new java.util.ArrayList<>();
        java.util.List<Long> poss = new java.util.ArrayList<>();
        for (int x = 1; x <= n; x++) {
            if (neg[x]) negs.add((long) -x); else poss.add((long) x);
        }
        java.util.Collections.sort(negs);
        java.util.Collections.sort(poss);
        long[] res = new long[n];
        int idx = 0;
        for (long v : negs) res[idx++] = v;
        for (long v : poss) res[idx++] = v;
        return res;
    }
}

