class Solution {
    static int[] dg;
    static Map<String, long[]> memo;
    static long[] go(int pos, int prev, boolean tight, boolean started) {
        if (pos == dg.length) return new long[]{1, 0};
        String key = pos + "|" + prev + "|" + (tight ? 1 : 0) + "|" + (started ? 1 : 0);
        long[] cached = memo.get(key);
        if (cached != null) return cached;
        long cnt = 0, tot = 0;
        int hi = tight ? dg[pos] : 9;
        for (int d = 0; d <= hi; d++) {
            boolean ntight = tight && (d == hi);
            boolean nstarted = started || d > 0;
            long add = started ? Math.abs(prev - d) : 0;
            long[] r = go(pos + 1, nstarted ? d : -1, ntight, nstarted);
            cnt += r[0]; tot += r[1] + add * r[0];
        }
        long[] res = new long[]{cnt, tot};
        memo.put(key, res);
        return res;
    }
    static long upTo(long N) {
        if (N < 0) return 0;
        String s = Long.toString(N);
        dg = new int[s.length()];
        for (int i = 0; i < s.length(); i++) dg[i] = s.charAt(i) - '0';
        memo = new HashMap<>();
        return go(0, -1, true, false)[1];
    }
    public static long totalWaviness(long L, long R) { return upTo(R) - upTo(L - 1); }
}

