class Solution {
    public static long concatenateNonZeroMultiplySum(long N) {
        String str = Long.toString(N);
        long sum = 0;
        StringBuilder concat = new StringBuilder();
        for (int i = 0; i < str.length(); i++) {
            int d = str.charAt(i) - '0';
            sum += d;
            if (d != 0) {
                concat.append((char) (d + '0'));
            }
        }
        if (concat.length() == 0) {
            return 0L;
        }
        BigInteger nonZeroNumber = new BigInteger(concat.toString());
        BigInteger result = nonZeroNumber.multiply(BigInteger.valueOf(sum));
        return result.longValue();
    }
}

