import java.util.*;

class Solution {
    static final long MOD = 1000000007L;

    public int numberOfEffectiveSubsequences(int[] nums) {
        int n = nums.length;
        int maxVal = 0;
        for (int v : nums) maxVal = Math.max(maxVal, v);
        int B = 1;
        while ((1 << B) <= maxVal) B++;
        int size = 1 << B;
        int fullmask = size - 1;

        long[] subsetSum = new long[size];
        for (int v : nums) subsetSum[v]++;
        for (int bit = 0; bit < B; bit++) {
            for (int mask = 0; mask < size; mask++) {
                if ((mask & (1 << bit)) != 0) {
                    subsetSum[mask] += subsetSum[mask ^ (1 << bit)];
                }
            }
        }

        int activeBits = 0;
        for (int v : nums) activeBits |= v;

        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) pow2[i] = (pow2[i-1] * 2) % MOD;

        long answer = 0;
        int submask = activeBits;
        while (submask > 0) {
            int bitsSet = Integer.bitCount(submask);
            long elementsWithNone = subsetSum[fullmask ^ submask];
            long forced = n - elementsWithNone;
            long ways = pow2[(int)(n - forced)];
            if (bitsSet % 2 == 1) {
                answer = (answer + ways) % MOD;
            } else {
                answer = (answer - ways + MOD) % MOD;
            }
            submask = (submask - 1) & activeBits;
        }
        return (int)(answer % MOD);
    }
}

