class Solution {
    private static boolean isBinaryPalindrome(int x) {
        String b = Integer.toBinaryString(x);
        return b.equals(new StringBuilder(b).reverse().toString());
    }
    public static int[] minOperationsToMakeBinaryPalindrome(int[] nums) {
        int[] result = new int[nums.length];
        for (int k = 0; k < nums.length; k++) {
            int n = nums[k];
            int d = 0;
            while (true) {
                if (n - d >= 1 && isBinaryPalindrome(n - d)) { result[k] = d; break; }
                if (isBinaryPalindrome(n + d)) { result[k] = d; break; }
                d++;
            }
        }
        return result;
    }
}

