        int[] sorted = arr.clone();
        Arrays.sort(sorted);
        Map<Integer, Integer> comp = new HashMap<>();
        int rank = 1;
        for (int val : sorted) {
            if (!comp.containsKey(val)) {
                comp.put(val, rank++);
            }
        }

        int size = comp.size();
        long[] bit = new long[size + 1];

        java.util.function.BiConsumer<Integer, Integer> add = (idx, delta) -> {
            int i = idx;
            while (i <= size) {
                bit[i] += delta;
                i += i & -i;
            }
        };

        java.util.function.Function<Integer, Long> sum = (idx) -> {
            long res = 0;
            int i = idx;
            while (i > 0) {
                res += bit[i];
                i -= i & -i;
            }
            return res;
        };

        long inv = 0;
        for (int i = 0; i < k; i++) {
            int idx = comp.get(arr[i]);
            inv += i - sum.apply(idx);
            add.accept(idx, 1);
        }

        long best = inv;

        for (int left = 0, right = k; right < n; left++, right++) {
            int outIdx = comp.get(arr[left]);
            long lessThanOut = sum.apply(outIdx - 1);
            inv -= lessThanOut;
            add.accept(outIdx, -1);

            int inIdx = comp.get(arr[right]);
            long greaterThanIn = (k - 1) - sum.apply(inIdx);
            inv += greaterThanIn;
            add.accept(inIdx, 1);

            if (inv < best) best = inv;
        }

        return best;
    }
}

class Solution {
