public class Solution {
    public static int[] sortByBinaryReflection(int[] arr) {
        int n = arr.length;
        Pair[] withReflection = new Pair[n];
        for (int i = 0; i < n; i++) {
            int num = arr[i];
            String binary = Integer.toBinaryString(num);
