                if (a.reflected != b.reflected) return a.reflected - b.reflected;
                return a.original - b.original;
            }
        });
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            result[i] = withReflection[i].original;
        }
        return result;
    }

    private static class Pair {
        int original;
        int reflected;
        Pair(int original, int reflected) {
            this.original = original;
            this.reflected = reflected;
        }
    }
}

