class Solution {
    public static long maxScore(int[] technique1, int[] technique2, int k) {
        int n = technique1.length;
        long total = 0;
        int natural = 0;
        List<Integer> losses = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int a = technique1[i], b = technique2[i];
            total += Math.max(a, b);
            if (a >= b) natural++;
            else losses.add(b - a);
        }
        int need = Math.max(0, k - natural);
        Collections.sort(losses);
        for (int i = 0; i < need && i < losses.size(); i++) total -= losses.get(i);
        return total;
    }
}

class Solution {
    private boolean isPrime(long x) {
        if (x < 2) return false;
        if (x < 4) return true;
        if (x % 2 == 0) return false;
        for (long i = 3; i * i <= x; i += 2) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public int largestPrime(int n) {
        int best = 0;
        long total = 0;
        for (int p = 2; total <= n; p++) {
            if (!isPrime(p)) continue;
            total += p;
            if (total > n) break;
            if (isPrime(total)) best = (int) total;
        }
        return best;
    }
}

