class Solution {
    public long minMoves(int[] balance) {
        int n = balance.length;
        long total = 0;
        for (int b : balance) total += b;
        if (total < 0) return -1;
        int mn = balance[0], idx = 0;
        for (int i = 1; i < n; i++) {
            if (balance[i] < mn) { mn = balance[i]; idx = i; }
        }
        if (mn >= 0) return 0;
        long deficit = -mn;
        List<long[]> leftAvail = new ArrayList<>();
        List<long[]> rightAvail = new ArrayList<>();
        for (int j = 1; j < n; j++) {
            int li = ((idx - j) % n + n) % n;
            int ri = (idx + j) % n;
            if (balance[li] > 0) leftAvail.add(new long[]{j, balance[li]});
            if (balance[ri] > 0) rightAvail.add(new long[]{j, balance[ri]});
        }
        int li = 0, ri = 0;
        long moves = 0;
        while (deficit > 0) {
            boolean canLeft = li < leftAvail.size();
            boolean canRight = ri < rightAvail.size();
            if (!canLeft && !canRight) break;
            if (canLeft && (!canRight || leftAvail.get(li)[0] <= rightAvail.get(ri)[0])) {
                long dist = leftAvail.get(li)[0], amt = leftAvail.get(li)[1];
                long take = Math.min(amt, deficit);
                moves += take * dist;
                deficit -= take;
                leftAvail.get(li)[1] -= take;
                if (leftAvail.get(li)[1] == 0) li++;
            } else {
                long dist = rightAvail.get(ri)[0], amt = rightAvail.get(ri)[1];
                long take = Math.min(amt, deficit);
                moves += take * dist;
                deficit -= take;
                rightAvail.get(ri)[1] -= take;
                if (rightAvail.get(ri)[1] == 0) ri++;
            }
        }
        return moves;
    }
}

