class Solution {
    public static int[] minDeletionsToMakeAlternatingSubstring(String s, int[][] queries) {
        int n = s.length();
        char[] chars = s.toCharArray();
        int[] bit = new int[n + 2];
        List<Integer> answers = new ArrayList<>();

        for (int i = 1; i < n; i++) {
            if (chars[i] == chars[i - 1]) add(bit, n, i + 1, 1);
        }

        for (int[] q : queries) {
            if (q[0] == 1) {
                int j = q[1];
                char newChar = (chars[j] == 'A') ? 'B' : 'A';
                if (j > 0) {
                    int oldEq = (chars[j] == chars[j-1]) ? 1 : 0;
                    int newEq = (newChar == chars[j-1]) ? 1 : 0;
                    if (oldEq != newEq) add(bit, n, j + 1, newEq - oldEq);
                }
                if (j + 1 < n) {
                    int oldEq = (chars[j+1] == chars[j]) ? 1 : 0;
                    int newEq = (chars[j+1] == newChar) ? 1 : 0;
                    if (oldEq != newEq) add(bit, n, j + 2, newEq - oldEq);
                }
                chars[j] = newChar;
            } else {
                int l = q[1], r = q[2];
                if (l >= r) answers.add(0);
                else answers.add(rangeSum(bit, l + 2, r + 1));
            }
        }
        int[] result = new int[answers.size()];
        for (int i = 0; i < result.length; i++) result[i] = answers.get(i);
        return result;
    }
    private static void add(int[] bit, int n, int i, int delta) {
        for (; i <= n; i += i & -i) bit[i] += delta;
    }
    private static int sum(int[] bit, int i) {
        int r = 0; for (; i > 0; i -= i & -i) r += bit[i]; return r;
    }
    private static int rangeSum(int[] bit, int l, int r) {
        return l > r ? 0 : sum(bit, r) - sum(bit, l - 1);
    }
}

class Solution {
