class Solution {
    public static long minimumDeletionCost(String s, int[] cost) {
        long totalCost = 0;
        Map<Character, Long> charCost = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int c = cost[i];
            totalCost += c;
            charCost.put(ch, charCost.getOrDefault(ch, 0L) + c);
        }
        long maxKeep = 0;
        for (long sum : charCost.values()) {
            if (sum > maxKeep) {
                maxKeep = sum;
            }
        }
        return totalCost - maxKeep;
    }
}

