class Solution {
    public static int minimumSwaps(int[] arr, int[] forbidden) {
        int n = arr.length;
        Map<Integer, Integer> cntArr = new HashMap<>();
        Map<Integer, Integer> cntForbidden = new HashMap<>();
        for (int i = 0; i < n; i++) {
            cntArr.merge(arr[i], 1, Integer::sum);
            cntForbidden.merge(forbidden[i], 1, Integer::sum);
        }
        for (Map.Entry<Integer, Integer> e : cntArr.entrySet()) {
            int v = e.getKey();
            int cnt = e.getValue();
            int forbiddenCnt = cntForbidden.getOrDefault(v, 0);
            if (cnt > n - forbiddenCnt) {
                return -1;
            }
        }
        int bad = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] == forbidden[i]) bad++;
        }
        if (bad == 0) return 0;
        return (bad + 1) / 2;
    }
}

