class Solution {
    public static int lastInteger(int n) {
        long head = 1;
        long step = 1;
        int remaining = n;
        boolean leftToRight = true;
        while (remaining > 1) {
            if (!leftToRight && (remaining % 2 == 0)) {
                head += step;
            }
            step <<= 1;
            remaining = (remaining + 1) >> 1;
            leftToRight = !leftToRight;
        }
        return (int) head;
    }
}

