class Solution {
    public static int maxSumDivisibleByThree(int[] nums) {
        List<Integer> rem0 = new ArrayList<>();
        List<Integer> rem1 = new ArrayList<>();
        List<Integer> rem2 = new ArrayList<>();
        for (int v : nums) {
            int r = v % 3;
            if (r == 0) {
                rem0.add(v);
            } else if (r == 1) {
                rem1.add(v);
            } else {
                rem2.add(v);
            }
        }
        Comparator<Integer> desc = Collections.reverseOrder();
        rem0.sort(desc);
        rem1.sort(desc);
        rem2.sort(desc);
        List<Integer> candidates = new ArrayList<>();
        if (rem0.size() >= 3) {
            candidates.add(rem0.get(0) + rem0.get(1) + rem0.get(2));
        }
        if (rem1.size() >= 3) {
            candidates.add(rem1.get(0) + rem1.get(1) + rem1.get(2));
        }
        if (rem2.size() >= 3) {
            candidates.add(rem2.get(0) + rem2.get(1) + rem2.get(2));
        }
        if (!rem0.isEmpty() && !rem1.isEmpty() && !rem2.isEmpty()) {
            candidates.add(rem0.get(0) + rem1.get(0) + rem2.get(0));
        }
        return candidates.isEmpty() ? 0 : Collections.max(candidates);
    }
}

