public class NumberOfBalancedIntegers {
    static long countUpTo(long n) {
        if (n < 11) return 0;
        String s = Long.toString(n);
        int len = s.length();
        Map<String, Long> memo = new HashMap<>();
        Object[] holder = new Object[1];
        class Solver {
            long dfs(int pos, int diff, boolean tight, boolean started, boolean parityOdd) {
                if (pos == len) return (started && diff == 0) ? 1 : 0;
                String key = pos + "," + diff + "," + started + "," + parityOdd;
                if (!tight && memo.containsKey(key)) return memo.get(key);
                int limit = tight ? (s.charAt(pos) - '0') : 9;
                long res = 0;
                for (int d = 0; d <= limit; d++) {
                    if (!started && d == 0) {
                        res += dfs(pos + 1, diff, tight && d == limit, false, true);
                    } else {
                        int delta = parityOdd ? -d : d;
                        res += dfs(pos + 1, diff + delta, tight && d == limit, true, !parityOdd);
                    }
                }
                if (!tight) memo.put(key, res);
                return res;
            }
        }
        return new Solver().dfs(0, 0, true, false, true);
    }
    static long numberOfBalancedIntegersOptimal(long low, long high) {
        if (high < 11) return 0;
        low = Math.max(low, 11);
        return countUpTo(high) - countUpTo(low - 1);
    }
    static boolean isBalancedNum(long n) {
        String s = Long.toString(n);
        if (s.length() < 2) return false;
        long evenSum = 0, oddSum = 0;
        for (int i = 0; i < s.length(); i++) {
            int pos = i + 1;
            if (pos % 2 == 0) evenSum += s.charAt(i) - '0'; else oddSum += s.charAt(i) - '0';
        }
        return evenSum == oddSum;
    }
    static long numberOfBalancedIntegersAlgo(long low, long high) {
        long cnt = 0;
        for (long n = low; n <= high; n++) if (isBalancedNum(n)) cnt++;
        return cnt;
    }
}

class Solution {
    public long maximumScore(int[] nums) {
        int n = nums.length;
        long best = Long.MIN_VALUE;
        for (int i = 0; i < n - 1; i++) {
            long prefix = 0;
            for (int k = 0; k <= i; k++) prefix += nums[k];
            long sufMin = Long.MAX_VALUE;
            for (int k = i + 1; k < n; k++) sufMin = Math.min(sufMin, nums[k]);
            best = Math.max(best, prefix - sufMin);
        }
        return best;
    }
}

