class Solution {
    public static long numberOfRoutes(String[] grid, int d) {
        final long MOD = 1000000007L;
        int n = grid.length, m = grid[0].length();
        long wUpSq = (long) d * d - 1;
        long wUp = -1;
        if (wUpSq >= 0) {
            wUp = (long) Math.sqrt((double) wUpSq);
            while (wUp >= 0 && wUp * wUp > wUpSq) wUp--;
            while ((wUp + 1) * (wUp + 1) <= wUpSq) wUp++;
        }
        long wStay = d;

        long[] dpUp = new long[m];
        long[] dpStay = new long[m];
        for (int c = 0; c < m; c++) if (grid[n-1].charAt(c) == '.') dpUp[c] = 1;

        for (int r = n - 1; r > 0; r--) {
            long[] preUp = new long[m + 1];
            for (int c = 0; c < m; c++) preUp[c+1] = (preUp[c] + dpUp[c]) % MOD;
            long[] newStay = new long[m];
            for (int c = 0; c < m; c++) {
                if (grid[r].charAt(c) != '.') continue;
                int lo = Math.max(0, (int)(c - wStay)), hi = Math.min(m - 1, (int)(c + wStay));
                long total = (preUp[hi+1] - preUp[lo] + MOD) % MOD;
                total = (total - dpUp[c] + MOD) % MOD;
                newStay[c] = total;
            }
            dpStay = newStay;

            long[] combined = new long[m];
            for (int c = 0; c < m; c++) combined[c] = (dpUp[c] + dpStay[c]) % MOD;
            long[] preComb = new long[m + 1];
            for (int c = 0; c < m; c++) preComb[c+1] = (preComb[c] + combined[c]) % MOD;

            long[] newUp = new long[m];
            for (int c = 0; c < m; c++) {
                if (grid[r-1].charAt(c) != '.' || wUp < 0) continue;
                int lo = Math.max(0, (int)(c - wUp)), hi = Math.min(m - 1, (int)(c + wUp));
                newUp[c] = (preComb[hi+1] - preComb[lo] + MOD) % MOD;
            }
            dpUp = newUp;
            dpStay = new long[m];
        }

        long[] preUp0 = new long[m + 1];
        for (int c = 0; c < m; c++) preUp0[c+1] = (preUp0[c] + dpUp[c]) % MOD;
        long[] dpStay0 = new long[m];
        for (int c = 0; c < m; c++) {
            if (grid[0].charAt(c) != '.') continue;
            int lo = Math.max(0, (int)(c - wStay)), hi = Math.min(m - 1, (int)(c + wStay));
            long total = (preUp0[hi+1] - preUp0[lo] + MOD) % MOD;
            dpStay0[c] = (total - dpUp[c] + MOD) % MOD;
        }

        long ans = 0;
        for (int c = 0; c < m; c++) ans = (ans + dpUp[c] + dpStay0[c]) % MOD;
        return ans;
    }
}

class Solution {
    public static String reversePrefix(String s, int k) {
        char[] chars = s.toCharArray();
        int left = 0, right = k - 1;
        while (left < right) { char t = chars[left]; chars[left] = chars[right]; chars[right] = t; left++; right--; }
        return new String(chars);
    }
}

import java.util.*;

class Solution {
    public static int minSubarrayLength(int[] arr, int K) {
        int left = 0;
        long distinctSum = 0;
        Map<Integer, Integer> freq = new HashMap<>();
        int best = Integer.MAX_VALUE;

        for (int right = 0; right < arr.length; right++) {
            int val = arr[right];
            int cnt = freq.getOrDefault(val, 0);
            freq.put(val, cnt + 1);
            if (cnt == 0) distinctSum += val;

            while (distinctSum >= K) {
                best = Math.min(best, right - left + 1);
                int leftVal = arr[left];
                int leftCnt = freq.get(leftVal);
                if (leftCnt == 1) distinctSum -= leftVal;
                if (leftCnt == 1) freq.remove(leftVal);
                else freq.put(leftVal, leftCnt - 1);
                left++;
            }
        }

        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

import java.util.*;
class Solution {
    public static long maxValueOfSequence(int n, int[][] restrictions, int[] diff) {
        long INF = Long.MAX_VALUE/2;
        long[] a = new long[n]; Arrays.fill(a, INF);
        a[0] = 0;
        for (int[] r : restrictions) a[r[0]] = Math.min(a[r[0]], (long) r[1]);
        for (int i = 1; i < n; i++) a[i] = Math.min(a[i], a[i-1] + diff[i-1]);
        for (int i = n-2; i >= 0; i--) a[i] = Math.min(a[i], a[i+1] + diff[i]);
        long mx = Long.MIN_VALUE;
        for (long x : a) mx = Math.max(mx, x);
        return mx;
    }
}

import java.util.*;
class Solution {
    public int minCost(List<List<Integer>> lists) {
        int n = lists.size();
        int full = 1 << n;
        List<Integer>[] sortedArr = new List[full];
        sortedArr[0] = new ArrayList<>();
        for (int mask = 1; mask < full; mask++) {
            int low = mask & (-mask);
            int idx = Integer.numberOfTrailingZeros(low);
            List<Integer> a = sortedArr[mask ^ low];
            List<Integer> b = lists.get(idx);
            List<Integer> merged = new ArrayList<>();
            int i = 0, j = 0;
            while (i < a.size() && j < b.size()) {
                if (a.get(i) <= b.get(j)) merged.add(a.get(i++));
                else merged.add(b.get(j++));
            }
            while (i < a.size()) merged.add(a.get(i++));
            while (j < b.size()) merged.add(b.get(j++));
            sortedArr[mask] = merged;
        }
        long INF = Long.MAX_VALUE / 2;
        long[] dp = new long[full];
        for (int mask = 1; mask < full; mask++) {
            if ((mask & (mask - 1)) == 0) { dp[mask] = 0; continue; }
            long best = INF;
            for (int sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask) {
                int comp = mask ^ sub;
                if (comp == 0) continue;
                List<Integer> A = sortedArr[sub], B = sortedArr[comp];
                int medA = A.get((A.size() - 1) / 2);
                int medB = B.get((B.size() - 1) / 2);
                long cost = dp[sub] + dp[comp] + A.size() + B.size() + Math.abs(medA - medB);
                if (cost < best) best = cost;
            }
            dp[mask] = best;
        }
        return (int) dp[full - 1];
    }
}

class Solution {
    public static long minimumCost(String s, String t, long flipCost, long swapCost, long crossCost) {
        long diff0 = 0, diff1 = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != t.charAt(i)) { if (s.charAt(i) == '0') diff0++; else diff1++; }
        }
        long mx = Math.max(diff0, diff1), mn = Math.min(diff0, diff1);
        long ans = (diff0 + diff1) * flipCost;
        ans = Math.min(ans, mn * swapCost + (mx - mn) * flipCost);
        long avg = (mx + mn) / 2;
        ans = Math.min(ans, (avg - mn) * crossCost + avg * swapCost + (mx + mn - avg * 2) * flipCost);
        return ans;
    }
}

