class Solution {
    public List<List<String>> wordSquares(String[] words) {
        int n = words.length;
        List<List<String>> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String top = words[i];
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                String left = words[j];
                if (top.charAt(0) != left.charAt(0)) continue;
                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) continue;
                    String right = words[k];
                    if (top.charAt(3) != right.charAt(0)) continue;
                    for (int h = 0; h < n; h++) {
                        if (h == i || h == j || h == k) continue;
                        String bottom = words[h];
                        if (bottom.charAt(0) == left.charAt(3) && bottom.charAt(3) == right.charAt(3)) {
                            res.add(Arrays.asList(top, left, right, bottom));
                        }
                    }
                }
            }
        }
        res.sort((a, b) -> {
            for (int idx = 0; idx < 4; idx++) {
                int c = a.get(idx).compareTo(b.get(idx));
                if (c != 0) return c;
            }
            return 0;
        });
        return res;
    }
}

