import java.util.*;
class Solution {
    public static long maximumAND(long[] nums, long k, int m) {
        long mxVal = 0; for (long x : nums) mxVal = Math.max(mxVal, x); mxVal += k;
        int mx = 0; long tmp = mxVal;
        while (tmp > 0) { mx++; tmp >>= 1; }
        long ans = 0;
        long[] cost = new long[nums.length];
        for (int bit = mx - 1; bit >= 0; bit--) {
            long target = ans | (1L << bit);
            for (int i = 0; i < nums.length; i++) {
                long x = nums[i];
                long val = target & (~x);
                int j = 0; long v2 = val;
                while (v2 > 0) { j++; v2 >>= 1; }
                long mask = (1L << j) - 1;
                cost[i] = (target & mask) - (x & mask);
            }
            long[] sorted = cost.clone();
            Arrays.sort(sorted);
            long sum = 0;
            for (int i = 0; i < m; i++) sum += sorted[i];
            if (sum <= k) ans = target;
        }
        return ans;
    }
}

