class AuctionSystem {
    private final Map<Integer, Map<Integer, Integer>> items = new HashMap<>();

    public void addBid(int userId, int itemId, int bidAmount) {
        items.computeIfAbsent(itemId, k -> new HashMap<>()).put(userId, bidAmount);
    }
    public void updateBid(int userId, int itemId, int newAmount) {
        items.get(itemId).put(userId, newAmount);
    }
    public void removeBid(int userId, int itemId) {
        items.get(itemId).remove(userId);
    }
    public int getHighestBidder(int itemId) {
        Map<Integer, Integer> bids = items.get(itemId);
        if (bids == null || bids.isEmpty()) return -1;
        int bestUser = -1, bestAmt = -1;
        for (Map.Entry<Integer, Integer> e : bids.entrySet()) {
            int uid = e.getKey(), amt = e.getValue();
            if (amt > bestAmt || (amt == bestAmt && uid > bestUser)) {
                bestAmt = amt;
                bestUser = uid;
            }
        }
        return bestUser;
    }
}

