class Solution {
    static int[] bfsDist(int n, List<List<Integer>> adj, int src) {
        int[] dist = new int[n]; Arrays.fill(dist, -1);
        dist[src] = 0;
        Deque<Integer> q = new ArrayDeque<>(); q.add(src);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj.get(u)) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.add(v); }
        }
        return dist;
    }
    public static int countPythagoreanNodes(int n, int[][] edges, int x, int y, int z) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] dx = bfsDist(n, adj, x), dy = bfsDist(n, adj, y), dz = bfsDist(n, adj, z);
        int count = 0;
        for (int u = 0; u < n; u++) {
            int[] a = {dx[u], dy[u], dz[u]};
            Arrays.sort(a);
            if (a[0]*a[0] + a[1]*a[1] == a[2]*a[2]) count++;
        }
        return count;
    }
