class Solution {
    long[] prefix, dpPrev, dpCur;

    long cost(int p, int i) {
        long s = prefix[i] - prefix[p];
        return s*(s+1)/2;
    }

    void compute(int lo, int hi, int optlo, int opthi) {
        if (lo > hi) return;
        int mid = (lo+hi)/2;
        long bestVal = Long.MAX_VALUE;
        int bestP = -1;
        int pHi = Math.min(opthi, mid-1);
        for (int p = optlo; p <= pHi; p++) {
            if (dpPrev[p] == Long.MAX_VALUE) continue;
            long val = dpPrev[p] + cost(p, mid);
            if (val < bestVal) { bestVal = val; bestP = p; }
        }
        dpCur[mid] = bestVal;
        if (bestP == -1) bestP = optlo;
        compute(lo, mid-1, optlo, bestP);
        compute(mid+1, hi, bestP, opthi);
    }

    public long minimumScore(int[] nums, int k) {
        int n = nums.length;
        prefix = new long[n+1];
        for (int i = 0; i < n; i++) prefix[i+1] = prefix[i] + nums[i];
        dpPrev = new long[n+1];
        java.util.Arrays.fill(dpPrev, Long.MAX_VALUE);
        dpPrev[0] = 0;
        for (int j = 1; j <= k; j++) {
            dpCur = new long[n+1];
            java.util.Arrays.fill(dpCur, Long.MAX_VALUE);
            compute(j, n, j-1, n-1);
            dpPrev = dpCur;
        }
        return dpPrev[n];
    }
}

import java.util.*;
class Solution {
    public int longestSubsequence(int[] nums) {
        int ans = 0;
        // any subsequence with non-zero AND has SOME bit set in every element; conversely, restricting
        // to elements with a fixed bit set and finding LIS among just those automatically has that bit
        // in the AND. So try every bit position and take the best LIS.
        for (int bit = 0; bit < 30; bit++) {
            List<Integer> filtered = new ArrayList<>();
            for (int x : nums) if ((x & (1 << bit)) != 0) filtered.add(x);
            ans = Math.max(ans, lisLength(filtered));
        }
        return ans;
    }

    private int lisLength(List<Integer> arr) {
        List<Integer> tails = new ArrayList<>();
        for (int x : arr) {
            int idx = Collections.binarySearch(tails, x);
            if (idx < 0) idx = -(idx + 1);
            if (idx == tails.size()) tails.add(x);
            else tails.set(idx, x);
        }
        return tails.size();
    }
}

class Solution {
    static final int MX = 51;
    static long[][] C = new long[MX][MX + 1];
    static {
        for (int i = 0; i < MX; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }
    // Build answer bit by bit from position 49 down to 0. For bit i, C[i][k] counts
    // how many valid numbers have bit i = 0 (remaining k ones chosen from lower i bits).
    // If n exceeds that count, bit i must be 1 in the answer; consume that block from n.
    public long nthSmallest(long n, int k) {
        long ans = 0;
        for (int i = 49; i >= 0 && k > 0; i--) {
            long cnt = (i >= k) ? C[i][k] : 0;
            if (n > cnt) {
                n -= cnt;
                ans |= (1L << i);
                k--;
            }
        }
        return ans;
    }
}

public class Solution {
    public static String reverseLettersThenSpecials(String s) {
        char[] chars = s.toCharArray();
        int left = 0, right = chars.length - 1;
        while (left < right) {
            while (left < right && !isAsciiLetter(chars[left])) left++;
            while (left < right && !isAsciiLetter(chars[right])) right--;
            if (left < right) {
                char tmp = chars[left];
                chars[left] = chars[right];
                chars[right] = tmp;
                left++;
                right--;
            }
        }
        left = 0;
        right = chars.length - 1;
        while (left < right) {
            while (left < right && isAsciiLetter(chars[left])) left++;
            while (left < right && isAsciiLetter(chars[right])) right--;
            if (left < right) {
                char tmp = chars[left];
                chars[left] = chars[right];
                chars[right] = tmp;
                left++;
                right--;
            }
        }
        return new String(chars);
    }
    private static boolean isAsciiLetter(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    }
}

