class Solution {
    public static int minK(int[] nums, int limit) {
        long total = 0;
        int maxVal = 0;
        for (int v : nums) {
            total += v;
            if (v > maxVal) maxVal = v;
        }
        if (total <= limit) return 0;
        int low = 0, high = maxVal;
        while (low < high) {
            int mid = (low + high) / 2;
            long reducedSum = 0;
            for (int v : nums) {
                if (v > mid) reducedSum += v - mid;
            }
            if (reducedSum <= limit) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

