class Solution {
    public static List<Integer> mergeAdjacent(int[] arr) {
        List<Integer> stack = new ArrayList<>();
        for (int i = 0; i < arr.length; i++) {
            stack.add(arr[i]);
            while (stack.size() >= 2) {
                int top = stack.get(stack.size() - 1);
                int next = stack.get(stack.size() - 2);
                if (top != next) break;
                stack.remove(stack.size() - 1);
                stack.remove(stack.size() - 1);
                stack.add(top + next);
            }
        }
        return stack;
    }
}

class Solution {
    public int dominantIndices(int[] nums) {
        int n = nums.length;
        int ans = 0;
        long sufSum = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            int cnt = n - i - 1;
            // cross-multiply instead of dividing to avoid floating-point precision issues
            if ((long) nums[i] * cnt > sufSum) ans++;
            sufSum += nums[i];
        }
        return ans;
    }
}

class Solution {
    public long countSubarrays(int[] nums, long k) {
        long ans = 0;
        Deque<Integer> q1 = new ArrayDeque<>();
        Deque<Integer> q2 = new ArrayDeque<>();
        int l = 0;
        for (int r = 0; r < nums.length; r++) {
            int x = nums[r];
            while (!q1.isEmpty() && nums[q1.peekLast()] <= x) q1.pollLast();
            while (!q2.isEmpty() && nums[q2.peekLast()] >= x) q2.pollLast();
            q1.addLast(r); q2.addLast(r);
            while (l < r && (long)(nums[q1.peekFirst()] - nums[q2.peekFirst()]) * (r - l + 1) > k) {
                l++;
                if (q1.peekFirst() < l) q1.pollFirst();
                if (q2.peekFirst() < l) q2.pollFirst();
            }
            ans += r - l + 1;
        }
        return ans;
    }
}

