class Solution {
    public int numberOfPrefixConnectedGroups(String[] words, int k) {
        Map<String,Integer> cnt = new HashMap<>();
        for (String w : words) if (w.length() >= k) cnt.merge(w.substring(0,k), 1, Integer::sum);
        int ans = 0;
        for (int v : cnt.values()) if (v >= 2) ans++;
        return ans;
    }
}

class Solution {
    static long[] fact = new long[10];
    static {
        fact[0] = 1;
        for (int i = 1; i <= 9; i++) fact[i] = fact[i - 1] * i;
    }

    public boolean isDigitorialPermutation(int n) {
        // digit-factorial sum is invariant under permutation, so just compute it once for n
        long sum = 0;
        int[] cntN = new int[10];
        int x = n;
        while (x > 0) {
            int d = x % 10;
            cntN[d]++;
            sum += fact[d];
            x /= 10;
        }
        // if the digit multisets of n and sum match, sum itself (written normally, no leading
        // zero issue since it's a positive integer) IS a valid permutation of n's digits
        int[] cntSum = new int[10];
        long s = sum;
        do {
            int d = (int) (s % 10);
            cntSum[d]++;
            s /= 10;
        } while (s > 0);
        for (int i = 0; i < 10; i++) if (cntN[i] != cntSum[i]) return false;
        return true;
    }
}

import java.util.*;

public class P7 {
    static List<Boolean> solve(int n, int[][] edges, String s, String[] queries) {
        int LOG = Math.max(1, (int)Math.ceil(Math.log(n+1)/Math.log(2)));
        List<List<Integer>> adj = new ArrayList<>();
        for (int i=0;i<n;i++) adj.add(new ArrayList<>());
        for (int[] e: edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] charBit = new int[n];
        for (int i=0;i<n;i++) charBit[i] = 1 << (s.charAt(i)-'a');
        int[][] up = new int[n][LOG];
        int[] depth = new int[n], tin = new int[n], tout = new int[n], initMask = new int[n];
        int[] timer = {0};
        Deque<int[]> stk = new ArrayDeque<>();
        stk.push(new int[]{0,-1,0});
        while (!stk.isEmpty()) {
            int[] cur = stk.pop();
            int node = cur[0], parent = cur[1], state = cur[2];
            if (state == 0) {
                tin[node] = timer[0]++;
                up[node][0] = parent != -1 ? parent : node;
                for (int k=1;k<LOG;k++) up[node][k] = up[up[node][k-1]][k-1];
                depth[node] = parent == -1 ? 0 : depth[parent]+1;
                initMask[node] = (parent != -1 ? initMask[parent] : 0) ^ charBit[node];
                stk.push(new int[]{node,parent,1});
                for (int nb : adj.get(node)) if (nb != parent) stk.push(new int[]{nb,node,0});
            } else {
                tout[node] = timer[0]-1;
            }
        }
        int[] bit = new int[n+1];
        int finalLOG = LOG;
        java.util.function.BiFunction<Integer,Integer,Integer> lca = null;
        // implement lca inline via lambda referencing arrays
        int[] depthArr = depth;
        int[][] upArr = up;
        java.util.function.IntBinaryOperator lcaFn = (u,v) -> {
            int uu=u, vv=v;
            if (depthArr[uu] < depthArr[vv]) { int t=uu; uu=vv; vv=t; }
            int diff = depthArr[uu]-depthArr[vv], b=0;
            while (diff != 0) { if ((diff&1)!=0) uu = upArr[uu][b]; diff >>= 1; b++; }
            if (uu == vv) return uu;
            for (int k=finalLOG-1;k>=0;k--) if (upArr[uu][k] != upArr[vv][k]) { uu = upArr[uu][k]; vv = upArr[vv][k]; }
            return upArr[uu][0];
        };
        List<Boolean> answers = new ArrayList<>();
        for (String q : queries) {
            String[] parts = q.split(" ");
            if (parts[0].equals("update")) {
                int node = Integer.parseInt(parts[1]);
                int newBit = 1 << (parts[2].charAt(0)-'a');
                int oldBit = charBit[node];
                if (newBit != oldBit) {
                    int delta = oldBit ^ newBit;
                    int i = tin[node]+1; while (i<=n) { bit[i]^=delta; i += i&(-i); }
                    if (tout[node]+1 < n) { i = tout[node]+2; while (i<=n) { bit[i]^=delta; i += i&(-i); } }
                    charBit[node] = newBit;
                }
            } else {
                int u = Integer.parseInt(parts[1]), v = Integer.parseInt(parts[2]);
                int w = lcaFn.applyAsInt(u,v);
                int maskU = initMask[u] ^ bitPrefix(bit, tin[u], n);
                int maskV = initMask[v] ^ bitPrefix(bit, tin[v], n);
                int curW = charBit[w];
                int pathMask = maskU ^ maskV ^ curW;
                answers.add((pathMask & (pathMask-1)) == 0);
            }
        }
        return answers;
    }
    static int bitPrefix(int[] bit, int idx, int n) {
        int res=0, i=idx+1;
        while (i>0) { res ^= bit[i]; i -= i&(-i); }
        return res;
    }
    public static void main(String[] args) {
        System.out.println(solve(3, new int[][]{{0,1},{1,2}}, "aac", new String[]{"query 0 2","update 1 b","query 0 2"}) + " expect [true, false]");
        System.out.println(solve(4, new int[][]{{0,1},{0,2},{0,3}}, "abca", new String[]{"query 1 2","update 0 b","query 2 3","update 3 a","query 1 3"}) + " expect [false, false, true]");
    }
}

class Solution {
    public int findScoreDifference(int[] nums) {
        boolean firstActive = true;
        int firstScore = 0, secondScore = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (x % 2 == 1) firstActive = !firstActive;
            if ((i + 1) % 6 == 0) firstActive = !firstActive;
            if (firstActive) firstScore += x;
            else secondScore += x;
        }
        return firstScore - secondScore;
    }
}

import java.util.*;

public class P8 {
    static int maxSubarrayXorBounded(int[] nums, int k) {
        int n = nums.length;
        int[] prefix = new int[n+1];
        for (int i=0;i<n;i++) prefix[i+1]=prefix[i]^nums[i];
        int maxPref=0; for (int p: prefix) maxPref=Math.max(maxPref,p);
        int maxbit = Math.max(1, maxPref==0?1:(32-Integer.numberOfLeadingZeros(maxPref)));
        List<int[]> trie = new ArrayList<>();
        trie.add(new int[]{-1,-1,0});
        final int MB = maxbit;
        // insert/query as closures using trie list
        return run(nums,k,prefix,trie,MB);
    }
    static int run(int[] nums, int k, int[] prefix, List<int[]> trie, int maxbit) {
        int n = nums.length;
        Deque<Integer> maxdq = new ArrayDeque<>(), mindq = new ArrayDeque<>();
        int l=0, ans=0;
        boolean[] inserted = new boolean[n+1];
        for (int r=0;r<n;r++) {
            while(!maxdq.isEmpty() && nums[maxdq.peekLast()]<=nums[r]) maxdq.pollLast();
            maxdq.addLast(r);
            while(!mindq.isEmpty() && nums[mindq.peekLast()]>=nums[r]) mindq.pollLast();
            mindq.addLast(r);
            while (nums[maxdq.peekFirst()]-nums[mindq.peekFirst()] > k) {
                if (inserted[l]) { insert(trie, prefix[l], -1, maxbit); inserted[l]=false; }
                if (maxdq.peekFirst()==l) maxdq.pollFirst();
                if (mindq.peekFirst()==l) mindq.pollFirst();
                l++;
            }
            insert(trie, prefix[r], 1, maxbit);
            inserted[r]=true;
            ans = Math.max(ans, query(trie, prefix[r+1], maxbit));
        }
        return ans;
    }
    static void insert(List<int[]> trie, int val, int delta, int maxbit) {
        int node=0; trie.get(node)[2]+=delta;
        for (int b=maxbit-1;b>=0;b--) {
            int bit=(val>>b)&1;
            if (trie.get(node)[bit]==-1) { trie.add(new int[]{-1,-1,0}); trie.get(node)[bit]=trie.size()-1; }
            node = trie.get(node)[bit];
            trie.get(node)[2]+=delta;
        }
    }
    static int query(List<int[]> trie, int val, int maxbit) {
        int node=0, res=0;
        for (int b=maxbit-1;b>=0;b--) {
            int bit=(val>>b)&1, want=1-bit;
            if (trie.get(node)[want]!=-1 && trie.get(trie.get(node)[want])[2]>0) { res |= (1<<b); node = trie.get(node)[want]; }
            else node = trie.get(node)[bit];
        }
        return res;
    }
    public static void main(String[] a) {
        int[] nums = {5,4,5,6};
        System.out.println(maxSubarrayXorBounded(nums,2) + " expect 7");
        System.out.println(maxSubarrayXorBounded(nums,1) + " expect 6");
    }
}

