class Solution {
    public static String mergeCharacters(String s, int k) {
        Map<Character, Integer> last = new HashMap<>();
        StringBuilder ans = new StringBuilder();
        for (char c : s.toCharArray()) {
            int cur = ans.length();
            Integer prev = last.get(c);
            if (prev != null && cur - prev <= k) continue;
            ans.append(c);
            last.put(c, cur);
        }
        return ans.toString();
    }
}

class Solution {
    static final long MOD = 1_000_000_007L;
    static long modPow(long base, long exp) {
        long res = 1 % MOD; base %= MOD; if (base < 0) base += MOD;
        while (exp > 0) { if ((exp & 1) == 1) res = (res * base) % MOD; base = (base * base) % MOD; exp >>= 1; }
        return res;
    }
    public long sumKDigitNumbers(long L, long R, long K) {
        if (K <= 0) return 0;
        long base = R - L + 1;
        long waysPerPos = modPow(base, K - 1);
        long sumDigits = (L + R) * base / 2;
        long pow10k = modPow(10, K);
        long inv9 = modPow(9, MOD - 2);
        long geoSum = ((pow10k - 1 + MOD) % MOD) * inv9 % MOD;
        long result = waysPerPos * (sumDigits % MOD) % MOD;
        result = result * geoSum % MOD;
        return result;
    }
}

import java.util.*;

class Solution {
    private Map<String, Long> f = new HashMap<>();
    private int[] nums;
    private int n;
    private long k;

    public long countSequences(int[] nums, long k) {
        this.nums = nums;
        this.n = nums.length;
        this.k = k;
        this.f.clear();
        return dfs(0, 1L, 1L);
    }

    private long dfs(int i, long p, long q) {
        if (i == n) return (p == k && q == 1L) ? 1 : 0;
        String key = i + "," + p + "," + q;
        if (f.containsKey(key)) return f.get(key);
        long res = dfs(i + 1, p, q);
        long x = nums[i];
        long g1 = gcd(p * x, q);
        res += dfs(i + 1, (p * x) / g1, q / g1);
        long g2 = gcd(p, q * x);
        res += dfs(i + 1, p / g2, (q * x) / g2);
        f.put(key, res);
        return res;
    }

    private long gcd(long a, long b) {
        while (b != 0) { long t = a % b; a = b; b = t; }
        return a;
    }
}

class Solution {
    public String maxXorAfterRearrangement(String s, String t) {
        int n = s.length();
        int ones = 0;
        for (char c : t.toCharArray()) if (c == '1') ones++;
        int zeros = n - ones;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '0') {
                if (ones > 0) { sb.append('1'); ones--; } else { sb.append('0'); zeros--; }
            } else {
                if (zeros > 0) { sb.append('1'); zeros--; } else { sb.append('0'); ones--; }
            }
        }
        return sb.toString();
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int subarraysWithKDistinct(int[] nums, int K) {
        return (int) (atMost(nums, K) - atMost(nums, K - 1));
    }

    private static long atMost(int[] nums, int k) {
        int left = 0;
        long result = 0;
        Map<Integer, Integer> freq = new HashMap<>();

        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];
            freq.put(val, freq.getOrDefault(val, 0) + 1);

            while (freq.size() > k) {
                int leftVal = nums[left];
                int cnt = freq.get(leftVal) - 1;
                if (cnt == 0) {
                    freq.remove(leftVal);
                } else {
                    freq.put(leftVal, cnt);
                }
                left++;
            }

            result += right - left + 1;
        }
        return result;
    }
}

class Solution {
    public int[] smallestPairWithDifferentFrequencies(int[] nums) {
        java.util.TreeMap<Integer, Integer> freq = new java.util.TreeMap<>();
        for (int x : nums) freq.merge(x, 1, Integer::sum);
        java.util.List<Integer> keys = new java.util.ArrayList<>(freq.keySet());
        for (int i = 0; i < keys.size(); i++) {
            int x = keys.get(i);
            for (int j = i + 1; j < keys.size(); j++) {
                int y = keys.get(j);
                if (!freq.get(x).equals(freq.get(y))) {
                    return new int[]{x, y};
                }
            }
        }
        return new int[]{-1, -1};
    }
}

import java.util.*;

class Solution {
    private static long bestRangeForPattern(long[] nums, int[] parity, int startParity) {
        int n = nums.length;
        List<Long> fixedVals = new ArrayList<>();
        List<Long> mismVals = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int exp = startParity == 0 ? (i % 2) : (1 - i % 2);
            if (parity[i] == exp) fixedVals.add(nums[i]);
            else mismVals.add(nums[i]);
        }
        if (mismVals.isEmpty()) {
            if (fixedVals.isEmpty()) return 0;
            return Collections.max(fixedVals) - Collections.min(fixedVals);
        }
        long lo, hi;
        if (!fixedVals.isEmpty()) {
            lo = Collections.min(fixedVals);
            hi = Collections.max(fixedVals);
        } else {
            lo = hi = mismVals.get(0) - 1;
            for (long v : mismVals) { lo = Math.min(lo, v - 1); hi = Math.max(hi, v - 1); }
        }
        List<Long> allVals = new ArrayList<>(fixedVals);
        for (long v : mismVals) allVals.add(v - 1);
        long loBound = 0;
        long hiBound = Collections.max(allVals) - Collections.min(allVals);

        final long fLo = lo, fHi = hi;
        final List<Long> fMism = mismVals;

        while (loBound < hiBound) {
            long mid = loBound + (hiBound - loBound) / 2;
            if (feasible(mid, fLo, fHi, fMism)) hiBound = mid;
            else loBound = mid + 1;
        }
        return loBound;
    }

    private static boolean feasible(long W, long lo, long hi, List<Long> mismVals) {
        long baseLo = hi - W, baseHi = lo;
        if (baseLo > baseHi) return false;
        List<long[]> events = new ArrayList<>();
        for (long v : mismVals) {
            long aLo = v - 1 - W, aHi = v - 1;
            long bLo = v + 1 - W, bHi = v + 1;
            if (aHi + 1 >= bLo) {
                events.add(new long[]{aLo, 1});
                events.add(new long[]{bHi + 1, -1});
            } else {
                events.add(new long[]{aLo, 1}); events.add(new long[]{aHi + 1, -1});
                events.add(new long[]{bLo, 1}); events.add(new long[]{bHi + 1, -1});
            }
        }
        TreeSet<Long> ptsSet = new TreeSet<>();
        for (long[] e : events) ptsSet.add(e[0]);
        ptsSet.add(baseLo); ptsSet.add(baseHi);
        events.sort((a, b) -> Long.compare(a[0], b[0]));
        int idx = 0;
        long cur = 0;
        long needed = mismVals.size();
        for (long p : ptsSet) {
            while (idx < events.size() && events.get(idx)[0] <= p) {
                cur += events.get(idx)[1];
                idx++;
            }
            if (p >= baseLo && p <= baseHi && cur >= needed) return true;
        }
        return false;
    }

    public static int[] minOperationsParity(int[] numsInt) {
        int n = numsInt.length;
        long[] nums = new long[n];
        for (int i = 0; i < n; i++) nums[i] = numsInt[i];
        int[] parity = new int[n];
        for (int i = 0; i < n; i++) parity[i] = (int) (((nums[i] % 2) + 2) % 2);
        int mismA = 0, mismB = 0;
        for (int i = 0; i < n; i++) {
            int expA = i % 2, expB = 1 - i % 2;
            if (parity[i] != expA) mismA++;
            if (parity[i] != expB) mismB++;
        }
        int bestOps = Math.min(mismA, mismB);
        List<Integer> candidates = new ArrayList<>();
        if (mismA == bestOps) candidates.add(0);
        if (mismB == bestOps) candidates.add(1);
        long bestRange = Long.MAX_VALUE;
        for (int sp : candidates) bestRange = Math.min(bestRange, bestRangeForPattern(nums, parity, sp));
        return new int[]{bestOps, (int) bestRange};
    }
}

class Solution {
    // Single pass: track the best (smallest capacity that still fits) box seen so far,
    // keeping the first index on ties since we scan left to right.
    public int minimumIndex(int[] capacity, int itemSize) {
        int ans = -1;
        for (int i = 0; i < capacity.length; i++) {
            if (capacity[i] >= itemSize && (ans == -1 || capacity[i] < capacity[ans])) ans = i;
        }
        return ans;
    }
}

