class Solution {
    public int smallestBalancedIndex(int[] nums) {
        int n = nums.length;
        long CAP = (long) 4e18; // sentinel safely above any possible prefix sum (<= 1e5*1e9=1e14)
        long[] prefixSum = new long[n];
        for (int i = 1; i < n; i++) prefixSum[i] = prefixSum[i - 1] + nums[i - 1];
        long[] suffixProd = new long[n];
        suffixProd[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) {
            long prev = suffixProd[i + 1];
            long v = nums[i + 1];
            if (prev >= CAP || (v != 0 && prev > CAP / v)) {
                suffixProd[i] = CAP; // clamp: once too big it can never match a valid sum again
            } else {
                suffixProd[i] = prev * v;
            }
        }
        for (int i = 0; i < n; i++) {
            if (prefixSum[i] == suffixProd[i]) return i;
        }
        return -1;
    }
}

