class Solution {
    public static int minBitwiseOr(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int answer = 0;
        for (int bit = 30; bit >= 0; bit--) {
            int tryAns = answer;
            int mask = tryAns | ((1 << bit) - 1);
            boolean ok = true;
            for (int i = 0; i < n && ok; i++) {
                boolean rowOk = false;
                for (int j = 0; j < m; j++) {
                    if ((grid[i][j] | mask) == mask) {
                        rowOk = true;
                        break;
                    }
                }
                if (!rowOk) {
                    ok = false;
                }
            }
            if (!ok) {
                answer |= (1 << bit);
            }
        }
        return answer;
    }
}

