public class H8 {
    static List<Integer> digitsOf(long x) {
        String s = Long.toString(x);
        List<Integer> d = new ArrayList<>();
        for (char c : s.toCharArray()) d.add(c - '0');
        return d;
    }

    static boolean isGood(long x) {
        List<Integer> d = digitsOf(x);
        if (d.size() == 1) return true;
        boolean inc = true, dec = true;
        for (int i = 0; i + 1 < d.size(); i++) {
            if (!(d.get(i) < d.get(i+1))) inc = false;
            if (!(d.get(i) > d.get(i+1))) dec = false;
        }
        return inc || dec;
    }

    static int digitSum(long x) {
        int s = 0;
        for (int d : digitsOf(x)) s += d;
        return s;
    }

    static long[] GOOD_SORTED;
    static Set<Integer> GOOD_SUMS = new HashSet<>();

    static void buildGoodSet() {
        TreeSet<Long> good = new TreeSet<>();
        for (int mask = 1; mask < (1<<9); mask++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 9; i++) if ((mask & (1<<i)) != 0) sb.append((char)('1'+i));
            good.add(Long.parseLong(sb.toString()));
        }
        for (int mask = 1; mask < (1<<10); mask++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 9; i >= 0; i--) if ((mask & (1<<i)) != 0) sb.append((char)('0'+i));
            good.add(Long.parseLong(sb.toString()));
        }
        GOOD_SORTED = new long[good.size()];
        int idx = 0;
        for (long v : good) GOOD_SORTED[idx++] = v;
        for (int s = 0; s < 300; s++) if (isGood(s)) GOOD_SUMS.add(s);
    }

    static long countGoodUpTo(long n) {
        if (n < 0) return 0;
        int lo = 0, hi = GOOD_SORTED.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (GOOD_SORTED[mid] <= n) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static long[][] memo;

    static long dpDigitSum(int pos, boolean tight, int total, String s) {
        int length = s.length();
        if (pos == length) return GOOD_SUMS.contains(total) ? 1 : 0;
        if (!tight && memo[pos][total] != -1) return memo[pos][total];
        int limit = tight ? (s.charAt(pos) - '0') : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            res += dpDigitSum(pos + 1, tight && d == limit, total + d, s);
        }
        if (!tight) memo[pos][total] = res;
        return res;
    }

    static long countDigitSumGoodUpTo(long n) {
        if (n < 0) return 0;
        String s = Long.toString(n);
        memo = new long[s.length() + 1][300];
        for (long[] row : memo) Arrays.fill(row, -1);
        return dpDigitSum(0, true, 0, s);
    }

    static long countBothUpTo(long n) {
        if (n < 0) return 0;
        long cnt = 0;
        for (long x : GOOD_SORTED) {
            if (x > n) break;
            if (GOOD_SUMS.contains(digitSum(x))) cnt++;
        }
        return cnt;
    }

    static long fancyCountUpTo(long n) {
        if (n < 0) return 0;
        return countGoodUpTo(n) + countDigitSumGoodUpTo(n) - countBothUpTo(n);
    }

    static long countFancyNumbers(long l, long r) {
        return fancyCountUpTo(r) - fancyCountUpTo(l - 1);
    }

    public static void main(String[] args) {
        buildGoodSet();
        System.out.println(countFancyNumbers(8, 10) + " expected 3");
        System.out.println(countFancyNumbers(12340, 12341) + " expected 1");
        System.out.println(countFancyNumbers(123456788, 123456788) + " expected 0");
    }
}

class Solution {
    public int minOperations(String s) {
        boolean isSorted = true;
        char[] cs = s.toCharArray();
        int n = cs.length;
        char mn = cs[0], mx = cs[0];
        for (int i = 1; i < n; ++i) {
            mn = (char) Math.min(mn, cs[i]);
            mx = (char) Math.max(mx, cs[i]);
            if (cs[i] < cs[i - 1]) isSorted = false;
        }
        if (isSorted) return 0;
        if (n == 2) return -1;
        if (cs[0] == mn || cs[n - 1] == mx) return 1;
        for (int i = 1; i < n - 1; ++i) if (cs[i] == mn || cs[i] == mx) return 2;
        return 3;
    }
}

