public class Solution {
    public static long minCost(String s, long encCost, long flatCost) {
        int n = s.length();
        long[] pre = new long[n+1];
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + (s.charAt(i) == '1' ? 1 : 0);
        Map<Long, Long> memo = new HashMap<>();
        return dfs(0, n, pre, encCost, flatCost, memo);
    }
    static long dfs(int x, int y, long[] pre, long encCost, long flatCost, Map<Long,Long> memo) {
        long key = (long)x * 200000 + y;
        if (memo.containsKey(key)) return memo.get(key);
        long L = y - x;
        long X = pre[y] - pre[x];
        long whole = (X == 0) ? flatCost : L * X * encCost;
        long res = whole;
        if (L % 2 == 0) {
            int mid = x + (int)(L/2);
            long split = dfs(x, mid, pre, encCost, flatCost, memo) + dfs(mid, y, pre, encCost, flatCost, memo);
            res = Math.min(whole, split);
        }
        memo.put(key, res);
        return res;
    }
}

