public class LongestArithmeticSequence {
    static int longestArithmeticOptimal(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;
        int[] left = new int[n], right = new int[n];
        Arrays.fill(left, 2); Arrays.fill(right, 2);
        left[0] = 1; right[n-1] = 1;
        for (int i = 2; i < n; i++) if (nums[i]-nums[i-1]==nums[i-1]-nums[i-2]) left[i]=left[i-1]+1;
        for (int i = n-3; i >= 0; i--) if (nums[i+1]-nums[i]==nums[i+2]-nums[i+1]) right[i]=right[i+1]+1;
        int ans = 2;
        for (int i = 0; i < n; i++) {
            ans = Math.max(ans, Math.max(left[i], right[i]));
            if (i > 0) ans = Math.max(ans, left[i-1]+1);
            if (i+1 < n) ans = Math.max(ans, right[i+1]+1);
            if (i > 0 && i < n-1) {
                int diffSum = nums[i+1]-nums[i-1];
                if (diffSum % 2 == 0) {
                    int diff = diffSum/2;
                    int k = 3;
                    if (i > 1 && diff == (nums[i-1]-nums[i-2])) k += left[i-1]-1;
                    if (i < n-2 && diff == (nums[i+2]-nums[i+1])) k += right[i+1]-1;
                    ans = Math.max(ans, k);
                }
            }
        }
        return ans;
    }
    static int longestArithmeticAlgo(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;
        int best = 2;
        Set<Integer> diffSet = new TreeSet<>();
        for (int a=0;a<n;a++) for (int b=0;b<n;b++) if (a!=b) diffSet.add(nums[b]-nums[a]);
        diffSet.add(0);
        for (int i = 0; i < n; i++) {
            Set<Integer> candidates = new TreeSet<>();
            candidates.add(nums[i]);
            for (int d : diffSet) {
                if (i > 0) candidates.add(nums[i-1]+d);
                if (i < n-1) candidates.add(nums[i+1]-d);
            }
            for (int repl : candidates) {
                int[] arr = nums.clone();
                arr[i] = repl;
                int cur = 1, localBest = 1;
                for (int j = 1; j < n; j++) {
                    if (j >= 2 && arr[j]-arr[j-1]==arr[j-1]-arr[j-2]) cur++; else cur = 2;
                    localBest = Math.max(localBest, cur);
                }
                best = Math.max(best, localBest);
            }
        }
        return best;
    }
}

class Solution {
    class UnionFind {
        Map<Long, Long> p = new HashMap<>();
        Map<Long, Integer> size = new HashMap<>();
        long find(long x) {
            if (!p.containsKey(x)) { p.put(x, x); size.put(x, 1); }
            if (p.get(x) != x) p.put(x, find(p.get(x)));
            return p.get(x);
        }
        boolean union(long a, long b) {
            long pa = find(a), pb = find(b);
            if (pa == pb) return false;
            int sa = size.get(pa), sb = size.get(pb);
            if (sa > sb) { p.put(pb, pa); size.put(pa, sa + sb); }
            else { p.put(pa, pb); size.put(pb, sa + sb); }
            return true;
        }
    }
    public int maxActivated(int[][] points) {
        UnionFind uf = new UnionFind();
        long m = (long) 3e9;
        for (int[] pt : points) uf.union(pt[0], pt[1] + m);
        Map<Long, Integer> cnt = new HashMap<>();
        for (int[] pt : points) cnt.merge(uf.find(pt[0]), 1, Integer::sum);
        int mx1 = 0, mx2 = 0;
        for (int x : cnt.values()) {
            if (mx1 < x) { mx2 = mx1; mx1 = x; }
            else if (mx2 < x) mx2 = x;
        }
        return mx1 + mx2 + 1;
    }
}

