class Solution {
    public static long countCommasInRange(long L, long R) {
        return totalUpTo(R) - totalUpTo(L - 1);
    }

    private static long totalUpTo(long N) {
        if (N <= 0) return 0;
        long total = 0;
        long power = 1;
        int digit = 1;
        while (power <= N) {
            long nextPower = power * 10;
            long end = Math.min(N, nextPower - 1);
            long countNumbers = end - power + 1;
            long commasPerNumber = (digit - 1) / 3;
            total += countNumbers * commasPerNumber;
            power = nextPower;
            digit++;
        }
        return total;
    }
}

