public class P19 {
    static long countGoodSubarrays(int[] nums) {
        int n = nums.length;
        int[] l = new int[n], r = new int[n];
        Arrays.fill(l,-1); Arrays.fill(r,n);
        Deque<Integer> stk = new ArrayDeque<>();
        for (int i=0;i<n;i++) {
            while (!stk.isEmpty() && (nums[stk.peek()]|nums[i])==nums[i]) stk.pop();
            l[i] = stk.isEmpty()? -1: stk.peek();
            stk.push(i);
        }
        stk.clear();
        for (int i=n-1;i>=0;i--) {
            while (!stk.isEmpty() && ((nums[stk.peek()]|nums[i])==nums[i]) && nums[stk.peek()]!=nums[i]) stk.pop();
            r[i] = stk.isEmpty()? n: stk.peek();
            stk.push(i);
        }
        long ans=0;
        for (int i=0;i<n;i++) ans += (long)(i-l[i]) * (r[i]-i);
        return ans;
    }
    public static void main(String[] a) {
        System.out.println(countGoodSubarrays(new int[]{4,2,3})+" expect 4");
        System.out.println(countGoodSubarrays(new int[]{1,3,1})+" expect 6");
    }
}

