class Solution {
    public static String countCommas(String L, String R) {
        BigInteger Lbig = new BigInteger(L);
        BigInteger Rbig = new BigInteger(R);
        BigInteger total = BigInteger.ZERO;
        for (int d = 1; d <= 19; d++) {
            BigInteger start = BigInteger.TEN.pow(d - 1);
            BigInteger end = BigInteger.TEN.pow(d).subtract(BigInteger.ONE);
            BigInteger lo = Lbig.max(start);
            BigInteger hi = Rbig.min(end);
            if (lo.compareTo(hi) > 0) continue;
            BigInteger count = hi.subtract(lo).add(BigInteger.ONE);
            int commas = (d - 1) / 3;
            total = total.add(count.multiply(BigInteger.valueOf(commas)));
        }
        return total.toString();
    }
}

public class P20 {
    static final long MOD = 1_000_000_007L;
    static long modpow(long b, long e, long m) { b%=m; long r=1; while(e>0){ if((e&1)==1) r=r*b%m; b=b*b%m; e>>=1;} return r; }
    static long countVisiblePeople(int n, int pos, int k) {
        int l = pos, r = n-pos-1;
        int maxN = Math.max(l,r)+1;
        long[] fact = new long[maxN+1], invFact = new long[maxN+1];
        fact[0]=1;
        for (int i=1;i<=maxN;i++) fact[i]=fact[i-1]*i%MOD;
        invFact[maxN]=modpow(fact[maxN],MOD-2,MOD);
        for (int i=maxN;i>0;i--) invFact[i-1]=invFact[i]*i%MOD;
        long ans=0;
        for (int a=0;a<=Math.min(k,l);a++) {
            int b=k-a;
            if (b<=r) {
                long cl = (a<0||a>l)?0:fact[l]*invFact[a]%MOD*invFact[l-a]%MOD;
                long cr = (b<0||b>r)?0:fact[r]*invFact[b]%MOD*invFact[r-b]%MOD;
                ans=(ans+2*cl%MOD*cr)%MOD;
            }
        }
        return ans;
    }
    public static void main(String[] a) {
        System.out.println(countVisiblePeople(4,1,1)+" expect 6");
        System.out.println(countVisiblePeople(2,0,0)+" expect 2");
    }
}

