class Solution {
    public static int minRemovals(int[] arr, int target) {
        int n = arr.length;
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int v : arr) {
            Map<Integer, Integer> next = new HashMap<>(dp);
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int xorVal = entry.getKey();
                int size = entry.getValue();
                int newXor = xorVal ^ v;
                int newSize = size + 1;
                Integer existing = next.get(newXor);
                if (existing == null || newSize > existing) {
                    next.put(newXor, newSize);
                }
            }
            dp = next;
        }
        Integer best = dp.get(target);
        if (best == null) return -1;
        return n - best;
    }
}

