public class EventManager {
    private final TreeMap<Integer, String> tsToName = new TreeMap<>();
    private final Map<String, Integer> nameToTs = new HashMap<>();

    public void addEvent(String name, int timestamp) {
        if (nameToTs.containsKey(name)) return;
        nameToTs.put(name, timestamp);
        tsToName.put(timestamp, name);
    }

    public void deleteEvent(String name) {
        Integer ts = nameToTs.remove(name);
        if (ts != null) tsToName.remove(ts);
    }

    public String getNextEvent(String name) {
        Integer ts = nameToTs.get(name);
        if (ts == null) return "-1";
        Map.Entry<Integer, String> e = tsToName.higherEntry(ts);
        return e == null ? "-1" : e.getValue();
    }

    public String getPreviousEvent(String name) {
        Integer ts = nameToTs.get(name);
        if (ts == null) return "-1";
        Map.Entry<Integer, String> e = tsToName.lowerEntry(ts);
        return e == null ? "-1" : e.getValue();
    }
}

class Solution {
    public long sortableIntegers(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int k = 1; k <= n; k++) {
            if (n % k != 0) continue;
            int d = n / k;
            boolean ok = true;
            int prevMax = Integer.MIN_VALUE;
            for (int b = 0; b < d && ok; b++) {
                int descents = 0;
                int curMin = Integer.MAX_VALUE, curMax = Integer.MIN_VALUE;
                for (int i = 0; i < k; i++) {
                    int idx = b*k+i;
                    curMin = Math.min(curMin, nums[idx]);
                    curMax = Math.max(curMax, nums[idx]);
                    int nextIdx = b*k + (i+1)%k;
                    if (nums[idx] > nums[nextIdx]) descents++;
                }
                if (descents > 1) { ok = false; break; }
                if (curMin < prevMax) { ok = false; break; }
                prevMax = curMax;
            }
            if (ok) total += k;
        }
        return total;
    }
}

class Solution {
    public int minAbsoluteDifference(int[] nums) {
        int n = nums.length;
        List<Integer> ones = new ArrayList<>();
        List<Integer> twos = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) ones.add(i);
            else if (nums[i] == 2) twos.add(i);
        }
        int ans = Integer.MAX_VALUE;
        for (int i : ones) {
            for (int j : twos) {
                ans = Math.min(ans, Math.abs(i - j));
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int minXorPath(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        @SuppressWarnings("unchecked")
        Set<Integer>[][] dp = new HashSet[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                dp[i][j] = new HashSet<>();
            }
        }
        dp[0][0].add(grid[0][0]);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                int val = grid[i][j];
                if (i > 0) {
                    for (int x : dp[i - 1][j]) {
                        dp[i][j].add(x ^ val);
                    }
                }
                if (j > 0) {
                    for (int x : dp[i][j - 1]) {
                        dp[i][j].add(x ^ val);
                    }
                }
            }
        }
        int answer = Integer.MAX_VALUE;
        for (int x : dp[m - 1][n - 1]) {
            if (x < answer) answer = x;
        }
        return answer;
    }
}

class Solution {
    public int mirrorFrequency(String s) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : s.toCharArray()) freq.merge(c, 1, Integer::sum);
        Set<Character> visited = new HashSet<>();
        int ans = 0;
        for (char c : freq.keySet()) {
            if (visited.contains(c)) continue; // avoid double-counting the (c,m)/(m,c) pair
            char m;
            if (c >= 'a' && c <= 'z') m = (char) ('a' + 25 - (c - 'a'));
            else m = (char) ('0' + 9 - (c - '0'));
            visited.add(c);
            visited.add(m);
            int mv = freq.getOrDefault(m, 0); // mirror char may not appear in s at all -> freq 0
            ans += Math.abs(freq.get(c) - mv);
        }
        return ans;
    }
}

import java.util.*;
class Solution {
    public static int countArrays(int[] digitSum) {
        final int MOD = 1000000007;
        final int MAXV = 5000;
        int[] DS = new int[MAXV+1];
        for (int v=0; v<=MAXV; v++) { int s=0,x=v; while(x>0){s+=x%10;x/=10;} DS[v]=s; }
        int n = digitSum.length;
        long[] dpPrev = new long[MAXV+1];
        for (int v=0;v<=MAXV;v++) if (DS[v]==digitSum[0]) dpPrev[v]=1;
        for (int i=1;i<n;i++){
            long[] prefix = new long[MAXV+1]; long running=0;
            for (int v=0;v<=MAXV;v++){ running=(running+dpPrev[v])%MOD; prefix[v]=running; }
            int target=digitSum[i];
            long[] dpCur = new long[MAXV+1];
            for (int v=0;v<=MAXV;v++) if (DS[v]==target) dpCur[v]=prefix[v];
            dpPrev=dpCur;
        }
        long total=0;
        for (long x: dpPrev) total=(total+x)%MOD;
        return (int)total;
    }
}

