class Solution {
    private static final int MX = 200050;
    private static final boolean[] IS_PRIME = new boolean[MX + 1];
    private static final List<Integer> PRIMES = new ArrayList<>();
    static {
        Arrays.fill(IS_PRIME, true);
        IS_PRIME[0] = false; IS_PRIME[1] = false;
        for (int i = 2; (long) i * i <= MX; i++) if (IS_PRIME[i]) for (int j = i * i; j <= MX; j += i) IS_PRIME[j] = false;
        for (int i = 2; i <= MX; i++) if (IS_PRIME[i]) PRIMES.add(i);
    }
    public int minOperations(int[] nums) {
        int ans = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if ((i & 1) == 0) {
                int j = Collections.binarySearch(PRIMES, x);
                if (j < 0) j = -j - 1;
                ans += PRIMES.get(j) - x;
            } else if (IS_PRIME[x]) {
                ans += (x == 2) ? 2 : 1;
            }
        }
        return ans;
    }
}

public class P28 {
    static long[] better(long[] a, long[] b) {
        if (a[0] != b[0]) return a[0] > b[0] ? a : b;
        return a[1] <= b[1] ? a : b;
    }
    static long minIncrease(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0;
        long[] notTake = {0,0}, take = {-1,0};
        for (int i=1;i<n-1;i++) {
            long costI = Math.max(0, Math.max((long)nums[i-1]-nums[i]+1, (long)nums[i+1]-nums[i]+1));
            long[] newTake = {notTake[0]+1, notTake[1]+costI};
            long[] newNotTake = better(notTake, take);
            notTake = newNotTake; take = newTake;
        }
        return better(notTake, take)[1];
    }
    public static void main(String[] a) {
        System.out.println(minIncrease(new int[]{1,2,2})+" expect 1");
        System.out.println(minIncrease(new int[]{2,1,1,3})+" expect 2");
        System.out.println(minIncrease(new int[]{5,2,1,4,3})+" expect 4");
    }
}

import java.util.*;
class Solution {
    static long gcd(long a, long b) { while (b != 0) { long t = a % b; a = b; b = t; } return a; }
    static boolean check(long[] nums, long p) {
        int n = nums.length;
        List<Long> filtered = new ArrayList<>();
        for (long x : nums) if (x % p == 0) filtered.add(x / p);
        if (filtered.isEmpty()) return false;
        if (filtered.size() < n) {
            long g = 0;
            for (long v : filtered) g = gcd(g, v);
            return g == 1;
        } else {
            int m = filtered.size();
            long[] pre = new long[m+1], suf = new long[m+1];
            for (int i=0;i<m;i++) pre[i+1] = gcd(pre[i], filtered.get(i));
            for (int i=m-1;i>=0;i--) suf[i] = gcd(suf[i+1], filtered.get(i));
            for (int i=0;i<m;i++) if (gcd(pre[i], suf[i+1]) == 1) return true;
            return false;
        }
    }
    public static int goodSubsequences(long[] nums, long p, int[][] queries) {
        int ans = 0;
        for (int[] q : queries) {
            nums[q[0]] = q[1];
            if (check(nums, p)) ans++;
        }
        return ans;
    }
}

