class Solution {
    static final int MAXV = 100001;

    public long maxAlternatingSum(int[] nums, int k) {
        int n = nums.length;
        long[] bitDown = new long[MAXV + 2]; // prefix-max Fenwick keyed by value, holds best "down"-state score
        long[] bitUp = new long[MAXV + 2];   // prefix-max Fenwick keyed by (MAXV+1-value), holds best "up"-state score
        long[] up = new long[n], down = new long[n];
        long ans = Long.MIN_VALUE;
        int inserted = -1;
        for (int i = 0; i < n; i++) {
            // release every earlier index that is now far enough away (>= k) to be a valid predecessor
            int limit = i - k;
            while (inserted < limit) {
                inserted++;
                update(bitDown, nums[inserted], down[inserted]);
                update(bitUp, MAXV + 1 - nums[inserted], up[inserted]);
            }
            // up[i]: last transition into i was an increase, so predecessor must be in "down" state with smaller value
            long bestDown = query(bitDown, nums[i] - 1);
            up[i] = nums[i] + Math.max(0, bestDown);
            // down[i]: last transition into i was a decrease, so predecessor must be in "up" state with larger value
            long bestUp = query(bitUp, MAXV + 1 - (nums[i] + 1));
            down[i] = nums[i] + Math.max(0, bestUp);
            ans = Math.max(ans, Math.max(up[i], down[i]));
        }
        return ans;
    }

    private void update(long[] bit, int i, long val) {
        for (; i <= MAXV; i += i & (-i)) bit[i] = Math.max(bit[i], val);
    }
    private long query(long[] bit, int i) {
        long res = 0;
        for (; i > 0; i -= i & (-i)) res = Math.max(res, bit[i]);
        return res;
    }
}

class Solution {
    public String sortVowels(String s) {
        String vowelsOrder = "aeiou";
        Map<Character,Integer> freq = new HashMap<>();
        Map<Character,Integer> firstOcc = new HashMap<>();
        List<Integer> vowelPositions = new ArrayList<>();
        char[] arr = s.toCharArray();
        for (int i = 0; i < arr.length; i++) {
            char c = arr[i];
            if (vowelsOrder.indexOf(c) >= 0) {
                vowelPositions.add(i);
                freq.merge(c, 1, Integer::sum);
                firstOcc.putIfAbsent(c, i);
            }
        }
        List<Character> letters = new ArrayList<>(freq.keySet());
        letters.sort((a, b) -> {
            int fa = freq.get(a), fb = freq.get(b);
            if (fa != fb) return fb - fa;
            return firstOcc.get(a) - firstOcc.get(b);
        });
        List<Character> sortedVowels = new ArrayList<>();
        for (char c : letters) {
            int f = freq.get(c);
            for (int k = 0; k < f; k++) sortedVowels.add(c);
        }
        for (int idx = 0; idx < vowelPositions.size(); idx++) {
            arr[vowelPositions.get(idx)] = sortedVowels.get(idx);
        }
        return new String(arr);
    }
}

import java.lang.Math;

class Solution {
    public static long sumPrimesBetweenReverse(int num) {
        int rev = 0;
        int tmp = num;
        while (tmp > 0) {
            rev = rev * 10 + (tmp % 10);
            tmp = tmp / 10;
        }
        int low = Math.min(num, rev);
        int high = Math.max(num, rev);
        long total = 0;
        for (int i = low; i <= high; i++) {
            if (i > 1) {
                boolean isPrime = true;
                int limit = (int) Math.sqrt(i);
                for (int d = 2; d <= limit; d++) {
                    if (i % d == 0) {
                        isPrime = false;
                        break;
                    }
                }
                if (isPrime) {
                    total += i;
                }
            }
        }
        return total;
    }
}

class Solution {
    // A coherent string can only take one of a few shapes (verified by exhaustive
    // enumeration for small n: exactly n+3 valid strings total):
    //   - all zeros
    //   - all ones
    //   - a single '1' surrounded by zeros (any position)
    //   - a '1' at both ends with zeros strictly in between
    // Any other arrangement creates either "011" or "110" as a subsequence.
    // Take the minimum Hamming distance from s to the best member of each family.
    public int minFlips(String s) {
        int n = s.length();
        int totalOnes = 0;
        for (char c : s.toCharArray()) if (c == '1') totalOnes++;

        int costAll0 = totalOnes;
        int costAll1 = n - totalOnes;
        // cheapest single-1 target: keep an existing '1' in place if one exists
        int bestSingle1 = (totalOnes >= 1) ? (totalOnes - 1) : 1;

        int costTwoEnds;
        if (n == 1) {
            costTwoEnds = (s.charAt(0) == '1') ? 0 : 1;
        } else {
            int left = (s.charAt(0) == '1') ? 0 : 1;
            int right = (s.charAt(n - 1) == '1') ? 0 : 1;
            int middleOnes = 0;
            for (int i = 1; i < n - 1; i++) if (s.charAt(i) == '1') middleOnes++;
            costTwoEnds = left + right + middleOnes;
        }

        return Math.min(Math.min(costAll0, costAll1), Math.min(bestSingle1, costTwoEnds));
    }
}

import java.util.*;
class Solution {
    public int[] minCosts(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] closest = new int[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) closest[i] = 1;
            else if (i == n-1) closest[i] = n-2;
            else {
                int dl = nums[i]-nums[i-1], dr = nums[i+1]-nums[i];
                closest[i] = dl <= dr ? i-1 : i+1;
            }
        }
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n-1; i++) {
            int w = nums[i+1]-nums[i];
            adj.get(i).add(new int[]{i+1, w});
            adj.get(i+1).add(new int[]{i, w});
        }
        for (int i = 0; i < n; i++) adj.get(i).add(new int[]{closest[i], 1});

        Map<Integer, long[]> cache = new HashMap<>();
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            long[] dist = cache.get(l);
            if (dist == null) {
                dist = new long[n];
                Arrays.fill(dist, Long.MAX_VALUE/2);
                dist[l] = 0;
                PriorityQueue<long[]> pq = new PriorityQueue<>((a,b) -> Long.compare(a[0], b[0]));
                pq.add(new long[]{0, l});
                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    long d = cur[0]; int u = (int) cur[1];
                    if (d > dist[u]) continue;
                    for (int[] e : adj.get(u)) {
                        int v = e[0], w = e[1];
                        if (d + w < dist[v]) {
                            dist[v] = d + w;
                            pq.add(new long[]{dist[v], v});
                        }
                    }
                }
                cache.put(l, dist);
            }
            ans[qi] = (int) dist[r];
        }
        return ans;
    }
}

class Solution {
    public int[] scoreValidator(String[] events) {
        int score = 0, counter = 0;
        for (String e : events) {
            if (counter == 10) break;
            if (e.equals("W")) counter++;
            else if (e.equals("WD") || e.equals("NB")) score += 1;
            else score += Integer.parseInt(e);
            if (counter == 10) break;
        }
        return new int[]{score, counter};
    }
}

public class H9 {
    static int maxFixedPoints(int[] nums) {
        int n = nums.length;
        int[] req = new int[n];
        for (int i = 0; i < n; i++) req[i] = i - nums[i];
        int[] dp = new int[n];
        int best = 0;
        for (int i = 0; i < n; i++) {
            if (req[i] < 0) { dp[i] = 0; continue; }
            dp[i] = 1;
            for (int j = 0; j < i; j++) {
                if (dp[j] > 0 && nums[j] < nums[i] && req[j] <= req[i]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(maxFixedPoints(new int[]{0,2,1}) + " expected 2");
        System.out.println(maxFixedPoints(new int[]{3,1,2}) + " expected 2");
        System.out.println(maxFixedPoints(new int[]{1,0,1,2}) + " expected 3");
    }
}

import java.util.*;
class Solution {
    public static int minGenerations(int[][] points, int[] target) {
        Set<List<Integer>> pointSet = new HashSet<>();
        for (int[] p : points) pointSet.add(toList(p));
        List<Integer> targetList = toList(target);
        if (pointSet.contains(targetList)) return 0;
        for (int gen = 1; gen <= 40; gen++) {
            List<List<Integer>> pts = new ArrayList<>(pointSet);
            Set<List<Integer>> newPoints = new HashSet<>();
            int n = pts.size();
            for (int i = 0; i < n; i++) {
                for (int j = i+1; j < n; j++) {
                    List<Integer> a = pts.get(i), b = pts.get(j);
                    List<Integer> avg = new ArrayList<>();
                    for (int k = 0; k < a.size(); k++) avg.add(Math.floorDiv(a.get(k)+b.get(k), 2));
                    newPoints.add(avg);
                }
            }
            boolean addedNew = false;
            for (List<Integer> p : newPoints) if (pointSet.add(p)) addedNew = true;
            if (pointSet.contains(targetList)) return gen;
            if (!addedNew) break;
        }
        return -1;
    }
    static List<Integer> toList(int[] arr) {
        List<Integer> l = new ArrayList<>();
        for (int x : arr) l.add(x);
        return l;
    }
}

import java.util.*;
public class P41 {
    static int[] countWordOccurrences(String[] chunks, String[] queries) {
        StringBuilder sb = new StringBuilder();
        for (String c : chunks) sb.append(c);
        String s = sb.toString();
        int n = s.length();
        Map<String,Integer> cnt = new HashMap<>();
        int i = 0;
        while (i < n) {
            char c = s.charAt(i);
            if (c == ' ' || c == '-') { i++; continue; }
            int j = i;
            while (j < n) {
                char cj = s.charAt(j);
                if (cj == ' ') break;
                if (cj == '-') {
                    boolean joiner = (j>i) && isLower(s.charAt(j-1)) && (j+1<n) && isLower(s.charAt(j+1));
                    if (!joiner) break;
                }
                j++;
            }
            cnt.merge(s.substring(i,j), 1, Integer::sum);
            i = j;
        }
        int[] ans = new int[queries.length];
        for (int k=0;k<queries.length;k++) ans[k] = cnt.getOrDefault(queries[k], 0);
        return ans;
    }
    static boolean isLower(char ch){ return ch>='a' && ch<='z'; }
    public static void main(String[] a) {
        System.out.println(Arrays.toString(countWordOccurrences(new String[]{"hello wor","ld hello"}, new String[]{"hello","world","wor"}))+" expect [2, 1, 0]");
        System.out.println(Arrays.toString(countWordOccurrences(new String[]{"a--b a-","-c"}, new String[]{"a","b","c"}))+" expect [2, 1, 1]");
        System.out.println(Arrays.toString(countWordOccurrences(new String[]{"hello"}, new String[]{"hello","ell"}))+" expect [1, 0]");
    }
}

import java.util.*;
class Solution {
    private int minHeavyEdges(int n, int[][] edges, int threshold, int source, int target) {
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            int cost = w <= threshold ? 0 : 1;
            adj[u].add(new int[]{v, cost});
            adj[v].add(new int[]{u, cost});
        }
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(source);
        while (!dq.isEmpty()) {
            int u = dq.pollFirst();
            for (int[] edge : adj[u]) {
                int v = edge[0], c = edge[1];
                int nd = dist[u] + c;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    if (c == 0) dq.addFirst(v); else dq.addLast(v);
                }
            }
        }
        return dist[target];
    }
    public int minimumThresholdPath(int n, int[][] edges, int source, int target, int k) {
        if (source == target) return 0;
        TreeSet<Integer> ws = new TreeSet<>();
        for (int[] e : edges) ws.add(e[2]);
        List<Integer> weights = new ArrayList<>(ws);
        if (weights.isEmpty() || weights.get(0) > 0) weights.add(0, 0);
        int lo = 0, hi = weights.size() - 1, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            int t = weights.get(mid);
            int h = minHeavyEdges(n, edges, t, source, target);
            if (h <= k) { ans = t; hi = mid - 1; } else lo = mid + 1;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static long minimizeArraySum(int[] arr) {
        int n = arr.length;
        if (n == 0) return 0L;

        int maxVal = arr[0];
        for (int v : arr) {
            if (v > maxVal) maxVal = v;
        }

        byte[] exists = new byte[maxVal + 1];
        for (int v : arr) {
            exists[v] = 1;
        }

        int[] minDiv = new int[maxVal + 1];
        for (int i = 0; i <= maxVal; i++) {
            minDiv[i] = Integer.MAX_VALUE;
        }

        for (int d = 1; d <= maxVal; d++) {
            if (exists[d] == 0) continue;
            for (int m = d; m <= maxVal; m += d) {
                if (exists[m] == 1 && d < minDiv[m]) {
                    minDiv[m] = d;
                }
            }
        }

        long total = 0L;
        for (int v : arr) {
            total += minDiv[v];
        }
        return total;
    }
}

