public class Solution {
    public static long minCostToBuyApples(int N, int[] cost, int[] weight) {
        int m = cost.length;
        int maxW = 0;
        for (int w : weight) maxW = Math.max(maxW, w);
        int limit = N + maxW;
        long INF = Long.MAX_VALUE / 2;
        long[] dp = new long[limit + 1];
        java.util.Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i < limit; i++) {
            if (dp[i] == INF) continue;
            for (int j = 0; j < m; j++) {
                int next = Math.min(limit, i + weight[j]);
                if (dp[i] + cost[j] < dp[next]) dp[next] = dp[i] + cost[j];
            }
        }
        long ans = INF;
        for (int i = N; i <= limit; i++) ans = Math.min(ans, dp[i]);
        return ans == INF ? -1 : ans;
    }
}

