class Solution {
    public int countKthRoots(int l, int r, int k) {
        if (k == 1) return r - l + 1;
        int ans = 0;
        for (long x = 0; ; x++) {
            long y = 1;
            boolean over = false;
            for (int i = 0; i < k; i++) {
                y *= x;
                if (y > r) { over = true; break; }
            }
            if (over) break;
            if (y >= l && y <= r) ans++;
            if (x > 0 && y > r) break;
        }
        return ans;
    }
}

class Solution {
    static final long MOD1 = 1_000_000_007L, MOD2 = 998_244_353L;
    static final long BASE1 = 100003L, BASE2 = 100019L;

    // Binary search on length L (monotonic: if a unique-length-L subarray exists, extending
    // it by one element either left or right - always possible since L<n leaves room - keeps
    // it unique, so the property is monotonic in L). Existence check uses DOUBLE hashing
    // (two independent large-prime moduli/bases combined into one 64-bit key) rather than a
    // single rolling hash: this problem has two open LeetCode-Feedback reports of accepted
    // single-hash solutions failing on real inputs - one via a Thue-Morse sequence exploiting
    // unsigned-64-bit overflow (power-of-2 modulus), another via a plain 1e9+7-modulus birthday
    // collision on an ordinary-looking test case. A hash collision can only ever falsely MERGE
    // two different contents (never split identical content into different buckets, since equal
    // content always produces the identical hash deterministically), so any bucket with count==1
    // is guaranteed to be a true positive; double hashing over two large primes makes the
    // collision probability at n=1e5 scale astronomically small (~1e-9) instead of the ~few
    // expected collisions a single ~1e9 modulus would see at this scale.
    public int smallestUniqueSubarray(int[] nums) {
        int n = nums.length;
        long[] pow1 = new long[n + 1], pow2 = new long[n + 1];
        pow1[0] = pow2[0] = 1;
        for (int i = 1; i <= n; i++) { pow1[i] = pow1[i-1]*BASE1%MOD1; pow2[i] = pow2[i-1]*BASE2%MOD2; }
        long[] pre1 = new long[n + 1], pre2 = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pre1[i+1] = (pre1[i]*BASE1 + nums[i]) % MOD1;
            pre2[i+1] = (pre2[i]*BASE2 + nums[i]) % MOD2;
        }
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (hasUnique(mid, pre1, pre2, pow1, pow2, n)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

    private boolean hasUnique(int L, long[] pre1, long[] pre2, long[] pow1, long[] pow2, int n) {
        java.util.HashMap<Long, Integer> cnt = new java.util.HashMap<>();
        long[] keys = new long[n - L + 1];
        for (int i = 0; i + L <= n; i++) {
            long h1 = (pre1[i+L] - pre1[i]*pow1[L] % MOD1 + MOD1*MOD1) % MOD1;
            long h2 = (pre2[i+L] - pre2[i]*pow2[L] % MOD2 + MOD2*MOD2) % MOD2;
            long key = h1 * 1_000_000_009L + h2;
            keys[i] = key;
            cnt.merge(key, 1, Integer::sum);
        }
        for (long k : keys) if (cnt.get(k) == 1) return true;
        return false;
    }
}

import java.util.*;
public class P45 {
    static final long MOD = 1000000007L;
    static int countNonAdjacentSubsets(int[] parent, int[] nums, int k) {
        int n = parent.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i=0;i<n;i++) children.add(new ArrayList<>());
        for (int i=0;i<n;i++) if (parent[i]!=-1) children.get(parent[i]).add(i);
        int[] order = new int[n]; int idx=0;
        Deque<Integer> stk = new ArrayDeque<>(); stk.push(0);
        while(!stk.isEmpty()){
            int u=stk.pop(); order[idx++]=u;
            for(int v: children.get(u)) stk.push(v);
        }
        long[][] dpNot=new long[n][], dpSel=new long[n][];
        for (int i=n-1;i>=0;i--) {
            int u=order[i];
            long[] dn=new long[k], ds=new long[k];
            dn[0]=1; ds[nums[u]%k]=1;
            for (int v: children.get(u)) {
                long[] cn=dpNot[v], cs=dpSel[v];
                long[] comb=new long[k];
                for(int j=0;j<k;j++) comb[j]=(cn[j]+cs[j])%MOD;
                long[] nn=new long[k], ns=new long[k];
                for(int a=0;a<k;a++){
                    if(dn[a]!=0) for(int b=0;b<k;b++) if(comb[b]!=0){
                        int ix=(a+b)%k; nn[ix]=(nn[ix]+dn[a]*comb[b])%MOD;
                    }
                    if(ds[a]!=0) for(int b=0;b<k;b++) if(cn[b]!=0){
                        int ix=(a+b)%k; ns[ix]=(ns[ix]+ds[a]*cn[b])%MOD;
                    }
                }
                dn=nn; ds=ns;
            }
            dpNot[u]=dn; dpSel[u]=ds;
        }
        return (int)((dpNot[0][0]+dpSel[0][0]-1+MOD)%MOD);
    }
    public static void main(String[] a){
        System.out.println(countNonAdjacentSubsets(new int[]{-1,0,1},new int[]{1,2,3},3)+" expect 1");
        System.out.println(countNonAdjacentSubsets(new int[]{-1,0,0,0},new int[]{2,1,2,1},3)+" expect 2");
        System.out.println(countNonAdjacentSubsets(new int[]{-1,0,0,0},new int[]{3,3,3,3},3)+" expect 8");
        System.out.println(countNonAdjacentSubsets(new int[]{-1,0,1,2},new int[]{2,4,2,4},2)+" expect 7");
        System.out.println(countNonAdjacentSubsets(new int[]{-1,0,0},new int[]{6,3,3},3)+" expect 4");
    }
}

class Solution {
    public int maxIntersectionSum(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Map<Long, Long> dp = new HashMap<>();
        for (int r1 = 0; r1 < m; r1++) {
            for (int r2 = 0; r2 < m; r2++) {
                int lo = Math.max(0, r2), hi = Math.min(r1, m - 1);
                long contrib = 0;
                for (int r = lo; r <= hi; r++) contrib += grid[r][0];
                long key = (long) r1 * 1000 + r2;
                dp.merge(key, contrib, Math::max);
            }
        }
        for (int c = 1; c < n; c++) {
            Map<Long, Long> ndp = new HashMap<>();
            for (Map.Entry<Long, Long> e : dp.entrySet()) {
                int pr1 = (int) (e.getKey() / 1000), pr2 = (int) (e.getKey() % 1000);
                long val = e.getValue();
                for (int r1 = pr1; r1 < m; r1++) {
                    for (int r2 = 0; r2 <= pr2; r2++) {
                        int lo = Math.max(pr1, r2), hi = Math.min(r1, pr2);
                        long contrib = 0;
                        for (int r = lo; r <= hi; r++) contrib += grid[r][c];
                        long nkey = (long) r1 * 1000 + r2;
                        long nv = val + contrib;
                        ndp.merge(nkey, nv, Math::max);
                    }
                }
            }
            dp = ndp;
        }
        long finalKey = (long) (m - 1) * 1000 + 0;
        return (int) (long) dp.getOrDefault(finalKey, 0L);
    }
}

class Solution {
    public int countLocalMaximums(int[][] matrix) {
        int n = matrix.length, m = matrix[0].length;
        int count = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int x = matrix[r][c];
                if (x == 0) continue;
                boolean isMax = true;
                for (int dr = -x; dr <= x && isMax; dr++) {
                    for (int dc = -x; dc <= x; dc++) {
                        if (Math.abs(dr) == x && Math.abs(dc) == x) continue;
                        int rr = r+dr, cc = c+dc;
                        if (rr < 0 || rr >= n || cc < 0 || cc >= m) continue;
                        if (matrix[rr][cc] > x) { isMax = false; break; }
                    }
                }
                if (isMax) count++;
            }
        }
        return count;
    }
}

class Solution {
    public int minSwaps(int[] nums) {
        int n = nums.length;
        int zeros = 0;
        for (int x : nums) if (x == 0) zeros++;
        int targetNonZeroLen = n - zeros;
        // each zero sitting inside the target non-zero prefix is misplaced, and each swap
        // fixes exactly one such zero (swapping it with a misplaced non-zero in the tail)
        int misplaced = 0;
        for (int i = 0; i < targetNonZeroLen; i++) {
            if (nums[i] == 0) misplaced++;
        }
        return misplaced;
    }
}

import java.util.*;
public class P47 {
    static List<Long> numberOfPairs(int[] nums1, int[] nums2, int[][] queries) {
        long[] b = new long[nums2.length];
        for (int i=0;i<nums2.length;i++) b[i]=nums2[i];
        Map<Long,Long> freqA=new HashMap<>(), freqB=new HashMap<>();
        for (int v: nums1) freqA.merge((long)v,1L,Long::sum);
        for (long v: b) freqB.merge(v,1L,Long::sum);
        List<Long> answer=new ArrayList<>();
        for (int[] q: queries) {
            if (q[0]==1) {
                int l=q[1],r=q[2]; long x=q[3];
                for (int i=l;i<=r;i++) {
                    long old=b[i], nw=old+x;
                    b[i]=nw;
                    long c=freqB.get(old)-1;
                    if (c==0) freqB.remove(old); else freqB.put(old,c);
                    freqB.merge(nw,1L,Long::sum);
                }
            } else {
                long tot=q[1], total=0;
                for (Map.Entry<Long,Long> e: freqA.entrySet()) {
                    Long cb=freqB.get(tot-e.getKey());
                    if (cb!=null) total += e.getValue()*cb;
                }
                answer.add(total);
            }
        }
        return answer;
    }
    public static void main(String[] a){
        System.out.println(numberOfPairs(new int[]{1,2},new int[]{3,4},new int[][]{{2,5},{1,0,0,2},{2,5}})+" expect [2, 1]");
        System.out.println(numberOfPairs(new int[]{1,1},new int[]{2,2,3},new int[][]{{2,4},{1,0,1,1},{2,4}})+" expect [2, 6]");
        System.out.println(numberOfPairs(new int[]{2,5,8,4},new int[]{1,3,8},new int[][]{{2,9},{1,1,2,1},{2,10}})+" expect [1, 0]");
    }
}

class Solution {
    public static int minOperations(int[] nums, int k) {
        int n = nums.length;
        int[] residues = new int[n];
        for (int i = 0; i < n; i++) residues[i] = ((nums[i] % k) + k) % k;
        int best = Integer.MAX_VALUE;
        for (int x = 0; x < k; x++) {
            for (int y = 0; y < k; y++) {
                if (x == y) continue;
                int cost = 0;
                for (int i = 0; i < n; i++) {
                    int target = (i % 2 == 0) ? x : y;
                    int diff = Math.abs(residues[i] - target);
                    cost += Math.min(diff, k - diff);
                }
                best = Math.min(best, cost);
            }
        }
        return best;
    }
}

class Solution {
    // Two-pointer, single pass: 'l' is the write index, track a run-length counter
    // that resets whenever the value changes; only keep an element while its running
    // count is still within k.
    public int[] limitOccurrences(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return nums;
        int[] res = new int[n];
        int l = 0, cnt = 0;
        for (int r = 0; r < n; r++) {
            if (r == 0 || nums[r] != nums[r - 1]) cnt = 1; else cnt++;
            if (cnt <= k) { res[l] = nums[r]; l++; }
        }
        return java.util.Arrays.copyOf(res, l);
    }
}

class Solution {
    // The two operations (rotate-left-by-1, reverse-whole-array) only generate at most 2n
    // distinct reachable arrangements: rotate_left^shift(source) and rotate_left^shift(reverse(source))
    // for shift in 0..n-1. Model this as an explicit 2n-node graph - node (flip, shift) - and BFS it
    // directly instead of hand-deriving a closed form (a naive "just count rotations to align zero"
    // formula misses cheaper double-reverse-sandwich paths, e.g. [1,2,3,4,0] sorts in 3 ops via
    // rotate-then-reverse, not the 4 a naive zero-position formula would give - LeetCode-Feedback has
    // an open issue about exactly this kind of undercounted edge case).
    // Edges: rotate: (f,s) -> (f, (s+1)%n), cost 1.
    // reverse: (f,s) -> (1-f, (n-s)%n), cost 1  [reverse(rotate_left^s(base)) = rotate_left^{(n-s)%n}(reverse(base))].
    public int minOperations(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;

        int p0 = -1;
        for (int i = 0; i < n; i++) if (nums[i] == 0) { p0 = i; break; }
        boolean sourceIsRot = true;
        for (int i = 0; i < n; i++) if (nums[(p0 + i) % n] != i) { sourceIsRot = false; break; }

        int[] rev = new int[n];
        for (int i = 0; i < n; i++) rev[i] = nums[n - 1 - i];
        int p0r = -1;
        for (int i = 0; i < n; i++) if (rev[i] == 0) { p0r = i; break; }
        boolean revIsRot = true;
        for (int i = 0; i < n; i++) if (rev[(p0r + i) % n] != i) { revIsRot = false; break; }

        if (!sourceIsRot && !revIsRot) return -1;

        int[][] dist = new int[2][n];
        for (int[] row : dist) java.util.Arrays.fill(row, -1);
        dist[0][0] = 0;
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int f = cur[0], s = cur[1], d = dist[f][s];
            int ns = (s + 1) % n;
            if (dist[f][ns] == -1) { dist[f][ns] = d + 1; q.add(new int[]{f, ns}); }
            int nf = 1 - f, ns2 = (n - s) % n;
            if (dist[nf][ns2] == -1) { dist[nf][ns2] = d + 1; q.add(new int[]{nf, ns2}); }
        }

        int best = Integer.MAX_VALUE;
        if (sourceIsRot && dist[0][p0] != -1) best = Math.min(best, dist[0][p0]);
        if (revIsRot && dist[1][p0r] != -1) best = Math.min(best, dist[1][p0r]);
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

class Solution {
    public int passwordStrength(String password) {
        Set<Character> seen = new HashSet<>();
        for (char c : password.toCharArray()) seen.add(c);
        int ans = 0;
        for (char c : seen) {
            if (Character.isLowerCase(c)) ans += 1;
            else if (Character.isUpperCase(c)) ans += 2;
            else if (Character.isDigit(c)) ans += 3;
            else if ("!@#$".indexOf(c) >= 0) ans += 5;
        }
        return ans;
    }
}

class Solution {
    public static int maximumSaleItems(int[][] items, int budget) {
        int[] f = new int[budget + 1];
        int mn = Integer.MAX_VALUE;
        for (int[] item : items) {
            int factor = item[0], price = item[1];
            mn = Math.min(mn, price);
            int cnt = 0;
            for (int[] jItem : items) if (jItem[0] % factor == 0) cnt++;
            for (int j = budget; j >= price; j--) f[j] = Math.max(f[j], f[j-price] + cnt);
        }
        int ans = 0;
        for (int i = 0; i <= budget; i++) ans = Math.max(ans, f[i] + (budget - i) / mn);
        return ans;
    }
}

public class Solution {
    public static String patternPrinting1(int N) {
        StringBuilder output = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j < i; j++) {
                output.append("*");
            }
            if (i < N) output.append("\n");
        }
        return output.toString();
    }
}

