class Solution {
    public static int digitFrequencyScore(Object num) {
        String str = String.valueOf(num);
        int[] freq = new int[10];
        for (int i = 0; i < str.length(); i++) {
            int d = str.charAt(i) - '0';
            if (d >= 0 && d <= 9) {
                freq[d]++;
            }
        }
        int score = 0;
        for (int d = 0; d < 10; d++) {
            score += d * freq[d];
        }
        return score;
    }
}

import java.util.*;
class Solution {
    public static long maximumSaleItems(int[][] items, long budget) {
        int maxF = 0;
        for (int[] it : items) maxF = Math.max(maxF, it[0]);
        int[] freq = new int[maxF + 1];
        for (int[] it : items) freq[it[0]]++;
        long[] S = new long[maxF + 1];
        for (int f = 1; f <= maxF; f++) {
            long total = 0;
            for (int m = f; m <= maxF; m += f) total += freq[m];
            S[f] = total;
        }
        long minPrice = Long.MAX_VALUE;
        for (int[] it : items) minPrice = Math.min(minPrice, it[1]);
        List<long[]> attractive = new ArrayList<>();
        for (int[] it : items) {
            long f = it[0], p = it[1];
            long D = S[(int) f] - 1;
            if (p <= 2 * minPrice) attractive.add(new long[]{p, D});
        }
        attractive.sort((a, b) -> Long.compare(a[0], b[0]));
        long totalItems = 0, remaining = budget;
        for (long[] pd : attractive) {
            long price = pd[0], D = pd[1];
            if (D <= 0 || remaining < price) continue;
            long buy = Math.min(D, remaining / price);
            totalItems += buy * 2;
            remaining -= buy * price;
        }
        totalItems += remaining / minPrice;
        return totalItems;
    }
}

class Solution {
    public static boolean isPalindrome(int num) {
        if (num < 0) return false;
        int original = num;
        int reversed = 0;
        while (num > 0) {
            reversed = reversed * 10 + (num % 10);
            num = num / 10;
        }
        return reversed == original;
    }
}

class Solution {
    public List<Integer> maxMexArray(int[] a) {
        int n = a.length;
        List<Integer> result = new ArrayList<>();
        int i = 0;
        while (i < n) {
            boolean[] present = new boolean[n + 2];
            for (int j = i; j < n; j++) if (a[j] <= n + 1) present[a[j]] = true;
            int mex = 0;
            while (mex <= n && present[mex]) mex++;
            Set<Integer> seen = new HashSet<>();
            int found = -1;
            for (int j = i; j < n; j++) {
                int v = a[j];
                if (v < mex) seen.add(v);
                if (seen.size() == mex) { found = j; break; }
            }
            result.add(mex);
            i = found + 1;
        }
        return result;
    }
}

class Solution {
    public static int countDigits(int num) {
        int n = Math.abs(num);
        int count = 0;
        String s = Integer.toString(n);
        for (int i = 0; i < s.length(); i++) {
            int digit = s.charAt(i) - '0';
            if (digit != 0 && n % digit == 0) {
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

public class Solution {
    public static String solve(String input) {
        String[] parts = input.trim().split("\\s+");
        int idx = 0;
        int t = Integer.parseInt(parts[idx++]);
        List<String> out = new ArrayList<>();
        for (int tc = 0; tc < t; tc++) {
            int n = Integer.parseInt(parts[idx++]);
            for (int i = 1; i <= n; i++) {
                StringBuilder line = new StringBuilder();
                for (int j = 0; j < i; j++) {
                    line.append(i);
                    if (j < i - 1) line.append(' ');
                }
                out.add(line.toString());
            }
            if (tc != t - 1) out.add("");
        }
        return String.join("\n", out);
    }
}

