class Solution {
    public static int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

class Solution {
    public static boolean isArmstrong(int num) {
        if (num < 0) return false;
        int temp = num;
        int digitCount = 0;
        do {
            digitCount++;
            temp = temp / 10;
        } while (temp > 0);
        temp = num;
        long sum = 0;
        while (temp > 0) {
            int digit = temp % 10;
            sum += (long) Math.pow(digit, digitCount);
            temp = temp / 10;
        }
        if (num == 0) sum = (long) Math.pow(0, digitCount);
        return sum == num;
    }
}

