import java.util.ArrayList;
import java.util.List;

class Solution {
    public static int[] unionSortedArrays(int[] arr1, int[] arr2) {
        List<Integer> result = new ArrayList<>();
        int i = 0, j = 0;
        while (i < arr1.length && j < arr2.length) {
            if (arr1[i] < arr2[j]) {
                if (result.isEmpty() || result.get(result.size() - 1) != arr1[i]) {
                    result.add(arr1[i]);
                }
                i++;
            } else if (arr1[i] > arr2[j]) {
                if (result.isEmpty() || result.get(result.size() - 1) != arr2[j]) {
                    result.add(arr2[j]);
                }
                j++;
            } else {
                if (result.isEmpty() || result.get(result.size() - 1) != arr1[i]) {
                    result.add(arr1[i]);
                }
                i++;
                j++;
            }
        }
        while (i < arr1.length) {
            if (result.isEmpty() || result.get(result.size() - 1) != arr1[i]) {
                result.add(arr1[i]);
            }
            i++;
        }
        while (j < arr2.length) {
            if (result.isEmpty() || result.get(result.size() - 1) != arr2[j]) {
                result.add(arr2[j]);
            }
            j++;
        }
        int[] resArray = new int[result.size()];
        for (int k = 0; k < result.size(); k++) {
            resArray[k] = result.get(k);
        }
        return resArray;
    }
}

class Solution {
    public static Integer secondLargest(int[] arr) {
        int max = Integer.MIN_VALUE;
        int second = Integer.MIN_VALUE;
        for (int i = 0; i < arr.length; i++) {
            int val = arr[i];
            if (val > max) {
                second = max;
                max = val;
            } else if (val > second && val < max) {
                second = val;
            }
        }
        return second == Integer.MIN_VALUE ? null : second;
    }
}

class Solution {
    public static int maxConsecutiveOnes(int[] nums) {
        int maxStreak = 0;
        int currentStreak = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 1) {
                currentStreak++;
            } else {
                if (currentStreak > maxStreak) {
                    maxStreak = currentStreak;
                }
                currentStreak = 0;
            }
        }
        if (currentStreak > maxStreak) {
            maxStreak = currentStreak;
        }
        return maxStreak;
    }
}

