class Solution {
    public static boolean isValidBST(TreeNode root) {
        return validate(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private static boolean validate(TreeNode node, long lowerBound, long upperBound) {
        if (node == null) {
            return true;
        }
        if (node.val <= lowerBound || node.val >= upperBound) {
            return false;
        }
        return validate(node.left, lowerBound, node.val) && validate(node.right, node.val, upperBound);
    }
}

import java.util.*;

class Solution {
    public static int kthLargestElement(int[] nums, int k) {
        MinHeap heap = new MinHeap(k + 1);
        for (int num : nums) {
            heap.push(num);
            if (heap.size() > k) {
                heap.pop();
            }
        }
        return heap.peek();
    }

    private static class MinHeap {
        private final int[] data;
        private int size;

        MinHeap(int capacity) {
            this.data = new int[capacity];
            this.size = 0;
        }

        private int parent(int i) {
            return (i - 1) >> 1;
        }

        private int left(int i) {
            return i * 2 + 1;
        }

        private int right(int i) {
            return i * 2 + 2;
        }

        private void swap(int i, int j) {
            int tmp = data[i];
            data[i] = data[j];
            data[j] = tmp;
        }

        private void heapifyUp(int i) {
            while (i > 0 && data[parent(i)] > data[i]) {
                swap(i, parent(i));
                i = parent(i);
            }
        }

        private void heapifyDown(int i) {
            while (true) {
                int smallest = i;
                int l = left(i);
                int r = right(i);
                if (l < size && data[l] < data[smallest]) smallest = l;
                if (r < size && data[r] < data[smallest]) smallest = r;
                if (smallest == i) break;
                swap(i, smallest);
                i = smallest;
            }
        }

        void push(int val) {
            data[size++] = val;
            heapifyUp(size - 1);
        }

        int pop() {
            if (size == 1) {
                return data[--size];
            }
            int top = data[0];
            data[0] = data[--size];
            heapifyDown(0);
            return top;
        }

        int peek() {
            return data[0];
        }

        int size() {
            return size;
        }
    }
}

import java.util.*;

class Solution {
    public static int countComponents(int n, int[][] edges) {
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (parent[x] != x) parent[x] = applyAsInt(parent[x]);
                return parent[x];
            }
        };

        java.util.function.BiFunction<Integer, Integer, Boolean> union = (a, b) -> {
            int rootA = find.applyAsInt(a);
            int rootB = find.applyAsInt(b);
            if (rootA == rootB) return false;
            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
            return true;
        };

        int components = n;
        for (int[] edge : edges) {
            if (union.apply(edge[0], edge[1])) components--;
        }
        return components;
    }
}

import java.util.*;

class Solution {
    public static List<Integer> rangeSumQuery(int[] nums, List<List<Object>> queries) {
        int n = nums.length;
        long[] tree = new long[4 * n];
        build(tree, nums, 1, 0, n - 1);
        List<Integer> answers = new ArrayList<>();
        for (List<Object> q : queries) {
            String type = (String) q.get(0);
            if (type.equals("update")) {
                int idx = ((Number) q.get(1)).intValue();
                int val = ((Number) q.get(2)).intValue();
                update(tree, 1, 0, n - 1, idx, val);
            } else { // "sum"
                int left = ((Number) q.get(1)).intValue();
                int right = ((Number) q.get(2)).intValue();
                answers.add((int) query(tree, 1, 0, n - 1, left, right));
            }
        }
        return answers;
    }

    private static void build(long[] tree, int[] nums, int node, int l, int r) {
        if (l == r) {
            tree[node] = nums[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(tree, nums, node * 2, l, mid);
        build(tree, nums, node * 2 + 1, mid + 1, r);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    private static void update(long[] tree, int node, int l, int r, int idx, int val) {
        if (l == r) {
            tree[node] = val;
            return;
        }
        int mid = (l + r) >> 1;
        if (idx <= mid) {
            update(tree, node * 2, l, mid, idx, val);
        } else {
            update(tree, node * 2 + 1, mid + 1, r, idx, val);
        }
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    private static long query(long[] tree, int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            return tree[node];
        }
        if (r < ql || l > qr) {
            return 0;
        }
        int mid = (l + r) >> 1;
        return query(tree, node * 2, l, mid, ql, qr) +
               query(tree, node * 2 + 1, mid + 1, r, ql, qr);
    }
}

