class Solution {
    public static int bestTimeToBuySellCooldown(int[] prices) {
        if (prices == null || prices.length == 0) return 0;
        int cash = 0;
        int hold = -prices[0];
        int prevCash = 0;
        for (int i = 1; i < prices.length; i++) {
            int newCash = Math.max(cash, hold + prices[i]);
            int newHold = Math.max(hold, prevCash - prices[i]);
            prevCash = cash;
            cash = newCash;
            hold = newHold;
        }
        return cash;
    }
}

