class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        // valToMinPrefix: for each value seen, the smallest prefix-sum-before-it (best possible
        // subarray start using that value as the first element)
        Map<Integer, Long> valToMinPrefix = new HashMap<>();
        long prefix = 0;
        Long best = null;
        for (int x : nums) {
            if (valToMinPrefix.containsKey(x - k)) {
                long cand = prefix + x - valToMinPrefix.get(x - k);
                best = (best == null) ? cand : Math.max(best, cand);
            }
            if (valToMinPrefix.containsKey(x + k)) {
                long cand = prefix + x - valToMinPrefix.get(x + k);
                best = (best == null) ? cand : Math.max(best, cand);
            }
            if (!valToMinPrefix.containsKey(x) || valToMinPrefix.get(x) > prefix) {
                valToMinPrefix.put(x, prefix);
            }
            prefix += x;
        }
        return best != null ? best : 0;
    }
}

class Solution {
    private long[] countLeSamelen(String bound, int limit) {
        int n = bound.length();
        long total = 0;
        boolean exactAchievable = true;
        for (int i = 0; i < n; i++) {
            int d = bound.charAt(i) - '0';
            int lo = (i == 0) ? 1 : 0;
            int hi = Math.min(d - 1, limit);
            if (hi >= lo) {
                int ways = hi - lo + 1;
                int remaining = n - i - 1;
                total += (long) ways * (long) Math.pow(limit + 1, remaining);
            }
            if (d > limit) { exactAchievable = false; break; }
        }
        return new long[]{total, exactAchievable ? 1 : 0};
    }

    private long countUpto(long x, int limit, String s) {
        if (x <= 0) return 0;
        String sx = Long.toString(x);
        int n = sx.length(), ls = s.length();
        for (char c : s.toCharArray()) if (c - '0' > limit) return 0;
        if (n < ls) return 0;
        long total = 0;
        for (int L = ls; L < n; L++) {
            if (L == ls) {
                if (s.charAt(0) != '0') total += 1;
            } else {
                int free = L - ls;
                total += (long) limit * (long) Math.pow(limit + 1, free - 1);
            }
        }
        int preLen = n - ls;
        if (preLen == 0) {
            if (s.charAt(0) != '0' && s.compareTo(sx) <= 0) total += 1;
        } else {
            String prefixOfX = sx.substring(0, preLen);
            String suffixOfX = sx.substring(preLen);
            long[] r = countLeSamelen(prefixOfX, limit);
            long cnt = r[0];
            if (r[1] == 1 && suffixOfX.compareTo(s) >= 0) cnt += 1;
            total += cnt;
        }
        return total;
    }

    public long numberOfPowerfulInt(long start, long finish, int limit, String s) {
        return countUpto(finish, limit, s) - countUpto(start - 1, limit, s);
    }
}

