class Solution {
    public static int[] beautifulIndices(String s, String a, String b, int k) {
        List<Integer> beautiful = new ArrayList<>();
        for (int i = 0; i <= s.length() - a.length(); i++) {
            if (s.substring(i, i + a.length()).equals(a)) {
                for (int j = 0; j <= s.length() - b.length(); j++) {
                    if (s.substring(j, j + b.length()).equals(b) && Math.abs(i - j) <= k) {
                        beautiful.add(i);
                        break;
                    }
                }
            }
        }
        Set<Integer> set = new HashSet<>(beautiful);
        List<Integer> resultList = new ArrayList<>(set);
        Collections.sort(resultList);
        int[] result = new int[resultList.size()];
        for (int i = 0; i < resultList.size(); i++) {
            result[i] = resultList.get(i);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int maximumSetSize(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int half = n / 2;
        Set<Integer> set1 = new HashSet<>(), set2 = new HashSet<>();
        for (int x : nums1) set1.add(x);
        for (int x : nums2) set2.add(x);
        Set<Integer> common = new HashSet<>(set1);
        common.retainAll(set2);
        int only1 = set1.size() - common.size();
        int only2 = set2.size() - common.size();
        // prioritize values unique to each array first (common values can be covered by either side)
        int take1 = Math.min(only1, half);
        int remain1 = half - take1;
        int take2 = Math.min(only2, half);
        int remain2 = half - take2;
        int commonUsed = Math.min(common.size(), remain1 + remain2);
        return take1 + take2 + commonUsed;
    }
}

class Solution {
    public static long minCost(int[] nums, int k, int dist) {
        int n = nums.length;
        final long INF = Long.MAX_VALUE/2;
        long answer = INF;
        for (int i1 = 1; i1 < n; i1++) {
            int maxLast = Math.min(n-1, i1+dist);
            int minLast = i1 + (k-2) - 1;
            if (minLast > maxLast) continue;
            for (int iLast = minLast; iLast <= maxLast; iLast++) {
                int interiorLen = iLast - i1 - 1;
                int need = Math.max(k-3, 0);
                if (interiorLen < need) continue;
                int[] interior = java.util.Arrays.copyOfRange(nums, i1+1, iLast);
                java.util.Arrays.sort(interior);
                long sumSmallest = 0;
                for (int x = 0; x < need; x++) sumSmallest += interior[x];
                long total = nums[0]+nums[i1]+nums[iLast]+sumSmallest;
                if (total < answer) answer = total;
            }
        }
        return answer==INF ? -1 : answer;
    }
}

class Solution {
    public long minDamage(int power, int[] damage, int[] health) {
        int n = damage.length;
        long[][] a = new long[n][2]; // [hits needed, damage per second]
        for (int i = 0; i < n; i++) {
            a[i][0] = (health[i] - 1) / power + 1;
            a[i][1] = damage[i];
        }
        // Exchange-argument greedy: kill enemies in increasing order of hits[i]/damage[i]
        // (compare via cross-multiplication to avoid floating point).
        Arrays.sort(a, (p, q) -> Long.compare(p[0]*q[1], q[0]*p[1]));
        long ans = 0;
        long s = 0; // cumulative hits so far - kept as long throughout (a known accepted
                    // solution used a plain int here and overflowed on a large hack test,
                    // per LeetCode-Feedback #23837)
        for (long[] p : a) {
            s += p[0];
            ans += s * p[1];
        }
        return ans;
    }
}

import java.util.Arrays;

class Solution {
    public static boolean canSortArray(int[] nums) {
        int[] sortedNums = nums.clone();
        Arrays.sort(sortedNums);
        int[] setBitsCount = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            setBitsCount[i] = countSetBits(nums[i]);
        }
        int[] sortedSetBitsCount = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            sortedSetBitsCount[i] = countSetBits(sortedNums[i]);
        }
        for (int i = 0; i < nums.length; i++) {
            if (setBitsCount[i] != sortedSetBitsCount[i]) {
                return false;
            }
        }
        return true;
    }

    private static int countSetBits(int n) {
        return Integer.bitCount(n);
    }
}
